    private val jetBrainsMonoNormal: Typeface by lazy(LazyThreadSafetyMode.NONE) { Typeface.create(jetBrainsMonoTypeface, Typeface.NORMAL) }

    private fun loadFrontendTypeface(fontId: Int, fallback: Typeface): Typeface =
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            runCatching { resources.getFont(fontId) }.getOrDefault(fallback)
        } else fallback

    /** Reuse StrictFocus's display/body/telemetry type system on the production screens. */
    private fun applyFrontendTypography(root: ViewGroup) {
        val count = root.childCount
        for (index in 0 until count) {
            val child = root.getChildAt(index)
            if (child is TextView) {
                val original = child.typeface ?: Typeface.DEFAULT
                val isBold = original.isBold
                val isMono = child.tag == "telemetry_type"
                val target = when {
                    isMono -> if (isBold) jetBrainsMonoBold else jetBrainsMonoNormal
                    isBold || child.textSize / resources.displayMetrics.scaledDensity >= 16f -> if (isBold) spaceGroteskBold else spaceGroteskNormal
                    else -> manropeNormal
                }
                if (child.typeface !== target) {
                    child.typeface = target
                }
                if (child.includeFontPadding) {
                    child.includeFontPadding = false
                }
            } else if (child is ViewGroup) {
                applyFrontendTypography(child)
            }
        }
    }

