    private fun isReducedMotionEnabled(): Boolean {
        return try {
            Settings.Global.getFloat(contentResolver, Settings.Global.ANIMATOR_DURATION_SCALE, 1f) == 0f
        } catch (_: Exception) {
            false
        }
    }

    private fun buildTruthfulStrictBotMessage(): String {
        return try {
            val summary = db.getTruthfulDailySummary(db.nowDate(), isDevMode)
            val strictBotSummary = summary.optString("strictbot_summary", "")
            val countdown = db.getCurrentCountdownState(db.nowDate(), setOf("HOURLY"))
            if (countdown.hasActiveWindow) {
                val mm = countdown.secondsRemaining / 60
                val ss = countdown.secondsRemaining % 60
                "${countdown.title ?: "Active submission window"} is open (${String.format(Locale.US, "%02d:%02d", mm, ss)} remaining). $strictBotSummary"
            } else if (strictBotSummary.isNotBlank()) {
                strictBotSummary
            } else {
                val st = db.getDayState(db.nowDate(), isDevMode)
                buildStrictBotContextLine(
                    st.optInt("score", 0),
                    st.optInt("wakeup_camera") == 1,
                    st.optInt("wakeup_bt") == 1,
                    st.optInt("wakeup_track") == 1,
                    st.optString("bath_status").startsWith("BATH COMPLETE"),
                    st.optString("gym_status").startsWith("GYM COMPLETE"),
                    st.optInt("hourly_completed", 0)
                )
            }
        } catch (_: Exception) {
            "StrictBot ready. All messages are generated from your recorded activity and proof state."
        }
    }

    private fun speakStrictBot(customText: String? = null) {
        val message = customText ?: buildTruthfulStrictBotMessage()
        if (::strictBotChat.isInitialized) strictBotChat.speakUserRequested(message)
    }

    private fun dispatchStrictBotEvent(eventType: String, customMessage: String? = null) {
        val animState = DisciplineScoringRules.resolveStrictBotAnimationForEvent(eventType)
        strictBotState = animState
        selectedKineticsMode = animState
        currentMascotView?.let { animateMascotKinetics(it, animState) }
        val isOnlinePaired = db.getConfigValue("pairing_status", "OFFLINE") == "ONLINE"
        currentBotStatusLabel?.text = "StrictBot • $animState • ${if (isOnlinePaired) "Synced" else "Local mode"}"
        if (!customMessage.isNullOrBlank()) {
            triggerBotMessage(customMessage, animState)
        }
        if (::strictBotChat.isInitialized) strictBotChat.onApplicationStateChanged("$eventType:${db.getConfigValue("last_sync_time", "")}:${db.getScore(db.nowDate(), false)}")
    }

    private fun animateMascotKinetics(img: View, mode: String) {
        val normMode = when (mode.uppercase(Locale.US)) {
            "HOVER" -> "IDLE"
            in DisciplineScoringRules.STRICTBOT_SUPPORTED_ANIMATIONS -> mode.uppercase(Locale.US)
            else -> DisciplineScoringRules.resolveStrictBotAnimationForEvent(mode)
        }
        strictBotState = normMode
        img.animate().cancel()
        img.rotation = 0f
        img.translationX = 0f
        img.translationY = 0f
        img.scaleX = 1f
        img.scaleY = 1f
        if (isReducedMotionEnabled()) return
        when (normMode) {
            "FLY" -> {
                img.animate().translationY(-dp(16).toFloat()).scaleX(1.1f).scaleY(1.1f)
                    .setDuration(350L).setInterpolator(DecelerateInterpolator())
                    .withEndAction {
                        img.animate().translationY(0f).scaleX(1f).scaleY(1f).setDuration(350L).start()
                    }.start()
            }
            "WALK" -> {
                img.animate().rotation(9f).translationX(dp(7).toFloat()).setDuration(220L)
                    .withEndAction {
                        img.animate().rotation(-9f).translationX(-dp(7).toFloat()).setDuration(220L)
                            .withEndAction {
                                img.animate().rotation(0f).translationX(0f).setDuration(180L).start()
                            }.start()
                    }.start()
            }
            "SPEAK" -> {
                img.animate().scaleX(1.08f).scaleY(1.08f).translationY(-dp(4).toFloat()).setDuration(200L)
                    .withEndAction {
                        img.animate().scaleX(1f).scaleY(1f).translationY(0f).setDuration(200L).start()
                    }.start()
            }
            "REVIEW" -> {
                img.animate().rotation(6f).scaleX(1.05f).scaleY(1.05f).setDuration(260L)
                    .withEndAction {
                        img.animate().rotation(-6f).setDuration(260L)
                            .withEndAction {
                                img.animate().rotation(0f).scaleX(1f).scaleY(1f).setDuration(200L).start()
                            }.start()
                    }.start()
            }
            "SUCCESS" -> {
                img.animate().translationY(-dp(12).toFloat()).scaleX(1.12f).scaleY(1.12f)
                    .setDuration(260L).setInterpolator(OvershootInterpolator(1.8f))
                    .withEndAction {
                        img.animate().translationY(0f).scaleX(1f).scaleY(1f).setDuration(240L).start()
                    }.start()
            }
            "WARNING" -> {
                img.animate().translationX(dp(6).toFloat()).setDuration(100L)
                    .withEndAction {
                        img.animate().translationX(-dp(6).toFloat()).setDuration(100L)
                            .withEndAction {
                                img.animate().translationX(0f).setDuration(100L).start()
                            }.start()
                    }.start()
            }
            else -> { // IDLE
                img.animate().translationY(-dp(8).toFloat()).scaleX(1.03f).scaleY(1.03f)
                    .setDuration(480L).withEndAction {
                        img.animate().translationY(0f).scaleX(1f).scaleY(1f).setDuration(480L).start()
                    }.start()
            }
        }
    }

