    private fun cleanUserFacingText(raw: String?): String {

        if (raw.isNullOrBlank()) return ""

        return raw.replace("POSSIBLE_DUPLICATE", "Potential Duplicate")

                  .replace("HIGH_SIMILARITY", "High Visual Similarity")

                  .replace("EXACT_DUPLICATE", "Exact Duplicate")

                  .replace("DAILY_RESET", "Daily Points Baseline")

                  .replace("INITIAL_RESET", "Initial Points Reset")

                  .replace("PROOF_APPROVED", "Proof Approved")

                  .replace("PROOF_REJECTED", "Proof Rejected")

                  .replace("HOURLY_WASTED", "Hourly Interval Missed")

                  .replace("RESTRICTED_APP_PENALTY", "Restricted App Penalty")

                  .replace("BROWSER_EXTENSION_PENALTY", "Browser Extension Penalty")

    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        db = StrictRecordsLocalDb.getInstance(this)
        try {
            val schedFilter = IntentFilter(ACTION_SCHEDULE_RESTRICTION_TRIGGER).apply {
                addAction(MorningWakeUpManager.ACTION_START_MORNING_FLOW)
            }
            scheduleRestrictionReceiver = object : BroadcastReceiver() {
                override fun onReceive(context: Context?, intent: Intent?) {
                    uiHandler.post {
                        if (screenResumed && !isFinishing && !isDestroyed) {
                            if (intent?.action == MorningWakeUpManager.ACTION_START_MORNING_FLOW) {
                                checkAutoPromptOnLaunch()
                                return@post
                            }
                            val status = ScheduleDeadlineManager.evaluateScheduleStatus(this@MainActivity, db)
                            if (status == ScheduleDeadlineRules.ScheduleDeadlineState.OVERDUE_UNCONFIRMED ||
                                status == ScheduleDeadlineRules.ScheduleDeadlineState.COMPLETION_REQUIRED) {
                                isSchedulePendingRestricted = true
                                currentScheduleDeadlineState = ScheduleDeadlineRules.ScheduleDeadlineState.COMPLETION_REQUIRED
                                refreshUi()
                            }
                        }
                    }
                }
            }
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                registerReceiver(scheduleRestrictionReceiver, schedFilter, Context.RECEIVER_NOT_EXPORTED)
            } else {
                registerReceiver(scheduleRestrictionReceiver, schedFilter)
            }
        } catch (_: Exception) {}
        scoreArcView = ScoreArcView(this)
        scoreBigLabel = TextView(this)
        scoreStateLabel = TextView(this)
        clockHourLabel = TextView(this)
        clockMinLabel = TextView(this)
        clockAmPmLabel = TextView(this)
        uiHandler.postDelayed({
            StrictEnforcementService.start(applicationContext)
            val app = applicationContext
            Thread { WakeUpAlarmReceiver.scheduleDefaultDailyRoutine(app) }.start()
        }, 2000L)
        strictBotChat = StrictBotChatController(
            activity = this,
            db = db,
            onNavigate = { target -> navigateStrictBotAction(target) },
            onConfirmedOperation = { triggerServerSync() },
            onMotion = { motion ->
                strictBotState = motion
                currentMascotView?.let { animateMascotKinetics(it, motion) }
                currentBotStatusLabel?.text = "StrictBot • $motion"
            },
            onTypography = { view -> applyFrontendTypography(view) }
        )
        buildShell()
        handleIncomingIntent(intent)
        refreshUi()
        // The permission gate is never bypassed by developer mode or exported
        // activity extras.
        if (!DisciplinePermissionManager.isPermissionGatePassed(this)) {
            DisciplinePermissionManager.showMandatoryOnboardingWizard(this) {
                refreshUi()
            }
        }
        splashOverlay.visibility = View.GONE

        // In-App APK Updater Registration (Requirements 1, 4, 6)
        updateListener = object : AppUpdateManager.UpdateListener {
            override fun onUpdateStateChanged(
                state: AppUpdateManager.UpdateState,
                release: AppUpdateManager.ReleaseInfo?,
                progress: Int,
                errorMessage: String?
            ) {
                runOnUiThread {
                    headerUpdateBtn?.let { btn ->
                        when (state) {
                            AppUpdateManager.UpdateState.UPDATE_AVAILABLE -> {
                                btn.text = "↻ Update"
                                btn.visibility = View.VISIBLE
                            }
                            AppUpdateManager.UpdateState.DOWNLOADING -> {
                                btn.text = "↻ $progress%"
                                btn.visibility = View.VISIBLE
                            }
                            AppUpdateManager.UpdateState.DOWNLOAD_VERIFIED,
                            AppUpdateManager.UpdateState.INSTALLATION_PENDING -> {
                                btn.text = "↻ Install"
                                btn.visibility = View.VISIBLE
                            }
                            AppUpdateManager.UpdateState.FAILED -> {
                                btn.visibility = View.GONE
                            }
                            AppUpdateManager.UpdateState.UP_TO_DATE,
                            AppUpdateManager.UpdateState.IDLE -> {
                                btn.visibility = View.GONE
                            }
                            else -> {}
                        }
                    }
                }
            }
        }
        updateListener?.let { AppUpdateManager.getInstance(this).addListener(it) }

        // Proof submission & asynchronous evaluation bus
        proofEvaluationListener = { event ->
            runOnUiThread {
                if (!isFinishing && !isDestroyed) {
                    refreshUi()
                    if (event.pointsAwarded > 0) {
                        dispatchStrictBotEvent("POINTS_AWARDED", event.message)
                    }
                }
            }
        }
        proofEvaluationListener?.let { ProofEvaluationManager.addListener(it) }
        ProofEvaluationManager.resumePendingEvaluations(this, db)
        AiServiceHealthManager.initializeAndSchedulePeriodicCheck(this)
        PersistentUploadQueueManager.triggerQueueProcessingAsync(this)
    }

    override fun onConfigurationChanged(newConfig: android.content.res.Configuration) {
        super.onConfigurationChanged(newConfig)
        val sidePadDp = getResponsiveSidePaddingDp()
        topHeaderView?.setPadding(dp(sidePadDp), dp(10), dp(sidePadDp), dp(8))
        if (::contentContainer.isInitialized) {
            contentContainer.setPadding(dp(sidePadDp), dp(6), dp(sidePadDp), dp(96))
        }
        lastRenderedTab = ""
        refreshUi()
        if (::strictBotChat.isInitialized) strictBotChat.onConfigurationChanged()
    }

    override fun onNewIntent(intent: Intent?) {
        super.onNewIntent(intent)
        if (intent != null) { setIntent(intent); handleIncomingIntent(intent); refreshUi() }
    }

    override fun onResume() {
        super.onResume()
        StrictAccessibilityService.activeInstance?.onOwnActivityResumed()
        StrictRecordsPowerManager.onDeviceUnlocked(this)
        AiServiceHealthManager.synchronizeConfigWithBackend(this, force = false)
        val deadlineStatus = ScheduleDeadlineManager.evaluateScheduleStatus(this, db)
        if (deadlineStatus == ScheduleDeadlineRules.ScheduleDeadlineState.OVERDUE_UNCONFIRMED ||
            deadlineStatus == ScheduleDeadlineRules.ScheduleDeadlineState.COMPLETION_REQUIRED) {
            isSchedulePendingRestricted = true
            currentScheduleDeadlineState = ScheduleDeadlineRules.ScheduleDeadlineState.COMPLETION_REQUIRED
        } else if (deadlineStatus == ScheduleDeadlineRules.ScheduleDeadlineState.CONFIRMED_AND_RELEASED ||
                   deadlineStatus == ScheduleDeadlineRules.ScheduleDeadlineState.ON_TIME_CONFIRMED) {
            if (isSchedulePendingRestricted) {
                isSchedulePendingRestricted = false
                currentScheduleDeadlineState = deadlineStatus
                ScheduleDeadlineManager.cancelDeadlineNotification(this)
            }
        }
        screenResumed = true
        if (db.isWakeUpVerificationCompleted(db.nowDate())) {
            activeWakeUpPrerequisiteDialog?.dismiss()
            activeWakeUpPrerequisiteDialog = null
        }
        if (!StrictEnforcementService.isServiceRunning()) {
            uiHandler.post {
                StrictEnforcementService.start(applicationContext)
            }
        }
        TargetAppMonitoringPolicy.invalidateInstalledPackages()
        // Optional Usage Access revocation pauses target monitoring. Returning
        // to the app refreshes the real state without a repair dialog or redirect.
        DisciplinePermissionManager.handleResumeCheck(this) {
            refreshUi()
        }
        StrictAccessibilityService.activeInstance?.refreshPackageFilter()
        AccessibilityGraceManager.checkAccessibilityState(this)
        checkForegroundRestriction()
        startHeartbeatLoop()
        AppUpdateManager.getInstance(this).checkForUpdates()
        if (::strictBotChat.isInitialized) strictBotChat.recheckPermissions()
        liveSnapshotAt = 0L
        StrictWidgetUpdates.request(applicationContext)
        startLiveClock()
        startBotBreath()
        if (resumeWorkInFlight.compareAndSet(false, true)) Thread {
            try {
                UsageAccessMonitor.reconcile(applicationContext)
                db.reconcileValidatedSubmissions(db.nowDate())
                PersistentUploadQueueManager.triggerQueueProcessingAsync(applicationContext)
                AiServiceHealthManager.refreshIfStaleAsync(applicationContext, "activity_on_resume")
            } catch (error: Exception) {
                Log.w("StrictRecords", "Resume reconciliation: ${error.javaClass.simpleName}")
            } finally { resumeWorkInFlight.set(false) }
        }.start()
        refreshUi()
        uiHandler.post { if (screenResumed) checkAutoPromptOnLaunch() }
    }

    private var hasAutoPromptedOnLaunch = false
    private var isBathPopupShowing = false
    private var isBathPopupQueued = false
    private var bathPopupShownDate: String? = null

    private fun checkAutoPromptOnLaunch() {
        if (!screenResumed || isFinishing || isDestroyed) return
        if (isSchedulePendingRestricted) return
        val today = db.nowDate()
        val countdown = db.getCurrentCountdownState(today)
        val isWakeUp = countdown.title?.contains("Wake", ignoreCase = true) == true
        val isWakeUpActive = countdown.hasActiveWindow && isWakeUp
        val isCriticalDialogActive = WakeUpVerificationController.isVerificationDialogActive()

        val isWakeUpDone = db.isWakeUpVerificationCompleted(today, isDevMode)
        val isConfirmed = db.isBathScheduleConfirmed(today)
        val isMorningCompleted = isConfirmed || db.getConfigValue("morning_setup_completed_$today", "false") == "true"
        val alreadyAutoOpenedToday = db.hasMorningInAppAutoOpened(today)
        val calNow = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone(db.scheduleTimezone())).apply { timeInMillis = db.authoritativeNowMs() }
        val currentHour = calNow.get(java.util.Calendar.HOUR_OF_DAY)
        val isBeforeMorningCutoff = currentHour < 10
        val isMorningEligible = isBeforeMorningCutoff && !isMorningCompleted && (MorningWakeUpManager.isMorningFlowEligible(db, db.authoritativeNowMs()) ||
            (db.hasMorningFlowPromptBeenShown(today) && (!isWakeUpDone || !isConfirmed)))
        if (isMorningEligible && !alreadyAutoOpenedToday && !hasAutoPromptedOnLaunch && !isCriticalDialogActive) {
            hasAutoPromptedOnLaunch = true
            db.markMorningInAppAutoOpened(today)
            if (!isWakeUpDone) {
                if (!isConfirmed) {
                    isBathPopupQueued = true
                }
                window?.decorView?.post {
                    if (!screenResumed || isFinishing || isDestroyed) return@post
                    showWakeUpVerificationDialog()
                }
                return
            } else if (!isConfirmed && !isBathPopupShowing) {
                bathPopupShownDate = today
                window?.decorView?.post {
                    if (!screenResumed || isFinishing || isDestroyed) return@post
                    showBathScheduleConfirmationDialog(isEditing = false)
                }
                return
            }
        }

        val triggerResult = BathScheduleMorningPopupRules.shouldShowFirstMorningPopup(
            date = today,
            isConfirmed = isConfirmed,
            popupShownDate = bathPopupShownDate,
            isCriticalDialogActive = isCriticalDialogActive,
            clockMs = db.authoritativeNowMs(),
            timezone = db.scheduleTimezone()
        )

        if (isWakeUpActive && countdown.submissionEligible && !isWakeUpDone && !hasAutoPromptedOnLaunch) {
            hasAutoPromptedOnLaunch = true
            if (!isConfirmed) {
                isBathPopupQueued = true
            }
            window?.decorView?.post {
                if (!screenResumed || isFinishing || isDestroyed) return@post
                showWakeUpVerificationDialog()
            }
            return
        }

        if (triggerResult.shouldQueue) {
            isBathPopupQueued = true
            return
        }

        if (triggerResult.shouldShow && !isBathPopupShowing && !isMorningCompleted) {
            val isPromptAllowed = isBeforeMorningCutoff || (triggerResult.reason == "RECOVERY_FALLBACK" && !db.hasMorningFlowPromptBeenShown(today) && bathPopupShownDate != today)
            if (isPromptAllowed) {
                bathPopupShownDate = today
                db.markMorningFlowPromptShown(today)
                window?.decorView?.post {
                    if (!screenResumed || isFinishing || isDestroyed) return@post
                    showBathScheduleConfirmationDialog(isEditing = false)
                }
                return
            }
        }

        val hourlyAct = db.getActiveOrTargetHourlyActivity(today)
        val isAlreadySubmitted = hourlyAct?.status in listOf("SUBMITTED", "VALIDATING", "VERIFIED", "COMPLETED", "EXCUSED", "CANCELLED", "MISSED", "CLOSED")
        if (countdown.hasActiveWindow && countdown.submissionEligible && countdown.state == "OPEN" && !isAlreadySubmitted && !hasAutoPromptedOnLaunch) {
            hasAutoPromptedOnLaunch = true
            window?.decorView?.post {
                if (!screenResumed || isFinishing || isDestroyed) return@post
                showHourlySubmissionDialog()
            }
        }
    }

    private fun checkQueuedBathPopup() {
        val today = db.nowDate()
        if (!db.isBathScheduleConfirmed(today) && !isBathPopupShowing) {
            isBathPopupQueued = false
            bathPopupShownDate = today
            window?.decorView?.post {
                showBathScheduleConfirmationDialog(isEditing = false)
            }
        }
    }

    fun onTargetMonitoringChanged() {
        StrictWidgetUpdates.request(applicationContext,"monitoring")
        refreshUi()
        if (::strictBotChat.isInitialized) strictBotChat.recheckPermissions()
    }

    override fun onPause() {
        screenResumed = false
        val pm = getSystemService(Context.POWER_SERVICE) as? android.os.PowerManager
        val km = getSystemService(Context.KEYGUARD_SERVICE) as? android.app.KeyguardManager
        if (pm?.isInteractive == false || km?.isKeyguardLocked == true) {
            StrictRecordsPowerManager.onScreenOff(this)
        }
        dismissActiveDialogsOnExit()
        clockRunnable?.let { uiHandler.removeCallbacks(it) }
        botBreathRunnable?.let { uiHandler.removeCallbacks(it) }
        if (::floatingBotOrb.isInitialized) {
            floatingBotOrb.animate().cancel()
            floatingBotOrb.scaleX = 1f
            floatingBotOrb.scaleY = 1f
        }
        currentMascotView?.animate()?.cancel()
        heartbeatRunnable?.let { uiHandler.removeCallbacks(it) }
        if (::strictBotChat.isInitialized) strictBotChat.pause()
        super.onPause()
    }

    override fun onBackPressed() {
        if (isSchedulePendingRestricted) {
            Toast.makeText(this, "Today's schedule is pending. Complete and confirm today's schedule to restore normal app access.", Toast.LENGTH_LONG).show()
            return
        }
        if (::strictBotChat.isInitialized && strictBotChat.dismiss()) return
        if (isAdminMode) {
            if (adminSubTab != "OVERVIEW") {
                adminSubTab = "OVERVIEW"
                refreshUi()
                return
            } else {
                isAdminMode = false
                activeTab = "HOME"
                Toast.makeText(this, "Exited Admin Mode", Toast.LENGTH_SHORT).show()
                refreshUi()
                return
            }
        }
        super.onBackPressed()
    }

    private fun startHeartbeatLoop() {
        heartbeatRunnable?.let { uiHandler.removeCallbacks(it) }
        heartbeatRunnable = object : Runnable {
            override fun run() {
                if (!screenResumed) return
                if (heartbeatInFlight.compareAndSet(false, true)) {
                    Thread {
                        try {
                        if (!db.isDeviceRegistered()) return@Thread
                        val (ok, status) = db.sendHeartbeat(this@MainActivity)
                        if (ok) {
                            db.flushSyncEventsQueue(this@MainActivity)
                        }
                        val today = db.nowDate()
                        val routineGate = db.getDailyRoutineGate(today)
                        val activitiesForPreflight = db.getDailyActivities(today)
                        val nowMs = System.currentTimeMillis()
                        for (act in activitiesForPreflight) {
                            try {
                                val startMs = ProofWindowPreflightManager.parseIsoToMs(act.windowStart)
                                if (startMs >= nowMs - ProofWindowPreflightManager.PREFLIGHT_LEAD_TIME_MS &&
                                    act.status.uppercase(java.util.Locale.US) in setOf("SCHEDULED", "UPCOMING", "NOTIFIED") &&
                                    act.windowStart.isNotBlank() && !act.detailsJson.contains("\"excused\":true")) {
                                    ProofWindowPreflightManager.schedulePreflightForWindow(
                                        this@MainActivity,
                                        act.activityId,
                                        act.windowStart,
                                        act.scheduleVersion
                                    )
                                }
                            } catch (t: Throwable) {
                                Log.w("StrictRecords", "Preflight loop exception: ${t.message}")
                            }
                        }
                        val activityState = activitiesForPreflight.joinToString("|") { "${it.activityId}:${it.status}:${it.scheduleVersion}" }
                        val newHash = "${db.getScore(today, isDevMode)}_${db.calculateStreakDays(isDevMode)}_${db.getRemoteAppLocks()}_${routineGate}_${activityState}_$ok"
                        runOnUiThread {
                            if (isFinishing || isDestroyed || !screenResumed) return@runOnUiThread
                            if (::headerSyncDot.isInitialized) {
                                headerSyncDot.background = surfaceBg(if (ok) CLR_GREEN else CLR_AMBER, 99)
                            }
                            if (status == "NOT_REGISTERED" || status == "REVOKED" || newHash != lastSyncedHash) {
                                lastSyncedHash = newHash
                                refreshUi()
                            }
                        }
                        } catch (error: Throwable) {
                            Log.w("StrictRecords", "Visible sync error: ${error.javaClass.simpleName}: ${error.message}")
                        } finally { heartbeatInFlight.set(false) }
                    }.start()
                }
                val tzIst = db.scheduleTimezone()
                val calNow = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone(tzIst))
                val curH = calNow.get(java.util.Calendar.HOUR_OF_DAY)
                val curM = calNow.get(java.util.Calendar.MINUTE)
                val todayStr = db.nowDate()
                if (curH == 21 && curM >= 40 && lastPromptedNightlySummaryDate != todayStr) {
                    lastPromptedNightlySummaryDate = todayStr
                    runOnUiThread {
                        if (!isFinishing && !isDestroyed) {
                            showTodaysSummaryDialog()
                        }
                    }
                }
                uiHandler.postDelayed(this, 60000L)
            }
        }
        uiHandler.post(heartbeatRunnable!!)
    }

    private fun checkForegroundRestriction() {
        if (FinancialSafePause.isPauseActive(this)) {
            StrictBotOverlayController.hidePopupImmediate()
            return
        }
        val activePkg = HardwareDeviceVerifier.detectRealForegroundPackage(this)
        if (activePkg == packageName) {
            // MainActivity itself is foreground; do NOT hide active popup or modal dialogs
            return
        }
        if (activePkg == null ||
            FinancialSafePause.isProtectedFinancialPackage(this, activePkg) ||
            !TargetAppMonitoringPolicy.mayMonitor(this, activePkg) ||
            !HardwareDeviceVerifier.confirmTargetForeground(this, activePkg) ||
            !DisciplineScoringRules.isRestrictedTarget(activePkg)) {
            StrictBotOverlayController.hidePopupImmediate()
            return
        }
        val score = db.getScore(db.nowDate(), false)
        val decision = DisciplineScoringRules.evaluateRestrictionDecision(
            score = score,
            packageNameOrApp = activePkg,
            appLocks = db.getRemoteAppLocks(),
            isEducationalUnlockActive = db.isEducationalUnlockActive()
        )
        if (decision.isRestricted && !StrictBotOverlayController.isDismissedForCurrentSession(activePkg)) {
            db.recordRestrictionEvent(
                decision.packageName,
                decision.appName,
                decision.scoreAtDetection,
                decision.requiredScore,
                decision.action,
                decision.reason
            )
            StrictBotOverlayController.showStrictBotPopup(this, decision)
        }
    }

    override fun onRequestPermissionsResult(
        requestCode: Int,
        permissions: Array<out String>,
        grantResults: IntArray
    ) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults)
        if (requestCode == 16980) {
            if (grantResults.isNotEmpty() && grantResults.all { it == android.content.pm.PackageManager.PERMISSION_GRANTED }) showBluetoothTransferDialog()
            else Toast.makeText(this, "Nearby devices permission is needed to select the receiving PC", Toast.LENGTH_LONG).show()
            return
        }

        if (::strictBotChat.isInitialized && strictBotChat.onPermissionResult(requestCode, grantResults)) return
        DisciplinePermissionManager.handlePermissionResult(this, requestCode, permissions, grantResults) {
            refreshUi()
        }
    }

    private fun dismissActiveDialogsOnExit() {
        if (!isFinishing) return
        activeHourlyCountdownRunnable?.let { uiHandler.removeCallbacks(it) }
        activeHourlyCountdownRunnable = null
        try {
            if (activeHourlyDialog?.isShowing == true) activeHourlyDialog?.dismiss()
        } catch (_: Exception) {}
        activeHourlyDialog = null

        try {
            if (WakeUpVerificationController.isVerificationDialogActive()) {
                WakeUpVerificationController.dismissVerificationDialog()
            }
        } catch (_: Exception) {}

        try {
            if (bathDialogRef?.isShowing == true) bathDialogRef?.dismiss()
        } catch (_: Exception) {}
        bathDialogRef = null
        isBathPopupShowing = false

        try {
            if (travelDialogRef?.isShowing == true) travelDialogRef?.dismiss()
        } catch (_: Exception) {}
        travelDialogRef = null

        try {
            if (gymDialogRef?.isShowing == true) gymDialogRef?.dismiss()
        } catch (_: Exception) {}
        gymDialogRef = null

        try {
            if (updateDialogRef?.isShowing == true) updateDialogRef?.dismiss()
        } catch (_: Exception) {}
        updateDialogRef = null
    }

    override fun onDestroy() {
        try {
            scheduleRestrictionReceiver?.let { unregisterReceiver(it) }
            scheduleRestrictionReceiver = null
        } catch (_: Exception) {}
        dismissActiveDialogsOnExit()
        screenResumed = false
        liveSnapshotGeneration++
        liveStateWorker.shutdownNow()
        updateListener?.let { AppUpdateManager.getInstance(this).removeListener(it) }
        updateListener = null
        proofEvaluationListener?.let { ProofEvaluationManager.removeListener(it) }
        proofEvaluationListener = null
        mediaPlayer?.release()
        stopWakeUpPreview()
        if (::strictBotChat.isInitialized) strictBotChat.destroy()
        clockRunnable?.let { uiHandler.removeCallbacks(it) }
        botBreathRunnable?.let { uiHandler.removeCallbacks(it) }
        heartbeatRunnable?.let { uiHandler.removeCallbacks(it) }
        youtubeCountdownRunnable?.let { uiHandler.removeCallbacks(it) }
        gymModeCountdownRunnable?.let { uiHandler.removeCallbacks(it) }
        super.onDestroy()
    }

