    private fun dp(v: Int) = TypedValue.applyDimension(
        TypedValue.COMPLEX_UNIT_DIP, v.toFloat(), resources.displayMetrics).toInt()

    private fun dp(v: Float) = TypedValue.applyDimension(
        TypedValue.COMPLEX_UNIT_DIP, v, resources.displayMetrics).toInt()

    private fun dp(v: Number) = TypedValue.applyDimension(
        TypedValue.COMPLEX_UNIT_DIP, v.toFloat(), resources.displayMetrics).toInt()

    private fun sp(v: Float) = TypedValue.applyDimension(
        TypedValue.COMPLEX_UNIT_SP, v, resources.displayMetrics)

    private fun toast(msg: String) {
        runOnUiThread {
            Toast.makeText(this, msg, Toast.LENGTH_SHORT).show()
        }
    }

    // ════════════════════════════════════════════════════════
    // Drawable helpers (surface system)
    // ════════════════════════════════════════════════════════

    fun surfaceBg(fillHex: String, radiusDp: Int = 20, strokeHex: String? = null, strokeDp: Int = 1): GradientDrawable =
        GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = dp(radiusDp).toFloat()
            setColor(Color.parseColor(fillHex))
            if (strokeHex != null) setStroke(dp(strokeDp), Color.parseColor(strokeHex))
        }

    private fun gradientBg(c1: String, c2: String, radiusDp: Int = 20,
                            orient: GradientDrawable.Orientation = GradientDrawable.Orientation.TL_BR,
                            strokeHex: String? = null): GradientDrawable =
        GradientDrawable(orient, intArrayOf(Color.parseColor(c1), Color.parseColor(c2))).apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = dp(radiusDp).toFloat()
            if (strokeHex != null) setStroke(dp(1), Color.parseColor(strokeHex))
        }

    // ════════════════════════════════════════════════════════
    // Spring-physics button helper
    // Every button gets: press scale → spring release
    // + optional loading / success state
    // ════════════════════════════════════════════════════════

    private fun View.applySpringTouch(
        scaleDown: Float = 0.95f,
        onTap: (() -> Unit)? = null
    ) {
        var touchStartX = 0f
        var touchStartY = 0f
        setOnTouchListener { v, ev ->
            when (ev.action) {
                MotionEvent.ACTION_DOWN -> {
                    touchStartX = ev.x; touchStartY = ev.y
                    animate().scaleX(scaleDown).scaleY(scaleDown)
                        .setDuration(DUR_FAST).setInterpolator(DecelerateInterpolator()).start()
                }
                MotionEvent.ACTION_UP -> {
                    animate().scaleX(1f).scaleY(1f)
                        .setDuration(DUR_SPRING).setInterpolator(OvershootInterpolator(2.2f)).start()
                    val dx = ev.x - touchStartX; val dy = ev.y - touchStartY
                    if (dx * dx + dy * dy < dp(12) * dp(12)) onTap?.invoke()
                }
                MotionEvent.ACTION_CANCEL -> {
                    animate().scaleX(1f).scaleY(1f).setDuration(DUR_MED).start()
                }
            }
            true
        }
    }

    private fun haptic(style: Int = 0) {
        try {
            @Suppress("DEPRECATION")
            val vib = getSystemService(Context.VIBRATOR_SERVICE) as? Vibrator ?: return
            val pattern = when (style) {
                1 -> longArrayOf(0, 18, 60, 18)          // success double-tap
                2 -> longArrayOf(0, 30, 40, 80, 30, 0)   // reward triple
                3 -> longArrayOf(0, 60)                   // warning single
                else -> longArrayOf(0, 12)                // light tick
            }
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
                val eff = VibrationEffect.createWaveform(pattern, -1)
                vib.vibrate(eff)
            } else {
                @Suppress("DEPRECATION")
                vib.vibrate(pattern, -1)
            }
        } catch (_: Exception) {}
    }

    // ════════════════════════════════════════════════════════
    // PRIMARY BUTTON — idle/press/loading/success states
    // ════════════════════════════════════════════════════════

    private fun makePrimaryButton(
        label: String,
        accentHex: String = CLR_INDIGO,
        widthMatchParent: Boolean = false,
        onTap: (btn: LinearLayout) -> Unit
    ): LinearLayout {
        val padV = dp(if (isWideLayout()) 12 else 9)
        val padH = dp(if (isWideLayout()) 18 else 14)
        val btn = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER
            setPadding(padH, padV, padH, padV)
            background = gradientBg(accentHex, darken(accentHex, 0.6f), 99)
            layoutParams = if (widthMatchParent)
                LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            else
                LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        val tv = TextView(this).apply {
            text = label
            textSize = if (isWideLayout()) 13.5f else 12.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            letterSpacing = 0.04f
        }
        btn.addView(tv)
        btn.applySpringTouch { onTap(btn) }
        return btn
    }

    private fun setPrimaryButtonLabel(button: LinearLayout, label: String) {
        (button.getChildAt(0) as? TextView)?.text = label
    }

    private fun makeSecondaryButton(label: String, accentHex: String = CLR_BLUE, onTap: () -> Unit): LinearLayout {
        val padV = dp(if (isWideLayout()) 9 else 6)
        val padH = dp(if (isWideLayout()) 14 else 10)
        val btn = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER
            setPadding(padH, padV, padH, padV)
            background = surfaceBg(CLR_ELEVATED, 99, accentHex, 1)
        }
        val tv = TextView(this).apply {
            text = label
            textSize = if (isWideLayout()) 12f else 10.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(accentHex))
        }
        btn.addView(tv)
        btn.applySpringTouch { onTap() }
        return btn
    }

    /**
     * Lays out the action buttons of a dialog row (e.g. CANCEL + CONFIRM) with a clear gap and a
     * comfortable minimum tap height so neighbouring buttons are not hit by mistake. Applied only
     * to the rows that call it; the shared button factories keep their existing look elsewhere.
     */
    private fun spaceDialogButtons(row: LinearLayout, vararg buttons: View) {
        row.gravity = Gravity.END or Gravity.CENTER_VERTICAL
        val gap = dp(if (isWideLayout()) 24 else 20)
        val minHeight = dp(46)
        buttons.forEachIndexed { index, button ->
            button.minimumHeight = minHeight
            button.layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { if (index > 0) leftMargin = gap }
        }
    }

    private fun makeChip(label: String, accentHex: String, selected: Boolean = false, onTap: () -> Unit): TextView =
        TextView(this).apply {
            text = label
            textSize = 12f
            setTypeface(typeface, if (selected) Typeface.BOLD else Typeface.NORMAL)
            setTextColor(Color.parseColor(if (selected) "#FFFFFF" else CLR_TEXT_SECONDARY))
            setPadding(dp(14), dp(8), dp(14), dp(8))
            background = if (selected) gradientBg(accentHex, darken(accentHex, 0.7f), 99)
                         else surfaceBg(CLR_ELEVATED, 99, CLR_TEXT_DIM, 1)
            applySpringTouch(scaleDown = 0.93f) { onTap() }
        }

    // ════════════════════════════════════════════════════════
    // Color utilities
    // ════════════════════════════════════════════════════════

    private fun darken(hex: String, factor: Float): String {
        val c = Color.parseColor(hex)
        val r = (Color.red(c) * factor).toInt().coerceIn(0, 255)
        val g = (Color.green(c) * factor).toInt().coerceIn(0, 255)
        val b = (Color.blue(c) * factor).toInt().coerceIn(0, 255)
        return String.format("#%02X%02X%02X", r, g, b)
    }

    private fun scoreColor(score: Int) = when {
        score >= 90 -> CLR_BLUE
        score >= 80 -> CLR_GREEN
        score >= 60 -> CLR_AMBER
        else -> CLR_RED
    }

    // ════════════════════════════════════════════════════════
    // CUSTOM VIEW: Animated Score Arc (Canvas-based)
    // ════════════════════════════════════════════════════════

    inner class ScoreArcView(ctx: Context) : View(ctx) {

        var targetProgress = 0f
        var animProgress = 0f
        private val trackPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            style = Paint.Style.STROKE
            strokeWidth = dp(10).toFloat()
            strokeCap = Paint.Cap.ROUND
            color = Color.parseColor(CLR_SURFACE)
        }
        private val arcPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            style = Paint.Style.STROKE
            strokeWidth = dp(10).toFloat()
            strokeCap = Paint.Cap.ROUND
        }
        private val glowPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            style = Paint.Style.STROKE
            strokeWidth = dp(18).toFloat()
            strokeCap = Paint.Cap.ROUND
            alpha = 35
        }
        private var isGlowing = false

        fun animateTo(newProgress: Float, onDone: (() -> Unit)? = null) {
            val from = animProgress
            ValueAnimator.ofFloat(from, newProgress).apply {
                duration = DUR_HERO
                interpolator = DecelerateInterpolator(1.8f)
                addUpdateListener { animProgress = it.animatedValue as Float; invalidate() }
                addListener(object : AnimatorListenerAdapter() {
                    override fun onAnimationEnd(a: Animator) { onDone?.invoke() }
                })
                start()
            }
        }

        fun triggerGlow() {
            isGlowing = true
            invalidate()
            uiHandler.postDelayed({ isGlowing = false; invalidate() }, 900L)
        }

        override fun onDraw(canvas: Canvas) {
            val w = width.toFloat(); val h = height.toFloat()
            val padding = dp(14).toFloat()
            val rect = RectF(padding, padding, w - padding, h - padding)
            val startAngle = 135f; val sweepTotal = 270f

            val progressFrac = (animProgress / 100f).coerceIn(0f, 1f)

            // glow
            if (isGlowing) {
                val score = animProgress.toInt()
                glowPaint.color = Color.parseColor(scoreColor(score))
                canvas.drawArc(rect, startAngle, sweepTotal * progressFrac, false, glowPaint)
            }

            // track
            canvas.drawArc(rect, startAngle, sweepTotal, false, trackPaint)

            // arc
            val score = animProgress.toInt()
            val arcColor = Color.parseColor(scoreColor(score))
            arcPaint.shader = LinearGradient(
                rect.left, rect.top, rect.right, rect.bottom,
                intArrayOf(arcColor, adjustAlpha(arcColor, 0.7f)),
                null, Shader.TileMode.CLAMP
            )
            canvas.drawArc(rect, startAngle, sweepTotal * progressFrac, false, arcPaint)
        }

        private fun adjustAlpha(color: Int, factor: Float): Int {
            return Color.argb((Color.alpha(color) * factor).toInt(), Color.red(color), Color.green(color), Color.blue(color))
        }
    }

    // ════════════════════════════════════════════════════════
    // CUSTOM REFINED VECTOR ICON VIEW & MASCOT GLOW VIEW
    // ════════════════════════════════════════════════════════

    inner class MascotGlowView(ctx: Context) : View(ctx) {
        private val topGlowPaint = Paint(Paint.ANTI_ALIAS_FLAG)
        private val bottomGlowPaint = Paint(Paint.ANTI_ALIAS_FLAG)
        override fun onDraw(canvas: Canvas) {
            val w = width.toFloat()
            val h = height.toFloat()
            if (w <= 0f || h <= 0f) return
            val cx = w * 0.5f
            val cy = h * 0.46f
            val r = minOf(w, h) * 0.52f
            topGlowPaint.shader = android.graphics.RadialGradient(
                cx, cy, r,
                intArrayOf(
                    Color.argb(68, 0, 229, 153),
                    Color.argb(32, 0, 210, 255),
                    Color.TRANSPARENT
                ),
                floatArrayOf(0f, 0.58f, 1f),
                Shader.TileMode.CLAMP
            )
            canvas.drawCircle(cx, cy, r, topGlowPaint)

            val by = h * 0.84f
            val br = minOf(w, h) * 0.36f
            bottomGlowPaint.shader = android.graphics.RadialGradient(
                cx, by, br,
                intArrayOf(
                    Color.argb(85, 245, 158, 11),
                    Color.argb(28, 239, 68, 68),
                    Color.TRANSPARENT
                ),
                floatArrayOf(0f, 0.6f, 1f),
                Shader.TileMode.CLAMP
            )
            canvas.drawCircle(cx, by, br, bottomGlowPaint)
        }
    }

    inner class VectorIconView(
        ctx: Context,
        var iconType: String,
        colorHex: String,
        private val strokeDp: Float = 1.8f
    ) : View(ctx) {
        private var currentColor: Int = Color.parseColor(colorHex)
        private val strokePaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            style = Paint.Style.STROKE
            strokeCap = Paint.Cap.ROUND
            strokeJoin = Paint.Join.ROUND
        }
        private val fillPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            style = Paint.Style.FILL
        }
        private val path = Path()
        private val rect = RectF()

        fun setTint(colorHex: String) {
            currentColor = Color.parseColor(colorHex)
            invalidate()
        }

        override fun onDraw(canvas: Canvas) {
            val w = width.toFloat()
            val h = height.toFloat()
            if (w <= 0f || h <= 0f) return
            val sw = TypedValue.applyDimension(TypedValue.COMPLEX_UNIT_DIP, strokeDp, resources.displayMetrics)
            strokePaint.strokeWidth = sw
            strokePaint.color = currentColor
            fillPaint.color = currentColor
            path.reset()

            val cx = w * 0.5f
            val cy = h * 0.5f
            val r = minOf(w, h) * 0.38f

            when (iconType) {
                "SHIELD" -> {
                    path.moveTo(cx, cy - r)
                    path.lineTo(cx + r * 0.82f, cy - r * 0.55f)
                    path.lineTo(cx + r * 0.72f, cy + r * 0.25f)
                    path.quadTo(cx, cy + r * 1.05f, cx, cy + r * 1.05f)
                    path.quadTo(cx, cy + r * 1.05f, cx - r * 0.72f, cy + r * 0.25f)
                    path.lineTo(cx - r * 0.82f, cy - r * 0.55f)
                    path.close()
                    canvas.drawPath(path, fillPaint)
                }
                "FLAME" -> {
                    path.moveTo(cx, cy - r * 1.05f)
                    path.cubicTo(cx + r * 0.85f, cy - r * 0.35f, cx + r * 0.95f, cy + r * 0.45f, cx, cy + r)
                    path.cubicTo(cx - r * 0.95f, cy + r * 0.45f, cx - r * 0.85f, cy - r * 0.35f, cx, cy - r * 1.05f)
                    path.close()
                    canvas.drawPath(path, fillPaint)
                    fillPaint.color = Color.parseColor(CLR_BG)
                    canvas.drawCircle(cx, cy + r * 0.35f, r * 0.28f, fillPaint)
                    fillPaint.color = currentColor
                }
                "CALENDAR" -> {
                    rect.set(cx - r, cy - r * 0.78f, cx + r, cy + r * 0.95f)
                    canvas.drawRoundRect(rect, sw * 1.2f, sw * 1.2f, strokePaint)
                    canvas.drawLine(cx - r, cy - r * 0.22f, cx + r, cy - r * 0.22f, strokePaint)
                    canvas.drawLine(cx - r * 0.45f, cy - r * 1.05f, cx - r * 0.45f, cy - r * 0.55f, strokePaint)
                    canvas.drawLine(cx + r * 0.45f, cy - r * 1.05f, cx + r * 0.45f, cy - r * 0.55f, strokePaint)
                }
                "CLOCK" -> {
                    canvas.drawCircle(cx, cy, r, strokePaint)
                    canvas.drawLine(cx, cy - r * 0.52f, cx, cy, strokePaint)
                    canvas.drawLine(cx, cy, cx + r * 0.42f, cy + r * 0.25f, strokePaint)
                }
                "ALARM" -> {
                    canvas.drawCircle(cx, cy + r * 0.08f, r * 0.88f, strokePaint)
                    canvas.drawLine(cx, cy - r * 0.36f, cx, cy + r * 0.08f, strokePaint)
                    canvas.drawLine(cx, cy + r * 0.08f, cx + r * 0.38f, cy + r * 0.28f, strokePaint)
                    canvas.drawLine(cx - r * 0.85f, cy - r * 0.55f, cx - r * 0.42f, cy - r * 0.88f, strokePaint)
                    canvas.drawLine(cx + r * 0.42f, cy - r * 0.88f, cx + r * 0.85f, cy - r * 0.55f, strokePaint)
                }
                "SLIDERS" -> {
                    val y1 = cy - r * 0.55f
                    val y2 = cy
                    val y3 = cy + r * 0.55f
                    canvas.drawLine(cx - r, y1, cx + r, y1, strokePaint)
                    canvas.drawLine(cx - r, y2, cx + r, y2, strokePaint)
                    canvas.drawLine(cx - r, y3, cx + r, y3, strokePaint)
                    canvas.drawCircle(cx - r * 0.3f, y1, sw * 1.15f, fillPaint)
                    canvas.drawCircle(cx + r * 0.35f, y2, sw * 1.15f, fillPaint)
                    canvas.drawCircle(cx - r * 0.15f, y3, sw * 1.15f, fillPaint)
                }
                "STAR" -> {
                    for (i in 0 until 10) {
                        val ang = Math.toRadians((i * 36 - 90).toDouble())
                        val rad = if (i % 2 == 0) r else r * 0.44f
                        val px = cx + (rad * Math.cos(ang)).toFloat()
                        val py = cy + (rad * Math.sin(ang)).toFloat()
                        if (i == 0) path.moveTo(px, py) else path.lineTo(px, py)
                    }
                    path.close()
                    canvas.drawPath(path, fillPaint)
                }
                "SUN" -> {
                    canvas.drawCircle(cx, cy, r * 0.46f, fillPaint)
                    for (i in 0 until 8) {
                        val ang = Math.toRadians((i * 45).toDouble())
                        val x1 = cx + (r * 0.68f * Math.cos(ang)).toFloat()
                        val y1 = cy + (r * 0.68f * Math.sin(ang)).toFloat()
                        val x2 = cx + (r * 0.98f * Math.cos(ang)).toFloat()
                        val y2 = cy + (r * 0.98f * Math.sin(ang)).toFloat()
                        canvas.drawLine(x1, y1, x2, y2, strokePaint)
                    }
                }
                "CHECK_CIRCLE" -> {
                    canvas.drawCircle(cx, cy, r * 0.92f, fillPaint)
                    strokePaint.color = Color.parseColor(CLR_BG)
                    strokePaint.strokeWidth = sw * 1.25f
                    path.moveTo(cx - r * 0.38f, cy + r * 0.02f)
                    path.lineTo(cx - r * 0.08f, cy + r * 0.32f)
                    path.lineTo(cx + r * 0.42f, cy - r * 0.26f)
                    canvas.drawPath(path, strokePaint)
                    strokePaint.color = currentColor
                }
                "GYM" -> {
                    val d = r * 0.65f
                    canvas.drawLine(cx - d, cy - d, cx + d, cy + d, strokePaint)
                    canvas.drawLine(cx - d, cy - d, cx - d * 0.25f, cy - d, strokePaint)
                    canvas.drawLine(cx - d, cy - d, cx - d, cy - d * 0.25f, strokePaint)
                    canvas.drawLine(cx + d, cy + d, cx + d * 0.25f, cy + d, strokePaint)
                    canvas.drawLine(cx + d, cy + d, cx + d, cy + d * 0.25f, strokePaint)
                }
                "BATH" -> {
                    rect.set(cx - r * 0.95f, cy - r * 0.05f, cx + r * 0.95f, cy + r * 0.72f)
                    canvas.drawRoundRect(rect, sw * 1.4f, sw * 1.4f, fillPaint)
                    canvas.drawLine(cx - r * 0.95f, cy - r * 0.05f, cx + r * 0.95f, cy - r * 0.05f, strokePaint)
                    canvas.drawLine(cx - r * 0.65f, cy - r * 0.75f, cx - r * 0.65f, cy - r * 0.05f, strokePaint)
                    canvas.drawLine(cx - r * 0.65f, cy - r * 0.75f, cx - r * 0.25f, cy - r * 0.75f, strokePaint)
                }
                "CAR", "TRAVEL" -> {
                    rect.set(cx - r * 0.92f, cy - r * 0.1f, cx + r * 0.92f, cy + r * 0.62f)
                    canvas.drawRoundRect(rect, sw * 1.2f, sw * 1.2f, strokePaint)
                    path.moveTo(cx - r * 0.68f, cy - r * 0.1f)
                    path.lineTo(cx - r * 0.42f, cy - r * 0.68f)
                    path.lineTo(cx + r * 0.42f, cy - r * 0.68f)
                    path.lineTo(cx + r * 0.68f, cy - r * 0.1f)
                    canvas.drawPath(path, strokePaint)
                    canvas.drawCircle(cx - r * 0.52f, cy + r * 0.26f, sw * 0.85f, fillPaint)
                    canvas.drawCircle(cx + r * 0.52f, cy + r * 0.26f, sw * 0.85f, fillPaint)
                }
                "PLANE" -> {
                    path.moveTo(cx - r * 0.85f, cy + r * 0.15f)
                    path.lineTo(cx + r * 0.85f, cy - r * 0.45f)
                    path.lineTo(cx + r * 0.15f, cy + r * 0.55f)
                    path.lineTo(cx - r * 0.2f, cy + r * 0.15f)
                    path.close()
                    canvas.drawPath(path, strokePaint)
                    canvas.drawLine(cx - r * 0.85f, cy + r * 0.78f, cx + r * 0.85f, cy + r * 0.78f, strokePaint)
                }
                "WALK" -> {
                    canvas.drawCircle(cx, cy - r * 0.68f, r * 0.22f, fillPaint)
                    canvas.drawLine(cx, cy - r * 0.42f, cx, cy + r * 0.22f, strokePaint)
                    canvas.drawLine(cx - r * 0.48f, cy - r * 0.12f, cx + r * 0.48f, cy - r * 0.12f, strokePaint)
                    canvas.drawLine(cx, cy + r * 0.22f, cx - r * 0.42f, cy + r * 0.88f, strokePaint)
                    canvas.drawLine(cx, cy + r * 0.22f, cx + r * 0.42f, cy + r * 0.88f, strokePaint)
                }
                "SPEAKER" -> {
                    path.moveTo(cx - r * 0.75f, cy - r * 0.28f)
                    path.lineTo(cx - r * 0.35f, cy - r * 0.28f)
                    path.lineTo(cx + r * 0.12f, cy - r * 0.68f)
                    path.lineTo(cx + r * 0.12f, cy + r * 0.68f)
                    path.lineTo(cx - r * 0.35f, cy + r * 0.28f)
                    path.lineTo(cx - r * 0.75f, cy + r * 0.28f)
                    path.close()
                    canvas.drawPath(path, fillPaint)
                    rect.set(cx - r * 0.2f, cy - r * 0.55f, cx + r * 0.75f, cy + r * 0.55f)
                    canvas.drawArc(rect, -45f, 90f, false, strokePaint)
                }
                "HOVER" -> {
                    canvas.drawCircle(cx + r * 0.25f, cy - r * 0.22f, r * 0.32f, fillPaint)
                    canvas.drawLine(cx - r * 0.85f, cy - r * 0.25f, cx - r * 0.2f, cy - r * 0.25f, strokePaint)
                    canvas.drawLine(cx - r * 0.95f, cy + r * 0.15f, cx + r * 0.55f, cy + r * 0.15f, strokePaint)
                    canvas.drawLine(cx - r * 0.65f, cy + r * 0.55f, cx + r * 0.35f, cy + r * 0.55f, strokePaint)
                }
                "NAV_HOME" -> {
                    val g = r * 0.16f
                    val s = r * 0.78f
                    val cr = sw * 0.9f
                    rect.set(cx - s - g, cy - s - g, cx - g, cy - g)
                    canvas.drawRoundRect(rect, cr, cr, fillPaint)
                    rect.set(cx + g, cy - s - g, cx + s + g, cy - g)
                    canvas.drawRoundRect(rect, cr, cr, fillPaint)
                    rect.set(cx - s - g, cy + g, cx - g, cy + s + g)
                    canvas.drawRoundRect(rect, cr, cr, fillPaint)
                    rect.set(cx + g, cy + g, cx + s + g, cy + s + g)
                    canvas.drawRoundRect(rect, cr, cr, fillPaint)
                }
                "NAV_TASKS" -> {
                    rect.set(cx - r * 0.85f, cy - r * 0.72f, cx + r * 0.85f, cy + r * 0.92f)
                    canvas.drawRoundRect(rect, sw * 1.1f, sw * 1.1f, strokePaint)
                    canvas.drawLine(cx - r * 0.85f, cy - r * 0.18f, cx + r * 0.85f, cy - r * 0.18f, strokePaint)
                    canvas.drawLine(cx - r * 0.42f, cy - r * 0.98f, cx - r * 0.42f, cy - r * 0.48f, strokePaint)
                    canvas.drawLine(cx + r * 0.42f, cy - r * 0.98f, cx + r * 0.42f, cy - r * 0.48f, strokePaint)
                }
                "NAV_REWARDS" -> {
                    path.moveTo(cx - r * 0.45f, cy - r * 0.95f)
                    path.lineTo(cx - r * 0.15f, cy - r * 0.15f)
                    path.lineTo(cx + r * 0.15f, cy - r * 0.15f)
                    path.lineTo(cx + r * 0.45f, cy - r * 0.95f)
                    canvas.drawPath(path, strokePaint)
                    canvas.drawCircle(cx, cy + r * 0.35f, r * 0.56f, strokePaint)
                    canvas.drawCircle(cx, cy + r * 0.35f, r * 0.22f, fillPaint)
                }
                "NAV_DEVICES" -> {
                    rect.set(cx - r * 0.95f, cy - r * 0.68f, cx + r * 0.38f, cy + r * 0.38f)
                    canvas.drawRoundRect(rect, sw, sw, strokePaint)
                    canvas.drawLine(cx - r * 1.05f, cy + r * 0.68f, cx + r * 0.42f, cy + r * 0.68f, strokePaint)
                    rect.set(cx + r * 0.48f, cy - r * 0.28f, cx + r * 0.98f, cy + r * 0.68f)
                    canvas.drawRoundRect(rect, sw * 0.8f, sw * 0.8f, strokePaint)
                }
                "NAV_SETTINGS" -> {
                    val cr = r * 0.58f
                    canvas.drawCircle(cx, cy, cr, strokePaint)
                    canvas.drawCircle(cx, cy, r * 0.22f, fillPaint)
                    for (i in 0 until 6) {
                        val ang = Math.toRadians((i * 60).toDouble())
                        val cos = Math.cos(ang).toFloat()
                        val sin = Math.sin(ang).toFloat()
                        val x1 = cx + (cr - sw * 0.2f) * cos
                        val y1 = cy + (cr - sw * 0.2f) * sin
                        val x2 = cx + (r * 0.95f) * cos
                        val y2 = cy + (r * 0.95f) * sin
                        canvas.drawLine(x1, y1, x2, y2, strokePaint)
                    }
                }
            }
        }
    }

    private fun currentWindowWidthDp(): Float {
        val configuredWidth = resources.configuration.screenWidthDp
        return if (configuredWidth > 0) configuredWidth.toFloat()
        else resources.displayMetrics.widthPixels / resources.displayMetrics.density
    }

    /** Use one-column layouts when either the window or the user's text scale is tight. */
    private fun isWideLayout(): Boolean =
        currentWindowWidthDp() >= 600f && resources.configuration.fontScale < 1.25f

    private fun isCompactPhoneLayout(): Boolean = !isWideLayout()

    private fun isNarrowPhoneLayout(): Boolean =
        currentWindowWidthDp() < 400f || resources.configuration.fontScale >= 1.25f

    private fun getResponsiveSidePaddingDp(): Int {
        val widthDp = currentWindowWidthDp()
        return when {
            widthDp >= 1000 -> ((widthDp - 960f) / 2f).toInt().coerceAtLeast(24)
            widthDp >= 600  -> 18
            else            -> 12
        }
    }

    // ════════════════════════════════════════════════════════
    // BUILD ROOT SHELL
    // ════════════════════════════════════════════════════════

    private fun buildShell() {
        rootFrame = FrameLayout(this).apply {
            setBackgroundColor(Color.parseColor(CLR_BG))
        }

        val sidePadDp = getResponsiveSidePaddingDp()

        // ── Compact top header bar ─────────────────────────
        val header = buildTopHeader()
        topHeaderView = header
        header.layoutParams = LinearLayout.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)

        // Stretch short pages to the available height so their contextual tail panel can use
        // the remaining space instead of leaving an unused black area above the navigation.
        contentScroll = ScrollView(this).apply {
            isVerticalScrollBarEnabled = false
            overScrollMode = View.OVER_SCROLL_NEVER
            isFillViewport = true
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f)
        }

        contentContainer = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(sidePadDp), dp(6), dp(sidePadDp), dp(96))
        }
        contentScroll.addView(contentContainer)

        // ── Docked Bottom navigation bar ───────────────────
        val nav = buildFloatingNav()
        bottomNavView = nav
        applyFrontendTypography(header)
        applyFrontendTypography(nav)

        // ── Main vertical container ─────────────────────────
        val mainVert = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)
        }

        mainVert.addView(header)
        mainVert.addView(contentScroll)
        mainVert.addView(nav)
        rootFrame.addView(mainVert)

        // ── Floating StrictBot orb (Hidden to prevent blocking bottom nav) ───
        floatingBotOrb = TextView(this).apply {
            text = "🤖"
            textSize = 22f
            gravity = Gravity.CENTER
            visibility = View.GONE
            applySpringTouch { showStrictBotPanel() }
        }
        startBotBreath()

        // ── Floating score capsule (sticky) ────────────────
        headerScoreCapsule = TextView(this).apply {
            text = "⚡ 0 / 100"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_AMBER_LIGHT))
            setPadding(dp(12), dp(5), dp(12), dp(5))
            background = surfaceBg(CLR_ELEVATED, 99, CLR_AMBER, 1)
            layoutParams = FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT,
                ViewGroup.LayoutParams.WRAP_CONTENT,
                Gravity.TOP or Gravity.END
            ).apply { topMargin = dp(8); rightMargin = dp(16) }
            alpha = 0f
            applySpringTouch {
                activeTab = "TRANSACTIONS"
                refreshUi()
            }
        }

        // ── Floating score points animation label ──────────
        floatingPointsLabel = TextView(this).apply {
            textSize = 18f
            setTypeface(typeface, Typeface.BOLD)
            gravity = Gravity.CENTER
            visibility = View.GONE
            layoutParams = FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT, Gravity.CENTER)
        }
        rootFrame.addView(headerScoreCapsule)
        rootFrame.addView(floatingPointsLabel)
        rootFrame.addView(floatingBotOrb)

        // ── Splash overlay ─────────────────────────────────
        splashOverlay = buildSplashOverlay()
        rootFrame.addView(splashOverlay)

        setContentView(rootFrame)
    }

    // ── Top compact header (Reference Image B spec) ──────────────────────
    private fun buildTopHeader(): LinearLayout = LinearLayout(this).apply {
        val compactHeader = isNarrowPhoneLayout()
        orientation = LinearLayout.VERTICAL
        gravity = Gravity.CENTER_VERTICAL
        val sidePadDp = getResponsiveSidePaddingDp()
        setPadding(dp(sidePadDp), dp(if (isWideLayout()) 6 else 4), dp(sidePadDp), dp(if (isWideLayout()) 5 else 3))

        val primaryRow = LinearLayout(this@MainActivity).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT
            )
        }
