    // ── Docked Bottom Navigation Bar (Reference Image B spec) ──────────────
    private fun buildFloatingNav(): FrameLayout {
        navBtns.clear()
        val isTablet = isWideLayout()
        val baseNavHeightDp = if (isTablet) 64 else 58
        val navHeightDp = maxOf(
            baseNavHeightDp,
            (baseNavHeightDp * resources.configuration.fontScale).toInt()
        )

        val container = FrameLayout(this).apply {
            background = ColorDrawable(Color.parseColor("#060A0F"))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                dp(navHeightDp)
            )
        }

        // Subtle 1dp top separator line
        container.addView(View(this).apply {
            background = ColorDrawable(Color.parseColor(CLR_BORDER))
            layoutParams = FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                dp(1),
                Gravity.TOP
            )
        })

        // Subtle active top-bar glow indicator
        navIndicator = View(this).apply {
            background = surfaceBg(CLR_GREEN, 99)
            alpha = 0f
            layoutParams = FrameLayout.LayoutParams(dp(32), dp(2), Gravity.TOP)
        }
        container.addView(navIndicator)

        navPillBox = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            val sidePad = getResponsiveSidePaddingDp()
            setPadding(dp(sidePad), dp(4), dp(sidePad), dp(4))
            layoutParams = FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.MATCH_PARENT,
                Gravity.CENTER_VERTICAL
            )
        }

        data class NavItem(val iconType: String, val label: String, val tab: String)
        val items = listOf(
            NavItem("NAV_HOME", "Home", "HOME"),
            NavItem("NAV_TASKS", "Tasks", "CHALLENGES"),
            NavItem("NAV_REWARDS", "Rewards", "REWARDS"),
            NavItem("NAV_DEVICES", "Devices", "DEVICES"),
            NavItem("NAV_SETTINGS", "Settings", "PROFILE")
        )

        items.forEach { item ->
            val btn = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                gravity = Gravity.CENTER
                setPadding(dp(4), dp(4), dp(4), dp(4))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.MATCH_PARENT, 1f)
                tag = false
            }
            val iconSz = if (isTablet) 22 else 20
            val iconView = VectorIconView(this, item.iconType, CLR_TEXT_DIM, 1.8f).apply {
                layoutParams = LinearLayout.LayoutParams(dp(iconSz), dp(iconSz)).apply {
                    bottomMargin = dp(3)
                }
            }
            val labelTv = TextView(this).apply {
                text = item.label
                textSize = if (isTablet) 11.5f else 10.5f
                gravity = Gravity.CENTER
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
                maxLines = 1
                ellipsize = TextUtils.TruncateAt.END
            }
            btn.addView(iconView)
            btn.addView(labelTv)
            btn.applySpringTouch(scaleDown = 0.92f) {
                if (isSchedulePendingRestricted) {
                    Toast.makeText(this@MainActivity, "Access restricted. You missed the 10:00 AM deadline. Complete and confirm today's schedule to restore access.", Toast.LENGTH_LONG).show()
                    return@applySpringTouch
                }
                if (activeTab != item.tab) {
                    dispatchStrictBotEvent("NAVIGATE_SECTION")
                }
                activeTab = item.tab
                refreshUi()
            }
            navBtns.add(btn)
            navPillBox.addView(btn)
        }

        container.addView(navPillBox)
        return container
    }

