    private fun updateNavStyle() {
        val tabOrder = listOf("HOME", "CHALLENGES", "REWARDS", "DEVICES", "PROFILE")
        val effectiveTab = when (activeTab) {
            "HOME" -> "HOME"
            "CHALLENGES" -> "CHALLENGES"
            "REWARDS" -> "REWARDS"
            "DEVICES" -> "DEVICES"
            "PROFILE", "ADMIN" -> "PROFILE"
            "TRANSACTIONS", "HISTORY" -> "HOME"
            else -> "HOME"
        }
        val activeIdx = tabOrder.indexOf(effectiveTab)
        navBtns.forEachIndexed { i, btn ->
            val isActive = i == activeIdx
            val iconView = btn.getChildAt(0) as? VectorIconView
            val labelTv = btn.getChildAt(1) as? TextView
            val tint = if (isActive) CLR_GREEN else CLR_TEXT_DIM
            iconView?.setTint(tint)
            labelTv?.setTextColor(Color.parseColor(tint))
            labelTv?.setTypeface(
                manropeTypeface,
                if (isActive) Typeface.BOLD else Typeface.NORMAL
            )
            val wasActive = btn.tag == true
            btn.tag = isActive
            if (isActive && !wasActive) {
                btn.animate().cancel()
                btn.scaleX = 0.94f
                btn.scaleY = 0.94f
                btn.animate().scaleX(1f).scaleY(1f).setDuration(DUR_SPRING)
                    .setInterpolator(OvershootInterpolator(1.25f)).start()
            }
        }
    }

