    // ════════════════════════════════════════════════════════
    // LIVE CLOCK
    // ════════════════════════════════════════════════════════

    private fun startLiveClock() {
        clockRunnable?.let { uiHandler.removeCallbacks(it) }
        if (!screenResumed) return
        clockRunnable = object : Runnable {
            override fun run() {
                if (!screenResumed || isDestroyed) return
                updateClockViews()
                uiHandler.postDelayed(this, 1000L)
            }
        }
        uiHandler.post(clockRunnable!!)
    }

    private var lastObservedDate = ""
    private var lastRenderedTab = ""
    private var lastObservedWindowState: String? = null
    private var lastObservedWindowActivityId: String? = null
    private var lastObservedGymQaState: String? = null
    private var lastObservedTravelQaState: String? = null
    private val clockCalendar by lazy {
        Calendar.getInstance(java.util.TimeZone.getTimeZone(liveTimezone))
    }
    private var lastClockMinute = -1
    private var lastClockHour = -1
    private var lastClockAmPm = ""
    private var accInterruptionCountdownTv: TextView? = null
    private var accInterruptionSubtitleTv: TextView? = null
    private var accInterruptionTelemetryTv: TextView? = null
    private var lastAccCheckMs = 0L

    private fun updateClockViews() {
        requestLiveSnapshot()
        val nowMs = db.authoritativeNowMs()
        clockCalendar.timeInMillis = nowMs
        val h12 = clockCalendar.get(Calendar.HOUR).let { if (it == 0) 12 else it }
        val m = clockCalendar.get(Calendar.MINUTE)
        val s = clockCalendar.get(Calendar.SECOND)
        val amPm = if (clockCalendar.get(Calendar.AM_PM) == Calendar.AM) "AM" else "PM"
        val time12WithSec = String.format(Locale.US, "%d:%02d:%02d %s", h12, m, s, amPm)
        headerClockPill?.text = "• $time12WithSec"

        if (m != lastClockMinute || h12 != lastClockHour || amPm != lastClockAmPm) {
            lastClockMinute = m
            lastClockHour = h12
            lastClockAmPm = amPm
            val compactUi = isCompactPhoneLayout()
            val time12Display = if (compactUi) {
                String.format(Locale.US, "%d:%02d %s", h12, m, amPm)
            } else {
                time12WithSec
            }
            heroTimePill?.text = time12Display
            telemetryTimeLabel?.text = time12Display
            telemetry24hLabel?.text = time12Display
            nextHourlyNowLabel?.text = "NOW: $time12Display"

            if (::clockHourLabel.isInitialized) {
                val hStr = h12.toString().padStart(2, '0')
                val mStr = m.toString().padStart(2, '0')
                if (clockHourLabel.text != hStr) {
                    clockHourLabel.text = hStr
                }
                if (clockMinLabel.text != mStr) {
                    clockMinLabel.text = mStr
                }
                clockAmPmLabel.text = amPm
            }
        }
        updateCountdownViews()
        val countdownTv = accInterruptionCountdownTv
        if (countdownTv != null) {
            val uiStatus = AccessibilityGraceManager.getUiStatus(this)
            if (uiStatus.isInterrupted) {
                val remSec = (uiStatus.remainingGraceMs / 1000).coerceAtLeast(0)
                val timeStr = if (remSec > 0) {
                    val mm = remSec / 60
                    val ss = remSec % 60
                    String.format(Locale.US, "%02d:%02d", mm, ss)
                } else {
                    val overdueSec = uiStatus.overdueSeconds
                    val mm = overdueSec / 60
                    val ss = overdueSec % 60
                    String.format(Locale.US, "-%02d:%02d", mm, ss)
                }
                if (countdownTv.text != timeStr) {
                    countdownTv.text = timeStr
                }
                countdownTv.setTextColor(if (remSec > 0) Color.parseColor("#FFAA00") else Color.parseColor("#FF4444"))
                val subTv = accInterruptionSubtitleTv
                if (subTv != null) {
                    val subText = if (remSec > 0) {
                        val deadlineCal = Calendar.getInstance().apply { timeInMillis = uiStatus.graceDeadlineWallMs }
                        val deadlineStr = android.text.format.DateFormat.format("hh:mm:ss a", deadlineCal).toString()
                        "Grace period active — deadline: $deadlineStr"
                    } else {
                        val overdueSec = uiStatus.overdueSeconds
                        val overdueMm = overdueSec / 60
                        val overdueSs = overdueSec % 60
                        val overdueFmt = String.format(Locale.US, "-%02d:%02d", overdueMm, overdueSs)
                        "Grace expired — $overdueFmt overdue • Penalty: ${uiStatus.recordedPenaltyPoints} pt(s)"
                    }
                    if (subTv.text != subText) {
                        subTv.text = subText
                    }
                }
                val telemTv = accInterruptionTelemetryTv
                if (telemTv != null) {
                    val usageMinutes = (uiStatus.confirmedUsageDurationMs / 60000).toInt()
                    val usageSecs = ((uiStatus.confirmedUsageDurationMs % 60000) / 1000).toInt()
                    val telemText = "State: ${uiStatus.stateCode} • Confirmed restricted usage: ${usageMinutes}m ${usageSecs}s • Penalty: ${uiStatus.recordedPenaltyPoints} pts"
                    if (telemTv.text != telemText) {
                        telemTv.text = telemText
                    }
                }
            } else {
                refreshUi()
            }
        } else if (activeTab == "HOME" && nowMs - lastAccCheckMs >= 2000L) {
            lastAccCheckMs = nowMs
            val uiStatus = AccessibilityGraceManager.checkAccessibilityState(this)
            if (uiStatus.isInterrupted) {
                refreshUi()
            }
        }
    }

    /** Only one database batch can run; the one-second clock renders cached deadlines. */
    private fun requestLiveSnapshot() {
        if (!screenResumed || isDestroyed || liveSnapshotInFlight) return
        val elapsed = SystemClock.elapsedRealtime()
        val now = db.authoritativeNowMs()
        val countdown = liveCountdown
        val atBoundary = countdown != null && (
            (countdown.hasActiveWindow && liveWindowEndMs != Long.MIN_VALUE && now >= liveWindowEndMs) ||
            (!countdown.hasActiveWindow && liveWindowStartMs != Long.MIN_VALUE && now >= liveWindowStartMs))
        if (!atBoundary && liveSnapshotAt != 0L && elapsed - liveSnapshotAt < MonitoringWorkPolicy.UI_SNAPSHOT_INTERVAL_MS) return
        liveSnapshotInFlight = true
        val generation = liveSnapshotGeneration
        val devMode = isDevMode
        liveStateWorker.execute {
            try {
                val date = db.nowDate()
                if (lastObservedDate.isNotEmpty() && date != lastObservedDate) db.ensureDay(date, devMode)
                val timezone = db.scheduleTimezone()
                val next = db.getCurrentCountdownState(date, setOf("HOURLY"))
                val start = next.windowStart?.let { db.parseIsoToMs(it) } ?: Long.MIN_VALUE
                val end = next.windowEnd?.let { db.parseIsoToMs(it) } ?: Long.MIN_VALUE
                val pending = db.getPendingNotifications(date)
                // Notifications consumed by the database must still be delivered if the screen pauses.
                for ((i, n) in pending.withIndex()) {
                    val message = n.optString("message")
                    if (message.isNotEmpty()) WakeUpAlarmReceiver.postDisciplineNotification(
                        applicationContext, 4000 + i, n.optString("title", "STRICTRECORDS"), message, "ALERT")
                }
                val now = db.authoritativeNowMs()
                val currentGymQaState = runCatching {
                    val gymOccurrences = db.getDailyActivities(date).filter { it.type == "GYM" }
                    val gymAct = gymOccurrences.firstOrNull()
                    val gymDone = gymOccurrences.any { it.status in listOf("VERIFIED", "COMPLETED", "SUBMITTED", "SKIPPED", "VALIDATING") }
                    if (gymDone || gymAct == null) "DONE"
                    else {
                        val sMs = db.parseIsoToMs(gymAct.windowStart)
                        val eMs = db.parseIsoToMs(gymAct.windowEnd)
                        GymWindowRules.state(now, sMs, eMs)
                    }
                }.getOrDefault("UPCOMING")

                val currentTravelQaState = runCatching {
                    val isTravelBooked = db.isTravelPrebooked(date)
                    val travelOccurrences = db.getDailyActivities(date).filter { it.type == "TRAVEL" }
                    val travelAct = travelOccurrences.firstOrNull()
                    val travelDone = travelOccurrences.any { it.status in listOf("VERIFIED", "COMPLETED", "SUBMITTED", "VALIDATING", "PENDING_SYNC") }
                    if (!isTravelBooked || travelDone || travelAct == null) "DONE"
                    else {
                        val details = runCatching { JSONObject(travelAct.detailsJson) }.getOrNull()
                        val proofStartMs = details?.optLong("proof_window_start_ms", 0L).takeIf { (it ?: 0L) > 0L }
                            ?: details?.optLong("travel_end_ms", 0L).takeIf { (it ?: 0L) > 0L }
                            ?: db.parseIsoToMs(travelAct.windowStart)
                        val proofEndMs = details?.optLong("proof_window_end_ms", 0L).takeIf { (it ?: 0L) > 0L }
                            ?: db.parseIsoToMs(travelAct.windowEnd)
                        TravelBookingRules.state(now, proofStartMs, proofEndMs)
                    }
                }.getOrDefault("UPCOMING")

                uiHandler.post {
                    liveSnapshotInFlight = false
                    if (isDestroyed || generation != liveSnapshotGeneration) { requestLiveSnapshot(); return@post }
                    val dayChanged = lastObservedDate.isNotEmpty() && lastObservedDate != date
                    lastObservedDate = date
                    liveTimezone = timezone
                    runCatching { clockCalendar.timeZone = java.util.TimeZone.getTimeZone(timezone) }
                    liveCountdown = next
                    liveWindowStartMs = start
                    liveWindowEndMs = end
                    liveGymQaState = currentGymQaState
                    liveTravelQaState = currentTravelQaState
                    liveSnapshotAt = elapsed
                    if (screenResumed) {
                        for (n in pending) n.optString("message").takeIf { it.isNotEmpty() }?.let { triggerBotMessage(it, "ATTENTION") }
                        updateCountdownViews()
                        if (dayChanged) refreshUi()
                    }
                }
            } catch (error: Exception) {
                Log.w("StrictRecords", "Live state: ${error.javaClass.simpleName}")
                uiHandler.post { liveSnapshotInFlight = false; liveSnapshotAt = elapsed }
            }
        }
    }

    private fun updateCountdownViews() {
        if (isUpdatingCountdownViews) return
        isUpdatingCountdownViews = true
        try {
            val snapshot = liveCountdown ?: return
            val now = db.authoritativeNowMs()
            val remaining = if (liveWindowEndMs != Long.MIN_VALUE) MonitoringWorkPolicy.secondsUntil(liveWindowEndMs, now) else snapshot.secondsRemaining
            val until = if (liveWindowStartMs != Long.MIN_VALUE) MonitoringWorkPolicy.secondsUntil(liveWindowStartMs, now) else snapshot.secondsUntilOpen
            val countdown = snapshot.copy(secondsRemaining = if (snapshot.hasActiveWindow || snapshot.state == "BLOCKED_WAKEUP") remaining else 0L,
                secondsUntilOpen = if (snapshot.hasActiveWindow) 0L else until,
                isWarning = snapshot.hasActiveWindow && remaining <= 120L)

            val currentGymQaState = liveGymQaState
            val currentTravelQaState = liveTravelQaState

            val hourlyChanged = lastObservedWindowState != null && (lastObservedWindowState != countdown.state || lastObservedWindowActivityId != countdown.activityId)
            val gymChanged = lastObservedGymQaState != null && lastObservedGymQaState != currentGymQaState
            val travelChanged = lastObservedTravelQaState != null && lastObservedTravelQaState != currentTravelQaState

            // Update observed state tracking BEFORE invoking refreshUi to prevent recursive cycles
            lastObservedWindowState = countdown.state
            lastObservedWindowActivityId = countdown.activityId
            lastObservedGymQaState = currentGymQaState
            lastObservedTravelQaState = currentTravelQaState

            if (hourlyChanged || gymChanged || travelChanged) {
                refreshUi()
            }

        val isWakeUpWindow = countdown.type.equals("WAKE_UP", ignoreCase = true) ||
            countdown.activityId?.contains("WAKEUP", ignoreCase = true) == true
        val rangeStart = countdown.windowStart?.let { windowClock12h(it) }.orEmpty()
        val rangeEnd = countdown.windowEnd?.let { windowClock12h(it) }.orEmpty()
        if (rangeStart.isNotBlank() && rangeEnd.isNotBlank()) homeWindowRangeLabel?.text = "$rangeStart – $rangeEnd"
        val pts = if (countdown.points > 0) countdown.points else if (isWakeUpWindow) 35 else 8
        if (countdown.hasActiveWindow) {
            val remSec = countdown.secondsRemaining
            val mm = remSec / 60
            val ss = remSec % 60
            val timeStr = String.format(Locale.US, "%02d:%02d remaining", mm, ss)
            windowCountdownLabel?.text = timeStr

            when (countdown.state) {
                "SUBMITTED", "VALIDATING", "AI_PROVISIONAL", "PENDING_SYNC" -> {
                    windowCountdownLabel?.setTextColor(Color.parseColor(CLR_AMBER))
                    windowStatusBadge?.text = if (isWakeUpWindow) "☀️ WAKE-UP SUBMITTED — REVIEW PENDING" else "⏳ SUBMITTED — AI REVIEW PENDING"
                    windowStatusBadge?.setTextColor(Color.parseColor(CLR_AMBER))
                    windowTitleLabel?.text = (countdown.title ?: "Hourly Checkpoint") + "\nSubmitted — AI review pending ($timeStr until window closes)"
                    windowActionBtn?.visibility = View.VISIBLE
                    windowActionBtn?.text = "⏳ REVIEW PENDING"
                    windowActionBtn?.background = surfaceBg(CLR_AMBER, 12)
                    windowActionBtn?.setTextColor(Color.parseColor("#070A0C"))

                    homeWindowOpensInLabel?.text = "AI REVIEW"
                    homeWindowCountdownLabel?.text = String.format(Locale.US, "%02d:%02d", mm, ss)
                    homeWindowCountdownLabel?.setTextColor(Color.parseColor(CLR_AMBER))
                    homeWindowActionBtn?.text = "⏳ Review Pending"
                    homeWindowActionBtn?.background = surfaceBg(CLR_AMBER, 10)
                    homeWindowActionBtn?.visibility = View.VISIBLE
                }
                "VERIFIED", "APPROVED", "COMPLETED" -> {
                    windowCountdownLabel?.setTextColor(Color.parseColor(CLR_GREEN))
                    windowStatusBadge?.text = if (isWakeUpWindow) "✅ WAKE-UP VERIFIED (+$pts PTS)" else "✅ EVIDENCE APPROVED (+$pts PTS)"
                    windowStatusBadge?.setTextColor(Color.parseColor(CLR_GREEN))
                    windowTitleLabel?.text = (countdown.title ?: "Hourly Checkpoint") + "\nVerified & Approved! Window closes in $timeStr"
                    windowActionBtn?.visibility = View.VISIBLE
                    windowActionBtn?.text = "✅ APPROVED (+$pts PTS)"
                    windowActionBtn?.background = surfaceBg(CLR_GREEN, 12)
                    windowActionBtn?.setTextColor(Color.parseColor("#070A0C"))

                    homeWindowOpensInLabel?.text = "VERIFIED"
                    homeWindowCountdownLabel?.text = String.format(Locale.US, "%02d:%02d", mm, ss)
                    homeWindowCountdownLabel?.setTextColor(Color.parseColor(CLR_GREEN))
                    homeWindowActionBtn?.text = "✅ Verified"
                    homeWindowActionBtn?.background = surfaceBg(CLR_GREEN, 10)
                    homeWindowActionBtn?.visibility = View.VISIBLE
                }
                "REJECTED", "REJECTED_LATE" -> {
                    val isLocked = !countdown.submissionEligible || countdown.points == 0
                    val reasonStr = cleanUserFacingText(countdown.rejectionReason?.takeIf { it.isNotBlank() } ?: "Duplicate evidence detected")
                    windowCountdownLabel?.setTextColor(Color.parseColor(CLR_RED))
                    windowStatusBadge?.text = if (isLocked) "❌ PROOF REJECTED • LOCKED" else "❌ SUBMISSION REJECTED"
                    windowStatusBadge?.setTextColor(Color.parseColor(CLR_RED))
                    windowTitleLabel?.text = (countdown.title ?: "Hourly Checkpoint") + if (isLocked) {
                        "\nRejected & Locked (0 pts): $reasonStr"
                    } else {
                        "\nRejected: $reasonStr. Resubmit before window closes in $timeStr"
                    }
                    windowActionBtn?.visibility = View.VISIBLE
                    windowActionBtn?.text = if (isLocked) "❌ REJECTED (0 PTS)" else "⚠️ RESUBMIT PROOF"
                    windowActionBtn?.background = surfaceBg(CLR_RED, 12)
                    windowActionBtn?.setTextColor(Color.WHITE)

                    homeWindowOpensInLabel?.text = if (isLocked) "REJECTED • LOCKED" else "REJECTED"
                    homeWindowCountdownLabel?.text = String.format(Locale.US, "%02d:%02d", mm, ss)
                    homeWindowCountdownLabel?.setTextColor(Color.parseColor(CLR_RED))
                    homeWindowActionBtn?.text = if (isLocked) "❌ Rejected (0 pts)" else "⚠️ Resubmit"
                    homeWindowActionBtn?.background = surfaceBg(CLR_RED, 10)
                    homeWindowActionBtn?.visibility = View.VISIBLE
                }
                else -> {
                    windowCountdownLabel?.setTextColor(Color.parseColor(if (countdown.isWarning) CLR_RED else CLR_GREEN))
                    windowStatusBadge?.text = if (isWakeUpWindow) "☀️ WAKE-UP WINDOW OPEN" else if (countdown.isWarning) "⚠️ CLOSING SOON" else "🟢 WINDOW OPEN"
                    windowStatusBadge?.setTextColor(Color.parseColor(if (countdown.isWarning) CLR_RED else CLR_GREEN))
                    windowTitleLabel?.text = countdown.title ?: if (isWakeUpWindow) "Morning Wake-Up Verification" else "Activity Window Open"
                    windowActionBtn?.visibility = if (countdown.submissionEligible || !isWakeUpWindow) View.VISIBLE else View.GONE
                    windowActionBtn?.text = if (isWakeUpWindow) "☀️ VERIFY WAKE-UP (+$pts)" else "⚡ SUBMIT HOURLY PROOF (+$pts)"
                    windowActionBtn?.background = surfaceBg(CLR_GREEN, 12)
                    windowActionBtn?.setTextColor(Color.parseColor("#070A0C"))

                    homeWindowOpensInLabel?.text = if (countdown.submissionEligible || !isWakeUpWindow) "WINDOW OPEN" else "OPEN · APPROVAL REQUIRED"
                    homeWindowCountdownLabel?.text = String.format(Locale.US, "%02d:%02d", mm, ss)
                    homeWindowCountdownLabel?.setTextColor(Color.parseColor(if (countdown.isWarning) CLR_RED else CLR_GREEN))
                    homeWindowActionBtn?.text = if (isWakeUpWindow) "☀️ Verify Wake-Up" else "⚡ Submit Proof"
                    homeWindowActionBtn?.background = surfaceBg(CLR_GREEN, 10)
                    homeWindowActionBtn?.visibility = if (countdown.submissionEligible || !isWakeUpWindow) View.VISIBLE else View.GONE
                }
            }
        } else if (isWakeUpWindow && countdown.state == "BLOCKED_WAKEUP" && countdown.secondsRemaining > 0L) {
            val time = String.format(Locale.US, "%02d:%02d", countdown.secondsRemaining / 60, countdown.secondsRemaining % 60)
            windowCountdownLabel?.text = "$time until close"
            windowStatusBadge?.text = "WAKE-UP APPROVAL REQUIRED"
            windowTitleLabel?.text = countdown.title
            windowActionBtn?.visibility = View.GONE
            homeWindowOpensInLabel?.text = "PENDING"
            homeWindowCountdownLabel?.text = time
            homeWindowActionBtn?.visibility = View.GONE
        } else if (countdown.state == "ALL_CLOSED") {
            windowCountdownLabel?.text = "No more windows today"
            windowCountdownLabel?.setTextColor(Color.parseColor(CLR_GREEN))
            windowStatusBadge?.text = "WINDOWS CLOSED"
            windowStatusBadge?.setTextColor(Color.parseColor(CLR_GREEN))
            windowTitleLabel?.text = "See Tasks for submitted and missed checkpoints"
            windowActionBtn?.visibility = View.GONE

            homeWindowOpensInLabel?.text = "STATUS"
            homeWindowCountdownLabel?.text = "CLOSED"
            homeWindowCountdownLabel?.setTextColor(Color.parseColor(CLR_GREEN))
            homeWindowActionBtn?.visibility = View.GONE
        } else {
            val untilSec = countdown.secondsUntilOpen
            val hh = untilSec / 3600
            val mm = (untilSec % 3600) / 60
            val ss = untilSec % 60
            val timeStr = if (hh > 0) {
                String.format(Locale.US, "Opens in %02d:%02d:%02d", hh, mm, ss)
            } else {
                String.format(Locale.US, "Opens in %02d:%02d", mm, ss)
            }
            val timeStrShort = if (hh > 0) {
                String.format(Locale.US, "%02d:%02d:%02d", hh, mm, ss)
            } else {
                String.format(Locale.US, "%02d:%02d", mm, ss)
            }
            windowCountdownLabel?.text = timeStr
            windowCountdownLabel?.setTextColor(Color.parseColor(CLR_CYAN))
            windowStatusBadge?.text = if (isWakeUpWindow) "☀️ NEXT WAKE-UP CHECK" else "⏱ NEXT HOURLY CHECK"
            windowStatusBadge?.setTextColor(Color.parseColor(CLR_CYAN))
            val proofOpenLabel = if (!countdown.windowStart.isNullOrEmpty()) {
                val wsFormatted = windowClock12h(countdown.windowStart)
                (countdown.title ?: "Scheduled Checkpoint") + "\nProof window opens at $wsFormatted"
            } else {
                countdown.title ?: "Scheduled Checkpoint"
            }
            windowTitleLabel?.text = proofOpenLabel
            windowActionBtn?.visibility = View.GONE

            homeWindowOpensInLabel?.text = "OPENS IN"
            homeWindowCountdownLabel?.text = timeStrShort
            homeWindowCountdownLabel?.setTextColor(Color.parseColor(CLR_GREEN))
            homeWindowActionBtn?.visibility = View.GONE
        }
        } finally {
            isUpdatingCountdownViews = false
        }
    }

    private fun buildWindowCountdownCard(): LinearLayout {
        val card = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(14), dp(16), dp(14))
            background = surfaceBg(CLR_SURFACE, 20, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(14) }
        }

        val topRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(6)
            }
        }
        windowStatusBadge = TextView(this).apply {
            text = "⏱ ACTIVITY WINDOW"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_BLUE))
            letterSpacing = 0.08f
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        topRow.addView(windowStatusBadge)

        windowCountdownLabel = TextView(this).apply {
            text = "--:--"
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
        }
        topRow.addView(windowCountdownLabel)
        card.addView(topRow)

        windowTitleLabel = TextView(this).apply {
            text = "Loading schedule..."
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }
        card.addView(windowTitleLabel)

        windowActionBtn = TextView(this).apply {
            text = "⚡ SUBMIT CHECKPOINT"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            gravity = Gravity.CENTER
            setPadding(dp(14), dp(8), dp(14), dp(8))
            background = surfaceBg(CLR_BLUE, 12)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            applySpringTouch {
                haptic(1)
                val cd = db.getCurrentCountdownState(db.nowDate(), setOf("HOURLY"))
                val isWakeUp = cd.type.equals("WAKE_UP", ignoreCase = true) ||
                    cd.activityId?.contains("WAKEUP", ignoreCase = true) == true
                if (isWakeUp) {
                    showWakeUpVerificationDialog()
                    return@applySpringTouch
                }
                // Safety guard: block submission if proof window isn't actually open yet
                if (!cd.hasActiveWindow) {
                    val opensAt = if (!cd.windowStart.isNullOrEmpty()) {
                        " Opens at ${windowClock12h(cd.windowStart)}."
                    } else ""
                    android.widget.Toast.makeText(
                        this@MainActivity,
                        "Proof window not open yet.$opensAt",
                        android.widget.Toast.LENGTH_SHORT
                    ).show()
                    return@applySpringTouch
                }
                showHourlySubmissionDialog()
            }
        }
        card.addView(windowActionBtn)

        updateCountdownViews()
        return card
    }

    // ════════════════════════════════════════════════════════
    // STRICTBOT BREATH ANIMATION
    // ════════════════════════════════════════════════════════

    private fun startBotBreath() {
        botBreathRunnable?.let { uiHandler.removeCallbacks(it) }
        if (!screenResumed) return
        botBreathRunnable = object : Runnable {
            override fun run() {
                if (!screenResumed || isDestroyed) return
                if (::floatingBotOrb.isInitialized && floatingBotOrb.visibility == View.VISIBLE && floatingBotOrb.isAttachedToWindow) {
                    floatingBotOrb.animate().scaleX(1.08f).scaleY(1.08f)
                        .setDuration(1100L).withEndAction {
                            if (screenResumed && !isDestroyed && ::floatingBotOrb.isInitialized && floatingBotOrb.isAttachedToWindow) {
                                floatingBotOrb.animate().scaleX(1f).scaleY(1f)
                                    .setDuration(1100L).start()
                            }
                        }.start()
                }
                uiHandler.postDelayed(this, 3500L)
            }
        }
        uiHandler.postDelayed(botBreathRunnable!!, 2000L)
    }

    // ════════════════════════════════════════════════════════
    // FLOATING POINTS ANIMATION (+15 / -5 rising/falling)
    // ════════════════════════════════════════════════════════

    private fun showFloatingPoints(pts: Int, fromView: View? = null) {
        val positive = pts >= 0
        floatingPointsLabel.text = if (positive) "+$pts ⚡" else "$pts"
        floatingPointsLabel.setTextColor(Color.parseColor(if (positive) CLR_GREEN else CLR_RED))
        floatingPointsLabel.visibility = View.VISIBLE
        floatingPointsLabel.alpha = 1f
        floatingPointsLabel.translationY = 0f
        val targetY = if (positive) -dp(80).toFloat() else dp(60).toFloat()
        AnimatorSet().apply {
            playTogether(
                ObjectAnimator.ofFloat(floatingPointsLabel, "translationY", 0f, targetY),
                ObjectAnimator.ofFloat(floatingPointsLabel, "alpha", 1f, 0f).apply { startDelay = 350L }
            )
            setDuration(700L)
            interpolator = DecelerateInterpolator()
            addListener(object : AnimatorListenerAdapter() {
                override fun onAnimationEnd(a: Animator) {
                    floatingPointsLabel.visibility = View.GONE
                    floatingPointsLabel.translationY = 0f
                }
            })
            start()
        }
    }

    // ════════════════════════════════════════════════════════
    // REWARD UNLOCK ANIMATION
    // ════════════════════════════════════════════════════════

    private fun triggerRewardUnlockAnimation() {
        haptic(2)
        scoreArcView.triggerGlow()
        scoreStateLabel.apply {
            val originalText = text
            text = "🏆 REWARD UNLOCKED"
            setTextColor(Color.parseColor(CLR_AMBER))
            animate().scaleX(1.15f).scaleY(1.15f).setDuration(DUR_MED).withEndAction {
                animate().scaleX(1f).scaleY(1f).setDuration(DUR_SPRING)
                    .setInterpolator(OvershootInterpolator(2f)).start()
            }.start()
        }
        triggerBotMessage("You earned it. 🏆 Reward unlocked.", "CELEBRATING")
    }

    // ════════════════════════════════════════════════════════
    // REFRESH MAIN UI (SEAMLESS IN-PLACE UPDATES)
    // ════════════════════════════════════════════════════════

    internal fun refreshUi() {
        if (Looper.myLooper() != Looper.getMainLooper()) { uiHandler.post { refreshUi() }; return }
        refreshRequested = true
        liveSnapshotGeneration++
        liveSnapshotAt = 0L
        if (!screenResumed || refreshPosted || isDestroyed) return
        refreshPosted = true
        uiHandler.post {
            refreshPosted = false
            if (!screenResumed || isDestroyed || !refreshRequested) return@post
            refreshRequested = false
            try {
                renderCurrentUi()
            } catch (t: Throwable) {
                Log.e("MainActivity", "Error in renderCurrentUi: ${t.message}", t)
            }
        }
    }

    private fun renderCurrentUi() {
        val date = db.nowDate()
        val st = db.getDayState(date, isDevMode)
        val score = st.optInt("score", 0)
        val prevScore = lastScore
        val isSameTab = (lastRenderedTab == activeTab)
        val savedScrollY = if (::contentScroll.isInitialized) contentScroll.scrollY else 0
        lastRenderedTab = activeTab
        lastScore = score

        // Update floating score capsule
        headerScoreCapsule.text = "⚡ $score / 100"
        headerScoreCapsule.setTextColor(Color.parseColor(scoreColor(score)))

        // Sync dot color
        val synced = st.optString("sync_status", "").contains("SYNCED")
        if (::headerSyncDot.isInitialized) {
            headerSyncDot.background = surfaceBg(if (synced) CLR_GREEN else CLR_AMBER, 99)
        }

        // Update top header title, subtitle, and live streak pill
        headerTitleLabel?.text = when (activeTab) {
            "HOME" -> "DASHBOARD"
            "CHALLENGES" -> "SCHEDULE & TASKS"
            "REWARDS" -> "REWARDS & PRIVILEGES"
            "DEVICES" -> "DEVICE CENTER"
            "PROFILE" -> "SETTINGS & PROFILE"
            "ADMIN" -> "ADMIN CONSOLE"
            else -> "DASHBOARD"
        }
        headerSubLabel?.text = if (isAdminMode) "ADMIN ACTIVE" else if (isDevMode) "DEV ACTIVE" else "STRICT ACTIVE"
        headerStreakLabel?.text = "${st.optInt("streak_days", 0)}D"

        updateNavStyle()
        rootFrame.setBackgroundColor(Color.parseColor(CLR_BG))
        accInterruptionCountdownTv = null
        accInterruptionSubtitleTv = null
        accInterruptionTelemetryTv = null
        cachedHomeActivities = null
        contentContainer.removeAllViews()

        val sidePadDp = getResponsiveSidePaddingDp()
        contentContainer.setPadding(dp(sidePadDp), dp(6), dp(sidePadDp), dp(96))

        if (isSchedulePendingRestricted) {
            headerTitleLabel?.text = "SCHEDULE PENDING"
            headerSubLabel?.text = "DEADLINE OVERDUE"
            renderTodaySchedulePendingScreen()
            applyFrontendTypography(contentContainer)
            return
        }

        when (activeTab) {
            "HOME"                -> renderHomeTab(st, score)
            "CHALLENGES"          -> renderChallengesTab(st, score)
            "TIMELINE"            -> renderTimelineTab(st, score)
            "REWARDS"             -> renderRewardsTab(st, score)
            "DEVICES"             -> renderDevicesTab(st, score)
            "PROFILE"             -> renderProfileTab(st, score)
            "ADMIN"               -> renderAdminTab(st, score)
            "TRANSACTIONS", "HISTORY" -> renderTransactionsTab(st, score)
        }
        if (activeTab in setOf("HOME", "REWARDS")) {
            contentContainer.addView(buildViewportFillPanel(activeTab, st, score, cachedHomeActivities))
        }
        if (activeTab == "HOME") {
            val dashboardBugRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER
                setPadding(0, dp(10), 0, dp(14))
                applySpringTouch { showReportBugDialog() }
            }
            dashboardBugRow.addView(TextView(this).apply {
                text = "StrictRoutines • "
                textSize = 10.5f
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
            })
            dashboardBugRow.addView(TextView(this).apply {
                text = "Report Bug"
                textSize = 10.5f
                setTextColor(Color.parseColor(CLR_CYAN))
            })
            contentContainer.addView(dashboardBugRow)
        }
        applyFrontendTypography(contentContainer)

        // Detect score change for animations after views are attached
        if (prevScore >= 0 && score != prevScore) {
            val delta = score - prevScore
            val crossed80 = prevScore < 80 && score >= 80
            showFloatingPoints(delta)
            if (::scoreArcView.isInitialized) {
                scoreArcView.animateTo(score.toFloat()) {
                    if (crossed80) triggerRewardUnlockAnimation()
                }
                animateScoreLabelTo(prevScore, score)
            }
            haptic(if (delta > 0) 1 else 3)
        } else if (::scoreArcView.isInitialized) {
            scoreArcView.animProgress = score.toFloat()
            scoreArcView.targetProgress = score.toFloat()
            scoreArcView.invalidate()
        }

        if (isSameTab) {
            // Seamless in-place update: preserve scroll position and never flash alpha to 0
            contentContainer.alpha = 1f
            contentScroll.scrollTo(0, savedScrollY)
            contentScroll.post { contentScroll.scrollTo(0, savedScrollY) }
        } else {
            contentScroll.scrollTo(0, 0)
            contentContainer.alpha = 0f
            contentContainer.translationY = dp(8).toFloat()
            contentContainer.animate().cancel()
            contentContainer.animate().alpha(1f).translationY(0f).setDuration(DUR_MED)
                .setInterpolator(DecelerateInterpolator(1.35f)).start()
        }
        if (::strictBotChat.isInitialized) {
            val wake = db.getWakeUpFlowStatus(date, false)
            strictBotChat.onApplicationStateChanged("$date:$score:${st.optString("sync_status")}:${wake.optString("status")}:${wake.optBoolean("all_completed")}:${db.getDailyRoutineGate(date)}:${db.getConfigValue("last_sync_time", "")}")
        }
    }

    /**
     * A data-backed lower panel expands only into unused viewport space. Longer pages keep
     * their natural scroll height; short Home, Rewards, and Devices pages stay visually filled.
     */
    private fun buildViewportFillPanel(
        tab: String,
        st: JSONObject,
        score: Int,
        cachedActivities: List<DisciplineScoringRules.ScheduledActivityItem>? = null
    ): LinearLayout {
        val widthDp = currentWindowWidthDp()
        val isTablet = isWideLayout()
        val accent = when (tab) {
            "REWARDS" -> CLR_CYAN
            "DEVICES" -> CLR_GREEN
            else -> CLR_GREEN
        }
        val panel = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(if (isTablet) 20 else 16), dp(if (isTablet) 18 else 16), dp(if (isTablet) 20 else 16), dp(if (isTablet) 16 else 14))
            background = surfaceBg(CLR_SURFACE, 20, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                0,
                1f
            ).apply {
                topMargin = dp(10)
                bottomMargin = dp(6)
            }
        }

        val icon = when (tab) {
            "REWARDS" -> "NAV_REWARDS"
            "DEVICES" -> "NAV_DEVICES"
            else -> "NAV_HOME"
        }
        val intro = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT
            )
        }
        val iconBox = FrameLayout(this).apply {
            layoutParams = LinearLayout.LayoutParams(dp(42), dp(42)).apply { rightMargin = dp(12) }
            background = surfaceBg(CLR_ELEVATED, 13, accent, 1)
            addView(VectorIconView(this@MainActivity, icon, accent, 1.7f).apply {
                layoutParams = FrameLayout.LayoutParams(dp(20), dp(20), Gravity.CENTER)
            })
        }
        intro.addView(iconBox)
        val introCopy = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        introCopy.addView(TextView(this).apply {
            text = when (tab) {
                "REWARDS" -> "REWARD PATH"
                "DEVICES" -> "LIVE CONNECTION"
                else -> "UP NEXT"
            }
            textSize = 9.5f
            setTypeface(typeface, Typeface.BOLD)
            letterSpacing = 0.08f
            setTextColor(Color.parseColor(CLR_TEXT_DIM))
        })
        introCopy.addView(TextView(this).apply {
            text = when (tab) {
                "REWARDS" -> "Your next unlock"
                "DEVICES" -> "Device health"
                else -> "Today's next steps"
            }
            textSize = if (isTablet) 17f else 15f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { topMargin = dp(3) }
        })
        intro.addView(introCopy)
        panel.addView(intro)

        when (tab) {
            "HOME" -> {
                val activityList = cachedActivities ?: runCatching { db.getDailyActivities(db.nowDate()) }.getOrDefault(emptyList())
                val upcoming = activityList.filter { it.status.uppercase(Locale.US) in setOf("SCHEDULED", "UPCOMING", "NOTIFIED") }
                val verifiedCount = activityList.count {
                    it.status.uppercase(Locale.US) in setOf("VERIFIED", "COMPLETED")
                }
                panel.addView(TextView(this).apply {
                    text = if (upcoming.isNotEmpty()) {
                        "Your saved schedule is ready. The next checkpoint windows are listed here."
                    } else {
                        "No later checkpoint is currently scheduled. Your saved progress remains available in Tasks."
                    }
                    textSize = 11f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    layoutParams = LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT,
                        ViewGroup.LayoutParams.WRAP_CONTENT
                    ).apply { topMargin = dp(8) }
                })
                if (upcoming.isEmpty()) {
                    val progressRow = LinearLayout(this).apply {
                        orientation = LinearLayout.HORIZONTAL
                        gravity = Gravity.CENTER_VERTICAL
                        setPadding(dp(12), dp(11), dp(12), dp(11))
                        background = surfaceBg(CLR_ELEVATED, 13, CLR_BORDER, 1)
                        layoutParams = LinearLayout.LayoutParams(
                            ViewGroup.LayoutParams.MATCH_PARENT,
                            ViewGroup.LayoutParams.WRAP_CONTENT
                        ).apply { topMargin = dp(12) }
                    }
                    progressRow.addView(TextView(this).apply {
                        text = "$verifiedCount"
                        textSize = 23f
                        setTypeface(typeface, Typeface.BOLD)
                        setTextColor(Color.parseColor(CLR_GREEN))
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { rightMargin = dp(10) }
                    })
                    progressRow.addView(TextView(this).apply {
                        text = "verified checkpoints today"
                        textSize = 11f
                        setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    })
                    panel.addView(progressRow)
                } else {
                    val activity = upcoming.first()
                        val item = LinearLayout(this).apply {
                            orientation = LinearLayout.HORIZONTAL
                            gravity = Gravity.CENTER_VERTICAL
                            setPadding(dp(12), dp(10), dp(12), dp(10))
                            background = surfaceBg(CLR_ELEVATED, 13, CLR_BORDER, 1)
                            layoutParams = LinearLayout.LayoutParams(
                                ViewGroup.LayoutParams.MATCH_PARENT,
                                ViewGroup.LayoutParams.WRAP_CONTENT
                            ).apply { topMargin = dp(8) }
                        }
                        item.addView(View(this).apply {
                            background = surfaceBg(CLR_GREEN, 99)
                            layoutParams = LinearLayout.LayoutParams(dp(7), dp(7)).apply { rightMargin = dp(10) }
                        })
                        val copy = LinearLayout(this).apply {
                            orientation = LinearLayout.VERTICAL
                            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                        }
                        copy.addView(TextView(this).apply {
                            text = activity.title
                            textSize = 11.5f
                            setTypeface(typeface, Typeface.BOLD)
                            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                            maxLines = 1
                            ellipsize = TextUtils.TruncateAt.END
                        })
                        copy.addView(TextView(this).apply {
                            val start = windowClock12h(activity.windowStart)
                            val end = windowClock12h(activity.windowEnd)
                            text = if (start.isNotBlank() && end.isNotBlank()) "$start – $end" else "Scheduled checkpoint"
                            textSize = 10f
                            setTypeface(Typeface.MONOSPACE, Typeface.NORMAL)
                            tag = "telemetry_type"
                            setTextColor(Color.parseColor(CLR_TEXT_DIM))
                            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(3) }
                        })
                        item.addView(copy)
                        item.addView(designStatusPill("NEXT", CLR_GREEN))
                        panel.addView(item)
                    if (upcoming.size > 1) {
                        panel.addView(TextView(this).apply {
                            text = "+ ${upcoming.size - 1} more checkpoint${if (upcoming.size == 2) "" else "s"} scheduled today"
                            textSize = 10f
                            setTextColor(Color.parseColor(CLR_TEXT_DIM))
                            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                                topMargin = dp(6)
                            }
                        })
                    }
                }
            }
            "REWARDS" -> {
                val verifiedScore = st.optInt("verified_points", score).coerceAtMost(100)
                val currentStreak = st.optInt("streak_days", 0).coerceAtLeast(0)
                val configuredPrivileges = DisciplineScoringRules.CONFIGURED_RESTRICTED_APPS.distinctBy { it.displayName }.sortedBy { it.requiredScore }
                val remoteLocks = db.getRemoteAppLocks()
                val nextPrivilege = configuredPrivileges.firstOrNull { privilege ->
                    val unlocked = !DisciplineScoringRules.evaluateRestrictionDecision(
                        verifiedScore, privilege.packageName, appLocks = remoteLocks,
                        isEducationalUnlockActive = db.isEducationalUnlockActive()
                    ).isRestricted
                    !unlocked
                }
                val nextMilestone = listOf(7, 14, 30).firstOrNull { currentStreak < it }
                val pointsNeeded = nextPrivilege?.let { (it.requiredScore - verifiedScore).coerceAtLeast(0) }
                panel.addView(TextView(this).apply {
                    text = when {
                        nextPrivilege != null -> "$pointsNeeded verified points to reach ${nextPrivilege.displayName}."
                        nextMilestone != null -> "Keep your $currentStreak-day streak moving toward the $nextMilestone-day milestone."
                        else -> "All configured privilege thresholds and streak milestones are reached."
                    }
                    textSize = 11f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(8) }
                })
                if (nextPrivilege != null && pointsNeeded != null) {
                    panel.addView(ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal).apply {
                        max = nextPrivilege.requiredScore.coerceAtLeast(1)
                        progress = verifiedScore.coerceAtMost(max)
                        progressTintList = ColorStateList.valueOf(Color.parseColor(CLR_CYAN))
                        progressBackgroundTintList = ColorStateList.valueOf(Color.parseColor(CLR_ELEVATED))
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(7)).apply { topMargin = dp(15) }
                    })
                    val progressRow = LinearLayout(this).apply {
                        orientation = LinearLayout.HORIZONTAL
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(7) }
                    }
                    progressRow.addView(TextView(this).apply {
                        text = "$verifiedScore verified points"
                        textSize = 10f
                        setTextColor(Color.parseColor(CLR_TEXT_DIM))
                        layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                    })
                    progressRow.addView(TextView(this).apply {
                        text = "${nextPrivilege.requiredScore} needed"
                        textSize = 10f
                        setTypeface(typeface, Typeface.BOLD)
                        setTextColor(Color.parseColor(CLR_CYAN))
                    })
                    panel.addView(progressRow)
                } else {
                    panel.addView(TextView(this).apply {
                        text = "Current streak: $currentStreak days"
                        textSize = 13f
                        setTypeface(typeface, Typeface.BOLD)
                        setTextColor(Color.parseColor(CLR_GREEN))
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(12) }
                    })
                }
            }
            "DEVICES" -> {
                val registered = db.isDeviceRegistered()
                val registration = db.getDeviceRegistration()
                val pairingStatus = db.getConfigValue("pairing_status", if (registered) "REGISTERED" else "NOT_REGISTERED")
                val hostOnline = registered && pairingStatus.equals("ONLINE", ignoreCase = true)
                val networkReady = HardwareDeviceVerifier.isNetworkOrWifiAvailable(this)
                val pcName = registration?.optString("paired_pc_name")?.takeIf { it.isNotBlank() } ?: "Windows PC"
                val endpointRow = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.CENTER_VERTICAL
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(14) }
                }
                fun endpointCard(title: String, status: String, tint: String): LinearLayout = LinearLayout(this).apply {
                    orientation = LinearLayout.VERTICAL
                    setPadding(dp(12), dp(12), dp(12), dp(12))
                    background = surfaceBg(CLR_ELEVATED, 14, CLR_BORDER, 1)
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                    addView(TextView(this@MainActivity).apply {
                        text = title
                        textSize = 9f
                        setTypeface(typeface, Typeface.BOLD)
                        setTextColor(Color.parseColor(CLR_TEXT_DIM))
                    })
                    addView(TextView(this@MainActivity).apply {
                        text = status
                        textSize = 12f
                        setTypeface(typeface, Typeface.BOLD)
                        setTextColor(Color.parseColor(tint))
                        maxLines = 1
                        ellipsize = TextUtils.TruncateAt.END
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(5) }
                    })
                }
                endpointRow.addView(endpointCard(
                    "THIS DEVICE",
                    if (registered) "Registered" else "Not paired",
                    if (registered) CLR_GREEN else CLR_AMBER
                ))
                endpointRow.addView(View(this).apply {
                    background = surfaceBg(if (hostOnline && networkReady) CLR_GREEN else CLR_TEXT_DIM, 99)
                    layoutParams = LinearLayout.LayoutParams(dp(24), dp(3)).apply { leftMargin = dp(8); rightMargin = dp(8) }
                })
                endpointRow.addView(endpointCard(
                    "WINDOWS PC",
                    if (hostOnline) pcName else if (registered) "Offline" else "Not paired",
                    if (hostOnline) CLR_GREEN else CLR_TEXT_DIM
                ))
                panel.addView(endpointRow)

                val networkRow = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.CENTER_VERTICAL
                    setPadding(dp(12), dp(10), dp(12), dp(10))
                    background = surfaceBg(CLR_ELEVATED, 13, CLR_BORDER, 1)
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(8) }
                }
                networkRow.addView(TextView(this).apply {
                    text = "Network"
                    textSize = 10.5f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                })
                networkRow.addView(TextView(this).apply {
                    text = if (networkReady) "Connected" else "Unavailable"
                    textSize = 10.5f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(if (networkReady) CLR_CYAN else CLR_AMBER))
                })
                panel.addView(networkRow)
                panel.addView(TextView(this).apply {
                    text = "Last confirmed sync: ${db.getConfigValue("last_sync_time", "Never")}"
                    textSize = 10f
                    setTextColor(Color.parseColor(CLR_TEXT_DIM))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(8) }
                })
            }
        }

        panel.addView(View(this).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f)
        })
        val actionLabel = when (tab) {
            "REWARDS" -> "VIEW DAILY CHECKPOINTS"
            "DEVICES" -> "SYNC DEVICES"
            else -> "OPEN TODAY'S SCHEDULE"
        }
        val action = makeSecondaryButton(actionLabel, accent) {
            when (tab) {
                "DEVICES" -> triggerServerSync()
                else -> {
                    activeTab = "CHALLENGES"
                    refreshUi()
                }
            }
        }.apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        panel.addView(action)
        return panel
    }

    private fun animateScoreLabelTo(from: Int, to: Int) {
        if (!::scoreBigLabel.isInitialized) return
        ValueAnimator.ofInt(from, to).apply {
            duration = DUR_HERO
            interpolator = DecelerateInterpolator(1.8f)
            addUpdateListener { scoreBigLabel.text = (it.animatedValue as Int).toString() }
            start()
        }
    }

    // ════════════════════════════════════════════════════════
    // SKELETON LOADING ROW
    // ════════════════════════════════════════════════════════

    private fun makeSkeletonRow(heightDp: Int = 20, widthFraction: Float = 1f): View = View(this).apply {
        background = surfaceBg(CLR_SURFACE, 8)
        layoutParams = LinearLayout.LayoutParams(0, dp(heightDp), widthFraction).apply {
            topMargin = dp(8); bottomMargin = dp(4)
        }
        // shimmer alpha pulse
        val shimmer = ObjectAnimator.ofFloat(this, "alpha", 0.3f, 0.8f).apply {
            duration = 900L; repeatMode = ValueAnimator.REVERSE; repeatCount = ValueAnimator.INFINITE
        }
        shimmer.start()
    }

    // ════════════════════════════════════════════════════════
    // SECTION HEADING
    // ════════════════════════════════════════════════════════

    private fun sectionHeading(title: String, actionLabel: String? = null, onAction: (() -> Unit)? = null): LinearLayout =
        LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            val topM = dp(if (isWideLayout()) 14 else 9)
            val botM = dp(if (isWideLayout()) 8 else 5)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { topMargin = topM; bottomMargin = botM }

            addView(TextView(this@MainActivity).apply {
                text = title
                textSize = if (isWideLayout()) 13f else 11.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                letterSpacing = 0.08f
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            })
            if (actionLabel != null && onAction != null) {
                addView(TextView(this@MainActivity).apply {
                    text = actionLabel
                    textSize = if (isWideLayout()) 11f else 10f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(CLR_CYAN))
                    applySpringTouch { onAction() }
                })
            }
        }

    private fun designCard(
        orientation: Int = LinearLayout.VERTICAL,
        paddingDp: Int = if (isWideLayout()) 14 else 11,
        cornerDp: Int = 16,
        strokeHex: String = CLR_BORDER
    ): LinearLayout = LinearLayout(this).apply {
        this.orientation = orientation
        setPadding(dp(paddingDp), dp(paddingDp), dp(paddingDp), dp(paddingDp))
        background = surfaceBg(CLR_SURFACE, cornerDp, strokeHex, 1)
    }

    private fun designStatusPill(label: String, tintHex: String): TextView = TextView(this).apply {
        text = label
        textSize = 9.5f
        setTypeface(typeface, Typeface.BOLD)
        setTextColor(Color.parseColor(tintHex))
        setPadding(dp(9), dp(5), dp(9), dp(5))
        background = surfaceBg(CLR_ELEVATED, 99, tintHex, 1)
        gravity = Gravity.CENTER
    }

    private fun addScoreDeductionSummary(card: LinearLayout, state: JSONObject) {
        val deductions = state.optInt("penalty_points", 0)
        if (deductions <= 0) return
        val gymDeduction = state.optInt("gym_penalty_points", 0)
        card.addView(TextView(this).apply {
            text = "Deductions today: −$deductions" + if (gymDeduction > 0) " · Gym: −$gymDeduction" else ""
            textSize = 10f
            setTextColor(Color.parseColor(CLR_RED))
            maxLines = 2
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(6)
            }
        })
    }

    private fun windowClock(value: String): String =
        runCatching { value.substring(11, 16) }.getOrDefault("")

    private fun windowClock12h(value: String): String =
        ScheduleClock.display(db.parseIsoToMs(value), db.scheduleTimezone())

    // ════════════════════════════════════════════════════════
    // HOME TAB — Reference Image B & Responsive Tablet Layout
    // ════════════════════════════════════════════════════════

    
    private fun buildStrictSessionLiveCard(): View? {
        val isMonitoring = AndroidStrictMonitoringService.isServiceRunning
        val sessionId = AndroidStrictMonitoringService.currentSessionId
        val monitorState = AndroidStrictMonitoringService.currentMonitoringState
        val hasUsage = StrictSessionUsageMonitor.hasUsagePermission(this)

        if (!isMonitoring && monitorState in setOf(AndroidStrictMonitoringService.STATE_ANDROID_NOT_JOINED, AndroidStrictMonitoringService.STATE_ANDROID_SESSION_COMPLETED, "○ IDLE", "")) {
            return null
        }

        val card = designCard(paddingDp = 14, cornerDp = 18).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(12)
            }
            background = surfaceBg("#0B1C28", 18, if (hasUsage) CLR_CYAN else CLR_AMBER, 1)
        }

        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        }
        headerRow.addView(TextView(this).apply {
            text = "🔒 ACTIVE STRICT SESSION"
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (hasUsage) CLR_CYAN else CLR_AMBER))
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        })
        headerRow.addView(TextView(this).apply {
            text = when (monitorState) {
                AndroidStrictMonitoringService.STATE_ANDROID_MONITORING_ACTIVE -> "● MONITORING ACTIVE"
                AndroidStrictMonitoringService.STATE_ANDROID_SCREEN_LOCKED,
                AndroidStrictMonitoringService.STATE_ANDROID_LOCKED_SLEEPING -> "● LOCKED / SLEEPING"
                AndroidStrictMonitoringService.STATE_ANDROID_PERMISSION_REQUIRED -> "⚠️ PERMISSION REQUIRED"
                AndroidStrictMonitoringService.STATE_ANDROID_APP_USAGE_DETECTED -> "⚠️ USAGE DETECTED"
                else -> "● $monitorState"
            }
            textSize = 10.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(
                when (monitorState) {
                    AndroidStrictMonitoringService.STATE_ANDROID_MONITORING_ACTIVE -> CLR_GREEN
                    AndroidStrictMonitoringService.STATE_ANDROID_SCREEN_LOCKED,
                    AndroidStrictMonitoringService.STATE_ANDROID_LOCKED_SLEEPING -> CLR_CYAN
                    AndroidStrictMonitoringService.STATE_ANDROID_PERMISSION_REQUIRED -> CLR_AMBER
                    AndroidStrictMonitoringService.STATE_ANDROID_APP_USAGE_DETECTED -> CLR_RED
                    else -> CLR_TEXT_DIM
                }
            ))
        })
        card.addView(headerRow)

        card.addView(TextView(this).apply {
            text = "Session ID: ${if (sessionId.isNotBlank()) sessionId else "Active"}"
            textSize = 11f
            setTypeface(Typeface.MONOSPACE, Typeface.NORMAL)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        })

        val phase = AndroidStrictMonitoringService.currentSessionPhase
        val phoneAllowed = AndroidStrictMonitoringService.isPhoneUsageAllowed

        val phaseRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        }
        phaseRow.addView(TextView(this).apply {
            text = "PHASE: $phase"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(when (phase) {
                "FOCUS_ACTIVE" -> CLR_CYAN
                "FOCUS_BUFFER" -> CLR_AMBER
                "PROOF_SUBMISSION_OPEN" -> CLR_GREEN
                "SESSION_PAUSED" -> CLR_AMBER
                else -> CLR_TEXT_PRIMARY
            }))
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        })
        phaseRow.addView(TextView(this).apply {
            text = if (phoneAllowed) "🟢 PHONE ALLOWED" else "🔴 RESTRICTED"
            textSize = 10.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (phoneAllowed) CLR_GREEN else CLR_RED))
        })
        card.addView(phaseRow)

        card.addView(TextView(this).apply {
            text = "Windows EXE is authoritative controller. Android companion is actively monitoring foreground apps and reporting every 30 seconds."
            textSize = 10.5f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
        })

        if (!hasUsage) {
            card.addView(TextView(this).apply {
                text = "⚠️ PACKAGE_USAGE_STATS permission is required for Strict Session monitoring to function."
                textSize = 11f
                setTextColor(Color.parseColor(CLR_AMBER))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
            })
            card.addView(makeSecondaryButton("⚙️ GRANT USAGE ACCESS", CLR_AMBER) {
                StrictSessionUsageMonitor.openUsageAccessSettings(this@MainActivity)
            })
        } else {
            card.addView(TextView(this).apply {
                text = "✓ Usage Access Permission Granted (UsageStats monitoring active)"
                textSize = 10f
                setTextColor(Color.parseColor(CLR_GREEN))
            })
        }

        return card
    }

private fun renderHomeTab(st: org.json.JSONObject, score: Int) {
        val camOk   = st.optInt("wakeup_camera") == 1
        val btOk    = st.optInt("wakeup_bt") == 1
        val trkOk   = st.optInt("wakeup_track") == 1
        val bathOk  = st.optString("bath_status").startsWith("BATH COMPLETE")
        val gymOk   = st.optString("gym_status").startsWith("GYM COMPLETE")
        val hourlyN = st.optInt("hourly_completed", 0)
        val cal = Calendar.getInstance(java.util.TimeZone.getTimeZone(db.scheduleTimezone())).apply { timeInMillis = db.authoritativeNowMs() }

        val greetHour = cal.get(Calendar.HOUR_OF_DAY)
        val greeting = when {
            greetHour < 12 -> "Good morning"
            greetHour < 17 -> "Good afternoon"
            greetHour < 21 -> "Good evening"
            else -> "Good night"
        }
        val dateBadgeStr = android.text.format.DateFormat.format("EEE, MMM dd", cal).toString()
        val h12 = cal.get(Calendar.HOUR).let { if (it == 0) 12 else it }
        val m = cal.get(Calendar.MINUTE)
        val s = cal.get(Calendar.SECOND)
        val amPm = if (cal.get(Calendar.AM_PM) == Calendar.AM) "AM" else "PM"
        val compactUi = isCompactPhoneLayout()
        val timeBadgeStr = if (compactUi) {
            String.format(Locale.US, "%d:%02d %s", h12, m, amPm)
        } else {
            String.format(Locale.US, "%d:%02d:%02d %s", h12, m, s, amPm)
        }

        // Real application state (no hardcoded 14-day fallback)
        val streakDays = st.optInt("streak_days", 0).coerceAtLeast(0)
        val verifiedPts = st.optInt("verified_points", score)
        val provisionalPts = st.optInt("provisional_points", 0)
        val syncStatusStr = st.optString("sync_status", "PENDING SYNC")
        val isOnlinePaired = db.getConfigValue("pairing_status", "OFFLINE") == "ONLINE"
        val isSynced = syncStatusStr.contains("SYNCED")

        val widthDp = currentWindowWidthDp()
        val isTablet = isWideLayout()
        val sectionGap = dp(if (isTablet) 12 else 8)

        // ════════════════════════════════════════════════════════
        // 1. GREETING & MASCOT HERO CARD (Reference Section B)
        // ════════════════════════════════════════════════════════
        val mascotHeroCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            val padH = dp(if (isTablet) 18 else 12)
            val padV = dp(if (isTablet) 14 else 10)
            setPadding(padH, padV, padH, dp(if (isTablet) 12 else 9))
            background = surfaceBg(CLR_SURFACE, 18, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(
