        // 1B. ACCESSIBILITY INTERRUPTION COUNTDOWN BANNER
        // ════════════════════════════════════════════════════════
        val accStatus = AccessibilityGraceManager.getUiStatus(this)
        if (accStatus.isInterrupted) {
            val bannerCard = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                val padH = dp(if (isTablet) 18 else 14)
                val padV = dp(if (isTablet) 14 else 12)
                setPadding(padH, padV, padH, padV)
                background = surfaceBg("#2A1212", 16, "#FF4444", 2)
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = sectionGap }
            }

            val bannerHeader = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }

            val warnIcon = TextView(this).apply {
                text = "⚠️"
                textSize = if (isTablet) 24f else 20f
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    rightMargin = dp(10)
                }
            }
            bannerHeader.addView(warnIcon)

            val bannerTitleCol = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            }

            val bannerTitle = TextView(this).apply {
                text = when (accStatus.missingAccessType) {
                    AccessibilityGraceManager.MISSING_TYPE_USAGE_ACCESS -> "StrictRoutines Usage Access is OFF"
                    AccessibilityGraceManager.MISSING_TYPE_BOTH -> "StrictRoutines Permissions Missing"
                    else -> "StrictRoutines Accessibility is OFF"
                }
                textSize = if (isTablet) 16f else 14.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor("#FF5555"))
            }
            bannerTitleCol.addView(bannerTitle)

            val bannerSubtitle = TextView(this).apply {
                tag = "acc_interruption_subtitle"
                val remSec = (accStatus.remainingGraceMs / 1000).coerceAtLeast(0)
                val deadlineCal = Calendar.getInstance().apply { timeInMillis = accStatus.graceDeadlineWallMs }
                val deadlineStr = android.text.format.DateFormat.format("hh:mm:ss a", deadlineCal).toString()
                text = if (remSec > 0) {
                    "Grace period active — deadline: $deadlineStr"
                } else {
                    val overdueSec = accStatus.overdueSeconds
                    val overdueMm = overdueSec / 60
                    val overdueSs = overdueSec % 60
                    val overdueFmt = String.format(Locale.US, "-%02d:%02d", overdueMm, overdueSs)
                    "Grace expired — $overdueFmt overdue • Penalty: ${accStatus.recordedPenaltyPoints} pt(s)"
                }
                textSize = if (isTablet) 12f else 11f
                setTextColor(Color.parseColor("#CCCCCC"))
            }
            bannerTitleCol.addView(bannerSubtitle)
            bannerHeader.addView(bannerTitleCol)

            val countdownBadge = TextView(this).apply {
                tag = "acc_interruption_countdown"
                val remSec = (accStatus.remainingGraceMs / 1000).coerceAtLeast(0)
                if (remSec > 0) {
                    val mm = remSec / 60
                    val ss = remSec % 60
                    text = String.format(Locale.US, "%02d:%02d", mm, ss)
                    setTextColor(Color.parseColor("#FFAA00"))
                } else {
                    val overdueSec = accStatus.overdueSeconds
                    val mm = overdueSec / 60
                    val ss = overdueSec % 60
                    text = String.format(Locale.US, "-%02d:%02d", mm, ss)
                    setTextColor(Color.parseColor("#FF4444"))
                }
                textSize = if (isTablet) 20f else 17f
                setTypeface(typeface, Typeface.BOLD)
                setPadding(dp(8), dp(4), dp(8), dp(4))
                background = surfaceBg("#3D1B1B", 8, "#FF5555", 1)
            }
            bannerHeader.addView(countdownBadge)
            bannerCard.addView(bannerHeader)

            val usageMinutes = (accStatus.confirmedUsageDurationMs / 60000).toInt()
            val usageSecs = ((accStatus.confirmedUsageDurationMs % 60000) / 1000).toInt()
            val telemetryLine = TextView(this).apply {
                tag = "acc_interruption_telemetry"
                text = "State: ${accStatus.accessState.name} • Confirmed restricted usage: ${usageMinutes}m ${usageSecs}s • Penalty: ${accStatus.recordedPenaltyPoints} pts"
                textSize = if (isTablet) 11.5f else 10.5f
                setTextColor(Color.parseColor("#AAAAAA"))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(8)
                    bottomMargin = dp(10)
                }
            }
            bannerCard.addView(telemetryLine)

            if (accStatus.canOpenAccessibilitySettings && accStatus.canOpenUsageAccessSettings) {
                val btnRow = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
                }
                val accBtn = makePrimaryButton("ACCESSIBILITY", "#FF4444", true) {
                    try {
                        startActivity(Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS).apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) })
                    } catch (e: Exception) {
                        Toast.makeText(this, "Could not open settings: ${e.message}", Toast.LENGTH_SHORT).show()
                    }
                }.apply {
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
                }
                val usageBtn = makePrimaryButton("USAGE ACCESS", "#FF4444", true) {
                    try {
                        startActivity(Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS).apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) })
                    } catch (e: Exception) {
                        Toast.makeText(this, "Could not open settings: ${e.message}", Toast.LENGTH_SHORT).show()
                    }
                }.apply {
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
                }
                btnRow.addView(accBtn)
                btnRow.addView(usageBtn)
                bannerCard.addView(btnRow)
            } else if (accStatus.canOpenUsageAccessSettings) {
                val usageBtn = makePrimaryButton("OPEN USAGE ACCESS SETTINGS", "#FF4444", true) {
                    try {
                        startActivity(Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS).apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) })
                    } catch (e: Exception) {
                        Toast.makeText(this, "Could not open settings: ${e.message}", Toast.LENGTH_SHORT).show()
                    }
                }
                bannerCard.addView(usageBtn)
            } else {
                val settingsBtn = makePrimaryButton("OPEN ACCESSIBILITY SETTINGS", "#FF4444", true) {
                    try {
                        startActivity(Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS).apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) })
                    } catch (e: Exception) {
                        Toast.makeText(this, "Could not open settings: ${e.message}", Toast.LENGTH_SHORT).show()
                    }
                }
                bannerCard.addView(settingsBtn)
            }

            accInterruptionCountdownTv = countdownBadge
            accInterruptionSubtitleTv = bannerSubtitle
            accInterruptionTelemetryTv = telemetryLine

            contentContainer.addView(bannerCard)
        }

