        // ════════════════════════════════════════════════════════
        // 4. NEXT HOURLY CHECK CARD (Reference Section E)
        // ════════════════════════════════════════════════════════
        val countdown = db.getCurrentCountdownState(db.nowDate(), setOf("HOURLY"))
        val isWakeUpCountdown = countdown.type.equals("WAKE_UP", ignoreCase = true) ||
            countdown.activityId?.contains("WAKEUP", ignoreCase = true) == true
        val hourSlotDefault = String.format(Locale.US, "%02d:00 - %02d:00", greetHour, (greetHour + 1) % 24)
        val slotRegex = Regex("\\b\\d{2}:\\d{2}\\s*-\\s*\\d{2}:\\d{2}\\b")
        val fallbackSlotDisplay = (slotRegex.find(countdown.title ?: "")?.value ?: hourSlotDefault)
            .split("-").joinToString(" – ") { DisciplineScoringRules.formatTime12h(it.trim()).trimStart('0') }
        val windowStartLabel = countdown.windowStart?.let { windowClock12h(it) }
        val windowEndLabel = countdown.windowEnd?.let { windowClock12h(it) }
        val activeSlotDisplay = if (!windowStartLabel.isNullOrBlank() && !windowEndLabel.isNullOrBlank()) {
            "$windowStartLabel – $windowEndLabel"
        } else {
            fallbackSlotDisplay
        }

        val hourlyCard = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            val padH = dp(if (isTablet) 16 else 12)
            val padV = dp(if (isTablet) 13 else 9)
            setPadding(padH, padV, padH, padV)
