    private fun buildStrictBotContextLine(
        score: Int, cam: Boolean, bt: Boolean, trk: Boolean, bath: Boolean, gym: Boolean, hourly: Int): String {
        return when {
            !cam   -> "Step 1: Capture a wake-up photo for review. Points stay at 0 until approval."
            !bt    -> "Step 2: Confirm audio ready for your motivation track."
            !trk   -> "Step 3: Complete the motivation track. Points stay at 0 until proof approval."
            !bath  -> "Bath deadline approaching. Submit proof before 10:00 AM for review."
            hourly < 3 -> "Submit hourly photo proofs for review. ${3 - hourly} left for today."
            !gym   -> "Gym starts at 6:00 PM. ${80 - score} points to unlock reward."
            else   -> "You're at $score points. ${80 - score} more to unlock reward."
        }
    }

    // ════════════════════════════════════════════════════════
    // AI REVIEW PROGRESS COMPONENT
    // ════════════════════════════════════════════════════════

    private fun buildAiReviewProgressView(
        evalRecord: JSONObject?,
        act: DisciplineScoringRules.ScheduledActivityItem?,
        onRetry: (() -> Unit)? = null
    ): LinearLayout {
        val outJson = try {
            JSONObject(evalRecord?.optString("evaluator_output_json", "{}") ?: "{}")
        } catch (_: Exception) { JSONObject() }

        val dbStatus = evalRecord?.optString("status") ?: act?.status ?: ProofSubmissionRules.States.SUBMITTED_PENDING_EVALUATION
        val awardedPts = evalRecord?.optInt("points_awarded", act?.points ?: 0) ?: act?.points ?: 0

        var stage = outJson.optInt("stage", 0)
        var percent = outJson.optInt("progress_percent", 0)
        var stageName = outJson.optString("stage_name", "")
        var statusLabel = outJson.optString("status_label", "")
        var statusMessage = outJson.optString("status_message", "")

        val isUnconfiguredStatus = statusLabel.contains("CONFIGURATION", ignoreCase = true) ||
                statusMessage.contains("Configuration Required", ignoreCase = true) ||
                statusMessage.contains("not configured", ignoreCase = true) ||
                outJson.optBoolean("taufa_unconfigured", false)
        val isUploadFailedStatus = statusLabel.contains("UPLOAD FAILED", ignoreCase = true) ||
                statusMessage.contains("upload to Taufa failed", ignoreCase = true)
        val isPendingRetryStatus = statusLabel.contains("PENDING RETRY", ignoreCase = true) ||
                statusLabel == ProofSubmissionRules.StatusLabels.FAILED_RETRY_AVAILABLE ||
                dbStatus == ProofSubmissionRules.States.RETRYABLE_FAILURE ||
                statusMessage.contains("remains pending", ignoreCase = true)

        if (isUnconfiguredStatus) {
            stage = 4
            percent = 0
            stageName = "Configuration Required"
            statusLabel = "CONFIGURATION REQUIRED"
            statusMessage = "AI Evaluation Not Started — Taufa Session Configuration Required"
        } else if (isUploadFailedStatus) {
            stage = 4
            percent = 50
            stageName = "Upload Failed"
            statusLabel = "UPLOAD FAILED"
            statusMessage = "Image upload to Taufa failed — original evidence preserved."
        } else if (isPendingRetryStatus) {
            stage = 5
            percent = 50
            stageName = "Waiting for Taufa AI response"
            statusLabel = "PENDING RETRY"
            statusMessage = "AI validation queued — submission remains Pending Validation."
        }

        // Fallback mapping if stage metadata is missing or older format
        if (stage == 0 && !isUnconfiguredStatus) {
            when (dbStatus) {
                ProofSubmissionRules.States.APPROVED, "VERIFIED", "COMPLETED" -> {
                    stage = ProofSubmissionRules.PipelineStages.STAGE_8_COMPLETE
                    percent = 100
                    stageName = "Review completed"
                    statusLabel = if (awardedPts == 8) ProofSubmissionRules.StatusLabels.APPROVED_FULL_POINTS else ProofSubmissionRules.StatusLabels.APPROVED_PARTIAL_POINTS
                    statusMessage = if (awardedPts == 8) "Approved — full points (8/8 pts)" else "Approved — partial points ($awardedPts/8 pts)"
                }
                ProofSubmissionRules.States.REJECTED, "REJECTED_LATE" -> {
                    stage = ProofSubmissionRules.PipelineStages.STAGE_8_COMPLETE
                    percent = 100
                    stageName = "Review completed"
                    statusLabel = ProofSubmissionRules.StatusLabels.REJECTED
                    val actDetails = try { JSONObject(act?.detailsJson ?: "{}") } catch (_: Exception) { JSONObject() }
                    val rawReason = outJson.optString("rejection_reason").takeIf { it.isNotBlank() }
                        ?: actDetails.optString("rejection_reason").takeIf { it.isNotBlank() }
                        ?: "Rejected (0 pts)"
                    statusMessage = cleanUserFacingText(rawReason)
                }
                ProofSubmissionRules.States.RETRYABLE_FAILURE -> {
                    stage = ProofSubmissionRules.PipelineStages.STAGE_5_AI_ANALYSIS
                    percent = 50
                    stageName = "Waiting for Taufa AI response"
                    statusLabel = "PENDING RETRY"
                    statusMessage = "AI validation queued — submission remains Pending Validation."
                }
                ProofSubmissionRules.States.FLAGGED_FOR_REVIEW -> {
                    stage = ProofSubmissionRules.PipelineStages.STAGE_8_COMPLETE
                    percent = 100
                    stageName = "Review completed"
                    statusLabel = ProofSubmissionRules.StatusLabels.AWAITING_ADMIN_REVIEW
                    val specReason = act?.let { a ->
                        runCatching { JSONObject(a.detailsJson).optString("review_reason") }.getOrNull()
                    }?.takeIf { it.isNotBlank() }
                    statusMessage = if (!specReason.isNullOrBlank()) "Awaiting admin review · $specReason" else "AI analysis complete. Awaiting human admin review."
                }
                ProofSubmissionRules.States.EVALUATING, "VALIDATING" -> {
                    stage = ProofSubmissionRules.PipelineStages.STAGE_5_AI_ANALYSIS
                    percent = 65
                    stageName = "AI evidence analysis"
                    statusLabel = ProofSubmissionRules.StatusLabels.PROCESSING
                    statusMessage = "Analyzing submitted evidence with Taufa AI..."
                }
                else -> {
                    stage = ProofSubmissionRules.PipelineStages.STAGE_1_RECEIVED
                    percent = 12
                    stageName = "Submission received"
                    statusLabel = ProofSubmissionRules.StatusLabels.SUBMITTED
                    statusMessage = "Submission received and validated locally."
                }
            }
        }

        val container = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(14), dp(12), dp(14), dp(12))
            val borderColor = when {
                statusLabel == ProofSubmissionRules.StatusLabels.APPROVED_FULL_POINTS || statusLabel == ProofSubmissionRules.StatusLabels.APPROVED_PARTIAL_POINTS -> CLR_GREEN
                statusLabel == ProofSubmissionRules.StatusLabels.REJECTED || isUploadFailedStatus -> CLR_RED
                isUnconfiguredStatus || isPendingRetryStatus || statusLabel == ProofSubmissionRules.StatusLabels.AWAITING_ADMIN_REVIEW -> CLR_AMBER
                else -> CLR_CYAN
            }
            background = surfaceBg("#0D1520", 12, borderColor, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(12)
            }
        }

        // Header Row: Title + Percentage
        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(6)
            }
        }
        val titleTv = TextView(this).apply {
            text = "AI Proof Review"
            textSize = 13f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        val percentTv = TextView(this).apply {
            text = if (isPendingRetryStatus) "50% (Paused)" else "$percent%"
            textSize = 13f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (percent == 100 && awardedPts > 0) CLR_GREEN else if (isUnconfiguredStatus || isPendingRetryStatus || isUploadFailedStatus) CLR_AMBER else CLR_CYAN))
        }
        headerRow.addView(titleTv)
        headerRow.addView(percentTv)
        container.addView(headerRow)

        // Horizontal Progress Bar
        val pb = ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal).apply {
            max = 100
            this.progress = percent
            isIndeterminate = false
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(8)).apply {
                bottomMargin = dp(8)
            }
            val progressColor = when {
                statusLabel == ProofSubmissionRules.StatusLabels.APPROVED_FULL_POINTS || statusLabel == ProofSubmissionRules.StatusLabels.APPROVED_PARTIAL_POINTS -> Color.parseColor(CLR_GREEN)
                statusLabel == ProofSubmissionRules.StatusLabels.REJECTED || isUploadFailedStatus -> Color.parseColor(CLR_RED)
                isUnconfiguredStatus || isPendingRetryStatus || statusLabel == ProofSubmissionRules.StatusLabels.AWAITING_ADMIN_REVIEW -> Color.parseColor(CLR_AMBER)
                else -> Color.parseColor(CLR_CYAN)
            }
            progressTintList = android.content.res.ColorStateList.valueOf(progressColor)
            progressBackgroundTintList = android.content.res.ColorStateList.valueOf(Color.parseColor("#1E293B"))
        }
        container.addView(pb)

        // Status Message
        val statusTv = TextView(this).apply {
            text = "Status: $statusMessage"
            textSize = 11.5f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(2)
            }
        }
        container.addView(statusTv)

        // Stage Description
        val stageTv = TextView(this).apply {
            text = if (isPendingRetryStatus) {
                "Stage: Waiting for Taufa AI response"
            } else {
                "Stage: $stageName (Stage $stage of 8)"
            }
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_DIM))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(4)
            }
        }
        container.addView(stageTv)

        if (isPendingRetryStatus) {
            val supportingTv = TextView(this).apply {
                text = "ℹ️ No approval or points have been granted yet."
                textSize = 10.5f
                setTextColor(Color.parseColor("#8B949E"))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(6)
                }
            }
            container.addView(supportingTv)
        }

        // Distinct State Badge
        val badge = TextView(this).apply {
            text = statusLabel.uppercase(Locale.US)
            textSize = 10.5f
            setTypeface(typeface, Typeface.BOLD)
            val badgeBg: String
            val badgeFg: String
            when {
                statusLabel == ProofSubmissionRules.StatusLabels.APPROVED_FULL_POINTS || statusLabel == ProofSubmissionRules.StatusLabels.APPROVED_PARTIAL_POINTS -> {
                    badgeBg = "#0F2E1E"; badgeFg = CLR_GREEN
                }
                statusLabel == ProofSubmissionRules.StatusLabels.REJECTED || isUploadFailedStatus -> {
                    badgeBg = "#2A1215"; badgeFg = CLR_RED
                }
                isUnconfiguredStatus || isPendingRetryStatus || statusLabel == ProofSubmissionRules.StatusLabels.AWAITING_ADMIN_REVIEW -> {
                    badgeBg = "#2D2415"; badgeFg = CLR_AMBER
                }
                else -> {
                    badgeBg = "#0A1E24"; badgeFg = CLR_CYAN
                }
            }
            background = surfaceBg(badgeBg, 6, badgeFg, 1)
            setTextColor(Color.parseColor(badgeFg))
            setPadding(dp(8), dp(3), dp(8), dp(3))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        container.addView(badge)

        // Duplicate detection context and review option (Issues 7 & 8)
        val actDetails = try { JSONObject(act?.detailsJson ?: "{}") } catch (_: Exception) { JSONObject() }
        val matchedEvId = outJson.optString("matched_evidence_id").takeIf { it.isNotBlank() }
            ?: actDetails.optString("matched_evidence_id").takeIf { it.isNotBlank() }
        val simScoreVal = outJson.optDouble("similarity_score", -1.0).takeIf { it >= 0.0 }
            ?: actDetails.optDouble("similarity_score", -1.0).takeIf { it >= 0.0 }
        val isReviewEligible = outJson.optBoolean("review_eligible", false) ||
            actDetails.optBoolean("review_eligible", false)
        val isRejected = statusLabel == ProofSubmissionRules.StatusLabels.REJECTED || dbStatus in listOf(ProofSubmissionRules.States.REJECTED, "REJECTED_LATE")
        if (isRejected && (!matchedEvId.isNullOrBlank() || simScoreVal != null || isReviewEligible)) {
            val dupContextCard = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(10), dp(8), dp(10), dp(8))
                background = surfaceBg("#1E1012", 8, CLR_RED, 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(8)
                }
            }
            dupContextCard.addView(TextView(this).apply {
                text = "🔍 DUPLICATE DETECTION DETAILS"
                textSize = 10f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_RED))
            })
            if (!matchedEvId.isNullOrBlank()) {
                dupContextCard.addView(TextView(this).apply {
                    text = "• Matched prior evidence: $matchedEvId"
                    textSize = 10.5f
                    setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(2)
                    }
                })
            }
            if (simScoreVal != null && simScoreVal > 0.0) {
                val simPct = (simScoreVal * (if (simScoreVal <= 1.0) 100.0 else 1.0)).toInt()
                dupContextCard.addView(TextView(this).apply {
                    text = "• Visual similarity match: $simPct%"
                    textSize = 10.5f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                })
            }
            if (isReviewEligible) {
                dupContextCard.addView(TextView(this).apply {
                    text = "ℹ️ Potential duplicate flagged. Eligible for manual administrator appeal."
                    textSize = 10.5f
                    setTextColor(Color.parseColor(CLR_AMBER))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(4)
                    }
                })
                val appealBtn = makeSecondaryButton("📩 Request Admin Review", CLR_CYAN) {
                    act?.let { targetAct ->
                        try {
                            val detailsObj = JSONObject(targetAct.detailsJson)
                            detailsObj.put("review_reason", "User requested review for visual similarity ($matchedEvId)")
                            detailsObj.put("submission_locked", false)
                            val cv = android.content.ContentValues().apply {
                                put("status", "SUBMITTED")
                                put("validation_status", "NEEDS_REVIEW")
                                put("details_json", detailsObj.toString())
                            }
                            db.writableDatabase.update("scheduled_activities", cv, "activity_id = ?", arrayOf(targetAct.activityId))
                            val cvReview = android.content.ContentValues().apply {
                                put("status", "NEEDS_REVIEW")
                                put("decision", "AWAITING_REVIEW")
                                put("reason_note", "User requested review for visual similarity ($matchedEvId)")
                            }
                            db.writableDatabase.update("proof_reviews", cvReview, "activity_id = ?", arrayOf(targetAct.activityId))
                            Toast.makeText(this@MainActivity, "Review request submitted to administrator.", Toast.LENGTH_LONG).show()
                            refreshUi()
                        } catch (ex: Exception) {
                            Toast.makeText(this@MainActivity, "Could not submit review: ${ex.message}", Toast.LENGTH_SHORT).show()
                        }
                    }
                }.apply {
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(6)
                    }
                }
                dupContextCard.addView(appealBtn)
            }
            container.addView(dupContextCard)
        }

        // Retry button if failure
        if (statusLabel == ProofSubmissionRules.StatusLabels.FAILED_RETRY_AVAILABLE || dbStatus == ProofSubmissionRules.States.RETRYABLE_FAILURE || isPendingRetryStatus || isUploadFailedStatus || isUnconfiguredStatus) {
            val retryBtn = makeSecondaryButton("🔄 Retry AI Review", CLR_CYAN) {
                onRetry?.invoke()
            }.apply {
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(8)
                }
            }
            container.addView(retryBtn)
        }

        return container
    }

    // ════════════════════════════════════════════════════════
    // CHALLENGES TAB — Premium interactive task flow
    // ════════════════════════════════════════════════════════

    private fun renderChallengesTab(st: org.json.JSONObject, score: Int) {
        val verifiedScore = st.optInt("verified_points", score).coerceAtMost(100)
        val provisionalPoints = st.optInt("provisional_points", 0).coerceAtLeast(0)
        val camOk  = st.optInt("wakeup_camera") == 1
        val btOk   = st.optInt("wakeup_bt") == 1
        val trkOk  = st.optInt("wakeup_track") == 1
        val bathOk = st.optString("bath_status").startsWith("BATH COMPLETE")
        val gymOk  = st.optString("gym_status").startsWith("GYM COMPLETE")

        // ── Stitch DailyAuditSummaryCard ────────────────────
        val auditCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(12), dp(10), dp(12), dp(10))
            background = surfaceBg(CLR_SURFACE, 14, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(8) }
        }
        val auditTopRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        val auditCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        auditCol.addView(TextView(this).apply {
            text = "TODAY'S VERIFIED DISCIPLINE SCORE"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            letterSpacing = 0.05f
        })
        val scoreRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.BOTTOM
        }
        scoreRow.addView(TextView(this).apply {
            text = "$verifiedScore"
            textSize = 22f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_GREEN))
        })
        scoreRow.addView(TextView(this).apply {
            text = " / 100 pts"
            textSize = 12f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            setPadding(dp(4), 0, 0, dp(4))
        })
        auditCol.addView(scoreRow)
        auditTopRow.addView(auditCol)

        val statusPill = TextView(this).apply {
            text = if (verifiedScore >= 80) "OPTIMAL" else "IN PROGRESS"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_GREEN))
            setPadding(dp(10), dp(4), dp(10), dp(4))
            background = surfaceBg(CLR_ELEVATED, 99, CLR_GREEN, 1)
        }
        auditTopRow.addView(statusPill)
        auditCard.addView(auditTopRow)

        val progBar = ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal).apply {
            max = 100
            progress = verifiedScore
            progressTintList = ColorStateList.valueOf(Color.parseColor(CLR_GREEN))
            progressBackgroundTintList = ColorStateList.valueOf(Color.parseColor(CLR_SURFACE_LOW))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(7)).apply { topMargin = dp(10) }
        }
        auditCard.addView(progBar)
        addScoreDeductionSummary(auditCard, st)
        if (provisionalPoints > 0) {
            auditCard.addView(TextView(this).apply {
                text = "+$provisionalPoints provisional points pending confirmation"
                textSize = 10f
                setTextColor(Color.parseColor(CLR_CYAN))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(6)
                }
            })
        }
        contentContainer.addView(auditCard)
        buildStrictSessionLiveCard()?.let { contentContainer.addView(it) }

        // ── Authoritative Time-Window Countdown Card ───────
        contentContainer.addView(buildWindowCountdownCard())

        // ── Daily report uses the saved schedule, local proof reviews, and point ledger ──
        val reportDate = db.nowDate()
        val reportActivities = db.getDailyActivities(reportDate)
        val proofReviews = db.getDailyProofReviews(reportDate)
        val proofEvaluations = db.getDailyProofEvaluations(reportDate, isDevMode)
        val reviewByActId = HashMap<String, JSONObject>(proofReviews.size)
        val reviewBySubId = HashMap<String, JSONObject>(proofReviews.size)
        val reviewByEvId = HashMap<String, JSONObject>(proofReviews.size)
        for (r in proofReviews) {
            val aid = r.optString("activity_id")
            if (aid.isNotBlank() && !reviewByActId.containsKey(aid)) reviewByActId[aid] = r
            val sid = r.optString("submission_id")
            if (sid.isNotBlank() && !reviewBySubId.containsKey(sid)) reviewBySubId[sid] = r
            val eid = r.optString("evidence_id")
            if (eid.isNotBlank() && !reviewByEvId.containsKey(eid)) reviewByEvId[eid] = r
        }

        val evalByActId = HashMap<String, JSONObject>(proofEvaluations.size)
        val evalBySubId = HashMap<String, JSONObject>(proofEvaluations.size)
        for (e in proofEvaluations) {
            val aid = e.optString("activity_id")
            if (aid.isNotBlank() && !evalByActId.containsKey(aid)) evalByActId[aid] = e
            val sid = e.optString("submission_id")
            if (sid.isNotBlank() && !evalBySubId.containsKey(sid)) evalBySubId[sid] = e
        }

        val cachedWakeFlow = db.getWakeUpFlowStatus(reportDate, isDevMode)
        val cachedWakeCompleted = cachedWakeFlow.optBoolean("all_completed", false)
        val cachedDayWakeStatus = db.getDayState(reportDate, isDevMode).optString("wakeup_status", "").uppercase(Locale.US)
        val cachedGateActive = db.getDailyRoutineGate(reportDate).optBoolean("active", false)
        val cachedAttemptId = cachedWakeFlow.optString("attempt_id")
        val cachedWakePendingSync = if (cachedAttemptId.isNotBlank()) {
            val evtId = "evt_wake_" + UUID.nameUUIDFromBytes(cachedAttemptId.toByteArray()).toString()
            db.getSyncEventState(evtId).first in listOf("PENDING", "SYNCED")
        } else false

        fun reportReview(activity: DisciplineScoringRules.ScheduledActivityItem): JSONObject? {
            if (activity.activityId.isNotBlank()) {
                reviewByActId[activity.activityId]?.let { return it }
            }

            val details = runCatching { JSONObject(activity.detailsJson) }.getOrNull()
            if (details != null) {
                val subId = details.optString("submission_id")
                if (subId.isNotBlank()) {
                    reviewBySubId[subId]?.let { return it }
                }
                val evidenceId = details.optString("evidence_id", details.optString("evidenceId", ""))
                if (evidenceId.isNotBlank()) {
                    reviewByEvId[evidenceId]?.let { return it }
                }
            }
            return null
        }

        fun reportEvaluation(activity: DisciplineScoringRules.ScheduledActivityItem): JSONObject? {
            if (activity.activityId.isNotBlank()) {
                evalByActId[activity.activityId]?.let { return it }
            }
            val details = runCatching { JSONObject(activity.detailsJson) }.getOrNull()
            if (details != null) {
                val subId = details.optString("submission_id")
                if (subId.isNotBlank()) {
                    evalBySubId[subId]?.let { return it }
                }
            }
            return null
        }

        fun reportSubmitted(activity: DisciplineScoringRules.ScheduledActivityItem): Boolean {
            val actDetails = runCatching { JSONObject(activity.detailsJson) }.getOrDefault(JSONObject())
            val review = reportReview(activity)
            val eval = reportEvaluation(activity)
            val reviewStatus = review?.optString("status", "").orEmpty().uppercase(Locale.US)
            val hasApprovedReview = reviewStatus in setOf("APPROVED", "VERIFIED", "COMPLETED")
            val evalStatus = eval?.optString("status", "").orEmpty().uppercase(Locale.US)
            val hasApprovedEval = evalStatus in setOf("APPROVED", "VERIFIED", "COMPLETED")

            if (activity.type == "HOURLY") {
                val cat = review?.optString("category")?.takeIf { it.isNotBlank() && !it.equals("Unavailable", ignoreCase = true) }
                    ?: actDetails.optString("category").takeIf { it.isNotBlank() && !it.equals("Unavailable", ignoreCase = true) }
                    ?: actDetails.optString("activity_category").takeIf { it.isNotBlank() && !it.equals("Unavailable", ignoreCase = true) }
                    ?: actDetails.optString("primary_activity").takeIf { it.isNotBlank() && !it.equals("Unavailable", ignoreCase = true) }
                    ?: db.getScheduledActivityCategory(activity.activityId).takeIf { it.isNotBlank() && !it.equals("Unavailable", ignoreCase = true) }
                if (cat.isNullOrBlank() && !hasApprovedReview && !hasApprovedEval) {
                    return false
                }
                val hasSubmissionId = actDetails.optString("submission_id").isNotBlank() || eval?.optString("submission_id")?.isNotBlank() == true
                val hasEvidenceId = actDetails.optString("evidence_id", actDetails.optString("evidenceId", "")).isNotBlank()
                val hasRealProof = hasSubmissionId || hasEvidenceId || (review != null && !cat.isNullOrBlank()) || eval != null
                val hasSubmittedAt = !activity.submittedAt.isNullOrBlank()
                return hasRealProof && (hasSubmittedAt || eval != null || activity.status.uppercase(Locale.US) in setOf("SUBMITTED", "VALIDATING", "AI_PROVISIONAL", "VERIFIED", "COMPLETED", "REJECTED", "REJECTED_LATE"))
            }

            if (activity.type == "WAKE_UP" || activity.activityId.contains("WAKEUP")) {
                val isGenuinelySubmitted = hasApprovedReview || hasApprovedEval || cachedWakeCompleted || cachedDayWakeStatus in setOf("PENDING_SERVER", "VERIFIED", "COMPLETED") || cachedGateActive || cachedWakePendingSync
                return isGenuinelySubmitted
            }

            val hasSubmissionId = actDetails.optString("submission_id").isNotBlank() || eval?.optString("submission_id")?.isNotBlank() == true
            val hasEvidenceId = actDetails.optString("evidence_id", actDetails.optString("evidenceId", "")).isNotBlank()
            val hasReview = review != null || eval != null
            val hasSubmittedAt = !activity.submittedAt.isNullOrBlank()
            val hasRealProof = hasSubmissionId || hasEvidenceId || (review != null && hasApprovedReview) || (eval != null && hasApprovedEval)
            return (hasRealProof || hasApprovedReview || hasApprovedEval) && (hasSubmittedAt || hasReview || activity.status.uppercase(Locale.US) in setOf("SUBMITTED", "VALIDATING", "AI_PROVISIONAL", "VERIFIED", "COMPLETED", "REJECTED", "REJECTED_LATE"))
        }

        fun reportStatus(activity: DisciplineScoringRules.ScheduledActivityItem): String {
            val state = activity.status.uppercase(Locale.US)
            val nowMs = db.authoritativeNowMs()
            val startMs = db.parseIsoToMs(activity.windowStart)
            val endMs = db.parseIsoToMs(activity.windowEnd)

            val actDetails = runCatching { JSONObject(activity.detailsJson) }.getOrDefault(JSONObject())
            val hasSubmittedAt = !activity.submittedAt.isNullOrBlank()
            val review = reportReview(activity)
            val eval = reportEvaluation(activity)
            val reviewState = review?.optString("status", "")?.uppercase(Locale.US).orEmpty()
            val reviewDecision = review?.optString("decision", "")?.uppercase(Locale.US).orEmpty()
            val evalState = eval?.optString("status", "")?.uppercase(Locale.US).orEmpty()
            val hasActualSubmission = reportSubmitted(activity)

            val isRejectedAuthoritative = state in setOf("REJECTED", "REJECTED_LATE", "PROVISIONAL_REJECT") ||
                reviewState in setOf("REJECTED", "REJECTED_LATE") ||
                reviewDecision == "REJECTED" ||
                evalState in setOf("REJECTED", "REJECTED_LATE") ||
                actDetails.optString("ai_validation_state") == "REJECTED"

            val isVerifiedAuthoritative = !isRejectedAuthoritative && (
                state in setOf("VERIFIED", "COMPLETED", "APPROVED") ||
                reviewState in setOf("APPROVED", "VERIFIED", "COMPLETED") ||
                reviewDecision in setOf("APPROVED", "VERIFIED") ||
                evalState in setOf("APPROVED", "VERIFIED", "COMPLETED") ||
                actDetails.optString("ai_validation_state") in setOf("APPROVED", "VERIFIED")
            )

            if (!hasActualSubmission && !isRejectedAuthoritative && !isVerifiedAuthoritative && state in setOf("SUBMITTED", "VALIDATING", "AI_PROVISIONAL", "ADMIN_REVIEW", "UNDER_REVIEW", "NEEDS_REVIEW", "DUPLICATE_REVIEW", "VERIFIED", "COMPLETED", "APPROVED")) {
                if (state in setOf("SKIPPED", "EXCUSED", "CANCELLED", "PENDING_SYNC")) return state
                return WindowStateRules.state("SCHEDULED", nowMs, startMs, endMs, activity.submissionEligible)
            }

            if (activity.type == "HOURLY") {
                if (isVerifiedAuthoritative) return "VERIFIED"
                if (isRejectedAuthoritative) return "REJECTED"
                if (hasActualSubmission) {
                    if (reviewState in setOf("UNDER_REVIEW", "NEEDS_REVIEW", "ADMIN_REVIEW", "FLAGGED_FOR_REVIEW")) return "ADMIN_REVIEW"
                    if (reviewState in setOf("PENDING", "AI_ANALYZING", "AI_QUEUED", "PROCESSING") || state in setOf("SUBMITTED", "VALIDATING", "AI_PROVISIONAL")) return "AI_REVIEW"
                    return "SUBMITTED"
                }
                if (state in setOf("CANCELLED", "SKIPPED", "EXCUSED")) return state
                // No actual submission exists for this hourly occurrence: derive state purely from window schedule
                return when {
                    nowMs >= endMs -> "MISSED"
                    nowMs >= startMs -> "OPEN"
                    else -> "UPCOMING"
                }
            }

            if (activity.type != "TRAVEL" && startMs != Long.MIN_VALUE && nowMs < startMs) {
                if (!hasActualSubmission && !isRejectedAuthoritative && !isVerifiedAuthoritative) {
                    return "UPCOMING"
                }
            }

            if (isVerifiedAuthoritative) return "VERIFIED"
            if (isRejectedAuthoritative) return "REJECTED"
            if (hasActualSubmission && reviewState in setOf("UNDER_REVIEW", "NEEDS_REVIEW", "ADMIN_REVIEW", "FLAGGED_FOR_REVIEW")) return "ADMIN_REVIEW"
            if (hasActualSubmission && (hasSubmittedAt || state in setOf("SUBMITTED", "VALIDATING", "AI_PROVISIONAL"))) return "SUBMITTED"
            if (state in setOf("SKIPPED", "EXCUSED", "CANCELLED", "PENDING_SYNC")) return state

            if (activity.type == "TRAVEL") {
                if (TravelBookingRules.isDemoBooking(activity.title, activity.detailsJson)) {
                    return "DEMO"
                }
                val depMs = actDetails.optLong("departure_ms", 0L).takeIf { it > 0L } ?: db.parseIsoToMs(activity.scheduledTime)
                val durationHours = actDetails.optInt("duration_hours", 3).coerceIn(1, 24)
                val travelEndMs = actDetails.optLong("travel_end_ms", 0L).takeIf { it > 0L } ?: (depMs + durationHours * 3600_000L)
                val proofStartMs = actDetails.optLong("proof_window_start_ms", 0L).takeIf { it > 0L } ?: travelEndMs
                val proofEndMs = actDetails.optLong("proof_window_end_ms", 0L).takeIf { it > 0L } ?: (proofStartMs + 2 * 3600_000L)
                val hasSubmitted = hasActualSubmission || reviewState.isNotBlank()
                val travelState = TravelBookingRules.resolveAuthoritativeState(
                    nowMs = nowMs,
                    departureMs = depMs,
                    travelEndMs = travelEndMs,
                    proofStartMs = proofStartMs,
                    proofEndMs = proofEndMs,
                    status = state,
                    hasProofSubmitted = hasSubmitted
                )
                return when (travelState) {
                    TravelBookingRules.TravelStatusState.PREBOOKED -> "UPCOMING"
                    TravelBookingRules.TravelStatusState.TRAVEL_IN_PROGRESS -> "TRAVEL_IN_PROGRESS"
                    TravelBookingRules.TravelStatusState.PROOF_OPENS_SOON -> "PROOF_OPENS_SOON"
                    TravelBookingRules.TravelStatusState.SUBMISSION_OPEN -> "OPEN"
                    TravelBookingRules.TravelStatusState.SUBMITTED_PENDING_REVIEW -> "SUBMITTED"
                    TravelBookingRules.TravelStatusState.VERIFIED -> "VERIFIED"
                    TravelBookingRules.TravelStatusState.MISSED -> "MISSED"
                    TravelBookingRules.TravelStatusState.REJECTED -> "REJECTED"
                }
            }

            return WindowStateRules.state(state, nowMs, startMs, endMs, activity.submissionEligible)
        }

        val reportStates = reportActivities.associate { it.activityId to reportStatus(it) }
        val reportMetrics = listOf(
            Triple("SCHEDULED", reportActivities.size, CLR_CYAN),
            Triple("VERIFIED", reportStates.values.count { it in setOf("VERIFIED", "APPROVED", "COMPLETED") }, CLR_GREEN),
            Triple("PENDING REVIEW", reportStates.values.count { it in setOf("SUBMITTED", "VALIDATING", "AI_PROVISIONAL", "ADMIN_REVIEW", "UNDER_REVIEW", "NEEDS_REVIEW", "DUPLICATE_REVIEW") }, CLR_AMBER),
            Triple("REJECTED", reportStates.values.count { it in setOf("REJECTED", "REJECTED_LATE", "PROVISIONAL_REJECT") }, CLR_RED),
            Triple("MISSED", reportActivities.count { reportStates[it.activityId] in setOf("MISSED", "EXPIRED", "CLOSED") && !reportSubmitted(it) }, CLR_TEXT_DIM),
            Triple("UPCOMING", reportStates.values.count { it in setOf("SCHEDULED", "UPCOMING", "NOTIFIED", "OPEN") }, CLR_TEXT_SECONDARY)
        )
        val reportColumns = if (isWideLayout()) 3 else 2
        val reportGrid = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        }
        reportMetrics.chunked(reportColumns).forEach { values ->
            val row = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
            values.forEach { (label, count, accent) ->
                row.addView(designCard(paddingDp = 9, cornerDp = 12, strokeHex = CLR_BORDER).apply {
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(6); bottomMargin = dp(6) }
                    addView(TextView(this@MainActivity).apply {
                        text = label; textSize = 8f; setTypeface(typeface, Typeface.BOLD); setTextColor(Color.parseColor(CLR_TEXT_SECONDARY)); maxLines = 1
                    })
                    addView(TextView(this@MainActivity).apply {
                        text = count.toString(); textSize = 18f; setTypeface(typeface, Typeface.BOLD); setTextColor(Color.parseColor(accent))
                    })
                })
            }
            repeat(reportColumns - values.size) {
                row.addView(View(this).apply { layoutParams = LinearLayout.LayoutParams(0, 1, 1f).apply { rightMargin = dp(6) } })
            }
            reportGrid.addView(row)
        }
        val reportPointsSummary = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(5) }
            val vPts = st.optInt("verified_points", verifiedScore)
            listOf(
                Triple("VERIFIED POINTS", vPts, if (vPts < 0) CLR_RED else CLR_GREEN),
                Triple("PROVISIONAL POINTS", provisionalPoints, CLR_AMBER)
            ).forEach { (label, value, accent) ->
                addView(designCard(paddingDp = 10, cornerDp = 13, strokeHex = CLR_BORDER).apply {
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(6) }
                    addView(TextView(this@MainActivity).apply { text = label; textSize = 8f; setTypeface(typeface, Typeface.BOLD); setTextColor(Color.parseColor(CLR_TEXT_SECONDARY)) })
                    addView(TextView(this@MainActivity).apply { text = "$value pts"; textSize = 15f; setTypeface(typeface, Typeface.BOLD); setTextColor(Color.parseColor(accent)) })
                })
            }
        }
        val reportFilters = listOf("ALL", "VERIFIED", "PENDING", "REJECTED", "MISSED", "UPCOMING")
        val reportFilterScroll = HorizontalScrollView(this).apply {
            isHorizontalScrollBarEnabled = false
            isHorizontalFadingEdgeEnabled = true
            setFadingEdgeLength(dp(24))
            clipToPadding = false
            setPadding(0, 0, dp(16), 0)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
        }
        val reportFilterRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            setPadding(0, 0, dp(24), 0)
            clipToPadding = false
        }
        reportFilters.forEach { filter ->
            reportFilterRow.addView(TextView(this).apply {
                text = filter.replace("_", " ").lowercase(Locale.US).replaceFirstChar { it.uppercase() }
                textSize = 10.5f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(if (dailyReportFilter == filter) CLR_GREEN else CLR_TEXT_SECONDARY))
                setPadding(dp(12), dp(6), dp(12), dp(6))
                background = surfaceBg(if (dailyReportFilter == filter) "#0B2B22" else CLR_SURFACE, 99, if (dailyReportFilter == filter) CLR_GREEN else CLR_BORDER, 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { rightMargin = dp(6) }
                applySpringTouch { dailyReportFilter = filter; refreshUi() }
            })
        }
        reportFilterScroll.addView(reportFilterRow)

        val dailyReportItems = reportActivities.filter { activity ->
            val state = reportStates[activity.activityId].orEmpty()
            val submitted = reportSubmitted(activity)
            when (dailyReportFilter) {
                "COMPLETED" -> submitted
                "VERIFIED" -> state in setOf("VERIFIED", "APPROVED", "COMPLETED")
                "PENDING" -> state in setOf("SUBMITTED", "VALIDATING", "AI_PROVISIONAL", "ADMIN_REVIEW", "UNDER_REVIEW", "NEEDS_REVIEW", "DUPLICATE_REVIEW")
                "REJECTED" -> state in setOf("REJECTED", "REJECTED_LATE", "PROVISIONAL_REJECT")
                "MISSED" -> state in setOf("MISSED", "EXPIRED", "CLOSED") && !submitted
                "UPCOMING" -> state in setOf("SCHEDULED", "UPCOMING", "NOTIFIED", "OPEN")
                else -> true
            }
        }
        val activeCountdown = db.getCurrentCountdownState(reportDate)
        val hourlyActivities = dailyReportItems
        val verifiedCheckpoints = reportActivities.count { reportStates[it.activityId] in setOf("VERIFIED", "APPROVED", "COMPLETED") }
        contentContainer.addView(sectionHeading("DAILY DISCIPLINE PROTOCOL", "$verifiedCheckpoints/${reportActivities.size} verified"))
        contentContainer.addView(reportFilterScroll)

        if (hourlyActivities.isEmpty()) {
            contentContainer.addView(buildEmptyState(
                "◷", "No activities match this filter", "Choose All to view every saved activity."
            ))
        } else {
            val countdownIndex = hourlyActivities.indexOfFirst { it.activityId == activeCountdown.activityId }
            val nextOpenIndex = if (countdownIndex >= 0) countdownIndex else hourlyActivities.indexOfFirst {
                it.status.equals("OPEN", ignoreCase = true) || it.status.equals("SCHEDULED", ignoreCase = true)
            }
            val firstVisibleIndex = if (nextOpenIndex >= 0) (nextOpenIndex - 1).coerceAtLeast(0)
                else (hourlyActivities.size - 5).coerceAtLeast(0)
            val localScoreEventsRaw = db.getScoreEvents(reportDate, isDevMode)
            val parsedScoreEvents = ArrayList<JSONObject>(localScoreEventsRaw.length())
            for (i in 0 until localScoreEventsRaw.length()) {
                localScoreEventsRaw.optJSONObject(i)?.let { parsedScoreEvents.add(it) }
            }
            val validRetainedEvIds = HashSet<String>()
            for (event in parsedScoreEvents) {
                if (event.optString("event_type") == "PROOF_APPROVED") {
                    val evId = event.optJSONObject("audit")?.optString("evidence_id").orEmpty()
                    if (evId.isNotBlank() && evId !in validRetainedEvIds) {
                        if (db.hasApprovedRetainedProof(evId)) {
                            validRetainedEvIds.add(evId)
                        }
                    }
                }
            }
            val proofApprovedScoreEvents = parsedScoreEvents.filter { event ->
                if (event.optString("event_type") != "PROOF_APPROVED") return@filter false
                val evId = event.optJSONObject("audit")?.optString("evidence_id").orEmpty()
                evId.isNotBlank() && evId in validRetainedEvIds
            }

            val visibleCheckpoints = if (showAllHourlyCheckpoints) hourlyActivities
                else hourlyActivities.drop(firstVisibleIndex).take(5)

            var previousDayPart = ""
            visibleCheckpoints.forEach { activity ->
                val hasRealSubmission = reportSubmitted(activity)
                val state = reportStates[activity.activityId].orEmpty()
                val review = reportReview(activity)
                val eval = reportEvaluation(activity)
                val isVerified = state in setOf("VERIFIED", "APPROVED", "COMPLETED")
                val isRejected = state in setOf("REJECTED", "REJECTED_LATE", "PROVISIONAL_REJECT")
                val isSubmitted = !isVerified && !isRejected && hasRealSubmission && state in setOf("SUBMITTED", "VALIDATING", "AI_PROVISIONAL", "ADMIN_REVIEW", "UNDER_REVIEW", "NEEDS_REVIEW", "DUPLICATE_REVIEW")
                val isOpen = state == "OPEN"
                val isMissed = state == "MISSED" || state == "EXPIRED" || state == "CLOSED"
                val isAdminReview = !isVerified && !isRejected && hasRealSubmission && state in setOf("AI_PROVISIONAL", "ADMIN_REVIEW", "UNDER_REVIEW", "NEEDS_REVIEW", "DUPLICATE_REVIEW")
                val scheduledHour = windowClock(activity.scheduledTime).take(2).toIntOrNull() ?: 12
                val dayPart = when {
                    scheduledHour in 5..11 -> "MORNING"
                    scheduledHour in 12..16 -> "AFTERNOON"
                    scheduledHour in 17..20 -> "EVENING"
                    else -> "NIGHT"
                }
                if (dayPart != previousDayPart) {
                    contentContainer.addView(sectionHeading(dayPart))
                    previousDayPart = dayPart
                }
                val actDetails = runCatching { JSONObject(activity.detailsJson) }.getOrDefault(JSONObject())
                val isTravelHold = actDetails.optBoolean("travel_hold", false)
                val isWakeHold = actDetails.optBoolean("wake_hold", false)
                val isNotExcused = actDetails.optBoolean("not_excused", false)

                val isTravel = activity.type == "TRAVEL"
                val isTravelDemo = isTravel && TravelBookingRules.isDemoBooking(activity.title, activity.detailsJson)
                val isTravelReal = isTravel && !isTravelDemo

                var travelAuthState: TravelBookingRules.TravelStatusState? = null
                var depTimeStr = ""
                var arrTimeStr = ""
                var proofEndStr = ""

                if (isTravelReal) {
                    val depMs = actDetails.optLong("departure_ms", 0L).takeIf { it > 0L } ?: db.parseIsoToMs(activity.scheduledTime)
                    val durationHours = actDetails.optInt("duration_hours", 3).coerceIn(1, 24)
                    val travelEndMs = actDetails.optLong("travel_end_ms", 0L).takeIf { it > 0L } ?: (depMs + durationHours * 3600_000L)
                    val proofStartMs = actDetails.optLong("proof_window_start_ms", 0L).takeIf { it > 0L } ?: travelEndMs
                    val proofEndMs = actDetails.optLong("proof_window_end_ms", 0L).takeIf { it > 0L } ?: (proofStartMs + 2 * 3600_000L)

                    depTimeStr = ScheduleClock.display(depMs, db.scheduleTimezone(), "h:mm a")
                    arrTimeStr = ScheduleClock.display(travelEndMs, db.scheduleTimezone(), "h:mm a")
                    proofEndStr = ScheduleClock.display(proofEndMs, db.scheduleTimezone(), "h:mm a")

                    val hasSubmitted = !activity.submittedAt.isNullOrBlank() || state in setOf("SUBMITTED", "VALIDATING", "AI_PROVISIONAL", "VERIFIED", "COMPLETED") || (review != null)
                    travelAuthState = TravelBookingRules.resolveAuthoritativeState(
                        nowMs = db.authoritativeNowMs(),
                        departureMs = depMs,
                        travelEndMs = travelEndMs,
                        proofStartMs = proofStartMs,
                        proofEndMs = proofEndMs,
                        status = activity.status,
                        hasProofSubmitted = hasSubmitted
                    )
                }

                val isPostExamSlot = (activity.type == "HOURLY") && (
                    actDetails.optBoolean("is_post_exam_class_time", false) ||
                    actDetails.optBoolean("post_exam_bonus_eligible", false) ||
                    db.isPostExamBonusEligible(reportDate, activity.activityId)
                )

                val isBath = activity.type == "BATH" || activity.activityId.contains("BATH")
                val isExcusedByBath = actDetails.optBoolean("suppressed_by_bath", false) ||
                    actDetails.optString("reconciliation_status") == "EXCUSED_BY_BATH" ||
                    actDetails.optString("attendance_status") == "EXCUSED_BY_BATH" ||
                    actDetails.optString("suppression_reason").contains("bath", ignoreCase = true)

                val tint = when {
                    isBath -> CLR_CYAN
                    isExcusedByBath -> CLR_CYAN
                    isTravelDemo -> CLR_AMBER
                    isTravelReal -> when (travelAuthState) {
                        TravelBookingRules.TravelStatusState.VERIFIED -> CLR_GREEN
                        TravelBookingRules.TravelStatusState.SUBMISSION_OPEN -> CLR_GREEN
                        TravelBookingRules.TravelStatusState.PROOF_OPENS_SOON -> CLR_AMBER
                        TravelBookingRules.TravelStatusState.SUBMITTED_PENDING_REVIEW -> CLR_AMBER
                        TravelBookingRules.TravelStatusState.TRAVEL_IN_PROGRESS -> CLR_PURPLE
                        TravelBookingRules.TravelStatusState.PREBOOKED -> CLR_TEXT_SECONDARY
                        TravelBookingRules.TravelStatusState.MISSED, TravelBookingRules.TravelStatusState.REJECTED -> CLR_RED
                        else -> CLR_TEXT_SECONDARY
                    }
                    isVerified -> CLR_GREEN
                    isAdminReview -> CLR_AMBER
                    isOpen || isSubmitted -> CLR_CYAN
                    isRejected || isNotExcused -> CLR_RED
                    isTravelHold -> CLR_PURPLE
                    isWakeHold -> CLR_AMBER
                    state == "EXCUSED" -> CLR_CYAN
                    isMissed -> CLR_TEXT_DIM
                    else -> CLR_TEXT_SECONDARY
                }
                val statusLabel = when {
                    isBath -> "PLANNED"
                    isExcusedByBath -> "EXCUSED – Bath overlap"
                    isTravelDemo -> "SIMULATED TEST"
                    isTravelReal -> when (travelAuthState) {
                        TravelBookingRules.TravelStatusState.PREBOOKED -> "PREBOOKED"
                        TravelBookingRules.TravelStatusState.TRAVEL_IN_PROGRESS -> "TRAVEL IN PROGRESS"
                        TravelBookingRules.TravelStatusState.PROOF_OPENS_SOON -> "PROOF OPENS AT $arrTimeStr"
                        TravelBookingRules.TravelStatusState.SUBMISSION_OPEN -> "SUBMISSION WINDOW OPEN"
                        TravelBookingRules.TravelStatusState.SUBMITTED_PENDING_REVIEW -> "PROOF SUBMITTED — PENDING REVIEW"
                        TravelBookingRules.TravelStatusState.VERIFIED -> "TRAVEL VERIFIED"
                        TravelBookingRules.TravelStatusState.MISSED -> "TRAVEL PROOF MISSED"
                        TravelBookingRules.TravelStatusState.REJECTED -> "TRAVEL PROOF REJECTED"
                        else -> "PREBOOKED"
                    }
                    state == "SKIPPED" -> "SKIPPED"
                    isTravelHold -> "TRAVEL HOLD"
                    isWakeHold -> "WAKE HOLD"
                    isNotExcused -> "NOT EXCUSED"
                    state == "EXCUSED" -> "EXCUSED"
                    state == "PENDING_SYNC" -> "PENDING SYNC"
                    state == "EXPIRED" -> "EXPIRED"
                    state == "INVALID_WINDOW" -> "INVALID WINDOW"
                    isVerified -> "VERIFIED"
                    isRejected -> "REJECTED"
                    isAdminReview -> "ADMIN REVIEW"
                    hasRealSubmission && (state == "SUBMITTED" || state == "VALIDATING") -> "AI REVIEW"
                    isOpen -> "OPEN NOW"
                    isMissed -> "MISSED"
                    else -> "UPCOMING"
                }
                val startTime = windowClock12h(activity.windowStart)
                val endTime = windowClock12h(activity.windowEnd)
                val savedBath = if (activity.type == "BATH" || activity.activityId.contains("BATH"))
                    runCatching { db.getSavedBathSchedule(activity) }.getOrNull() else null
                val timeRange = when {
                    isTravelDemo -> "Simulated Test Window"
                    isTravelReal -> "Trip: $depTimeStr – $arrTimeStr • Proof: $arrTimeStr – $proofEndStr"
                    activity.type == "GYM" -> {
                        val plannedStr = windowClock12h(activity.scheduledTime)
                        val durMins = actDetails.optInt("duration_minutes", 90)
                        val expFinish = actDetails.optString("expected_finish").ifBlank {
                            GymWindowRules.calculateGymWindow(reportDate, activity.scheduledTime.takeLast(5), durMins).expectedFinishDisplay
                        }
                        if (startTime.isNotEmpty() && endTime.isNotEmpty()) {
                            "Gym: $plannedStr – $expFinish • Proof: $startTime – $endTime"
                        } else {
                            "Gym: $plannedStr – $expFinish"
                        }
                    }
                    activity.type == "BATH" || activity.activityId.contains("BATH") -> {
                        val actInterval = savedBath?.activityIntervalDisplay.orEmpty()
                        if (actInterval.isNotEmpty()) {
                            actInterval
                        } else if (startTime.isNotEmpty() && endTime.isNotEmpty()) {
                            "$startTime–$endTime"
                        } else {
                            "3:30 PM–4:00 PM"
                        }
                    }
                    startTime.isNotEmpty() && endTime.isNotEmpty() -> "$startTime – $endTime"
                    else -> "Scheduled checkpoint"
                }
                val rawTitle = activity.title.replace(
                    Regex("\\s*\\(\\d{2}:\\d{2}\\s*[-–]\\s*\\d{2}:\\d{2}\\)"), ""
                ).trim()
                val title = when {
                    isTravelDemo -> "Travel & Transit (Simulated Demo)"
                    activity.type == "BATH" || activity.activityId.contains("BATH") -> {
                        val actInterval = savedBath?.activityIntervalDisplay.orEmpty()
                        if (actInterval.isNotEmpty()) "Bath – $actInterval" else "Scheduled Bath"
                    }
                    else -> rawTitle
                }
                val approvedProofExists = db.hasApprovedRetainedProof(review?.optString("evidence_id").orEmpty())
                val approvedProofPoints = if (approvedProofExists) review?.optInt("points_awarded", 0) ?: 0 else 0
                val detail = when {
                    isTravelDemo -> "Simulated demo run · Does not affect attendance, points, or restrictions"
                    isTravelReal -> when (travelAuthState) {
                        TravelBookingRules.TravelStatusState.PREBOOKED -> "Travel reserved $depTimeStr – $arrTimeStr"
                        TravelBookingRules.TravelStatusState.TRAVEL_IN_PROGRESS -> "Travel in progress ($depTimeStr – $arrTimeStr) · Proof opens at $arrTimeStr"
                        TravelBookingRules.TravelStatusState.PROOF_OPENS_SOON -> "Arriving soon · Proof submission window opens at $arrTimeStr"
                        TravelBookingRules.TravelStatusState.SUBMISSION_OPEN -> "Proof submission window is open until $proofEndStr"
                        TravelBookingRules.TravelStatusState.SUBMITTED_PENDING_REVIEW -> "Proof submitted · AI review pending"
                        TravelBookingRules.TravelStatusState.VERIFIED -> "Travel proof verified · Points awarded"
                        TravelBookingRules.TravelStatusState.MISSED -> "Travel proof was not submitted by the $proofEndStr deadline · 0 points"
                        TravelBookingRules.TravelStatusState.REJECTED -> "Travel proof rejected · 0 points"
                        else -> "Travel scheduled"
                    }
                    isTravelHold -> "Travel hold — awaiting travel proof"
                    isWakeHold -> "Wake-up verification pending"
                    isNotExcused -> actDetails.optString("failure_reason").ifBlank { actDetails.optString("suppression_reason", "Not excused") }
                    state == "EXCUSED" -> when {
                        actDetails.optBoolean("suppressed_by_bath", false) || actDetails.optString("suppression_reason").contains("bath", ignoreCase = true) || actDetails.optString("bath_activity_id").isNotBlank() -> "Excused — Scheduled Bath Activity"
                        actDetails.optBoolean("suppressed_by_exam", false) || actDetails.optString("suppression_reason").contains("exam", ignoreCase = true) || actDetails.optString("suppression_reason").contains("examination", ignoreCase = true) -> actDetails.optString("suppression_reason").ifBlank { "Excused — Approved Examination" }
                        actDetails.optString("attendance_status") == "EXCUSED_NO_POINTS" || isPostExamSlot -> "Excused — no submission required, no points awarded"
                        actDetails.optString("reconciliation_status") == "EXCUSED_BY_GYM" || actDetails.optBoolean("gym_excused", false) -> "Excused · Covered by verified Gym workout"
                        actDetails.optBoolean("suppressed_by_gym", false) || actDetails.optBoolean("gym_hold", false) -> "Excused · Covered by verified Gym workout"
                        actDetails.optString("suppression_reason").isNotBlank() -> actDetails.optString("suppression_reason")
                        else -> "Excused from schedule"
                    }
                    state == "PENDING_SYNC" -> "Proof saved on this device · awaiting server confirmation"
                    state == "EXPIRED" -> activity.eligibilityReason.ifBlank { "No submission before closing" }
                    isVerified -> {
                        val pts = if (approvedProofPoints > 0) approvedProofPoints else activity.configuredPoints
                        if (isPostExamSlot) {
                            "Approved · Full points (+$pts pts) • +1 Bonus Point Awarded"
                        } else if (pts == 8 || pts == 15 || pts == 10 || pts == 5) "Approved · Full points (+$pts pts)"
                        else "Approved · Partial points (+$pts pts)"
                    }
                    isAdminReview -> {
                        val specReason = actDetails.optString("review_reason").takeIf { it.isNotBlank() }
                            ?: review?.optString("reason_note")?.takeIf { it.isNotBlank() }
                            ?: eval?.let { e ->
                                runCatching { JSONObject(e.optString("evaluator_output_json", "{}")).optString("status_message") }.getOrNull()
                            }?.takeIf { it.isNotBlank() }
                            ?: "Awaiting administrator review"
                        "Awaiting admin review · $specReason"
                    }
                    isSubmitted -> "Submission received · validation pending"
                    isOpen -> if (isPostExamSlot) "Optional Attendance • Bonus point: +1" else if (activity.submissionEligible || activity.type == "HOURLY") "Submission window is open" else "Window open · ${activity.eligibilityReason}"
                    isRejected -> {
                        var reason = eval?.let { e ->
                            val outJson = runCatching { JSONObject(e.optString("evaluator_output_json", "{}")) }.getOrNull()
                            outJson?.optString("reason")?.takeIf { it.isNotBlank() }
                                ?: outJson?.optString("rejection_reason")?.takeIf { it.isNotBlank() }
                        }
                        if (reason.isNullOrBlank()) {
                            reason = review?.optString("reason_note")?.takeIf { it.isNotBlank() }
                                ?: review?.optString("reason_category")?.takeIf { it.isNotBlank() }
                                ?: actDetails.optString("rejection_reason").takeIf { it.isNotBlank() }
                                ?: actDetails.optString("failure_reason").takeIf { it.isNotBlank() }
                        }
                        cleanUserFacingText(reason?.takeIf { it.isNotBlank() } ?: "Proof Rejected & Locked · Duplicate evidence detected")
                    }
                    isBath -> "Scheduled activity · No proof required"
                    isExcusedByBath -> "This proof window overlaps your scheduled Bath activity. No submission required." 
                    isMissed -> {
                        if (isExcusedByBath) {
                            "This proof window overlaps your scheduled Bath activity. No submission required."
                        } else if (isPostExamSlot && !hasRealSubmission) {
                            "Excused — no submission required, no points awarded"
                        } else {
                            val fail = actDetails.optString("failure_reason")
                            val supp = actDetails.optString("suppression_reason")
                            if (fail.isNotBlank()) fail
                            else if (supp.isNotBlank() && !actDetails.optBoolean("suppressed_by_bath", false)) supp
                            else "No submission recorded before the window closed"
                        }
                    }
                    activity.type == "GYM" && isVerified -> "Gym workout verified (+15 pts)"
                    activity.type == "GYM" && isSubmitted -> "Gym proof submitted · awaiting evaluation"
                    activity.type == "GYM" && (state == "OPEN" || state == "UPCOMING") -> "Planned Gym session"
                    isPostExamSlot && !hasRealSubmission -> "Optional Attendance • Bonus point: +1"
                    activity.type == "HOURLY" -> "Normal attendance required · Window opens at ${startTime.ifEmpty { "the scheduled time" }}"
                    else -> "Window opens at " + startTime.ifEmpty { "the scheduled time" }
                }
                val pointsLabel = when {
                    isBath -> "0 PTS (EXEMPT)"
                    isExcusedByBath -> "0 PTS (EXCUSED)"
                    isTravelDemo -> "0 PTS (DEMO)"
                    isTravelReal -> when (travelAuthState) {
                        TravelBookingRules.TravelStatusState.VERIFIED -> "VERIFIED · +${if (approvedProofPoints > 0) approvedProofPoints else activity.configuredPoints} PTS"
                        TravelBookingRules.TravelStatusState.SUBMITTED_PENDING_REVIEW -> "POINTS PENDING"
                        TravelBookingRules.TravelStatusState.MISSED -> "MISSED · 0 PTS"
                        TravelBookingRules.TravelStatusState.REJECTED -> "REJECTED · 0 PTS"
                        else -> "TARGET · ${activity.configuredPoints} PTS"
                    }
                    isTravelHold -> "TRAVEL HOLD · 0 PTS"
                    isWakeHold -> "WAKE HOLD · 0 PTS"
                    isNotExcused -> "NOT EXCUSED · 0 PTS"
                    isPostExamSlot && isVerified -> "VERIFIED · +${if (approvedProofPoints > 0) approvedProofPoints else activity.configuredPoints} PTS (+1 BONUS)"
                    isPostExamSlot && (state == "EXCUSED" || (!hasRealSubmission && isMissed)) -> "0 PTS"
                    state == "EXCUSED" -> "0 PTS"
                    isVerified && approvedProofPoints > 0 -> "VERIFIED · +$approvedProofPoints PTS"
                    isVerified -> "VERIFIED · 0 PTS"
                    isSubmitted -> "POINTS PENDING"
                    isMissed || isRejected -> if (isMissed) "MISSED · 0 PTS" else "REJECTED · 0 PTS"
                    activity.configuredPoints > 0 -> "TARGET · " + activity.configuredPoints + " PTS"
                    else -> "POINT TARGET NOT RECORDED"
                }

                val isCardActiveOpen = if (isTravelReal) (travelAuthState == TravelBookingRules.TravelStatusState.SUBMISSION_OPEN) else (!isTravelDemo && isOpen)
                val checkpointCard = designCard(paddingDp = 12, cornerDp = 16, strokeHex = if (isCardActiveOpen) CLR_GREEN else CLR_BORDER).apply {
                    layoutParams = LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                    ).apply { bottomMargin = dp(8) }
                }
                val checkpointTop = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.CENTER_VERTICAL
                }
                checkpointTop.addView(TextView(this).apply {
                    text = if (isVerified) "✓" else if (isOpen) "●" else "○"
                    textSize = 12f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(tint))
                    gravity = Gravity.CENTER
                    layoutParams = LinearLayout.LayoutParams(dp(18), dp(18)).apply { rightMargin = dp(8) }
                })
                checkpointTop.addView(TextView(this).apply {
                    text = timeRange
                    textSize = 13f
                    setTypeface(Typeface.MONOSPACE, Typeface.BOLD)
                    tag = "telemetry_type"
                    setTextColor(Color.parseColor(if (isOpen) CLR_GREEN else CLR_TEXT_PRIMARY))
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                })
                checkpointTop.addView(designStatusPill(statusLabel, tint))
                checkpointCard.addView(checkpointTop)
                val activityCategory = review?.optString("category")?.takeIf { it.isNotBlank() && !it.equals("Unavailable", ignoreCase = true) }
                    ?: db.getScheduledActivityCategory(activity.activityId).takeIf { it.isNotBlank() && !it.equals("Unavailable", ignoreCase = true) }
                    ?: runCatching { JSONObject(activity.detailsJson).optString("category") }.getOrNull()?.takeIf { it.isNotBlank() && !it.equals("Unavailable", ignoreCase = true) }
                    ?: runCatching { JSONObject(activity.detailsJson).optString("activity_category") }.getOrNull()?.takeIf { it.isNotBlank() && !it.equals("Unavailable", ignoreCase = true) }
                    ?: ""
                if (activityCategory.isNotBlank() || isPostExamSlot) {
                    val metaBadgesRow = LinearLayout(this).apply {
                        orientation = LinearLayout.HORIZONTAL
                        gravity = Gravity.CENTER_VERTICAL
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                            topMargin = dp(4)
                        }
                    }
                    if (activityCategory.isNotBlank()) {
                        metaBadgesRow.addView(TextView(this).apply {
                            text = activityCategory
                            textSize = 9.5f
                            setTypeface(typeface, Typeface.BOLD)
                            setTextColor(Color.parseColor(CLR_CYAN))
                            setPadding(dp(7), dp(2.5f), dp(7), dp(2.5f))
                            background = surfaceBg(CLR_SURFACE_LOW, 8, CLR_CYAN, 1)
                            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { rightMargin = dp(6) }
                        })
                    }
                    if (isPostExamSlot) {
                        val peBadgeText = when {
                            isVerified -> "+1 Bonus Point Awarded"
                            state == "EXCUSED" || (isMissed && !hasRealSubmission) -> "Excused (0 pts)"
                            else -> "Optional Attendance • Bonus point: +1"
                        }
                        val peBadgeClr = when {
                            isVerified -> CLR_GREEN
                            state == "EXCUSED" || (isMissed && !hasRealSubmission) -> CLR_TEXT_DIM
                            else -> CLR_CYAN
                        }
                        metaBadgesRow.addView(TextView(this).apply {
                            text = peBadgeText
                            textSize = 9.5f
                            setTypeface(typeface, Typeface.BOLD)
                            setTextColor(Color.parseColor(peBadgeClr))
                            setPadding(dp(7), dp(2.5f), dp(7), dp(2.5f))
                            background = surfaceBg(CLR_SURFACE_LOW, 8, peBadgeClr, 1)
                        })
                    }
                    checkpointCard.addView(metaBadgesRow)
                }
                checkpointCard.addView(TextView(this).apply {
                    text = title
                    textSize = 13f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(7)
                    }
                })
                val detailRow = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.CENTER_VERTICAL
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(4)
                    }
                }
                detailRow.addView(TextView(this).apply {
                    text = detail
                    textSize = 10.5f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                })
                detailRow.addView(TextView(this).apply {
                    text = pointsLabel
                    textSize = 10f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(if (isMissed || isRejected) CLR_TEXT_DIM else tint))
                })
                checkpointCard.addView(detailRow)
                if (activity.type == "BATH" || activity.activityId.contains("BATH")) {
                    val bWin = db.getSavedBathSchedule(activity)
                    val bathFieldsLayout = LinearLayout(this).apply {
                        orientation = LinearLayout.VERTICAL
                        setPadding(dp(10), dp(8), dp(10), dp(8))
                        background = surfaceBg(CLR_ELEVATED, 10, CLR_BORDER, 1)
                        layoutParams = LinearLayout.LayoutParams(
                            ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                        ).apply { topMargin = dp(6) }
                    }
                    fun addBathField(label: String, value: String) {
                        bathFieldsLayout.addView(TextView(this).apply {
                            text = "$label: $value"
                            textSize = 10.5f
                            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(2) }
                        })
                    }
                    addBathField("Bath Interval", bWin.activityIntervalDisplay)
                    addBathField("Status", "Scheduled activity · No proof required")
                    checkpointCard.addView(bathFieldsLayout)
                }
                val evidenceId = review?.optString("evidence_id").orEmpty()
                val reviewDecision = when {
                    isVerified && approvedProofPoints > 0 -> "Approved (+$approvedProofPoints pts) · ${review?.optString("reviewed_by").takeIf { !it.isNullOrBlank() } ?: "Taufa_AI"}"
                    isVerified -> "Approved · ${review?.optString("reviewed_by").takeIf { !it.isNullOrBlank() } ?: "Taufa_AI"}"
                    isRejected -> "Rejected (0 pts) · ${review?.optString("reviewed_by").takeIf { !it.isNullOrBlank() } ?: "AI_Reviewer"}"
                    review == null -> "Not recorded"
                    review.optString("status").equals("PENDING", ignoreCase = true) || review.optString("status").equals("NEEDS_REVIEW", ignoreCase = true) -> {
                        val r = review.optString("reason_note").takeIf { it.isNotBlank() } ?: "Awaiting administrator review"
                        "Awaiting review · $r"
                    }
                    review.optString("decision").isNotBlank() -> review.optString("decision") + " · " + review.optString("reviewed_by", "reviewer")
                    else -> review.optString("status", "Not recorded")
                }
                val activityDetails = runCatching { JSONObject(activity.detailsJson) }.getOrDefault(JSONObject())
                val activityDescription = listOf("user_description", "description", "activity_description")
                    .map { activityDetails.optString(it) }.firstOrNull { it.isNotBlank() }.orEmpty()
                val linkedEvents = proofApprovedScoreEvents.filter { event ->
                    val audit = event.optJSONObject("audit") ?: JSONObject()
                    val auditActId = audit.optString("activity_id")
                    val auditEvId = audit.optString("evidence_id")
                    val scoreEvId = activityDetails.optString("score_event_id")
                    (auditActId.isNotBlank() && auditActId == activity.activityId) ||
                        (evidenceId.isNotBlank() && auditEvId == evidenceId) ||
                        (scoreEvId.isNotBlank() && scoreEvId == event.optString("event_id"))
                }
                val verifiedActivityPoints = when {
                    linkedEvents.isNotEmpty() -> linkedEvents.sumOf { it.optInt("points").coerceAtLeast(0) }
                    isVerified && approvedProofExists -> approvedProofPoints.coerceAtLeast(0)
                    else -> 0
                }
                val rejectedActivityPoints = linkedEvents.sumOf { kotlin.math.abs(it.optInt("points").coerceAtMost(0)) }
                val isExpanded = expandedDailyActivityId == activity.activityId
                checkpointCard.addView(TextView(this).apply {
                    text = if (isExpanded) "Hide activity details  ▴" else "View activity details  ▾"
                    textSize = 10f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(CLR_CYAN))
                    setPadding(0, dp(8), 0, dp(2))
                    applySpringTouch {
                        expandedDailyActivityId = if (isExpanded) null else activity.activityId
                        refreshUi()
                    }
                })
                if (isExpanded) {
                    val submissionTime = if (hasRealSubmission) {
                        review?.optString("submitted_at")?.takeIf { it.isNotBlank() }
                            ?: activity.submittedAt?.takeIf { it.isNotBlank() } ?: "None recorded"
                    } else {
                        "None recorded"
                    }
                    val reason = when {
                        review?.optString("reason_note")?.isNotBlank() == true -> review.optString("reason_note")
                        review?.optString("reason_category")?.isNotBlank() == true -> review.optString("reason_category")
                        activityDetails.optString("failure_reason").isNotBlank() -> activityDetails.optString("failure_reason")
                        activityDetails.optString("suppression_reason").isNotBlank() -> activityDetails.optString("suppression_reason")
                        isMissed -> "No submission was recorded before the window closed."
                        isRejected -> "No rejection reason was recorded."
                        else -> "None recorded"
                    }
                    val configuredPoints = if (activity.configuredPoints > 0) activity.configuredPoints.toString() + " pts" else "Not recorded"
                    val pointRefs = linkedEvents.joinToString { it.optString("event_id") }.ifBlank { "No linked transaction" }
                    val bookingId = TravelBookingRules.formatBookingReference(
                        activityDetails.optString("booking_id"),
                        activity.type == "TRAVEL" && activityDetails.optBoolean("is_prebooked", false)
                    )
                    val schedVerText = TravelBookingRules.formatScheduleVersion(activity.scheduleVersion)
                    val localEval = db.getProofEvaluationByActivity(activity.activityId, reportDate)
                    val evalStatus = TravelBookingRules.formatAiAnalysisStatus(
                        submittedAt = activity.submittedAt,
                        reviewStatus = review?.optString("status"),
                        reviewPoints = review?.optInt("points_awarded", 0) ?: 0,
                        localEvalStatus = localEval?.optString("status"),
                        localEvalPoints = localEval?.optInt("points_awarded", 0) ?: 0
                    )
                    val syncInfo = db.getActivitySyncInfo(activity.activityId, reportDate)
                    val evidenceStatus = if (hasRealSubmission) {
                        if (evidenceId.isNotBlank()) "Received ($evidenceId)" else "Received"
                    } else {
                        "Not submitted"
                    }
                    val detailsText = buildString {
                        if (bookingId.isNotBlank()) append("Booking ID: $bookingId\n")
                        append("Activity ID: " + activity.activityId + "\n")
                        if (activityCategory.isNotBlank()) append("Category: " + activityCategory + "\n")
                        append("Schedule version: " + schedVerText + "\n")
                        if (activity.type == "TRAVEL") {
                            val depTime = activityDetails.optString("departure_time").ifBlank { windowClock12h(activity.scheduledTime) }
                            val durHours = activityDetails.optInt("duration_hours", 3)
                            val proofOpen = windowClock12h(activity.windowStart)
                            val proofClose = windowClock12h(activity.windowEnd)
                            append("Departure: $depTime · Expected duration: ${durHours}h\n")
                            append("Proof window: $proofOpen – $proofClose\n")
                        } else if (activity.type == "GYM") {
                            val plannedStart = windowClock12h(activity.scheduledTime)
                            val durMins = activityDetails.optInt("duration_minutes", 90)
                            val expFinish = activityDetails.optString("expected_finish").ifBlank {
                                GymWindowRules.calculateGymWindow(reportDate, activity.scheduledTime.takeLast(5), durMins).expectedFinishDisplay
                            }
                            val actFinish = activityDetails.optString("actual_finish")
                            val proofOpen = windowClock12h(activity.windowStart)
                            val proofClose = windowClock12h(activity.windowEnd)
                            val verifiedStart = activityDetails.optString("verified_gym_start")
                            val actualEnd = activityDetails.optString("actual_gym_end")
                            val reconciledArr = activityDetails.optJSONArray("reconciled_hourly_occurrences")
                            val reconciledCount = reconciledArr?.length() ?: 0
                            append("Planned start: $plannedStart · Expected duration: ${durMins}m\n")
                            append("Expected finish: $expFinish\n")
                            if (verifiedStart.isNotBlank() && actualEnd.isNotBlank()) {
                                append("Verified workout: ${windowClock12h(verifiedStart)} – ${windowClock12h(actualEnd)}\n")
                            } else if (actFinish.isNotBlank()) {
                                append("Actual finish: " + windowClock12h(actFinish) + " (Early finish)\n")
                            }
                            append("Proof window: $proofOpen – $proofClose\n")
                            if (isVerified && reconciledCount > 0) {
                                append("Reconciled hourly slots: $reconciledCount excused\n")
                            }
                        } else if (activity.type == "BATH" || activity.activityId.contains("BATH")) {
                            val bWin = db.getSavedBathSchedule(activity)
                            append("Bath Interval: ${bWin.activityIntervalDisplay}\n")
                            append("Status: Scheduled activity · No proof required\n")
                        } else if (activity.type == "HOURLY") {
                            append("Target: " + windowClock12h(activity.scheduledTime) + " · Deadline: " + endTime + "\n")
                            if (activityDetails.optBoolean("suppressed_by_exam", false) || activityDetails.optString("suppression_reason").contains("exam", ignoreCase = true)) {
                                append("Attendance: ${activityDetails.optString("suppression_reason", "Excused — Approved Examination")}\n")
                                if (activityDetails.optString("exam_booking_id").isNotBlank()) append("Exam Booking: ${activityDetails.optString("exam_booking_id")}\n")
                                if (activityDetails.optString("exam_name").isNotBlank()) append("Exam Name: ${activityDetails.optString("exam_name")}\n")
                            }
                            if (isExcusedByBath) {
                                append("Attendance: EXCUSED – Bath overlap\n")
                                append("Reason: This proof window overlaps your scheduled Bath activity. No submission required.\n")
                                if (activityDetails.optString("bath_activity_interval").isNotBlank()) append("Bath Interval: ${activityDetails.optString("bath_activity_interval")}\n")
                                if (activityDetails.optString("bath_activity_id").isNotBlank()) append("Bath Occurrence: ${activityDetails.optString("bath_activity_id")}\n")
                            }
                            val recStatus = activityDetails.optString("reconciliation_status")
                            if (recStatus == "PRESERVED_USER_SUBMISSION") {
                                append("Gym reconciliation: User Submission Preserved (Overlaps Verified Gym Workout)\n")
                            } else if (recStatus == "EXCUSED_BY_GYM" || activityDetails.optBoolean("gym_excused", false)) {
                                append("Gym reconciliation: Excused by Verified Gym Workout\n")
                            }
                        } else {
                            append("Target: " + windowClock12h(activity.scheduledTime) + " · Deadline: " + endTime + "\n")
                        }
                        append("Submission: " + submissionTime + "\n")
                        append("Evidence: " + evidenceStatus + "\n")
                        append("AI analysis: " + evalStatus + "\n")
                        append("Administrator: " + reviewDecision + "\n")
                        append("Configured points: " + configuredPoints + "\n")
                        append("Provisional points: " + if (state in setOf("AI_PROVISIONAL", "ADMIN_REVIEW", "UNDER_REVIEW", "NEEDS_REVIEW", "DUPLICATE_REVIEW")) "Amount not recorded per activity" else "0")
                        append("\nVerified points: " + verifiedActivityPoints + " · Rejected/revoked: " + rejectedActivityPoints + "\n")
                        append("Point transaction IDs: " + pointRefs + "\n")
                        append("Sync: " + syncInfo.displayLabel + "\n")
                        if (evidenceId.isNotBlank()) append("Evidence ID: " + evidenceId + "\n")
                        if (activityDescription.isNotBlank()) append("Description: " + activityDescription + "\n")
                        if (isMissed || isRejected) append("Reason: " + reason)
                    }
                    checkpointCard.addView(TextView(this).apply {
                        text = detailsText
                        textSize = 10f
                        setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                        setPadding(dp(10), dp(8), dp(10), dp(8))
                        background = surfaceBg(CLR_ELEVATED, 10, CLR_BORDER, 1)
                    })
                }
                val isWakeUpActivity = activity.type.equals("WAKE_UP", ignoreCase = true) ||
                    activity.activityId.contains("WAKEUP", ignoreCase = true)
                if (isWakeUpActivity && !isVerified) {
                    val isSubmitted = reportSubmitted(activity)
                    val isWindowOpen = db.isWakeUpWindowOpen()
                    val btnText = when {
                        isSubmitted -> "⏳ SUBMITTED · PENDING REVIEW"
                        !isWindowOpen -> "🧪 TEST WAKE-UP VERIFICATION (DEMO)"
                        else -> "☀️ VERIFY WAKE-UP"
                    }
                    val btnColor = when {
                        isSubmitted -> CLR_AMBER
                        !isWindowOpen -> CLR_BORDER
                        else -> CLR_GREEN
                    }
                    val wakeBtn = makePrimaryButton(btnText, btnColor, widthMatchParent = true) {
                        if (isSubmitted) {
                            Toast.makeText(this, "Wake-up verification is submitted and pending review.", Toast.LENGTH_SHORT).show()
                        } else if (!isWindowOpen) {
                            WakeUpVerificationController.showWakeUpVerificationDialog(this, db, isDevMode = true) { refreshUi() }
                        } else {
                            showWakeUpVerificationDialog()
                        }
                    }.apply {
                        layoutParams = LinearLayout.LayoutParams(
                            ViewGroup.LayoutParams.MATCH_PARENT,
                            ViewGroup.LayoutParams.WRAP_CONTENT
                        ).apply { topMargin = dp(8) }
                    }
                    checkpointCard.addView(wakeBtn)
                    checkpointCard.applySpringTouch {
                        if (isSubmitted) {
                            Toast.makeText(this, "Wake-up verification is submitted and pending review.", Toast.LENGTH_SHORT).show()
                        } else if (!isWindowOpen) {
                            WakeUpVerificationController.showWakeUpVerificationDialog(this, db, isDevMode = true) { refreshUi() }
                        } else {
                            showWakeUpVerificationDialog()
                        }
                    }
                } else if (activity.type in listOf("HOURLY", "GYM", "TRAVEL") && !isExcusedByBath && state != "EXCUSED") {
                    if (activity.type == "TRAVEL") {
                        if (isTravelReal) {
                            when (travelAuthState) {
                                TravelBookingRules.TravelStatusState.SUBMISSION_OPEN -> {
                                    checkpointCard.addView(makePrimaryButton("SUBMIT TRAVEL PROOF", CLR_GREEN, widthMatchParent = true) {
                                        showTravelProofDialog(activity)
                                    })
                                }
                                TravelBookingRules.TravelStatusState.SUBMITTED_PENDING_REVIEW -> {
                                    checkpointCard.addView(makeSecondaryButton("⏳ SUBMITTED · PENDING REVIEW", CLR_AMBER) {
                                        Toast.makeText(this, "Travel proof submitted and pending review.", Toast.LENGTH_SHORT).show()
                                    }.apply {
                                        layoutParams = LinearLayout.LayoutParams(
                                            ViewGroup.LayoutParams.MATCH_PARENT,
                                            ViewGroup.LayoutParams.WRAP_CONTENT
                                        ).apply { topMargin = dp(6) }
                                    })
                                }
                                TravelBookingRules.TravelStatusState.PREBOOKED,
                                TravelBookingRules.TravelStatusState.TRAVEL_IN_PROGRESS,
                                TravelBookingRules.TravelStatusState.PROOF_OPENS_SOON -> {
                                    val openTimeStr = if (arrTimeStr.isNotBlank()) arrTimeStr else windowClock12h(activity.windowStart)
                                    checkpointCard.addView(makeSecondaryButton("⏳ PROOF OPENS AT $openTimeStr", CLR_TEXT_SECONDARY) {
                                        Toast.makeText(this, "Proof submission opens on arrival at $openTimeStr (until $proofEndStr).", Toast.LENGTH_SHORT).show()
                                    }.apply {
                                        layoutParams = LinearLayout.LayoutParams(
                                            ViewGroup.LayoutParams.MATCH_PARENT,
                                            ViewGroup.LayoutParams.WRAP_CONTENT
                                        ).apply { topMargin = dp(6) }
                                    })
                                }
                                else -> {
                                    // MISSED / REJECTED: no submission action allowed; card status and audit details explain why
                                }
                            }
                        }
                    } else {
                        val nowMs = db.authoritativeNowMs()
                        val sMs = db.parseIsoToMs(activity.windowStart)
                        val eMs = db.parseIsoToMs(activity.windowEnd)
                        val isWindowTimeOpen = (sMs != Long.MIN_VALUE && eMs != Long.MIN_VALUE && nowMs in sMs until eMs)
                        val canSubmit = (isOpen || (isWindowTimeOpen && !isMissed && !isRejected)) && (activity.submissionEligible || activity.type == "HOURLY") && !isRejected && !isBath && activity.status != "EXCUSED" && state != "EXCUSED" && !isExcusedByBath
                        if (canSubmit) {
                            if (activity.type == "GYM") {
                                checkpointCard.addView(makePrimaryButton("SUBMIT GYM PROOF", CLR_GREEN, widthMatchParent = true) {
                                    showGymProofDialog(activity)
                                })
                            } else {
                                val btnText = if (isVerified || isSubmitted) "SUBMIT ANOTHER PROOF" else "SUBMIT ${activity.type} PROOF"
                                checkpointCard.addView(makePrimaryButton(btnText, CLR_GREEN, widthMatchParent = true) {
                                    showHourlySubmissionDialog(activity)
                                })
                            }
                        } else if (isRejected && activity.type == "HOURLY") {
                            checkpointCard.addView(makeSecondaryButton("❌ VIEW REJECTION DETAILS", CLR_RED) {
                                showHourlySubmissionDialog(activity)
                            }.apply {
                                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                                    topMargin = dp(6)
                                }
                            })
                        } else if (activity.type == "GYM" && !isVerified && !isSubmitted && !isMissed && !isRejected) {
                            if (sMs != Long.MIN_VALUE && nowMs < sMs) {
                                checkpointCard.addView(makePrimaryButton("FINISHED GYM EARLY", CLR_CYAN, widthMatchParent = true) {
                                    db.finishGymEarly(activity.activityId)
                                    val updatedAct = db.getDailyActivities(reportDate).firstOrNull { it.activityId == activity.activityId } ?: activity
                                    showGymProofDialog(updatedAct)
                                    refreshUi()
                                }.apply {
                                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                                        topMargin = dp(6)
                                    }
                                })
                            }
                        }
                        if (activity.type == "GYM" && (isVerified || isSubmitted || activity.status in listOf("VERIFIED", "COMPLETED", "SUBMITTED", "VALIDATING"))) {
                            checkpointCard.addView(makeSecondaryButton("🔍 VIEW WORKOUT ANALYSIS", CLR_CYAN) {
                                MiFitnessGymWorkoutController.showGymProofDetailsDialog(this, db, activity)
                            }.apply {
                                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                                    topMargin = dp(6)
                                }
                            })
                        }
                    }
                }
                contentContainer.addView(checkpointCard)
            }

            if (hourlyActivities.size > visibleCheckpoints.size) {
                val expandLabel = if (showAllHourlyCheckpoints) "SHOW NEARBY CHECKPOINTS" else "VIEW ALL ${hourlyActivities.size} CHECKPOINTS"
                val scheduleToggle = makeSecondaryButton(expandLabel, CLR_CYAN) {
                    showAllHourlyCheckpoints = !showAllHourlyCheckpoints
                    refreshUi()
                }.apply {
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        bottomMargin = dp(8)
                    }
                }
                contentContainer.addView(scheduleToggle)
            }
        }

        contentContainer.addView(sectionHeading("DAILY ROUTINE & ACTIVITY REPORT", "$reportDate · ${reportActivities.size} activities"))
        contentContainer.addView(reportGrid)
        contentContainer.addView(reportPointsSummary)

        // ── Section: Wake-Up Wizard ────────────────────────
        contentContainer.addView(sectionHeading("WAKE-UP PROTOCOL", if (camOk && btOk && trkOk) "✓ VERIFIED" else "☀️ Open Flow") {
            showWakeUpVerificationDialog()
        })

        // Wake-up step indicator bar
        val stepBar = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(16), dp(14), dp(16), dp(14))
            background = surfaceBg(CLR_SURFACE, 20)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
            applySpringTouch { showWakeUpVerificationDialog() }
        }
        data class WakeStep(val icon: String, val label: String, val done: Boolean)
        listOf(
            WakeStep("⚡", "Wake-Up", camOk),
            WakeStep("🎧", "Earphones", btOk),
            WakeStep("🔥", "Track", trkOk)
        ).forEachIndexed { i, step ->
            val stepCol = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                gravity = Gravity.CENTER
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            }
            val circle = TextView(this).apply {
                text = if (step.done) "✓" else "${i + 1}"
                textSize = 13f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                gravity = Gravity.CENTER
                background = surfaceBg(
                    if (step.done) CLR_GREEN else if (i == listOf(camOk, btOk, trkOk).indexOfFirst { !it }) CLR_BLUE else CLR_SURFACE_LOW,
                    99
                )
                val sz = dp(32)
                layoutParams = LinearLayout.LayoutParams(sz, sz).apply { bottomMargin = dp(4) }
            }
            stepCol.addView(circle)
            stepCol.addView(TextView(this).apply {
                text = step.icon + " " + step.label
                textSize = 9.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(if (step.done) CLR_GREEN else CLR_TEXT_SECONDARY))
                gravity = Gravity.CENTER
            })
            stepBar.addView(stepCol)
            if (i < 2) {
                stepBar.addView(View(this).apply {
                    background = surfaceBg(if (listOf(camOk, btOk, trkOk)[i]) CLR_GREEN else CLR_TEXT_DIM, 4)
                    layoutParams = LinearLayout.LayoutParams(dp(20), dp(2))
                })
            }
        }
        contentContainer.addView(stepBar)

        val openWakeUpFlowBtn = makePrimaryButton(
            if (camOk && btOk && trkOk) "☀️ WAKE-UP VERIFICATION COMPLETED ✓" else "☀️ OPEN 3-STEP WAKE-UP VERIFICATION",
            if (camOk && btOk && trkOk) CLR_CYAN else CLR_GREEN,
            widthMatchParent = true
        ) {
            showWakeUpVerificationDialog()
        }.apply {
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
        }
        contentContainer.addView(openWakeUpFlowBtn)

        // Three action cards
        data class WakeActionSpec(val title: String, val sub: String, val pts: String, val accent: String, val isDone: Boolean)
        listOf(
            WakeActionSpec("⚡ Step 1: Live Camera & Face Proof", "20-sec continuous live camera presence + face & eye verification", "+15 (+5 on-time)", CLR_BLUE, camOk),
            WakeActionSpec("🎧 Step 2: Bluetooth Earbuds Route", "Select Bluetooth earbuds (${db.getEarbudsConfig()}) & verify active audio route", "Required", CLR_VIOLET, btOk),
            WakeActionSpec("🔥 Step 3: Motivation Track (≤60% Vol)", "Full motivation track playback on earbuds with anti-seek & volume cap", "+20", CLR_GREEN, trkOk)
        ).forEach { spec ->
            val taskCard = buildPremiumTaskCard(
                title = spec.title, subtitle = spec.sub,
                points = spec.pts, accentHex = spec.accent,
                isDone = spec.isDone
            ) {
                when {
                    spec.title.contains("Step 1") || spec.title.contains("Wake-Up") -> showWakeUpVerificationDialog()
                    spec.title.contains("Step 2") || spec.title.contains("Blue")    -> verifyBluetoothNow()
                    spec.title.contains("Step 3") || spec.title.contains("Track")   -> playMotivationTrack()
                }
            }
            contentContainer.addView(taskCard)
        }

        // Track progress
        trackProgressBar = ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal).apply {
            max = 100
            progress = if (trkOk) 100 else 0
            progressTintList = android.content.res.ColorStateList.valueOf(Color.parseColor(CLR_GREEN))
            progressBackgroundTintList = android.content.res.ColorStateList.valueOf(Color.parseColor(CLR_SURFACE))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(6)).apply {
                bottomMargin = dp(16)
            }
        }
        contentContainer.addView(trackProgressBar)

        // ── Hourly check-in ────────────────────────────────
        contentContainer.addView(sectionHeading("HOURLY CHECK-IN",
            "${st.optInt("hourly_completed")}/15 logged"))

        val hourlyCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(16), dp(16), dp(16))
            background = surfaceBg(CLR_SURFACE, 18, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        }

        val targetAct = db.getActiveOrTargetHourlyActivity(db.nowDate())
        val homeNowMs = db.authoritativeNowMs()
        val homeActS = targetAct?.let { db.parseIsoToMs(it.windowStart) } ?: Long.MAX_VALUE
        val homeActE = targetAct?.let { db.parseIsoToMs(it.windowEnd) } ?: Long.MIN_VALUE
        val isWindowOpen = targetAct != null && homeNowMs in homeActS until homeActE
        val isUpcoming = targetAct != null && homeNowMs < homeActS

        val evalRecord = targetAct?.let { db.getProofEvaluationByActivity(it.activityId, db.nowDate()) }
        val evalOutJson = try {
            JSONObject(evalRecord?.optString("evaluator_output_json", "{}") ?: "{}")
        } catch (_: Exception) { JSONObject() }
        val statusLabel = evalOutJson.optString("status_label", "")
        val awardedPts = evalRecord?.optInt("points_awarded", targetAct?.points ?: 0) ?: targetAct?.points ?: 0

        val isAlreadySubmitted = targetAct != null && (
            targetAct.status in listOf("SUBMITTED", "VALIDATING", "VERIFIED", "APPROVED", "COMPLETED") ||
            !targetAct.submittedAt.isNullOrBlank() ||
            evalRecord != null ||
            db.getDailyProofReviews(db.nowDate()).any { it.optString("activity_id") == targetAct.activityId }
        )

        val isApproved = targetAct?.status in listOf("VERIFIED", "APPROVED", "COMPLETED") ||
                         evalRecord?.optString("status") in listOf("VERIFIED", "APPROVED") ||
                         statusLabel in listOf(ProofSubmissionRules.StatusLabels.APPROVED_FULL_POINTS, ProofSubmissionRules.StatusLabels.APPROVED_PARTIAL_POINTS)
        val isRejected = targetAct?.status in listOf("REJECTED", "REJECTED_LATE") ||
                         evalRecord?.optString("status") == "REJECTED" ||
                         statusLabel == ProofSubmissionRules.StatusLabels.REJECTED
        val isFailRetry = evalRecord?.optString("status") == ProofSubmissionRules.States.RETRYABLE_FAILURE ||
                          statusLabel == ProofSubmissionRules.StatusLabels.FAILED_RETRY_AVAILABLE

        val isTargetPostExam = targetAct != null && targetAct.type == "HOURLY" && (
            targetAct.detailsJson.contains("\"is_post_exam_class_time\":true") ||
            targetAct.detailsJson.contains("\"post_exam_bonus_eligible\":true") ||
            db.isPostExamBonusEligible(db.nowDate(), targetAct.activityId)
        )

        if (isTargetPostExam) {
            val peBadge = TextView(this).apply {
                text = when {
                    isApproved -> "🎓 +1 Bonus Point Awarded (Post-Exam Class)"
                    targetAct?.status == "EXCUSED" -> "Excused — no submission required, no points awarded"
                    else -> "Optional Attendance • Bonus point: +1"
                }
                textSize = 11.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(if (isApproved) CLR_GREEN else CLR_CYAN))
                setPadding(dp(12), dp(6), dp(12), dp(6))
                background = surfaceBg(if (isApproved) "#0B2B22" else CLR_SURFACE_LOW, 10, if (isApproved) CLR_GREEN else CLR_CYAN, 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(10)
                }
            }
            hourlyCard.addView(peBadge)
        }

        var descInput: EditText? = null

        if (isAlreadySubmitted) {
            val progressView = buildAiReviewProgressView(evalRecord, targetAct, onRetry = {
                targetAct?.let { act ->
                    ProofEvaluationManager.retryHourlyEvaluation(this@MainActivity, db, act.activityId, db.nowDate())
                    Toast.makeText(this@MainActivity, "Retrying AI review...", Toast.LENGTH_SHORT).show()
                    refreshUi()
                }
            })
            hourlyCard.addView(progressView)
        } else {
            hourlyCard.addView(TextView(this).apply {
                text = "WHAT DID YOU DO?"
                textSize = 11f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                letterSpacing = 0.08f
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(10) }
            })

            // Activity chips (updates in-place without reloading the screen)
            val chipScroll = HorizontalScrollView(this).apply {
                isHorizontalScrollBarEnabled = false
                overScrollMode = View.OVER_SCROLL_NEVER
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(14) }
            }
            val chipRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
            val activities = listOf("COLLEGE", "STUDY", "EDITING", "VIDEO SHOOT")
            val chipViews = mutableListOf<Pair<String, TextView>>()
            activities.forEach { act ->
                val actUpper = act.uppercase()
                val chip = makeChip(act, CLR_GREEN, selectedHourlyActivity == actUpper) {
                    selectedHourlyActivity = actUpper
                    chipViews.forEach { (code, tv) ->
                        val sel = code == selectedHourlyActivity
                        tv.setTypeface(tv.typeface, if (sel) Typeface.BOLD else Typeface.NORMAL)
                        tv.setTextColor(Color.parseColor(if (sel) "#FFFFFF" else CLR_TEXT_SECONDARY))
                        tv.background = if (sel) gradientBg(CLR_GREEN, darken(CLR_GREEN, 0.7f), 99)
                                        else surfaceBg(CLR_ELEVATED, 99, CLR_TEXT_DIM, 1)
                        tv.setPadding(dp(14), dp(8), dp(14), dp(8))
                    }
                }
                chip.layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { rightMargin = dp(8) }
                chipViews.add(actUpper to chip)
                chipRow.addView(chip)
            }
            chipScroll.addView(chipRow)
            hourlyCard.addView(chipScroll)

            hourlyCard.addView(TextView(this).apply {
                text = "WHAT DID YOU ACCOMPLISH?"
                textSize = 11f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                letterSpacing = 0.08f
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(8) }
            })

            val dInput = EditText(this).apply {
                hint = "Describe your last hour. Attach photo proof for review; points remain 0 until approval."
                textSize = 13f
                setTextColor(Color.WHITE)
                setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
                setPadding(dp(14), dp(12), dp(14), dp(12))
                background = surfaceBg(CLR_SURFACE_LOW, 14, CLR_TEXT_DIM, 1)
                minLines = 2
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(12) }
            }
            descInput = dInput
            hourlyCard.addView(dInput)

            val photoBtn = makeSecondaryButton(
                if (hourlyHasPhoto) "📎  $lastCapturedHourlyPhotoName attached ✓" else "📎  Attach required evidence", CLR_CYAN
            ) { showHourlyEvidenceSourceDialog() }
            hourlyAttachmentButton = photoBtn
            photoBtn.layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
            hourlyCard.addView(photoBtn)
        }

        lateinit var submitBtn: LinearLayout
        val btnTitle = when {
            isAlreadySubmitted -> {
                when {
                    isApproved && awardedPts == 8 -> "✅ APPROVED — FULL POINTS (8/8 PTS)"
                    isApproved -> "✅ APPROVED — PARTIAL POINTS ($awardedPts/8 PTS)"
                    isRejected -> "❌ SUBMISSION REJECTED (0 PTS)"
                    isFailRetry -> "🔄 RETRY AI REVIEW"
                    else -> "⏳ AI REVIEW IN PROGRESS (0 PTS)"
                }
            }
            isWindowOpen -> {
                val remSec = (homeActE - homeNowMs) / 1000L
                val mm = remSec / 60L
                val ss = remSec % 60L
                String.format(Locale.US, "⚡ SUBMIT PROOF (%02d:%02d REMAINING)", mm, ss)
            }
            isUpcoming -> {
                val wStartLabel = targetAct?.let { windowClock12h(it.windowStart) } ?: ""
                "HOURLY WINDOW OPENS AT $wStartLabel"
            }
            else -> "HOURLY WINDOW CLOSED"
        }
        val btnColor = when {
            isAlreadySubmitted -> when {
                isApproved -> CLR_GREEN
                isRejected -> CLR_RED
                isFailRetry -> CLR_CYAN
                else -> CLR_AMBER
            }
            isWindowOpen -> CLR_GREEN
            else -> CLR_SURFACE_LOW
        }
        submitBtn = makePrimaryButton(btnTitle, btnColor, widthMatchParent = true) {
            if (hourlySubmissionInProgress) return@makePrimaryButton
            val clickNowMs = db.authoritativeNowMs()
            val act = db.getActiveOrTargetHourlyActivity(db.nowDate())
            if (act == null) {
                Toast.makeText(this, "No scheduled checkpoint is available.", Toast.LENGTH_LONG).show()
                return@makePrimaryButton
            }
            if (isAlreadySubmitted) {
                if (isFailRetry) {
                    ProofEvaluationManager.retryHourlyEvaluation(this@MainActivity, db, act.activityId, db.nowDate())
                    Toast.makeText(this@MainActivity, "Retrying AI review...", Toast.LENGTH_SHORT).show()
                    refreshUi()
                } else {
                    showHourlySubmissionDialog(act)
                }
                return@makePrimaryButton
            }
            val actS = db.parseIsoToMs(act.windowStart)
            val actE = db.parseIsoToMs(act.windowEnd)
            if (clickNowMs < actS) {
                val startLabel = windowClock12h(act.windowStart)
                Toast.makeText(this, "Hourly submission window has not opened yet (opens at $startLabel).", Toast.LENGTH_LONG).show()
                return@makePrimaryButton
            }
            if (clickNowMs >= actE) {
                val endLabel = windowClock12h(act.windowEnd)
                Toast.makeText(this, "Hourly submission window closed at $endLabel. Late submissions cannot be accepted.", Toast.LENGTH_LONG).show()
                return@makePrimaryButton
            }
            if (selectedHourlyActivity.isBlank()) {
                Toast.makeText(this, "Select an activity category.", Toast.LENGTH_LONG).show()
                return@makePrimaryButton
            }
            val noteText = descInput?.text?.toString()?.trim() ?: ""
            if (noteText.isBlank()) {
                Toast.makeText(this, "Describe what you did during the last hour.", Toast.LENGTH_LONG).show()
                descInput?.requestFocus()
                return@makePrimaryButton
            }
            haptic(1)
            val hour = db.nowTime().take(2).toIntOrNull() ?: 10
            val proofBytes = lastCapturedHourlyPhotoBytes
            if (!hourlyHasPhoto || proofBytes == null || proofBytes.isEmpty()) {
                Toast.makeText(this, "Attach at least one image or supported file.", Toast.LENGTH_LONG).show()
                return@makePrimaryButton
            }
            if (act == null) {
                Toast.makeText(this, "No scheduled checkpoint is available.", Toast.LENGTH_LONG).show()
                return@makePrimaryButton
            }
            val timing = db.evaluateSubmissionTiming(act.activityId, db.authoritativeNowMs(), recordLocally = false)
            if (!timing.allowed && hourlyPendingSyncEventId == null) {
                Toast.makeText(this, timing.message, Toast.LENGTH_LONG).show()
                return@makePrimaryButton
            }
            val defaultSlot = String.format("%02d:00-%02d:00", (hour - 1).coerceAtLeast(0), hour)
            val slot = try {
                if (act != null) JSONObject(act.detailsJson).optString("hour_slot", defaultSlot) else defaultSlot
            } catch (_: Exception) {
                defaultSlot
            }
            submitBtn.isEnabled = false
            setPrimaryButtonLabel(submitBtn, "⏳ SUBMITTING...")
            Thread {
                try {
                    val receipt = ProofEvaluationManager.submitHourlyProof(
                        context = this@MainActivity,
                        db = db,
                        actId = act.activityId,
                        actType = act.type,
                        category = selectedHourlyActivity,
                        description = noteText,
                        attachments = listOf(AttachedProof(proofBytes, lastCapturedHourlyPhotoName.ifBlank { "evidence.jpg" })),
                        date = db.nowDate(),
                        isDevMode = isDevMode,
                        schedVer = act.scheduleVersion.coerceAtLeast(1),
                        slot = slot
                    )
                    uiHandler.post {
                        if (!receipt.success) {
                            submitBtn.isEnabled = true
                            setPrimaryButtonLabel(submitBtn, "⚡ SUBMIT HOURLY CHECK-IN")
                            Toast.makeText(this@MainActivity, receipt.message, Toast.LENGTH_LONG).show()
                            return@post
                        }
                        hourlyHasPhoto = false
                        lastCapturedHourlyPhotoBytes = null
                        lastCapturedHourlyPhotoName = "evidence.jpg"
                        updateHourlyEvidenceLabels()
                        hourlyPendingSubmissionId = null
                        hourlyPendingSyncEventId = null
                        selectedHourlyActivity = ""
                        descInput?.setText("")
                        triggerBotMessage(receipt.message, "SUCCESS")
                        Toast.makeText(this@MainActivity, receipt.message, Toast.LENGTH_LONG).show()
                        updateCountdownViews()
                        refreshUi()
                    }
                } catch (t: Throwable) {
                    Log.e("MainActivity", "Quick submission failed", t)
                    uiHandler.post {
                        submitBtn.isEnabled = true
                        setPrimaryButtonLabel(submitBtn, "⚡ SUBMIT HOURLY CHECK-IN")
                        Toast.makeText(this@MainActivity, "Submission failed: ${t.message}", Toast.LENGTH_LONG).show()
                        refreshUi()
                    }
                }
            }.start()
        }
        hourlyCard.addView(submitBtn)
        contentContainer.addView(hourlyCard)

        // ── Bath & Gym ─────────────────────────────────────
        contentContainer.addView(sectionHeading("TASKS"))

        val todayDate = db.nowDate()
        val isBathPlanConfirmed = db.isBathScheduleConfirmed(todayDate)
        val bathCount = db.getBathSubmissionCount(todayDate)
        val maxBaths = db.getMaxBathOccurrences(todayDate).coerceAtLeast(1)
        val bathDone = bathCount >= maxBaths
        val isCollege = db.getCollegeAttendance(todayDate) == "YES"
        val (canEditBath, _) = db.canEditTodayBathPlan(todayDate)

        val bathTitle: String
        val bathSub: String
        val bathClr: String
        val onBathClick: () -> Unit

        if (!isBathPlanConfirmed) {
            bathTitle = "🛁  BATH SCHEDULE UNCONFIRMED"
            bathSub = "Tap to configure today's bath plan"
            bathClr = CLR_AMBER
            onBathClick = { showBathScheduleConfirmationDialog(isEditing = false) }
        } else if (bathDone) {
            bathTitle = "🛁  Bath (Completed)"
            bathSub = "Scheduled activity · No proof required"
            bathClr = CLR_CYAN
            onBathClick = {
                if (canEditBath) {
                    showBathScheduleConfirmationDialog(isEditing = true)
                }
            }
        } else {
            val currentOccurrence = (bathCount + 1).coerceAtMost(maxBaths)
            val planned = db.getPlannedBathTime(currentOccurrence, isCollege, todayDate)
            val win = BathWindowRules.calculateBathWindow(currentOccurrence, isCollege, todayDate, planned, timezone = db.scheduleTimezone())
            bathTitle = "🛁  Bath – ${win.activityIntervalDisplay}"
            bathSub = "Scheduled activity · No proof required"
            bathClr = CLR_CYAN
            onBathClick = {
                if (canEditBath) {
                    showBathScheduleConfirmationDialog(isEditing = true)
                }
            }
        }

        val bgRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(10) }
        }
        bgRow.addView(buildPremiumTaskCard(bathTitle, bathSub, "0 PTS (EXEMPT)", bathClr, bathDone, isCompact = true, onTap = onBathClick))
        bgRow.addView(View(this).apply { layoutParams = LinearLayout.LayoutParams(dp(10), 1) })
        bgRow.addView(buildPremiumTaskCard("🏋️  Gym", "Proof review required", "0 until approved", CLR_PINK, gymOk, isCompact = true) {
            showActivityProofDialog("GYM")
        })
        contentContainer.addView(bgRow)

        val isTravelBooked = db.isTravelPrebooked(db.nowDate())
        val travelOccurrences = reportActivities.filter { it.type == "TRAVEL" }
        val travelDone = travelOccurrences.any { it.status in listOf("VERIFIED", "COMPLETED", "SUBMITTED", "VALIDATING", "PENDING_SYNC") }
        if (isTravelBooked) {
            val travelAct = travelOccurrences.firstOrNull()
            val travelDetails = runCatching { JSONObject(travelAct?.detailsJson ?: "{}") }.getOrNull()
            val travelStartMs = travelDetails?.optLong("proof_window_start_ms", 0L).takeIf { (it ?: 0L) > 0L }
                ?: travelDetails?.optLong("travel_end_ms", 0L).takeIf { (it ?: 0L) > 0L }
                ?: travelAct?.let { db.parseIsoToMs(it.windowStart) } ?: 0L
            val nowMs = db.authoritativeNowMs()
            val travelSubtitle = if (travelDone) {
                "Travel proof submitted ✓"
            } else if (travelStartMs > 0L && nowMs < travelStartMs) {
                val startStr = ScheduleClock.display(travelStartMs, db.scheduleTimezone(), "h:mm a")
                "Submission opens at $startStr"
            } else {
                "Photo proof & description required"
            }
            contentContainer.addView(buildPremiumTaskCard("🚗  Travel", travelSubtitle, "+10 pts on approval", CLR_PURPLE, travelDone, isCompact = false) {
                showActivityProofDialog("TRAVEL")
            })
        }
        contentContainer.addView(buildTravelPrebookingSection())
        contentContainer.addView(buildEmergencyTravelSection())
        contentContainer.addView(buildMoviePrebookingSection())
        contentContainer.addView(buildOfficialEventPrebookingSection())
        contentContainer.addView(buildExamPrebookingSection())
        contentContainer.addView(buildDailyPracticeTestSection())

        val gymOccurrence = reportActivities.firstOrNull { it.type == "GYM" && it.status in listOf("OPEN", "UPCOMING", "NOTIFIED", "SCHEDULED") }
        val gymSkipState = gymOccurrence?.let { db.getSyncEventState("gym_skip_${it.activityId}_${if (isDevMode) 1 else 0}").first }.orEmpty()
        val gymSkipped = gymOccurrence?.status == "SKIPPED" || st.optString("gym_status").contains("SKIPPED") || st.optInt("gym_penalty_points", 0) > 0
        if (gymOccurrence != null && !gymSkipped && gymOccurrence.status !in listOf("VERIFIED", "COMPLETED", "MISSED", "CLOSED", "EXPIRED")) {
            val skipBtn = makeSecondaryButton(if (gymSkipState == "PENDING") "Skip requested · pending sync" else "Skip Gym · configured penalty", CLR_RED) {
                val queued = db.completeGymSession(db.nowDate(), isDevMode, 0, skipped = true)
                refreshUi() // Disable repeated taps as soon as the durable request is saved.
                if (queued) Thread {
                    db.flushSyncEventsQueue(this@MainActivity)
                    runOnUiThread {
                        refreshUi()
                        Toast.makeText(this@MainActivity, "Skip status: ${db.getSyncEventState("gym_skip_${gymOccurrence.activityId}_${if (isDevMode) 1 else 0}").first}. Only a confirmed server transaction changes points.", Toast.LENGTH_LONG).show()
                    }
                }.start()
            }
            skipBtn.isEnabled = gymSkipState != "PENDING"
            contentContainer.addView(skipBtn)
        }


        // ── Score events ───────────────────────────────────
        contentContainer.addView(sectionHeading("SCORE AUDIT"))
        val events = db.getScoreEvents(db.nowDate(), isDevMode)
        if (events.length() == 0) {
            contentContainer.addView(buildEmptyState("📋", "No events yet", "Complete a task to start your audit trail."))
        } else {
            for (i in 0 until events.length()) {
                val ev = events.getJSONObject(i)
                val pts = ev.getInt("points")
                contentContainer.addView(buildEventRow(ev.getString("timestamp"), ev.getString("event_type"),
                    ev.getString("description"), pts) {
                    AlertDialog.Builder(this).setTitle("Audit: ${ev.getString("event_type")}")
                        .setMessage(ev.getJSONObject("audit").toString(2))
                        .setPositiveButton("Close", null).show()
                })
            }
        }

        // ── Gym Routine Statistics Dashboard (Extreme bottom of Tasks) ──
        contentContainer.addView(GymRoutineUi.createTasksDashboard(this, db, {
            activeTab = "PROFILE"
            refreshUi()
        }, {
            showDeviceCenterDialog()
        }))
    }

    // ── Premium task card (standalone full or compact half) ─
    private fun buildPremiumTaskCard(
        title: String, subtitle: String, points: String,
        accentHex: String, isDone: Boolean, isCompact: Boolean = false,
        onTap: () -> Unit
    ): View {
        val card = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(13), dp(12), dp(13), dp(12))
            background = if (isDone)
                surfaceBg(CLR_SURFACE, 18, accentHex, 1)
            else
                surfaceBg(CLR_SURFACE, 18, CLR_BORDER, 1)
            layoutParams = if (isCompact)
                LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            else
                LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(10)
                }
        }

        val titleRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(4) }
        }
        titleRow.addView(TextView(this).apply {
            text = title; textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        })
        if (isDone) {
            titleRow.addView(TextView(this).apply {
                text = "✓"
                textSize = 14f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(accentHex))
            })
        }
        card.addView(titleRow)
        card.addView(TextView(this).apply {
            text = subtitle; textSize = 10.5f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            maxLines = 2; ellipsize = TextUtils.TruncateAt.END
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(8) }
        })
        card.addView(TextView(this).apply {
            text = "⚡ $points"
            textSize = 12f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (isDone) accentHex else CLR_GREEN))
        })
        if (!isDone) {
            card.applySpringTouch { haptic(0); onTap() }
        }
        return card
    }

    // ── Single score event row ─────────────────────────────
    private fun buildEventRow(time: String, type: String, desc: String, pts: Int, onTap: () -> Unit): LinearLayout {
        val row = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(14), dp(12), dp(14), dp(12))
            background = surfaceBg(CLR_SURFACE, 16)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(8) }
            applySpringTouch { onTap() }
        }
        val accent = View(this).apply {
            background = surfaceBg(if (pts >= 0) CLR_GREEN else CLR_RED, 4)
            layoutParams = LinearLayout.LayoutParams(dp(4), dp(40)).apply { rightMargin = dp(12) }
        }
        row.addView(accent)
        val info = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        info.addView(TextView(this).apply {
            text = type; textSize = 12f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
        })
        info.addView(TextView(this).apply {
            text = "$desc • $time"; textSize = 10f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            maxLines = 1; ellipsize = TextUtils.TruncateAt.END
        })
        row.addView(info)
        row.addView(TextView(this).apply {
            text = if (pts >= 0) "+$pts" else "$pts"
            textSize = 14f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (pts >= 0) CLR_GREEN else CLR_RED))
        })
        return row
    }

