    // ════════════════════════════════════════════════════════
    // FOCUS & RESTRICTIONS TAB (Section 2, 7, 8, 9, 10)
    // ════════════════════════════════════════════════════════

    private fun updateFocusCountdownView() {
        if (focusCountdownLabel == null) return
        val activeSession = db.getActiveFocusSession() ?: return
        val status = activeSession.optString("status", "IDLE")
        val plannedEnd = activeSession.optString("planned_end_time", "")
        if (status == "ACTIVE" && plannedEnd.isNotEmpty()) {
            try {
                val sdf = SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.US)
                val endDt = sdf.parse(plannedEnd)?.time ?: 0L
                val now = System.currentTimeMillis()
                val diffSec = ((endDt - now) / 1000).coerceAtLeast(0)
                val mm = diffSec / 60
                val ss = diffSec % 60
                focusCountdownLabel?.text = String.format(Locale.US, "%02d:%02d", mm, ss)
                focusStatusBadge?.text = "● FOCUS IN PROGRESS"
                focusStatusBadge?.setTextColor(Color.parseColor(CLR_GREEN))
                val totalSec = activeSession.optInt("target_minutes", 25) * 60
                val elapsed = (totalSec - diffSec).coerceAtLeast(0)
                val progress = if (totalSec > 0) ((elapsed.toFloat() / totalSec) * 100).toInt().coerceIn(0, 100) else 0
                focusProgressBar?.progress = progress
            } catch (_: Exception) {}
        } else if (status == "PAUSED") {
            focusStatusBadge?.text = "⏸ PAUSED"
            focusStatusBadge?.setTextColor(Color.parseColor(CLR_AMBER))
        }
    }

    private fun renderFocusTab(st: org.json.JSONObject, score: Int) {
        val activeSession = db.getActiveFocusSession()
        val isFocusActive = activeSession != null
        val focusStatus = activeSession?.optString("status", "IDLE") ?: "IDLE"
        val isPaused = focusStatus == "PAUSED"
        val settings = db.getFocusSettings()
        val isStrictMode = settings.optBoolean("strict_mode", true)
        val isStudyMode = settings.optBoolean("youtube_study_mode", true)
        val isDndMode = settings.optBoolean("block_notifications", true)
        val sessionGoal = activeSession?.optString("goal", "Deep Work & Coding Sprint") ?: "Deep Work & Coding Sprint"
        val durationMins = activeSession?.optInt("target_minutes", selectedFocusDurationMinutes) ?: selectedFocusDurationMinutes
        val remSeconds = activeSession?.optInt("remaining_seconds", durationMins * 60) ?: (durationMins * 60)

        contentContainer.addView(sectionHeading("FOCUS & RESTRICTIONS", "⚙️ Settings") {
            showFocusSettingsSheet()
        })

        // 1. HERO FOCUS CARD
        val heroCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            gravity = Gravity.CENTER_HORIZONTAL
            setPadding(dp(22), dp(24), dp(22), dp(24))
            background = if (isFocusActive) {
                gradientBg("#170B28", "#250F3E", 28, strokeHex = CLR_VIOLET)
            } else {
                gradientBg(CLR_SURFACE_LOW, CLR_SURFACE, 28, strokeHex = CLR_INDIGO)
            }
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        }

        val heroBadgeRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(16) }
        }
        val statusBadge = TextView(this).apply {
            text = when {
                !isFocusActive -> "○ READY TO FOCUS"
                isPaused -> "⏸ PAUSED"
                else -> "● FOCUS IN PROGRESS"
            }
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(when {
                !isFocusActive -> CLR_TEXT_SECONDARY
                isPaused -> CLR_AMBER
                else -> CLR_GREEN
            }))
            background = surfaceBg(when {
                !isFocusActive -> CLR_SURFACE
                isPaused -> "#332600"
                else -> "#0F2E1E"
            }, 99, when {
                !isFocusActive -> CLR_TEXT_DIM
                isPaused -> CLR_AMBER
                else -> CLR_GREEN
            }, 1)
            setPadding(dp(10), dp(4), dp(10), dp(4))
            letterSpacing = 0.05f
        }
        focusStatusBadge = statusBadge
        heroBadgeRow.addView(statusBadge)

        heroBadgeRow.addView(View(this).apply {
            layoutParams = LinearLayout.LayoutParams(0, 0, 1f)
        })

        val modeBadge = TextView(this).apply {
            text = if (isStudyMode) "📺 YouTube Study" else if (isStrictMode) "🔒 Strict Lock" else "⚡ Standard"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            background = surfaceBg(CLR_SURFACE, 99, CLR_CYAN, 1)
            setPadding(dp(10), dp(4), dp(10), dp(4))
            letterSpacing = 0.04f
        }
        heroBadgeRow.addView(modeBadge)
        heroCard.addView(heroBadgeRow)

        val timerLabel = TextView(this).apply {
            text = String.format(Locale.US, "%02d:%02d", remSeconds / 60, remSeconds % 60)
            textSize = 48f
            setTypeface(Typeface.MONOSPACE, Typeface.BOLD)
            tag = "telemetry_type"
            setTextColor(Color.WHITE)
            gravity = Gravity.CENTER
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
        }
        focusCountdownLabel = timerLabel
        heroCard.addView(timerLabel)

        val initProgress = if (isFocusActive && durationMins > 0) {
            (((durationMins * 60 - remSeconds).toFloat() / (durationMins * 60)) * 100).toInt().coerceIn(0, 100)
        } else 0
        val pBar = ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal).apply {
            max = 100
            progress = initProgress
            progressTintList = ColorStateList.valueOf(Color.parseColor(if (isFocusActive) CLR_VIOLET else CLR_INDIGO))
            progressBackgroundTintList = ColorStateList.valueOf(Color.parseColor(CLR_SURFACE))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(8)).apply {
                bottomMargin = dp(14)
            }
        }
        focusProgressBar = pBar
        heroCard.addView(pBar)

        val goalTv = TextView(this).apply {
            text = "🎯 $sessionGoal"
            textSize = 13f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            gravity = Gravity.CENTER
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(18) }
        }
        focusGoalLabel = goalTv
        heroCard.addView(goalTv)

        if (!isFocusActive) {
            val pillContainer = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(20) }
            }
            val pillViews = mutableListOf<Pair<Int, TextView>>()
            listOf(25, 45, 60, 90).forEach { mins ->
                val isSelected = selectedFocusDurationMinutes == mins
                val pill = TextView(this).apply {
                    text = "${mins}m"
                    textSize = 12f
                    setTypeface(typeface, if (isSelected) Typeface.BOLD else Typeface.NORMAL)
                    setTextColor(Color.parseColor(if (isSelected) "#FFFFFF" else CLR_TEXT_SECONDARY))
                    background = if (isSelected) gradientBg(CLR_INDIGO, CLR_VIOLET, 99) else surfaceBg(CLR_ELEVATED, 99, CLR_TEXT_DIM, 1)
                    setPadding(dp(14), dp(8), dp(14), dp(8))
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                        setMargins(dp(3), 0, dp(3), 0)
                    }
                    gravity = Gravity.CENTER
                    applySpringTouch {
                        selectedFocusDurationMinutes = mins
                        timerLabel.text = String.format(Locale.US, "%02d:00", mins)
                        pillViews.forEach { (m, tv) ->
                            val sel = m == selectedFocusDurationMinutes
                            tv.setTypeface(tv.typeface, if (sel) Typeface.BOLD else Typeface.NORMAL)
                            tv.setTextColor(Color.parseColor(if (sel) "#FFFFFF" else CLR_TEXT_SECONDARY))
                            tv.background = if (sel) gradientBg(CLR_INDIGO, CLR_VIOLET, 99) else surfaceBg(CLR_ELEVATED, 99, CLR_TEXT_DIM, 1)
                            tv.setPadding(dp(14), dp(8), dp(14), dp(8))
                        }
                    }
                }
                pillViews.add(mins to pill)
                pillContainer.addView(pill)
            }
            heroCard.addView(pillContainer)

            val startBtn = makePrimaryButton("🚀 START FOCUS SESSION", CLR_VIOLET, widthMatchParent = true) { _ ->
                val resObj = JSONObject().apply {
                    put("strict_mode", isStrictMode)
                    put("youtube_study_mode", isStudyMode)
                    put("block_notifications", isDndMode)
                }
                db.startFocusSession("Sprint ${selectedFocusDurationMinutes}m", sessionGoal, selectedFocusDurationMinutes, resObj, isDevMode)
                if (isDndMode) {
                    DisciplinePermissionManager.setFocusDndMode(this, true)
                }
                haptic(1)
                triggerBotMessage("Focus session started (${selectedFocusDurationMinutes}m). Stay locked in!", "SUCCESS")
                refreshUi()
            }
            heroCard.addView(startBtn)

        } else {
            val focusId = activeSession!!.optString("focus_id", "")
            val actionRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }

            if (isPaused) {
                actionRow.addView(makePrimaryButton("▶ RESUME", CLR_GREEN) { _ ->
                    db.resumeFocusSession(focusId)
                    haptic(1)
                    triggerBotMessage("Focus session resumed.", "SUCCESS")
                    refreshUi()
                }.apply { layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(6) } })

                actionRow.addView(makePrimaryButton("🏁 FINISH", CLR_BLUE) { _ ->
                    val pts = db.finishFocusSession(focusId, isDevMode)
                    DisciplinePermissionManager.setFocusDndMode(this, false)
                    haptic(1)
                    showFloatingPoints(pts)
                    triggerBotMessage("Session completed. Points remain 0 until proof is approved.", "SUCCESS")
                    refreshUi()
                }.apply { layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(6) } })

                actionRow.addView(makeSecondaryButton("✕ QUIT", CLR_RED) {
                    db.interruptFocusSession(focusId, "Cancelled")
                    DisciplinePermissionManager.setFocusDndMode(this, false)
                    haptic(3)
                    triggerBotMessage("Focus session stopped.", "WARNING")
                    refreshUi()
                }.apply { layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f) })

            } else {
                actionRow.addView(makeSecondaryButton("⏸ PAUSE", CLR_AMBER) {
                    db.pauseFocusSession(focusId)
                    haptic(2)
                    triggerBotMessage("Session paused.", "WARNING")
                    refreshUi()
                }.apply { layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(6) } })

                actionRow.addView(makePrimaryButton("🏁 COMPLETE", CLR_VIOLET) { _ ->
                    val pts = db.finishFocusSession(focusId, isDevMode)
                    DisciplinePermissionManager.setFocusDndMode(this, false)
                    haptic(1)
                    showFloatingPoints(pts)
                    triggerBotMessage("Focus session completed. Points remain 0 until proof is approved.", "SUCCESS")
                    refreshUi()
                }.apply { layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(6) } })

                actionRow.addView(makeSecondaryButton("✕ GIVE UP", CLR_RED) {
                    showGiveUpConfirmDialog(focusId)
                }.apply { layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f) })
            }

            heroCard.addView(actionRow)
        }

        contentContainer.addView(heroCard)

        // 2. RESTRICTIONS CARD
        contentContainer.addView(sectionHeading("ACTIVE RESTRICTIONS", "🛡️ Strengthen") {
            showStrengthenRestrictionsSheet()
        })
        val restCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(18), dp(18), dp(18), dp(18))
            background = surfaceBg(CLR_SURFACE, 20, CLR_INDIGO, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(16) }
        }

        val isEduUnlock = db.isEducationalUnlockActive()
        val eduReason = db.getEducationalUnlockReason()
        val appLocks = db.getRemoteAppLocks()
        val isYtLocked = appLocks.optBoolean("youtube", true)
        val isIgLocked = appLocks.optBoolean("instagram", true)
        val isSpLocked = appLocks.optBoolean("spotify", true)
        val curScore = db.getScore(db.nowDate(), isDevMode)

        val ytDec = DisciplineScoringRules.evaluateRestrictionDecision(curScore, "YouTube", appLocks = appLocks, isEducationalUnlockActive = isEduUnlock, context = this, db = db)
        val igDec = DisciplineScoringRules.evaluateRestrictionDecision(curScore, "Instagram", appLocks = appLocks, context = this, db = db)
        val spDec = DisciplineScoringRules.evaluateRestrictionDecision(curScore, "Spotify", appLocks = appLocks, context = this, db = db)

        val ytSub = "Score: ${if (curScore >= 80) "Eligible ($curScore/80)" else "Below threshold ($curScore/80)"} • Config: ${if (isYtLocked) "ON" else "OFF"} • Enforce: ${ytDec.platformEnforcement} • Sync: ${ytDec.synchronization}"
        val igSub = "Score: ${if (curScore >= 80) "Eligible ($curScore/80)" else "Below threshold ($curScore/80)"} • Config: ${if (isIgLocked) "ON" else "OFF"} • Enforce: ${igDec.platformEnforcement} • Sync: ${igDec.synchronization}"
        val spSub = "Score: ${if (curScore >= 60) "Eligible ($curScore/60)" else "Below threshold ($curScore/60)"} • Config: ${if (isSpLocked) "ON" else "OFF"} • Enforce: ${spDec.platformEnforcement} • Sync: ${spDec.synchronization}"

        val restRows = listOf(
            Triple("▶ YouTube Restriction", ytSub, isYtLocked),
            Triple("◎ Instagram Restriction", igSub, isIgLocked),
            Triple("♫ Spotify / Music Restriction", spSub, isSpLocked),
            Triple("📺 YouTube Study Mode", if (isStudyMode) "ACTIVE — Educational content only; shorts blocked" else "OFF — All YouTube allowed", isStudyMode),
            Triple("🎓 Educational YouTube Unlock", if (isEduUnlock) "ACTIVE — $eduReason (Shorts, Home & Entertainment blocked)" else "OFF — Tap to request study unlock", isEduUnlock),
            Triple("🔒 Strict Mode Lock", if (isStrictMode) "ACTIVE — Distractions blocked during session" else "OFF", isStrictMode),
            Triple("🔕 Silence Notifications", if (isDndMode) "ACTIVE — DND priorities engaged" else "OFF", isDndMode),
            Triple("📱 Android Protection", if (DisciplinePermissionManager.isDeviceAdminActive(this)) "ACTIVE — Device admin anti-uninstall lock" else "TAP TO ACTIVATE — Device admin lock", DisciplinePermissionManager.isDeviceAdminActive(this))
        )
        restRows.forEachIndexed { i, (rTitle, rSub, active) ->
            val row = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                setPadding(dp(4), dp(8), dp(4), dp(8))
                if (rTitle.contains("▶ YouTube Restriction")) {
                    isClickable = true
                    isFocusable = true
                    setOnClickListener {
                        val willEnable = !isYtLocked
                        if (!willEnable) {
                            if (curScore < 80) {
                                AlertDialog.Builder(this@MainActivity)
                                    .setTitle("YouTube Restriction Cannot Be Disabled")
                                    .setMessage("Authoritative policy requires a score of 80 to unlock entertainment.\n\nCurrent Score: $curScore / 80\nPoints needed: ${80 - curScore}\n\nComplete scheduled hourly activities to restore access.")
                                    .setPositiveButton("OK", null)
                                    .show()
                                return@setOnClickListener
                            }
                        }
                        appLocks.put("youtube", willEnable)
                        db.setRemoteAppLocks(appLocks)
                        val syncPayload = JSONObject().apply {
                            put("target", "youtube")
                            put("enabled", willEnable)
                            put("device_id", "lenovo_android")
                        }
                        db.enqueueSyncEvent("RESTRICTION_TOGGLED", syncPayload, this@MainActivity)
                        Toast.makeText(this@MainActivity, "YouTube restriction set to ${if (willEnable) "ON (BLOCKED)" else "OFF (ALLOWED)"}", Toast.LENGTH_SHORT).show()
                        refreshUi()
                    }
                } else if (rTitle.contains("◎ Instagram Restriction")) {
                    isClickable = true
                    isFocusable = true
                    setOnClickListener {
                        val willEnable = !isIgLocked
                        if (!willEnable) {
                            if (curScore < 80) {
                                AlertDialog.Builder(this@MainActivity)
                                    .setTitle("Instagram Restriction Cannot Be Disabled")
                                    .setMessage("Authoritative policy requires a score of 80 to unlock entertainment.\n\nCurrent Score: $curScore / 80\nPoints needed: ${80 - curScore}\n\nComplete scheduled hourly activities to restore access.")
                                    .setPositiveButton("OK", null)
                                    .show()
                                return@setOnClickListener
                            }
                        }
                        appLocks.put("instagram", willEnable)
                        db.setRemoteAppLocks(appLocks)
                        val syncPayload = JSONObject().apply {
                            put("target", "instagram")
                            put("enabled", willEnable)
                            put("device_id", "lenovo_android")
                        }
                        db.enqueueSyncEvent("RESTRICTION_TOGGLED", syncPayload, this@MainActivity)
                        Toast.makeText(this@MainActivity, "Instagram restriction set to ${if (willEnable) "ON (BLOCKED)" else "OFF (ALLOWED)"}", Toast.LENGTH_SHORT).show()
                        refreshUi()
                    }
                } else if (rTitle.contains("♫ Spotify / Music Restriction")) {
                    isClickable = true
                    isFocusable = true
                    setOnClickListener {
                        val willEnable = !isSpLocked
                        if (!willEnable) {
                            if (curScore < 60) {
                                AlertDialog.Builder(this@MainActivity)
                                    .setTitle("Spotify Restriction Cannot Be Disabled")
                                    .setMessage("Authoritative policy requires a score of 60 to unlock audio/music.\n\nCurrent Score: $curScore / 60\nPoints needed: ${60 - curScore}\n\nComplete scheduled hourly activities to restore access.")
                                    .setPositiveButton("OK", null)
                                    .show()
                                return@setOnClickListener
                            }
                        }
                        appLocks.put("spotify", willEnable)
                        db.setRemoteAppLocks(appLocks)
                        val syncPayload = JSONObject().apply {
                            put("target", "spotify")
                            put("enabled", willEnable)
                            put("device_id", "lenovo_android")
                        }
                        db.enqueueSyncEvent("RESTRICTION_TOGGLED", syncPayload, this@MainActivity)
                        Toast.makeText(this@MainActivity, "Spotify restriction set to ${if (willEnable) "ON (BLOCKED)" else "OFF (ALLOWED)"}", Toast.LENGTH_SHORT).show()
                        refreshUi()
                    }
                } else if (rTitle.contains("Educational YouTube Unlock")) {
                    isClickable = true
                    isFocusable = true
                    setOnClickListener {
                        if (isEduUnlock) {
                            AlertDialog.Builder(this@MainActivity)
                                .setTitle("🎓 Educational Unlock Active")
                                .setMessage("Reason: $eduReason\n\nShorts, home feed, and entertainment are strictly blocked.\n\nWould you like to cancel this unlock?")
                                .setPositiveButton("Cancel Unlock") { _, _ ->
                                    db.cancelEducationalUnlock()
                                    Toast.makeText(this@MainActivity, "Educational unlock cancelled", Toast.LENGTH_SHORT).show()
                                    refreshUi()
                                }
                                .setNegativeButton("Keep Active", null)
                                .show()
                        } else {
                            showEducationalUnlockRequestDialog()
                        }
                    }
                }
                if (i < restRows.size - 1) {
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(4) }
                }
            }
            val col = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            }
            col.addView(TextView(this).apply {
                text = rTitle; textSize = 13.5f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
            })
            col.addView(TextView(this).apply {
                text = rSub; textSize = 10.5f
                setTextColor(Color.parseColor(if (active) CLR_GREEN else CLR_TEXT_SECONDARY))
            })
            row.addView(col)
            val badge = TextView(this).apply {
                text = if (active) "ON" else "OFF"
                textSize = 10f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(if (active) CLR_GREEN else CLR_TEXT_DIM))
                background = surfaceBg(if (active) "#0B2E1E" else CLR_ELEVATED, 99, if (active) CLR_GREEN else CLR_TEXT_DIM, 1)
                setPadding(dp(10), dp(4), dp(10), dp(4))
            }
            row.addView(badge)
            restCard.addView(row)
        }
        contentContainer.addView(restCard)

        // 3. STATS CARD
        contentContainer.addView(sectionHeading("TODAY'S FOCUS STATS"))
        val historyList = db.getFocusHistory(15)
        val todaySessions = historyList.filter { it.optString("date", "") == db.nowDate() && it.optString("status") == "COMPLETED" }
        val todayMins = todaySessions.sumOf { it.optInt("target_minutes", 0) }
        val todayPts = todaySessions.sumOf { it.optInt("points_awarded", 0) }

        val statCard = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER
            setPadding(dp(16), dp(18), dp(16), dp(18))
            background = surfaceBg(CLR_SURFACE, 20)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(16) }
        }
        listOf(
            Triple("${todaySessions.size}", "Sessions", CLR_CYAN),
            Triple("${todayMins}m", "Focused", CLR_VIOLET),
            Triple("+$todayPts", "Points", CLR_GREEN)
        ).forEachIndexed { idx, (valStr, lblStr, clrStr) ->
            if (idx > 0) {
                statCard.addView(View(this).apply {
                    background = surfaceBg(CLR_TEXT_DIM, 2)
                    layoutParams = LinearLayout.LayoutParams(dp(1), dp(32))
                })
            }
            val col = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                gravity = Gravity.CENTER
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            }
            col.addView(TextView(this).apply {
                text = valStr; textSize = 20f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(clrStr))
            })
            col.addView(TextView(this).apply {
                text = lblStr; textSize = 10.5f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            })
            statCard.addView(col)
        }
        contentContainer.addView(statCard)

        // 4. FOCUS HISTORY LIST
        contentContainer.addView(sectionHeading("FOCUS HISTORY"))
        if (historyList.isEmpty()) {
            contentContainer.addView(TextView(this).apply {
                text = "No focus sessions recorded yet. Start your first sprint above!"
                textSize = 12f
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
                gravity = Gravity.CENTER
                setPadding(dp(16), dp(24), dp(16), dp(24))
            })
        } else {
            historyList.take(8).forEach { sess ->
                val sTitle = sess.optString("title", "Focus Session")
                val sGoal = sess.optString("goal", "")
                val sMins = sess.optInt("target_minutes", 25)
                val sStatus = sess.optString("status", "COMPLETED")
                val sPts = sess.optInt("points_awarded", 0)
                val sTime = sess.optString("started_at", "").takeLast(8)

                val itemRow = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.CENTER_VERTICAL
                    setPadding(dp(14), dp(12), dp(14), dp(12))
                    background = surfaceBg(CLR_SURFACE, 16)
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
                }
                val iconTv = TextView(this).apply {
                    text = if (sStatus == "COMPLETED") "⚡" else "✕"
                    textSize = 16f
                    gravity = Gravity.CENTER
                    layoutParams = LinearLayout.LayoutParams(dp(32), dp(32)).apply { rightMargin = dp(10) }
                }
                itemRow.addView(iconTv)

                val col = LinearLayout(this).apply {
                    orientation = LinearLayout.VERTICAL
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                }
                col.addView(TextView(this).apply {
                    text = sTitle; textSize = 13f; setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.WHITE)
                })
                col.addView(TextView(this).apply {
                    text = "${sMins}m • $sTime ${if (sGoal.isNotEmpty()) "• $sGoal" else ""}"; textSize = 10f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                })
                itemRow.addView(col)

                val ptsBadge = TextView(this).apply {
                    text = if (sStatus == "COMPLETED") "+$sPts pts" else sStatus
                    textSize = 10.5f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(if (sStatus == "COMPLETED") CLR_GREEN else CLR_RED))
                }
                itemRow.addView(ptsBadge)
                contentContainer.addView(itemRow)
            }
        }
    }

    private fun showGiveUpConfirmDialog(focusId: String) {
        val input = EditText(this).apply {
            hint = "Reason for interrupting session (optional)"
            setTextColor(Color.WHITE)
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_INDIGO, 1)
            setPadding(dp(12), dp(10), dp(12), dp(10))
        }
        AlertDialog.Builder(this)
            .setTitle("Interrupt Focus Session?")
            .setMessage("Giving up now forfeits session bonus points.")
            .setView(input)
            .setPositiveButton("Give Up") { _, _ ->
                val reason = input.text.toString().trim().ifEmpty { "User interrupted" }
                db.interruptFocusSession(focusId, reason)
                DisciplinePermissionManager.setFocusDndMode(this, false)
                haptic(3)
                triggerBotMessage("Session interrupted: $reason", "WARNING")
                refreshUi()
            }
            .setNegativeButton("Keep Focusing", null)
            .show()
    }

    private fun showFocusSettingsSheet() {
        val settings = db.getFocusSettings()
        var strict = settings.optBoolean("strict_mode", true)
        var study = settings.optBoolean("youtube_study_mode", true)
        var dnd = settings.optBoolean("block_notifications", true)
        var homeLock = settings.optBoolean("block_home", false)

        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(22), dp(20), dp(22), dp(16))
            background = surfaceBg(CLR_MODAL, 24, CLR_INDIGO, 1)
        }
        dialogView.addView(TextView(this).apply {
            text = "⚙️ FOCUS SETTINGS & RULES"
            textSize = 16f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(4) }
        })
        dialogView.addView(TextView(this).apply {
            text = "Configure anti-distraction rules and restrictions."
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(16) }
        })

        val switches = listOf(
            Triple("📺 YouTube Study Mode", "Allow educational lectures only; block shorts & entertainment") { checked: Boolean -> study = checked },
            Triple("🔒 Strict Mode Lock", "Disallow app switching & social distractions") { checked: Boolean -> strict = checked },
            Triple("🔕 Silence Notifications", "Enable Do Not Disturb priority interruptions") { checked: Boolean ->
                dnd = checked
                if (checked && !DisciplinePermissionManager.isNotificationPolicyAccessGranted(this)) {
                    DisciplinePermissionManager.requestNotificationPolicyAccess(this)
                }
            },
            Triple("📱 Lock Task Mode", "Pin StrictRoutines on screen during focus") { checked: Boolean -> homeLock = checked }
        )

        val initialValues = listOf(study, strict, dnd, homeLock)
        switches.forEachIndexed { idx, (title, desc, onChange) ->
            val row = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                setPadding(0, dp(8), 0, dp(8))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
            }
            val col = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(8) }
            }
            col.addView(TextView(this).apply {
                text = title; textSize = 13.5f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
            })
            col.addView(TextView(this).apply {
                text = desc; textSize = 10f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            })
            row.addView(col)
            val sw = Switch(this).apply {
                isChecked = initialValues[idx]
                setOnCheckedChangeListener { _, isChecked -> onChange(isChecked) }
            }
            row.addView(sw)
            dialogView.addView(row)
        }

        val strengthenBtn = makeSecondaryButton("🛡️ STRENGTHEN RESTRICTIONS", CLR_CYAN) {
            showStrengthenRestrictionsSheet()
        }
        strengthenBtn.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
            topMargin = dp(8); bottomMargin = dp(16)
        }
        dialogView.addView(strengthenBtn)

        var dialogRef: AlertDialog? = null
        val saveRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.END
        }
        saveRow.addView(makeSecondaryButton("CANCEL", CLR_TEXT_DIM) {
            dialogRef?.dismiss()
        })
        saveRow.addView(makePrimaryButton("SAVE SETTINGS", CLR_VIOLET) { _ ->
            val updated = JSONObject().apply {
                put("strict_mode", strict)
                put("youtube_study_mode", study)
                put("block_notifications", dnd)
                put("block_home", homeLock)
            }
            db.saveFocusSettings(updated)
            haptic(1)
            triggerBotMessage("Focus settings updated.", "SUCCESS")
            dialogRef?.dismiss()
            refreshUi()
        }.apply { layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { leftMargin = dp(10) } })
        dialogView.addView(saveRow)

        dialogRef = AlertDialog.Builder(this)
            .setView(dialogView)
            .create().apply {
                window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
                show()
            }
    }

    private fun showEducationalUnlockRequestDialog() {
        val input = EditText(this).apply {
            hint = "e.g. Need to watch Python algorithms lecture for university exam"
            setHintTextColor(Color.parseColor("#64748B"))
            setTextColor(Color.WHITE)
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 13f)
            setPadding(dp(16), dp(12), dp(16), dp(12))
            background = surfaceBg("#0A0B10", 8, "#334155", 1)
            minLines = 3
            gravity = Gravity.TOP or Gravity.START
        }

        val container = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(10), dp(20), dp(10))
            addView(input)
        }

        AlertDialog.Builder(this)
            .setTitle("🎓 Request Educational Unlock")
            .setMessage("Provide your educational study purpose.\n\n⚠️ Strict Rules Enforced:\n• Shorts are blocked\n• Home feed is blocked\n• Educational search only\n• NO entertainment, music, gaming, comedy, or serials.")
            .setView(container)
            .setPositiveButton("Submit Request") { _, _ ->
                val reason = input.text?.toString()?.trim() ?: ""
                val validation = DisciplineScoringRules.validateEducationalUnlockReason(reason)
                if (!validation.first) {
                    Toast.makeText(this, validation.second, Toast.LENGTH_LONG).show()
                } else {
                    db.setEducationalUnlock(reason, 60)
                    Toast.makeText(this, "Educational Unlock Approved (60 mins)!\nShorts & Homepage are blocked.", Toast.LENGTH_LONG).show()
                    refreshUi()
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun showStrengthenRestrictionsSheet() {
        val hasAdmin = DisciplinePermissionManager.isDeviceAdminActive(this)
        val hasDnd = DisciplinePermissionManager.isNotificationPolicyAccessGranted(this)

        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(22), dp(20), dp(22), dp(16))
            background = surfaceBg(CLR_MODAL, 24, CLR_INDIGO, 1)
        }
        dialogView.addView(TextView(this).apply {
            text = "🛡️ STRENGTHEN RESTRICTIONS"
            textSize = 16f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(4) }
        })
        dialogView.addView(TextView(this).apply {
            text = "Activate tamper-proofing & anti-uninstall defenses."
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(16) }
        })

        // 1. Device Admin
        val adminRow = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(12), dp(10), dp(12), dp(10))
            background = surfaceBg(CLR_SURFACE_LOW, 14)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(10) }
        }
        adminRow.addView(TextView(this).apply {
            text = "Device Administrator (Anti-Uninstall)"; textSize = 13f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
        })
        adminRow.addView(TextView(this).apply {
            text = if (hasAdmin) "✓ ENABLED — Unauthorized removal is blocked." else "Prevents removing StrictRoutines during discipline hours."; textSize = 10f
            setTextColor(Color.parseColor(if (hasAdmin) CLR_GREEN else CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        })
        if (!hasAdmin) {
            adminRow.addView(makePrimaryButton("ENABLE DEVICE ADMIN", CLR_CYAN) { _ ->
                DisciplinePermissionManager.requestDeviceAdmin(this)
            })
        }
        dialogView.addView(adminRow)

        // 2. DND Policy Access
        val dndRow = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(12), dp(10), dp(12), dp(10))
            background = surfaceBg(CLR_SURFACE_LOW, 14)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(10) }
        }
        dndRow.addView(TextView(this).apply {
            text = "Do Not Disturb Policy Access"; textSize = 13f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
        })
        dndRow.addView(TextView(this).apply {
            text = if (hasDnd) "✓ GRANTED — StrictRoutines can silence alerts." else "Allows StrictRoutines to suppress notifications in focus mode."; textSize = 10f
            setTextColor(Color.parseColor(if (hasDnd) CLR_GREEN else CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        })
        if (!hasDnd) {
            dndRow.addView(makePrimaryButton("GRANT DND ACCESS", CLR_CYAN) { _ ->
                DisciplinePermissionManager.requestNotificationPolicyAccess(this)
            })
        }
        dialogView.addView(dndRow)

        // 3. Multi-Window / Split-screen protection
        val mwRow = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(12), dp(10), dp(12), dp(10))
            background = surfaceBg(CLR_SURFACE_LOW, 14)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(16) }
        }
        mwRow.addView(TextView(this).apply {
            text = "Split-Screen & Multitasking Filter"; textSize = 13f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
        })
        mwRow.addView(TextView(this).apply {
            text = "✓ AUTOMATIC — Disables secondary split windows when focus session runs."; textSize = 10f
            setTextColor(Color.parseColor(CLR_GREEN))
        })
        dialogView.addView(mwRow)

        var dialogRef: AlertDialog? = null
        dialogView.addView(makeSecondaryButton("CLOSE", CLR_TEXT_DIM) {
            dialogRef?.dismiss()
            refreshUi()
        })

        dialogRef = AlertDialog.Builder(this)
            .setView(dialogView)
            .create().apply {
                window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
                show()
            }
    }

    // ════════════════════════════════════════════════════════
    // DEVICES TAB (Section 6)
