    private fun launchBuiltInQrScanner() {
        try {
            val intent = Intent(this, QrScannerActivity::class.java)
            startActivityForResult(intent, 777)
        } catch (e: Exception) {
            Toast.makeText(this, "Could not open QR Scanner: ${e.message}", Toast.LENGTH_LONG).show()
            showDeviceCenterDialog()
        }
    }

    private fun renderDevicesTab(st: org.json.JSONObject, score: Int) {
        // 2. Windows PC Direct Pairing (Local LAN / QR code pairing)
        contentContainer.addView(sectionHeading("WINDOWS PC DIRECT PAIRING", "+ Pair device") {
            showDeviceCenterDialog()
        })
        val isRegistered = db.isDeviceRegistered()
        val reg = db.getDeviceRegistration()
        val isLanOn = HardwareDeviceVerifier.isNetworkOrWifiAvailable(this)
        val pairingStatus = db.getConfigValue("pairing_status", if (isRegistered) "REGISTERED" else "NOT_REGISTERED")
        val isTablet = isWideLayout()
        val manufacturer = android.os.Build.MANUFACTURER.trim()
        val model = android.os.Build.MODEL.trim()
        val deviceName = reg?.optString("device_name")?.trim()?.takeIf { it.isNotBlank() }?.let { registeredName ->
            val manufacturerPrefix = "$manufacturer "
            if (manufacturer.isNotEmpty() && registeredName.startsWith(manufacturerPrefix, ignoreCase = true) &&
                registeredName.substring(manufacturerPrefix.length).startsWith(manufacturer, ignoreCase = true)) {
                registeredName.substring(manufacturerPrefix.length)
            } else registeredName
        } ?: if (manufacturer.isNotEmpty() && model.startsWith(manufacturer, ignoreCase = true)) model
            else listOf(manufacturer, model).filter { it.isNotBlank() }.joinToString(" ")
        val pcName = reg?.optString("paired_pc_name", "Windows PC")?.takeIf { it.isNotBlank() } ?: "Windows PC"
        val lastSync = db.getConfigValue("last_sync_time", "Never")
        val hostOnline = isRegistered && pairingStatus.equals("ONLINE", ignoreCase = true)

        // 1. Current Connection Status Banner
        val hero = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(16), dp(16), dp(16))
            background = surfaceBg(CLR_SURFACE, 18, if (hostOnline) CLR_GREEN else CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(16) }
        }

        val topRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
        }
        topRow.addView(TextView(this).apply {
            text = when {
                isRegistered && hostOnline -> "✓ REGISTERED • ONLINE"
                isRegistered && pairingStatus.equals("OFFLINE", ignoreCase = true) -> "✓ REGISTERED • OFFLINE"
                isRegistered -> "✓ REGISTERED DEVICE"
                pairingStatus.equals("REVOKED", ignoreCase = true) -> "⛔ DEVICE REVOKED"
                else -> "⚠️ UNREGISTERED DEVICE"
            }
            textSize = 13.5f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (hostOnline) CLR_GREEN else if (pairingStatus.equals("REVOKED", ignoreCase = true)) CLR_RED else if (isRegistered) CLR_CYAN else CLR_AMBER))
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        })
        topRow.addView(TextView(this).apply {
            text = if (isLanOn) "● NETWORK READY" else "○ OFFLINE"
            textSize = 10f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (isLanOn) CLR_CYAN else CLR_TEXT_DIM))
        })
        hero.addView(topRow)

        hero.addView(TextView(this).apply {
            text = if (isRegistered)
                "$deviceName is paired with $pcName. Last confirmed sync: $lastSync"
            else
                "Pair this Android device with your Windows StrictRoutines app to sync records."
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(12) }
        })

        val btnRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        val syncBtn = makeSecondaryButton("🔄 SYNC NOW", CLR_GREEN) {
            triggerServerSync()
        }.apply { layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(6) } }
        btnRow.addView(syncBtn)

        if (isRegistered) {



            val revokeBtn = makeSecondaryButton("⚠️ REVOKE", CLR_RED) {
                AlertDialog.Builder(this)
                    .setTitle("Revoke Device Registration?")
                    .setMessage("This will permanently unpair this Android device from $pcName. You will need to pair again to sync records.")
                    .setPositiveButton("REVOKE") { _, _ ->
                        db.revokeDeviceRegistration(this@MainActivity, notifyServer = true)
                        haptic(3)
                        Toast.makeText(this@MainActivity, "Device Registration Revoked", Toast.LENGTH_SHORT).show()
                        refreshUi()
                    }
                    .setNegativeButton("Cancel", null)
                    .show()
            }.apply { layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(6) } }
            btnRow.addView(revokeBtn)
        } else {
            val detailsBtn = makeSecondaryButton("⚙️ DETAILS", CLR_CYAN) {
                showDeviceCenterDialog()
            }.apply { layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(6) } }
            btnRow.addView(detailsBtn)
        }

        hero.addView(btnRow)
        // 2. Connect New Device Card (Always accessible on Devices tab)
        val connectCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(16), dp(16), dp(16))
            background = surfaceBg(CLR_SURFACE, 18, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(16) }
        }

        connectCard.addView(TextView(this).apply {
            text = "Pair a Windows device"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(4) }
        })
        connectCard.addView(TextView(this).apply {
            text = "Use the QR code or pairing code shown in the Windows Device Center."
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(14) }
        })

        val scanQrBtn = makePrimaryButton("SCAN QR CODE", CLR_GREEN, widthMatchParent = true) { _ ->
            launchBuiltInQrScanner()
        }.apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(14) }
        }
        connectCard.addView(scanQrBtn)

        connectCard.addView(TextView(this).apply {
            text = "Or enter the code shown on your Windows application:"
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        })

        connectCard.addView(TextView(this).apply {
            text = "PAIRING CODE (6-DIGIT PIN OR SR-XXXX-XXXX)"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            letterSpacing = 0.08f
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(4) }
        })

        val inlineKeyInput = EditText(this).apply {
            hint = "Pairing code"
            textSize = 17f
            setTypeface(Typeface.MONOSPACE, Typeface.BOLD)
            tag = "telemetry_type"
            gravity = Gravity.CENTER
            setTextColor(Color.WHITE)
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            inputType = android.text.InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS
            background = surfaceBg(CLR_SURFACE_LOW, 14, CLR_BORDER, 1)
            setPadding(dp(16), dp(12), dp(16), dp(12))
            filters = arrayOf(android.text.InputFilter.AllCaps(), android.text.InputFilter.LengthFilter(16))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(10) }
        }
        connectCard.addView(inlineKeyInput)

        val inlineFeedback = TextView(this).apply {
            text = ""
            textSize = 11f
            gravity = Gravity.CENTER
            setTextColor(Color.parseColor(CLR_AMBER))
            visibility = View.GONE
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(10) }
        }
        connectCard.addView(inlineFeedback)

        val connectDevBtn = makePrimaryButton("CONNECT DEVICE", CLR_GREEN, widthMatchParent = true) { _ ->
            val key = inlineKeyInput.text.toString().trim()
            if (key.length < 6) {
                inlineFeedback.visibility = View.VISIBLE
                inlineFeedback.setTextColor(Color.parseColor(CLR_AMBER))
                inlineFeedback.text = "Please enter the 6-digit PIN or Pairing Code (SR-XXXX-XXXX) shown on Windows."
                haptic(2)
                return@makePrimaryButton
            }
            inlineFeedback.visibility = View.VISIBLE
            inlineFeedback.setTextColor(Color.parseColor(CLR_CYAN))
            inlineFeedback.text = "Scanning Wi-Fi & connecting to StrictRoutines PC..."
            val pcEndpoint = ""
            Thread {
                val (ok, msg) = db.performPairingHandshake(pcEndpoint, key, this@MainActivity)
                runOnUiThread {
                    if (ok) {
                        haptic(1)
                        inlineFeedback.setTextColor(Color.parseColor(CLR_GREEN))
                        inlineFeedback.text = "✓ $msg"
                        triggerBotMessage("Device permanently paired with PC!", "SUCCESS")
                        Toast.makeText(this@MainActivity, "✓ Device Connected!\n$msg", Toast.LENGTH_LONG).show()
                        refreshUi()
                    } else {
                        haptic(3)
                        inlineFeedback.setTextColor(Color.parseColor(CLR_RED))
                        inlineFeedback.text = "✕ $msg"
                        Toast.makeText(this@MainActivity, "Pairing failed: $msg", Toast.LENGTH_LONG).show()
                    }
                }
            }.start()
        }
        connectCard.addView(connectDevBtn)

        if (isTablet) {
            val deviceCards = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(8)
                }
            }
            hero.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                rightMargin = dp(8)
            }
            connectCard.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                leftMargin = dp(8)
            }
            deviceCards.addView(hero)
            deviceCards.addView(connectCard)
            contentContainer.addView(deviceCards)
        } else {
            hero.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
            connectCard.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
            contentContainer.addView(hero)
            contentContainer.addView(connectCard)
        }

        // Strict Session Companion & Usage Access Card
        val companionCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(16), dp(16), dp(16))
            background = surfaceBg(CLR_SURFACE, 18, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(16) }
        }
        val compRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        }
        compRow.addView(TextView(this).apply {
            text = "STRICT SESSION COMPANION"
            textSize = 12f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        })
        val isMonitoring = AndroidStrictMonitoringService.isServiceRunning
        val monitorState = AndroidStrictMonitoringService.currentMonitoringState
        compRow.addView(TextView(this).apply {
            text = if (isMonitoring) "● $monitorState" else "○ IDLE"
            textSize = 11f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (isMonitoring) CLR_GREEN else CLR_TEXT_DIM))
        })
        companionCard.addView(compRow)

        val hasUsage = StrictSessionUsageMonitor.hasUsagePermission(this)
        companionCard.addView(TextView(this).apply {
            text = if (hasUsage) "✓ Usage Access Permission Granted (UsageStats monitoring active)"
                   else "⚠️ Usage Access Required: Strict Session mobile monitoring requires PACKAGE_USAGE_STATS permission."
            textSize = 11f
            setTextColor(Color.parseColor(if (hasUsage) CLR_TEXT_SECONDARY else CLR_AMBER))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
        })
        if (!hasUsage) {
            companionCard.addView(makeSecondaryButton("⚙️ GRANT USAGE ACCESS", CLR_AMBER) {
                StrictSessionUsageMonitor.openUsageAccessSettings(this@MainActivity)
            })
        }
        contentContainer.addView(companionCard)

        // 3. Current pairing details; credentials and network endpoints stay out of the user-facing page.
        contentContainer.addView(sectionHeading("PAIRING STATUS"))
        val specsCard = designCard(paddingDp = 14, cornerDp = 18).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(16) }
        }
        val rows = listOf(
            Triple("This device", deviceName, CLR_TEXT_PRIMARY),
            Triple("Platform", reg?.optString("device_type")?.takeIf { it.isNotBlank() } ?: "ANDROID", CLR_TEXT_SECONDARY),
            Triple("Paired computer", if (isRegistered) pcName else "Not paired", if (isRegistered) CLR_TEXT_PRIMARY else CLR_TEXT_DIM),
            Triple("Connection", when {
                !isRegistered -> "Not registered"
                pairingStatus.equals("ONLINE", ignoreCase = true) -> "Online"
                pairingStatus.equals("OFFLINE", ignoreCase = true) -> "Offline"
                pairingStatus.equals("REVOKED", ignoreCase = true) -> "Revoked"
                else -> "Registered"
            }, when {
                hostOnline -> CLR_GREEN
                pairingStatus.equals("REVOKED", ignoreCase = true) -> CLR_RED
                isRegistered -> CLR_CYAN
                else -> CLR_TEXT_DIM
            }),
            Triple("Network", if (isLanOn) "Connected" else "Offline", if (isLanOn) CLR_CYAN else CLR_TEXT_DIM),
            Triple("Last confirmed sync", lastSync, CLR_TEXT_SECONDARY)
        )
        rows.forEachIndexed { _, (k, v, clr) ->
            val r = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                setPadding(0, dp(6), 0, dp(6))
            }
            r.addView(TextView(this).apply {
                text = k; textSize = 12f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            })
            r.addView(TextView(this).apply {
                text = v; textSize = 11.5f; setTypeface(Typeface.MONOSPACE, Typeface.NORMAL)
                setTextColor(Color.parseColor(clr))
            })
            specsCard.addView(r)
        }
        contentContainer.addView(specsCard)
    }

    private fun formatRelativeTime(timestampStr: String?): String {
        if (timestampStr.isNullOrBlank() || timestampStr.equals("Never", ignoreCase = true)) {
            return "Never"
        }
        return try {
            val formats = listOf(
                java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'", java.util.Locale.US).apply { timeZone = java.util.TimeZone.getTimeZone("UTC") },
                java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'", java.util.Locale.US).apply { timeZone = java.util.TimeZone.getTimeZone("UTC") },
                java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.getDefault()),
                java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.getDefault())
            )
            var date: java.util.Date? = null
            for (fmt in formats) {
                try {
                    date = fmt.parse(timestampStr)
                    if (date != null) break
                } catch (_: Exception) {}
            }
            if (date != null) {
                val diffMs = System.currentTimeMillis() - date.time
                val diffSec = diffMs / 1000
                val diffMin = diffSec / 60
                val diffHours = diffMin / 60
                val diffDays = diffHours / 24
                when {
                    diffSec < 45 -> "Just now"
                    diffMin < 60 -> "$diffMin min${if (diffMin == 1L) "" else "s"} ago"
                    diffHours < 24 -> "$diffHours hour${if (diffHours == 1L) "" else "s"} ago"
                    diffDays < 7 -> "$diffDays day${if (diffDays == 1L) "" else "s"} ago"
                    else -> java.text.SimpleDateFormat("MMM d, h:mm a", java.util.Locale.getDefault()).format(date)
                }
            } else {
                timestampStr
            }
        } catch (_: Exception) {
            timestampStr
        }
    }



    private fun renderAutomaticBluetoothCard() {
        val card = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(16), dp(16), dp(16))
            background = surfaceBg(CLR_SURFACE, 18, CLR_BLUE, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(16) }
        }
        card.addView(TextView(this).apply {
            text = "AUTOMATIC BLUETOOTH SYNC"; textSize = 13.5f
            setTypeface(typeface, Typeface.BOLD); setTextColor(Color.parseColor(CLR_CYAN))
        })
        card.addView(TextView(this).apply {
            text = "Register this phone with your PC using QR / code, then remember this phone in the PC's Automatic Bluetooth Sync card. Choose that PC below once. Sync reconnects in the background when both devices have Bluetooth on."
            textSize = 11f; setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            setPadding(0, dp(8), 0, dp(8))
        })
        val allowed = android.os.Build.VERSION.SDK_INT < 31 || checkSelfPermission(android.Manifest.permission.BLUETOOTH_CONNECT) == android.content.pm.PackageManager.PERMISSION_GRANTED
        val adapter = android.bluetooth.BluetoothAdapter.getDefaultAdapter()
        val peers = if (allowed && adapter?.isEnabled == true)
            runCatching { adapter.bondedDevices.sortedBy { it.name ?: it.address } }.getOrDefault(emptyList()) else emptyList()
        val selectedPc = android.widget.Spinner(this).apply {
            this.adapter = android.widget.ArrayAdapter(this@MainActivity, android.R.layout.simple_spinner_dropdown_item,
                listOf("Select your registered Windows PC") + peers.map { "${it.name ?: "Paired PC"} · ${it.address}" })
            val saved = db.getConfigValue("bluetooth_auto_pc_address", "")
            setSelection(peers.indexOfFirst { it.address.equals(saved, true) }.let { if (it < 0) 0 else it + 1 })
            isEnabled = db.getConfigValue("bluetooth_auto_enabled", "false") != "true"
        }
        card.addView(selectedPc)
        val syncStatus = TextView(this).apply {
            textSize = 11f; setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            setPadding(0, dp(8), 0, dp(8))
        }
        card.addView(syncStatus)
        val updateStatus = object : Runnable {
            override fun run() {
                syncStatus.text = if (db.getConfigValue("bluetooth_auto_enabled", "false") == "true")
                    db.getConfigValue("bluetooth_auto_status", "Waiting to sync with remembered PC…")
                else "Automatic Bluetooth sync is off"
                if (syncStatus.isAttachedToWindow) syncStatus.postDelayed(this, 3000)
            }
        }
        syncStatus.post(updateStatus)
        val enabled = db.getConfigValue("bluetooth_auto_enabled", "false") == "true"
        card.addView(makePrimaryButton(if (enabled) "TURN OFF AUTOMATIC SYNC" else "REMEMBER PC & ENABLE SYNC", CLR_BLUE, widthMatchParent = true) {
            if (enabled) {
                db.setConfigValue("bluetooth_auto_enabled", "false")
                BluetoothTransferClient.cancelAutomatic()
                StrictEnforcementService.activeInstance?.refreshAutomaticBluetoothSync()
                refreshUi()
            } else if (!allowed) {
                requestPermissions(arrayOf(android.Manifest.permission.BLUETOOTH_CONNECT), 16980)
            } else {
                val pc = peers.getOrNull(selectedPc.selectedItemPosition - 1)
                val registration = db.getDeviceRegistration()
                if (pc == null || adapter?.isEnabled != true || registration?.optString("device_token").isNullOrBlank()) {
                    syncStatus.text = "Turn on Bluetooth, register this phone with your PC, then select that paired PC."
                } else {
                    db.setConfigValue("bluetooth_auto_pc_address", pc.address)
                    db.setConfigValue("bluetooth_auto_device_id", registration!!.getString("device_id"))
                    db.setConfigValue("bluetooth_auto_account_id", registration.getString("account_id"))
                    db.setConfigValue("bluetooth_auto_last_fingerprint", "")
                    db.setConfigValue("bluetooth_auto_enabled", "true")
                    StrictEnforcementService.start(this)
                    StrictEnforcementService.activeInstance?.refreshAutomaticBluetoothSync()
                    refreshUi()
                }
            }
        })
        contentContainer.addView(card)
    }

    private fun showBluetoothTransferDialog() {
        if (android.os.Build.VERSION.SDK_INT >= 31 && checkSelfPermission(android.Manifest.permission.BLUETOOTH_CONNECT) != android.content.pm.PackageManager.PERMISSION_GRANTED) {
            requestPermissions(arrayOf(android.Manifest.permission.BLUETOOTH_CONNECT), 16980)
            return
        }
        val adapter = android.bluetooth.BluetoothAdapter.getDefaultAdapter()
        val peers = if (adapter?.isEnabled == true) runCatching { adapter.bondedDevices.sortedBy { it.name ?: it.address } }.getOrDefault(emptyList()) else emptyList()

        val root = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(22), dp(20), dp(22), dp(16))
            background = surfaceBg(CLR_MODAL, 20, CLR_BLUE, 1)
        }

        root.addView(TextView(this).apply {
            text = "TEMPORARY BLUETOOTH TRANSFER"
            textSize = 15f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(6) }
        })

        root.addView(TextView(this).apply {
            text = "SENDING: this Android device → your selected Windows PC.\nPair both devices in Bluetooth Settings. On the PC, open Temporary Bluetooth Transfer, select this phone and start its receiving session."
            textSize = 11.5f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(14) }
        })

        val peerSelector = android.widget.Spinner(this)
        peerSelector.adapter = android.widget.ArrayAdapter(this, android.R.layout.simple_spinner_dropdown_item,
            listOf("Select the receiving Windows PC") + peers.map { "${it.name ?: "Paired device"} · ${it.address}" })
        root.addView(peerSelector)
        val confirmation = android.widget.CheckBox(this).apply {
            text = "I confirm the selected device is the intended receiving PC"
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
        }
        root.addView(confirmation)
        root.addView(makeSecondaryButton("BLUETOOTH SETTINGS", CLR_CYAN) {
            startActivity(android.content.Intent(android.provider.Settings.ACTION_BLUETOOTH_SETTINGS))
        })
        root.addView(TextView(this).apply {
            text = "Last successful transfer: ${db.getConfigValue("last_bluetooth_transfer", "None")}"
            textSize = 11f; setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
        })

        val pinInput = EditText(this).apply {
            hint = "6-DIGIT PIN"
            textSize = 20f
            setTypeface(Typeface.MONOSPACE, Typeface.BOLD)
            gravity = Gravity.CENTER
            setTextColor(Color.WHITE)
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            inputType = android.text.InputType.TYPE_CLASS_NUMBER
            background = surfaceBg(CLR_SURFACE_LOW, 14, CLR_CYAN, 1)
            setPadding(dp(16), dp(12), dp(16), dp(12))
            filters = arrayOf(android.text.InputFilter.LengthFilter(6))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
        }
        root.addView(pinInput)

        val statusView = TextView(this).apply {
            text = ""
            textSize = 11.5f
            gravity = Gravity.CENTER
            setTextColor(Color.parseColor(CLR_AMBER))
            visibility = View.GONE
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(14) }
        }
        root.addView(statusView)

        val dialog = AlertDialog.Builder(this)
            .setView(root)
            .setCancelable(true)
            .create()

        val btnRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.END
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            )
        }

        val cancelBtn = makeSecondaryButton("CANCEL", CLR_RED) {
            BluetoothTransferClient.cancel()
            dialog.dismiss()
        }.apply {
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { rightMargin = dp(8) }
        }

        var transferInProgress = false
        root.addView(makeSecondaryButton("USE LATEST DATA", CLR_CYAN) {
            if (!transferInProgress) AlertDialog.Builder(this)
                .setTitle("Prepare a new transfer package?")
                .setMessage("Use this only after a stale-package or account conflict. The saved retry snapshot will be discarded. Your points, proofs, history and tasks stay in the app database.")
                .setNegativeButton("Keep original retry", null)
                .setPositiveButton("Use latest data") { _, _ ->
                    statusView.visibility = View.VISIBLE
                    statusView.text = if (BluetoothTransferClient.clearPendingPackage(this))
                        "The next transfer will prepare current data. Open a new receiving session on the PC."
                    else "Wait for the active transfer to finish before preparing current data."
                }.show()
        })
        val startBtn = makePrimaryButton("START TRANSFER", CLR_BLUE) { _ ->
            if (transferInProgress) return@makePrimaryButton
            val peer = peers.getOrNull(peerSelector.selectedItemPosition - 1)
            if (peer == null || !confirmation.isChecked || adapter?.isEnabled != true) {
                statusView.visibility = View.VISIBLE
                statusView.text = "Turn on Bluetooth, select the paired receiving PC, and confirm the target."
                return@makePrimaryButton
            }
            val code = pinInput.text.toString().trim()
            if (code.length != 6) {
                statusView.visibility = View.VISIBLE
                statusView.setTextColor(Color.parseColor(CLR_AMBER))
                statusView.text = "Please enter the complete 6-digit session PIN shown on Windows."
                haptic(2)
                return@makePrimaryButton
            }

            transferInProgress = true
            pinInput.isEnabled = false
            statusView.visibility = View.VISIBLE
            statusView.setTextColor(Color.parseColor(CLR_CYAN))
            statusView.text = "Initiating temporary transfer..."

            db.executeBluetoothTransfer(
                code, peer.address,
                onProgress = { msg ->
                    runOnUiThread {
                        statusView.text = msg
                    }
                },
                onComplete = { success, message, receiptJson ->
                    runOnUiThread {
                        transferInProgress = false
                        pinInput.isEnabled = true
                        if (success) {
                            haptic(1)
                            statusView.setTextColor(Color.parseColor(CLR_GREEN))
                            val count = receiptJson?.optInt("transferred_count", 0) ?: 0
                            val pcScore = receiptJson?.optInt("final_score", receiptJson.optInt("confirmed_score", 0)) ?: 0
                            val breakdownObj = receiptJson?.optJSONObject("points_breakdown") ?: db.getPointsBreakdown(db.nowDate())
                            val bList = mutableListOf<String>()
                            if (breakdownObj.has("wake_up") || breakdownObj.has("Wake-up")) {
                                val pts = if (breakdownObj.has("wake_up")) breakdownObj.optInt("wake_up") else breakdownObj.optInt("Wake-up")
                                bList.add("• Wake-up: $pts pts")
                            }
                            if (breakdownObj.has("bath") || breakdownObj.has("Bath")) {
                                val pts = if (breakdownObj.has("bath")) breakdownObj.optInt("bath") else breakdownObj.optInt("Bath")
                                bList.add("• Bath: $pts pts")
                            }
                            if (breakdownObj.has("hourly") || breakdownObj.has("Hourly")) {
                                val pts = if (breakdownObj.has("hourly")) breakdownObj.optInt("hourly") else breakdownObj.optInt("Hourly")
                                bList.add("• Hourly: $pts pts")
                            }
                            if (breakdownObj.has("gym") || breakdownObj.has("Gym")) {
                                val pts = if (breakdownObj.has("gym")) breakdownObj.optInt("gym") else breakdownObj.optInt("Gym")
                                bList.add("• Gym: $pts pts")
                            }
                            if (breakdownObj.has("focus") || breakdownObj.has("Focus & Tasks")) {
                                val pts = if (breakdownObj.has("focus")) breakdownObj.optInt("focus") else breakdownObj.optInt("Focus & Tasks")
                                bList.add("• Focus: $pts pts")
                            }
                            val pen = if (breakdownObj.has("penalties")) breakdownObj.optInt("penalties") else -(breakdownObj.optInt("Violations", 0) + breakdownObj.optInt("Snooze", 0))
                            if (pen != 0) {
                                bList.add("• Penalties: $pen pts")
                            }
                            val breakdownSummary = if (bList.isNotEmpty()) "\nBreakdown:\n" + bList.joinToString("\n") else ""
                            statusView.text = "✓ Transfer committed to ${peer.name ?: peer.address}\nNew: $count · Already present: ${receiptJson?.optInt("already_present_count", 0)}\nRejected: ${receiptJson?.optInt("rejected_count", 0)} · Conflicts: ${receiptJson?.optInt("conflict_count", 0)}\nConfirmed PC score: $pcScore pts$breakdownSummary\n${receiptJson?.optString("synced_at")}"
                            Toast.makeText(this@MainActivity, "Bluetooth Transfer Successful ✓", Toast.LENGTH_LONG).show()
                            refreshUi()
                        } else {
                            haptic(3)
                            statusView.setTextColor(Color.parseColor(CLR_RED))
                            statusView.text = "❌ Transfer Failed:\n$message"
                        }
                    }
                }
            )
        }

        btnRow.addView(cancelBtn)
        btnRow.addView(startBtn)
        root.addView(btnRow)

        dialog.setOnDismissListener { BluetoothTransferClient.cancel() }
        dialog.show()
    }

