    private fun showEventAudit(event: org.json.JSONObject) {
        val type = event.optString("event_type")
        if (type.contains("PROOF")) {
            ProofApprovalReceiptDialog.show(this, db, event)
        } else {
            AlertDialog.Builder(this).setTitle("Event Audit: " + type)
                .setMessage(event.toString(2)).setPositiveButton("Close", null).show()
        }
    }

