        }
        val summaryCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        summaryCol.addView(TextView(this).apply {
            text = "$score / 100"
            textSize = 28f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(scoreColor(score)))
        })
        summaryCol.addView(TextView(this).apply {
            text = "${st.optString("score_state", "STRICT_MODE")}  •  ${st.optString("sync_status", "PENDING")}"
            textSize = 10f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY)); letterSpacing = 0.04f
        })
        summaryHero.addView(summaryCol)

        // Mini arc
        val miniArc = ScoreArcView(this).apply {
            targetProgress = score.toFloat()
            layoutParams = LinearLayout.LayoutParams(dp(70), dp(70))
        }
        miniArc.animateTo(score.toFloat())
        summaryHero.addView(miniArc)
        contentContainer.addView(summaryHero)

        // Score breakdown animated rows
        contentContainer.addView(sectionHeading("SCORE BREAKDOWN"))
        val events = db.getScoreEvents(db.nowDate(), isDevMode)
        if (events.length() == 0) {
            contentContainer.addView(buildEmptyState("📜", "No events yet",
                "Complete tasks to populate your daily timeline."))
        } else {
            for (i in 0 until events.length()) {
                val ev = events.getJSONObject(i)
                val pts = ev.getInt("points")
                val row = buildEventRow(ev.getString("timestamp"), ev.getString("event_type"),
                    ev.getString("description"), pts) {
                    showEventAudit(ev)
                }
                row.alpha = 0f
                row.translationY = dp(20).toFloat()
                contentContainer.addView(row)
                row.animate().alpha(1f).translationY(0f)
                    .setDuration(DUR_MED).setStartDelay(i * 60L)
                    .setInterpolator(DecelerateInterpolator()).start()
            }
        }

        // Sync row
        contentContainer.addView(sectionHeading("SYNC STATUS"))
        val syncCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(14), dp(16), dp(14))
            background = surfaceBg(CLR_SURFACE, 20)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        }
        listOf("Android" to CLR_GREEN, "Windows" to if (isDevMode) CLR_GREEN else CLR_TEXT_DIM,
            "Local Wi-Fi" to CLR_GREEN).forEach { (label, clr) ->
            val r = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
            }
            r.addView(View(this).apply {
                background = surfaceBg(clr, 99)
                layoutParams = LinearLayout.LayoutParams(dp(8), dp(8)).apply { rightMargin = dp(12) }
            })
            r.addView(TextView(this).apply {
                text = label; textSize = 13f; setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            })
            r.addView(TextView(this).apply {
                text = if (clr == CLR_GREEN) "✓ SYNCED" else if (clr == CLR_AMBER) "PENDING" else "OFFLINE"
                textSize = 10f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(clr))
            })
            syncCard.addView(r)
        }
        contentContainer.addView(syncCard)

        val syncNowBtn = makePrimaryButton("SYNC NOW", CLR_BLUE, widthMatchParent = true) {
            triggerServerSync()
        }
        contentContainer.addView(syncNowBtn)
    }

    // ════════════════════════════════════════════════════════
    // REWARDS TAB
    // ════════════════════════════════════════════════════════

    private fun renderRewardsTab(st: org.json.JSONObject, score: Int) {
        val verifiedScore = st.optInt("verified_points", score).coerceAtMost(100)
        val provisionalPoints = st.optInt("provisional_points", 0).coerceAtLeast(0)
        val currentStreak = st.optInt("streak_days", 0).coerceAtLeast(0)
        val threshold = DisciplineScoringRules.CONFIGURED_RESTRICTED_APPS
            .firstOrNull { it.displayName == "YouTube" }?.requiredScore ?: 80
        val remoteLocks = db.getRemoteAppLocks()
        val youtubeAllowed = !DisciplineScoringRules.evaluateRestrictionDecision(score, "YouTube", appLocks = remoteLocks, isEducationalUnlockActive = db.isEducationalUnlockActive()).isRestricted
        val instagramAllowed = !DisciplineScoringRules.evaluateRestrictionDecision(score, "Instagram", appLocks = remoteLocks).isRestricted
        val isTablet = isWideLayout()

        contentContainer.addView(sectionHeading("TODAY'S REWARD STATUS", db.nowDate()))
        val summary = designCard(paddingDp = 16, cornerDp = 18).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }
        val summaryTop = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
        }
        val scoreColumn = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        scoreColumn.addView(TextView(this).apply {
            text = "VERIFIED DISCIPLINE SCORE"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            letterSpacing = 0.06f
        })
        scoreColumn.addView(TextView(this).apply {
            text = "$verifiedScore / 100 pts"
            textSize = 25f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(scoreColor(verifiedScore)))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(3)
            }
        })
        summaryTop.addView(scoreColumn)
        val streakBlock = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            gravity = Gravity.END
        }
        streakBlock.addView(TextView(this).apply {
            text = "CURRENT STREAK"
            textSize = 9f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            gravity = Gravity.END
        })
        streakBlock.addView(TextView(this).apply {
            text = "$currentStreak days"
            textSize = 16f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            gravity = Gravity.END
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(4)
            }
        })
        summaryTop.addView(streakBlock)
        summary.addView(summaryTop)
        val thresholdText = "Music unlocks at 60 • YouTube & Instagram at 80"
        summary.addView(TextView(this).apply {
            text = thresholdText
            textSize = 10.5f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(8)
            }
        })
        summary.addView(ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal).apply {
            max = threshold.coerceAtLeast(1)
            progress = verifiedScore.coerceIn(0, max)
            progressTintList = ColorStateList.valueOf(Color.parseColor(CLR_GREEN))
            progressBackgroundTintList = ColorStateList.valueOf(Color.parseColor(CLR_SURFACE_LOW))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(6)).apply {
                topMargin = dp(9)
            }
        })
        if (provisionalPoints > 0) {
            summary.addView(TextView(this).apply {
                text = "+$provisionalPoints provisional points pending confirmation"
                textSize = 10f
                setTextColor(Color.parseColor(CLR_CYAN))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(7)
                }
            })
        }
        contentContainer.addView(summary)

        contentContainer.addView(sectionHeading("APP PRIVILEGES", "${DisciplineScoringRules.CONFIGURED_RESTRICTED_APPS.map { it.displayName }.distinct().size} configured"))
        val isGymModeActive = db.isGymModeMusicAllowed()
        val privilegeList = listOf(
            Triple("▶", "YouTube", youtubeAllowed),
            Triple("◎", "Instagram", instagramAllowed),
            Triple("♫", "Samsung Music", !DisciplineScoringRules.evaluateRestrictionDecision(score, "Samsung Music", appLocks = remoteLocks, isGymModeActive = isGymModeActive).isRestricted),
            Triple("♫", "Spotify", !DisciplineScoringRules.evaluateRestrictionDecision(score, "Spotify", appLocks = remoteLocks, isGymModeActive = isGymModeActive).isRestricted)
        ).filter { entry ->
            DisciplineScoringRules.CONFIGURED_RESTRICTED_APPS.any { it.displayName == entry.second }
        }
        val privilegeCards = privilegeList.map { (icon, brand, allowed) ->
            val appThreshold = DisciplineScoringRules.CONFIGURED_RESTRICTED_APPS
                .firstOrNull { it.displayName == brand }?.requiredScore ?: threshold
            val card = designCard(paddingDp = if (isTablet) 14 else 10, cornerDp = 16, strokeHex = if (allowed) CLR_GREEN else CLR_BORDER).apply {
                layoutParams = if (isTablet) {
                    LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { bottomMargin = dp(8) }
                } else {
                    LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
                }
                applySpringTouch(scaleDown = 0.98f) { testAppAccessDialog(brand, score, allowed) }
            }
            val titleRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
            }
            titleRow.addView(TextView(this).apply {
                text = icon
                textSize = 17f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(if (brand == "YouTube") "#FF6B6B" else "#D889FF"))
                gravity = Gravity.CENTER
                layoutParams = LinearLayout.LayoutParams(dp(30), dp(30)).apply { rightMargin = dp(10) }
            })
            titleRow.addView(TextView(this).apply {
                text = brand
                textSize = 14f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            })
            titleRow.addView(designStatusPill(if (allowed) "AVAILABLE" else "RESTRICTED", if (allowed) CLR_GREEN else CLR_TEXT_SECONDARY))
            card.addView(titleRow)
            val isGymUnlockedThisApp = isGymModeActive && (brand == "Samsung Music" || brand == "Spotify")
            card.addView(TextView(this).apply {
                visibility = if (isTablet) View.VISIBLE else View.GONE
                text = if (isGymUnlockedThisApp) "Unlocked by active GYM Mode music session."
                    else if (allowed) "Access is currently permitted by the active restriction state."
                    else "$appThreshold verified points required; active restrictions remain in effect."
                textSize = 10.5f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(8)
                }
            })
            card.addView(TextView(this).apply {
                text = if (isGymUnlockedThisApp) "Unlocked via GYM Mode"
                else if (!isTablet) {
                    if (allowed) "Unlocked • $appThreshold-point threshold"
                    else "Unlocks at $appThreshold • ${(appThreshold - verifiedScore).coerceAtLeast(0)} points remaining"
                } else if (verifiedScore >= appThreshold) "Score threshold met" else "${appThreshold - verifiedScore} verified points to threshold"
                textSize = 9.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(if (allowed) CLR_GREEN else CLR_CYAN))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(7)
                }
            })
            card
        }
        if (privilegeCards.isEmpty()) {
            contentContainer.addView(buildEmptyState("◈", "No configured privileges", "Configured app privileges will appear here."))
        } else if (isTablet) {
            privilegeCards.chunked(2).forEach { pair ->
                val row = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.TOP
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
                }
                pair.forEachIndexed { index, card ->
                    if (index > 0) (card.layoutParams as? LinearLayout.LayoutParams)?.leftMargin = dp(8)
                    row.addView(card)
                }
                contentContainer.addView(row)
            }
        } else {
            privilegeCards.forEach { contentContainer.addView(it) }
        }

        // ── Single-Video YouTube Reward Section ──
        contentContainer.addView(renderSingleVideoRewardSection(isTablet))

        // ── GYM Mode Section ──
        contentContainer.addView(renderGymModeSection(isTablet))

        // Streak milestone row adapted from StrictFocus, driven by the user's actual saved streak.
        contentContainer.addView(sectionHeading("STREAK MILESTONES", "$currentStreak day streak"))
        val milestonesCard = designCard(paddingDp = 14, cornerDp = 16).apply {
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(8) }
        }
        milestonesCard.addView(TextView(this).apply {
            text = "Discipline milestones"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(10) }
        })
        val milestoneRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
        }
        listOf(7 to "Recruit", 14 to "Enforcer", 30 to "Iron Will").forEachIndexed { index, milestone ->
            val (days, title) = milestone
            val unlocked = currentStreak >= days
            val badge = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                gravity = Gravity.CENTER
                setPadding(dp(5), dp(9), dp(5), dp(9))
                background = surfaceBg(CLR_ELEVATED, 12, if (unlocked) CLR_GREEN else CLR_BORDER, 1)
                contentDescription = "$days day milestone: $title, ${if (unlocked) "unlocked" else "locked"}"
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                    if (index > 0) leftMargin = dp(8)
                }
            }
            badge.addView(TextView(this).apply {
                text = if (unlocked) "✦" else "✧"
                textSize = 18f
                gravity = Gravity.CENTER
                setTextColor(Color.parseColor(if (unlocked) CLR_GREEN else CLR_TEXT_DIM))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(3)
                }
            })
            badge.addView(TextView(this).apply {
                text = "$days DAYS"
                textSize = 10f
                setTypeface(Typeface.MONOSPACE, Typeface.BOLD)
                tag = "telemetry_type"
                gravity = Gravity.CENTER
                setTextColor(Color.parseColor(if (unlocked) CLR_GREEN else CLR_TEXT_SECONDARY))
            })
            badge.addView(TextView(this).apply {
                text = title
                textSize = 9.5f
                gravity = Gravity.CENTER
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
                maxLines = 1
                ellipsize = TextUtils.TruncateAt.END
            })
            milestoneRow.addView(badge)
        }
        milestonesCard.addView(milestoneRow)
        contentContainer.addView(milestonesCard)

        val events = db.getScoreEvents(db.nowDate(), isDevMode)
        contentContainer.addView(sectionHeading("TODAY'S POINT ACTIVITY", if (events.length() > 0) "${events.length()} events" else ""))
        if (events.length() == 0) {
            val emptyActivity = designCard(orientation = LinearLayout.HORIZONTAL, paddingDp = 12, cornerDp = 14).apply {
                gravity = Gravity.CENTER_VERTICAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(8)
                }
            }
            emptyActivity.addView(TextView(this).apply {
                text = "✦"
                textSize = 16f
                setTextColor(Color.parseColor(CLR_CYAN))
                gravity = Gravity.CENTER
                layoutParams = LinearLayout.LayoutParams(dp(30), dp(30)).apply { rightMargin = dp(10) }
            })
            val emptyActivityCopy = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            }
            emptyActivityCopy.addView(TextView(this).apply {
                text = "No point activity yet"
                textSize = 12f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            })
            emptyActivityCopy.addView(TextView(this).apply {
                text = "Completed tasks and verified submissions will appear here."
                textSize = 10f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(2)
                }
            })
            emptyActivity.addView(emptyActivityCopy)
            contentContainer.addView(emptyActivity)
        } else {
            val firstRecent = (events.length() - 10).coerceAtLeast(0)
            for (i in events.length() - 1 downTo firstRecent) {
                val event = events.getJSONObject(i)
                val eventType = event.optString("event_type", "Score event")
                val row = buildEventRow(
                    event.optString("timestamp"),
                    LedgerSyncRules.transactionTitle(eventType),
                    event.optString("description"),
                    event.optInt("points")
                ) {
                    showEventAudit(event)
                }
                contentContainer.addView(row)
            }
        }

        contentContainer.addView(sectionHeading("PERMISSIONS"))
        val hasUsage = TargetAppMonitoringPolicy.canReadUsage(this)
        val permCard = designCard(orientation = LinearLayout.HORIZONTAL, paddingDp = 14, cornerDp = 16, strokeHex = if (hasUsage) CLR_GREEN else CLR_BORDER).apply {
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(2)
                bottomMargin = dp(10)
            }
        }
        val permInfo = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        permInfo.addView(TextView(this).apply {
            text = "OPTIONAL APP MONITORING"
            textSize = 12.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
        })
        permInfo.addView(TextView(this).apply {
            text = TargetAppMonitoringPolicy.monitoringStatus(this@MainActivity)
            textSize = 10f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(3)
            }
        })
        permCard.addView(permInfo)
        permCard.addView(makeSecondaryButton("CHOOSE APPS", if (hasUsage) CLR_GREEN else CLR_CYAN) {
            DisciplinePermissionManager.showTargetAppMonitoringSettings(this)
        })
        contentContainer.addView(permCard)

        // Accessibility Enforcement & Grace Status Card (Section 7)
        val graceStatus = AccessibilityGraceManager.getUiStatus(this)
        val accEnabled = HardwareDeviceVerifier.isAccessibilityServiceEnabled(this, StrictAccessibilityService::class.java)
        val isAccConnected = StrictAccessibilityService.activeInstance != null

        val strokeColor = when {
            graceStatus.statusText.startsWith("Penalty recorded") -> CLR_AMBER
            graceStatus.isInterrupted -> CLR_AMBER
            accEnabled && isAccConnected -> CLR_GREEN
            else -> CLR_BORDER
        }

        val accCard = designCard(orientation = LinearLayout.VERTICAL, paddingDp = 14, cornerDp = 16, strokeHex = strokeColor).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(2)
                bottomMargin = dp(10)
            }
        }

        val accHeaderRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }

        val accTitleCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }

        accTitleCol.addView(TextView(this).apply {
            text = "ACCESSIBILITY ENFORCEMENT & MONITORING"
            textSize = 12.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
        })

        accTitleCol.addView(TextView(this).apply {
            text = graceStatus.statusText
            textSize = 10.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (graceStatus.isInterrupted) CLR_AMBER else if (accEnabled && isAccConnected) CLR_GREEN else CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(3)
            }
        })
        accHeaderRow.addView(accTitleCol)

        val btnLabel = when {
            graceStatus.missingAccessType == AccessibilityGraceManager.MISSING_TYPE_USAGE_ACCESS -> "USAGE ACCESS"
            graceStatus.missingAccessType == AccessibilityGraceManager.MISSING_TYPE_BOTH -> "SETTINGS"
            else -> "ACCESSIBILITY"
        }
        val settingsBtn = makeSecondaryButton(btnLabel, if (graceStatus.isInterrupted) CLR_AMBER else CLR_CYAN) {
            try {
                val intent = if (graceStatus.missingAccessType == AccessibilityGraceManager.MISSING_TYPE_USAGE_ACCESS) {
                    Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS)
                } else {
                    Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)
                }
                startActivity(intent.apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) })
            } catch (_: Exception) {}
        }
        accHeaderRow.addView(settingsBtn)
        accCard.addView(accHeaderRow)

        if (graceStatus.isInterrupted && graceStatus.interruptedAtWallMs > 0L) {
            val sdf = java.text.SimpleDateFormat("HH:mm:ss", Locale.US)
            val detailsTv = TextView(this).apply {
                text = "Interrupted: ${sdf.format(java.util.Date(graceStatus.interruptedAtWallMs))}  |  Grace deadline: ${sdf.format(java.util.Date(graceStatus.graceDeadlineWallMs))}\nConfirmed usage: ${graceStatus.confirmedUsageDurationMs / 1000}s  |  Penalties: ${graceStatus.recordedPenaltyPoints} point(s)"
                textSize = 9.5f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(8)
                }
            }
            accCard.addView(detailsTv)
        }

        contentContainer.addView(accCard)
    }

    // ════════════════════════════════════════════════════════
    // PROFILE TAB
    // ════════════════════════════════════════════════════════

    private fun renderProfileTab(st: org.json.JSONObject, score: Int) {
        val levelTitle = DisciplineScoringRules.evaluateDisciplineLevel(score * 3)

        // Profile header
        val profileHero = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            gravity = Gravity.CENTER
            setPadding(dp(20), dp(28), dp(20), dp(24))
            background = gradientBg(CLR_SURFACE_LOW, CLR_SURFACE, 28)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        }
        val avatarImg = ImageView(this).apply {
            setImageResource(R.drawable.app_logo)
            scaleType = ImageView.ScaleType.FIT_CENTER
            background = surfaceBg(CLR_ELEVATED, 99, CLR_INDIGO, 2)
            setPadding(dp(4), dp(4), dp(4), dp(4))
            layoutParams = LinearLayout.LayoutParams(dp(80), dp(80)).apply {
                gravity = Gravity.CENTER_HORIZONTAL; bottomMargin = dp(14)
            }
        }
        avatarImg.scaleX = 0f; avatarImg.scaleY = 0f
        profileHero.addView(avatarImg)
        avatarImg.animate().scaleX(1f).scaleY(1f).setDuration(DUR_SPRING)
            .setInterpolator(OvershootInterpolator(1.8f)).start()

        val userName = db.getUserDisplayName()
        profileHero.addView(TextView(this).apply {
            text = userName; textSize = 20f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE); gravity = Gravity.CENTER
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(2) }
        })
        profileHero.addView(TextView(this).apply {
            text = "PRIMARY ADMINISTRATOR • $levelTitle"; textSize = 11f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_INDIGO)); gravity = Gravity.CENTER
            letterSpacing = 0.08f
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(14) }
        })

        // Stat row
        val statRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        listOf(
            Triple(score.toString(), "Score", scoreColor(score)),
            Triple("${st.optInt("hourly_completed", 0)}", "Hours", CLR_BLUE),
            Triple("${st.optInt("streak_days", 0)}d", "Streak", CLR_GREEN)
        ).forEachIndexed { i, (value, label, color) ->
            if (i > 0) {
                statRow.addView(View(this).apply {
                    background = surfaceBg(CLR_TEXT_DIM, 2)
                    layoutParams = LinearLayout.LayoutParams(dp(1), dp(32))
                })
            }
            val statCol = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                gravity = Gravity.CENTER
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            }
            statCol.addView(TextView(this).apply {
                text = value; textSize = 22f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(color)); gravity = Gravity.CENTER
            })
            statCol.addView(TextView(this).apply {
                text = label; textSize = 9f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY)); gravity = Gravity.CENTER
                letterSpacing = 0.06f
            })
            statRow.addView(statCol)
        }
        profileHero.addView(statRow)
        contentContainer.addView(profileHero)
        contentContainer.addView(DemoAccessSettingsCard.create(this) { db.getScore(db.nowDate(), false) })
        contentContainer.addView(StrictRecordsPowerSettingsCard.create(this) { refreshUi() })
        contentContainer.addView(AiHealthSettingsCard.create(this) { refreshUi() })

        // Settings rows
        val nextDayState = db.getNextDayScheduleState()
        val nextDateStr = nextDayState.optString("schedule_date", db.getNextCalendarDate())
        val isNextDayLocked = nextDayState.optBoolean("is_locked", false)
        val todayDate = db.nowDate()
        val (canEditBath, editBathReason) = db.canEditTodayBathPlan(todayDate)
        val isBathPlanConfirmed = db.isBathScheduleConfirmed(todayDate)
        val bathPlan = if (isBathPlanConfirmed) db.getDailyBathPlan(todayDate) else null
        val committedBathTimesDisplay = bathPlan?.optJSONArray("selected_bath_times")?.let { arr ->
            (0 until arr.length()).map { DisciplineScoringRules.formatTime12h(arr.optString(it)) }.joinToString(", ")
        } ?: ""

        val bathSettingsTitle = if (isBathPlanConfirmed) "🚿 Today's Bath Plan (Locked)" else "🚿 Configure Today's Bath Plan"
        val bathSettingsSubtitle = if (!isBathPlanConfirmed) {
            "Today's plan unconfirmed • Tap to configure"
        } else {
            if (committedBathTimesDisplay.isNotBlank()) "Today's bath time is locked ($committedBathTimesDisplay)" else "Today's bath time is locked"
        }
        contentContainer.addView(sectionHeading("SETTINGS"))
        contentContainer.addView(GymRoutineUi.createEntry(this, db) { showDeviceCenterDialog() })
        listOf(
            Triple("📅 Strict Calendar", "Monthly view • Daily schedules, Gym routine & verifications") {
                StrictCalendarUi.showCalendar(this, db)
            },
            Triple("📅 Schedule & Routine",
                if (isNextDayLocked) "Tomorrow ($nextDateStr) • LOCKED (SCHEDULED)" else "Configure tomorrow ($nextDateStr) • Wake-Up 6:00–10:00 AM") {
                showNextDayRoutinePlannerDialog()
            },
            Triple(bathSettingsTitle, bathSettingsSubtitle) {
                showBathScheduleConfirmationDialog(isEditing = isBathPlanConfirmed)
            },
            Triple("▦ Widgets", "Home-screen previews, sizes, content and appearance") {
                startActivity(Intent(this, StrictWidgetConfigurationActivity::class.java))
            },
            Triple("🎵 Wake-up Music",
                WakeUpMusicManager.getCurrentTrack(this)?.let {
                    val lockMsg = if (WakeUpMusicManager.isSelectionLocked(this)) "Locked until ${it.lockUntilDate}" else "Selection available"
                    "${it.title} • $lockMsg"
                } ?: "Default motivation track • Monthly locked selection") {
                showWakeUpMusicSettingsDialog()
            },
            Triple("🛡 Mode", if (isDevMode) "Developer mode active" else "Production mode") {
                isDevMode = !isDevMode; refreshUi()
            },
            Triple("📊 Selected-App Monitoring", TargetAppMonitoringPolicy.monitoringStatus(this)) {
                DisciplinePermissionManager.showTargetAppMonitoringSettings(this)
            },
            Triple("⏱ Scheduler & Alarm Diagnostics", "Next window, alarms, permissions & boot recovery") {
                showSchedulerDiagnosticsDialog()
            },
            Triple("🛡 Permissions & Access Center", "${DisciplinePermissionManager.getGrantedCount(this)}/${DisciplinePermissionManager.getTotalCount()} Verified") {
                DisciplinePermissionManager.showPermissionSetupSheet(this) { refreshUi() }
            },
            Triple("🔑 Admin Console & Permissions", if (db.isDefaultAdminPin()) "Initial key (1234) active • PIN required" else "Protected admin controls • PIN required") {
                promptAdminPinDialog()
            },
            Triple("⚙️ Change Admin Access Key", if (db.isDefaultAdminPin()) "Initial setup key (1234) • Change key" else "Custom security PIN configured") {
                promptChangeAdminPinDialog()
            },
            Triple("📱 Device Center & PC Pairing", if (db.isDeviceRegistered()) "● Registered" else "○ Not Paired") {
                showDeviceCenterDialog()
            },
            Triple("🔄 Sync Mesh", "Force sync records with PC") { triggerServerSync() },
            Triple("🐞 Report a Bug", "Submit an issue, unexpected behavior, or diagnostic logs") {
                showReportBugDialog()
            }
        ).forEach { (title, sub, action) ->
            val row = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                setPadding(dp(16), dp(14), dp(16), dp(14))
                background = surfaceBg(CLR_SURFACE, 18)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
                applySpringTouch { action() }
            }
            val col = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            }
            col.addView(TextView(this).apply {
                text = title; textSize = 14f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            })
            col.addView(TextView(this).apply {
                text = sub; textSize = 10.5f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            })
            row.addView(col)
            row.addView(TextView(this).apply {
                text = "›"; textSize = 18f
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
            })
            contentContainer.addView(row)
        }

        // Consolidated All Verification Settings
        contentContainer.addView(sectionHeading("ALL VERIFICATION SETTINGS"))
        listOf(
            Triple("🧪 Test Wake-Up Verification", "Practice 3-step verification • Camera, earbuds & audio (zero score impact)") {
                WakeUpVerificationController.showWakeUpVerificationDialog(this, db, isDevMode = true) { refreshUi() }
            },
            Triple("🌙 Test Mi Sleep Data Demo", "Upload Mi Fitness screenshot • Test OCR extraction & algorithm points (zero score impact)") {
                MiFitnessSleepController.showSleepDemoTestDialog(this, db)
            },
            Triple("🏋️ Mi Fitness Gym Sandbox", "Upload workout screenshot • Test OCR extraction, metrics & session matching (zero score impact)") {
                MiFitnessGymWorkoutController.showGymWorkoutDemoTestDialog(this, db)
            },
            Triple("🤖 Taufa AI Validation Demo", "Test Hourly Attendance AI evaluation • Category, description & up to 10 photos (zero score impact)") {
                showTaufaAiValidationDemoDialog()
            },
            Triple("🔍 Test Image & Text Analysis", "Diagnostic mode • Test multi-image OCR & visual duplicate checks (zero score impact)") {
                showImageAnalysisDiagnosticsDialog()
            },
            Triple("🎧 Configured Earbuds", db.getEarbudsConfig()) {
                DisciplinePermissionManager.showEarbudsSelectionDialog(this) { refreshUi() }
            },
            Triple("🔬 Internal Diagnostics & Test", "Hardware checks, LAN ping & YouTube test") {
                DisciplinePermissionManager.showDiagnosticsScreen(this, score) { refreshUi() }
            }
        ).forEach { (title, sub, action) ->
            val row = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                setPadding(dp(16), dp(14), dp(16), dp(14))
                background = surfaceBg(CLR_SURFACE, 18)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
                applySpringTouch { action() }
            }
            val col = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            }
            col.addView(TextView(this).apply {
                text = title; textSize = 14f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            })
            col.addView(TextView(this).apply {
                text = sub; textSize = 10.5f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            })
            row.addView(col)
            row.addView(TextView(this).apply {
                text = "›"; textSize = 18f
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
            })
            contentContainer.addView(row)
        }

        // Hardware & Capability Diagnostics
        contentContainer.addView(sectionHeading("HARDWARE & CAPABILITY DIAGNOSTICS"))
        val camGranted = DisciplinePermissionManager.isGranted(this, PermissionCapability.CAMERA)
        val btGranted = DisciplinePermissionManager.isGranted(this, PermissionCapability.BLUETOOTH)
        val usageGranted = DisciplinePermissionManager.isGranted(this, PermissionCapability.USAGE_STATS)
        val notifGranted = DisciplinePermissionManager.isGranted(this, PermissionCapability.NOTIFICATIONS)
        val alarmGranted = DisciplinePermissionManager.isGranted(this, PermissionCapability.EXACT_ALARM)
        val battGranted = DisciplinePermissionManager.isGranted(this, PermissionCapability.BATTERY_OPTIMIZATION)
        val musicNotifGranted = StrictMediaNotificationListener.isNotificationAccessGranted(this)
        val btList = HardwareDeviceVerifier.getConnectedBluetoothAudioDevices(this)

        val diagCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(14), dp(16), dp(14))
            background = surfaceBg(CLR_SURFACE, 20)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        data class DiagItem(val label: String, val status: String, val isOk: Boolean, val onAction: () -> Unit)
        listOf(
            DiagItem("📷 Camera Capability", if (camGranted) "GRANTED ✓" else "TAP TO GRANT ⚠", camGranted) {
                DisciplinePermissionManager.ensureCapability(this, PermissionCapability.CAMERA, "Diagnostics Test") { refreshUi() }
            },
            DiagItem("🎧 Bluetooth Earphones", if (btGranted) "GRANTED ✓ (${if (btList.isNotEmpty()) btList.first() else "No audio device"})" else "TAP TO GRANT ⚠", btGranted) {
                DisciplinePermissionManager.ensureCapability(this, PermissionCapability.BLUETOOTH, "Diagnostics Test") { refreshUi() }
            },
            DiagItem("📊 Selected-App Monitoring", TargetAppMonitoringPolicy.monitoringStatus(this), usageGranted) {
                DisciplinePermissionManager.showTargetAppMonitoringSettings(this)
            },
            DiagItem("🎵 Background Music Restriction", if (musicNotifGranted) "ACTIVE ✓" else "TAP TO CONFIGURE (MEDIA LISTENER)", musicNotifGranted) {
                DisciplinePermissionManager.ensureCapability(this, PermissionCapability.NOTIFICATION_LISTENER, "Background Music Restriction") { refreshUi() }
            },
            DiagItem("🔔 Discipline Alerts", if (notifGranted) "GRANTED ✓" else "TAP TO GRANT ⚠", notifGranted) {
                DisciplinePermissionManager.ensureCapability(this, PermissionCapability.NOTIFICATIONS, "Diagnostics Test") { refreshUi() }
            },
            DiagItem("⏰ Exact Alarm Scheduling", if (alarmGranted) "GRANTED ✓" else "TAP TO GRANT ⚠", alarmGranted) {
                DisciplinePermissionManager.ensureCapability(this, PermissionCapability.EXACT_ALARM, "Diagnostics Test") { refreshUi() }
            },
            DiagItem("⚡ Battery Optimization", if (battGranted) "EXEMPT ✓" else "TAP TO EXEMPT ⚠", battGranted) {
                DisciplinePermissionManager.ensureCapability(this, PermissionCapability.BATTERY_OPTIMIZATION, "Diagnostics Test") { refreshUi() }
            },
            DiagItem("📁 Audit Evidence Store", db.exportLocalEvidencePackage(db.nowDate(), isDevMode).name, true) {}
        ).forEach { item ->
            val stackDiagnostic = DiagnosticLayoutRules.itemStacked(resources.displayMetrics.widthPixels / resources.displayMetrics.density - 64f, resources.configuration.fontScale, item.status.length)
            val r = LinearLayout(this).apply {
                orientation = if (stackDiagnostic) LinearLayout.VERTICAL else LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(10) }
                applySpringTouch { item.onAction() }
            }
            r.addView(TextView(this).apply {
                text = item.label; textSize = 12f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = if (stackDiagnostic) LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
                    else LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 3f)
            })
            r.addView(TextView(this).apply {
                text = item.status; textSize = 11f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(if (item.isOk) CLR_GREEN else CLR_AMBER))
                maxLines = Int.MAX_VALUE
                setSingleLine(false)
                ellipsize = null
                gravity = if (stackDiagnostic) Gravity.START else Gravity.END
                layoutParams = if (stackDiagnostic) LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(4) }
                    else LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 2f).apply { leftMargin = dp(12) }
            })
            diagCard.addView(r)
        }
        contentContainer.addView(diagCard)

        // Administration & Control
        contentContainer.addView(sectionHeading("ADMINISTRATION & CONTROL"))
        val adminCard = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(16), dp(16), dp(16), dp(16))
            background = surfaceBg(CLR_SURFACE, 20, if (isAdminMode) CLR_GREEN else CLR_INDIGO, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(20) }
            applySpringTouch {
                if (isAdminMode) {
                    activeTab = "ADMIN"
                    refreshUi()
                } else {
                    promptAdminPinDialog()
                }
            }
        }
        val adminCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        adminCol.addView(TextView(this).apply {
            text = if (isAdminMode) "🛡 ADMIN MODE ACTIVE" else "🛡 ADMIN MODE CONSOLE"
            textSize = 14f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (isAdminMode) CLR_GREEN else CLR_TEXT_PRIMARY))
        })
        adminCol.addView(TextView(this).apply {
            text = if (isAdminMode) "Tap to open full Admin Dashboard" else "Secure proof review, scoring engine & device control (administrator key required)"
            textSize = 10.5f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
        })
        adminCard.addView(adminCol)
        adminCard.addView(makeSecondaryButton(if (isAdminMode) "OPEN" else "LOGIN", if (isAdminMode) CLR_GREEN else CLR_INDIGO) {
            if (isAdminMode) {
                activeTab = "ADMIN"
                refreshUi()
            } else {
                promptAdminPinDialog()
            }
        })
        contentContainer.addView(adminCard)

        // Non-disturbing bug reporting footer in Settings & Profile
        val settingsBugFooter = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER
            setPadding(0, dp(14), 0, dp(24))
            applySpringTouch { showReportBugDialog() }
        }
        settingsBugFooter.addView(TextView(this).apply {
            text = "🐞 Need Help or Found a Bug? Tap to Report"
            textSize = 11.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
        })
        contentContainer.addView(settingsBugFooter)
    }

    private fun renderSingleVideoRewardSection(isTablet: Boolean): View = YouTubeRewardCard(this, db)

    // ════════════════════════════════════════════════════════
    // GYM MODE (Temporary Music Access & 3 Lives System)
    // ════════════════════════════════════════════════════════

        private fun renderGymModeSection(isTablet: Boolean): View {
        val container = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(8) }
        }

        container.addView(sectionHeading("GYM MODE", "Temporary Music Access"))

        val card = designCard(paddingDp = if (isTablet) 14 else 11, cornerDp = 16, strokeHex = CLR_BORDER).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }

        val titleRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
        }
        titleRow.addView(TextView(this).apply {
            text = "🏋️"
            textSize = 18f
            gravity = Gravity.CENTER
            layoutParams = LinearLayout.LayoutParams(dp(30), dp(30)).apply { rightMargin = dp(10) }
        })
        val titleTextCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        titleTextCol.addView(TextView(this).apply {
            text = "GYM Mode • Music Access"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
        })

        // Ensure weekly reset checked
        db.checkGymModeWeeklyReset()

        val nowMs = db.authoritativeNowMs()
        val tz = db.scheduleTimezone()
        val today = db.nowDate()
        val lives = db.getGymModeLives()
        val activeSession = db.getGymModeActiveSession(nowMs)
        val isMusicActive = GymModeRules.isMusicAccessActive(nowMs, activeSession)
        val (gymPlanned, gymPlanReason) = db.isLocalGymPlannedForDate(today)
        val previouslyActivated = db.getPreviouslyActivatedGymIds(today)
        val targetGym = db.getActiveOrTargetGymActivity(nowMs)
        val todayGymSetup = db.getDailyGymSetup(today)
        val gymTime = targetGym?.scheduledTime ?: todayGymSetup?.plannedStartTime ?: "18:00"
        val timing = GymModeRules.calculateTiming(gymTime, today, tz)
        val isWithinWindow = GymModeRules.isWithinActivationWindow(nowMs, gymTime, today, tz)
        val todayGymActId = targetGym?.activityId ?: db.ensureGymOccurrence(today)
        val isGymAlreadyUsed = previouslyActivated.contains(todayGymActId)
        val gymSyncStatus = db.getGymModeSyncStatus(today)

        titleTextCol.addView(TextView(this).apply {
            text = "Samsung Music & Spotify • 3 Lives • Scheduled: " + timing.scheduledTimeFormatted
            textSize = 10f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(2)
            }
        })
        titleRow.addView(titleTextCol)

        val statusText = when {
            isMusicActive -> if (gymSyncStatus == "PENDING_SYNC") "ACTIVE • LOCAL" else "ACTIVE"
            !gymPlanned -> "NOT PLANNED"
            lives <= 0 -> "0 LIVES"
            isGymAlreadyUsed -> "USED TODAY"
            nowMs < timing.activationAvailableMs -> "OPENS AT " + timing.activationAvailableFormatted
            nowMs >= timing.scheduledExpiryMs -> "EXPIRED"
            else -> "READY"
        }
        val statusColorHex = when {
            isMusicActive -> CLR_GREEN
            !gymPlanned -> CLR_TEXT_SECONDARY
            lives <= 0 -> CLR_RED
            isGymAlreadyUsed -> CLR_TEXT_SECONDARY
            nowMs < timing.activationAvailableMs -> CLR_AMBER
            nowMs >= timing.scheduledExpiryMs -> CLR_TEXT_SECONDARY
            else -> CLR_CYAN
        }
        val statusPill = designStatusPill(statusText, statusColorHex)
        titleRow.addView(statusPill)
        card.addView(titleRow)

        if (gymSyncStatus in listOf("PENDING_SYNC", "SYNCED", "CONFLICT")) {
            val syncBannerTv = TextView(this).apply {
                text = when (gymSyncStatus) {
                    "PENDING_SYNC" -> "⟳ Activated Locally on Phone • PC Synchronization Queued"
                    "CONFLICT" -> "⚠️ Sync Conflict Requires Review • Local ledger history preserved"
                    else -> "✓ Synchronized with Shared Ledger"
                }
                textSize = 10.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(when (gymSyncStatus) {
                    "PENDING_SYNC" -> CLR_AMBER
                    "CONFLICT" -> CLR_RED
                    else -> CLR_GREEN
                }))
                setPadding(0, dp(4), 0, dp(2))
            }
            card.addView(syncBannerTv)
        }

        // Lives Badge Row
        addDailyGymDecisionViews(card, today, "Gym today")
        val livesRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(10), dp(7), dp(10), dp(7))
            background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(10)
                bottomMargin = dp(8)
            }
        }
        val gymHearts = db.getGymHearts()
        val livesTv = TextView(this).apply {
            text = ThreeHeartAccountabilityEngine.formatHeartsBadge(gymHearts, "GYM ACCOUNTABILITY")
            textSize = 13f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(when (lives) {
                3 -> CLR_GREEN
                2 -> CLR_CYAN
                1 -> CLR_AMBER
                else -> CLR_RED
            }))
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        livesRow.addView(livesTv)

        val resetHintTv = TextView(this).apply {
            text = "Resets Mon 00:00"
            textSize = 10f
            setTextColor(Color.parseColor(CLR_TEXT_DIM))
        }
        livesRow.addView(resetHintTv)
        card.addView(livesRow)

        val contentSection = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        card.addView(contentSection)

        if (isMusicActive && activeSession != null) {
            // Active session UI (GYM MODE ACTIVE)
            val activeHeadingTv = TextView(this).apply {
                text = "GYM MODE ACTIVE"
                textSize = 15f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_GREEN))
                letterSpacing = 0.04f
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(4)
                    bottomMargin = dp(4)
                }
            }
            contentSection.addView(activeHeadingTv)

            val timerTv = TextView(this).apply {
                textSize = 18f
                setTypeface(Typeface.MONOSPACE, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_GREEN))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(6)
                }
            }
            contentSection.addView(timerTv)

            gymModeCountdownRunnable?.let { uiHandler.removeCallbacks(it) }
            val countdownRunnable = object : Runnable {
                override fun run() {
                    val curNow = db.authoritativeNowMs()
                    val rem = (activeSession.accessExpiryMs - curNow).coerceAtLeast(0L)
                    if (rem <= 0L) {
                        timerTv.text = "Session expired • Enforcing restriction"
                        timerTv.setTextColor(Color.parseColor(CLR_RED))
                        statusPill.text = "EXPIRED"
                        statusPill.background = surfaceBg(CLR_ELEVATED, 99, CLR_RED, 1)
                        statusPill.setTextColor(Color.parseColor(CLR_RED))
                        BackgroundMusicRestrictionManager.checkAndEnforceMusicRestrictions(this@MainActivity, "gym_mode_expired_timer")
                    } else {
                        val totalSecs = rem / 1000
                        val hh = totalSecs / 3600
                        val mm = (totalSecs % 3600) / 60
                        val ss = totalSecs % 60
                        timerTv.text = String.format(Locale.US, "Remaining time: %02d:%02d:%02d", hh, mm, ss)
                        uiHandler.postDelayed(this, 1000L)
                    }
                }
            }
            gymModeCountdownRunnable = countdownRunnable
            uiHandler.post(countdownRunnable)

            val infoTv = TextView(this).apply {
                text = "Scheduled end: " + timing.scheduledExpiryFormatted + "\n• Permitted: Samsung Music & Spotify only\n• YouTube, Instagram & Web remain strictly locked"
                textSize = 11f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                setLineSpacing(dp(2).toFloat(), 1f)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(10)
                }
            }
            contentSection.addView(infoTv)

            val btnRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }

            val statusBtn = makePrimaryButton("GYM MODE STATUS", CLR_GREEN, widthMatchParent = false) {
                AlertDialog.Builder(this)
                    .setTitle("GYM MODE ACTIVE")
                    .setMessage("Workout session active with music entitlement.\n\n" +
                            "• Scheduled Gym Start: " + timing.scheduledTimeFormatted + "\n" +
                            "• Scheduled End: " + timing.scheduledExpiryFormatted + "\n" +
                            "• Music Apps Allowed: Samsung Music & Spotify\n" +
                            "• Remaining Lives: " + GymModeRules.formatLivesBadge(lives) + "\n\n" +
                            "Proof obligation is active until workout verification photo is submitted.")
                    .setPositiveButton("SUBMIT PROOF") { _, _ -> showGymProofDialog(targetGym) }
                    .setNeutralButton("EARLY EXIT") { _, _ ->
                        gymModeCountdownRunnable?.let { uiHandler.removeCallbacks(it) }
                        db.deactivateGymModeEarly(context = this@MainActivity)
                        Toast.makeText(this@MainActivity, "GYM Mode music access deactivated.", Toast.LENGTH_SHORT).show()
                        refreshUi()
                    }
                    .setNegativeButton("DISMISS", null)
                    .show()
            }
            btnRow.addView(statusBtn)

            val proofBtn = makeSecondaryButton("SUBMIT PROOF", CLR_CYAN) {
                showGymProofDialog(targetGym)
            }.apply {
                (layoutParams as? LinearLayout.LayoutParams)?.leftMargin = dp(8)
            }
            btnRow.addView(proofBtn)

            val exitBtn = makeSecondaryButton("EARLY EXIT", CLR_AMBER) {
                AlertDialog.Builder(this)
                    .setTitle("Toggle Off GYM Mode?")
                    .setMessage("Ending music access early revokes Samsung Music and Spotify permissions immediately.\n\nIMPORTANT: Your Gym proof obligation remains active and MUST still be submitted before the deadline, or 1 life will be deducted.")
                    .setPositiveButton("END MUSIC ACCESS") { _, _ ->
                        gymModeCountdownRunnable?.let { uiHandler.removeCallbacks(it) }
                        db.deactivateGymModeEarly(context = this@MainActivity)
                        Toast.makeText(this@MainActivity, "GYM Mode music access deactivated.", Toast.LENGTH_SHORT).show()
                        refreshUi()
                    }
                    .setNegativeButton("KEEP LISTENING", null)
                    .show()
            }.apply {
                (layoutParams as? LinearLayout.LayoutParams)?.leftMargin = dp(8)
            }
            btnRow.addView(exitBtn)

            contentSection.addView(btnRow)

        } else {
            // Inactive session UI
            val scheduleCard = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(14), dp(12), dp(14), dp(12))
                background = surfaceBg(CLR_SURFACE_LOW, 12, CLR_BORDER, 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(10)
                }
            }

            scheduleCard.addView(TextView(this).apply {
                text = "GYM MODE"
                textSize = 13f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_CYAN))
                letterSpacing = 0.05f
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(6)
                }
            })

            scheduleCard.addView(TextView(this).apply {
                text = "Scheduled time: " + timing.scheduledTimeFormatted + "\nActivation available: " + timing.activationAvailableFormatted + "\nScheduled expiry: " + timing.scheduledExpiryFormatted
                textSize = 12f
                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                setLineSpacing(dp(3).toFloat(), 1f)
            })
            contentSection.addView(scheduleCard)

            val countdownTv = TextView(this).apply {
                textSize = 12f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_AMBER))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(8)
                }
            }

            if (!gymPlanned) {
                countdownTv.text = gymPlanReason
                countdownTv.setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                contentSection.addView(countdownTv)
            } else if (lives <= 0) {
                val nextResetMs = GymModeRules.calculateNextWeeklyResetMs(nowMs, tz)
                val nextResetStr = SimpleDateFormat("EEEE, MMM d 'at' 12:00 AM", Locale.US).apply {
                    timeZone = TimeZone.getTimeZone(tz)
                }.format(java.util.Date(nextResetMs))
                countdownTv.text = "No lives remaining. GYM Mode is disabled until weekly reset on " + nextResetStr + "."
                countdownTv.setTextColor(Color.parseColor(CLR_RED))
                contentSection.addView(countdownTv)
            } else if (isGymAlreadyUsed) {
                countdownTv.text = "Today's Gym session has already been used for GYM Mode."
                countdownTv.setTextColor(Color.parseColor(CLR_TEXT_DIM))
                contentSection.addView(countdownTv)
            } else if (nowMs >= timing.scheduledExpiryMs) {
                countdownTv.text = "Scheduled session expired for today at " + timing.scheduledExpiryFormatted + "."
                countdownTv.setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                contentSection.addView(countdownTv)
            } else if (nowMs < timing.activationAvailableMs) {
                contentSection.addView(countdownTv)

                gymModeCountdownRunnable?.let { uiHandler.removeCallbacks(it) }
                val waitRunnable = object : Runnable {
                    override fun run() {
                        val cur = db.authoritativeNowMs()
                        val diff = (timing.activationAvailableMs - cur).coerceAtLeast(0L)
                        if (diff <= 0L) {
                            refreshUi()
                        } else {
                            val totalSec = diff / 1000
                            val mm = totalSec / 60
                            val ss = totalSec % 60
                            countdownTv.text = String.format(Locale.US, "Activation available in %02d:%02d (at %s)", mm, ss, timing.activationAvailableFormatted)
                            uiHandler.postDelayed(this, 1000L)
                        }
                    }
                }
                gymModeCountdownRunnable = waitRunnable
                uiHandler.post(waitRunnable)

                val disabledBtn = makePrimaryButton("ACTIVATE GYM MODE", CLR_SURFACE, widthMatchParent = true) {
                    Toast.makeText(this@MainActivity, "Gym Mode will become available at " + timing.activationAvailableFormatted + " (5 min before gym time).", Toast.LENGTH_SHORT).show()
                }.apply {
                    isEnabled = false
                    alpha = 0.5f
                }
                contentSection.addView(disabledBtn)
            } else {
                val activateBtn = makePrimaryButton("ACTIVATE GYM MODE", CLR_GREEN, widthMatchParent = true) { btn ->
                    AlertDialog.Builder(this)
                        .setTitle("Activate GYM Mode?")
                        .setMessage("Unlock Samsung Music and Spotify for your workout session.\n\n" +
                                "• Scheduled Time: " + timing.scheduledTimeFormatted + "\n" +
                                "• Scheduled Expiry: " + timing.scheduledExpiryFormatted + " (anchored to scheduled start)\n" +
                                "• Remaining Lives: " + GymModeRules.formatLivesBadge(lives) + "\n\n" +
                                "REQUIREMENT: You must complete your workout and submit valid Gym proof today. Missing the proof deadline or submitting fraudulent proof will deduct 1 life.")
                        .setPositiveButton("ACTIVATE") { _, _ ->
                            setPrimaryButtonLabel(btn, "ACTIVATING...")
                            Thread({
                                val res = db.activateGymMode(todayGymActId, context = this@MainActivity)
                                runOnUiThread {
                                    Toast.makeText(this@MainActivity, res.message, Toast.LENGTH_LONG).show()
                                    if (res.success) refreshUi() else setPrimaryButtonLabel(btn, "ACTIVATE GYM MODE")
                                }
                            }, "GymMode-Activate").start()
                        }
                        .setNegativeButton("CANCEL", null)
                        .show()
                }
                contentSection.addView(activateBtn)
            }
        }

        // Rule Disclosure Footer
        val disclosureTv = TextView(this).apply {
            text = "Rule 8: Early exit revokes music immediately but keeps Gym proof obligation active. 1 life deducted only on confirmed fraud or expired proof deadline. Lives replenish Mondays at 12:00 AM."
            textSize = 9.5f
            setTextColor(Color.parseColor(CLR_TEXT_DIM))
            setLineSpacing(dp(2).toFloat(), 1f)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(10)
            }
        }
        card.addView(disclosureTv)

        container.addView(card)
        return container
    }

    // ════════════════════════════════════════════════════════
    // STRICTBOT PANEL (premium bottom sheet style)
    // ════════════════════════════════════════════════════════

    private fun showStrictBotPanel() {
        if (::strictBotChat.isInitialized) strictBotChat.show()
    }

    private fun navigateStrictBotAction(target: String) {
        when (target) {
            "WAKEUP" -> showWakeUpVerificationDialog()
            "SCHEDULE" -> showNextDayRoutinePlannerDialog()
            "PERMISSIONS" -> DisciplinePermissionManager.showPermissionSetupSheet(this) {
                refreshUi()
                strictBotChat.recheckPermissions()
            }
            "REPORTS" -> showTodaysSummaryDialog()
            "TASKS", "EVIDENCE" -> { activeTab = "CHALLENGES"; refreshUi() }
            "DEVICES" -> { activeTab = "DEVICES"; refreshUi() }
            "PRIVILEGES" -> { activeTab = "REWARDS"; refreshUi() }
            "SETTINGS", "PROFILE" -> { activeTab = "PROFILE"; refreshUi() }
            "BUG", "REPORT", "REPORT_BUG" -> showReportBugDialog()
            // Opening admin navigation still uses the existing access flow. The
            // assistant's administrator authorization is enforced independently on the PC.
            "ADMIN" -> promptAdminPinDialog()
        }
    }

    // ════════════════════════════════════════════════════════
    // TODAY'S TRUTHFUL SUMMARY VIEW (Part 4 / Section 8)
    // ════════════════════════════════════════════════════════
    private fun showTodaysSummaryDialog() {
        showTodaysSummaryDialog(null as String?)
    }

    private fun showTodaysSummaryDialog(targetDate: String?) {
        dispatchStrictBotEvent("DAILY_SUMMARY_READY")
        val date = targetDate ?: db.nowDate()
        val summary = db.getTruthfulDailySummary(date, isDevMode)
        val overview = summary.optJSONObject("activity_overview") ?: JSONObject()
        val prodBreakdown = summary.optJSONObject("productivity_breakdown") ?: JSONObject()
        val evReview = summary.optJSONObject("evidence_review") ?: JSONObject()
        val scoreRewards = summary.optJSONObject("score_and_rewards") ?: JSONObject()
        val strictBotSummary = summary.optString("strictbot_summary", "No activity records found for today yet.")
        val observations = summary.optJSONArray("observations") ?: org.json.JSONArray()
        val recommendations = summary.optJSONArray("recommendations") ?: org.json.JSONArray()
        val formattedText = summary.optString("formatted_text", "")
        val snapVer = summary.optInt("snapshot_version", 1)
        val snapHash = summary.optString("snapshot_hash", "").take(10)

        val scroll = ScrollView(this).apply {
            isVerticalScrollBarEnabled = true
        }
        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(18), dp(20), dp(18))
            background = surfaceBg(CLR_MODAL, 22, CLR_BORDER, 1)
        }
        scroll.addView(dialogView)

        var dialogRef: AlertDialog? = null

        // Header row
        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        }
        headerRow.addView(ImageView(this).apply {
            setImageResource(R.drawable.strict_bot_mascot)
            scaleType = ImageView.ScaleType.FIT_CENTER
            layoutParams = LinearLayout.LayoutParams(dp(36), dp(36)).apply { rightMargin = dp(10) }
        })
        val titleCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        titleCol.addView(TextView(this).apply {
            text = "STRICTRECORDS — DAILY SUMMARY"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            letterSpacing = 0.04f
        })
        titleCol.addView(TextView(this).apply {
            text = "Snapshot v$snapVer ($snapHash)"
            textSize = 10f
            setTypeface(Typeface.MONOSPACE, Typeface.NORMAL)
            tag = "telemetry_type"
            setTextColor(Color.parseColor(CLR_CYAN))
        })
        headerRow.addView(titleCol)
        dialogView.addView(headerRow)

        // Date Navigation Row (View current day & historical previous days)
        val dateNavRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(6), dp(4), dp(6), dp(4))
            background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(6)
                bottomMargin = dp(8)
            }
        }

        val prevBtn = makeSecondaryButton("◀ PREV", CLR_CYAN) {
            val cal = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone(db.scheduleTimezone()))
            val parts = date.split("-")
            if (parts.size == 3) {
                cal.set(parts[0].toInt(), parts[1].toInt() - 1, parts[2].toInt())
                cal.add(java.util.Calendar.DAY_OF_YEAR, -1)
                val sdf = SimpleDateFormat("yyyy-MM-dd", Locale.US).apply { timeZone = java.util.TimeZone.getTimeZone(db.scheduleTimezone()) }
                dialogRef?.dismiss()
                showTodaysSummaryDialog(sdf.format(cal.time))
            }
        }.apply {
            setPadding(dp(8), dp(4), dp(8), dp(4))
        }
        dateNavRow.addView(prevBtn)

        val dateDisplayTv = TextView(this).apply {
            text = "📅 $date"
            textSize = 12.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            gravity = Gravity.CENTER
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            setOnClickListener {
                val parts = date.split("-")
                val y = parts.getOrNull(0)?.toIntOrNull() ?: 2026
                val m = (parts.getOrNull(1)?.toIntOrNull() ?: 11) - 1
                val d = parts.getOrNull(2)?.toIntOrNull() ?: 2
                android.app.DatePickerDialog(this@MainActivity, { _, selY, selM, selD ->
                    val selDate = String.format(Locale.US, "%04d-%02d-%02d", selY, selM + 1, selD)
                    dialogRef?.dismiss()
                    showTodaysSummaryDialog(selDate)
                }, y, m, d).show()
            }
        }
        dateNavRow.addView(dateDisplayTv)

        val nextBtn = makeSecondaryButton("NEXT ▶", CLR_CYAN) {
            val cal = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone(db.scheduleTimezone()))
            val parts = date.split("-")
            if (parts.size == 3) {
                cal.set(parts[0].toInt(), parts[1].toInt() - 1, parts[2].toInt())
                cal.add(java.util.Calendar.DAY_OF_YEAR, 1)
                val sdf = SimpleDateFormat("yyyy-MM-dd", Locale.US).apply { timeZone = java.util.TimeZone.getTimeZone(db.scheduleTimezone()) }
                val nextStr = sdf.format(cal.time)
                if (nextStr <= db.nowDate()) {
                    dialogRef?.dismiss()
                    showTodaysSummaryDialog(nextStr)
                } else {
                    Toast.makeText(this@MainActivity, "Cannot view summary for future dates.", Toast.LENGTH_SHORT).show()
                }
            }
        }.apply {
            setPadding(dp(8), dp(4), dp(8), dp(4))
        }
        dateNavRow.addView(nextBtn)
        dialogView.addView(dateNavRow)

        fun addSummarySectionCard(title: String, accentHex: String, lines: List<String>) {
            val card = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(14), dp(12), dp(14), dp(12))
                background = surfaceBg(CLR_SURFACE, 14, CLR_BORDER, 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(10) }
            }
            card.addView(TextView(this).apply {
                text = title
                textSize = 10.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(accentHex))
                letterSpacing = 0.06f
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
            })
            lines.forEach { line ->
                card.addView(TextView(this).apply {
                    text = line
                    textSize = 11.5f
                    setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                    setPadding(0, dp(2), 0, dp(2))
                })
            }
            dialogView.addView(card)
        }

        // 1. Overall Daily Productivity Score evaluated by Taufa AI
        val verifiedCount = overview.optInt("verified_count", 0)
        val schedCount = overview.optInt("scheduled_count", 0)
        val compCount = overview.optInt("completed_count", 0)
        val pendingCount = overview.optInt("pending_review_count", 0)
        val rejectedCount = overview.optInt("rejected_count", 0)
        val missedCount = overview.optInt("missed_count", 0)

        val taufaScore = if (schedCount > 0) ((verifiedCount.toDouble() / schedCount.toDouble()) * 100).toInt().coerceIn(0, 100) else 75
        val gate2Eligible = taufaScore >= 70

        addSummarySectionCard(
            "TAUFA AI DAILY PRODUCTIVITY EVALUATION",
            if (gate2Eligible) CLR_GREEN else CLR_AMBER,
            listOf(
                "• Overall Daily Productivity Score: $taufaScore%",
                "• Evaluation: " + if (gate2Eligible) "High Academic Discipline (>= 70%)" else "Insufficient Evidence (< 70%)",
                "• Gate 2 YouTube Override (9:40 PM – 10:00 PM IST): " + if (gate2Eligible) "ELIGIBLE" else "INELIGIBLE",
                "• Designated Taufa Chat: 891a3c1e-eed2-460e-bc05-6b8ac94bec5b"
            )
        )

        // 2. Summary of Completed Study Sessions & Total Study Time Achieved
        val focusSessionsCount = prodBreakdown.optJSONObject("focus_sessions")?.optInt("count", 0) ?: 0
        val focusTrackedMinutes = prodBreakdown.optJSONObject("focus_sessions")?.optInt("tracked_minutes", 0) ?: 0
        val studySessionsCount = prodBreakdown.optJSONObject("study_reading")?.optInt("count", 0) ?: 0
        val codingSessionsCount = prodBreakdown.optJSONObject("coding_technical")?.optInt("count", 0) ?: 0
        val totalTrackedMinutes = focusTrackedMinutes + (verifiedCount * 45)
        val studyHrs = totalTrackedMinutes / 60
        val studyMins = totalTrackedMinutes % 60

        addSummarySectionCard(
            "STUDY SESSIONS OVERVIEW",
            CLR_CYAN,
            listOf(
                "• Total study time achieved: " + (if (studyHrs > 0) "${studyHrs}h ${studyMins}m" else "${studyMins}m") + " ($totalTrackedMinutes minutes tracked)",
                "• Completed study sessions: ${verifiedCount} of $schedCount sessions verified",
                "• Completion rate: ${overview.optDouble("completion_rate_pct", 0.0)}%"
            )
        )

        // 3. Categorization of Activities
        // - Technical / Coding, Aptitude, Reasoning, English, Core Academic
        val allActs = db.getDailyActivities(date)
        var countTech = 0; var compTech = 0
        var countApt = 0; var compApt = 0
        var countReason = 0; var compReason = 0
        var countEng = 0; var compEng = 0
        var countCore = 0; var compCore = 0

        for (a in allActs) {
            val t = (a.title ?: "").lowercase(Locale.ROOT)
            val st = a.status.uppercase(Locale.ROOT)
            val isDone = st in listOf("COMPLETED", "APPROVED", "VERIFIED")
            when {
                t.contains("code") || t.contains("coding") || t.contains("python") || t.contains("java") || t.contains("dsa") || t.contains("project") -> {
                    countTech++; if (isDone) compTech++
                }
                t.contains("aptitude") || t.contains("quant") || t.contains("math") -> {
                    countApt++; if (isDone) compApt++
                }
                t.contains("reason") || t.contains("logic") || t.contains("puzzle") -> {
                    countReason++; if (isDone) compReason++
                }
                t.contains("english") || t.contains("verbal") || t.contains("reading") -> {
                    countEng++; if (isDone) compEng++
                }
                else -> {
                    countCore++; if (isDone) compCore++
                }
            }
        }

        addSummarySectionCard(
            "ACTIVITY CATEGORIZATION",
            CLR_INDIGO,
            listOf(
                "• Technical / Coding: $compTech/$countTech completed",
                "• Aptitude: $compApt/$countApt completed",
                "• Reasoning: $compReason/$countReason completed",
                "• English: $compEng/$countEng completed",
                "• Core Academic Subjects: $compCore/$countCore completed"
            )
        )

        // 4. Verification Status of Proof Submissions (Verified, Pending, Rejected, Missed)
        addSummarySectionCard(
            "PROOF SUBMISSIONS VERIFICATION STATUS",
            CLR_AMBER,
            listOf(
                "• Verified submissions: $verifiedCount",
                "• Pending review: $pendingCount",
                "• Rejected submissions: $rejectedCount",
                "• Missed checkpoints: $missedCount",
                "• Total evidence files processed: ${evReview.optInt("total_files", 0)}"
            )
        )

        // 5. Detailed Hourly Breakdown Table (06:00 to 22:00)
        val hourlySlotsList = listOf(
            "06:00-07:00", "07:00-08:00", "08:00-09:00", "09:00-10:00",
            "10:00-11:00", "11:00-12:00", "12:00-13:00", "13:00-14:00",
            "14:00-15:00", "15:00-16:00", "16:00-17:00", "17:00-18:00",
            "18:00-19:00", "19:00-20:00", "20:00-21:00", "21:00-22:00"
        )

        val hourlyCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(14), dp(12), dp(14), dp(12))
            background = surfaceBg(CLR_SURFACE, 14, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(10) }
        }
        hourlyCard.addView(TextView(this).apply {
            text = "HOURLY STUDY & DISCIPLINE BREAKDOWN (06:00 - 22:00)"
            textSize = 10.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            letterSpacing = 0.06f
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
        })

        for (slot in hourlySlotsList) {
            val matched = allActs.firstOrNull { it.title?.contains(slot) == true || (it.windowStart?.contains(slot.split("-")[0]) == true && it.type.contains("HOURLY")) }
            val actName = matched?.title ?: "Discipline Check ($slot)"
            val st = (matched?.status ?: "MISSED").uppercase(Locale.ROOT)
            val valStatus = when {
                st in listOf("VERIFIED", "APPROVED", "COMPLETED") -> "Verified"
                st in listOf("PENDING", "SUBMITTED", "VALIDATING") -> "Pending"
                st == "REJECTED" -> "Rejected"
                else -> "Missed"
            }
            val statusColor = when (valStatus) {
                "Verified" -> CLR_GREEN
                "Pending" -> CLR_AMBER
                "Rejected" -> CLR_RED
                else -> CLR_TEXT_DIM
            }

            val slotRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                setPadding(dp(6), dp(4), dp(6), dp(4))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            slotRow.addView(TextView(this).apply {
                text = slot
                textSize = 10.5f
                setTypeface(Typeface.MONOSPACE, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(dp(82), ViewGroup.LayoutParams.WRAP_CONTENT)
            })
            slotRow.addView(TextView(this).apply {
                text = actName
                textSize = 11f
                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            })
            slotRow.addView(designStatusPill(valStatus, statusColor))
            hourlyCard.addView(slotRow)
        }
        dialogView.addView(hourlyCard)

        // 6. Formatted Report Text Block
        if (formattedText.isNotBlank()) {
            dialogView.addView(TextView(this).apply {
                text = formattedText
                textSize = 10f
                setTypeface(Typeface.MONOSPACE, Typeface.NORMAL)
                tag = "telemetry_type"
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                setPadding(dp(12), dp(10), dp(12), dp(10))
                background = surfaceBg(CLR_SURFACE_LOW, 12, CLR_BORDER, 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(10) }
            })
        }

        // Action buttons
        val btnRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.END
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(14) }
        }
        btnRow.addView(makeSecondaryButton("📋 COPY", CLR_CYAN) {
            val cm = getSystemService(Context.CLIPBOARD_SERVICE) as? android.content.ClipboardManager
            cm?.setPrimaryClip(android.content.ClipData.newPlainText("StrictRecords Daily Summary", formattedText.ifBlank { strictBotSummary }))
            Toast.makeText(this, "Daily summary copied to clipboard ✓", Toast.LENGTH_SHORT).show()
        }.apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { rightMargin = dp(8) }
        })
        btnRow.addView(makeSecondaryButton("🔊 SPEAK", CLR_GREEN) {
            speakStrictBot(strictBotSummary)
        }.apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { rightMargin = dp(8) }
        })
        btnRow.addView(makePrimaryButton("CLOSE", CLR_INDIGO) {
            dialogRef?.dismiss()
        })
        dialogView.addView(btnRow)

        dialogRef = AlertDialog.Builder(this)
            .setView(scroll)
            .setCancelable(true)
            .create().apply {
                window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
                show()
            }
    }

    // ── Floating bot message (contextual speech bubble) ────
    private fun triggerBotMessage(message: String, state: String = "IDLE") {
        strictBotState = state
        if (::strictBotChat.isInitialized && strictBotChat.isVisible) return
        val bubble = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(12), dp(10), dp(12), dp(10))
            background = surfaceBg(CLR_MODAL, 20, CLR_INDIGO, 1)
            elevation = dp(16).toFloat()
            alpha = 0f
            layoutParams = FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT,
                ViewGroup.LayoutParams.WRAP_CONTENT,
                Gravity.BOTTOM or Gravity.END
            ).apply {
                bottomMargin = dp(84); rightMargin = dp(16)
                // max width ~80% screen
            }
        }
        bubble.addView(TextView(this).apply {
            text = "🤖"; textSize = 16f
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { rightMargin = dp(8) }
        })
        bubble.addView(TextView(this).apply {
            text = message; textSize = 12f
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            maxLines = 2
        })
        rootFrame.addView(bubble)
        bubble.animate().alpha(1f).translationY(-dp(8).toFloat()).setDuration(DUR_MED).start()
        uiHandler.postDelayed({
            bubble.animate().alpha(0f).translationY(dp(8).toFloat()).setDuration(DUR_MED)
                .withEndAction { rootFrame.removeView(bubble) }.start()
        }, 2800L)
    }

    // ════════════════════════════════════════════════════════
    // SCORE BREAKDOWN SHEET
    // ════════════════════════════════════════════════════════

    private fun triggerScoreBreakdownSheet() {
        val st = db.getDayState(db.nowDate(), isDevMode)
        val sc = st.optInt("verified_points", st.optInt("score", 0))
        val events = db.getScoreEvents(db.nowDate(), isDevMode)
        val panel = FrameLayout(this).apply {
            background = surfaceBg(CLR_MODAL, 32, CLR_BLUE, 1)
            elevation = dp(24).toFloat()
            layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT, Gravity.BOTTOM)
            translationY = dp(600).toFloat()
        }
        val scroll = ScrollView(this).apply {
            isVerticalScrollBarEnabled = false
            overScrollMode = View.OVER_SCROLL_NEVER
        }
        val inner = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(24), dp(20), dp(48))
        }
        inner.addView(View(this).apply {
            background = surfaceBg(CLR_TEXT_DIM, 4)
            layoutParams = LinearLayout.LayoutParams(dp(40), dp(4)).apply {
                gravity = Gravity.CENTER_HORIZONTAL; bottomMargin = dp(16)
            }
        })
        inner.addView(TextView(this).apply {
            text = "SCORE BREAKDOWN"; textSize = 13f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY)); letterSpacing = 0.1f
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(4) }
        })
        inner.addView(TextView(this).apply {
            text = "$sc / 100"; textSize = 36f; setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(scoreColor(sc)))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(16) }
        })
        if (st.optInt("penalty_points", 0) > 0) {
            inner.addView(TextView(this).apply {
                text = "Earned points minus deductions. The daily score has a minimum of 0."
                textSize = 12f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(12) }
            })
        }
        for (i in 0 until events.length()) {
            val ev = events.getJSONObject(i)
            val pts = ev.getInt("points")
            val audit = ev.optJSONObject("audit") ?: JSONObject()
            val isReversed = audit.optString("remediation_status") == "REVERSED"
            val evType = ev.getString("event_type")
            val displayType = when {
                isReversed -> "$evType [REVERSED]"
                pts < 0 -> "$evType [APPROVED]"
                evType == "RECONCILIATION_COMPENSATION" -> "RECONCILIATION [RESTORED]"
                else -> evType
            }
            inner.addView(buildEventRow(ev.getString("timestamp"), displayType,
                ev.getString("description"), pts) {})
        }
        if (events.length() == 0) inner.addView(buildEmptyState("📋", "No events yet", "Complete tasks to see your breakdown."))

        // Criterion 8: Dashboard displays distinct statuses: Confirmed points vs. Pending proposals
        val pendingProps = db.getDeductionProposals(db.nowDate(), status = "AWAITING_CONFIRMATION")
        if (pendingProps.length() > 0) {
            inner.addView(TextView(this).apply {
                text = "PENDING DEDUCTION PROPOSALS (${pendingProps.length()})"; textSize = 11f; setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_AMBER)); letterSpacing = 0.08f
                setPadding(0, dp(16), 0, dp(4))
            })
            inner.addView(TextView(this).apply {
                text = "Secondary client proposals have 0 pt impact until authorized in Admin console."
                textSize = 10f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
            })
            for (i in 0 until pendingProps.length()) {
                val p = pendingProps.getJSONObject(i)
                val pPts = p.optInt("proposed_points", -10)
                val propRow = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.CENTER_VERTICAL
                    setPadding(dp(14), dp(10), dp(14), dp(10))
                    background = surfaceBg(CLR_SURFACE_LOW, 14, CLR_AMBER, 1)
                    layoutParams = LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                    ).apply { bottomMargin = dp(6) }
                }
                val info = LinearLayout(this).apply {
                    orientation = LinearLayout.VERTICAL
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                }
                info.addView(TextView(this).apply {
                    text = "${p.optString("event_type")} [PROPOSED]"; textSize = 11f; setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(CLR_AMBER))
                })
                info.addView(TextView(this).apply {
                    text = "${p.optString("reason")} • ${p.optString("timestamp")}"; textSize = 9.5f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    maxLines = 1; ellipsize = TextUtils.TruncateAt.END
                })
                propRow.addView(info)
                propRow.addView(TextView(this).apply {
                    text = "$pPts pts (0 pt impact)"; textSize = 11f; setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(CLR_AMBER))
                })
                inner.addView(propRow)
            }
        }
        val viewHistoryBtn = makePrimaryButton("VIEW GPAY TRANSACTION LEDGER 🧾", CLR_CYAN, widthMatchParent = true) {
            panel.animate().translationY(dp(600).toFloat()).setDuration(DUR_MED)
                .withEndAction {
                    rootFrame.removeView(panel)
                    activeTab = "TRANSACTIONS"
                    refreshUi()
                }.start()
        }
        viewHistoryBtn.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(14) }
        inner.addView(viewHistoryBtn)

        val closeBtn = makePrimaryButton("CLOSE BREAKDOWN", CLR_BLUE, widthMatchParent = true) {
            panel.animate().translationY(dp(600).toFloat()).setDuration(DUR_MED)
                .withEndAction { rootFrame.removeView(panel) }.start()
        }
        closeBtn.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(10) }
        inner.addView(closeBtn)
        scroll.addView(inner)
        panel.addView(scroll)
        rootFrame.addView(panel)
        panel.animate().translationY(0f).setDuration(DUR_SLOW).setInterpolator(DecelerateInterpolator(1.8f)).start()
        panel.setOnClickListener {
            panel.animate().translationY(dp(600).toFloat()).setDuration(DUR_MED)
                .withEndAction { rootFrame.removeView(panel) }.start()
        }
    }

    private fun showSchedulerDiagnosticsDialog() {
        val today = db.nowDate()
        val allActs = db.getDailyActivities(today)
        val nextWindow = allActs.firstOrNull { it.status == "OPEN" }
            ?: allActs.firstOrNull { it.status in listOf("UPCOMING", "NOTIFIED") }
        val nextWindowStr = if (nextWindow != null) {
            "${nextWindow.title}\nStatus: ${nextWindow.status} · Window: ${windowClock12h(nextWindow.windowStart)} – ${windowClock12h(nextWindow.windowEnd)}"
        } else {
            "No more windows scheduled today"
        }

        val lastRestoration = db.getConfigValue("diag_last_scheduler_restoration_time", "Not recorded")
        val lastSource = db.getConfigValue("diag_last_scheduler_restoration_source", "MANUAL")
        val nextAlarmTime = db.getConfigValue("diag_next_alarm_time", "None scheduled")
        val nextAlarmKey = db.getConfigValue("diag_next_alarm_key", "")

        val notifMgr = getSystemService(Context.NOTIFICATION_SERVICE) as? NotificationManager
        val notifEnabled = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
            notifMgr?.areNotificationsEnabled() != false
        } else true
        val postNotifGranted = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) == PackageManager.PERMISSION_GRANTED
        } else true
        val notifStatus = if (notifEnabled && postNotifGranted) "GRANTED (Active)" else "DENIED / RESTRICTED"

        val am = getSystemService(Context.ALARM_SERVICE) as? AlarmManager
        val exactAlarmStatus = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            if (am?.canScheduleExactAlarms() == true) "GRANTED (Exact Alarms Eligible)" else "PERMISSION_REQUIRED / LIMITED"
        } else {
            "GRANTED (Pre-Android 12)"
        }

        val lastFailure = db.getConfigValue("diag_last_failure_reason", "None")

        val panel = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(18), dp(20), dp(18))
            background = surfaceBg(CLR_MODAL, 20, CLR_BORDER, 1)
        }
        panel.addView(TextView(this).apply {
            text = "⏱ SCHEDULER & REBOOT DIAGNOSTICS"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
        })
        panel.addView(TextView(this).apply {
            text = "Live diagnostic status for AlarmManager, boot recovery, and submission window state."
            textSize = 11.5f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            setPadding(0, dp(6), 0, dp(12))
        })

        fun addDiagCard(title: String, value: String, accent: String = CLR_TEXT_PRIMARY) {
            val card = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(12), dp(10), dp(12), dp(10))
                background = surfaceBg(CLR_ELEVATED, 12, CLR_BORDER, 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
            }
            card.addView(TextView(this).apply {
                text = title
                textSize = 9.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            })
            card.addView(TextView(this).apply {
                text = value
                textSize = 12f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(accent))
                setPadding(0, dp(3), 0, 0)
            })
            panel.addView(card)
        }

        addDiagCard("NEXT SCHEDULED WINDOW", nextWindowStr, if (nextWindow?.status == "OPEN") CLR_GREEN else CLR_CYAN)
        addDiagCard("NEXT ALARM REGISTRATION", if (nextAlarmKey.isNotBlank()) "$nextAlarmTime\nTarget: $nextAlarmKey" else nextAlarmTime, CLR_GREEN)
        addDiagCard("LAST SCHEDULER RESTORATION", "$lastRestoration ($lastSource)", CLR_TEXT_PRIMARY)
        addDiagCard("NOTIFICATION PERMISSION", notifStatus, if (notifStatus.startsWith("GRANTED")) CLR_GREEN else CLR_RED)
        addDiagCard("EXACT ALARM ELIGIBILITY", exactAlarmStatus, if (exactAlarmStatus.startsWith("GRANTED")) CLR_GREEN else CLR_AMBER)
        addDiagCard("LAST FAILURE REASON", lastFailure, if (lastFailure == "None") CLR_GREEN else CLR_RED)

        val btnRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            setPadding(0, dp(6), 0, 0)
        }
        val dialogRef = arrayOfNulls<AlertDialog>(1)
        val refreshBtn = makePrimaryButton("RE-CHECK & RESTORE", CLR_GREEN) {
            WakeUpAlarmReceiver.scheduleDefaultDailyRoutine(this, "DIAGNOSTICS_REFRESH")
            Toast.makeText(this, "Scheduler re-synchronized ✓", Toast.LENGTH_SHORT).show()
            dialogRef[0]?.dismiss()
            showSchedulerDiagnosticsDialog()
        }.apply {
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(8) }
        }
        val closeBtn = makeSecondaryButton("CLOSE", CLR_TEXT_SECONDARY) {
            dialogRef[0]?.dismiss()
        }.apply {
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        btnRow.addView(refreshBtn)
        btnRow.addView(closeBtn)
        panel.addView(btnRow)

        val scroll = ScrollView(this).apply { addView(panel) }
        dialogRef[0] = AlertDialog.Builder(this)
            .setView(scroll)
            .create().apply {
                window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
                show()
            }
    }

