    private var imageDiagnosticResultView: TextView? = null
    private var imageDiagnosticUris: List<Uri> = emptyList()
    private val imageDiagnosticResults = mutableMapOf<String, JSONObject>()
    private val imageDiagnosticBusy = AtomicBoolean(false)
    private var imageDiagnosticSession = ""

    private fun showImageAnalysisDiagnosticsDialog() {
        imageDiagnosticSession = "diagnostic_" + UUID.randomUUID().toString()
        imageDiagnosticUris = emptyList()
        imageDiagnosticResults.clear()
        val panel = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(18), dp(20), dp(18))
            background = surfaceBg(CLR_MODAL, 20, CLR_BORDER, 1)
        }
        panel.addView(TextView(this).apply {
            text = "IMAGE & TEXT ANALYSIS DIAGNOSTICS"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
        })
        panel.addView(TextView(this).apply {
            text = "Select up to 5 JPEG, PNG or WebP images (25 MiB each). OCR and visual labels run on-device. No attendance, proof review, history or points are written. Optional object detection may need its model download. ML Kit may send SDK performance metrics; your images and outputs are processed on-device."
            textSize = 12f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            setPadding(0, dp(10), 0, dp(10))
        })
        val resultView = TextView(this).apply {
            text = "Choose printed text, a screenshot, receipt, garment, fabric, no-text object, multiple objects or a low-light image to inspect actual results."
            textSize = 12f
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            setPadding(dp(12), dp(12), dp(12), dp(12))
            background = surfaceBg("#060A10", 8, CLR_BORDER, 1)
        }
        imageDiagnosticResultView = resultView
        panel.addView(ScrollView(this).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(240))
            addView(resultView)
        })
        val btnRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply {
                topMargin = dp(14)
            }
        }
        val btnSelect = makePrimaryButton("SELECT IMAGES", CLR_CYAN, widthMatchParent = false) {
            if (imageDiagnosticBusy.get()) {
                Toast.makeText(this, "Analysis is still running.", Toast.LENGTH_SHORT).show()
            } else {
                try {
                    startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).apply {
                        addCategory(Intent.CATEGORY_OPENABLE)
                        type = "image/*"
                        putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true)
                        putExtra(Intent.EXTRA_MIME_TYPES, arrayOf("image/jpeg", "image/png", "image/webp"))
                        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                    }, REQ_IMAGE_ANALYSIS_DIAGNOSTIC)
                } catch (e: Exception) {
                    resultView.text = "Could not open the image picker: ${e.message}"
                }
            }
        }.apply {
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                rightMargin = dp(6)
            }
        }
        val btnRetry = makePrimaryButton("RETRY FAILED STAGES", CLR_BLUE, widthMatchParent = false) {
            if (imageDiagnosticUris.isEmpty()) resultView.text = "Select images first."
            else runImageDiagnostics(imageDiagnosticUris, retry = true)
        }.apply {
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                leftMargin = dp(6)
            }
        }
        btnRow.addView(btnSelect)
        btnRow.addView(btnRetry)
        panel.addView(btnRow)
        val dialog = AlertDialog.Builder(this).setView(panel).setPositiveButton("Close", null).create()
        dialog.setOnDismissListener { if (imageDiagnosticResultView === resultView) imageDiagnosticResultView = null }
        dialog.show()
        dialog.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
    }

    private fun createSampleDemoImage(label: String, colorHex: String): ByteArray {
        val width = 400
        val height = 300
        val bmp = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        val canvas = Canvas(bmp)
        canvas.drawColor(Color.parseColor(colorHex))
        val paint = Paint().apply {
            color = Color.WHITE
            textSize = 24f
            isAntiAlias = true
            textAlign = Paint.Align.CENTER
            typeface = Typeface.DEFAULT_BOLD
        }
        canvas.drawText(label, (width / 2).toFloat(), (height / 2).toFloat(), paint)
        val bos = java.io.ByteArrayOutputStream()
        bmp.compress(Bitmap.CompressFormat.JPEG, 90, bos)
        bmp.recycle()
        return bos.toByteArray()
    }

    private fun refreshTaufaDemoPreviews() {
        val container = taufaDemoPreviewsContainer ?: return
        val scroll = taufaDemoPreviewsScrollView
        container.removeAllViews()
        taufaDemoStatusView?.text = "Sample Photos (${taufaDemoAttachments.size}/10):"
        if (taufaDemoAttachments.isEmpty()) {
            scroll?.visibility = View.GONE
            return
        }
        scroll?.visibility = View.VISIBLE
        val itemsCopy = taufaDemoAttachments.toList()
        itemsCopy.forEachIndexed { index, item ->
            val frame = FrameLayout(this).apply {
                layoutParams = LinearLayout.LayoutParams(dp(68), dp(68)).apply { rightMargin = dp(8) }
            }
            val iv = ImageView(this).apply {
                layoutParams = FrameLayout.LayoutParams(dp(62), dp(62)).apply { gravity = Gravity.BOTTOM or Gravity.START }
                scaleType = ImageView.ScaleType.CENTER_CROP
                background = surfaceBg("#1E293B", 8, "#475569", 1)
                try {
                    val opts = BitmapFactory.Options().apply { inSampleSize = 8 }
                    val bmp = BitmapFactory.decodeByteArray(item.bytes, 0, item.bytes.size, opts)
                    if (bmp != null) setImageBitmap(bmp)
                } catch (_: Throwable) {}
            }
            frame.addView(iv)

            val btnRemove = TextView(this).apply {
                text = "✕"
                textSize = 9f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                gravity = Gravity.CENTER
                background = surfaceBg("#DC2626", 10)
                layoutParams = FrameLayout.LayoutParams(dp(20), dp(20)).apply {
                    gravity = Gravity.TOP or Gravity.END
                }
                setOnClickListener {
                    if (index < taufaDemoAttachments.size) {
                        val removed = taufaDemoAttachments.removeAt(index)
                        refreshTaufaDemoPreviews()
                        Toast.makeText(this@MainActivity, "Removed ${removed.name}", Toast.LENGTH_SHORT).show()
                    }
                }
            }
            frame.addView(btnRemove)
            container.addView(frame)
        }
    }

    private fun showTaufaDemoEvidenceSourceDialog() {
        AlertDialog.Builder(this)
            .setTitle("Attach sample photos (up to 10)")
            .setItems(arrayOf("Take a photo", "Choose from Photos (up to 10)", "Browse image files (up to 10)")) { _, choice ->
                pendingPhotoPurpose = "TAUFA_DEMO"
                when (choice) {
                    0 -> launchHardwareCamera()
                    1, 2 -> {
                        try {
                            val intent = Intent(if (choice == 1) Intent.ACTION_PICK else Intent.ACTION_OPEN_DOCUMENT).apply {
                                if (choice == 2) addCategory(Intent.CATEGORY_OPENABLE)
                                type = "image/*"
                                putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true)
                                putExtra(Intent.EXTRA_MIME_TYPES, arrayOf("image/jpeg", "image/png", "image/webp"))
                                addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                            }
                            startActivityForResult(intent, REQ_HOURLY_EVIDENCE_PICK)
                        } catch (e: Exception) {
                            Toast.makeText(this, "Could not open image picker: ${e.message}", Toast.LENGTH_SHORT).show()
                        }
                    }
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

