                if (taufaDemoAttachments.size + 2 > 10) {
                    Toast.makeText(this@MainActivity, "Max 10 photos limit.", Toast.LENGTH_SHORT).show()
                    return@setOnClickListener
                }
                val img1 = createSampleDemoImage("Operating Systems Lecture Notes", "#1E3A8A")
                val img2 = createSampleDemoImage("CPU Scheduling Paging Code", "#065F46")
                taufaDemoAttachments.add(AttachedProof(img1, "sample_os_notes.jpg"))
                taufaDemoAttachments.add(AttachedProof(img2, "sample_paging_code.jpg"))
