        taufaDemoPreviewsScrollView = previewsScroll
        panel.addView(previewsScroll)
        refreshTaufaDemoPreviews()

        // Duplicate Check Toggle
        val dupToggleRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(12), dp(8), dp(12), dp(8))
            background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(14)
            }
        }
        val dupCheckIcon = TextView(this).apply {
            text = if (checkDuplicate) "☑" else "☐"
            textSize = 16f
            setTextColor(Color.parseColor(if (checkDuplicate) CLR_GREEN else CLR_TEXT_DIM))
            setPadding(0, 0, dp(8), 0)
        }
        val dupCheckLabel = TextView(this).apply {
            text = "Check Duplicate Evidence (intra-submission & cross-check)"
            textSize = 11.5f
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        dupToggleRow.addView(dupCheckIcon)
        dupToggleRow.addView(dupCheckLabel)
        dupToggleRow.setOnClickListener {
            checkDuplicate = !checkDuplicate
            dupCheckIcon.text = if (checkDuplicate) "☑" else "☐"
            dupCheckIcon.setTextColor(Color.parseColor(if (checkDuplicate) CLR_GREEN else CLR_TEXT_DIM))
        }
        panel.addView(dupToggleRow)

        // Results Container
        val resultCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(14), dp(12), dp(14), dp(12))
            background = surfaceBg("#060A10", 12, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(14)
            }
        }
        val resultHint = TextView(this).apply {
            text = "Press button below to evaluate with unified Taufa AI engine."
            textSize = 11.5f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            gravity = Gravity.CENTER
        }
        resultCard.addView(resultHint)
        panel.addView(resultCard)

        // Run Button
        var btnRunRef: LinearLayout? = null
        btnRunRef = makePrimaryButton("⚡ RUN DEMO VALIDATION", CLR_CYAN, widthMatchParent = true) {
            if (taufaDemoRunning.get()) {
                Toast.makeText(this@MainActivity, "Validation is already in progress...", Toast.LENGTH_SHORT).show()
                return@makePrimaryButton
            }
            val desc = descInput.text.toString().trim()
            if (desc.isBlank()) {
                Toast.makeText(this@MainActivity, "Please enter an activity description.", Toast.LENGTH_SHORT).show()
                return@makePrimaryButton
            }
            if (taufaDemoAttachments.isEmpty()) {
                Toast.makeText(this@MainActivity, "Please attach at least one sample photo.", Toast.LENGTH_SHORT).show()
                return@makePrimaryButton
            }

            taufaDemoRunning.set(true)
            btnRunRef?.alpha = 0.5f
            resultCard.removeAllViews()
            val modeTitle = if (currentMode == "DEMO") "DEMO EVALUATION" else "PRODUCTION VALIDATION"
            resultCard.addView(TextView(this@MainActivity).apply {
                text = "🤖 Running $modeTitle with Taufa AI engine...\nConnecting to conversation ${TaufaAiValidator.DESIGNATED_CONVERSATION_ID}..."
                textSize = 12f
                setTextColor(Color.parseColor(CLR_CYAN))
                setPadding(dp(8), dp(12), dp(8), dp(12))
                gravity = Gravity.CENTER
            })

            val cat = selectedCategory
            val imagesList = taufaDemoAttachments.map { it.bytes.copyOf() }
            val dupCheck = checkDuplicate
            val evalMode = currentMode
            val tType = when (cat) {
                "WAKE_UP" -> "wake_up"
                "BATH" -> "bath"
                "GYM" -> "gym"
                else -> "study"
            }

            Thread {
                val res = TaufaAiValidator.evaluateSubmission(
                    context = this@MainActivity,
                    category = cat,
                    description = desc,
                    images = imagesList,
                    taskType = tType,
                    mode = evalMode,
                    checkDuplicate = dupCheck
                )
                runOnUiThread {
                    taufaDemoRunning.set(false)
                    btnRunRef?.alpha = 1.0f
                    renderTaufaUnifiedResult(resultCard, res)
                }
            }.start()
        }
        btnRunTextRef = btnRunRef.getChildAt(0) as? TextView
        updateModeViews()
        panel.addView(btnRunRef)

        val scroll = ScrollView(this).apply {
            layoutParams = ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            addView(panel)
        }
        val dialog = AlertDialog.Builder(this)
            .setView(scroll)
            .setPositiveButton("Close", null)
            .create()
        dialog.show()
        dialog.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
    }

    private fun renderTaufaUnifiedResult(container: LinearLayout, res: TaufaAiValidator.UnifiedEvaluationResult) {
        container.removeAllViews()

        // 1. Header Row: Mode & Status Badges
        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }
        val modeBadge = TextView(this).apply {
            text = if (res.isDemo) "🧪 DEMO" else "⚡ PRODUCTION"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor("#0A0D10"))
            setPadding(dp(6), dp(2), dp(6), dp(2))
            background = surfaceBg(if (res.isDemo) CLR_AMBER else CLR_GREEN, 6)
        }
        headerRow.addView(modeBadge)

        val spacer = View(this).apply { layoutParams = LinearLayout.LayoutParams(dp(8), 1) }
        headerRow.addView(spacer)

        val statusColor = when (res.status) {
            "VALID" -> CLR_GREEN
            "INSUFFICIENT_EVIDENCE" -> CLR_AMBER
            "INVALID" -> CLR_RED
            "NEEDS_REVIEW" -> "#8B5CF6"
            else -> CLR_TEXT_SECONDARY
        }
        val statusBadge = TextView(this).apply {
            text = res.status
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(statusColor))
            setPadding(dp(8), dp(3), dp(8), dp(3))
            background = surfaceBg(CLR_SURFACE_LOW, 6, statusColor, 1)
        }
        headerRow.addView(statusBadge)

        val flexView = View(this).apply { layoutParams = LinearLayout.LayoutParams(0, 1, 1f) }
        headerRow.addView(flexView)

        val scoreBadge = TextView(this).apply {
            text = "Score: ${res.score} / ${res.maxScore}"
            textSize = 13f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (res.score >= 6) CLR_GREEN else if (res.score == 0) CLR_RED else CLR_AMBER))
            setPadding(dp(8), dp(3), dp(8), dp(3))
            background = surfaceBg(CLR_SURFACE_LOW, 6, CLR_BORDER, 1)
        }
        headerRow.addView(scoreBadge)
        container.addView(headerRow)

        // 2. Summary & Recommended Action Box
        val summaryCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(10), dp(8), dp(10), dp(8))
            background = surfaceBg(CLR_SURFACE_LOW, 8, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        }
        summaryCard.addView(TextView(this).apply {
            text = res.reasoningSummary
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (res.status == "VALID") CLR_GREEN else CLR_TEXT_PRIMARY))
        })
        val actionText = "Recommended Action: ${res.recommendedAction.uppercase(Locale.US)}  •  Human Review: ${if (res.requiresHumanReview) "REQUIRED" else "NOT NEEDED"}"
        summaryCard.addView(TextView(this).apply {
            text = actionText
            textSize = 10.5f
            setTextColor(Color.parseColor(if (res.requiresHumanReview) CLR_AMBER else CLR_CYAN))
            setPadding(0, dp(4), 0, 0)
        })
        container.addView(summaryCard)

        // 3. Key-Value Breakdown
        fun addRow(label: String, value: String, valColor: String = CLR_TEXT_PRIMARY) {
            val r = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                setPadding(0, dp(3), 0, dp(3))
            }
            r.addView(TextView(this).apply {
                text = label
                textSize = 10.5f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(dp(140), ViewGroup.LayoutParams.WRAP_CONTENT)
            })
            r.addView(TextView(this).apply {
                text = value
                textSize = 10.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(valColor))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            })
            container.addView(r)
        }

        addRow("Evaluation ID:", res.evaluationId.take(18) + "...", CLR_CYAN)
        addRow("Task Type / Mode:", "${res.taskType.uppercase(Locale.US)} (${res.mode})")
        addRow("Real Points Impact:", if (res.isDemo) "0 pts (Demo Isolated)" else "+${res.realPointsAwarded} pts committed", if (res.realPointsAwarded > 0) CLR_GREEN else CLR_CYAN)

        // Duplicate Check row
        val isDup = res.duplicateCheck?.optBoolean("duplicate_detected", false) == true
        addRow("Duplicate Check:", if (isDup) "⚠️ DUPLICATE DETECTED" else "✓ Unique Evidence", if (isDup) CLR_RED else CLR_GREEN)

        // 4. Criteria Results Breakdown
        if (res.criteriaResults.isNotEmpty()) {
            val critHeader = TextView(this).apply {
                text = "CRITERIA RESULTS:"
                textSize = 10f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_CYAN))
                setPadding(0, dp(8), 0, dp(2))
            }
            container.addView(critHeader)
            for (crit in res.criteriaResults) {
                val name = crit.optString("criterion", "criterion")
                val passed = crit.optBoolean("passed", false)
                val detail = crit.optString("details", "")
                addRow("  • $name:", "${if (passed) "✓" else "✗"} $detail", if (passed) CLR_GREEN else CLR_AMBER)
            }
        }

        // 5. Observations list
        if (res.observations.isNotEmpty()) {
            val obsHeader = TextView(this).apply {
                text = "VISUAL OBSERVATIONS:"
                textSize = 10f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_CYAN))
                setPadding(0, dp(8), 0, dp(2))
            }
            container.addView(obsHeader)
            for (obs in res.observations) {
                container.addView(TextView(this).apply {
                    text = "  • $obs"
                    textSize = 10f
                    setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                    setPadding(0, dp(1), 0, dp(1))
                })
            }
        }
    }

    private fun colorNameForHex(hex: String): String {
        return try {
            val color = Color.parseColor(hex)
            val r = Color.red(color)
            val g = Color.green(color)
            val b = Color.blue(color)
            val hsv = FloatArray(3)
            Color.RGBToHSV(r, g, b, hsv)
            val h = hsv[0]
            val s = hsv[1]
            val v = hsv[2]
            when {
                v < 0.16f -> "Black"
                v > 0.88f && s < 0.12f -> "White"
                s < 0.14f -> if (v > 0.55f) "Light Gray" else "Dark Gray"
                h in 0f..15f || h in 345f..360f -> if (v < 0.45f) "Maroon" else "Red"
                h in 15f..45f -> if (v < 0.45f) "Brown" else "Orange"
                h in 45f..70f -> "Yellow"
                h in 70f..165f -> if (v < 0.4f) "Dark Green" else "Green"
                h in 165f..200f -> "Cyan"
                h in 200f..260f -> if (v < 0.35f) "Navy Blue" else "Blue"
                h in 260f..310f -> "Purple"
                h in 310f..345f -> "Magenta / Pink"
                else -> "Neutral"
            }
        } catch (_: Exception) {
            "Color $hex"
        }
    }

    private fun formatStrictBotImageUnderstandingReport(name: String, sourceSize: Long, result: JSONObject, index: Int, total: Int): String {
        val ocr = result.optJSONObject("ocr")
        val vision = result.optJSONObject("vision")
        val objectDet = result.optJSONObject("object_detection")
        val measurements = result.optJSONObject("measurements")
        val original = result.optJSONObject("original")

        val ocrStatus = ocr?.optString("status") ?: "UNKNOWN"
        val ocrText = ocr?.optString("text")?.trim().orEmpty()
        val blocks = ocr?.optJSONArray("blocks")
        val blockCount = blocks?.length() ?: 0

        val labelsArray = vision?.optJSONArray("labels")
        val detectedLabels = mutableListOf<String>()
        val topLabelNames = mutableListOf<String>()
        if (labelsArray != null) {
            for (i in 0 until minOf(labelsArray.length(), 6)) {
                val item = labelsArray.optJSONObject(i) ?: continue
                val lbl = item.optString("label")
                val conf = (item.optDouble("confidence", 0.0) * 100).toInt()
                detectedLabels.add("$lbl ($conf%)")
                topLabelNames.add(lbl)
            }
        }

        val boxesArray = objectDet?.optJSONArray("boxes")
        val boxCount = boxesArray?.length() ?: 0

        val dominantColorsArray = measurements?.optJSONArray("dominant_colors")
        val colorList = mutableListOf<String>()
        val topColorNames = mutableListOf<String>()
        if (dominantColorsArray != null) {
            for (i in 0 until minOf(dominantColorsArray.length(), 4)) {
                val cObj = dominantColorsArray.optJSONObject(i) ?: continue
                val hex = cObj.optString("hex")
                val pct = (cObj.optDouble("fraction", 0.0) * 100).toInt()
                val cName = colorNameForHex(hex)
                colorList.add("$cName ($hex, $pct%)")
                topColorNames.add(cName)
            }
        }

        val quality = measurements?.optJSONObject("quality")
        val meanLuma = quality?.optDouble("mean_luma", 128.0) ?: 128.0
        val contrast = quality?.optDouble("contrast_stddev", 50.0) ?: 50.0
        val sharpness = quality?.optDouble("laplacian_energy", 50.0) ?: 50.0
        val lightDesc = when {
            meanLuma < 45 -> "Low light / dark"
            meanLuma > 230 -> "High exposure / very bright"
            else -> "Balanced lighting"
        }
        val sharpDesc = when {
            sharpness > 80 -> "Crisp edge sharpness"
            sharpness < 20 -> "Soft focus / smooth texture"
            else -> "Moderate detail"
        }
        val warnings = quality?.optJSONArray("warnings")

        val botUnderstanding = StringBuilder()
        if (result.optString("status") == "failed") {
            botUnderstanding.append("I encountered an issue analyzing this image: ${result.optString("error", "Unknown error")}.")
        } else {
            botUnderstanding.append("I examined this image ($name) and analyzed both visual features and text:\n\n")
            if (ocrText.isNotBlank() && topLabelNames.isNotEmpty()) {
                botUnderstanding.append("• Visual Content: I recognize ${topLabelNames.take(3).joinToString(", ")}.\n")
                botUnderstanding.append("• OCR Text: I extracted readable text: \"${ocrText.take(120).replace("\n", " ").trim()}${if (ocrText.length > 120) "…" else ""}\".\n")
                botUnderstanding.append("• Color & Lighting: Predominantly ${topColorNames.take(2).joinToString(" & ").ifBlank { "neutral tones" }}, with $lightDesc and $sharpDesc.")
            } else if (ocrText.isNotBlank()) {
                botUnderstanding.append("• Visual Content: This is primarily a text document or digital display.\n")
                botUnderstanding.append("• OCR Text: Extracted $blockCount text block(s): \"${ocrText.take(160).replace("\n", " ").trim()}${if (ocrText.length > 160) "…" else ""}\".\n")
                botUnderstanding.append("• Color & Lighting: $lightDesc with $sharpDesc.")
            } else if (topLabelNames.isNotEmpty()) {
                botUnderstanding.append("• Visual Content: Visible objects/scene include ${topLabelNames.take(4).joinToString(", ")}.\n")
                botUnderstanding.append("• OCR Text: No readable text detected (standard for objects, clothing, gym gear, or outdoor photos).\n")
                botUnderstanding.append("• Color & Lighting: Predominantly ${topColorNames.take(2).joinToString(" & ").ifBlank { "neutral tones" }}, with $lightDesc and $sharpDesc.")
            } else {
                botUnderstanding.append("• Visual Content: No high-confidence objects or text detected.\n")
                botUnderstanding.append("• Color & Lighting: Dominated by ${topColorNames.take(2).joinToString(" & ").ifBlank { "ambient tones" }} with $lightDesc.")
            }
        }

        val sb = StringBuilder()
        sb.append("╔═══════════════════════════════════════════════════════╗\n")
        sb.append("  ATTACHMENT $index OF $total: $name\n")
        sb.append("╚═══════════════════════════════════════════════════════╝\n\n")

        sb.append("🤖 STRICTBOT'S UNDERSTANDING:\n")
        sb.append(botUnderstanding.toString()).append("\n\n")

        sb.append("─────────────────────────────────────────────────────────\n")
        sb.append("📋 MODEL ACCURACY & OCR CROSSCHECK\n")
        sb.append("─────────────────────────────────────────────────────────\n")

        sb.append("📝 TEXT RECOGNITION (OCR):\n")
        sb.append("   • Status: $ocrStatus\n")
        sb.append("   • Detected Blocks: $blockCount block(s)\n")
        if (ocrText.isNotBlank()) {
            val previewLines = ocrText.lines().take(8)
            sb.append("   • Extracted Text Preview:\n")
            previewLines.forEach { line -> sb.append("     \"${line.trim()}\"\n") }
            if (ocrText.lines().size > 8) {
                sb.append("     … (${ocrText.lines().size - 8} additional lines omitted from preview)\n")
            }
        } else {
            sb.append("   • Extracted Text: None (Zero readable text detected)\n")
        }

        sb.append("\n👁️ VISUAL OBJECTS & SCENE LABELS:\n")
        if (detectedLabels.isNotEmpty()) {
            sb.append("   • Detected Labels: ${detectedLabels.joinToString(", ")}\n")
        } else {
            sb.append("   • Detected Labels: No general scene labels met confidence threshold\n")
        }
        sb.append("   • Localized Boxes: ${if (boxCount > 0) "$boxCount localized object(s)" else "None detected"}\n")

        sb.append("\n🎨 COLOR & VISUAL SURFACE:\n")
        sb.append("   • Dominant Colors: ${if (colorList.isNotEmpty()) colorList.joinToString(", ") else "None measured"}\n")
        sb.append("   • Lighting / Luma: $lightDesc (Mean: ${String.format(Locale.ROOT, "%.1f", meanLuma)})\n")
        sb.append("   • Contrast & Sharpness: $sharpDesc (Contrast: ${String.format(Locale.ROOT, "%.1f", contrast)}, Sharpness: ${String.format(Locale.ROOT, "%.1f", sharpness)})\n")
        sb.append("   • Fabric / Texture: Surface appearance observed. Physical material cannot be assumed without tactile verification.\n")
        if (warnings != null && warnings.length() > 0) {
            val warnList = (0 until warnings.length()).map { warnings.getString(it) }
            sb.append("   • Warnings: ${warnList.joinToString("; ")}\n")
        }

        val sha256 = original?.optString("sha256") ?: "n/a"
        val width = original?.optInt("width", 0) ?: 0
        val height = original?.optInt("height", 0) ?: 0
        val bytes = if (sourceSize >= 0) sourceSize else (original?.optLong("bytes", -1L) ?: -1L)

        sb.append("\n🔒 EVIDENCE INTEGRITY & DUPLICATE PREVENTION:\n")
        sb.append("   • SHA-256 Digest: $sha256\n")
        sb.append("   • Source Dimensions: ${width}x${height} px | Size: ${if (bytes >= 0) "$bytes bytes" else "measured on stream"}\n")
        sb.append("   • Storage Verification: Fingerprint indexed for app storage duplicate prevention.\n\n")

        sb.append("─────────────────────────────────────────────────────────\n")
        sb.append("⚙️ RAW ANALYSIS JSON (Stored for duplicate check & audit)\n")
        sb.append("─────────────────────────────────────────────────────────\n")
        sb.append(result.toString(2))

        return sb.toString()
    }

    private fun formatStrictBotSpokenSummary(name: String, result: JSONObject): String {
        val ocr = result.optJSONObject("ocr")
        val vision = result.optJSONObject("vision")
        val measurements = result.optJSONObject("measurements")

        val ocrText = ocr?.optString("text")?.trim().orEmpty()
        val labelsArray = vision?.optJSONArray("labels")
        val topLabels = mutableListOf<String>()
        if (labelsArray != null) {
            for (i in 0 until minOf(labelsArray.length(), 2)) {
                val item = labelsArray.optJSONObject(i) ?: continue
                topLabels.add(item.optString("label"))
            }
        }
        val dominantColors = measurements?.optJSONArray("dominant_colors")
        val topColorHex = dominantColors?.optJSONObject(0)?.optString("hex").orEmpty()
        val topColor = if (topColorHex.isNotBlank()) colorNameForHex(topColorHex) else ""

        return when {
            ocrText.isNotBlank() && topLabels.isNotEmpty() ->
                "I analyzed $name. Found text: \"${ocrText.take(40).replace("\n", " ").trim()}\" and detected ${topLabels.joinToString(" and ")}."
            ocrText.isNotBlank() ->
                "I analyzed $name. Extracted text: \"${ocrText.take(50).replace("\n", " ").trim()}\"."
            topLabels.isNotEmpty() ->
                "I analyzed $name. Detected ${topLabels.joinToString(" and ")} with no text${if (topColor.isNotBlank()) ", mostly $topColor" else ""}."
            else ->
                "I finished analyzing $name. ${if (topColor.isNotBlank()) "Predominantly $topColor image." else "Visual analysis complete."}"
        }
    }

    private fun runImageDiagnostics(uris: List<Uri>, retry: Boolean = false) {
        if (uris.isEmpty() || uris.size > 5) {
            imageDiagnosticResultView?.text = "Select 1–5 images. Every attachment must receive a result."
            return
        }
        if (!imageDiagnosticBusy.compareAndSet(false, true)) return
        val target = imageDiagnosticResultView
        val session = imageDiagnosticSession
        imageDiagnosticUris = uris
        if (!retry) imageDiagnosticResults.clear()
        target?.text = "Analyzing ${uris.size} images sequentially…"
        Thread {
            val report = StringBuilder()
            try {
                val sizes = uris.map { uri ->
                    runCatching {
                        contentResolver.query(uri, arrayOf(OpenableColumns.SIZE), null, null, null)?.use { c ->
                            if (c.moveToFirst() && !c.isNull(0)) c.getLong(0) else -1L
                        } ?: -1L
                    }.getOrDefault(-1L)
                }
                if (sizes.any { it > 25L * 1024 * 1024 } || sizes.filter { it >= 0 }.sum() > 125L * 1024 * 1024) {
                    throw IllegalArgumentException("Selected files exceed 25 MiB each or 125 MiB total. Unknown sizes are checked while streaming.")
                }
                for ((index, uri) in uris.withIndex()) {
                    val name = runCatching {
                        contentResolver.query(uri, arrayOf(OpenableColumns.DISPLAY_NAME), null, null, null)?.use { c ->
                            if (c.moveToFirst()) c.getString(0) else null
                        }
                    }.getOrNull() ?: "Image ${index + 1}"
                    val attachmentId = "$session-image-$index"
                    val result = try {
                        EvidenceAnalysisEngine.analyzeUri(
                            applicationContext, uri, attachmentId, session, batchId = session,
                            persistDerivatives = false, useObjectDetection = true,
                            priorResult = if (retry) imageDiagnosticResults[attachmentId] else null,
                            retryStages = if (retry) setOf("ocr", "vision", "objects") else emptySet()
                        )
                    } catch (e: Exception) {
                        JSONObject().put("status", "failed").put("image_id", attachmentId)
                            .put("error", "${e.javaClass.simpleName}: ${e.message}")
                    }
                    imageDiagnosticResults[attachmentId] = result

                    val humanReport = formatStrictBotImageUnderstandingReport(name, sizes[index], result, index + 1, uris.size)
                    report.append(humanReport).append("\n\n")

                    val botSpeech = formatStrictBotSpokenSummary(name, result)
                    val briefSummaryForChat = "${name}: ${botSpeech}"
                    db.setConfigValue("last_evidence_summary", briefSummaryForChat)
                    db.setConfigValue("last_evidence_json", result.toString())

                    val currentReport = report.toString()
                    runOnUiThread {
                        if (imageDiagnosticResultView === target) target?.text = currentReport + "Processing ${index + 1}/${uris.size}…"
                        triggerBotMessage(botSpeech, "TALK")
                        speakStrictBot(botSpeech)
                    }
                }
                report.append("Processed ${uris.size}/${uris.size} selected attachments. Stage failures are shown per image. Diagnostic only; no review or score awarded.")
            } catch (e: Exception) {
                report.append("Batch failed: ${e.message}. Selected images were not marked complete.")
            } finally {
                imageDiagnosticBusy.set(false)
                val finalReport = report.toString()
                runOnUiThread {
                    if (imageDiagnosticResultView === target) target?.text = finalReport
                    val lastSpeech = imageDiagnosticResults.values.firstOrNull()?.let {
                        formatStrictBotSpokenSummary("your tested image", it)
                    } ?: "Evidence image analysis complete."
                    triggerBotMessage(lastSpeech, "SUCCESS")
                }
            }
        }.start()
    }

    private fun showWakeUpVerificationDialog() {
        if (isFinishing || isDestroyed || !screenResumed) return
        WakeUpVerificationController.showWakeUpVerificationDialog(
            activity = this,
            db = db,
            isDevMode = isDevMode,
            onDismissed = {
                checkQueuedBathPopup()
            }
        ) {
            updateCountdownViews()
            refreshUi()
            checkQueuedBathPopup()
        }
