    private fun verifyBluetoothNow() {
        val route = HardwareDeviceVerifier.verifyActiveBluetoothEarbudsRoute(
            this,
            db.getEarbudsConfig(),
            db.getEarbudsAddress()
        )
        if (route.isActiveBluetoothEarbuds) {
            val devLabel = route.deviceName.ifBlank { db.getEarbudsConfig() }
            db.completeBluetoothStep(db.nowDate(), isDevMode, devLabel)
            haptic(1)
            triggerBotMessage("Bluetooth earbuds verified ✓ ($devLabel)", "SUCCESS")
            updateCountdownViews()
            refreshUi()
            showWakeUpVerificationDialog()
        } else {
            Toast.makeText(this, route.failureReason, Toast.LENGTH_LONG).show()
            showWakeUpVerificationDialog()
        }
    }

    private fun launchHardwareCamera() {
        val hasCameraHw = packageManager.hasSystemFeature(android.content.pm.PackageManager.FEATURE_CAMERA_ANY)
        if (!hasCameraHw) {
            try {
                startActivityForResult(
                    Intent(Intent.ACTION_GET_CONTENT).apply {
                        addCategory(Intent.CATEGORY_OPENABLE)
                        type = "image/*"
                    },
                    REQ_HOURLY_EVIDENCE_PICK
                )
            } catch (e: Exception) {
                Toast.makeText(this, "No camera hardware or image picker available.", Toast.LENGTH_LONG).show()
            }
            return
        }
        DisciplinePermissionManager.ensureCapability(
            this,
            PermissionCapability.CAMERA,
            when (pendingPhotoPurpose) {
                "WAKEUP" -> "Morning Wake-Up Camera Proof"
                "PC_SHUTDOWN" -> "Workstation Shutdown Photo Evidence"
                "TRAVEL" -> "Travel & Transit Photo Evidence"
                "GYM" -> "Gym & Workout Photo Evidence"
                else -> "Hourly Checkpoint Photo Evidence"
            },
            onGranted = {
                try {
                    val cameraDir = File(cacheDir, "camera").apply { mkdirs() }
                    val photoFile = File(cameraDir, "capture_${System.currentTimeMillis()}.jpg")
                    pendingCameraCaptureFile = photoFile
                    val photoUri = StrictFileProvider.getUriForFile(this, photoFile)

                    val intent = Intent(MediaStore.ACTION_IMAGE_CAPTURE).apply {
                        putExtra(MediaStore.EXTRA_OUTPUT, photoUri)
                        addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION or Intent.FLAG_GRANT_READ_URI_PERMISSION)
                    }
                    startActivityForResult(intent, REQ_CAMERA_CAPTURE)
                } catch (e: Exception) {
                    try {
                        startActivityForResult(
                            Intent(Intent.ACTION_GET_CONTENT).apply {
                                addCategory(Intent.CATEGORY_OPENABLE)
                                type = "image/*"
                            },
                            REQ_HOURLY_EVIDENCE_PICK
                        )
                    } catch (_: Exception) {
                        onPhotoBytesCaptured(ByteArray(0))
                    }
                }
            }
        )
    }

    private fun showHourlyEvidenceSourceDialog() {
        AlertDialog.Builder(this)
            .setTitle("Attach hourly proof (up to 10 photos)")
            .setItems(arrayOf("Take a photo", "Choose from Photos (up to 10)", "Browse image files (up to 10)")) { _, choice ->
                pendingPhotoPurpose = "HOURLY"
                when (choice) {
                    0 -> launchHardwareCamera()
                    1, 2 -> {
                        val action = if (choice == 1) Intent.ACTION_GET_CONTENT else Intent.ACTION_OPEN_DOCUMENT
                        val requestCode = if (choice == 1) REQ_HOURLY_EVIDENCE_PICK else REQ_HOURLY_EVIDENCE_DOCUMENT
                        try {
                            startActivityForResult(
                                Intent(action).apply {
                                    addCategory(Intent.CATEGORY_OPENABLE)
                                    type = "image/*"
                                    putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true)
                                    putExtra(Intent.EXTRA_MIME_TYPES, arrayOf("image/jpeg", "image/png", "image/webp"))
                                    addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                                },
                                requestCode
                            )
                        } catch (e: Exception) {
                            Toast.makeText(this, "Could not open the image picker: ${e.message}", Toast.LENGTH_LONG).show()
                        }
                    }
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun updateHourlyEvidenceLabels() {
        val count = hourlyAttachments.size
        val attached = count > 0
        val totalBytes = hourlyAttachments.sumOf { it.bytes.size.toLong() }
        val sizeStr = if (totalBytes < 1024 * 1024) {
            String.format(Locale.US, "%d KB", (totalBytes + 1023) / 1024)
        } else {
            String.format(Locale.US, "%.1f MB", totalBytes / (1024.0 * 1024.0))
        }
        val label = when {
            count == 0 -> "📎  Attach required evidence"
            count == 1 -> "📎  ${hourlyAttachments[0].name} attached ($sizeStr) ✓"
            else -> "📎  $count/10 images attached ($sizeStr total) ✓"
        }
        (hourlyAttachmentButton?.getChildAt(0) as? TextView)?.text = label
        hourlyAttachmentStatusView?.apply {
            text = label
            setTextColor(if (attached) Color.parseColor(CLR_GREEN) else Color.parseColor(CLR_TEXT_SECONDARY))
        }
        activeHourlyReviewLabel?.apply {
            if (attached) {
                text = "Status: OPEN • $count image(s) attached — ready for validation."
                setTextColor(Color.parseColor(CLR_CYAN))
            } else {
                text = "Status: OPEN • Evidence Check: Attach an image to inspect"
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            }
        }
    }

    private fun refreshHourlyPreviews() {
        val container = hourlyPreviewsContainer ?: return
        val scroll = hourlyPreviewsScrollView
        container.removeAllViews()
        if (hourlyAttachments.isEmpty()) {
            scroll?.visibility = View.GONE
            return
        }
        scroll?.visibility = View.VISIBLE
        val itemsCopy = hourlyAttachments.toList()
        itemsCopy.forEachIndexed { index, item ->
            val frame = FrameLayout(this).apply {
                layoutParams = LinearLayout.LayoutParams(dp(68), dp(68)).apply { rightMargin = dp(8) }
            }
            val iv = ImageView(this).apply {
                layoutParams = FrameLayout.LayoutParams(dp(62), dp(62)).apply { gravity = Gravity.BOTTOM or Gravity.START }
                scaleType = ImageView.ScaleType.CENTER_CROP
                background = surfaceBg("#1E293B", 8, "#475569", 1)
                try {
                    val opts = BitmapFactory.Options().apply { inSampleSize = 8 }
                    val bmp = BitmapFactory.decodeByteArray(item.bytes, 0, item.bytes.size, opts)
                    if (bmp != null) {
                        val rotation = try {
                            val exif = androidx.exifinterface.media.ExifInterface(java.io.ByteArrayInputStream(item.bytes))
                            when (exif.getAttributeInt(androidx.exifinterface.media.ExifInterface.TAG_ORIENTATION, androidx.exifinterface.media.ExifInterface.ORIENTATION_NORMAL)) {
                                androidx.exifinterface.media.ExifInterface.ORIENTATION_ROTATE_90 -> 90f
                                androidx.exifinterface.media.ExifInterface.ORIENTATION_ROTATE_180 -> 180f
                                androidx.exifinterface.media.ExifInterface.ORIENTATION_ROTATE_270 -> 270f
                                else -> 0f
                            }
                        } catch (_: Throwable) { 0f }
                        if (rotation != 0f) {
                            val matrix = android.graphics.Matrix().apply { postRotate(rotation) }
                            val rotatedBmp = android.graphics.Bitmap.createBitmap(bmp, 0, 0, bmp.width, bmp.height, matrix, true)
                            setImageBitmap(rotatedBmp)
                        } else {
                            setImageBitmap(bmp)
                        }
                    }
                } catch (_: Throwable) {}
            }
            frame.addView(iv)

            val btnRemove = TextView(this).apply {
                text = "✕"
                textSize = 9f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                gravity = Gravity.CENTER
                background = surfaceBg("#DC2626", 10)
                layoutParams = FrameLayout.LayoutParams(dp(20), dp(20)).apply {
                    gravity = Gravity.TOP or Gravity.END
                }
                setOnClickListener {
                    if (index < hourlyAttachments.size) {
                        val removed = hourlyAttachments.removeAt(index)
                        lastCapturedHourlyPhotoBytes = hourlyAttachments.firstOrNull()?.bytes
                        lastCapturedHourlyPhotoName = hourlyAttachments.firstOrNull()?.name ?: "evidence.jpg"
                        hourlyHasPhoto = hourlyAttachments.isNotEmpty()
                        updateHourlyEvidenceLabels()
                        refreshHourlyPreviews()
                        Toast.makeText(this@MainActivity, "Removed ${removed.name}", Toast.LENGTH_SHORT).show()
                    }
                }
            }
            frame.addView(btnRemove)
            container.addView(frame)
        }
    }

    private fun readHourlyEvidence(uri: Uri): Pair<ByteArray, String>? {
        return try {
            val mime = contentResolver.getType(uri)?.lowercase(Locale.US).orEmpty()
            val defaultName = when (mime) {
                "image/png" -> "evidence.png"
                "image/webp" -> "evidence.webp"
                else -> "evidence.jpg"
            }
            val name = contentResolver.query(uri, arrayOf(OpenableColumns.DISPLAY_NAME), null, null, null)?.use { cursor ->
                if (cursor.moveToFirst()) cursor.getString(0) else null
            }?.takeIf { it.isNotBlank() } ?: defaultName
            val bytes = contentResolver.openInputStream(uri)?.use { input ->
                val output = ByteArrayOutputStream()
                val buffer = ByteArray(8192)
                var total = 0
                while (true) {
                    val count = input.read(buffer)
                    if (count < 0) break
                    total += count
                    if (total > 25 * 1024 * 1024) return null
                    output.write(buffer, 0, count)
                }
                output.toByteArray()
            } ?: return null
            // Convert HEIC/HEIF to JPEG so the backend can process it.
            // For all other formats, preserve the original bytes without alteration.
            val processedBytes: ByteArray
            val processedName: String
            if (mime in setOf("image/heic", "image/heif", "image/heic-sequence", "image/heif-sequence")) {
                val bmp = BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
                if (bmp == null) return null
                val baos = java.io.ByteArrayOutputStream()
                bmp.compress(android.graphics.Bitmap.CompressFormat.JPEG, 92, baos)
                bmp.recycle()
                processedBytes = baos.toByteArray()
                processedName = name.substringBeforeLast('.') + ".jpg"
            } else {
                processedBytes = bytes
                processedName = name
            }
            if (!isValidProofImage(processedBytes)) return null
            val safeName = processedName.substringAfterLast('/').filter { it.isLetterOrDigit() || it in "._- " }
                .take(128).ifBlank { "evidence.jpg" }
            processedBytes to safeName
        } catch (e: Exception) {
            Log.w("StrictRoutines", "Unable to read selected hourly evidence: ${e.message}")
            null
        }
    }

