    @Deprecated("Deprecated in Java")
    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)


        if (requestCode == REQ_PICK_WAKEUP_MUSIC) {
            val uri = if (resultCode == RESULT_OK) data?.data else null
            onWakeUpMusicPicked?.invoke(uri)
            onWakeUpMusicPicked = null
            return
        }
        if (requestCode == REQ_EXAM_EVIDENCE_PICK) {
            if (resultCode == RESULT_OK) {
                val clip = data?.clipData
                val uris = if (clip != null) (0 until clip.itemCount).map { clip.getItemAt(it).uri }
                    else listOfNotNull(data?.data)
                onExamImagesPicked?.invoke(uris)
            } else {
                onExamImagesPicked?.invoke(emptyList())
            }
            onExamImagesPicked = null
            return
        }
        if (requestCode == REQ_SLEEP_SCREENSHOT_PICK) {
            if (resultCode == RESULT_OK) {
                val clip = data?.clipData
                val uris = if (clip != null) (0 until clip.itemCount).map { clip.getItemAt(it).uri }
                    else listOfNotNull(data?.data)
                onSleepScreenshotsPicked?.invoke(uris)
            } else {
                onSleepScreenshotsPicked?.invoke(emptyList())
            }
            onSleepScreenshotsPicked = null
            return
        }
        if (requestCode == REQ_GYM_SCREENSHOT_PICK) {
            if (resultCode == RESULT_OK) {
                val clip = data?.clipData
                val uris = if (clip != null) (0 until clip.itemCount).map { clip.getItemAt(it).uri }
                    else listOfNotNull(data?.data)
                onGymScreenshotsPicked?.invoke(uris)
            } else {
                onGymScreenshotsPicked?.invoke(emptyList())
            }
            onGymScreenshotsPicked = null
            return
        }
        if (requestCode == REQ_MOVIE_TICKET_PICK) {
            val uri = if (resultCode == RESULT_OK) data?.data else null
            onMovieTicketPicked?.invoke(uri)
            onMovieTicketPicked = null
            return
        }
        if (requestCode == REQ_IMAGE_ANALYSIS_DIAGNOSTIC) {
            if (resultCode == RESULT_OK) {
                val clip = data?.clipData
                val uris = if (clip != null) (0 until clip.itemCount).map { clip.getItemAt(it).uri }
                    else listOfNotNull(data?.data)
                runImageDiagnostics(uris)
            }
            return
        }
        if (requestCode == REQ_CAMERA_CAPTURE && resultCode == RESULT_OK) {
            val capturedFile = pendingCameraCaptureFile
            val fileBytes: ByteArray? = try {
                if (capturedFile != null && capturedFile.exists() && capturedFile.length() > 0) {
                    capturedFile.readBytes()
                } else null
            } catch (_: Exception) { null }

            val finalBytes: ByteArray = if (fileBytes != null && fileBytes.size > 0) {
                fileBytes
            } else {
                @Suppress("DEPRECATION")
                val rawBmp = data?.extras?.get("data") as? Bitmap
                if (rawBmp != null) {
                    val normalizedBmp = if (rawBmp.width < 160 || rawBmp.height < 160) {
                        val scale = maxOf(320f / rawBmp.width.coerceAtLeast(1), 320f / rawBmp.height.coerceAtLeast(1))
                        Bitmap.createScaledBitmap(
                            rawBmp,
                            (rawBmp.width * scale).toInt().coerceAtLeast(160),
                            (rawBmp.height * scale).toInt().coerceAtLeast(160),
                            true
                        )
                    } else {
                        rawBmp
                    }
                    val bos = ByteArrayOutputStream()
                    normalizedBmp.compress(Bitmap.CompressFormat.JPEG, 90, bos)
                    if (normalizedBmp !== rawBmp) normalizedBmp.recycle()
                    bos.toByteArray()
                } else {
                    ByteArray(0)
                }
            }
            try { capturedFile?.delete() } catch (_: Exception) {}
            pendingCameraCaptureFile = null
            onPhotoBytesCaptured(finalBytes, "camera_capture.jpg")
        } else if ((requestCode == REQ_HOURLY_EVIDENCE_PICK || requestCode == REQ_HOURLY_EVIDENCE_DOCUMENT) && resultCode == RESULT_OK) {
            val clipData = data?.clipData
            if (clipData != null && clipData.itemCount > 0) {
                val maxItems = minOf(clipData.itemCount, TaufaAiValidator.MAX_HOURLY_PHOTOS)
                val readList = mutableListOf<Pair<ByteArray, String>>()
                for (i in 0 until maxItems) {
                    val u = clipData.getItemAt(i).uri
                    val ev = u?.let(::readHourlyEvidence)
                    if (ev != null) readList.add(ev)
                }
                if (readList.isNotEmpty()) {
                    onMultiplePhotosCaptured(readList)
                } else {
                    Toast.makeText(this, "The selected images could not be read or exceed the file limit.", Toast.LENGTH_LONG).show()
                }
            } else {
                val uri = data?.data
                val evidence = uri?.let(::readHourlyEvidence)
                if (evidence == null) {
                    Toast.makeText(this, "The selected image could not be read or exceeds the file limit.", Toast.LENGTH_LONG).show()
                } else {
                    onPhotoBytesCaptured(evidence.first, evidence.second)
                }
            }
        } else if (requestCode == 777) {
            if (data?.getBooleanExtra("MANUAL_ENTRY_REQUESTED", false) == true) {
                activeTab = "DEVICES"
                refreshUi()
                showDeviceCenterDialog()
                return
            }
            if (resultCode == RESULT_OK) {
                val contents = data?.getStringExtra("SCAN_RESULT")
                if (!contents.isNullOrEmpty()) {
                    val clean = contents.trim()
                    triggerBotMessage("Connecting to PC via QR code...", "SYNCING")
                    Toast.makeText(this, "QR Scanned! Connecting to StrictRoutines PC...", Toast.LENGTH_SHORT).show()
                    Thread {
                        var endpoint = ""
                        var skey = clean
                        val candidateEndpoints = mutableListOf<String>()
                        try {
                            val j = JSONObject(clean)
                            skey = j.optString("session_key", j.optString("key", j.optString("manual_pin", clean))).trim()
                            endpoint = j.optString("server_endpoint", "").trim()
                            val candArr = j.optJSONArray("candidate_endpoints")
                            if (candArr != null) {
                                for (idx in 0 until candArr.length()) {
                                    val c = candArr.optString(idx, "").trim()
                                    if (c.isNotEmpty() && !candidateEndpoints.contains(c)) {
                                        candidateEndpoints.add(c)
                                    }
                                }
                            }
                        } catch (_: Exception) {
                            val regex = Regex("(?i)SR-[A-Z0-9]{4}-[A-Z0-9]{4}")
                            val match = regex.find(clean)
                            if (match != null) {
                                skey = match.value.uppercase()
                            }
                        }
                        val (ok, msg) = db.performPairingHandshake(
                            endpoint,
                            skey,
                            this@MainActivity,
                            candidateEndpoints
                        )
                        runOnUiThread {
                            if (ok) {
                                haptic(1)
                                triggerBotMessage("Device permanently paired via QR!", "SUCCESS")
                                Toast.makeText(this@MainActivity, "✓ Device Connected!\n$msg", Toast.LENGTH_LONG).show()
                                activeTab = "DEVICES"
                                refreshUi()
                            } else {
                                haptic(3)
                                triggerBotMessage("QR pairing failed.", "WARNING")
                                AlertDialog.Builder(this@MainActivity)
                                    .setTitle("⚠️ Pairing Failed")
                                    .setMessage("Could not complete pairing:\n\n$msg\n\nPlease generate a fresh QR code on your Windows PC or enter the Pairing Code manually.")
                                    .setPositiveButton("Try Manual Code") { _, _ ->
                                        activeTab = "DEVICES"
                                        refreshUi()
                                    }
                                    .setNegativeButton("Rescan QR") { _, _ ->
                                        launchBuiltInQrScanner()
                                    }
                                    .show()
                            }
                        }
                    }.start()
                }
            }
        }
    }

    private fun isValidProofImage(bytes: ByteArray): Boolean {
        if (bytes.isEmpty() || bytes.size > 25 * 1024 * 1024) return false
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size, bounds)
        // Allow null mimeType (BitmapFactory may not detect MIME for all formats)
        // and allow HEIC/HEIF in addition to standard web formats
        val mimeType = bounds.outMimeType?.lowercase(java.util.Locale.US)
        val isKnownFormat = mimeType == null ||
            mimeType in setOf("image/jpeg", "image/jpg", "image/png", "image/webp",
                              "image/heic", "image/heif", "image/heic-sequence", "image/heif-sequence")
        if (!isKnownFormat) return false
        // For HEIC/HEIF, BitmapFactory.decodeByteArray may return null dimensions on older APIs.
        // If dimensions are available, validate them; otherwise fall through to decode check.
        if (bounds.outWidth > 0 && bounds.outHeight > 0) {
            if (bounds.outWidth < 100 || bounds.outHeight < 100) return false
            if (bounds.outWidth > 50_000 || bounds.outHeight > 50_000) return false
        }

        val sample = BitmapFactory.Options().apply { inSampleSize = 1 }
        val largestDimension = maxOf(bounds.outWidth.coerceAtLeast(1), bounds.outHeight.coerceAtLeast(1))
        while (largestDimension / sample.inSampleSize > 1024 && sample.inSampleSize < 64) {
            sample.inSampleSize *= 2
        }
        val decoded = BitmapFactory.decodeByteArray(bytes, 0, bytes.size, sample) ?: return false
        val w = decoded.width
        val h = decoded.height
        decoded.recycle()
        return w >= 100 && h >= 100
    }

    private fun onMultiplePhotosCaptured(list: List<Pair<ByteArray, String>>) {
        if (pendingPhotoPurpose == "TRAVEL") {
            val first = list.firstOrNull { isValidProofImage(it.first) }
            if (first != null) {
                travelProofBytes = first.first
                travelProofName = first.second
                travelPhotoStatusView?.apply {
                    text = "✓ Photo attached: ${first.second} (${first.first.size / 1024} KB)"
                    setTextColor(Color.parseColor(CLR_GREEN))
                }
                try {
                    val opts = BitmapFactory.Options().apply { inSampleSize = 4 }
                    val bmp = BitmapFactory.decodeByteArray(first.first, 0, first.first.size, opts)
                    if (bmp != null) {
                        travelPhotoPreviewView?.apply {
                            setImageBitmap(bmp)
                            visibility = View.VISIBLE
                        }
                    }
                } catch (_: Exception) {}
            } else {
                Toast.makeText(this, "None of the selected files were valid images.", Toast.LENGTH_LONG).show()
            }
            return
        }
        if (pendingPhotoPurpose == "GYM") {
            val first = list.firstOrNull { isValidProofImage(it.first) }
            if (first != null) {
                gymProofBytes = first.first
                gymProofName = first.second
                gymPhotoStatusView?.apply {
                    text = "✓ Photo attached: ${first.second} (${first.first.size / 1024} KB)"
                    setTextColor(Color.parseColor(CLR_GREEN))
                }
                try {
                    val opts = BitmapFactory.Options().apply { inSampleSize = 4 }
                    val bmp = BitmapFactory.decodeByteArray(first.first, 0, first.first.size, opts)
                    if (bmp != null) {
                        gymPhotoPreviewView?.apply {
                            setImageBitmap(bmp)
                            visibility = View.VISIBLE
                        }
                    }
                } catch (_: Exception) {}
            } else {
                Toast.makeText(this, "None of the selected files were valid images.", Toast.LENGTH_LONG).show()
            }
            return
        }
        if (pendingPhotoPurpose == "TAUFA_DEMO") {
            val valid = list.filter { isValidProofImage(it.first) }
            if (valid.isEmpty()) {
                Toast.makeText(this, "None of the selected files were valid images.", Toast.LENGTH_LONG).show()
                return
            }
            val availableSlots = TaufaAiValidator.MAX_HOURLY_PHOTOS - taufaDemoAttachments.size
            if (availableSlots <= 0) {
                Toast.makeText(this, "Maximum ${TaufaAiValidator.MAX_HOURLY_PHOTOS} photos already attached.", Toast.LENGTH_LONG).show()
                return
            }
            valid.take(availableSlots).forEach {
                taufaDemoAttachments.add(AttachedProof(it.first, it.second))
            }
            refreshTaufaDemoPreviews()
            Toast.makeText(this, "Added sample image(s) (${taufaDemoAttachments.size}/${TaufaAiValidator.MAX_HOURLY_PHOTOS}).", Toast.LENGTH_SHORT).show()
            return
        }
        val validItems = list.filter { isValidProofImage(it.first) }
        if (validItems.isEmpty()) {
            Toast.makeText(this, "None of the selected files were valid images.", Toast.LENGTH_LONG).show()
            return
        }
        val currentCount = hourlyAttachments.size
        val availableSlots = TaufaAiValidator.MAX_HOURLY_PHOTOS - currentCount
        if (availableSlots <= 0) {
            Toast.makeText(this, "Maximum ${TaufaAiValidator.MAX_HOURLY_PHOTOS} photos already attached.", Toast.LENGTH_LONG).show()
            return
        }
        if (validItems.size > availableSlots) {
            Toast.makeText(this, "Maximum ${TaufaAiValidator.MAX_HOURLY_PHOTOS} photos allowed. Adding first $availableSlots of ${validItems.size} selected photos.", Toast.LENGTH_LONG).show()
        }
        validItems.take(availableSlots).forEach {
            hourlyAttachments.add(AttachedProof(it.first, it.second))
        }
        hourlyHasPhoto = hourlyAttachments.isNotEmpty()
        lastCapturedHourlyPhotoBytes = hourlyAttachments.firstOrNull()?.bytes
        lastCapturedHourlyPhotoName = hourlyAttachments.firstOrNull()?.name ?: "evidence.jpg"
        updateHourlyEvidenceLabels()
        refreshHourlyPreviews()
        activeHourlyReviewLabel?.apply {
            text = "Status: REVIEW • ${hourlyAttachments.size}/10 image(s) attached and validated ✓"
            setTextColor(Color.parseColor(CLR_GREEN))
        }
    }

    private fun onPhotoBytesCaptured(bytes: ByteArray, fileName: String? = null) {
        if (!isValidProofImage(bytes)) {
            Toast.makeText(this, "That file is not a valid photo. Choose or capture a readable image.", Toast.LENGTH_LONG).show()
            return
        }
        if (pendingPhotoPurpose == "WAKEUP") {
            val date = db.nowDate()
            dispatchStrictBotEvent("EVIDENCE_ANALYZING")
            db.completeCameraStep(date, isDevMode, bytes)
            dispatchStrictBotEvent("EVIDENCE_ANALYZING", "Photo captured. Complete live-presence, earbuds and full-track checks in wake-up verification. This capture alone confirms no points or wake-up completion.")
            updateCountdownViews()
            showWakeUpVerificationDialog()
        } else if (pendingPhotoPurpose == "TRAVEL") {
            val safeName = fileName?.takeIf { it.isNotBlank() } ?: "travel_proof.jpg"
            travelProofBytes = bytes
            travelProofName = safeName
            travelPhotoStatusView?.apply {
                text = "✓ Photo attached: $safeName (${bytes.size / 1024} KB)"
                setTextColor(Color.parseColor(CLR_GREEN))
            }
            try {
                val opts = BitmapFactory.Options().apply { inSampleSize = 4 }
                val bmp = BitmapFactory.decodeByteArray(bytes, 0, bytes.size, opts)
                if (bmp != null) {
                    travelPhotoPreviewView?.apply {
                        setImageBitmap(bmp)
                        visibility = View.VISIBLE
                    }
                }
            } catch (_: Exception) {}
        } else if (pendingPhotoPurpose == "GYM") {
            val safeName = fileName?.takeIf { it.isNotBlank() } ?: "gym_proof.jpg"
            gymProofBytes = bytes
            gymProofName = safeName
            gymPhotoStatusView?.apply {
                text = "✓ Photo attached: $safeName (${bytes.size / 1024} KB)"
                setTextColor(Color.parseColor(CLR_GREEN))
            }
            try {
                val opts = BitmapFactory.Options().apply { inSampleSize = 4 }
                val bmp = BitmapFactory.decodeByteArray(bytes, 0, bytes.size, opts)
                if (bmp != null) {
                    gymPhotoPreviewView?.apply {
                        setImageBitmap(bmp)
                        visibility = View.VISIBLE
                    }
                }
            } catch (_: Exception) {}
        } else if (pendingPhotoPurpose == "TAUFA_DEMO") {
            val safeName = fileName?.takeIf { it.isNotBlank() } ?: "sample_${taufaDemoAttachments.size + 1}.jpg"
            if (taufaDemoAttachments.size >= TaufaAiValidator.MAX_HOURLY_PHOTOS) {
                Toast.makeText(this, "Maximum ${TaufaAiValidator.MAX_HOURLY_PHOTOS} photos already attached. Remove an image first.", Toast.LENGTH_LONG).show()
                return
            }
            taufaDemoAttachments.add(AttachedProof(bytes, safeName))
            refreshTaufaDemoPreviews()
            Toast.makeText(this, "Sample photo added (${taufaDemoAttachments.size}/${TaufaAiValidator.MAX_HOURLY_PHOTOS}).", Toast.LENGTH_SHORT).show()
        } else if (pendingPhotoPurpose == "HOURLY") {
            val safeName = fileName?.takeIf { it.isNotBlank() } ?: "evidence.jpg"
            if (hourlyAttachments.size >= TaufaAiValidator.MAX_HOURLY_PHOTOS) {
                Toast.makeText(this, "Maximum ${TaufaAiValidator.MAX_HOURLY_PHOTOS} photos already attached. Remove an image first.", Toast.LENGTH_LONG).show()
                return
            }
            hourlyAttachments.add(AttachedProof(bytes, safeName))
            hourlyHasPhoto = true
            lastCapturedHourlyPhotoBytes = hourlyAttachments.firstOrNull()?.bytes
            lastCapturedHourlyPhotoName = hourlyAttachments.firstOrNull()?.name ?: "evidence.jpg"
            updateHourlyEvidenceLabels()
            refreshHourlyPreviews()
            dispatchStrictBotEvent("EVIDENCE_ANALYZING", "Analyzing evidence hash & duplicate history...")
            activeHourlyReviewLabel?.apply {
                text = "Status: REVIEW • ${hourlyAttachments.size}/10 image(s) attached ✓"
                setTextColor(Color.parseColor(CLR_CYAN))
            }
            Thread {
                val sha256 = DisciplineScoringRules.computeSha256Hex(bytes)
                val (dHash, aHash) = db.computePerceptualHashes(bytes)
                val historical = db.getHistoricalEvidenceFingerprints()
                val dupCheck = DisciplineScoringRules.evaluateDuplicateCheck(
                    currentSha256 = sha256,
                    currentDhash = dHash,
                    currentOcrTokens = emptyList(),
                    history = historical,
                    currentAhash = aHash
                )
                runOnUiThread {
                    lastHourlyDuplicateStatus = dupCheck.status
                    val cleanStatus = cleanUserFacingText(dupCheck.status)
                    if (dupCheck.status in setOf("EXACT_DUPLICATE", "HIGH_SIMILARITY", "POSSIBLE_DUPLICATE")) {
                        dispatchStrictBotEvent("DUPLICATE_DETECTED", "Duplicate check: $cleanStatus (${dupCheck.comparisonMethod})")
                        activeHourlyReviewLabel?.apply {
                            val simPct = (dupCheck.similarityScore * 100).toInt()
                            text = "⚠️ Duplicate check: $cleanStatus (${dupCheck.comparisonMethod}, similarity $simPct%) • Matched: ${dupCheck.matchedEvidenceId ?: "prior proof"}"
                            setTextColor(Color.parseColor(CLR_AMBER))
                        }
                    } else {
                        dispatchStrictBotEvent("EVIDENCE_ANALYZING", "Local hash comparison: $cleanStatus. OCR and task review have not been confirmed.")
                        activeHourlyReviewLabel?.apply {
                            text = "✓ Evidence check: $cleanStatus (${dupCheck.comparisonMethod}) • Ready for submission"
                            setTextColor(Color.parseColor(CLR_GREEN))
                        }
                    }
                }
            }.start()
        } else if (pendingPhotoPurpose == "PC_SHUTDOWN") {
            val date = db.nowDate()
            val evId = "ev_sd_" + UUID.randomUUID().toString().replace("-", "").take(12)
            db.analyzeAndRecordEvidence(
                evidenceId = evId,
                submissionId = "sub_sd_$date",
                activityId = "PC_SHUTDOWN",
                date = date,
                rawBytes = bytes,
                category = "PC_SHUTDOWN",
                fileName = fileName?.takeIf { it.isNotBlank() } ?: "pc_shutdown.jpg"
            )
            db.recordPhoneShutdownPhoto(date, evId)
            dispatchStrictBotEvent("EVIDENCE_ANALYZING", "Workstation shutdown photo submitted. Display state and Windows shutdown event pending review.")
            Toast.makeText(this, "PC shutdown photo submitted! ✓", Toast.LENGTH_SHORT).show()
        }
        if (activeHourlyDialog?.isShowing != true) {
            refreshUi()
        }
    }

    private fun playMotivationTrack() {
        showWakeUpVerificationDialog()
    }

    private fun pollTrackProgress() {
        val mp = mediaPlayer ?: return
        if (mp.isPlaying) {
            val pct = ((mp.currentPosition.toDouble() / mp.duration.coerceAtLeast(1)) * 100.0).toInt()
            trackProgressBar?.progress = pct
            uiHandler.postDelayed({ pollTrackProgress() }, 200)
        }
    }

