    private fun testAppAccessDialog(app: String, score: Int, allowedOverride: Boolean? = null) {
        val threshold = if (app == "Local MP3") 60 else DisciplineScoringRules.CONFIGURED_RESTRICTED_APPS
            .firstOrNull { it.displayName.equals(app, ignoreCase = true) }?.requiredScore ?: 80
        val allowed = allowedOverride ?: DisciplineScoringRules.isAppAllowed(score, app)
        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(18), dp(20), dp(14))
            background = surfaceBg(CLR_MODAL, 18, if (allowed) CLR_GREEN else CLR_BORDER, 1)
        }
        dialogView.addView(TextView(this).apply {
            text = if (allowed) "AVAILABLE · $app" else "RESTRICTED · $app"
            textSize = 16f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (allowed) CLR_GREEN else CLR_TEXT_PRIMARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        })
        dialogView.addView(TextView(this).apply {
            text = "Current score: $score / 100\nConfigured score threshold: $threshold points\n\n" +
                if (allowed) "Access is currently permitted by the active restriction state."
                else "Access is currently restricted. Score rules may require ${(threshold - score).coerceAtLeast(0)} more points."
            textSize = 12f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
        })
        var dialogRef: AlertDialog? = null
        dialogView.addView(makeSecondaryButton("CLOSE", if (allowed) CLR_GREEN else CLR_CYAN) {
            dialogRef?.dismiss()
        }.apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                gravity = Gravity.END
                topMargin = dp(14)
            }
        })
        dialogRef = AlertDialog.Builder(this)
            .setView(dialogView)
            .create().apply {
                window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
                show()
            }
    }

