        val card = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            val pad = dp(if (isTablet) 14 else 12)
            setPadding(pad, pad, pad, pad)
            background = surfaceBg(CLR_SURFACE, 16, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
        }

        // Top Row: Icon + Header
        val topRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }

        val iconBadge = FrameLayout(this).apply {
            layoutParams = LinearLayout.LayoutParams(dp(32), dp(32)).apply { rightMargin = dp(10) }
            background = surfaceBg(CLR_ELEVATED, 10, CLR_BORDER, 1)
        }
        val iconTv = TextView(this).apply {
            text = "🎓"
            textSize = 16f
            gravity = Gravity.CENTER
            layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)
        }
        iconBadge.addView(iconTv)
        topRow.addView(iconBadge)

        val titleCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        titleCol.addView(TextView(this).apply {
            text = "TOMORROW'S COLLEGE ATTENDANCE"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            letterSpacing = 0.04f
        })

        val promptText: String
        val badgeText: String
        val badgeBg: String
        val badgeTextColor: String
        val badgeBorder: String

        val tomorrowBathCount = db.getMaxBathOccurrences(tomorrow)
        val bathPlural = if (tomorrowBathCount > 1) "BATHS" else "BATH"
        val tomorrowExamPlan = db.getDailyCollegeExamPlan(tomorrow)?.let { CollegeExamScheduleRules.CollegeExamPlan.fromJson(it) }
        val isCollegeYes = currentTomorrowAnswer == "YES"

        if (currentTomorrowAnswer.isNotBlank()) {
            promptText = "Confirmed Plan for Tomorrow, $tomorrowDisplay"
            if (isCollegeYes) {
                badgeText = "YES · $tomorrowBathCount $bathPlural"
                badgeBg = "#092419"
                badgeTextColor = CLR_GREEN
                badgeBorder = CLR_GREEN
            } else {
                badgeText = "NO · $tomorrowBathCount $bathPlural"
                badgeBg = "#121A2E"
                badgeTextColor = CLR_CYAN
                badgeBorder = CLR_CYAN
            }
        } else if (isDeadlinePassed) {
            promptText = "COLLEGE PLAN NOT CONFIGURED"
            badgeText = "DEADLINE PASSED (10:30 PM)"
            badgeBg = "#2E1515"
            badgeTextColor = CLR_AMBER
            badgeBorder = CLR_AMBER
        } else {
            promptText = "Are you attending college tomorrow, $tomorrowDisplay?"
            val diffMs = maxOf(0L, deadlineMs - nowMs)
            val diffHours = diffMs / 3600_000L
            val diffMins = (diffMs % 3600_000L) / 60_000L
            val countdownStr = if (diffHours > 0) "${diffHours}h ${diffMins}m left" else "${diffMins}m left"
            badgeText = "DUE 10:30 PM ($countdownStr)"
            badgeBg = CLR_SURFACE_LOW
            badgeTextColor = CLR_AMBER
            badgeBorder = CLR_AMBER
        }

        titleCol.addView(TextView(this).apply {
            text = promptText
            textSize = 13f
