            text = badgeText
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(badgeTextColor))
            setPadding(dp(8), dp(4), dp(8), dp(4))
            background = surfaceBg(badgeBg, 8, badgeBorder, 1)
        }
        topRow.addView(statusBadge)
        card.addView(topRow)

        if (currentTodayAnswer.isNotBlank()) {
            val todayBathCount = db.getMaxBathOccurrences(today)
            val todaySummary = if (currentTodayAnswer == "YES") "Today's Active Plan: Attending College ($todayBathCount Bath${if (todayBathCount > 1) "s" else ""} scheduled)" else "Today's Active Plan: Staying Home ($todayBathCount Bath${if (todayBathCount > 1) "s" else ""} scheduled)"
            card.addView(TextView(this).apply {
                text = todaySummary
                textSize = 10f
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(6)
                }
            })
        }

        val explanationText = when {
            currentTomorrowAnswer == "YES" -> {
                val sb = java.lang.StringBuilder()
                if (tomorrowExamPlan != null && !tomorrowExamPlan.collegeStartHhmm.isNullOrBlank()) {
                    sb.append("College: ${tomorrowExamPlan.collegeHoursDisplay}")
                    if (tomorrowExamPlan.hasExam) {
                        sb.append(" • Exam: ${tomorrowExamPlan.examHoursDisplay}")
                        if (tomorrowExamPlan.hasPostExamClassTime) {
                            sb.append(" • Post-exam class: ${tomorrowExamPlan.postExamClassDisplay} (Optional attendance • Bonus point: +1)")
                        }
                    }
                    sb.append("\n")
                } else {
                    sb.append("Attending college tomorrow\n")
                }
                sb.append("Bath sessions: $tomorrowBathCount scheduled independently")
                sb.toString()
            }
            currentTomorrowAnswer == "NO" -> "Staying home tomorrow • Bath sessions: $tomorrowBathCount scheduled independently"
            isDeadlinePassed -> "The 10:30 PM decision deadline for tomorrow ($tomorrowDisplay) has passed without a recorded choice. Select your plan now to configure tomorrow's routines:"
            else -> "Decision deadline: 10:30 PM tonight. Please confirm whether you are attending college tomorrow ($tomorrowDisplay) to configure your routines."
        }
        card.addView(TextView(this).apply {
            text = explanationText
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        })

        if (currentTomorrowAnswer.isNotBlank()) {
