                showBathProtocolSettingsDialog()
            }.apply {
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
            }
            btnRow.addView(editBtn)
            btnRow.addView(configBtn)
            card.addView(btnRow)
        } else {
            val btnRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }

            val btnYes = TextView(this).apply {
                text = "YES — ATTENDING COLLEGE"
                textSize = 11f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor("#070A0C"))
                gravity = Gravity.CENTER
                background = surfaceBg(CLR_GREEN, 10)
                setPadding(dp(12), dp(10), dp(12), dp(10))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(6) }
                applySpringTouch {
                    showNextDayRoutinePlannerDialog(forceUnlock = false, initialCollege = "YES")
                }
            }
            btnRow.addView(btnYes)

            val btnNo = TextView(this).apply {
                text = "NO — STAYING HOME"
                textSize = 11f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                gravity = Gravity.CENTER
                background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                setPadding(dp(12), dp(10), dp(12), dp(10))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(6) }
                applySpringTouch {
                    showNextDayRoutinePlannerDialog(forceUnlock = false, initialCollege = "NO")
                }
            }
            btnRow.addView(btnNo)
            card.addView(btnRow)

            val configBtn = makeSecondaryButton("⚙ CONFIGURE BATH TIMES & WINDOWS", CLR_CYAN) {
                showBathProtocolSettingsDialog()
            }.apply {
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(8)
                }
            }
            card.addView(configBtn)
        }

        addDailyGymDecisionViews(card, tomorrow, "Are you going to the gym tomorrow?")
        return card
    }

    private fun addDailyGymDecisionViews(card: LinearLayout, date: String, prompt: String) {
        val current = GymPolicyClient.decision(db, date)
        val label = TextView(this).apply {
            text = "$prompt ($date)"; textSize = 12f
            setTypeface(typeface, Typeface.BOLD); setTextColor(Color.WHITE)
            setPadding(0, dp(12), 0, dp(6))
        }
        card.addView(label)
        val selector = android.widget.Spinner(this).apply {
            adapter = android.widget.ArrayAdapter(this@MainActivity, android.R.layout.simple_spinner_dropdown_item,
                listOf("Choose Gym attendance", "Yes — Gym Day", if (date == db.nowDate()) "No — No Gym Today" else "No — No Gym Tomorrow"))
            setSelection(when(current.optString("status")) { "GYM_PLANNED" -> 1; "GYM_NOT_PLANNED" -> 2; else -> 0 })
        }
        card.addView(selector)
        val status = TextView(this).apply {
            text = when (current.optString("status")) {
                "GYM_PLANNED" -> if (current.optString("sync_status") == "PENDING_PC_SYNC") "Gym planned locally · PC sync queued (Offline GYM Mode ready after 5:00 PM)" else "Gym planned · confirmed revision ${current.optInt("revision")}"
                "GYM_NOT_PLANNED" -> "GYM Mode unavailable — Gym was marked as not planned for this date."
                else -> "Following persisted Alternate-Day Gym Routine (or choose an explicit override above)"
            }
            val pending = db.getConfigValue(GymPolicyClient.pendingKey(db,date), "")
            if (pending.isNotBlank()) {
                val pObj = runCatching { JSONObject(pending) }.getOrNull()
                if (pObj?.optBoolean("conflict") == true) {
                    text = pObj.optString("error", "Gym decision conflict — refresh required")
                }
            }
            textSize = 11f; setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            setPadding(0, dp(6), 0, dp(8))
        }
        card.addView(status)
        var savingGymDecision = false
        card.addView(makeSecondaryButton("SAVE GYM DECISION", CLR_CYAN) {
            if (savingGymDecision) return@makeSecondaryButton
            if (selector.selectedItemPosition == 0) { status.text = "Choose Yes or No first"; return@makeSecondaryButton }
            savingGymDecision = true
            selector.isEnabled = false
            val planned = selector.selectedItemPosition == 1
            Thread({
                val result = GymPolicyClient.save(db,date,planned)
                runOnUiThread {
                    savingGymDecision = false
                    selector.isEnabled = true
                    status.text = if (result.optBoolean("success")) {
                        if (result.optBoolean("offline_saved")) {
                            result.optString("message", "Saved locally · PC sync queued")
                        } else {
                            val decision = result.optJSONObject("decision") ?: GymPolicyClient.decision(db, date)
                            if (decision.optString("sync_status") == "REVOCATION_PENDING") "Gym marked No · restoring normal restrictions" else "Gym decision confirmed · revision ${decision.optInt("revision")}"
                        }
                    } else result.optString("error")
                    BackgroundMusicRestrictionManager.checkAndEnforceMusicRestrictions(this@MainActivity,"daily_gym_decision")
                    if (result.optBoolean("success")) refreshUi()
                }
            }, "Gym-DailyDecision").start()
        })
    }

    private fun showBathProtocolSettingsDialog() {
        showBathScheduleConfirmationDialog(isEditing = true)
    }

    private fun showBathScheduleConfirmationDialog(isEditing: Boolean = false, onDismissed: (() -> Unit)? = null) {
        if (isBathPopupShowing) return
        isBathPopupShowing = true

        val today = db.nowDate()
        val todayDisplay = try {
            val inSdf = SimpleDateFormat("yyyy-MM-dd", Locale.US).apply { isLenient = false }
            val outSdf = SimpleDateFormat("EEEE, MMM d, yyyy", Locale.US)
            outSdf.format(inSdf.parse(today) ?: Date())
        } catch (_: Exception) { today }

        val existingPlan = db.getDailyBathPlan(today)
        val hasConfirmedPlan = db.isBathScheduleConfirmed(today)

        var collegeChoice: String? = if (existingPlan != null) {
            existingPlan.optString("college_decision").ifBlank { null }
        } else {
            db.getCollegeAttendance(today).takeIf { it.isNotBlank() } ?: "YES"
        }

        var bathSessionCount = if (existingPlan != null && existingPlan.optJSONArray("selected_bath_times")?.length() != null) {
            existingPlan.optJSONArray("selected_bath_times")!!.length().coerceIn(1, 2)
        } else {
            db.getConfigValue("bath_session_count_$today", if (collegeChoice == "YES") "2" else "1").toIntOrNull()?.coerceIn(1, 2) ?: 1
        }

        var bath1Planned = if (existingPlan != null && (existingPlan.optJSONArray("selected_bath_times")?.length() ?: 0) >= 1) {
            existingPlan.optJSONArray("selected_bath_times")?.optString(0) ?: "07:30"
        } else {
            db.getPlannedBathTime(1, collegeChoice == "YES", today).ifBlank { if (collegeChoice == "YES") "07:30" else "13:00" }
        }

        var bath2Planned = if (existingPlan != null && (existingPlan.optJSONArray("selected_bath_times")?.length() ?: 0) >= 2) {
            existingPlan.optJSONArray("selected_bath_times")?.optString(1) ?: "16:00"
        } else {
            db.getPlannedBathTime(2, collegeChoice == "YES", today).ifBlank { if (collegeChoice == "YES") "16:00" else "18:00" }
        }

        var wakeupTargetPlanned = existingPlan?.optString("wakeup_target")?.takeIf { it.isNotBlank() }
            ?: db.getConfigValue("wakeup_target_$today", "").takeIf { it.isNotBlank() }
            ?: db.getScheduleForDate(today)?.optString("wake_up_time")?.takeIf { it.isNotBlank() }
            ?: db.getScheduleDraftForDate(today)?.optString("wake_up_time")?.takeIf { it.isNotBlank() }
            ?: db.getConfigValue("wakeup_target", "07:00")

        fun calcWakeupWindowText(hhmm: String): String {
            val parts = hhmm.split(":")
            val mins = (parts.getOrNull(0)?.toIntOrNull() ?: 7) * 60 + (parts.getOrNull(1)?.toIntOrNull() ?: 0)
            val s = (mins - 10 + 1440) % 1440
            val endMins = minOf(mins + 10, 10 * 60)
            val e = endMins % 1440
            val sStr = String.format(Locale.US, "%02d:%02d", s / 60, s % 60)
            val eStr = String.format(Locale.US, "%02d:%02d", e / 60, e % 60)
            return "${DisciplineScoringRules.formatTime12h(sStr)}–${DisciplineScoringRules.formatTime12h(eStr)}"
        }

        var dialogRef: AlertDialog? = null
        var isSavingBathPlan = false

        val existingDailyGym = db.getDailyGymSetup(today)
        var gymChoice: String? = existingDailyGym?.choice?.name?.takeIf { it != "UNSET" }
            ?: run {
                val dec = GymPolicyClient.decision(db, today)
                when (dec.optString("status")) {
                    "GYM_PLANNED" -> "YES"
                    "GYM_NOT_PLANNED" -> "NO_GYM"
                    else -> null
                }
            }
        var gymPlannedTime: String = existingDailyGym?.plannedStartTime?.takeIf { it.isNotBlank() }
            ?: db.getDailyActivities(today).firstOrNull { it.type == "GYM" }?.scheduledTime?.substringAfter('T', "")?.take(5)?.takeIf { it.isNotBlank() }
            ?: db.getScheduleDraftForDate(today)?.optString("gym_time")?.takeIf { it.isNotBlank() }
            ?: db.getScheduleForDate(today)?.optString("gym_time")?.takeIf { it.isNotBlank() }
            ?: "18:00"
        var gymPlannedDuration: Int = existingDailyGym?.plannedDurationMinutes?.takeIf { it > 0 }
            ?: db.getScheduleDraftForDate(today)?.optInt("gym_duration_minutes", 0)?.takeIf { it > 0 }
            ?: db.getScheduleForDate(today)?.optInt("gym_duration_minutes", 0)?.takeIf { it > 0 }
            ?: 90

        val existingSleepSub = db.getSleepSubmission(today, isDevMode)
        val pendingSleepEval = db.getProofEvaluationByActivity("act_sleep_$today", today, isDevMode)
        val sleepTelemetry = MiFitnessSleepController.getSleepCardTelemetry(db, today, isDevMode)
        val isSleepDeclined = db.getConfigValue("sleep_report_declined_$today", "false") == "true"
        val hasExistingSleepSubmission = existingSleepSub != null || pendingSleepEval != null || sleepTelemetry.isCompleted || sleepTelemetry.status == "EVALUATING"

        var sleepReportChoice: String? = when {
