            val gymAnchorDate = gymPair.second.lastOrNull()?.anchorDate?.ifBlank { gymPair.first } ?: gymPair.first.ifBlank { GymRoutineDates.LAUNCH_DATE }
            val gymStatusDisplay = when (plannedGymState) {
