                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(14)
                }
            }
            val btnCollegeYes = TextView(this@MainActivity).apply {
                text = "🎓 Yes, college day"
                textSize = 11.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(if (collegeChoice == "YES") Color.parseColor("#070A0C") else Color.WHITE)
                gravity = Gravity.CENTER
                background = if (collegeChoice == "YES") surfaceBg(CLR_CYAN, 10) else surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                setPadding(dp(10), dp(12), dp(10), dp(12))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
                applySpringTouch {
                    collegeChoice = "YES"
                    bath1Planned = "07:30"
                    if (bath2Planned == "18:00") bath2Planned = "16:00"
                    renderDialogContent()
                }
            }
            val btnCollegeNo = TextView(this@MainActivity).apply {
                text = "🏠 No, non-college day"
                textSize = 11.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(if (collegeChoice == "NO") Color.parseColor("#070A0C") else Color.WHITE)
                gravity = Gravity.CENTER
                background = if (collegeChoice == "NO") surfaceBg(CLR_GREEN, 10) else surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                setPadding(dp(10), dp(12), dp(10), dp(12))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
                applySpringTouch {
                    collegeChoice = "NO"
                    if (bath1Planned == "07:30") bath1Planned = "13:00"
                    if (bath2Planned == "16:00") bath2Planned = "18:00"
                    renderDialogContent()
                }
            }
            collegeRow.addView(btnCollegeYes)
            collegeRow.addView(btnCollegeNo)
            container.addView(collegeRow)

            // ── Section 3: Bath Frequency ──
            container.addView(TextView(this@MainActivity).apply {
                text = "3. How many bath sessions are planned today?"
                textSize = 12.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(6)
                }
            })
            val freqRow = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(14)
                }
            }
            val btnOneBath = TextView(this@MainActivity).apply {
                text = "🛁 One bath session"
                textSize = 11.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(if (bathSessionCount == 1) Color.parseColor("#070A0C") else Color.WHITE)
                gravity = Gravity.CENTER
                background = if (bathSessionCount == 1) surfaceBg(CLR_GREEN, 10) else surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                setPadding(dp(10), dp(12), dp(10), dp(12))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
                applySpringTouch {
                    bathSessionCount = 1
                    renderDialogContent()
                }
            }
            val btnTwoBaths = TextView(this@MainActivity).apply {
                text = "🛁🛁 Two bath sessions"
                textSize = 11.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(if (bathSessionCount == 2) Color.parseColor("#070A0C") else Color.WHITE)
                gravity = Gravity.CENTER
                background = if (bathSessionCount == 2) surfaceBg(CLR_CYAN, 10) else surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                setPadding(dp(10), dp(12), dp(10), dp(12))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
                applySpringTouch {
                    bathSessionCount = 2
                    renderDialogContent()
                }
            }
            freqRow.addView(btnOneBath)
            freqRow.addView(btnTwoBaths)
            container.addView(freqRow)

            // ── Section 4: Bath Timings & Late Evaluation ──
            val isCollege = collegeChoice == "YES"
            container.addView(TextView(this@MainActivity).apply {
                text = "4. Bath Session Timing"
                textSize = 12.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(6)
                }
            })

            // Bath 1 selector (fixed 07:30 on college days per Part B.4; configurable on non-college days)
            if (isCollege) bath1Planned = "07:30"
            val b1Win = BathWindowRules.calculateBathWindow(1, isCollege, today, bath1Planned, timezone = db.scheduleTimezone())
            val b1Rec = BathScheduleRecord.fromWindow(b1Win, db.scheduleTimezone())
            val b1Btn = TextView(this@MainActivity).apply {
                text = if (isCollege) {
                    "Bath #1: ${DisciplineScoringRules.formatTime12h(bath1Planned)} (Fixed College Morning Slot)"
                } else {
                    "Bath #1: ${DisciplineScoringRules.formatTime12h(bath1Planned)} ▼"
                }
                textSize = 12f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                gravity = Gravity.CENTER
                background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                setPadding(dp(14), dp(10), dp(14), dp(10))
                if (!isCollege) {
                    applySpringTouch {
                        val parts = bath1Planned.split(":").map { it.toInt() }
                        TimePickerDialog(this@MainActivity, { _, h, m ->
                            val chosen = String.format(Locale.US, "%02d:%02d", h, m)
                            val startWin = "06:00"
                            val endWin = "21:00"
                            if (BathWindowRules.isValidPlannedBathTime(chosen, startWin, endWin)) {
                                bath1Planned = chosen
                                renderDialogContent()
                            } else {
                                Toast.makeText(this@MainActivity, "Bath #1 must fall within $startWin–$endWin", Toast.LENGTH_LONG).show()
                            }
                        }, parts[0], parts[1], false).show()
                    }
                }
            }
            container.addView(b1Btn)
            val b1Info = TextView(this@MainActivity).apply {
                text = "• Bath Interval: ${b1Rec.activityIntervalDisplay}\n• Scheduled activity · No proof required"
                textSize = 10.5f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(4)
                    bottomMargin = dp(8)
                }
            }
            container.addView(b1Info)

            var b2Win: BathWindowRules.BathWindow? = null
            if (bathSessionCount >= 2) {
                val b2Calculated = BathWindowRules.calculateBathWindow(2, isCollege, today, bath2Planned, timezone = db.scheduleTimezone())
                b2Win = b2Calculated
                val b2Rec = BathScheduleRecord.fromWindow(b2Calculated, db.scheduleTimezone())
                val b2Btn = TextView(this@MainActivity).apply {
                    text = "Bath #2: ${DisciplineScoringRules.formatTime12h(bath2Planned)} ▼"
                    textSize = 12f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.WHITE)
                    gravity = Gravity.CENTER
                    background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                    setPadding(dp(14), dp(10), dp(14), dp(10))
                    applySpringTouch {
                        val parts = bath2Planned.split(":").map { it.toInt() }
                        TimePickerDialog(this@MainActivity, { _, h, m ->
                            val chosen = String.format(Locale.US, "%02d:%02d", h, m)
                            val startWin = if (isCollege) "16:00" else "12:00"
                            val endWin = if (isCollege) "20:00" else "21:00"
                            if (BathWindowRules.isValidPlannedBathTime(chosen, startWin, endWin)) {
                                bath2Planned = chosen
                                renderDialogContent()
                            } else {
                                Toast.makeText(this@MainActivity, "Bath #2 must fall within $startWin–$endWin", Toast.LENGTH_LONG).show()
                            }
                        }, parts[0], parts[1], false).show()
                    }
                }
                container.addView(b2Btn)
                val b2Info = TextView(this@MainActivity).apply {
                    text = "• Bath Interval: ${b2Rec.activityIntervalDisplay}\n• Scheduled activity · No proof required"
                    textSize = 10.5f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(4)
                        bottomMargin = dp(8)
                    }
                }
                container.addView(b2Info)
            }

            // Late wake-up evaluation
            val lateEval = BathWindowRules.evaluateLateWakeUp(db.authoritativeNowMs(), isCollege, b1Win, b2Win)
            if (bathSessionCount >= 2 && !lateEval.bath2Feasible) {
                container.addView(TextView(this@MainActivity).apply {
                    text = "⚠️ Bath Session 2 conflicts with Bath Session 1. Adjust Bath #2 timing before confirming."
                    textSize = 11f
                    setTextColor(Color.parseColor(CLR_RED))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        bottomMargin = dp(8)
                    }
                })
            }

            // ── Section 5: Sleep Data Report ──
            val isSleepDeadlinePassed = MiFitnessSleepBonusRules.isDeadlinePassed(db.authoritativeNowMs(), today, db.scheduleTimezone())

            val sleepSection = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(14), dp(12), dp(14), dp(12))
                background = surfaceBg(CLR_SURFACE_LOW, 12, CLR_BORDER, 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(14)
                }
            }

            sleepSection.addView(TextView(this@MainActivity).apply {
                text = "5. SLEEP DATA REPORT"
                textSize = 12f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_CYAN))
                letterSpacing = 0.04f
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(4)
                }
            })

            sleepSection.addView(TextView(this@MainActivity).apply {
                text = "Would you like to submit your sleep report today?"
                textSize = 12.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(8)
                }
            })

            if (hasExistingSleepSubmission) {
                val existingStatusCard = LinearLayout(this@MainActivity).apply {
                    orientation = LinearLayout.VERTICAL
                    setPadding(dp(12), dp(10), dp(12), dp(10))
                    background = surfaceBg("#0E1A29", 10, CLR_CYAN, 1)
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
                    addView(TextView(context).apply {
                        text = "CURRENT STATUS: ${sleepTelemetry.statusLabel.uppercase(java.util.Locale.US)}"
                        textSize = 11f
                        setTypeface(typeface, Typeface.BOLD)
                        setTextColor(Color.parseColor(sleepTelemetry.statusColorHex))
                    })
                    addView(TextView(context).apply {
                        text = sleepTelemetry.summaryLine
                        textSize = 10.5f
                        setTextColor(Color.WHITE)
                        setPadding(0, dp(3), 0, 0)
                    })
                }
                sleepSection.addView(existingStatusCard)
            } else if (isSleepDeadlinePassed) {
                val deadlinePassedCard = LinearLayout(this@MainActivity).apply {
                    orientation = LinearLayout.VERTICAL
                    setPadding(dp(12), dp(10), dp(12), dp(10))
                    background = surfaceBg("#1E1E24", 10, "#8B949E", 1)
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
                    addView(TextView(context).apply {
                        text = "⏰ 12:00 PM deadline has passed. Sleep report submissions are closed for today."
                        textSize = 11f
                        setTextColor(Color.parseColor("#8B949E"))
                    })
                }
                sleepSection.addView(deadlinePassedCard)
            } else {
                val sleepChoiceRow = LinearLayout(this@MainActivity).apply {
                    orientation = LinearLayout.HORIZONTAL
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        bottomMargin = dp(10)
                    }
                }
                val isSleepYes = sleepReportChoice == "YES"
                val isSleepNo = sleepReportChoice == "NO"

                val btnSleepYes = TextView(this@MainActivity).apply {
                    text = "🌙 Yes, submit report"
                    textSize = 11.5f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(if (isSleepYes) Color.parseColor("#070A0C") else Color.WHITE)
                    gravity = Gravity.CENTER
                    background = if (isSleepYes) surfaceBg(CLR_CYAN, 10) else surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                    setPadding(dp(10), dp(12), dp(10), dp(12))
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
                    applySpringTouch {
                        sleepReportChoice = "YES"
                        renderDialogContent()
                    }
                }

                val btnSleepNo = TextView(this@MainActivity).apply {
                    text = "❌ No, skip today"
                    textSize = 11.5f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(if (isSleepNo) Color.parseColor("#070A0C") else Color.WHITE)
                    gravity = Gravity.CENTER
                    background = if (isSleepNo) surfaceBg(CLR_GREEN, 10) else surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                    setPadding(dp(10), dp(12), dp(10), dp(12))
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
                    applySpringTouch {
                        sleepReportChoice = "NO"
                        attachedSleepUri = null
                        attachedSleepName = null
                        renderDialogContent()
                    }
                }
                sleepChoiceRow.addView(btnSleepYes)
                sleepChoiceRow.addView(btnSleepNo)
                sleepSection.addView(sleepChoiceRow)

                if (isSleepNo) {
                    val noSleepCard = LinearLayout(this@MainActivity).apply {
                        orientation = LinearLayout.VERTICAL
                        setPadding(dp(12), dp(10), dp(12), dp(10))
                        background = surfaceBg("#071E17", 10, CLR_GREEN, 1)
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
                        addView(TextView(context).apply {
                            text = "✓ Sleep report skipped for today."
                            textSize = 12f
                            setTypeface(typeface, Typeface.BOLD)
                            setTextColor(Color.parseColor(CLR_GREEN))
                        })
                        addView(TextView(context).apply {
                            text = "No sleep submission will be created. No bonus points or penalties applied. Previous sleep records are preserved."
                            textSize = 10.5f
                            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                            setPadding(0, dp(2), 0, 0)
                        })
                    }
                    sleepSection.addView(noSleepCard)
                }

                if (isSleepYes) {
                    val uploadCard = LinearLayout(this@MainActivity).apply {
                        orientation = LinearLayout.VERTICAL
                        setPadding(dp(12), dp(10), dp(12), dp(10))
                        background = surfaceBg("#161B22", 10, CLR_BORDER, 1)
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
                    }

                    uploadCard.addView(TextView(this@MainActivity).apply {
                        text = "Upload Mi Fitness / Xiaomi Smartwatch Sleep Report"
                        textSize = 11.5f
                        setTypeface(typeface, Typeface.BOLD)
                        setTextColor(Color.WHITE)
                    })

                    uploadCard.addView(TextView(this@MainActivity).apply {
                        text = "⚡ Bonus: up to 5 pts   •   ⏰ Submission deadline: 12:00 PM"
                        textSize = 10.5f
                        typeface = Typeface.MONOSPACE
                        setTextColor(Color.parseColor(CLR_GREEN))
                        setPadding(0, dp(2), 0, dp(8))
                    })

                    if (attachedSleepUri == null) {
                        val btnPick = TextView(this@MainActivity).apply {
                            text = "📁 Select Sleep Screenshot / Photo"
                            textSize = 12f
                            setTypeface(typeface, Typeface.BOLD)
                            setTextColor(Color.WHITE)
                            gravity = Gravity.CENTER
                            background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_CYAN, 1)
                            setPadding(dp(14), dp(10), dp(14), dp(10))
                            applySpringTouch {
                                pickSleepScreenshot { uris ->
                                    val u = uris.firstOrNull()
                                    if (u != null) {
                                        attachedSleepUri = u
                                        attachedSleepName = u.lastPathSegment ?: "sleep_screenshot.jpg"
                                        renderDialogContent()
                                    }
                                }
                            }
                        }
                        uploadCard.addView(btnPick)
                    } else {
                        val previewRow = LinearLayout(this@MainActivity).apply {
                            orientation = LinearLayout.HORIZONTAL
                            gravity = Gravity.CENTER_VERTICAL
                            setPadding(0, dp(4), 0, dp(8))
                        }

                        val thumbView = ImageView(this@MainActivity).apply {
                            layoutParams = LinearLayout.LayoutParams(dp(54), dp(54)).apply { rightMargin = dp(10) }
                            scaleType = ImageView.ScaleType.CENTER_CROP
                            try {
                                val stream = contentResolver.openInputStream(attachedSleepUri!!)
                                val bmp = android.graphics.BitmapFactory.decodeStream(stream)
                                stream?.close()
                                if (bmp != null) setImageBitmap(bmp) else setImageResource(android.R.drawable.ic_menu_gallery)
                            } catch (_: Exception) {
                                setImageResource(android.R.drawable.ic_menu_gallery)
                            }
                        }
                        previewRow.addView(thumbView)

                        val infoCol = LinearLayout(this@MainActivity).apply {
                            orientation = LinearLayout.VERTICAL
                            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                        }
                        infoCol.addView(TextView(this@MainActivity).apply {
                            text = "✓ Sleep Screenshot Attached"
                            textSize = 11.5f
                            setTypeface(typeface, Typeface.BOLD)
                            setTextColor(Color.parseColor(CLR_GREEN))
                        })
                        infoCol.addView(TextView(this@MainActivity).apply {
                            text = attachedSleepName ?: "sleep_screenshot.jpg"
                            textSize = 10f
                            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                            maxLines = 1
                            ellipsize = android.text.TextUtils.TruncateAt.MIDDLE
                        })
                        infoCol.addView(TextView(this@MainActivity).apply {
                            text = "Ready to submit with morning routine"
                            textSize = 9.5f
                            setTextColor(Color.parseColor(CLR_CYAN))
                        })
                        previewRow.addView(infoCol)
                        uploadCard.addView(previewRow)

                        val actionBtnRow = LinearLayout(this@MainActivity).apply {
                            orientation = LinearLayout.HORIZONTAL
                            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                                topMargin = dp(4)
                            }
                        }
                        actionBtnRow.addView(makeSecondaryButton("CHANGE IMAGE", CLR_CYAN) {
                            pickSleepScreenshot { uris ->
                                val u = uris.firstOrNull()
                                if (u != null) {
                                    attachedSleepUri = u
                                    attachedSleepName = u.lastPathSegment ?: "sleep_screenshot.jpg"
                                    renderDialogContent()
                                }
                            }
                        }.apply {
                            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
                        })
                        actionBtnRow.addView(makeSecondaryButton("REMOVE", CLR_RED) {
                            attachedSleepUri = null
                            attachedSleepName = null
                            renderDialogContent()
                        }.apply {
                            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
                        })
                        uploadCard.addView(actionBtnRow)
                    }
                    sleepSection.addView(uploadCard)
                }
            }

            container.addView(sleepSection)

            // ── Section E: Confirmation Action ──
            val actionRow = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            if (isEditing) {
                actionRow.addView(makeSecondaryButton("CANCEL", CLR_TEXT_DIM) {
                    dialogRef?.dismiss()
                    isBathPopupShowing = false
                }.apply {
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(6) }
                })
            }

            val confirmBtn = makePrimaryButton("CONFIRM TODAY'S ROUTINE", CLR_GREEN) { btnView ->
                if (isSavingBathPlan) return@makePrimaryButton
                if (collegeChoice == null) {
                    AlertDialog.Builder(this@MainActivity)
                        .setTitle("Schedule Configuration")
                        .setMessage("Please select whether you are going to college today (YES or NO).")
                        .setPositiveButton("OK", null)
                        .show()
                    return@makePrimaryButton
                }

                if (gymChoice == null) {
                    AlertDialog.Builder(this@MainActivity)
                        .setTitle("Schedule Configuration")
                        .setMessage("Please answer: Are you going to the gym today? (YES or NO).")
                        .setPositiveButton("OK", null)
                        .show()
                    return@makePrimaryButton
                }

                if (sleepReportChoice == null && !hasExistingSleepSubmission && !MiFitnessSleepBonusRules.isDeadlinePassed(db.authoritativeNowMs(), today, db.scheduleTimezone())) {
                    AlertDialog.Builder(this@MainActivity)
                        .setTitle("Schedule Configuration")
                        .setMessage("Please select whether you would like to submit your sleep report today (YES or NO).")
                        .setPositiveButton("OK", null)
                        .show()
                    return@makePrimaryButton
                }

                val cleanCollege = collegeChoice!!.trim().uppercase(Locale.US)
                val isCollege = cleanCollege == "YES"
                val times = if (bathSessionCount == 1) listOf(bath1Planned) else listOf(bath1Planned, bath2Planned)

                val cleanWakeup = DisciplineScoringRules.validateWakeUpTime(wakeupTargetPlanned).let {
                    if (it.first) it.second else "07:00"
                }

                if (gymChoice == "YES") {
                    val gymVal = DailyGymScheduleRules.validateGymTiming(
                        choice = DailyGymScheduleRules.DailyGymChoice.YES,
                        plannedStartTime = gymPlannedTime,
                        durationMinutes = gymPlannedDuration,
                        attendsCollege = isCollege,
                        collegeStartHhmm = if (isCollege) "09:00" else null,
                        collegeEndHhmm = if (isCollege) "15:15" else null,
                        bathTimes = times,
                        wakeUpTargetHhmm = cleanWakeup
                    )
                    if (!gymVal.isValid) {
                        AlertDialog.Builder(this@MainActivity)
                            .setTitle("Invalid Gym Timing")
                            .setMessage(gymVal.errorMessage ?: "Invalid gym timing.")
                            .setPositiveButton("OK", null)
                            .show()
                        return@makePrimaryButton
                    }
                }
                val popupVal = BathScheduleMorningPopupRules.validateSelection(
                    collegeDecision = cleanCollege,
                    selectedTimes = times,
                    windowStartOverride = if (isCollege) null else "06:00",
                    windowEndOverride = if (isCollege) null else "22:00",
                    sessionCount = bathSessionCount
                )
                if (!popupVal.isValid) {
                    AlertDialog.Builder(this@MainActivity)
                        .setTitle("Invalid Schedule")
                        .setMessage(popupVal.errorMessage ?: "Invalid schedule.")
                        .setPositiveButton("OK", null)
                        .show()
                    return@makePrimaryButton
                }
                val indepVal = BathSchedulePlanManager.validateSelection(
                    date = today,
                    collegeDecision = cleanCollege,
                    selectedTimes = times,
                    timezone = db.scheduleTimezone(),
                    sessionCount = bathSessionCount
                )
                if (!indepVal.isValid) {
                    AlertDialog.Builder(this@MainActivity)
                        .setTitle("Invalid Bath Times")
                        .setMessage(indepVal.errorMessage ?: "Invalid bath times.")
                        .setPositiveButton("OK", null)
                        .show()
                    return@makePrimaryButton
                }
                if (bathSessionCount >= 2 && !lateEval.bath2Feasible) {
                    AlertDialog.Builder(this@MainActivity)
                        .setTitle("Bath Timing Conflict")
                        .setMessage("Bath #1 and Bath #2 overlap. Please choose non-overlapping times.")
                        .setPositiveButton("OK", null)
                        .show()
                    return@makePrimaryButton
                }

                isSavingBathPlan = true
                val btnTv = btnView.getChildAt(0) as? TextView
                btnTv?.text = "SAVING ROUTINE..."
                btnView.alpha = 0.6f

                val bathTimeoutRunnable = Runnable {
                    if (isSavingBathPlan) {
                        isSavingBathPlan = false
                        btnTv?.text = "CONFIRM TODAY'S ROUTINE"
                        btnView.alpha = 1.0f
                        val confirmedNow = try { db.isScheduleConfirmedForDate(today) } catch (_: Throwable) { false }
                        if (confirmedNow) {
                            haptic(1)
                            isSchedulePendingRestricted = false
                            currentScheduleDeadlineState = ScheduleDeadlineRules.ScheduleDeadlineState.CONFIRMED_AND_RELEASED
                            try { ScheduleDeadlineManager.cancelDeadlineNotification(this@MainActivity) } catch (_: Throwable) {}
                            try { WakeUpAlarmReceiver.scheduleHourlyWindows(this@MainActivity, forceRebuild = true) } catch (_: Throwable) {}
                            try { MorningWakeUpManager.cancelMorningNotification(this@MainActivity) } catch (_: Throwable) {}
                            Toast.makeText(this@MainActivity, "Today's routine confirmed & saved ✓", Toast.LENGTH_LONG).show()
                            dialogRef?.dismiss()
                            isBathPopupShowing = false
                            updateCountdownViews()
                            refreshUi()
                        } else {
                            Toast.makeText(this@MainActivity, "Routine save timed out. Inputs preserved; please tap again.", Toast.LENGTH_LONG).show()
                        }
                    }
                }
                uiHandler.postDelayed(bathTimeoutRunnable, 15000L)

                Thread {
                    try {
                        val gymPlannedBool = (gymChoice == "YES")
                        if (sleepReportChoice == "NO") {
                            db.setConfigValue("sleep_report_declined_$today", "true")
                            db.setConfigValue("sleep_report_today_$today", "false")
                        } else if (sleepReportChoice == "YES" && attachedSleepUri != null) {
                            db.setConfigValue("sleep_report_declined_$today", "false")
                            db.setConfigValue("sleep_report_today_$today", "true")
                            val capturedSleepUri = attachedSleepUri!!
                            Thread {
                                try {
                                    ProofEvaluationManager.submitSleepReport(
                                        context = this@MainActivity,
                                        db = db,
                                        uris = listOf(capturedSleepUri),
                                        date = today,
                                        isDevMode = isDevMode
                                    )
                                } catch (se: Throwable) {
                                    Log.w("MainActivity", "Sleep report submission error: ${se.message}", se)
                                }
                            }.start()
                        }
                        db.setConfigValue("morning_setup_completed_$today", "true")
                        db.saveDailyGymSetup(
                            date = today,
                            choice = gymChoice!!,
                            startTime = if (gymPlannedBool) gymPlannedTime else null,
                            durationMinutes = if (gymPlannedBool) gymPlannedDuration else 0,
                            isConfirmed = true
                        )
                        db.setConfigValue("wakeup_target", cleanWakeup)
                        db.setConfigValue("wakeup_target_$today", cleanWakeup)
                        db.saveScheduleDraftForDate(
                            date = today,
                            wakeUpTime = cleanWakeup,
                            bathTime = bath1Planned,
                            gymTime = if (gymPlannedBool) gymPlannedTime else "",
                            gymEnabled = gymPlannedBool,
                            collegeDecision = cleanCollege,
                            bathSessionCount = bathSessionCount,
                            bathTimes = times,
                            gymDurationMinutes = if (gymPlannedBool) gymPlannedDuration else 0
                        )
                        var res = db.confirmDailyBathPlan(today, cleanCollege, times, allowOverwrite = true)
                        if (res.optBoolean("success")) {
                            val curPlan = db.getDailyBathPlan(today) ?: JSONObject()
                            curPlan.put("wakeup_target", cleanWakeup)
                            curPlan.put("daily_gym_choice", gymChoice)
                            curPlan.put("gym_planned", gymPlannedBool)
                            if (gymPlannedBool) {
                                curPlan.put("gym_time", gymPlannedTime)
                                curPlan.put("gym_duration_minutes", gymPlannedDuration)
                            }
                            db.setConfigValue("daily_bath_plan_$today", curPlan.toString())
                            // Keep the day-level schedule record consistent so the 10:00 AM deadline gate is satisfied.
                            val fin = db.finalizeDailyRoutineSchedule(today)
                            if (!fin.optBoolean("success", false)) res = fin
                        }
                        val savedPlan = db.getDailyBathPlan(today)
                        val planCollege = savedPlan?.optString("college_decision", "")?.trim()?.uppercase(Locale.US)
                        val planBathCount = savedPlan?.optJSONArray("selected_bath_times")?.length() ?: 0
                        val isConfirmed = db.isScheduleConfirmedForDate(today)
                        val persistedMatch = res.optBoolean("success") &&
                            planCollege == cleanCollege &&
                            planBathCount == bathSessionCount &&
                            isConfirmed

                        runOnUiThread {
                            uiHandler.removeCallbacks(bathTimeoutRunnable)
                            isSavingBathPlan = false
                            btnTv?.text = "CONFIRM TODAY'S ROUTINE"
                            btnView.alpha = 1.0f

                            if (persistedMatch) {
                                haptic(1)
                                isSchedulePendingRestricted = false
                                currentScheduleDeadlineState = ScheduleDeadlineRules.ScheduleDeadlineState.CONFIRMED_AND_RELEASED
                                try {
                                    ScheduleDeadlineManager.cancelDeadlineNotification(this@MainActivity)
                                } catch (e: Throwable) {
                                    Log.w("MainActivity", "cancelDeadlineNotification error: ${e.message}")
                                }
                                try {
                                    WakeUpAlarmReceiver.scheduleHourlyWindows(this@MainActivity, forceRebuild = true)
                                } catch (e: Throwable) {
                                    Log.w("MainActivity", "scheduleHourlyWindows error: ${e.message}")
                                }
                                MorningWakeUpManager.cancelMorningNotification(this@MainActivity)
                                Toast.makeText(this@MainActivity, "Today's routine confirmed & saved ✓", Toast.LENGTH_LONG).show()
                                dialogRef?.dismiss()
                                isBathPopupShowing = false
                                updateCountdownViews()
                                refreshUi()

                                Thread {
                                    try {
                                        db.syncRoutineScheduleWithServer(today)
                                    } catch (_: Throwable) {}
                                }.start()
                            } else {
                                val err = when {
                                    !res.optBoolean("success") -> res.optString("error", "Database routine confirmation failed.")
                                    planCollege != cleanCollege -> "College attendance ($planCollege) does not match chosen value ($cleanCollege)."
                                    planBathCount != bathSessionCount -> "Bath count ($planBathCount) does not match chosen count ($bathSessionCount)."
                                    !isConfirmed -> "Schedule lock verification failed: daily routine record was not finalized in database."
                                    else -> res.optString("error", "Failed to verify saved daily routine.")
                                }
                                AlertDialog.Builder(this@MainActivity)
                                    .setTitle("Schedule Configuration Error")
                                    .setMessage("Unable to confirm today's routine:\n\n$err\n\nYour selections have been preserved. Please check your selections and try again.")
                                    .setPositiveButton("OK", null)
                                    .show()
                            }
                        }
                    } catch (t: Throwable) {
                        Log.e("MainActivity", "Fatal error during routine confirmation", t)
                        runOnUiThread {
                            uiHandler.removeCallbacks(bathTimeoutRunnable)
                            isSavingBathPlan = false
                            btnTv?.text = "CONFIRM TODAY'S ROUTINE"
                            btnView.alpha = 1.0f

                            val causeMsg = t.localizedMessage ?: t.javaClass.simpleName
                            AlertDialog.Builder(this@MainActivity)
                                .setTitle("Schedule Configuration Error")
                                .setMessage("An unexpected error occurred while saving your routine:\n\n$causeMsg\n\nYour selections have been preserved. Please try again.")
                                .setPositiveButton("OK", null)
                                .show()
                        }
                    }
                }.start()
            }.apply {
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, if (isEditing) 2f else 1f)
            }
            actionRow.addView(confirmBtn)
            container.addView(actionRow)
        }

        renderDialogContent()

        val dialog = AlertDialog.Builder(this)
            .setView(scroll)
            .setCancelable(isEditing)
            .create()

        dialog.setOnDismissListener {
            isBathPopupShowing = false
            onDismissed?.invoke()
        }

        dialogRef = dialog
        bathDialogRef = dialog
        dialog.setOnDismissListener {
            isBathPopupShowing = false
            if (bathDialogRef === dialog) {
                bathDialogRef = null
            }
            onDismissed?.invoke()
        }
        dialog.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
        if (!isFinishing && !isDestroyed && screenResumed) {
            dialog.show()
        }
    }

    private var wakeUpPreviewPlayer: MediaPlayer? = null

    private fun isWakeUpPreviewPlaying(): Boolean {
        return try {
            wakeUpPreviewPlayer?.isPlaying == true
        } catch (_: Exception) {
            false
        }
    }

    private fun startWakeUpPreview(onFinished: () -> Unit) {
        stopWakeUpPreview()
        try {
            val track = WakeUpMusicManager.getCurrentTrack(this)
            val mp = MediaPlayer().apply {
                if (track != null && File(track.filePath).isFile) {
                    setDataSource(track.filePath)
                } else {
                    val afd = resources.openRawResourceFd(R.raw.motivation_track)
                    setDataSource(afd.fileDescriptor, afd.startOffset, afd.length)
                    afd.close()
                }
                setOnCompletionListener {
                    stopWakeUpPreview()
                    onFinished()
                }
                setOnErrorListener { _, _, _ ->
                    stopWakeUpPreview()
                    onFinished()
                    true
                }
                prepare()
                start()
            }
            wakeUpPreviewPlayer = mp
        } catch (e: Exception) {
            Log.e("WakeUpMusic", "Error starting music preview: ${e.message}", e)
            Toast.makeText(this, "Playback error: ${e.message}", Toast.LENGTH_SHORT).show()
            stopWakeUpPreview()
            onFinished()
        }
    }

    private fun stopWakeUpPreview() {
        try {
            wakeUpPreviewPlayer?.let {
                if (it.isPlaying) it.stop()
                it.release()
            }
        } catch (_: Exception) {}
        wakeUpPreviewPlayer = null
    }

    private fun showWakeUpMusicSettingsDialog() {
        var dialogRef: AlertDialog? = null

        val scroll = ScrollView(this)
        val container = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(18), dp(20), dp(18))
            background = surfaceBg(CLR_MODAL, 20, CLR_BORDER, 1)
        }
        scroll.addView(container)

        fun populateDialog() {
            container.removeAllViews()

            val track = WakeUpMusicManager.getCurrentTrack(this)
            val isLocked = WakeUpMusicManager.isSelectionLocked(this)

            // Header
            container.addView(TextView(this).apply {
                text = "🎵 WAKE-UP MUSIC CONFIGURATION"
                textSize = 15f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                letterSpacing = 0.04f
            })
            container.addView(TextView(this).apply {
                text = "Plays through verified Bluetooth earbuds during Wake-Up Step 3. Changes are locked until the 1st of next calendar month to prevent breaking discipline habits."
                textSize = 11f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(4)
                    bottomMargin = dp(14)
                }
            })

            // Current Track Card
            val trackCard = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                background = surfaceBg(CLR_SURFACE_LOW, 14, CLR_BORDER, 1)
                setPadding(dp(14), dp(12), dp(14), dp(12))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(12)
                }
            }

            trackCard.addView(TextView(this).apply {
                text = "CURRENT TRACK SELECTION"
                textSize = 10f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_CYAN))
                letterSpacing = 0.06f
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(6)
                }
            })

            val displayTitle = track?.title ?: "Built-in Motivation Track"
            val displayFile = track?.originalFilename ?: "motivation_track.wav (Built-in Default)"
            val durationSec = if (track != null) track.durationMs / 1000 else 150
            val durMin = durationSec / 60
            val durRemSec = durationSec % 60
            val durText = String.format(Locale.US, "%d:%02d (%d sec)", durMin, durRemSec, durationSec)
            val formatText = track?.format ?: "WAV / Audio"
            val selectedDateText = track?.selectedAt?.takeIf { it.isNotBlank() } ?: "System Default"

            trackCard.addView(TextView(this).apply {
                text = displayTitle
                textSize = 14f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
            })

            trackCard.addView(TextView(this).apply {
                text = "File: $displayFile"
                textSize = 11f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(2)
                }
            })

            trackCard.addView(TextView(this).apply {
                text = "Duration: $durText • Format: $formatText"
                textSize = 11f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(2)
                }
            })

            trackCard.addView(TextView(this).apply {
                text = if (track != null) "● Verified & ready for playback" else "● Built-in fallback ready"
                textSize = 11f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_GREEN))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(4)
                }
            })

            trackCard.addView(TextView(this).apply {
                text = "Selected on: $selectedDateText"
                textSize = 10f
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(4)
                }
            })

            container.addView(trackCard)

            // Monthly Lock Card
            val lockCard = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                val borderCol = if (isLocked) CLR_AMBER else CLR_GREEN
                val bgCol = if (isLocked) "#1A1508" else "#0B1912"
                background = surfaceBg(bgCol, 14, borderCol, 1)
                setPadding(dp(14), dp(12), dp(14), dp(12))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(14)
                }
            }

            lockCard.addView(TextView(this).apply {
                text = if (isLocked) "🔒 MONTHLY SELECTION LOCK: ACTIVE" else "🔓 MONTHLY SELECTION LOCK: OPEN"
                textSize = 11f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(if (isLocked) CLR_AMBER else CLR_GREEN))
                letterSpacing = 0.04f
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(4)
                }
            })

            val lockUntilStr = track?.lockUntilDate?.takeIf { it.isNotBlank() }
                ?: WakeUpMusicManager.calculateNextMonthLockDateString(System.currentTimeMillis())

            lockCard.addView(TextView(this).apply {
                text = if (isLocked) {
                    "Next track change permitted: $lockUntilStr (00:00:00 IST).\nSelection is locked for the remainder of this calendar month to ensure morning discipline consistency."
                } else {
                    "Track selection is currently permitted. Note: Selecting a track will lock changes until 00:00:00 on the 1st of next month."
                }
                textSize = 11f
                setTextColor(Color.parseColor(if (isLocked) "#D4B483" else CLR_TEXT_SECONDARY))
            })

            container.addView(lockCard)

            // Buttons
            // 1. Select Music from Device
            val selectBtn = makePrimaryButton(
                label = if (isLocked) "🔒 SELECTION LOCKED UNTIL $lockUntilStr" else "📁 SELECT MUSIC FROM DEVICE",
                accentHex = if (isLocked) CLR_TEXT_DIM else CLR_BLUE,
                widthMatchParent = true
            ) {
                if (isLocked) {
                    haptic(1)
                    AlertDialog.Builder(this@MainActivity)
                        .setTitle("Monthly Selection Locked")
                        .setMessage("Wake-up music cannot be modified during the calendar month. Your next change is permitted on $lockUntilStr at 00:00:00 IST.\n\nThis monthly lock enforces commitment to your routine.")
                        .setPositiveButton("OK", null)
                        .show()
                } else {
                    launchWakeUpMusicPicker { uri ->
                        if (uri != null) {
                            Toast.makeText(this@MainActivity, "Importing & validating track...", Toast.LENGTH_SHORT).show()
                            Thread {
                                val result = WakeUpMusicManager.importMusicFromUri(this@MainActivity, uri)
                                runOnUiThread {
                                    when (result) {
                                        is WakeUpMusicManager.ImportResult.Success -> {
                                            haptic(1)
                                            Toast.makeText(
                                                this@MainActivity,
                                                "Track \"${result.trackInfo.title}\" verified and locked until ${result.trackInfo.lockUntilDate}! ✓",
                                                Toast.LENGTH_LONG
                                            ).show()
                                            populateDialog()
                                            refreshUi()
                                        }
                                        is WakeUpMusicManager.ImportResult.Failure -> {
                                            haptic(2)
                                            AlertDialog.Builder(this@MainActivity)
                                                .setTitle("Audio Import Failed")
                                                .setMessage("${result.error}\n\nExisting track selection was preserved.")
                                                .setPositiveButton("OK", null)
                                                .show()
                                        }
                                    }
                                }
                            }.start()
                        }
                    }
                }
            }.apply {
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(8)
                }
            }
            container.addView(selectBtn)

            // 2. Test Selected Music
            val isPlaying = isWakeUpPreviewPlaying()
            val testBtnLabel = if (isPlaying) "⏹ STOP TEST PLAYBACK" else "▶ TEST SELECTED MUSIC"
            val testBtnColor = if (isPlaying) CLR_AMBER else CLR_INDIGO

            val testBtn = makePrimaryButton(
                label = testBtnLabel,
                accentHex = testBtnColor,
                widthMatchParent = true
            ) {
                haptic(1)
                if (isWakeUpPreviewPlaying()) {
                    stopWakeUpPreview()
                    populateDialog()
                } else {
                    startWakeUpPreview {
                        runOnUiThread { populateDialog() }
                    }
                    populateDialog()
                }
            }.apply {
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(14)
                }
            }
            container.addView(testBtn)

            // Close button
            val closeBtn = makeSecondaryButton("CLOSE", CLR_TEXT_DIM) {
                stopWakeUpPreview()
                dialogRef?.dismiss()
            }.apply {
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            container.addView(closeBtn)
        }

        populateDialog()

        dialogRef = AlertDialog.Builder(this)
            .setView(scroll)
            .create()
        dialogRef.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
        dialogRef.setOnDismissListener {
            stopWakeUpPreview()
        }
        dialogRef.show()
    }

    private fun buildTravelPrebookingSection(): View {
        val today = db.nowDate()
        val upcomingBookings = db.getUpcomingTravelBookings(today)
        val isTablet = isWideLayout()

        val card = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            val pad = dp(if (isTablet) 14 else 12)
            setPadding(pad, pad, pad, pad)
            background = surfaceBg(CLR_SURFACE, 16, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
        }

        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        }

        val iconBadge = FrameLayout(this).apply {
            layoutParams = LinearLayout.LayoutParams(dp(32), dp(32)).apply { rightMargin = dp(10) }
            background = surfaceBg(CLR_ELEVATED, 10, CLR_BORDER, 1)
        }
        val iconTv = TextView(this).apply {
            text = "📅"
            textSize = 16f
            gravity = Gravity.CENTER
            layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)
        }
        iconBadge.addView(iconTv)
        headerRow.addView(iconBadge)

        val titleCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        titleCol.addView(TextView(this).apply {
            text = "UPCOMING TRAVEL"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_PURPLE))
            letterSpacing = 0.05f
        })
        titleCol.addView(TextView(this).apply {
            text = "Travel Pre-booking"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
        })
        headerRow.addView(titleCol)

        val restriction = db.getTravelPrebookingRestriction()
        val btnPrebook = TextView(this).apply {
            text = if (restriction.isRestricted) "LOCKED" else "+ PRE-BOOK"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (restriction.isRestricted) CLR_TEXT_DIM else "#070A0C"))
            background = surfaceBg(if (restriction.isRestricted) CLR_SURFACE_LOW else CLR_PURPLE, 8)
            setPadding(dp(12), dp(6), dp(12), dp(6))
            applySpringTouch {
                if (restriction.isRestricted) {
                    Toast.makeText(this@MainActivity, "Travel pre-booking is locked until ${restriction.lockUntilDateStr} (3 consecutive missed travel proofs).", Toast.LENGTH_LONG).show()
                } else {
                    showPrebookTravelDialog()
                }
            }
        }
        headerRow.addView(btnPrebook)
        card.addView(headerRow)

        if (restriction.isRestricted) {
            val lockNotice = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                background = surfaceBg("#2A1215", 10, CLR_RED, 1)
                setPadding(dp(12), dp(10), dp(12), dp(10))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(8)
                }
            }
            lockNotice.addView(TextView(this).apply {
                text = "⚠️ PRE-BOOKING LOCKED UNTIL ${restriction.lockUntilDateStr.uppercase(Locale.US)}"
                textSize = 11f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_RED))
            })
            lockNotice.addView(TextView(this).apply {
                val dates = restriction.failedDates.joinToString(", ")
                text = "Pre-booking is disabled for 3 calendar months due to 3 consecutive missed travel proof submissions ($dates)."
                textSize = 10.5f
                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(2)
                }
            })
            card.addView(lockNotice)
        }

        if (upcomingBookings.isEmpty()) {
            val emptyBox = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                setPadding(dp(14), dp(12), dp(14), dp(12))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            emptyBox.addView(TextView(this).apply {
                text = "No upcoming pre-booked travel"
                textSize = 12f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            })
            emptyBox.addView(TextView(this).apply {
                text = "Pre-booking opens at 12:00 AM two days before departure and closes 6 hours before departure time."
                textSize = 11f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(2)
                }
            })
            card.addView(emptyBox)
        } else {
            upcomingBookings.forEach { booking ->
                val row = LinearLayout(this).apply {
                    orientation = LinearLayout.VERTICAL
                    background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                    setPadding(dp(12), dp(10), dp(12), dp(10))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        bottomMargin = dp(6)
                    }
                }

                val rowHeader = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.CENTER_VERTICAL
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
                }

                val details = runCatching { JSONObject(booking.detailsJson) }.getOrDefault(JSONObject())
                val departureTime = details.optString("departure_time", booking.scheduledTime)
                val desc = details.optString("prebooked_description", details.optString("description", booking.title))

                rowHeader.addView(TextView(this).apply {
                    text = "🚗 ${booking.date} · $departureTime"
                    textSize = 12f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.WHITE)
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                })

                val statusPill = TextView(this).apply {
                    text = "PRE-BOOKED"
                    textSize = 9f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(CLR_PURPLE))
                    background = surfaceBg("#1E102A", 6, CLR_PURPLE, 1)
                    setPadding(dp(6), dp(2), dp(6), dp(2))
                }
                rowHeader.addView(statusPill)
                row.addView(rowHeader)

                if (desc.isNotBlank()) {
                    row.addView(TextView(this).apply {
                        text = desc
                        textSize = 11f
                        setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                            topMargin = dp(4)
                        }
                    })
                }
                card.addView(row)
            }
        }

        return card
    }

    private fun buildEmergencyTravelSection(): View {
        val isTablet = isWideLayout()
        val card = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            val pad = dp(if (isTablet) 14 else 12)
            setPadding(pad, pad, pad, pad)
            background = surfaceBg(CLR_SURFACE, 16, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
        }

        // Header Row
        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        }
        val iconBadge = FrameLayout(this).apply {
            layoutParams = LinearLayout.LayoutParams(dp(32), dp(32)).apply { rightMargin = dp(10) }
            background = surfaceBg(CLR_ELEVATED, 10, CLR_BORDER, 1)
        }
        iconBadge.addView(TextView(this).apply {
            text = "🚨"
            textSize = 16f
            gravity = Gravity.CENTER
            layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)
        })
        headerRow.addView(iconBadge)

        val titleCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        titleCol.addView(TextView(this).apply {
            text = "EMERGENCY TRAVEL BOOK"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_AMBER))
            letterSpacing = 0.05f
        })
        titleCol.addView(TextView(this).apply {
            text = "Immediate Travel & Approval"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
        })
        headerRow.addView(titleCol)

        val travelHearts = db.getTravelHearts()
        val btnRequest = TextView(this).apply {
            text = if (travelHearts <= 0) "LOCKED" else "+ REQUEST TRAVEL"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (travelHearts <= 0) CLR_TEXT_DIM else "#070A0C"))
            background = surfaceBg(if (travelHearts <= 0) CLR_SURFACE_LOW else CLR_AMBER, 8)
            setPadding(dp(12), dp(6), dp(12), dp(6))
            applySpringTouch {
                if (travelHearts <= 0) {
                    Toast.makeText(this@MainActivity, "Emergency Travel is locked: 0 hearts remaining. Reset by administrator to restore.", Toast.LENGTH_LONG).show()
                } else {
                    showEmergencyTravelBookingDialog()
                }
            }
        }
        headerRow.addView(btnRequest)
        card.addView(headerRow)

        // Travel Accountability Heart Badge Row
        val heartsRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(12), dp(8), dp(12), dp(8))
            background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        }
        val heartsTv = TextView(this).apply {
            text = ThreeHeartAccountabilityEngine.formatHeartsBadge(travelHearts, "TRAVEL ACCOUNTABILITY")
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(when (travelHearts) {
                3 -> CLR_GREEN
                2 -> CLR_CYAN
                1 -> CLR_AMBER
                else -> CLR_RED
            }))
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        heartsRow.addView(heartsTv)
        if (travelHearts <= 0) {
            val btnReset = TextView(this).apply {
                text = "ADMIN RESET"
                textSize = 10f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_RED))
                background = surfaceBg("#331010", 6, CLR_RED, 1)
                setPadding(dp(8), dp(4), dp(8), dp(4))
                applySpringTouch {
                    showAdminResetHeartsDialog("TRAVEL")
                }
            }
            heartsRow.addView(btnReset)
        }
        card.addView(heartsRow)

        // Check deadlines for state transitions & heart deductions
        db.checkEmergencyTravelDeadlines()

        val nowMs = db.authoritativeNowMs()
        val today = db.nowDate()
        val latestRequest = db.getLatestEmergencyTravel(today)

        if (latestRequest == null) {
            val emptyBox = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                setPadding(dp(14), dp(12), dp(14), dp(12))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            emptyBox.addView(TextView(this).apply {
                text = "No emergency travel requests today"
                textSize = 12f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            })
            emptyBox.addView(TextView(this).apply {
                text = "Request an emergency travel slot shortly before departure (e.g. 5:40 PM for 6:00 PM departure). Requires administrator review before departure."
                textSize = 11f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(2)
                }
            })
            card.addView(emptyBox)
        } else {
            val reqCard = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                background = surfaceBg(CLR_SURFACE_LOW, 12, CLR_BORDER, 1)
                setPadding(dp(14), dp(12), dp(14), dp(12))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }

            val statusRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(6)
                }
            }
            val titleText = when (latestRequest.travelType) {
                "CAR_RIDE" -> "🚗 Car ride"
                "AUTO" -> "🛺 Auto"
                "BUS" -> "🚌 Bus"
                "TRAIN" -> "🚆 Train"
                "FLIGHT" -> "✈️ Flight"
                else -> "🚘 Other Travel"
            }
            statusRow.addView(TextView(this).apply {
                text = "$titleText · ${latestRequest.departureTime} – ${latestRequest.returnTime}"
                textSize = 13f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            })

            val statusColor = when (latestRequest.status) {
                EmergencyTravelRules.Status.ACTIVE -> CLR_GREEN
                EmergencyTravelRules.Status.APPROVED -> CLR_GREEN
                EmergencyTravelRules.Status.EVIDENCE_VERIFIED -> CLR_GREEN
                EmergencyTravelRules.Status.SCHEDULED -> CLR_CYAN
                EmergencyTravelRules.Status.AWAITING_APPROVAL -> CLR_AMBER
                EmergencyTravelRules.Status.AWAITING_EVIDENCE -> CLR_AMBER
                EmergencyTravelRules.Status.EVIDENCE_SUBMITTED -> CLR_CYAN
                EmergencyTravelRules.Status.REJECTED -> CLR_RED
                EmergencyTravelRules.Status.EXPIRED -> CLR_RED
                else -> CLR_TEXT_SECONDARY
            }
            statusRow.addView(designStatusPill(latestRequest.status, statusColor))
            reqCard.addView(statusRow)

            reqCard.addView(TextView(this).apply {
                text = "Purpose: ${latestRequest.purpose}" + (if (!latestRequest.destinationLocation.isNullOrBlank()) " • Destination: ${latestRequest.destinationLocation}" else "")
                textSize = 11.5f
                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(6)
                }
            })

            when (latestRequest.status) {
                EmergencyTravelRules.Status.ACTIVE -> {
                    val activeBanner = TextView(this).apply {
                        text = "🚨 EMERGENCY TRAVEL ACTIVE"
                        textSize = 13.5f
                        setTypeface(typeface, Typeface.BOLD)
                        setTextColor(Color.parseColor(CLR_GREEN))
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                            topMargin = dp(4)
                            bottomMargin = dp(4)
                        }
                    }
                    reqCard.addView(activeBanner)

                    val timerTv = TextView(this).apply {
                        textSize = 15f
                        setTypeface(Typeface.MONOSPACE, Typeface.BOLD)
                        setTextColor(Color.parseColor(CLR_GREEN))
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                            bottomMargin = dp(6)
                        }
                    }
                    reqCard.addView(timerTv)

                    val countdownRunnable = object : Runnable {
                        override fun run() {
                            val cur = db.authoritativeNowMs()
                            val rem = (latestRequest.returnMs - cur).coerceAtLeast(0L)
                            if (rem <= 0L) {
                                timerTv.text = "Travel duration completed • Awaiting evidence"
                                timerTv.setTextColor(Color.parseColor(CLR_AMBER))
                                db.completeEmergencyTravel(latestRequest.requestId)
                                refreshUi()
                            } else {
                                val secs = rem / 1000
                                val hh = secs / 3600
                                val mm = (secs % 3600) / 60
                                val ss = secs % 60
                                timerTv.text = String.format(Locale.US, "Remaining: %02d:%02d:%02d (Until %s)", hh, mm, ss, latestRequest.returnTime)
                                uiHandler.postDelayed(this, 1000L)
                            }
                        }
                    }
                    uiHandler.post(countdownRunnable)

                    val btnRow = LinearLayout(this).apply {
                        orientation = LinearLayout.HORIZONTAL
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                            topMargin = dp(6)
                        }
                    }
                    val btnProof = makePrimaryButton("SUBMIT PROOF", CLR_GREEN, widthMatchParent = false) {
                        showUnifiedEvidenceSubmissionDialog("TRAVEL", latestRequest.requestId)
                    }
                    val btnReturn = makeSecondaryButton("FINISH EARLY", CLR_AMBER) {
                        db.completeEmergencyTravel(latestRequest.requestId)
                        Toast.makeText(this@MainActivity, "Emergency travel finished early. Please submit travel evidence.", Toast.LENGTH_SHORT).show()
                        refreshUi()
                    }
                    btnRow.addView(btnProof)
                    btnRow.addView(btnReturn)
                    reqCard.addView(btnRow)
                }
                EmergencyTravelRules.Status.AWAITING_APPROVAL -> {
                    val auditMsg = if (latestRequest.isMateriallyModified) "⚠️ Modified schedule requires renewed administrator approval."
                    else "⏳ Request submitted. Awaiting administrator approval before departure."
                    reqCard.addView(TextView(this).apply {
                        text = auditMsg
                        textSize = 11f
                        setTextColor(Color.parseColor(CLR_AMBER))
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                            bottomMargin = dp(8)
                        }
                    })
                    val btnRow = LinearLayout(this).apply {
                        orientation = LinearLayout.HORIZONTAL
                    }
                    val btnAdmin = makePrimaryButton("ADMIN APPROVE", CLR_AMBER, widthMatchParent = false) {
                        showAdminApprovalDialog(latestRequest)
                    }
                    val btnModify = makeSecondaryButton("MODIFY SLOT", CLR_CYAN) {
                        showEmergencyTravelBookingDialog(latestRequest)
                    }
                    btnRow.addView(btnAdmin)
                    btnRow.addView(btnModify)
                    reqCard.addView(btnRow)
                }
                EmergencyTravelRules.Status.APPROVED, EmergencyTravelRules.Status.SCHEDULED -> {
                    val availableStartMs = latestRequest.departureMs - (5 * 60 * 1000L)
                    val canActivateNow = nowMs >= availableStartMs && nowMs < latestRequest.returnMs
                    val btnRow = LinearLayout(this).apply {
                        orientation = LinearLayout.HORIZONTAL
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                            topMargin = dp(4)
                        }
                    }
                    val btnActivate = makePrimaryButton(
                        if (canActivateNow) "ACTIVATE TRAVEL MODE" else "OPENS 5 MIN BEFORE",
                        if (canActivateNow) CLR_GREEN else CLR_TEXT_DIM,
                        widthMatchParent = false
                    ) {
                        if (canActivateNow) {
                            val (success, msg) = db.activateEmergencyTravel(latestRequest.requestId, context = this@MainActivity)
                            Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show()
                            refreshUi()
                        } else {
                            val sdf = SimpleDateFormat("h:mm a", Locale.US).apply { timeZone = TimeZone.getTimeZone(db.scheduleTimezone()) }
                            Toast.makeText(this@MainActivity, "Activation opens at ${sdf.format(Date(availableStartMs))} (5 minutes before departure).", Toast.LENGTH_SHORT).show()
                        }
                    }
                    val btnModify = makeSecondaryButton("MODIFY SLOT", CLR_CYAN) {
                        showEmergencyTravelBookingDialog(latestRequest)
                    }
                    btnRow.addView(btnActivate)
                    btnRow.addView(btnModify)
                    reqCard.addView(btnRow)
                }
                EmergencyTravelRules.Status.AWAITING_EVIDENCE -> {
                    val sdf = SimpleDateFormat("h:mm a", Locale.US).apply { timeZone = TimeZone.getTimeZone(db.scheduleTimezone()) }
                    reqCard.addView(TextView(this).apply {
                        text = "⚠️ Travel ended. Submit proof by ${sdf.format(Date(latestRequest.evidenceDeadlineMs))} to preserve your 3 hearts."
                        textSize = 11f
                        setTextColor(Color.parseColor(CLR_AMBER))
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                            bottomMargin = dp(8)
                        }
                    })
                    val btnSubmit = makePrimaryButton("SUBMIT EVIDENCE", CLR_GREEN, widthMatchParent = false) {
                        showUnifiedEvidenceSubmissionDialog("TRAVEL", latestRequest.requestId)
                    }
                    reqCard.addView(btnSubmit)
                }
                EmergencyTravelRules.Status.EVIDENCE_VERIFIED -> {
                    reqCard.addView(TextView(this).apply {
                        text = "✓ Travel evidence verified! All 3 hearts preserved in Travel Accountability."
                        textSize = 11.5f
                        setTypeface(typeface, Typeface.BOLD)
                        setTextColor(Color.parseColor(CLR_GREEN))
                    })
                }
                EmergencyTravelRules.Status.REJECTED -> {
                    reqCard.addView(TextView(this).apply {
                        text = "✕ Request was rejected: ${latestRequest.approvalReason ?: "Not approved"}"
                        textSize = 11f
                        setTextColor(Color.parseColor(CLR_RED))
                    })
                }
                EmergencyTravelRules.Status.EXPIRED -> {
                    reqCard.addView(TextView(this).apply {
                        text = "✕ Evidence deadline passed without submission. Exactly 1 heart deducted."
                        textSize = 11f
                        setTextColor(Color.parseColor(CLR_RED))
                    })
                }
            }
            card.addView(reqCard)
        }

        return card
    }

    private fun showEmergencyTravelBookingDialog(existingRequest: EmergencyTravelRules.EmergencyTravelRequest? = null) {
        val tz = TimeZone.getTimeZone(db.scheduleTimezone())
        val dateFmt = SimpleDateFormat("yyyy-MM-dd", Locale.US).apply { timeZone = tz }
        val timeFmt = SimpleDateFormat("HH:mm", Locale.US).apply { timeZone = tz }
        val nowCal = Calendar.getInstance(tz)

        // Default departure: 20 minutes from now (advance booking shortly before departure)
        val defaultDepCal = (nowCal.clone() as Calendar).apply { add(Calendar.MINUTE, 20) }
        val defaultRetCal = (defaultDepCal.clone() as Calendar).apply { add(Calendar.HOUR_OF_DAY, 2) }

        var selectedDate = existingRequest?.travelDate ?: dateFmt.format(nowCal.time)
        var selectedDepTime = existingRequest?.departureTime ?: timeFmt.format(defaultDepCal.time)
        var selectedRetTime = existingRequest?.returnTime ?: timeFmt.format(defaultRetCal.time)
        var selectedType = existingRequest?.travelType ?: "CAR_RIDE"

        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(18), dp(20), dp(18))
            background = surfaceBg(CLR_MODAL, 18, CLR_BORDER, 1)
        }

        val titleTv = TextView(this).apply {
            text = if (existingRequest != null) "✏️ MODIFY EMERGENCY TRAVEL" else "🚨 EMERGENCY TRAVEL BOOK"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_AMBER))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(4)
            }
        }
        dialogView.addView(titleTv)

        val heartsTv = TextView(this).apply {
            text = ThreeHeartAccountabilityEngine.formatHeartsBadge(db.getTravelHearts(), "TRAVEL ACCOUNTABILITY")
            textSize = 11.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_GREEN))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(12)
            }
        }
        dialogView.addView(heartsTv)

        // Departure Row
        val depRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
            setPadding(dp(12), dp(10), dp(12), dp(10))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }
        val depLabel = TextView(this).apply {
            text = "⏰ Departure: $selectedDepTime"
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        val btnPickDep = TextView(this).apply {
            text = "Select Time"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            background = surfaceBg(CLR_ELEVATED, 6, CLR_BORDER, 1)
            setPadding(dp(10), dp(5), dp(10), dp(5))
            setOnClickListener {
                val parts = selectedDepTime.split(":")
                val h = parts.getOrNull(0)?.toIntOrNull() ?: 18
                val m = parts.getOrNull(1)?.toIntOrNull() ?: 0
                android.app.TimePickerDialog(this@MainActivity, { _, hourOfDay, minute ->
                    selectedDepTime = String.format(Locale.US, "%02d:%02d", hourOfDay, minute)
                    depLabel.text = "⏰ Departure: $selectedDepTime"
                }, h, m, true).show()
            }
        }
        depRow.addView(depLabel)
        depRow.addView(btnPickDep)
        dialogView.addView(depRow)

        // Return Row
        val retRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
            setPadding(dp(12), dp(10), dp(12), dp(10))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        }
        val retLabel = TextView(this).apply {
            text = "⏰ Expected Return: $selectedRetTime"
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        val btnPickRet = TextView(this).apply {
            text = "Select Time"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            background = surfaceBg(CLR_ELEVATED, 6, CLR_BORDER, 1)
            setPadding(dp(10), dp(5), dp(10), dp(5))
            setOnClickListener {
                val parts = selectedRetTime.split(":")
                val h = parts.getOrNull(0)?.toIntOrNull() ?: 20
                val m = parts.getOrNull(1)?.toIntOrNull() ?: 0
                android.app.TimePickerDialog(this@MainActivity, { _, hourOfDay, minute ->
                    selectedRetTime = String.format(Locale.US, "%02d:%02d", hourOfDay, minute)
                    retLabel.text = "⏰ Expected Return: $selectedRetTime"
                }, h, m, true).show()
            }
        }
        retRow.addView(retLabel)
        retRow.addView(btnPickRet)
        dialogView.addView(retRow)

        // Travel Type Selection Chips
        dialogView.addView(TextView(this).apply {
            text = "Travel Type"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(4)
            }
        })
        val typeRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        }
        val types = listOf("CAR_RIDE" to "Car ride", "AUTO" to "Auto", "BUS" to "Bus", "TRAIN" to "Train", "OTHER" to "Other")
        val chipViews = mutableListOf<TextView>()
        fun updateTypeChips() {
            chipViews.forEachIndexed { idx, tv ->
                val code = types[idx].first
                val isSel = code == selectedType
                tv.setTextColor(Color.parseColor(if (isSel) "#070A0C" else CLR_TEXT_PRIMARY))
                tv.background = surfaceBg(if (isSel) CLR_AMBER else CLR_SURFACE_LOW, 8, if (isSel) CLR_AMBER else CLR_BORDER, 1)
            }
        }
        types.forEach { (code, label) ->
            val chip = TextView(this).apply {
                text = label
                textSize = 11f
                setTypeface(typeface, Typeface.BOLD)
                gravity = Gravity.CENTER
                setPadding(dp(10), dp(6), dp(10), dp(6))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                    rightMargin = dp(4)
                }
                setOnClickListener {
                    selectedType = code
                    updateTypeChips()
                }
            }
            chipViews.add(chip)
            typeRow.addView(chip)
        }
        updateTypeChips()
        dialogView.addView(typeRow)

        // Purpose Input
        dialogView.addView(TextView(this).apply {
            text = "Travel Purpose (Required)"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(4)
            }
        })
        val purposeInput = android.widget.EditText(this).apply {
            hint = "e.g. Urgent hospital appointment, family emergency"
            setText(existingRequest?.purpose ?: "")
            setTextColor(Color.WHITE)
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            background = surfaceBg(CLR_SURFACE_LOW, 8, CLR_BORDER, 1)
            setPadding(dp(10), dp(8), dp(10), dp(8))
            textSize = 12f
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(14)
            }
        }
        dialogView.addView(purposeInput)

        val scroll = ScrollView(this).apply { addView(dialogView) }
        val dialog = AlertDialog.Builder(this)
            .setView(scroll)
            .create()

        val btnActionRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        val btnSubmit = makePrimaryButton(
            if (existingRequest != null) "UPDATE TRAVEL SLOT" else "REQUEST APPROVAL",
            CLR_AMBER,
            widthMatchParent = false
        ) {
            val purpose = purposeInput.text.toString().trim()
            if (purpose.length < 3) {
                Toast.makeText(this@MainActivity, "Please enter a valid travel purpose (min 3 characters).", Toast.LENGTH_SHORT).show()
                return@makePrimaryButton
            }
            if (existingRequest != null) {
                val (updated, msg) = db.modifyEmergencyTravelSlot(
                    requestId = existingRequest.requestId,
                    newDeparture = selectedDepTime,
                    newReturn = selectedRetTime,
                    reason = "User modified travel slot ($purpose)",
                    context = this@MainActivity
                )
                Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show()
                if (updated != null) dialog.dismiss()
            } else {
                val (created, msg) = db.createEmergencyTravelRequest(
                    travelDate = selectedDate,
                    departureTime = selectedDepTime,
                    returnTime = selectedRetTime,
                    purpose = purpose,
                    travelType = selectedType,
                    context = this@MainActivity
                )
                Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show()
                if (created != null) dialog.dismiss()
            }
            refreshUi()
        }
        val btnCancel = makeSecondaryButton("CANCEL", CLR_TEXT_DIM) {
            dialog.dismiss()
        }
        btnActionRow.addView(btnSubmit)
        btnActionRow.addView(btnCancel)
        dialogView.addView(btnActionRow)

        dialog.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
        dialog.show()
    }

    private fun showAdminApprovalDialog(request: EmergencyTravelRules.EmergencyTravelRequest) {
        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(18), dp(20), dp(18))
            background = surfaceBg(CLR_MODAL, 18, CLR_BORDER, 1)
