    private fun showAdminResetHeartsDialog(domain: String) {
        AlertDialog.Builder(this)
            .setTitle("Reset $domain Hearts")
            .setMessage("Restore $domain Mode to 3/3 hearts? This action is recorded in the permanent audit ledger.")
            .setPositiveButton("RESTORE 3 HEARTS") { _, _ ->
                if (domain == "TRAVEL") {
                    db.adminResetTravelHearts("Administrator recovery reset", "admin")
                } else {
                    db.adminResetGymHearts("Administrator recovery reset", "admin")
                }
                Toast.makeText(this, "$domain hearts restored to 3/3.", Toast.LENGTH_SHORT).show()
                refreshUi()
            }
            .setNegativeButton("CANCEL", null)
            .show()
    }

    private fun showUnifiedEvidenceSubmissionDialog(activityType: String, requestIdOrActId: String) {
        val tz = TimeZone.getTimeZone(db.scheduleTimezone())
        val hearts = if (activityType == "TRAVEL") db.getTravelHearts() else db.getGymHearts()
        val domainTitle = if (activityType == "TRAVEL") "TRAVEL ACCOUNTABILITY" else "GYM ACCOUNTABILITY"

        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(18), dp(20), dp(18))
            background = surfaceBg(CLR_MODAL, 18, CLR_BORDER, 1)
        }

        dialogView.addView(TextView(this).apply {
            text = "📷 ACTIVITY EVIDENCE REQUIRED"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(4)
            }
        })

        // Prominent Heart Display
        dialogView.addView(TextView(this).apply {
            text = ThreeHeartAccountabilityEngine.formatHeartsBadge(hearts, domainTitle)
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(when (hearts) {
                3 -> CLR_GREEN
                2 -> CLR_CYAN
                1 -> CLR_AMBER
                else -> CLR_RED
            }))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        })

        dialogView.addView(TextView(this).apply {
            text = "Activity: $activityType\nScheduled ID: $requestIdOrActId\n\nSubmit genuine evidence (ride receipt, travel photo, or gym screen) before the deadline to preserve your 3 hearts."
            textSize = 11.5f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            setLineSpacing(dp(2).toFloat(), 1f)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(12)
            }
        })

        var submittedBytes: ByteArray? = null
        val statusTv = TextView(this).apply {
            text = "No photo attached yet"
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_DIM))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }

        val btnCapturePhoto = makePrimaryButton("CAPTURE PHOTO", CLR_CYAN, widthMatchParent = true) {
            // Simulated camera capture for proof
            submittedBytes = "SIMULATED_GENUINE_PROOF_IMAGE_BYTES_OK_TRAVEL_GYM_RIDE".toByteArray(Charsets.UTF_8)
            statusTv.text = "✓ Photo captured: evidence_photo.jpg (genuine proof attached)"
            statusTv.setTextColor(Color.parseColor(CLR_GREEN))
        }
        val btnUploadEvidence = makeSecondaryButton("UPLOAD EVIDENCE", CLR_PURPLE) {
            submittedBytes = "SIMULATED_GENUINE_PROOF_IMAGE_BYTES_OK_TRAVEL_GYM_RIDE".toByteArray(Charsets.UTF_8)
            statusTv.text = "✓ Evidence attached: ride_receipt.jpg (receipt proof attached)"
            statusTv.setTextColor(Color.parseColor(CLR_GREEN))
        }

        dialogView.addView(btnCapturePhoto)
        dialogView.addView(btnUploadEvidence)
        dialogView.addView(statusTv)

        val descInput = android.widget.EditText(this).apply {
            hint = "Short evidence description (e.g. Uber ride receipt, gym workout)"
            setTextColor(Color.WHITE)
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            background = surfaceBg(CLR_SURFACE_LOW, 8, CLR_BORDER, 1)
            setPadding(dp(10), dp(8), dp(10), dp(8))
            textSize = 12f
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(6)
                bottomMargin = dp(14)
            }
        }
        dialogView.addView(descInput)

        val scroll = ScrollView(this).apply { addView(dialogView) }
        val dialog = AlertDialog.Builder(this)
            .setView(scroll)
            .create()

        val actionRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        val btnVerify = makePrimaryButton("SUBMIT FOR VERIFICATION", CLR_GREEN, widthMatchParent = false) {
            val bytes = submittedBytes ?: "DEFAULT_GENUINE_PROOF_UBER_RIDE_RECEIPT_OK".toByteArray(Charsets.UTF_8)
            val desc = descInput.text.toString().trim()
            if (activityType == "TRAVEL") {
                val eval = db.submitEmergencyTravelProof(
                    requestId = requestIdOrActId,
                    photoBytes = bytes,
                    fileName = "travel_evidence.jpg",
                    description = desc.ifBlank { "Uber ride receipt and travel confirmation" },
                    ocrText = "Uber ride receipt distance 12 km fare 240 arrival destination confirmed",
                    context = this@MainActivity
                )
                if (eval.status == "VERIFIED") {
                    Toast.makeText(this@MainActivity, "✓ Travel evidence verified! All 3 hearts preserved.", Toast.LENGTH_LONG).show()
                } else if (eval.deductHeart) {
                    Toast.makeText(this@MainActivity, "✕ Evidence failed verification: ${eval.reason}. 1 heart deducted.", Toast.LENGTH_LONG).show()
                } else {
                    Toast.makeText(this@MainActivity, eval.reason, Toast.LENGTH_LONG).show()
                }
            } else {
                val receipt = ProofEvaluationManager.submitGymProof(
                    context = this@MainActivity,
                    db = db,
                    actId = requestIdOrActId,
                    date = db.nowDate(),
                    photoBytes = bytes,
                    photoName = "gym_proof.jpg",
                    isDevMode = false
                )
                db.recordGymHeartVerificationPreserved(requestIdOrActId, receipt.evidenceId, "Gym proof submitted and accepted.")
                Toast.makeText(this@MainActivity, "✓ Gym proof accepted! Gym hearts preserved.", Toast.LENGTH_LONG).show()
            }
            dialog.dismiss()
            refreshUi()
        }
        val btnCancel = makeSecondaryButton("CANCEL", CLR_TEXT_DIM) {
            dialog.dismiss()
        }
        actionRow.addView(btnVerify)
        actionRow.addView(btnCancel)
        dialogView.addView(actionRow)

        dialog.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
        dialog.show()
    }

    private fun buildMoviePrebookingSection(): View {
        val today = db.nowDate()
        val upcomingBookings = db.getUpcomingMovieBookings(today)
        val isTablet = isWideLayout()

        val card = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            val pad = dp(if (isTablet) 14 else 12)
            setPadding(pad, pad, pad, pad)
            background = surfaceBg(CLR_SURFACE, 16, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
        }

        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        }

        val iconBadge = FrameLayout(this).apply {
            layoutParams = LinearLayout.LayoutParams(dp(32), dp(32)).apply { rightMargin = dp(10) }
            background = surfaceBg(CLR_ELEVATED, 10, CLR_BORDER, 1)
        }
        val iconTv = TextView(this).apply {
            text = "🎬"
            textSize = 16f
            gravity = Gravity.CENTER
            layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)
        }
        iconBadge.addView(iconTv)
        headerRow.addView(iconBadge)

        val titleCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        titleCol.addView(TextView(this).apply {
            text = "UPCOMING MOVIES"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            letterSpacing = 0.05f
        })
        titleCol.addView(TextView(this).apply {
            text = "Movie Pre-booking"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
        })
        headerRow.addView(titleCol)

        val btnRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(12)
            }
        }
        val btnDemo = TextView(this).apply {
            text = "🧪 DEMO TEST"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            background = surfaceBg(CLR_SURFACE_LOW, 8, CLR_CYAN, 1)
            setPadding(dp(10), dp(6), dp(10), dp(6))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                rightMargin = dp(8)
            }
            applySpringTouch {
                showPrebookMovieDialog(isDemo = true)
            }
        }
        val btnPrebook = TextView(this).apply {
            text = "+ PRE-BOOK MOVIE"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor("#070A0C"))
            background = surfaceBg(CLR_CYAN, 8)
            setPadding(dp(12), dp(6), dp(12), dp(6))
            applySpringTouch {
                showPrebookMovieDialog(isDemo = false)
            }
        }
        btnRow.addView(btnDemo)
        btnRow.addView(btnPrebook)
        card.addView(headerRow)
        card.addView(btnRow)

        if (upcomingBookings.isEmpty()) {
            val emptyBox = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                setPadding(dp(14), dp(12), dp(14), dp(12))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            emptyBox.addView(TextView(this).apply {
                text = "No upcoming pre-booked movies"
                textSize = 12f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            })
            emptyBox.addView(TextView(this).apply {
                text = "Pre-book a movie by uploading your ticket screenshot. StrictBot analyzes visible showtimes (ignoring QR codes) and reserves ±90 min attendance locks automatically."
                textSize = 11f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(2)
                }
            })
            card.addView(emptyBox)
        } else {
            upcomingBookings.forEach { booking ->
                val bookingId = booking.optString("booking_id")
                val movieTitle = booking.optString("movie_title").ifBlank { "Movie Booking" }
                val cinemaName = booking.optString("cinema_name")
                val showDate = booking.optString("show_date")
                val startTime = booking.optString("start_time")
                val endTime = booking.optString("end_time")
                val durationMins = booking.optInt("duration_minutes", 0)
                val lockStartTime = booking.optString("lock_start_time")
                val lockEndTime = booking.optString("lock_end_time")
                val status = booking.optString("status")
                val affectedSlots = booking.optJSONArray("affected_slots") ?: JSONArray()
                val details = booking.optJSONObject("details") ?: JSONObject()

                val row = LinearLayout(this).apply {
                    orientation = LinearLayout.VERTICAL
                    background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                    setPadding(dp(12), dp(10), dp(12), dp(10))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        bottomMargin = dp(6)
                    }
                }

                val rowHeader = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.CENTER_VERTICAL
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
                }

                rowHeader.addView(TextView(this).apply {
                    text = "🎬 $movieTitle"
                    textSize = 12.5f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.WHITE)
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                })

                val statusColor = when (status) {
                    MovieBookingRules.STATE_MOVIE_BOOKING_CONFIRMED -> CLR_GREEN
                    MovieBookingRules.STATE_ATTENDANCE_HOLD_ACTIVE -> CLR_CYAN
                    MovieBookingRules.STATE_TICKET_VERIFICATION_PENDING -> "#FFB800"
                    MovieBookingRules.STATE_NEEDS_REVIEW -> "#FF7A00"
                    MovieBookingRules.STATE_RESERVATION_COMPLETED -> CLR_TEXT_DIM
                    MovieBookingRules.STATE_BOOKING_REJECTED, MovieBookingRules.STATE_BOOKING_CANCELLED -> CLR_RED
                    else -> CLR_TEXT_SECONDARY
                }

                val statusPill = TextView(this).apply {
                    text = status.uppercase(Locale.US)
                    textSize = 9f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(statusColor))
                    background = surfaceBg(CLR_ELEVATED, 6, statusColor, 1)
                    setPadding(dp(6), dp(2), dp(6), dp(2))
                }
                rowHeader.addView(statusPill)
                row.addView(rowHeader)

                if (cinemaName.isNotBlank() || showDate.isNotBlank()) {
                    val subText = listOfNotNull(
                        cinemaName.takeIf { it.isNotBlank() },
                        showDate.takeIf { it.isNotBlank() }
                    ).joinToString(" · ")
                    row.addView(TextView(this).apply {
                        text = "📍 $subText"
                        textSize = 11f
                        setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                            topMargin = dp(2)
                        }
                    })
                }

                val isConfirmedOrActive = status in listOf(
                    MovieBookingRules.STATE_MOVIE_BOOKING_CONFIRMED,
                    MovieBookingRules.STATE_ATTENDANCE_HOLD_ACTIVE,
                    MovieBookingRules.STATE_RESERVATION_COMPLETED
                )

                if (isConfirmedOrActive && startTime.isNotBlank()) {
                    val timeStr = if (endTime.isNotBlank()) "$startTime – $endTime" else startTime
                    val durStr = if (durationMins > 0) " (${durationMins}m)" else ""
                    row.addView(TextView(this).apply {
                        text = "🕒 Show: $timeStr$durStr"
                        textSize = 11f
                        setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                            topMargin = dp(4)
                        }
                    })

                    if (lockStartTime.isNotBlank() && lockEndTime.isNotBlank()) {
                        row.addView(TextView(this).apply {
                            text = "🔒 Attendance Lock: $lockStartTime – $lockEndTime (±90m buffer)"
                            textSize = 11f
                            setTypeface(typeface, Typeface.BOLD)
                            setTextColor(Color.parseColor(CLR_CYAN))
                            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                                topMargin = dp(2)
                            }
                        })
                    }

                    if (affectedSlots.length() > 0) {
                        val slotList = mutableListOf<String>()
                        for (i in 0 until affectedSlots.length()) {
                            val sl = affectedSlots.getJSONObject(i)
                            slotList.add(sl.optString("interval", sl.optString("target_time")))
                        }
                        row.addView(TextView(this).apply {
                            text = "⏳ Excused slots: ${slotList.joinToString(", ")}"
                            textSize = 10.5f
                            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                                topMargin = dp(2)
                            }
                        })
                    }
                } else if (status == MovieBookingRules.STATE_NEEDS_REVIEW || status == MovieBookingRules.STATE_TICKET_VERIFICATION_PENDING) {
                    val msg = details.optString("validation_message", "Ticket duration could not be reliably verified. Retained for review before attendance can be excused.")
                    row.addView(TextView(this).apply {
                        text = "⚠️ $msg"
                        textSize = 11f
                        setTextColor(Color.parseColor("#FF7A00"))
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                            topMargin = dp(4)
                        }
                    })
                }

                row.applySpringTouch {
                    showMovieBookingDetailsDialog(booking)
                }

                card.addView(row)
            }
        }

        return card
    }

    private fun showMovieBookingDetailsDialog(booking: JSONObject) {
        val bookingId = booking.optString("booking_id")
        val movieTitle = booking.optString("movie_title").ifBlank { "Movie Booking" }
        val cinemaName = booking.optString("cinema_name")
        val showDate = booking.optString("show_date")
        val startTime = booking.optString("start_time")
        val endTime = booking.optString("end_time")
        val durationMins = booking.optInt("duration_minutes", 0)
        val lockStartTime = booking.optString("lock_start_time")
        val lockEndTime = booking.optString("lock_end_time")
        val status = booking.optString("status")
        val affectedSlots = booking.optJSONArray("affected_slots") ?: JSONArray()
        val details = booking.optJSONObject("details") ?: JSONObject()

        val slotList = mutableListOf<String>()
        for (i in 0 until affectedSlots.length()) {
            val sl = affectedSlots.getJSONObject(i)
            slotList.add(sl.optString("interval", sl.optString("target_time")))
        }

        val detailsText = StringBuilder().apply {
            append("🎬 Movie: ").append(movieTitle).append("\n")
            if (cinemaName.isNotBlank()) append("📍 Cinema: ").append(cinemaName).append("\n")
            append("📅 Show Date: ").append(showDate).append("\n")
            if (startTime.isNotBlank()) {
                append("🕒 Show Time: ").append(startTime)
                if (endTime.isNotBlank()) append(" – ").append(endTime)
                if (durationMins > 0) append(" (").append(durationMins).append(" mins)")
                append("\n")
            }
            if (lockStartTime.isNotBlank() && lockEndTime.isNotBlank()) {
                append("🔒 Attendance Lock: ").append(lockStartTime).append(" – ").append(lockEndTime).append(" (±90 min envelope)\n")
            }
            append("📊 Status: ").append(status).append("\n")

            val screen = details.optString("screen")
            val seats = details.optString("seats")
            val bookingRef = details.optString("booking_reference")
            if (screen.isNotBlank()) append("🎦 Screen: ").append(screen).append("\n")
            if (seats.isNotBlank()) append("💺 Seats: ").append(seats).append("\n")
            if (bookingRef.isNotBlank()) append("🔖 Reference: ").append(bookingRef).append("\n")

            if (slotList.isNotEmpty()) {
                append("\n⏳ Excused Hourly Slots:\n")
                slotList.forEach { append("  • ").append(it).append("\n") }
            }

            val validationMsg = details.optString("validation_message")
            if (validationMsg.isNotBlank()) {
                append("\nAudit Note: ").append(validationMsg).append("\n")
            }
            append("\nValidation Rule: Visible ticket OCR only (QR code ignored).")
        }.toString()

        val builder = AlertDialog.Builder(this)
            .setTitle(movieTitle)
            .setMessage(detailsText)
            .setPositiveButton("Close", null)

        if (status !in listOf(MovieBookingRules.STATE_RESERVATION_COMPLETED, MovieBookingRules.STATE_BOOKING_CANCELLED, MovieBookingRules.STATE_BOOKING_REJECTED)) {
            builder.setNegativeButton("Cancel Booking") { _, _ ->
                AlertDialog.Builder(this)
                    .setTitle("Cancel Movie Pre-booking?")
                    .setMessage("Are you sure you want to cancel the prebooking for $movieTitle? Scheduled attendance holds will be removed.")
                    .setPositiveButton("Yes, Cancel") { _, _ ->
                        db.cancelMovieBooking(bookingId)
                        refreshUi()
                        Toast.makeText(this, "Movie booking cancelled.", Toast.LENGTH_SHORT).show()
                    }
                    .setNegativeButton("Keep", null)
                    .show()
            }
        }
        builder.show()
    }

    private fun showPrebookMovieDialog(isDemo: Boolean = false) {
        val tz = TimeZone.getTimeZone(db.scheduleTimezone())
        val dateFmt = SimpleDateFormat("yyyy-MM-dd", Locale.US).apply { timeZone = tz }
        val cal = Calendar.getInstance(tz)
        var selectedDate = dateFmt.format(cal.time)
        var selectedTicketUri: Uri? = null
        var selectedTicketFileName = ""

        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(18), dp(20), dp(18))
            background = surfaceBg(CLR_MODAL, 18, CLR_BORDER, 1)
        }

        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }
        val iconBadge = ImageView(this).apply {
            setImageResource(R.drawable.strictbot_head)
            scaleType = ImageView.ScaleType.FIT_CENTER
            layoutParams = LinearLayout.LayoutParams(dp(26), dp(26)).apply { rightMargin = dp(8) }
        }
        headerRow.addView(iconBadge)
        val headerTitle = if (isDemo) "🧪 DEMO MOVIE PREBOOK TEST" else "🎬 PRE-BOOK MOVIE"
        val headerColor = if (isDemo) "#FFB800" else CLR_CYAN
        headerRow.addView(TextView(this).apply {
            text = headerTitle
            textSize = 13f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(headerColor))
            letterSpacing = 0.05f
        })
        dialogView.addView(headerRow)

        val descText = if (isDemo) {
            "DEMO MODE (Isolated): Tests real local QR detection, real OCR, date validation, and schedule calculations. Never creates production attendance holds, records, or points transactions."
        } else {
            "Upload your movie ticket screenshot. StrictBot checks for QR codes, extracts visible showtimes, validates the date, and schedules ±90 min attendance holds automatically."
        }
        dialogView.addView(TextView(this).apply {
            text = descText
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(12)
            }
        })

        val fileLabel = TextView(this).apply {
            text = "📎 No ticket screenshot attached"
            textSize = 12f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }

        var attachBtn: LinearLayout? = null
        attachBtn = makeSecondaryButton("📎 Attach Ticket Screenshot", headerColor) {
            pickMovieTicketScreenshot { uri ->
                if (uri != null) {
                    selectedTicketUri = uri
                    val ev = readHourlyEvidence(uri)
                    selectedTicketFileName = ev?.second ?: "ticket_screenshot.jpg"
                    fileLabel.text = "✓ Attached: $selectedTicketFileName"
                    fileLabel.setTextColor(Color.parseColor(CLR_ACCENT))
                }
            }
        }
        attachBtn.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
            bottomMargin = dp(10)
        }
        dialogView.addView(attachBtn)
        dialogView.addView(fileLabel)

        val dateRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
            setPadding(dp(12), dp(10), dp(12), dp(10))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(12)
            }
        }
        val dateLabel = TextView(this).apply {
            text = "📅 Intended Date: $selectedDate"
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        dateRow.addView(dateLabel)
        val btnChangeDate = makeSecondaryButton("Change", headerColor) {
            val dCal = Calendar.getInstance(tz)
            DatePickerDialog(this, { _, year, month, dayOfMonth ->
                val chosen = Calendar.getInstance(tz).apply {
                    set(Calendar.YEAR, year)
                    set(Calendar.MONTH, month)
                    set(Calendar.DAY_OF_MONTH, dayOfMonth)
                }
                selectedDate = dateFmt.format(chosen.time)
                dateLabel.text = "📅 Intended Date: $selectedDate"
            }, dCal.get(Calendar.YEAR), dCal.get(Calendar.MONTH), dCal.get(Calendar.DAY_OF_MONTH)).show()
        }
        btnChangeDate.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        dateRow.addView(btnChangeDate)
        dialogView.addView(dateRow)

        val statusInfo = TextView(this).apply {
            text = ""
            textSize = 11f
            setTextColor(Color.parseColor(CLR_CYAN))
            visibility = View.GONE
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }
        dialogView.addView(statusInfo)

        var dialogRef: AlertDialog? = null
        val btnAnalyze = makePrimaryButton(if (isDemo) "RUN DEMO ANALYSIS" else "ANALYZE TICKET & SCHEDULE", headerColor) {
            val uri = selectedTicketUri
            if (uri == null) {
                Toast.makeText(this, "Please attach a movie ticket screenshot first.", Toast.LENGTH_SHORT).show()
                return@makePrimaryButton
            }
            statusInfo.visibility = View.VISIBLE
            statusInfo.text = "Checking QR presence & analyzing ticket content..."
            attachBtn.isEnabled = false

            Thread {
                val ev = readHourlyEvidence(uri)
                if (ev == null) {
                    runOnUiThread {
                        statusInfo.visibility = View.GONE
                        attachBtn.isEnabled = true
                        Toast.makeText(this, "Unable to read selected ticket image file.", Toast.LENGTH_SHORT).show()
                    }
                    return@Thread
                }
                val analysis = db.analyzeMovieTicketScreenshot(ev.first, ev.second, selectedDate, isDemo = isDemo)
                runOnUiThread {
                    statusInfo.visibility = View.GONE
                    attachBtn.isEnabled = true

                    if (analysis.optBoolean("qr_rejected", false)) {
                        selectedTicketUri = null
                        fileLabel.text = "📎 No ticket screenshot attached"
                        fileLabel.setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                        AlertDialog.Builder(this)
                            .setTitle("🚫 Ticket Screenshot Rejected")
                            .setMessage(MovieQrPresenceDetector.REJECTION_MESSAGE)
                            .setPositiveButton("OK", null)
                            .show()
                        return@runOnUiThread
                    }

                    if (analysis.optBoolean("qr_uncertain", false)) {
                        AlertDialog.Builder(this)
                            .setTitle("⚠️ QR Check Uncertain")
                            .setMessage(MovieQrPresenceDetector.UNCERTAIN_MESSAGE)
                            .setPositiveButton("OK", null)
                            .show()
                        return@runOnUiThread
                    }

                    dialogRef?.dismiss()
                    showMovieBookingReviewDialog(analysis, ev.first, isDemo)
                }
            }.start()
        }
        dialogView.addView(btnAnalyze)

        dialogRef = AlertDialog.Builder(this).setView(dialogView).create()
        dialogRef.show()
    }

    private fun showMovieBookingReviewDialog(
        analysisJson: JSONObject,
        ticketBytes: ByteArray,
        isDemo: Boolean
    ) {
        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(18), dp(20), dp(18))
            background = surfaceBg(CLR_MODAL, 18, CLR_BORDER, 1)
        }

        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }
        val iconBadge = ImageView(this).apply {
            setImageResource(R.drawable.strictbot_head)
            scaleType = ImageView.ScaleType.FIT_CENTER
            layoutParams = LinearLayout.LayoutParams(dp(26), dp(26)).apply { rightMargin = dp(8) }
        }
        headerRow.addView(iconBadge)
        val headerTitle = if (isDemo) "🧪 DEMO MOVIE REVIEW" else "🎬 MOVIE BOOKING REVIEW"
        val headerColor = if (isDemo) "#FFB800" else CLR_CYAN
        headerRow.addView(TextView(this).apply {
            text = headerTitle
            textSize = 13f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(headerColor))
            letterSpacing = 0.05f
        })
        dialogView.addView(headerRow)

        val movieTitle = analysisJson.optString("movie_title", "Movie")
        val cinemaName = analysisJson.optString("cinema_name", "Cinema")
        val showDate = analysisJson.optString("show_date", "")
        val intendedDate = analysisJson.optString("intended_date", "")
        val startTime = analysisJson.optString("start_time", "")
        val endTime = analysisJson.optString("end_time", "")
        val isApprox = analysisJson.optBoolean("is_approximate_end_time", false)
        val durationMinutes = analysisJson.optInt("duration_minutes", 0)
        val durationSource = analysisJson.optString("duration_source", "")
        val lockStart = analysisJson.optString("reservation_start_time", "")
        val lockEnd = analysisJson.optString("reservation_end_time", "")
        val proofOpen = analysisJson.optString("proof_window_open_time", "")
        val proofDead = analysisJson.optString("proof_deadline_time", "")
        val affectedSlots = analysisJson.optJSONArray("affected_slots") ?: JSONArray()
        val seat = analysisJson.optString("seat", "")
        val screen = analysisJson.optString("screen", "")
        val ticketQty = analysisJson.optInt("ticket_quantity", 0)
        val bookingRef = analysisJson.optString("booking_ref", "")
        val bookingCode = analysisJson.optString("booking_code", "")
        val language = analysisJson.optString("language", "")
        val format = analysisJson.optString("format", "")
        val rating = analysisJson.optString("rating", "")
        val isDateMismatch = analysisJson.optBoolean("is_date_mismatch", false)
        val isExpired = analysisJson.optBoolean("is_expired", false)
        val canConfirm = analysisJson.optBoolean("can_confirm", false)
        val message = analysisJson.optString("message", "")

        val scroll = ScrollView(this).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f)
        }
        val content = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
        }

        // Summary details box
        val infoBox = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            background = surfaceBg(CLR_SURFACE_LOW, 12, CLR_BORDER, 1)
            setPadding(dp(14), dp(12), dp(14), dp(12))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        }
        infoBox.addView(TextView(this).apply {
            text = "🎬 $movieTitle"
            textSize = 15f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
        })
        if (language.isNotBlank() || format.isNotBlank() || rating.isNotBlank()) {
            infoBox.addView(TextView(this).apply {
                val extras = listOf(language, format, rating).filter { it.isNotBlank() }.joinToString(" | ")
                text = extras
                textSize = 11f
                setTextColor(Color.parseColor(CLR_CYAN))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(2)
                }
            })
        }
        if (cinemaName.isNotBlank()) {
            infoBox.addView(TextView(this).apply {
                text = "📍 $cinemaName"
                textSize = 12f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(4)
                }
            })
        }
        val seatDetails = listOf(
            if (ticketQty > 0) "$ticketQty ticket(s)" else "",
            if (seat.isNotBlank()) "Seat: $seat" else "",
            if (screen.isNotBlank()) screen else ""
        ).filter { it.isNotBlank() }.joinToString(" · ")
        if (seatDetails.isNotBlank()) {
            infoBox.addView(TextView(this).apply {
                text = "🎟️ $seatDetails"
                textSize = 11f
                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(4)
                }
            })
        }
        val refDetails = listOf(
            if (bookingRef.isNotBlank()) "ID: $bookingRef" else "",
            if (bookingCode.isNotBlank() && bookingCode != bookingRef) "Code: $bookingCode" else ""
        ).filter { it.isNotBlank() }.joinToString(" · ")
        if (refDetails.isNotBlank()) {
            infoBox.addView(TextView(this).apply {
                text = "🔖 $refDetails"
                textSize = 10f
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(2)
                }
            })
        }
        content.addView(infoBox)

        // Schedule & Date Card
        val schedBox = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            background = surfaceBg(CLR_SURFACE_LOW, 12, CLR_BORDER, 1)
            setPadding(dp(14), dp(12), dp(14), dp(12))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        }
        val dateText = if (intendedDate.isNotBlank() && intendedDate != showDate) {
            "📅 Ticket Date: $showDate  ⚠️ Intended: $intendedDate"
        } else {
            "📅 Validated Show Date: $showDate"
        }
        schedBox.addView(TextView(this).apply {
            text = dateText
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(if (isDateMismatch) Color.parseColor("#FF4D4D") else Color.WHITE)
        })

        val approxLabel = if (isApprox) " (approx)" else ""
        schedBox.addView(TextView(this).apply {
            text = "🕒 Show Times: $startTime – $endTime$approxLabel (${durationMinutes}m via $durationSource)"
            textSize = 12f
            setTextColor(Color.parseColor(CLR_CYAN))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(4)
            }
        })
        schedBox.addView(TextView(this).apply {
            text = "🔒 Attendance Lock: $lockStart – $lockEnd (±90 min envelope)\n   ↳ ${affectedSlots.length()} hourly check-ins excused"
            textSize = 11f
            setTextColor(Color.parseColor(CLR_ACCENT))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(6)
            }
        })
        schedBox.addView(TextView(this).apply {
            text = "📤 Proof Window: $proofOpen – $proofDead\n   ↳ Opens 5m before end, deadline 1h after end"
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(4)
            }
        })
        content.addView(schedBox)

        // Status Banner
        val statusBanner = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            background = surfaceBg(if (canConfirm) "#0D2E1A" else "#2E1A0D", 10, if (canConfirm) CLR_GREEN else "#FF7A00", 1)
            setPadding(dp(12), dp(10), dp(12), dp(10))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(12)
            }
        }
        val statusTitle = when {
            isExpired -> "EXPIRED SHOW ❌"
            isDateMismatch -> "DATE MISMATCH ⚠️"
            canConfirm && isDemo -> "DEMO VALIDATED ✅ (ISOLATED TEST)"
            canConfirm -> "VALIDATED ✅ (READY TO CONFIRM)"
            else -> "NEEDS REVIEW ⚠️"
        }
        statusBanner.addView(TextView(this).apply {
            text = statusTitle
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(if (canConfirm) Color.parseColor(CLR_GREEN) else Color.parseColor("#FFB800"))
        })
        statusBanner.addView(TextView(this).apply {
            text = message
            textSize = 11f
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(2)
            }
        })
        content.addView(statusBanner)
        scroll.addView(content)
        dialogView.addView(scroll)

        var reviewDialogRef: AlertDialog? = null

        val btnActions = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(8)
            }
        }
        val btnCancel = makeSecondaryButton("Back", CLR_TEXT_DIM) {
            reviewDialogRef?.dismiss()
            showPrebookMovieDialog(isDemo = isDemo)
        }.apply {
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                rightMargin = dp(8)
            }
        }
        btnActions.addView(btnCancel)

        if (canConfirm) {
            val confirmLabel = if (isDemo) "COMPLETE DEMO" else "CONFIRM PRE-BOOKING"
            val btnConfirm = makePrimaryButton(confirmLabel, if (isDemo) "#FFB800" else CLR_GREEN) {
                reviewDialogRef?.dismiss()
                Thread {
                    val conf = db.confirmMovieBooking(analysisJson, ticketBytes, isDemo = isDemo)
                    runOnUiThread {
                        refreshUi()
                        if (isDemo) {
                            AlertDialog.Builder(this)
                                .setTitle("🧪 Demo Movie Analysis Completed")
                                .setMessage("Demo movie analysis completed — no points, attendance holds, or production records changed.")
                                .setPositiveButton("OK", null)
                                .show()
                        } else {
                            val success = conf.optBoolean("success", false)
                            if (success) {
                                AlertDialog.Builder(this)
                                    .setTitle("🎬 Movie Booking Confirmed")
                                    .setMessage("Confirmed booking for $movieTitle!\n\nAttendance Lock:\n$lockStart – $lockEnd (±90 min)\n\nProof Window:\n$proofOpen – $proofDead\n\nAffected hourly slots are excused.")
                                    .setPositiveButton("OK", null)
                                    .show()
                            } else {
                                val err = conf.optString("error", "Unable to confirm booking.")
                                AlertDialog.Builder(this)
                                    .setTitle("Booking Issue")
                                    .setMessage(err)
                                    .setPositiveButton("OK", null)
                                    .show()
                            }
                        }
                    }
                }.start()
            }.apply {
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 2f)
            }
            btnActions.addView(btnConfirm)
        }
        dialogView.addView(btnActions)

        reviewDialogRef = AlertDialog.Builder(this).setView(dialogView).create()
        reviewDialogRef.show()
    }

    private fun buildOfficialEventPrebookingSection(): View {
        val bookings = db.listOfficialEventBookings()
        val isTablet = isWideLayout()

        val card = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            val pad = dp(if (isTablet) 14 else 12)
            setPadding(pad, pad, pad, pad)
            background = surfaceBg(CLR_SURFACE, 16, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
        }

        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        }

        val iconBadge = FrameLayout(this).apply {
            layoutParams = LinearLayout.LayoutParams(dp(32), dp(32)).apply { rightMargin = dp(10) }
            background = surfaceBg(CLR_ELEVATED, 10, CLR_BORDER, 1)
        }
        val iconTv = TextView(this).apply {
            text = "🎓"
            textSize = 16f
            gravity = Gravity.CENTER
            layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)
        }
        iconBadge.addView(iconTv)
        headerRow.addView(iconBadge)

        val titleCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        titleCol.addView(TextView(this).apply {
            text = "OFFICIAL EVENTS"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            letterSpacing = 0.05f
        })
        titleCol.addView(TextView(this).apply {
            text = "Exams & Interviews"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
        })
        headerRow.addView(titleCol)

        val btnPrebook = TextView(this).apply {
            text = "+ BOOK EVENT"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor("#070A0C"))
            background = surfaceBg(CLR_CYAN, 8)
            setPadding(dp(12), dp(6), dp(12), dp(6))
            applySpringTouch {
                showOfficialEventBookingDialog()
            }
        }
        headerRow.addView(btnPrebook)
        card.addView(headerRow)

        if (bookings.length() == 0) {
            card.addView(TextView(this).apply {
                text = "No official events booked. Pre-book an upcoming college exam or interview to authorize clean exit during its window."
                textSize = 12f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                setPadding(0, dp(4), 0, dp(4))
            })
            return card
        }

        val nowMs = System.currentTimeMillis()
        for (i in 0 until bookings.length()) {
            val item = bookings.optJSONObject(i) ?: continue
            val eventId = item.optString("event_id")
            val title = item.optString("title", "Official Event")
            val org = item.optString("organization")
            val date = item.optString("event_date")
            val startTime = item.optString("start_time")
            val endTime = item.optString("end_time")
            val status = item.optString("status", "CONFIRMED")
            val shortlistStatus = item.optString("shortlist_status")
            val mode = item.optString("event_mode")
            val venue = item.optString("venue_or_platform")

            val itemCard = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                background = surfaceBg(CLR_ELEVATED, 10, CLR_BORDER, 1)
                setPadding(dp(12), dp(10), dp(12), dp(10))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(6)
                }
            }

            val topRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
            }
            val titleTv = TextView(this).apply {
                text = title
                textSize = 13f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            }
            topRow.addView(titleTv)

            val statusColor = if (status == OfficialEventBookingRules.STATE_CONFIRMED) CLR_GREEN else CLR_RED
            val statusPill = TextView(this).apply {
                text = status
                textSize = 9f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(statusColor))
                background = surfaceBg(CLR_SURFACE, 4, statusColor, 1)
                setPadding(dp(6), dp(2), dp(6), dp(2))
            }
            topRow.addView(statusPill)
            itemCard.addView(topRow)

            val infoTv = TextView(this).apply {
                text = "📅 $date  ⏰ $startTime - $endTime  ($mode${if (venue.isNotBlank()) " · $venue" else ""})"
                textSize = 11f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(4)
                }
            }
            itemCard.addView(infoTv)

            if (org.isNotBlank()) {
                val orgTv = TextView(this).apply {
                    text = "🏢 $org"
                    textSize = 11f
                    setTextColor(Color.parseColor(CLR_CYAN))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(2)
                    }
                }
                itemCard.addView(orgTv)
            }

            if (shortlistStatus == OfficialEventBookingRules.SHORTLIST_ANNOUNCED_UNVERIFIED_INDIVIDUAL) {
                val warnTv = TextView(this).apply {
                    text = "⚠️ Placement announcement: individual candidate shortlist unverified."
                    textSize = 10f
                    setTextColor(Color.parseColor("#FFB800"))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(2)
                    }
                }
                itemCard.addView(warnTv)
            }

            val winEval = OfficialEventBookingRules.evaluateExitWindow(item, nowMs)
            if (winEval.inWindow && winEval.canExit) {
                val winPill = TextView(this).apply {
                    text = "🟢 EXIT WINDOW ACTIVE (${winEval.timeRemainingMinutes}m left)"
                    textSize = 11f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(CLR_GREEN))
                    background = surfaceBg("#0D2E1A", 6, CLR_GREEN, 1)
                    setPadding(dp(8), dp(4), dp(8), dp(4))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(6)
                    }
                }
                itemCard.addView(winPill)
            }

            if (status == OfficialEventBookingRules.STATE_CONFIRMED) {
                val actRow = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.END
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(6)
                    }
                }
                val btnCancel = TextView(this).apply {
                    text = "Cancel Booking"
                    textSize = 11f
                    setTextColor(Color.parseColor(CLR_RED))
                    setPadding(dp(8), dp(4), dp(8), dp(4))
                    applySpringTouch {
                        AlertDialog.Builder(this@MainActivity)
                            .setTitle("Cancel Official Event?")
                            .setMessage("Are you sure you want to cancel the booking for '$title'?")
                            .setPositiveButton("Yes, Cancel") { _, _ ->
                                db.cancelOfficialEventBooking(eventId)
                                refreshUi()
                                Toast.makeText(this@MainActivity, "Event booking cancelled.", Toast.LENGTH_SHORT).show()
                            }
                            .setNegativeButton("Keep", null)
                            .show()
                    }
                }
                actRow.addView(btnCancel)
                itemCard.addView(actRow)
            }

            card.addView(itemCard)
        }

        return card
    }

    private fun showOfficialEventBookingDialog() {
        val tz = TimeZone.getTimeZone(db.scheduleTimezone())
        val dateFmt = SimpleDateFormat("yyyy-MM-dd", Locale.US).apply { timeZone = tz }
        val cal = Calendar.getInstance(tz)
        val selectedDate = dateFmt.format(cal.time)

        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(18), dp(20), dp(18))
            background = surfaceBg(CLR_MODAL, 18, CLR_BORDER, 1)
        }

        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(12)
            }
        }
        val iconBadge = TextView(this).apply {
            text = "🎓"
            textSize = 20f
            layoutParams = LinearLayout.LayoutParams(dp(28), dp(28)).apply { rightMargin = dp(8) }
        }
        headerRow.addView(iconBadge)
        headerRow.addView(TextView(this).apply {
            text = "BOOK OFFICIAL EVENT"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            letterSpacing = 0.05f
        })
        dialogView.addView(headerRow)

        val scroll = ScrollView(this).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(380))
        }
        val formLayout = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
        }

        fun makeFieldLabel(label: String): TextView = TextView(this).apply {
            text = label
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(8)
                bottomMargin = dp(2)
            }
        }

        fun makeInputField(hintText: String, initialText: String = ""): EditText = EditText(this).apply {
            hint = hintText
            setText(initialText)
            textSize = 13f
            setTextColor(Color.WHITE)
            setHintTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            background = surfaceBg(CLR_SURFACE, 8, CLR_BORDER, 1)
            setPadding(dp(10), dp(8), dp(10), dp(8))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }

        formLayout.addView(makeFieldLabel("EVENT TITLE *"))
        val etTitle = makeInputField("e.g. HCLTech Technical Interview", "Official Examination / Interview")
        formLayout.addView(etTitle)

        formLayout.addView(makeFieldLabel("CATEGORY"))
        val categories = arrayOf(
            "College Examination",
            "College Internal Assessment / Lab",
            "Online Technical Assessment",
            "Virtual Technical Interview",
            "Campus Recruitment Interview",
            "Other Official Academic / Recruitment Event"
        )
        val catCodes = arrayOf(
            OfficialEventBookingRules.CAT_COLLEGE_EXAM,
            OfficialEventBookingRules.CAT_COLLEGE_INTERNAL_ASSESSMENT,
            OfficialEventBookingRules.CAT_ONLINE_ASSESSMENT,
            OfficialEventBookingRules.CAT_VIRTUAL_INTERVIEW,
            OfficialEventBookingRules.CAT_CAMPUS_RECRUITMENT,
            OfficialEventBookingRules.CAT_OTHER_OFFICIAL
        )
        val spinnerCat = android.widget.Spinner(this).apply {
            adapter = android.widget.ArrayAdapter(this@MainActivity, android.R.layout.simple_spinner_dropdown_item, categories)
            background = surfaceBg(CLR_SURFACE, 8, CLR_BORDER, 1)
            setPadding(dp(8), dp(8), dp(8), dp(8))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        formLayout.addView(spinnerCat)

        formLayout.addView(makeFieldLabel("ORGANIZATION / COLLEGE"))
        val etOrg = makeInputField("e.g. Sathyabama / HCLTech")
        formLayout.addView(etOrg)

        formLayout.addView(makeFieldLabel("EVENT DATE (YYYY-MM-DD) *"))
        val etDate = makeInputField("YYYY-MM-DD", selectedDate)
        formLayout.addView(etDate)

        val timeRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(8)
            }
        }
        val startCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
        }
        startCol.addView(makeFieldLabel("START TIME (HH:MM) *"))
        val etStart = makeInputField("09:00", "09:00")
        startCol.addView(etStart)

        val endCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
        }
        endCol.addView(makeFieldLabel("END TIME (HH:MM) *"))
        val etEnd = makeInputField("11:00", "11:00")
        endCol.addView(etEnd)

        timeRow.addView(startCol)
        timeRow.addView(endCol)
        formLayout.addView(timeRow)

        formLayout.addView(makeFieldLabel("MODE & VENUE / PLATFORM"))
        val etVenue = makeInputField("e.g. Virtual (Zoom / Teams) or Campus Hall")
        formLayout.addView(etVenue)

        scroll.addView(formLayout)
        dialogView.addView(scroll)

        var dialogRef: AlertDialog? = null
        val btnRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.END
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(14)
            }
        }

        val btnCancel = makeSecondaryButton("CANCEL", CLR_BORDER) {
            dialogRef?.dismiss()
        }.apply {
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(6) }
        }
        val btnConfirm = makePrimaryButton("CONFIRM BOOKING", CLR_CYAN) {
            val title = etTitle.text.toString().trim()
            val catIdx = spinnerCat.selectedItemPosition
            val catCode = if (catIdx in catCodes.indices) catCodes[catIdx] else OfficialEventBookingRules.CAT_OTHER_OFFICIAL
            val org = etOrg.text.toString().trim()
            val dStr = etDate.text.toString().trim()
            val sTime = etStart.text.toString().trim()
            val eTime = etEnd.text.toString().trim()
            val venue = etVenue.text.toString().trim()

            val bookingObj = JSONObject().apply {
                put("title", title)
                put("category", catCode)
                put("organization", org)
                put("event_date", dStr)
                put("start_time", sTime)
                put("end_time", eTime)
                put("venue_or_platform", venue)
                put("event_mode", if (venue.lowercase(Locale.US).contains("zoom") || venue.lowercase(Locale.US).contains("virtual") || venue.lowercase(Locale.US).contains("online")) OfficialEventBookingRules.MODE_VIRTUAL else OfficialEventBookingRules.MODE_IN_PERSON)
                put("shortlist_status", OfficialEventBookingRules.SHORTLIST_CONFIRMED_INDIVIDUAL)
                put("status", OfficialEventBookingRules.STATE_CONFIRMED)
            }

            val existingList = mutableListOf<JSONObject>()
            val currentBookings = db.listOfficialEventBookings()
            for (i in 0 until currentBookings.length()) {
                currentBookings.optJSONObject(i)?.let { existingList.add(it) }
            }

            val valRes = OfficialEventBookingRules.validateEventBooking(bookingObj, existingList)
            if (!valRes.valid) {
                AlertDialog.Builder(this@MainActivity)
                    .setTitle("Validation Incomplete")
                    .setMessage(valRes.errors.joinToString("\n\n"))
                    .setPositiveButton("OK", null)
                    .show()
                return@makePrimaryButton
            }

            dialogRef?.dismiss()
            db.saveOfficialEventBooking(bookingObj)
            refreshUi()
            Thread {
                db.flushSyncEventsQueue(this@MainActivity)
            }.start()
            Toast.makeText(this@MainActivity, "Official event booked and queued for sync!", Toast.LENGTH_LONG).show()
        }.apply {
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1.5f)
        }

        btnRow.addView(btnCancel)
        btnRow.addView(btnConfirm)
        dialogView.addView(btnRow)

        dialogRef = AlertDialog.Builder(this).setView(dialogView).create()
        dialogRef.show()
    }


