    private fun buildExamPrebookingSection(): View {
        val examsArr = db.listExamPrebookings()
        val isTablet = isWideLayout()

        val card = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            val pad = dp(if (isTablet) 14 else 12)
            setPadding(pad, pad, pad, pad)
            background = surfaceBg(CLR_SURFACE, 16, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
        }

        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        }

        val iconBadge = FrameLayout(this).apply {
            layoutParams = LinearLayout.LayoutParams(dp(32), dp(32)).apply { rightMargin = dp(10) }
            background = surfaceBg(CLR_ELEVATED, 10, CLR_BORDER, 1)
            addView(TextView(this@MainActivity).apply {
                text = "🎓"
                textSize = 16f
                gravity = Gravity.CENTER
                layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            })
        }
        headerRow.addView(iconBadge)

        val titleCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            addView(TextView(this@MainActivity).apply {
                text = "EXAM PREBOOKING (1–4 TESTS)"
                textSize = 10f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_CYAN))
                letterSpacing = 0.05f
            })
            addView(TextView(this@MainActivity).apply {
                text = "AI-Verified Academic Exemption"
                textSize = 14f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
            })
        }
        headerRow.addView(titleCol)

        val btnPrebook = TextView(this).apply {
            text = "+ PREBOOK EXAM(S)"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor("#070A0C"))
            background = surfaceBg(CLR_CYAN, 8)
            setPadding(dp(12), dp(6), dp(12), dp(6))
            applySpringTouch {
                showExamPrebookingDialog()
            }
        }
        headerRow.addView(btnPrebook)
        card.addView(headerRow)

        if (examsArr.length() == 0) {
            card.addView(TextView(this).apply {
                text = "No examinations prebooked. Register 1 to 4 semester exams, online placement drives (e.g. Cognizant CST), or university tests with supporting evidence."
                textSize = 11f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(2)
                }
            })
        } else {
            for (i in 0 until examsArr.length()) {
                val ex = examsArr.optJSONObject(i) ?: continue
                val bId = ex.optString("booking_id")
                val exName = ex.optString("exam_name", "Examination")
                val subj = ex.optString("subject", "")
                val inst = ex.optString("institution", "")
                val date = ex.optString("exam_date", "")
                val sTime = ex.optString("official_start_time", "")
                val eTime = ex.optString("official_end_time", "")
                val sIso = ex.optString("allocation_start_iso", "")
                val eIso = ex.optString("allocation_end_iso", "")
                val st = ex.optString("status", "EXAM_APPROVED")
                val consistency = ex.optString("cross_image_consistency", "CONSISTENT")
                val imgCount = ex.optInt("supporting_images_count", 1)
                val testIdx = ex.optInt("test_index", 1)
                val totTests = ex.optInt("total_tests", 1)

                val itemCard = LinearLayout(this).apply {
                    orientation = LinearLayout.VERTICAL
                    setPadding(dp(10), dp(8), dp(10), dp(8))
                    background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(6)
                    }
                }

                val topRow = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.CENTER_VERTICAL
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
                }
                val titleBox = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.CENTER_VERTICAL
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                    if (totTests > 1) {
                        addView(TextView(this@MainActivity).apply {
                            text = "TEST $testIdx/$totTests"
                            textSize = 9f
                            setTypeface(typeface, Typeface.BOLD)
                            setTextColor(Color.parseColor(CLR_CYAN))
                            background = surfaceBg(CLR_ELEVATED, 4, CLR_CYAN, 1)
                            setPadding(dp(4), dp(2), dp(4), dp(2))
                            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                                rightMargin = dp(6)
                            }
                        })
                    }
                    addView(TextView(this@MainActivity).apply {
                        text = exName
                        textSize = 12.5f
                        setTypeface(typeface, Typeface.BOLD)
                        setTextColor(Color.WHITE)
                    })
                }
                topRow.addView(titleBox)

                val badgeColor = if (st in listOf("EXAM_APPROVED", "EXAM_COMPLETED_EARLY")) CLR_CYAN else if (st == "EXAM_CANCELLED") CLR_RED else CLR_AMBER
                topRow.addView(TextView(this@MainActivity).apply {
                    text = if (st == "EXAM_COMPLETED_EARLY") "COMPLETED EARLY" else st.replace("EXAM_", "")
                    textSize = 9.5f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(badgeColor))
                    setPadding(dp(6), dp(2), dp(6), dp(2))
                    background = surfaceBg(CLR_ELEVATED, 6, badgeColor, 1)
                })
                itemCard.addView(topRow)

                itemCard.addView(TextView(this).apply {
                    text = "Subject: $subj • $inst • $date ($sTime – $eTime)"
                    textSize = 10.5f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(2)
                    }
                })

                val sDisp = if (sIso.contains("T")) sIso.substringAfter("T").take(5) else sTime
                val eDisp = if (eIso.contains("T")) eIso.substringAfter("T").take(5) else eTime
                itemCard.addView(TextView(this).apply {
                    text = "Attendance Lock / Exemption: $sDisp – $eDisp (Overlapping hourly checks excused)"
                    textSize = 10f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(CLR_GREEN))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(2)
                    }
                })

                itemCard.addView(TextView(this).apply {
                    text = "AI Validation: $consistency • $imgCount supporting document(s) verified"
                    textSize = 9.5f
                    setTextColor(Color.parseColor(CLR_TEXT_DIM))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(2)
                    }
                })

                if (st != "EXAM_CANCELLED") {
                    val actRow = LinearLayout(this).apply {
                        orientation = LinearLayout.HORIZONTAL
                        gravity = Gravity.END
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                            topMargin = dp(6)
                        }
                    }

                    if (st in listOf("EXAM_APPROVED", "EXAM_SCHEDULED", "EXAM_ACTIVE")) {
                        val btnEndEarly = TextView(this).apply {
                            text = "END EXAM EARLY"
                            textSize = 9.5f
                            setTypeface(typeface, Typeface.BOLD)
                            setTextColor(Color.parseColor(CLR_CYAN))
                            background = surfaceBg(CLR_ELEVATED, 6, CLR_CYAN, 1)
                            setPadding(dp(8), dp(4), dp(8), dp(4))
                            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                                rightMargin = dp(8)
                            }
                            applySpringTouch {
                                AlertDialog.Builder(this@MainActivity)
                                    .setTitle("End Exam Early?")
                                    .setMessage("Confirm that you have finished your examination early.\n\n• Proof windows up to now remain EXCUSED with full points credited.\n• Subsequent proof windows will be reactivated starting from their next scheduled time.")
                                    .setPositiveButton("Yes, End Early") { _, _ ->
                                        val res = db.confirmExamEarlyExit(bId)
                                        if (res != null) {
                                            Toast.makeText(this@MainActivity, "Exam marked completed early. Subsequent proof windows reactivated.", Toast.LENGTH_LONG).show()
                                            refreshUi()
                                        } else {
                                            Toast.makeText(this@MainActivity, "Failed to confirm early exit.", Toast.LENGTH_SHORT).show()
                                        }
                                    }
                                    .setNegativeButton("Cancel", null)
                                    .show()
                            }
                        }
                        actRow.addView(btnEndEarly)
                    }

                    val btnCancel = TextView(this).apply {
                        text = "CANCEL EXAM"
                        textSize = 9.5f
                        setTypeface(typeface, Typeface.BOLD)
                        setTextColor(Color.parseColor(CLR_RED))
                        background = surfaceBg(CLR_ELEVATED, 6, CLR_BORDER, 1)
                        setPadding(dp(8), dp(4), dp(8), dp(4))
                        applySpringTouch {
                            AlertDialog.Builder(this@MainActivity)
                                .setTitle("Cancel Examination Prebooking?")
                                .setMessage("Cancelling this examination will immediately restore normal hourly discipline checks for $date.")
                                .setPositiveButton("Yes, Cancel") { _, _ ->
                                    val ok = db.cancelExamPrebooking(bId)
                                    if (ok) {
                                        Toast.makeText(this@MainActivity, "Examination cancelled. Normal schedule restored.", Toast.LENGTH_SHORT).show()
                                        refreshUi()
                                    }
                                }
                                .setNegativeButton("Keep Exam", null)
                                .show()
                        }
                    }
                    actRow.addView(btnCancel)
                    itemCard.addView(actRow)
                }

                card.addView(itemCard)
            }
        }

        return card
    }

