        val testCardsContainer = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        formLayout.addView(testCardsContainer)

        fun makeFieldLabel(label: String): TextView = TextView(this).apply {
            text = label
            textSize = 9.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            letterSpacing = 0.03f
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(6)
                bottomMargin = dp(2)
            }
        }

        fun makeInputField(hintText: String, initialText: String = ""): EditText = EditText(this).apply {
            hint = hintText
            setText(initialText)
            textSize = 12f
            setTextColor(Color.WHITE)
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            background = surfaceBg(CLR_SURFACE_LOW, 8, CLR_BORDER, 1)
            setPadding(dp(10), dp(7), dp(10), dp(7))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }

        lateinit var btnAddTest: TextView

        fun addTestCard() {
            if (testHolders.size >= 4) {
                Toast.makeText(this@MainActivity, "Maximum 4 tests allowed.", Toast.LENGTH_SHORT).show()
                return
            }

            val tIdx = testHolders.size + 1
            val tCard = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(12), dp(10), dp(12), dp(10))
                background = surfaceBg(CLR_SURFACE, 12, CLR_BORDER, 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(12)
                }
            }

            val cardHead = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(6)
                }
                addView(TextView(this@MainActivity).apply {
                    text = "TEST ENTRY #$tIdx"
                    textSize = 11f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(CLR_CYAN))
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                })
            }

            val etName = makeInputField(if (tIdx == 1) "e.g. Cognizant CST Round 1 CA" else "e.g. Cognizant CST Round 2 Aptitude")
            val etSubj = makeInputField(if (tIdx == 1) "e.g. Communication Assessment" else "e.g. Quantitative & Reasoning Aptitude")
            val etInst = makeInputField("e.g. Sathyabama Placement / Cognizant", "Sathyabama Placement")
            val etDate = makeInputField(selectedDateDefault, selectedDateDefault)
            val etType = makeInputField("PLACEMENT_DRIVE", "PLACEMENT_DRIVE")
            val defaultStart = if (tIdx == 1) "09:00" else if (tIdx == 2) "14:00" else if (tIdx == 3) "17:00" else "19:00"
            val defaultEnd = if (tIdx == 1) "10:00" else if (tIdx == 2) "16:00" else if (tIdx == 3) "18:00" else "20:00"
            val etStart = makeInputField(defaultStart, defaultStart)
            val etEnd = makeInputField(defaultEnd, defaultEnd)
            val etPrep = makeInputField("30", "30")
            val etComp = makeInputField("30", "30")
            val etNotes = makeInputField("e.g. Round $tIdx mandatory assessment")

            val selectedUris = mutableListOf<Uri>()
            val tvCap = TextView(this@MainActivity).apply {
                text = "Supporting Evidence: 0 / 5 images (5 remaining)"
                textSize = 9.5f
                setTextColor(Color.parseColor(CLR_CYAN))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(4)
                    bottomMargin = dp(2)
                }
            }
            val thumbs = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            val hScroll = HorizontalScrollView(this@MainActivity).apply {
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(2)
                    bottomMargin = dp(6)
                }
                addView(thumbs)
            }

            fun updateThumbs() {
                thumbs.removeAllViews()
                tvCap.text = "Supporting Evidence: ${selectedUris.size} / 5 images (${5 - selectedUris.size} remaining)"
                for (uIdx in selectedUris.indices) {
                    val u = selectedUris[uIdx]
                    val frame = LinearLayout(this@MainActivity).apply {
                        orientation = LinearLayout.VERTICAL
                        gravity = Gravity.CENTER_HORIZONTAL
                        setPadding(dp(2), dp(2), dp(2), dp(2))
                        background = surfaceBg(CLR_ELEVATED, 6, CLR_BORDER, 1)
                        layoutParams = LinearLayout.LayoutParams(dp(64), ViewGroup.LayoutParams.WRAP_CONTENT).apply { rightMargin = dp(6) }
                    }
                    val iv = ImageView(this@MainActivity).apply {
                        layoutParams = LinearLayout.LayoutParams(dp(58), dp(58))
                        scaleType = ImageView.ScaleType.CENTER_CROP
                        try {
                            val s = contentResolver.openInputStream(u)
                            val b = BitmapFactory.decodeStream(s)
                            s?.close()
                            if (b != null) setImageBitmap(b) else setImageResource(android.R.drawable.ic_menu_gallery)
                        } catch (_: Exception) { setImageResource(android.R.drawable.ic_menu_gallery) }
                    }
                    frame.addView(iv)
                    val btnDel = TextView(this@MainActivity).apply {
                        text = "✕"
                        textSize = 9f
                        setTypeface(typeface, Typeface.BOLD)
                        setTextColor(Color.parseColor(CLR_RED))
                        setPadding(dp(2), dp(1), dp(2), dp(1))
                        setOnClickListener {
                            selectedUris.removeAt(uIdx)
                            updateThumbs()
                        }
                    }
                    frame.addView(btnDel)
                    thumbs.addView(frame)
                }
            }

            val btnAddImg = TextView(this@MainActivity).apply {
                text = "+ ADD SUPPORTING EVIDENCE IMAGE"
                textSize = 10f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_CYAN))
                background = surfaceBg(CLR_ELEVATED, 6, CLR_CYAN, 1)
                setPadding(dp(8), dp(6), dp(8), dp(6))
                gravity = Gravity.CENTER
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(4)
                }
                applySpringTouch {
                    if (selectedUris.size >= 5) {
                        Toast.makeText(this@MainActivity, "Maximum 5 supporting images reached for Test #$tIdx.", Toast.LENGTH_SHORT).show()
                        return@applySpringTouch
                    }
                    AlertDialog.Builder(this@MainActivity)
                        .setTitle("Add Supporting Evidence for Test #$tIdx")
                        .setItems(arrayOf("Choose from Gallery / Screenshots", "Browse image file")) { _, which ->
                            val action = if (which == 0) Intent.ACTION_GET_CONTENT else Intent.ACTION_OPEN_DOCUMENT
                            onExamImagesPicked = { uris ->
                                val rem = 5 - selectedUris.size
                                selectedUris.addAll(uris.take(rem))
                                updateThumbs()
                            }
                            try {
                                startActivityForResult(
                                    Intent(action).apply {
                                        type = "image/*"
                                        putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true)
                                        putExtra(Intent.EXTRA_MIME_TYPES, arrayOf("image/jpeg", "image/png", "image/webp"))
                                        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                                    },
                                    REQ_EXAM_EVIDENCE_PICK
                                )
                            } catch (e: Exception) {
                                Toast.makeText(this@MainActivity, "Could not open picker: ${e.message}", Toast.LENGTH_SHORT).show()
                            }
                        }
                        .setNegativeButton("Cancel", null)
                        .show()
                }
            }

            tCard.addView(cardHead)
            tCard.addView(makeFieldLabel("EXAMINATION / TEST NAME *"))
            tCard.addView(etName)
            tCard.addView(makeFieldLabel("SUBJECT / ASSESSMENT AREA *"))
            tCard.addView(etSubj)
            tCard.addView(makeFieldLabel("INSTITUTION / COMPANY *"))
            tCard.addView(etInst)

            val dRow = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            val dCol1 = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
                addView(makeFieldLabel("DATE (YYYY-MM-DD) *"))
                addView(etDate)
            }
            val dCol2 = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
                addView(makeFieldLabel("EXAM TYPE"))
                addView(etType)
            }
            dRow.addView(dCol1)
            dRow.addView(dCol2)
            tCard.addView(dRow)

            val tRow = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            val tCol1 = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
                addView(makeFieldLabel("START TIME (HH:MM) *"))
                addView(etStart)
            }
            val tCol2 = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
                addView(makeFieldLabel("END TIME (HH:MM) *"))
                addView(etEnd)
            }
            tRow.addView(tCol1)
            tRow.addView(tCol2)
            tCard.addView(tRow)

            val bRow = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            val bCol1 = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
                addView(makeFieldLabel("PREP BUFFER (MIN)"))
                addView(etPrep)
            }
            val bCol2 = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
                addView(makeFieldLabel("COMPLETION BUFFER (MIN)"))
                addView(etComp)
            }
            bRow.addView(bCol1)
            bRow.addView(bCol2)
            tCard.addView(bRow)

            tCard.addView(makeFieldLabel("NOTES / RESCHEDULING REMARKS"))
            tCard.addView(etNotes)
            tCard.addView(tvCap)
            tCard.addView(hScroll)
            tCard.addView(btnAddImg)

            val holder = MultiTestCardHolder(
                index = tIdx,
                cardView = tCard,
                etName = etName,
                etSubj = etSubj,
                etInst = etInst,
                etDate = etDate,
                etType = etType,
                etStart = etStart,
                etEnd = etEnd,
                etPrep = etPrep,
                etComp = etComp,
                etNotes = etNotes,
                selectedUris = selectedUris,
                tvCapacity = tvCap,
                thumbsContainer = thumbs
            )

            if (tIdx > 1) {
                val btnRemove = TextView(this@MainActivity).apply {
                    text = "✕ Remove Test"
                    textSize = 9.5f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(CLR_RED))
                    background = surfaceBg(CLR_ELEVATED, 4, CLR_BORDER, 1)
                    setPadding(dp(6), dp(2), dp(6), dp(2))
                    applySpringTouch {
                        testCardsContainer.removeView(tCard)
                        testHolders.remove(holder)
                        if (testHolders.size < 4) {
                            btnAddTest.isEnabled = true
                            btnAddTest.text = "+ ADD ANOTHER TEST (1 to 4)"
                            btnAddTest.setTextColor(Color.parseColor(CLR_CYAN))
                            btnAddTest.background = surfaceBg(CLR_ELEVATED, 8, CLR_CYAN, 1)
                        }
                    }
                }
                cardHead.addView(btnRemove)
            }

            testHolders.add(holder)
            testCardsContainer.addView(tCard)

            if (testHolders.size >= 4) {
                btnAddTest.isEnabled = false
                btnAddTest.text = "Maximum 4 tests allowed."
                btnAddTest.setTextColor(Color.parseColor(CLR_TEXT_DIM))
                btnAddTest.background = surfaceBg(CLR_SURFACE_LOW, 8, CLR_BORDER, 1)
            }
        }

        btnAddTest = TextView(this).apply {
            text = "+ ADD ANOTHER TEST (1 to 4)"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            background = surfaceBg(CLR_ELEVATED, 8, CLR_CYAN, 1)
            setPadding(dp(12), dp(8), dp(12), dp(8))
            gravity = Gravity.CENTER
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(12)
            }
            applySpringTouch {
                if (testHolders.size >= 4) {
                    Toast.makeText(this@MainActivity, "Maximum 4 tests allowed.", Toast.LENGTH_SHORT).show()
                } else {
                    addTestCard()
                }
            }
        }

        // Add initial Test #1 card
        addTestCard()
        formLayout.addView(btnAddTest)

        scroll.addView(formLayout)
        dialogView.addView(scroll)

        var dialogRef: AlertDialog? = null
        val btnRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.END
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(10)
            }
        }
        val btnCancel = makeSecondaryButton("CANCEL", CLR_BORDER) {
            dialogRef?.dismiss()
        }.apply {
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(6) }
        }

        val btnSubmit = makePrimaryButton("SUBMIT ALL TESTS", CLR_CYAN) {
            if (testHolders.isEmpty()) {
                Toast.makeText(this@MainActivity, "At least 1 test is required.", Toast.LENGTH_SHORT).show()
                return@makePrimaryButton
            }
            if (testHolders.size > 4) {
                Toast.makeText(this@MainActivity, "Maximum 4 tests allowed.", Toast.LENGTH_SHORT).show()
                return@makePrimaryButton
            }

            // Validate all fields
            val batchItems = mutableListOf<ExamPrebookingManager.ExamBatchTestItem>()
            val allocations = mutableListOf<Map<String, Any>>()

            for (i in testHolders.indices) {
                val h = testHolders[i]
                val name = h.etName.text.toString().trim()
                val subj = h.etSubj.text.toString().trim()
                val inst = h.etInst.text.toString().trim()
                val date = h.etDate.text.toString().trim()
                val sTime = h.etStart.text.toString().trim()
                val eTime = h.etEnd.text.toString().trim()
                val type = h.etType.text.toString().trim()
                val prep = h.etPrep.text.toString().toIntOrNull() ?: 30
                val comp = h.etComp.text.toString().toIntOrNull() ?: 30
                val notes = h.etNotes.text.toString().trim()

                if (name.isBlank() || subj.isBlank() || inst.isBlank() || date.isBlank() || sTime.isBlank() || eTime.isBlank()) {
                    Toast.makeText(this@MainActivity, "Test #${i + 1}: Please complete all required fields (*).", Toast.LENGTH_LONG).show()
                    return@makePrimaryButton
                }

                val alloc = ExamPrebookingManager.calculateAllocation(date, sTime, eTime, prep, comp, db.scheduleTimezone())
                allocations.add(alloc)

                batchItems.add(
                    ExamPrebookingManager.ExamBatchTestItem(
                        testIndex = i + 1,
                        examName = name,
                        subject = subj,
                        institution = inst,
                        examDate = date,
                        startTime = sTime,
                        endTime = eTime,
                        examType = type,
                        prepBufferMinutes = prep,
                        completionBufferMinutes = comp,
                        additionalInfo = notes,
                        imageBytesList = emptyList() // populated in worker thread
                    )
                )
            }

            // Pairwise overlap detection between tests in batch
            for (i in batchItems.indices) {
                for (j in i + 1 until batchItems.size) {
                    val t1 = batchItems[i]
                    val t2 = batchItems[j]
                    if (t1.examDate == t2.examDate) {
                        val s1 = allocations[i]["start_ms"] as Long
                        val e1 = allocations[i]["end_ms"] as Long
                        val s2 = allocations[j]["start_ms"] as Long
                        val e2 = allocations[j]["end_ms"] as Long
                        if (maxOf(s1, s2) < minOf(e1, e2)) {
                            AlertDialog.Builder(this@MainActivity)
                                .setTitle("Protected Time Conflict Detected")
                                .setMessage(
                                    "Conflict between Test #${t1.testIndex} ('${t1.examName}' ${t1.startTime}–${t1.endTime}) and " +
                                    "Test #${t2.testIndex} ('${t2.examName}' ${t2.startTime}–${t2.endTime}).\n\n" +
                                    "Protected buffers overlap. Please edit the affected test timings before submitting."
                                )
                                .setPositiveButton("Edit Timings", null)
                                .show()
                            return@makePrimaryButton
                        }
                    }
                }
            }

            val progress = AlertDialog.Builder(this@MainActivity)
                .setTitle("Processing Examination Prebooking Batch")
                .setMessage("Validating ${batchItems.size} test(s) & documents with AI...")
                .setCancelable(false)
                .show()

            Thread {
                val fullItems = mutableListOf<ExamPrebookingManager.ExamBatchTestItem>()
                for (i in batchItems.indices) {
                    val orig = batchItems[i]
                    val h = testHolders[i]
                    val byteArrayList = mutableListOf<ByteArray>()
                    for (u in h.selectedUris) {
                        val b = ExamPrebookingManager.processImageUri(this@MainActivity, u)
                        if (b != null) byteArrayList.add(b)
                    }
                    fullItems.add(orig.copy(imageBytesList = byteArrayList))
                }

                val batchRes = ExamPrebookingManager.submitExamPrebookingBatch(this@MainActivity, db, fullItems)

                runOnUiThread {
                    progress.dismiss()
                    if (!batchRes.success) {
                        AlertDialog.Builder(this@MainActivity)
                            .setTitle("Prebooking Submission Failed")
                            .setMessage(batchRes.error ?: "Could not complete batch prebooking.")
                            .setPositiveButton("OK", null)
                            .show()
                        return@runOnUiThread
                    }

                    dialogRef?.dismiss()
                    refreshUi()

                    val msg = buildString {
                        append("Batch ID: ${batchRes.batchId}\n")
                        append("Total Tests Prebooked: ${batchRes.totalTests}\n\n")
                        for (tr in batchRes.testResults) {
                            append("• ${tr.examName} (${tr.subject})\n")
                            append("  Date: ${tr.examDate} (${tr.allocationStartDisplay}–${tr.allocationEndDisplay})\n")
                            append("  Status: ${tr.status} • ${tr.provider}\n\n")
                        }
                        append("Overlapping hourly attendance checks have been EXCUSED with full credit.")
                    }

                    AlertDialog.Builder(this@MainActivity)
                        .setTitle("🎓 Batch Prebooking Confirmed (1–4 Tests)")
                        .setMessage(msg)
                        .setPositiveButton("OK", null)
                        .show()
                }
            }.start()
        }.apply {
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1.4f).apply { leftMargin = dp(6) }
        }

        btnRow.addView(btnCancel)
        btnRow.addView(btnSubmit)
        dialogView.addView(btnRow)

        dialogRef = AlertDialog.Builder(this)
            .setView(dialogView)
            .setCancelable(false)
            .create().apply {
                window?.setBackgroundDrawable(android.graphics.drawable.ColorDrawable(Color.TRANSPARENT))
                show()
            }
    }

    // =========================================================================
    // DAILY PRACTICE TEST SCHEDULER SECTION & CONFIGURATION (2 to 4 TESTS)
    // =========================================================================

    private fun buildDailyPracticeTestSection(): View {
        val today = db.nowDate()
        val sched = db.getDailyPracticeSchedule(today)
        val tmpl = db.getDailyPracticeTemplate()
        val isTablet = isWideLayout()

        // Calculate 10:00 AM morning deadline
        val tz = TimeZone.getTimeZone(db.scheduleTimezone())
        val calNow = Calendar.getInstance(tz)
        val calDeadline = Calendar.getInstance(tz).apply {
            set(Calendar.HOUR_OF_DAY, 10)
            set(Calendar.MINUTE, 0)
            set(Calendar.SECOND, 0)
            set(Calendar.MILLISECOND, 0)
        }
        val isPastDeadline = calNow.after(calDeadline)
        val remMinutes = maxOf(0L, (calDeadline.timeInMillis - calNow.timeInMillis) / 60000L)

        val card = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            val pad = dp(if (isTablet) 14 else 12)
            setPadding(pad, pad, pad, pad)
            background = surfaceBg(CLR_SURFACE, 16, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
        }

        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }

        val iconBadge = FrameLayout(this).apply {
            layoutParams = LinearLayout.LayoutParams(dp(32), dp(32)).apply { rightMargin = dp(10) }
            background = surfaceBg(CLR_ELEVATED, 10, CLR_BORDER, 1)
            addView(TextView(this@MainActivity).apply {
                text = "📝"
                textSize = 16f
                gravity = Gravity.CENTER
                layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            })
        }
        headerRow.addView(iconBadge)

        val titleCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            addView(TextView(this@MainActivity).apply {
                text = "DAILY PRACTICE TESTS (2–4 PER DAY)"
                textSize = 10f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_CYAN))
                letterSpacing = 0.05f
            })
            addView(TextView(this@MainActivity).apply {
                text = "Quantitative Aptitude, Communication & CST"
                textSize = 13.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
            })
        }
        headerRow.addView(titleCol)

        if (!isPastDeadline) {
            val btnConfig = TextView(this).apply {
                text = "⚙ CONFIGURE"
                textSize = 10.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor("#070A0C"))
                background = surfaceBg(CLR_CYAN, 8)
                setPadding(dp(10), dp(5), dp(10), dp(5))
                applySpringTouch {
                    showConfigurePracticeTestsDialog()
                }
            }
            headerRow.addView(btnConfig)
        }
        card.addView(headerRow)

        // Deadline status banner
        val banner = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(10), dp(6), dp(10), dp(6))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }
        if (!isPastDeadline) {
            banner.background = surfaceBg(CLR_ELEVATED, 8, CLR_CYAN, 1)
            banner.addView(TextView(this).apply {
                text = "⏳ Morning Scheduling Window · 10:00 AM Deadline (${remMinutes}m remaining)"
                textSize = 10f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_CYAN))
            })
        } else if (sched == null || sched.optString("status") == "MISSED") {
            banner.background = surfaceBg(CLR_ELEVATED, 8, CLR_RED, 1)
            banner.addView(TextView(this).apply {
                text = "🔒 10:00 AM Deadline Passed · Editing Locked · Today's Practice: MISSED"
                textSize = 10f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_RED))
            })
        } else {
            banner.background = surfaceBg(CLR_ELEVATED, 8, CLR_BORDER, 1)
            banner.addView(TextView(this).apply {
                text = "🔒 10:00 AM Schedule Locked · Practice Active"
                textSize = 10f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            })
        }
        card.addView(banner)

        // Executions or template preview
        val execs = sched?.optJSONArray("executions")
        val testsToShow = if (execs != null && execs.length() > 0) execs else tmpl.optJSONArray("tests")

        if (testsToShow == null || testsToShow.length() == 0) {
            card.addView(TextView(this).apply {
                text = "No practice tests configured. Default schedule includes Quantitative Aptitude (30m) & Communication (30m)."
                textSize = 11f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            })
        } else {
            for (i in 0 until testsToShow.length()) {
                val t = testsToShow.getJSONObject(i)
                val execId = t.optString("execution_id", "PRAC-$today-${i + 1}")
                val tIdx = t.optInt("test_index", i + 1)
                val cat = t.optString("category", "Quantitative Aptitude")
                val title = t.optString("title", cat)
                val sTime = t.optString("start_time", "10:30")
                val eTime = t.optString("end_time", "11:00")
                val dur = t.optInt("duration_minutes", 30)
                val st = t.optString("status", if (sched != null) "SCHEDULED" else "TEMPLATE")

                val itemCard = LinearLayout(this).apply {
                    orientation = LinearLayout.VERTICAL
                    setPadding(dp(10), dp(8), dp(10), dp(8))
                    background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(4)
                    }
                }

                val topRow = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    gravity = Gravity.CENTER_VERTICAL
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
                }

                topRow.addView(TextView(this@MainActivity).apply {
                    text = "TEST $tIdx: $title"
                    textSize = 12f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.WHITE)
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                })

                val badgeColor = when (st) {
                    "COMPLETED" -> CLR_GREEN
                    "IN_PROGRESS" -> CLR_AMBER
                    "MISSED" -> CLR_RED
                    "RESCHEDULED" -> CLR_PURPLE
                    else -> CLR_CYAN
                }
                topRow.addView(TextView(this@MainActivity).apply {
                    text = if (st == "COMPLETED") "COMPLETED (+5 pts)" else st
                    textSize = 9f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(badgeColor))
                    setPadding(dp(6), dp(2), dp(6), dp(2))
                    background = surfaceBg(CLR_ELEVATED, 6, badgeColor, 1)
                })
                itemCard.addView(topRow)

                itemCard.addView(TextView(this).apply {
                    text = "Category: $cat • $sTime – $eTime ($dur mins)"
                    textSize = 10f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(2)
                    }
                })

                // Action buttons if scheduled
                if (sched != null && st in listOf("SCHEDULED", "IN_PROGRESS", "RESCHEDULED")) {
                    val actRow = LinearLayout(this).apply {
                        orientation = LinearLayout.HORIZONTAL
                        gravity = Gravity.END
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                            topMargin = dp(6)
                        }
                    }

                    if (st == "SCHEDULED" || st == "RESCHEDULED") {
                        val btnStart = TextView(this).apply {
                            text = "START TEST"
                            textSize = 9.5f
                            setTypeface(typeface, Typeface.BOLD)
                            setTextColor(Color.parseColor(CLR_CYAN))
                            background = surfaceBg(CLR_ELEVATED, 6, CLR_CYAN, 1)
                            setPadding(dp(8), dp(4), dp(8), dp(4))
                            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                                rightMargin = dp(6)
                            }
                            applySpringTouch {
                                db.startPracticeTestExecution(execId)
                                refreshUi()
                            }
                        }
                        actRow.addView(btnStart)
                    }

                    if (st == "IN_PROGRESS") {
                        val btnComplete = TextView(this).apply {
                            text = "COMPLETE TEST (+5 pts)"
                            textSize = 9.5f
                            setTypeface(typeface, Typeface.BOLD)
                            setTextColor(Color.parseColor(CLR_GREEN))
                            background = surfaceBg(CLR_ELEVATED, 6, CLR_GREEN, 1)
                            setPadding(dp(8), dp(4), dp(8), dp(4))
                            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                                rightMargin = dp(6)
                            }
                            applySpringTouch {
                                val scoreEt = EditText(this@MainActivity).apply {
                                    hint = "Score (e.g. 25)"
                                    setTextColor(Color.WHITE)
                                }
                                AlertDialog.Builder(this@MainActivity)
                                    .setTitle("Complete Practice Test")
                                    .setMessage("Enter your score for $title (optional):")
                                    .setView(scoreEt)
                                    .setPositiveButton("Complete & Award +5 pts") { _, _ ->
                                        val sc = scoreEt.text.toString().toDoubleOrNull()
                                        db.completePracticeTestExecution(execId, score = sc, notes = "Completed in APK")
                                        Toast.makeText(this@MainActivity, "Practice test completed! +5 points awarded.", Toast.LENGTH_SHORT).show()
                                        refreshUi()
                                    }
                                    .setNegativeButton("Cancel", null)
                                    .show()
                            }
                        }
                        actRow.addView(btnComplete)
                    }

                    val btnResched = TextView(this).apply {
                        text = "RESCHEDULE"
                        textSize = 9.5f
                        setTypeface(typeface, Typeface.BOLD)
                        setTextColor(Color.parseColor(CLR_TEXT_MUTED))
                        background = surfaceBg(CLR_ELEVATED, 6, CLR_BORDER, 1)
                        setPadding(dp(8), dp(4), dp(8), dp(4))
                        applySpringTouch {
                            val timeEt = EditText(this@MainActivity).apply {
                                hint = "New start time (HH:MM e.g. 15:30)"
                                setText(sTime)
                                setTextColor(Color.WHITE)
                            }
                            AlertDialog.Builder(this@MainActivity)
                                .setTitle("Reschedule Practice Test")
                                .setMessage("Controlled rescheduling for genuine exceptions:")
                                .setView(timeEt)
                                .setPositiveButton("Reschedule") { _, _ ->
                                    val newT = timeEt.text.toString().trim()
                                    if (newT.isNotBlank()) {
                                        db.reschedulePracticeTestExecution(execId, newT, "User rescheduled from APK")
                                        refreshUi()
                                    }
                                }
                                .setNegativeButton("Cancel", null)
                                .show()
                        }
                    }
                    actRow.addView(btnResched)
                    itemCard.addView(actRow)
                }

                card.addView(itemCard)
            }
        }

        return card
    }

    private class PracticeTestRowState(
        val index: Int,
        val cardView: LinearLayout,
        val etTitle: EditText,
        val etCat: EditText,
        val etStart: EditText,
        val etDur: EditText
    )

    private fun showConfigurePracticeTestsDialog() {
        val today = db.nowDate()
        val tmpl = db.getDailyPracticeTemplate()
        val existingSched = db.getDailyPracticeSchedule(today)

        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(18), dp(16), dp(18), dp(16))
            background = surfaceBg(CLR_MODAL, 18, CLR_BORDER, 1)
        }

        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
            addView(TextView(this@MainActivity).apply {
                text = "📝"
                textSize = 20f
                layoutParams = LinearLayout.LayoutParams(dp(28), dp(28)).apply { rightMargin = dp(8) }
            })
            val titleCol = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                addView(TextView(this@MainActivity).apply {
                    text = "CONFIGURE DAILY PRACTICE (2–4 TESTS)"
                    textSize = 13.5f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(CLR_CYAN))
                    letterSpacing = 0.05f
                })
                addView(TextView(this@MainActivity).apply {
                    text = "Quant & Comm mandatory • Optional CST or Reasoning"
                    textSize = 10f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                })
            }
            addView(titleCol)
        }
        dialogView.addView(headerRow)

        val scroll = ScrollView(this).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f)
        }
        val formLayout = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }

        val rows = mutableListOf<PracticeTestRowState>()
        val rowsContainer = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        formLayout.addView(rowsContainer)

        fun makeFieldLabel(label: String): TextView = TextView(this).apply {
            text = label
            textSize = 9f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(4)
                bottomMargin = dp(1)
            }
        }

        fun makeInputField(hintText: String, initialText: String = ""): EditText = EditText(this).apply {
            hint = hintText
            setText(initialText)
            textSize = 11.5f
            setTextColor(Color.WHITE)
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            background = surfaceBg(CLR_SURFACE_LOW, 6, CLR_BORDER, 1)
            setPadding(dp(8), dp(6), dp(8), dp(6))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }

        lateinit var btnAddRow: TextView

        fun addRow(defaultCat: String = "Logical Reasoning", defaultTitle: String = "Logical Reasoning", defaultStart: String = "14:00", defaultDur: Int = 30) {
            if (rows.size >= 4) {
                Toast.makeText(this@MainActivity, "Maximum 4 tests allowed.", Toast.LENGTH_SHORT).show()
                return
            }

            val rIdx = rows.size + 1
            val rCard = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(10), dp(8), dp(10), dp(8))
                background = surfaceBg(CLR_SURFACE, 10, CLR_BORDER, 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(8)
                }
            }

            val head = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(4)
                }
                addView(TextView(this@MainActivity).apply {
                    text = "PRACTICE TEST #$rIdx" + (if (rIdx <= 2) " (MANDATORY)" else " (OPTIONAL)")
                    textSize = 10.5f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(if (rIdx <= 2) CLR_CYAN else CLR_AMBER))
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                })
            }
            rCard.addView(head)

            val etTitle = makeInputField("Title", defaultTitle)
            val etCat = makeInputField("Category", defaultCat)
            val etStart = makeInputField("Start time (HH:MM)", defaultStart)
            val etDur = makeInputField("Duration (mins)", defaultDur.toString())

            rCard.addView(makeFieldLabel("CATEGORY (Quant / Comm / CST / Reasoning / Coding)"))
            rCard.addView(etCat)
            rCard.addView(makeFieldLabel("TEST TITLE"))
            rCard.addView(etTitle)

            val timingRow = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            val col1 = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
                addView(makeFieldLabel("START TIME (HH:MM)"))
                addView(etStart)
            }
            val col2 = LinearLayout(this@MainActivity).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
                addView(makeFieldLabel("DURATION (MINUTES)"))
                addView(etDur)
            }
            timingRow.addView(col1)
            timingRow.addView(col2)
            rCard.addView(timingRow)

            val rowState = PracticeTestRowState(rIdx, rCard, etTitle, etCat, etStart, etDur)

            if (rIdx > 2) {
                val btnDel = TextView(this@MainActivity).apply {
                    text = "✕ Remove"
                    textSize = 9f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(CLR_RED))
                    background = surfaceBg(CLR_ELEVATED, 4, CLR_BORDER, 1)
                    setPadding(dp(6), dp(2), dp(6), dp(2))
                    applySpringTouch {
                        rowsContainer.removeView(rCard)
                        rows.remove(rowState)
                        if (rows.size < 4) {
                            btnAddRow.isEnabled = true
                            btnAddRow.text = "+ ADD PRACTICE TEST (Max 4)"
                            btnAddRow.setTextColor(Color.parseColor(CLR_CYAN))
                            btnAddRow.background = surfaceBg(CLR_ELEVATED, 6, CLR_CYAN, 1)
                        }
                    }
                }
                head.addView(btnDel)
            }

            rows.add(rowState)
            rowsContainer.addView(rCard)

            if (rows.size >= 4) {
                btnAddRow.isEnabled = false
                btnAddRow.text = "Maximum 4 tests allowed."
                btnAddRow.setTextColor(Color.parseColor(CLR_TEXT_DIM))
                btnAddRow.background = surfaceBg(CLR_SURFACE_LOW, 6, CLR_BORDER, 1)
            }
        }

        btnAddRow = TextView(this).apply {
            text = "+ ADD PRACTICE TEST (Max 4)"
            textSize = 10.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            background = surfaceBg(CLR_ELEVATED, 6, CLR_CYAN, 1)
            setPadding(dp(10), dp(6), dp(10), dp(6))
            gravity = Gravity.CENTER
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
            applySpringTouch {
                if (rows.size >= 4) {
                    Toast.makeText(this@MainActivity, "Maximum 4 tests allowed.", Toast.LENGTH_SHORT).show()
                } else if (rows.size == 2) {
                    // Suggest Cognizant CST or Reasoning as 3rd test
                    addRow("Company-Specific Assessment", "Cognizant CST Round 1 CA", "16:00", 40)
                } else {
                    addRow("Technical Aptitude", "Technical & Programming Drill", "18:00", 45)
                }
            }
        }

        // Initialize with existing template or default 2 tests
        val tmplTests = tmpl.optJSONArray("tests")
        if (tmplTests != null && tmplTests.length() >= 2) {
            for (i in 0 until minOf(4, tmplTests.length())) {
                val t = tmplTests.getJSONObject(i)
                addRow(
                    defaultCat = t.optString("category", if (i == 0) "Quantitative Aptitude" else "Communication"),
                    defaultTitle = t.optString("title", if (i == 0) "Quantitative Aptitude" else "Communication"),
                    defaultStart = t.optString("start_time", if (i == 0) "10:30" else "11:30"),
                    defaultDur = t.optInt("duration_minutes", 30)
                )
            }
        } else {
            addRow("Quantitative Aptitude", "Quantitative Aptitude", "10:30", 30)
            addRow("Communication", "Communication", "11:30", 30)
        }

        formLayout.addView(btnAddRow)
        scroll.addView(formLayout)
        dialogView.addView(scroll)

        var dialogRef: AlertDialog? = null
        val btnRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.END
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(8)
            }
        }
        val btnCancel = makeSecondaryButton("CANCEL", CLR_BORDER) {
            dialogRef?.dismiss()
        }.apply {
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(6) }
        }

        val btnSave = makePrimaryButton("SAVE & SUBMIT SCHEDULE", CLR_CYAN) { btnView ->
            if (rows.size < 2) {
                Toast.makeText(this@MainActivity, "At least 2 tests required (Quant & Comm).", Toast.LENGTH_SHORT).show()
                return@makePrimaryButton
            }
            if (rows.size > 4) {
                Toast.makeText(this@MainActivity, "Maximum 4 tests allowed.", Toast.LENGTH_SHORT).show()
                return@makePrimaryButton
            }

            val testsArr = JSONArray()
            for (i in rows.indices) {
                val r = rows[i]
                val cat = r.etCat.text.toString().trim()
                val title = r.etTitle.text.toString().trim()
                val sTime = r.etStart.text.toString().trim()
                val dur = r.etDur.text.toString().toIntOrNull() ?: 30

                if (cat.isBlank() || title.isBlank() || sTime.isBlank()) {
                    Toast.makeText(this@MainActivity, "Please complete all fields for Test #${i + 1}.", Toast.LENGTH_SHORT).show()
                    return@makePrimaryButton
                }

                testsArr.put(JSONObject().apply {
                    put("test_index", i + 1)
                    put("category", cat)
                    put("title", title)
                    put("start_time", sTime)
                    put("duration_minutes", dur)
                })
            }

            val btnTv = btnView.getChildAt(0) as? TextView
            btnTv?.text = "SAVING..."
            btnView.alpha = 0.6f

            Thread {
                try {
                    db.saveDailyPracticeTemplate(testsArr, "Configured Daily Practice Schedule")
                    val res = db.submitDailyPracticeSchedule(today, testsArr, "Submitted before 10:00 AM")
                    runOnUiThread {
                        btnTv?.text = "SAVE & SUBMIT SCHEDULE"
                        btnView.alpha = 1.0f
                        if (res != null) {
                            Toast.makeText(this@MainActivity, "Daily practice schedule saved (${rows.size} tests)!", Toast.LENGTH_SHORT).show()
                            dialogRef?.dismiss()
                            refreshUi()
                        } else {
                            AlertDialog.Builder(this@MainActivity)
                                .setTitle("Schedule Configuration Error")
                                .setMessage("Could not save daily practice schedule: database persistence failed.\n\nPlease check your test timings and try again.")
                                .setPositiveButton("OK", null)
                                .show()
                        }
                    }
                } catch (t: Throwable) {
                    Log.e("MainActivity", "Error saving practice schedule", t)
                    runOnUiThread {
                        btnTv?.text = "SAVE & SUBMIT SCHEDULE"
                        btnView.alpha = 1.0f
                        val err = t.localizedMessage ?: t.javaClass.simpleName
                        AlertDialog.Builder(this@MainActivity)
                            .setTitle("Schedule Configuration Error")
                            .setMessage("Failed to save daily practice schedule:\n\n$err\n\nPlease try again.")
                            .setPositiveButton("OK", null)
                            .show()
                    }
                }
            }.start()
        }.apply {
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1.4f).apply { leftMargin = dp(6) }
        }
        btnRow.addView(btnSave)
        dialogView.addView(btnRow)

        dialogRef = AlertDialog.Builder(this)
            .setView(dialogView)
            .setCancelable(false)
            .create().apply {
                window?.setBackgroundDrawable(android.graphics.drawable.ColorDrawable(Color.TRANSPARENT))
                show()
            }
    }

    private fun showPrebookTravelDialog() {
        val restriction = db.getTravelPrebookingRestriction()
        if (restriction.isRestricted) {
            Toast.makeText(this, "Travel pre-booking is locked until ${restriction.lockUntilDateStr} due to 3 consecutive missed travel proofs.", Toast.LENGTH_LONG).show()
            return
        }
        val tz = TimeZone.getTimeZone(db.scheduleTimezone())
        val dateFmt = SimpleDateFormat("yyyy-MM-dd", Locale.US).apply { timeZone = tz }
        val timeFmt = SimpleDateFormat("HH:mm", Locale.US).apply { timeZone = tz }

        val cal = Calendar.getInstance(tz).apply {
            add(Calendar.DAY_OF_YEAR, 1)
            set(Calendar.HOUR_OF_DAY, 9)
            set(Calendar.MINUTE, 0)
            set(Calendar.SECOND, 0)
            set(Calendar.MILLISECOND, 0)
        }

        var selectedDate = dateFmt.format(cal.time)
        var selectedTime = timeFmt.format(cal.time)
        var selectedDurationHours = 3

        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(18), dp(20), dp(18))
            background = surfaceBg(CLR_MODAL, 18, CLR_BORDER, 1)
        }

        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }
        val iconBadge = ImageView(this).apply {
            setImageResource(R.drawable.strictbot_head)
            scaleType = ImageView.ScaleType.FIT_CENTER
            layoutParams = LinearLayout.LayoutParams(dp(26), dp(26)).apply { rightMargin = dp(8) }
        }
        headerRow.addView(iconBadge)
        headerRow.addView(TextView(this).apply {
            text = "📅 PRE-BOOK TRAVEL"
            textSize = 13f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_PURPLE))
            letterSpacing = 0.05f
        })
        dialogView.addView(headerRow)

        dialogView.addView(TextView(this).apply {
            text = "Pre-booking opens at 12:00 AM two days before departure and closes 6 hours before departure time."
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(12)
            }
        })

        val dateRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
            setPadding(dp(12), dp(10), dp(12), dp(10))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }
        val dateLabel = TextView(this).apply {
            text = "📅 Date: $selectedDate"
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        dateRow.addView(dateLabel)

        val timeRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            background = surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
            setPadding(dp(12), dp(10), dp(12), dp(10))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        }
        val timeLabel = TextView(this).apply {
            text = "⏰ Departure: $selectedTime"
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        timeRow.addView(timeLabel)

        val durationLabel = TextView(this).apply {
            text = "Expected Travel Duration"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(4)
            }
        }
        dialogView.addView(durationLabel)

        val durationRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        }
        val durations = listOf(2, 3, 4, 5, 6)
        val chipViews = mutableListOf<TextView>()
        fun updateDurationChips() {
            chipViews.forEachIndexed { index, tv ->
                val d = durations[index]
                val isSelected = d == selectedDurationHours
                tv.setTextColor(Color.parseColor(if (isSelected) "#070A0C" else CLR_TEXT_PRIMARY))
                tv.background = surfaceBg(if (isSelected) CLR_PURPLE else CLR_SURFACE_LOW, 8, if (isSelected) CLR_PURPLE else CLR_BORDER, 1)
            }
        }

        val statusBanner = TextView(this).apply {
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setPadding(dp(10), dp(8), dp(10), dp(8))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(12)
            }
        }

        fun updateValidationStatus() {
            val eval = TravelBookingRules.evaluateBookingWindow(selectedDate, selectedTime, db.authoritativeNowMs(), tz)
            val win = TravelBookingRules.calculateTravelWindow(selectedDate, selectedTime, selectedDurationHours, tz)
            if (eval.allowed && win != null) {
                val deadlineCal = Calendar.getInstance(tz).apply { timeInMillis = eval.bookingDeadlineMs }
                val deadlineStr = SimpleDateFormat("MMM d, h:mm a", Locale.US).apply { timeZone = tz }.format(deadlineCal.time)
                val depDisplay = ScheduleClock.display(win.departureMs, db.scheduleTimezone(), "h:mm a")
                val arrDisplay = ScheduleClock.display(win.travelEndMs, db.scheduleTimezone(), "h:mm a")
                val proofEndDisplay = ScheduleClock.display(win.windowEndMs, db.scheduleTimezone(), "h:mm a")
                statusBanner.text = "✓ Trip: $depDisplay – $arrDisplay (${win.durationHours} hrs)\n" +
                    "✓ Proof window: $arrDisplay – $proofEndDisplay (Opens on arrival)\n" +
                    "✓ Hourly attendance: Suspended $depDisplay – $arrDisplay under travel hold\n" +
                    "Booking deadline: $deadlineStr"
                statusBanner.setTextColor(Color.parseColor(CLR_GREEN))
                statusBanner.background = surfaceBg("#092419", 8, CLR_GREEN, 1)
            } else {
                statusBanner.text = "✕ ${eval.reason}"
                statusBanner.setTextColor(Color.parseColor(CLR_RED))
                statusBanner.background = surfaceBg("#240909", 8, CLR_RED, 1)
            }
        }

        durations.forEach { d ->
            val chip = TextView(this).apply {
                text = "$d hrs"
                textSize = 11f
                setTypeface(typeface, Typeface.BOLD)
                gravity = Gravity.CENTER
                setPadding(dp(12), dp(7), dp(12), dp(7))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                    rightMargin = dp(4)
                }
                setOnClickListener {
                    selectedDurationHours = d
                    updateDurationChips()
                    updateValidationStatus()
                }
            }
            chipViews.add(chip)
            durationRow.addView(chip)
        }
        updateDurationChips()
        dialogView.addView(durationRow)

        val btnChangeDate = TextView(this).apply {
            text = "Pick Date"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            background = surfaceBg(CLR_ELEVATED, 6, CLR_BORDER, 1)
            setPadding(dp(10), dp(5), dp(10), dp(5))
            setOnClickListener {
                val dCal = Calendar.getInstance(tz).apply {
                    try {
                        val d = dateFmt.parse(selectedDate)
                        if (d != null) time = d
                    } catch (_: Exception) {}
                }
                DatePickerDialog(
                    this@MainActivity,
                    { _, y, m, d ->
                        val newCal = Calendar.getInstance(tz).apply {
                            set(Calendar.YEAR, y)
                            set(Calendar.MONTH, m)
                            set(Calendar.DAY_OF_MONTH, d)
                        }
                        selectedDate = dateFmt.format(newCal.time)
                        dateLabel.text = "📅 Date: $selectedDate"
                        updateValidationStatus()
                    },
                    dCal.get(Calendar.YEAR),
                    dCal.get(Calendar.MONTH),
                    dCal.get(Calendar.DAY_OF_MONTH)
                ).show()
            }
        }
        dateRow.addView(btnChangeDate)
        dialogView.addView(dateRow)

        val btnChangeTime = TextView(this).apply {
            text = "Pick Time"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            background = surfaceBg(CLR_ELEVATED, 6, CLR_BORDER, 1)
            setPadding(dp(10), dp(5), dp(10), dp(5))
            setOnClickListener {
                val tParts = selectedTime.split(":")
                val h = tParts.getOrNull(0)?.toIntOrNull() ?: 9
                val m = tParts.getOrNull(1)?.toIntOrNull() ?: 0
                TimePickerDialog(
                    this@MainActivity,
                    { _, hourOfDay, minute ->
                        selectedTime = String.format(Locale.US, "%02d:%02d", hourOfDay, minute)
                        timeLabel.text = "⏰ Departure: $selectedTime"
                        updateValidationStatus()
                    },
                    h,
                    m,
                    true
                ).show()
            }
        }
        timeRow.addView(btnChangeTime)
        dialogView.addView(timeRow)

        dialogView.addView(statusBanner)
        updateValidationStatus()

        dialogView.addView(TextView(this).apply {
            text = "Travel Description"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(4)
            }
        })

        val descInput = EditText(this).apply {
            hint = "e.g. Route, destination, train/bus/car details..."
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            setTextColor(Color.WHITE)
            textSize = 12f
            minLines = 2
            maxLines = 4
            gravity = Gravity.TOP or Gravity.START
            setPadding(dp(10), dp(8), dp(10), dp(8))
            background = surfaceBg(CLR_SURFACE_LOW, 8, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(14)
            }
        }
        dialogView.addView(descInput)

        val actionsRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.END
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }

        var dialogRef: AlertDialog? = null

        val btnCancel = TextView(this).apply {
            text = "Cancel"
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            background = surfaceBg(CLR_SURFACE_LOW, 8, CLR_BORDER, 1)
            setPadding(dp(14), dp(8), dp(14), dp(8))
            setOnClickListener { dialogRef?.dismiss() }
        }
        actionsRow.addView(btnCancel)

        var isSubmitting = false
        val btnConfirm = TextView(this).apply {
            text = "Confirm Pre-booking"
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor("#070A0C"))
            background = surfaceBg(CLR_PURPLE, 8)
            setPadding(dp(16), dp(8), dp(16), dp(8))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                leftMargin = dp(8)
            }
            setOnClickListener {
                if (isSubmitting) return@setOnClickListener
                val desc = descInput.text.toString().trim()
                if (desc.isBlank()) {
                    Toast.makeText(this@MainActivity, "Please enter a travel description.", Toast.LENGTH_SHORT).show()
                    descInput.requestFocus()
                    return@setOnClickListener
                }
                val eval = TravelBookingRules.evaluateBookingWindow(selectedDate, selectedTime, db.authoritativeNowMs(), tz)
                if (!eval.allowed) {
                    Toast.makeText(this@MainActivity, eval.reason, Toast.LENGTH_LONG).show()
                    return@setOnClickListener
                }

                isSubmitting = true
                isEnabled = false
                val res = db.prebookTravel(selectedDate, selectedTime, selectedDurationHours, desc)
                if (res.optBoolean("success", false)) {
                    haptic(1)
                    val msg = res.optString("message", "Travel pre-booked for $selectedDate at $selectedTime ✓")
                    Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show()
                    dialogRef?.dismiss()
                    refreshUi()
                } else {
                    isSubmitting = false
                    isEnabled = true
                    val err = res.optString("error", "Unable to pre-book travel.")
                    Toast.makeText(this@MainActivity, err, Toast.LENGTH_LONG).show()
                }
            }
        }
        actionsRow.addView(btnConfirm)
        dialogView.addView(actionsRow)

        dialogRef = AlertDialog.Builder(this)
            .setView(dialogView)
            .create()
        dialogRef.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
        dialogRef.show()
    }

    private fun showPcShutdownPhotoSourceDialog() {
        AlertDialog.Builder(this)
            .setTitle("Workstation Shutdown Photo Proof")
            .setItems(arrayOf("Take photo (workstation display off)", "Choose from Photos", "Browse image files")) { _, choice ->
                pendingPhotoPurpose = "PC_SHUTDOWN"
                when (choice) {
                    0 -> launchHardwareCamera()
                    1, 2 -> {
                        val action = if (choice == 1) Intent.ACTION_GET_CONTENT else Intent.ACTION_OPEN_DOCUMENT
                        val requestCode = if (choice == 1) REQ_HOURLY_EVIDENCE_PICK else REQ_HOURLY_EVIDENCE_DOCUMENT
                        try {
                            startActivityForResult(
                                Intent(action).apply {
                                    addCategory(Intent.CATEGORY_OPENABLE)
                                    type = "image/*"
                                    putExtra(Intent.EXTRA_MIME_TYPES, arrayOf("image/jpeg", "image/png", "image/webp"))
                                    addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                                },
                                requestCode
                            )
                        } catch (e: Exception) {
                            launchHardwareCamera()
                        }
                    }
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

