        val photoEvId = st.optString("evidence_id", "")
        val bonusStatus = st.optString("bonus_status", "AWAITING_WINDOWS_SHUTDOWN")
        val bonusPts = st.optInt("bonus_points", 15)
        val targetRewardDate = st.optString("target_reward_date", "")

        val scroll = ScrollView(this).apply { isVerticalScrollBarEnabled = true }
        val dialogView = LinearLayout(this).apply {
