        fun addStepRow(stepNum: String, title: String, isDone: Boolean, detail: String, actionBtn: View? = null) {
            val stepCard = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(12), dp(10), dp(12), dp(10))
                background = surfaceBg(CLR_SURFACE, 12, if (isDone) CLR_GREEN else CLR_BORDER, 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(8)
                }
            }
            val stepTop = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
            }
            stepTop.addView(TextView(this@MainActivity).apply {
                text = "${if (isDone) "✓" else "○"} $stepNum. $title"
                textSize = 11.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(if (isDone) CLR_GREEN else CLR_TEXT_PRIMARY))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            })
            stepTop.addView(TextView(this@MainActivity).apply {
                text = if (isDone) "COMPLETE" else "PENDING"
                textSize = 9.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(if (isDone) CLR_GREEN else CLR_AMBER))
            })
            stepCard.addView(stepTop)
            stepCard.addView(TextView(this).apply {
                text = detail
                textSize = 10f
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
                setPadding(0, dp(3), 0, 0)
            })
            if (actionBtn != null) {
                stepCard.addView(actionBtn.apply {
                    (layoutParams as? LinearLayout.LayoutParams)?.topMargin = dp(6)
                })
            }
            dialogView.addView(stepCard)
        }

        val pcDetail = if (shutdownRecorded) {
            if (isQualifying) "Win32 shutdown recorded at $shutdownTime (< $cutoffTime cutoff) ✓"
            else "Win32 shutdown recorded at $shutdownTime (>= $cutoffTime cutoff - Ineligible) ✕"
        } else {
            "Waiting for Windows PC shutdown event from background daemon. Offline shutdowns are reconciled upon reconnection."
        }
        addStepRow("1", "Windows PC Shutdown (< $cutoffTime)", shutdownRecorded && isQualifying, pcDetail)

        var dialogRef: AlertDialog? = null

        val attDetail = if (phoneAttOk) {
            "Attendance confirmed from this Android device (${phoneAttTime.take(19).replace("T", " ")}) ✓"
        } else {
            "Explicit confirmation required from this registered Android device."
        }
        val attBtn = if (!phoneAttOk) {
            makeSecondaryButton("Confirm Phone Attendance", CLR_CYAN) {
                db.confirmPhoneShutdownAttendance(today)
                Toast.makeText(this, "Attendance confirmed! ✓", Toast.LENGTH_SHORT).show()
                dispatchStrictBotEvent("ATTENDANCE_CONFIRMED", "PC shutdown attendance recorded from registered phone.")
