                    topMargin = dp(6)
                    bottomMargin = dp(8)
                }
            }
            devCard.addView(TextView(this).apply {
                text = "ADMIN / DEV CONTROLS"
                textSize = 9f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor("#A855F7"))
            })
            val btnRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(4)
                }
            }
            btnRow.addView(makeSecondaryButton("Simulate PC Shutdown (<11:45)", CLR_CYAN) {
                val fakeTs = "${today}T23:30:00"
                db.recordPcShutdownLocal(today, "sd_sim_${UUID.randomUUID().toString().take(6)}", fakeTs, cutoffTime = "23:45", isQualifying = true)
                Toast.makeText(this@MainActivity, "Simulated 11:30 PM PC shutdown event recorded", Toast.LENGTH_SHORT).show()
                dialogRef?.dismiss()
                refreshUi()
                showPcShutdownDialog()
            }.apply {
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
            })
            btnRow.addView(makeSecondaryButton("Evaluate & Award Bonus", CLR_GREEN) {
                val res = db.awardPcShutdownBonusLocally(today, adminId = "ADMIN_MANUAL")
                if (res.optBoolean("success", false)) {
                    Toast.makeText(this@MainActivity, "+$bonusPts points credited to $targetRewardDate! ✓", Toast.LENGTH_LONG).show()
                    dispatchStrictBotEvent("SUCCESS", "PC shutdown bonus approved: +$bonusPts pts credited to $targetRewardDate.")
                } else {
                    Toast.makeText(this@MainActivity, "Evaluation failed: ${res.optString("reason", res.optString("error"))}", Toast.LENGTH_LONG).show()
                }
                dialogRef?.dismiss()
                refreshUi()
                showPcShutdownDialog()
            }.apply {
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            })
            devCard.addView(btnRow)
            dialogView.addView(devCard)
        }

        val closeBtn = makeSecondaryButton("CLOSE", CLR_GREEN) {
            dialogRef?.dismiss()
        }.apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(8)
            }
        }
        dialogView.addView(closeBtn)

        val dialog = AlertDialog.Builder(this)
            .setView(scroll)
            .create()
        dialogRef = dialog
        dialog.show()
    }

