    private fun showWakeUpPrerequisiteDialog() {
        if (isFinishing || isDestroyed) return
        if (activeWakeUpPrerequisiteDialog?.isShowing == true) return
        activeWakeUpPrerequisiteDialog = AlertDialog.Builder(this)
            .setTitle("Complete Wake-Up Verification first.")
            .setMessage("Today's required wake-up verification is still pending. Complete it before proceeding with this activity.")
            .setPositiveButton("Open Wake-Up Verification") { _, _ ->
                activeWakeUpPrerequisiteDialog = null
                showWakeUpVerificationDialog()
            }
            .setNegativeButton("Cancel") { _, _ ->
                activeWakeUpPrerequisiteDialog = null
            }
            .setOnDismissListener {
                activeWakeUpPrerequisiteDialog = null
            }
            .show()
    }

    private fun showActivityProofDialog(type: String) {
        val date = db.nowDate()
        if (type == "BATH") {
            Toast.makeText(this, "Scheduled Bath is an exempt activity. No proof required.", Toast.LENGTH_SHORT).show()
            return
        }
        if (type == "TRAVEL") {
            if (!db.isTravelPrebooked(date)) {
                Toast.makeText(this, "Travel is only available on pre-booked dates.", Toast.LENGTH_SHORT).show()
                return
            }
            val travelOccurrences = db.getDailyActivities(date).filter { it.type == "TRAVEL" }
            val targetAct = travelOccurrences.firstOrNull()
            if (targetAct != null) {
                val details = runCatching { JSONObject(targetAct.detailsJson) }.getOrNull()
                val depMs = details?.optLong("departure_ms", 0L) ?: 0L
                val durationHours = details?.optInt("duration_hours", 3)?.coerceIn(1, 24) ?: 3
                val travelEndMs = details?.optLong("travel_end_ms", 0L).takeIf { (it ?: 0L) > 0L }
                    ?: (depMs + durationHours * 3600_000L)
                val proofStartMs = details?.optLong("proof_window_start_ms", 0L).takeIf { (it ?: 0L) > 0L }
                    ?: travelEndMs
                val proofEndMs = details?.optLong("proof_window_end_ms", 0L).takeIf { (it ?: 0L) > 0L }
                    ?: (proofStartMs + 2 * 3600_000L)
                val nowMs = db.authoritativeNowMs()
                if (nowMs < proofStartMs) {
                    val mins = ((proofStartMs - nowMs + 59999L) / 60000L).coerceAtLeast(1L)
                    val startStr = ScheduleClock.display(proofStartMs, db.scheduleTimezone(), "h:mm a")
                    Toast.makeText(this, "Travel proof submission opens in $mins minute(s) at $startStr", Toast.LENGTH_LONG).show()
                    return
                }
                if (nowMs >= proofEndMs) {
                    val endStr = ScheduleClock.display(proofEndMs, db.scheduleTimezone(), "h:mm a")
                    Toast.makeText(this, "Travel proof submission window closed at $endStr. Proof is no longer accepted.", Toast.LENGTH_LONG).show()
                    return
                }
            }
            showTravelProofDialog(targetAct)
            return
        }
        if (type == "GYM") {
            val targetAct = db.getActiveOrTargetGymActivity()
            if (targetAct != null) {
                val startMs = db.parseIsoToMs(targetAct.windowStart)
                val nowMs = db.authoritativeNowMs()
                if (startMs > 0L && nowMs < startMs) {
                    val mins = ((startMs - nowMs + 59999L) / 60000L).coerceAtLeast(1L)
                    val startStr = ScheduleClock.display(startMs, db.scheduleTimezone(), "h:mm a")
                    Toast.makeText(this, "Gym proof submission opens in $mins minute(s) at $startStr", Toast.LENGTH_LONG).show()
                    return
                }
            }
            showGymProofDialog(targetAct)
            return
        }
        val occurrence = db.getDailyActivities(date).firstOrNull { it.type == type && it.status == "OPEN" }
            ?: db.getDailyActivities(date).firstOrNull { it.type == type && it.status !in listOf("VERIFIED", "COMPLETED", "CANCELLED", "SKIPPED", "SUBMITTED", "VALIDATING") }
        if (occurrence == null) Toast.makeText(this, "No configured $type occurrence is available. Synchronize the current schedule.", Toast.LENGTH_LONG).show()
        else showHourlySubmissionDialog(occurrence)
    }

    private fun showHourlySubmissionDialog(selectedOccurrence: DisciplineScoringRules.ScheduledActivityItem? = null) {
        if (isFinishing || isDestroyed || !screenResumed) return
        if (selectedOccurrence?.type == "BATH" || selectedOccurrence?.activityId?.contains("BATH") == true) {
            Toast.makeText(this, "Bath is a scheduled exempt activity. No proof required.", Toast.LENGTH_SHORT).show()
            return
        }
        val isExcusedByBath = selectedOccurrence?.let { act ->
            val actDetails = runCatching { JSONObject(act.detailsJson) }.getOrDefault(JSONObject())
            actDetails.optBoolean("suppressed_by_bath", false) ||
                actDetails.optString("reconciliation_status") == "EXCUSED_BY_BATH" ||
                actDetails.optString("attendance_status") == "EXCUSED_BY_BATH" ||
                actDetails.optString("suppression_reason").contains("bath", ignoreCase = true)
        } ?: false
        if (isExcusedByBath || selectedOccurrence?.status == "EXCUSED") {
            Toast.makeText(this, "This proof window overlaps your scheduled Bath activity. No submission required.", Toast.LENGTH_SHORT).show()
            return
        }
        val date = db.nowDate()
        val hour = db.nowTime().take(2).toIntOrNull() ?: 10
        val act = selectedOccurrence ?: db.getActiveOrTargetHourlyActivity(date)
        if (act != null && act.status in listOf("SUBMITTED", "VALIDATING", "VERIFIED", "COMPLETED")) {
            Toast.makeText(this, "Activity is already submitted (${act.status}).", Toast.LENGTH_SHORT).show()
            return
        }
        if (act != null && (act.type.equals("BATH", ignoreCase = true) || act.activityId.contains("BATH", ignoreCase = true))) {
            Toast.makeText(this, "Bath is a scheduled exempt activity; no proof submission is required.", Toast.LENGTH_LONG).show()
            return
        }
        val isActivityProof = act?.type in listOf("BATH", "GYM", "TRAVEL") || (act?.type != null && act.type != "HOURLY")
        val isBath1 = act != null && (act.type == "BATH" || act.activityId.contains("BATH")) && (act.activityId.contains("BATH-1") || !act.activityId.contains("BATH-2"))
        if (isBath1) {
            val collegeChoice = db.getCollegeAttendance(date)
            if (collegeChoice.isBlank()) {
                Toast.makeText(this, "Please confirm today's routine setup first.", Toast.LENGTH_SHORT).show()
                showBathScheduleConfirmationDialog()
                return
            }
            if (collegeChoice == "YES" && !db.isWakeUpVerificationCompleted(date)) {
                showWakeUpPrerequisiteDialog()
                return
            }
        }
        if (act == null) {
            Toast.makeText(this, "No scheduled occurrence is available.", Toast.LENGTH_LONG).show()
            return
        }
        if (act != null && (act.type.equals("WAKE_UP", ignoreCase = true) || act.activityId.contains("WAKEUP", ignoreCase = true))) {
            showWakeUpVerificationDialog()
            return
        }
        if (act != null && act.type.equals("TRAVEL", ignoreCase = true)) {
            showTravelProofDialog(act)
            return
        }
        if (act != null && act.type.equals("GYM", ignoreCase = true)) {
            showGymProofDialog()
            return
        }
        val defaultSlot = String.format(Locale.US, "%02d:00-%02d:00", (hour - 1).coerceAtLeast(0), hour)
        val detailsObj = try {
            if (act != null && act.detailsJson.isNotBlank()) JSONObject(act.detailsJson) else JSONObject()
        } catch (_: Exception) {
            JSONObject()
        }
        val slot = detailsObj.optString("hour_slot", defaultSlot)
        val schedVer = detailsObj.optInt("schedule_version", 1).coerceAtLeast(1)
        val actId = act?.activityId ?: "ACT-${date.replace("-", "")}-${String.format(Locale.US, "%02d", hour)}00-HOURLY"

        if (detailsObj.optBoolean("travel_hold", false)) {
            Toast.makeText(this, "Hourly slot $slot is held for pre-booked travel. Submit travel proof to excuse this interval.", Toast.LENGTH_LONG).show()
            return
        }
        if (detailsObj.optBoolean("movie_hold", false) || act?.status == "EXCUSED") {
            val reason = detailsObj.optString("suppression_reason", "Excused — confirmed movie reservation")
            Toast.makeText(this, "Hourly slot $slot is $reason. Ordinary submission is excused.", Toast.LENGTH_LONG).show()
            return
        }
        if (detailsObj.optBoolean("not_excused", false) || detailsObj.optBoolean("travel_proof_failed", false)) {
            Toast.makeText(this, "Hourly slot $slot was not excused due to missed travel proof.", Toast.LENGTH_LONG).show()
            return
        }

        if (act != null) {
            val sMs = db.parseIsoToMs(act.windowStart)
            val eMs = db.parseIsoToMs(act.windowEnd)
            val nMs = db.authoritativeNowMs()
            val isBath = act.type == "BATH" || act.activityId.contains("BATH")
            val windowIsOpen = (isActivityProof && !isBath) || (nMs in sMs until eMs)

            if (isBath) {
                if (sMs != Long.MIN_VALUE && nMs < sMs) {
                    val openStr = windowClock12h(act.windowStart)
                    Toast.makeText(this, "Bath photo submission window opens at $openStr.", Toast.LENGTH_SHORT).show()
                    return
                }
                if (eMs != Long.MIN_VALUE && nMs >= eMs) {
                    val endStr = windowClock12h(act.windowEnd)
                    Toast.makeText(this, "Bath photo submission window closed at $endStr.", Toast.LENGTH_SHORT).show()
                    return
                }
            } else {
                if (!isActivityProof && sMs != Long.MIN_VALUE && nMs < sMs) {
                    val openStr = windowClock12h(act.windowStart)
                    Toast.makeText(this, "Submission window opens at $openStr for $slot.", Toast.LENGTH_SHORT).show()
                    return
                }
                if (!isActivityProof && eMs != Long.MIN_VALUE && nMs >= eMs) {
                    Toast.makeText(this, "Hourly submission window has expired for $slot.", Toast.LENGTH_SHORT).show()
                    return
                }
            }
            if (act.status in listOf("REJECTED", "REJECTED_LATE") && !windowIsOpen) {
                Toast.makeText(this, "Submission was rejected and window is now closed for $slot.", Toast.LENGTH_SHORT).show()
                return
            }
            if (!isActivityProof && act.status in listOf("MISSED", "CLOSED") && !windowIsOpen) {
                Toast.makeText(this, "Hourly submission window has expired for $slot.", Toast.LENGTH_SHORT).show()
                return
            }
        }

        if (activeHourlyDialog?.isShowing == true) {
            if (activeHourlyDialogActId == actId && activeHourlyDialogScheduleVersion == schedVer) {
                return
            } else {
                activeHourlyCountdownRunnable?.let { uiHandler.removeCallbacks(it) }
                activeHourlyCountdownRunnable = null
                try { activeHourlyDialog?.dismiss() } catch (_: Exception) {}
                activeHourlyDialog = null
            }
        }
        if (pendingProofOccurrenceId != actId) {
            hourlyPendingSubmissionId = null; hourlyPendingSyncEventId = null
            hourlyHasPhoto = false; lastCapturedHourlyPhotoBytes = null; lastCapturedHourlyPhotoName = "evidence.jpg"
            hourlyAttachments.clear()
            pendingProofOccurrenceId = actId
        }
        activeHourlyDialogActId = actId
        activeHourlyDialogScheduleVersion = schedVer

        val wStartStr = windowClock12h(act.windowStart)
        val wEndStr = windowClock12h(act.windowEnd)

        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(22), dp(20), dp(22), dp(18))
            background = surfaceBg(CLR_MODAL, 20, CLR_BORDER, 1)
        }

        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        }
        val mascotIcon = ImageView(this).apply {
            setImageResource(R.drawable.strictbot_head)
            scaleType = ImageView.ScaleType.FIT_CENTER
            layoutParams = LinearLayout.LayoutParams(dp(26), dp(26)).apply { rightMargin = dp(8) }
        }
        headerRow.addView(mascotIcon)
        headerRow.addView(TextView(this).apply {
            text = if (isActivityProof) "${act.type} PROOF" else "⏱️ HOURLY ACTIVITY CHECK-IN"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_GREEN))
            letterSpacing = 0.08f
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        })
        dialogView.addView(headerRow)

        dialogView.addView(TextView(this).apply {
            text = if (isActivityProof) act.title else "Activity Slot: $slot"
            textSize = 17f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(4) }
        })

        dialogView.addView(TextView(this).apply {
            text = "Submission Window: $wStartStr – $wEndStr • ID: $actId (v$schedVer)"
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        })

        val taskBot = StrictBotAnnouncementView(this,
            "Your ${act.title} submission window closes at $wEndStr. Complete the required checks and submit your proof before it closes.",
            "task:$actId:$schedVer")
        dialogView.addView(taskBot, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,
            ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(10) })

        val countdownBadge = TextView(this).apply {
            text = "⏳ Calculating remaining time..."
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_RED))
            setPadding(dp(10), dp(4), dp(10), dp(4))
            background = surfaceBg("#2A1215", 8, CLR_RED, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(10) }
        }
        dialogView.addView(countdownBadge)

        val actS = act?.let { db.parseIsoToMs(it.windowStart) } ?: Long.MAX_VALUE
        val actE = act?.let { db.parseIsoToMs(it.windowEnd) } ?: Long.MIN_VALUE

        val initialReviews = db.getDailyProofReviews(date)
        val initialReviewRecord = initialReviews.firstOrNull { it.optString("activity_id") == actId }
        val initialEvalRecord = db.getProofEvaluationByActivity(actId, date)
        val hasPendingSync = try {
            db.readableDatabase.rawQuery(
                "SELECT 1 FROM sync_events_queue WHERE payload_json LIKE ? AND sync_status = 'PENDING'",
                arrayOf("%$actId%")
            ).use { it.moveToFirst() }
        } catch (_: Throwable) { false }
        val isAlreadySubmitted = act != null && (
            act.status in listOf("SUBMITTED", "VALIDATING", "VERIFIED") ||
            initialReviewRecord != null ||
            initialEvalRecord != null ||
            hasPendingSync
        )
        if (isAlreadySubmitted) taskBot.setMessage("Your ${act.title} proof has already been submitted. Check the review status below.")
        val isApproved = (initialReviewRecord?.optString("decision") == "APPROVED" || initialReviewRecord?.optString("status") in listOf("APPROVED", "VERIFIED") || act?.status == "VERIFIED" || initialEvalRecord?.optString("status") in listOf("VERIFIED", "APPROVED"))
        val isRejected = (initialReviewRecord?.optString("decision") == "REJECTED" || initialReviewRecord?.optString("status") == "REJECTED" || act?.status in listOf("REJECTED", "REJECTED_LATE") || initialEvalRecord?.optString("status") == "REJECTED")
        val awardedPts = initialReviewRecord?.optInt("points_awarded", 0) ?: initialEvalRecord?.optInt("points_awarded", 0) ?: if (isApproved) 8 else 0

        val submittedStatusText = when {
            isApproved -> "✅ PROOF APPROVED (+$awardedPts PTS)"
            isRejected -> "❌ SUBMISSION REJECTED (0 PTS)"
            else -> "⏳ PROOF SUBMITTED — REVIEW PENDING"
        }

        lateinit var btnSubmit: TextView
        var submitButtonReady = false
        val tickRunnable = object : Runnable {
            override fun run() {
                val nowMs = db.authoritativeNowMs()
                val remSec = ((actE - nowMs) / 1000L).coerceAtLeast(0L)
                val untilSec = ((actS - nowMs) / 1000L).coerceAtLeast(0L)
                if (isAlreadySubmitted) {
                    val mm = String.format(Locale.US, "%02d", remSec / 60L)
                    val ss = String.format(Locale.US, "%02d", remSec % 60L)
                    countdownBadge.text = when {
                        isApproved -> "✅ PROOF APPROVED (+$awardedPts PTS) • Window closes at $wEndStr"
                        isRejected -> "🔒 SUBMISSION LOCKED (0 PTS) • Window closes at $wEndStr"
                        else -> "⏳ REVIEW PENDING • Submission locked • Window closes at $wEndStr"
                    }
                    val badgeColor = if (isApproved) CLR_GREEN else if (isRejected) CLR_RED else CLR_AMBER
                    val badgeBg = if (isApproved) "#0F2E1E" else if (isRejected) "#2A1215" else "#2D2415"
                    countdownBadge.setTextColor(Color.parseColor(badgeColor))
                    countdownBadge.background = surfaceBg(badgeBg, 8, badgeColor, 1)
                    if (submitButtonReady) {
                        btnSubmit.isEnabled = false
                        btnSubmit.text = submittedStatusText
                        btnSubmit.background = surfaceBg(if (isApproved) CLR_GREEN else if (isRejected) "#2A1215" else "#1A202C", 10, if (isRejected) CLR_RED else if (!isApproved) CLR_AMBER else null, if (isApproved) 0 else 1)
                        btnSubmit.setTextColor(Color.parseColor(if (isApproved) "#070A0C" else if (isRejected) CLR_RED else CLR_AMBER))
                    }
                } else if (isActivityProof) {
                    countdownBadge.text = "📷 DAILY HABIT PROOF"
                    countdownBadge.setTextColor(Color.parseColor(CLR_CYAN))
                    countdownBadge.background = surfaceBg("#0A1E24", 8, CLR_CYAN, 1)
                    if (submitButtonReady && !hourlySubmissionInProgress) {
                        btnSubmit.isEnabled = true
                        btnSubmit.text = "⚡ Submit Proof for Review"
                        btnSubmit.background = surfaceBg(CLR_GREEN, 10)
                        btnSubmit.setTextColor(Color.parseColor("#070A0C"))
                    }
                } else if (nowMs < actS) {
                    val mm = String.format(Locale.US, "%02d", untilSec / 60L)
                    val ss = String.format(Locale.US, "%02d", untilSec % 60L)
                    countdownBadge.text = "⏰ OPENS IN $mm:$ss"
                    countdownBadge.setTextColor(Color.parseColor(CLR_CYAN))
                    countdownBadge.background = surfaceBg("#0A1E24", 8, CLR_CYAN, 1)
                    if (submitButtonReady) {
                        btnSubmit.isEnabled = false
                        btnSubmit.text = "WINDOW OPENS AT $wStartStr"
                        btnSubmit.background = surfaceBg(CLR_SURFACE_LOW, 10)
                        btnSubmit.setTextColor(Color.parseColor(CLR_TEXT_DIM))
                    }
                } else if (nowMs in actS until actE) {
                    val mm = String.format(Locale.US, "%02d", remSec / 60L)
                    val ss = String.format(Locale.US, "%02d", remSec % 60L)
                    val isWarn = remSec <= 120L
                    countdownBadge.text = "⏳ $mm:$ss REMAINING"
                    countdownBadge.setTextColor(Color.parseColor(if (isWarn) CLR_RED else CLR_GREEN))
                    countdownBadge.background = surfaceBg(if (isWarn) "#2A1215" else "#0F2E1E", 8, if (isWarn) CLR_RED else CLR_GREEN, 1)
                    if (submitButtonReady && !hourlySubmissionInProgress) {
                        btnSubmit.isEnabled = true
                        btnSubmit.text = "⚡ Submit Proof for Review"
                        btnSubmit.background = surfaceBg(CLR_GREEN, 10)
                        btnSubmit.setTextColor(Color.parseColor("#070A0C"))
                    }
                } else {
                    countdownBadge.text = "🔴 WINDOW CLOSED AT $wEndStr"
                    countdownBadge.setTextColor(Color.parseColor(CLR_RED))
                    countdownBadge.background = surfaceBg("#2A1215", 8, CLR_RED, 1)
                    if (submitButtonReady) {
                        btnSubmit.isEnabled = false
                        btnSubmit.text = "HOURLY WINDOW CLOSED"
                        btnSubmit.background = surfaceBg(CLR_SURFACE_LOW, 10)
                        btnSubmit.setTextColor(Color.parseColor(CLR_TEXT_DIM))
                    }
                }
                if (activeHourlyDialog?.isShowing == true) {
                    uiHandler.postDelayed(this, 1000L)
                }
            }
        }
        activeHourlyCountdownRunnable = tickRunnable
        tickRunnable.run()

        val aiProgressHolder = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        dialogView.addView(aiProgressHolder)

        fun refreshAiProgress() {
            aiProgressHolder.removeAllViews()
            val freshEval = db.getProofEvaluationByActivity(actId, date)
            val freshAct = db.getActivityById(actId) ?: act
            val pView = buildAiReviewProgressView(freshEval, freshAct, onRetry = {
                ProofEvaluationManager.retryHourlyEvaluation(this@MainActivity, db, actId, date)
                Toast.makeText(this@MainActivity, "Retrying AI review...", Toast.LENGTH_SHORT).show()
                refreshAiProgress()
            })
            aiProgressHolder.addView(pView)
        }

        if (isAlreadySubmitted) {
            refreshAiProgress()
        }

        val isGym = isActivityProof && act.type.equals("GYM", ignoreCase = true)
        val isTravel = isActivityProof && act.type.equals("TRAVEL", ignoreCase = true)
        val isBath = isActivityProof && act.type.equals("BATH", ignoreCase = true)

        if (isBath) {
            dialogView.addView(TextView(this).apply {
                text = "Attach a photo proof of your bath routine. No description is required."
                textSize = 12f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(12) }
            })
        }

        if (!isGym && !isBath) {
            dialogView.addView(TextView(this).apply {
                text = when {
                    isTravel -> "Travel Description"
                    isActivityProof -> "${act.type} Description"
                    else -> "What did you do during the last hour?"
                }
                textSize = 13f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
            })
        }

        val plannedCategory = when {
            act.title.contains("College", ignoreCase = true) -> "COLLEGE"
            act.title.contains("Study", ignoreCase = true) -> "STUDY"
            act.title.contains("Coding", ignoreCase = true) -> "CODING"
            act.title.contains("Edit", ignoreCase = true) -> "EDITING"
            act.title.contains("Video", ignoreCase = true) -> "VIDEO SHOOT"
            act.type.isNotBlank() && act.type in listOf("COLLEGE", "STUDY", "CODING", "EDITING", "VIDEO SHOOT") -> act.type
            else -> "STUDY"
        }
        val savedCategory = initialReviewRecord?.optString("category")?.ifBlank { null }
            ?: detailsObj.optString("category").ifBlank { null }
            ?: detailsObj.optString("primary_activity").ifBlank { null }
        var chosenAct = if (savedCategory != null) savedCategory else plannedCategory
        val pillViews = mutableListOf<TextView>()
        if (!isActivityProof) {
            val activities = listOf("COLLEGE", "STUDY", "EDITING", "VIDEO SHOOT")
            val pillsContainer = HorizontalScrollView(this).apply {
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(12) }
            }
            val pillsRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
            activities.forEach { actName ->
                val isSel = actName.equals(chosenAct, ignoreCase = true)
                val pill = TextView(this).apply {
                    text = actName
                    textSize = 11f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(if (isSel) Color.WHITE else Color.parseColor(CLR_TEXT_SECONDARY))
                    background = surfaceBg(if (isSel) CLR_INDIGO else CLR_SURFACE_LOW, 14, if (isSel) CLR_INDIGO else "#334155", 1)
                    setPadding(dp(12), dp(6), dp(12), dp(6))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { rightMargin = dp(8) }
                    if (isAlreadySubmitted) {
                        isEnabled = false
                        alpha = if (isSel) 1f else 0.4f
                    } else {
                        setOnClickListener {
                            chosenAct = actName
                            selectedHourlyActivity = actName
                            pillViews.forEach { p ->
                                val sel = p.text.toString() == chosenAct
                                p.setTextColor(if (sel) Color.WHITE else Color.parseColor(CLR_TEXT_SECONDARY))
                                p.background = surfaceBg(if (sel) CLR_INDIGO else CLR_SURFACE_LOW, 14, if (sel) CLR_INDIGO else "#334155", 1)
                            }
                        }
                    }
                }
                pillViews.add(pill)
                pillsRow.addView(pill)
            }
            pillsContainer.addView(pillsRow)
            dialogView.addView(pillsContainer)
        }

        val descInput = EditText(this).apply {
            val submittedDesc = detailsObj.optString("description").ifBlank {
                detailsObj.optString("user_description").ifBlank {
                    initialReviewRecord?.optString("reason_note") ?: ""
                }
            }
            if (isAlreadySubmitted && submittedDesc.isNotBlank()) {
                setText(submittedDesc)
                isEnabled = false
                isFocusable = false
                alpha = 0.7f
            } else {
                hint = when {
                    isTravel -> "Enter travel details, commute route or destination..."
                    isActivityProof -> "Describe your ${act.type.lowercase()} details..."
                    else -> "Describe what you worked on, studied, or completed..."
                }
                setHintTextColor(Color.parseColor("#64748B"))
            }
            setTextColor(Color.WHITE)
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 12f)
            setPadding(dp(14), dp(12), dp(14), dp(12))
            background = surfaceBg("#0A0B10", 10, "#334155", 1)
            minLines = if (isTravel) 2 else 3
            gravity = Gravity.TOP or Gravity.START
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(12) }
        }
        if (!isGym && !isBath) {
            dialogView.addView(descInput)
        }

        val photoStatusLabel = TextView(this).apply {
            text = if (isAlreadySubmitted) "📎 Photo proof submitted ✓" else if (lastCapturedHourlyPhotoBytes != null) "📎 ${lastCapturedHourlyPhotoName} attached ✓" else "Required: Attach an image"
            textSize = 11f
            setTextColor(if (isAlreadySubmitted || lastCapturedHourlyPhotoBytes != null) Color.parseColor(CLR_GREEN) else Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        }
        hourlyAttachmentStatusView = photoStatusLabel
        dialogView.addView(photoStatusLabel)

        val btnAttachPhoto = TextView(this).apply {
            text = if (isAlreadySubmitted) "🔒 Evidence Submitted & Locked" else "📎 Choose Image / Capture Photo"
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(if (isAlreadySubmitted) Color.parseColor(CLR_TEXT_DIM) else Color.WHITE)
            gravity = Gravity.CENTER
            setPadding(dp(14), dp(8), dp(14), dp(8))
            background = surfaceBg(CLR_SURFACE_LOW, 10, if (isAlreadySubmitted) "#334155" else "#475569", 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(10) }
            if (isAlreadySubmitted) {
                isEnabled = false
                alpha = 0.5f
            } else {
                setOnClickListener {
                    showHourlyEvidenceSourceDialog()
                }
            }
        }
        dialogView.addView(btnAttachPhoto)

        val previewsContainer = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
        }
        val previewsScroll = HorizontalScrollView(this).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(10) }
            visibility = View.GONE
            addView(previewsContainer)
        }
        hourlyPreviewsContainer = previewsContainer
        hourlyPreviewsScrollView = previewsScroll
        dialogView.addView(previewsScroll)
        if (hourlyAttachments.isEmpty() && lastCapturedHourlyPhotoBytes != null) {
            hourlyAttachments.add(AttachedProof(lastCapturedHourlyPhotoBytes!!, lastCapturedHourlyPhotoName.ifBlank { "evidence.jpg" }))
        }
        refreshHourlyPreviews()

        val taufaStatusBadge = TextView(this).apply {
            textSize = 10.5f
            setTypeface(typeface, Typeface.BOLD)
            setPadding(dp(8), dp(4), dp(8), dp(4))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }
        dialogView.addView(taufaStatusBadge)

        fun updateTaufaBadge() {
            val isEvaluating = hourlySubmissionInProgress || (initialEvalRecord?.optString("status") in listOf(
                ProofSubmissionRules.States.EVALUATING, "VALIDATING"))
            val isFailed = initialEvalRecord?.optString("status") == ProofSubmissionRules.States.RETRYABLE_FAILURE ||
                    initialReviewRecord?.optString("status") == "RETRYABLE_FAILURE" ||
                    (initialEvalRecord?.optString("evaluator_output_json")?.contains("PENDING RETRY") == true)
            val isCfg = TaufaAiValidator.isConfigured(this@MainActivity)

            val preflight = ProofWindowPreflightManager.getPreflightRecord(this@MainActivity, actId)

            when {
                isEvaluating -> {
                    taufaStatusBadge.text = "🔵 Taufa connected · Evaluating"
                    taufaStatusBadge.setTextColor(Color.parseColor(CLR_CYAN))
                    taufaStatusBadge.background = surfaceBg("#0A1E24", 6, CLR_CYAN, 1)
                }
                isFailed -> {
                    taufaStatusBadge.text = "🔴 Taufa connection failed · Retry available"
                    taufaStatusBadge.setTextColor(Color.parseColor(CLR_RED))
                    taufaStatusBadge.background = surfaceBg("#2A1215", 6, CLR_RED, 1)
                }
                preflight != null -> {
                    when (preflight.selectedValidationProvider) {
                        "TAUFA_AI" -> {
                            val backupText = if (preflight.backupProvider.isNotBlank() && preflight.backupProvider != "NONE") " (OPENAI BACKUP)" else ""
                            taufaStatusBadge.text = "🟢 AI PREFLIGHT: TAUFA CONNECTED$backupText"
                            taufaStatusBadge.setTextColor(Color.parseColor(CLR_GREEN))
                            taufaStatusBadge.background = surfaceBg("#0F2E1E", 6, CLR_GREEN, 1)
                        }
                        "OPENAI_FALLBACK" -> {
                            taufaStatusBadge.text = "🟢 AI FALLBACK READY: OPENAI CONNECTED"
                            taufaStatusBadge.setTextColor(Color.parseColor(CLR_GREEN))
                            taufaStatusBadge.background = surfaceBg("#0F2E1E", 6, CLR_GREEN, 1)
                        }
                        else -> {
                            taufaStatusBadge.text = "🟡 AI SERVICES UNAVAILABLE · SUBMISSION PROTECTED"
                            taufaStatusBadge.setTextColor(Color.parseColor(CLR_AMBER))
                            taufaStatusBadge.background = surfaceBg("#2D2415", 6, CLR_AMBER, 1)
                        }
                    }
                }
                !isCfg -> {
                    taufaStatusBadge.text = "⚠️ Taufa not configured · Connect paired PC"
                    taufaStatusBadge.setTextColor(Color.parseColor(CLR_AMBER))
                    taufaStatusBadge.background = surfaceBg("#2D2415", 6, CLR_AMBER, 1)
                }
                else -> {
                    val cached = TaufaPcBridge.cachedStatus ?: TaufaPcBridge.statusFromHealthRecord(AiServiceHealthManager.getCachedHealthRecord(this@MainActivity))
                    AiServiceHealthManager.refreshIfStaleAsync(this@MainActivity, "proof_dialog_open")
                    if (cached != null) {
                        if (cached.ready) {
                            taufaStatusBadge.text = "🟢 ${cached.uiStatus}"
                            taufaStatusBadge.setTextColor(Color.parseColor(CLR_GREEN))
                            taufaStatusBadge.background = surfaceBg("#0F2E1E", 6, CLR_GREEN, 1)
                        } else {
                            taufaStatusBadge.text = "🟡 ${cached.uiStatus}"
                            taufaStatusBadge.setTextColor(Color.parseColor(CLR_AMBER))
                            taufaStatusBadge.background = surfaceBg("#2D2415", 6, CLR_AMBER, 1)
                        }
                    } else {
                        taufaStatusBadge.text = "🟡 Taufa configured · Connection unavailable"
                        taufaStatusBadge.setTextColor(Color.parseColor(CLR_AMBER))
                        taufaStatusBadge.background = surfaceBg("#2D2415", 6, CLR_AMBER, 1)
                        Thread {
                            val st = TaufaPcBridge.checkStatus(this@MainActivity)
                            runOnUiThread {
                                if (st.ready) {
                                    taufaStatusBadge.text = "🟢 ${cached.uiStatus}"
                                    taufaStatusBadge.setTextColor(Color.parseColor(CLR_GREEN))
                                    taufaStatusBadge.background = surfaceBg("#0F2E1E", 6, CLR_GREEN, 1)
                                } else {
                                    taufaStatusBadge.text = "🟡 ${cached.uiStatus}"
                                    taufaStatusBadge.setTextColor(Color.parseColor(CLR_AMBER))
                                    taufaStatusBadge.background = surfaceBg("#2D2415", 6, CLR_AMBER, 1)
                                }
                            }
                        }.start()
                    }
                }
            }
        }
        updateTaufaBadge()

        val aiNotice = TextView(this).apply {
            text = "ℹ️ Hourly attendance photos and description are evaluated by AI for consistency."
            textSize = 10f
            setTextColor(Color.parseColor(CLR_TEXT_DIM))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        }
        dialogView.addView(aiNotice)

        val aiReviewStatusLabel = TextView(this).apply {
            text = when {
                isApproved -> "Status: VERIFIED (+${awardedPts} pts) • Review Completed ✓"
                isRejected -> "Status: REJECTED (0 pts) • ${initialReviewRecord?.optString("reason_note")?.ifBlank { "Validation failed" } ?: "Validation failed"}"
                isAlreadySubmitted -> "Status: SUBMITTED • AI Review in progress"
                hourlyAttachments.isNotEmpty() -> "Status: OPEN • ${hourlyAttachments.size} image(s) attached — ready for validation."
                else -> "Status: OPEN • Evidence Check: Attach an image to inspect"
            }
            textSize = 11f
            setTextColor(Color.parseColor(if (isApproved) CLR_GREEN else if (isRejected) CLR_RED else if (isAlreadySubmitted || hourlyAttachments.isNotEmpty()) CLR_CYAN else CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(12) }
        }
        activeHourlyReviewLabel = aiReviewStatusLabel
        dialogView.addView(aiReviewStatusLabel)

        var dialogRef: AlertDialog? = null
        val actionsRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.END
        }

        val btnCancel = TextView(this).apply {
            text = "Cancel"
            textSize = 12f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            setPadding(dp(14), dp(8), dp(14), dp(8))
            setOnClickListener { dialogRef?.dismiss() }
        }
        actionsRow.addView(btnCancel)

        btnSubmit = TextView(this).apply {
            val initNowMs = db.authoritativeNowMs()
            val isOpen = isActivityProof || (initNowMs in actS until actE)
            val btnActionText = if (isAlreadySubmitted) submittedStatusText else if (isOpen) "⚡ Submit Proof for Review" else if (initNowMs < actS) "WINDOW OPENS AT $wStartStr" else "HOURLY WINDOW CLOSED"
            text = btnActionText
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            val btnColor = if (isAlreadySubmitted) (if (isApproved) "#070A0C" else if (isRejected) CLR_RED else CLR_AMBER) else if (isOpen) "#070A0C" else CLR_TEXT_DIM
            val btnBg = if (isAlreadySubmitted) surfaceBg(if (isApproved) CLR_GREEN else if (isRejected) "#2A1215" else "#1A202C", 10, if (isRejected) CLR_RED else if (!isApproved) CLR_AMBER else null, if (isApproved) 0 else 1) else surfaceBg(if (isOpen) CLR_GREEN else CLR_SURFACE_LOW, 10)
            setTextColor(Color.parseColor(btnColor))
            gravity = Gravity.CENTER
            setPadding(dp(16), dp(8), dp(16), dp(8))
            background = btnBg
            isEnabled = isOpen && !isAlreadySubmitted
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { leftMargin = dp(8) }
            setOnClickListener {
                if (hourlySubmissionInProgress) return@setOnClickListener
                if (isAlreadySubmitted) {
                    Toast.makeText(this@MainActivity, "Proof has already been submitted for this slot. Submissions are locked.", Toast.LENGTH_SHORT).show()
                    return@setOnClickListener
                }
                val clickNowMs = db.authoritativeNowMs()
                if (!isActivityProof) {
                    if (clickNowMs < actS) {
                        Toast.makeText(this@MainActivity, "Submission window has not opened yet (opens at $wStartStr).", Toast.LENGTH_SHORT).show()
                        return@setOnClickListener
                    }
                    if (clickNowMs >= actE) {
                        Toast.makeText(this@MainActivity, "Hourly submission window has closed ($wEndStr). Late submissions cannot be accepted.", Toast.LENGTH_SHORT).show()
                        return@setOnClickListener
                    }
                }
                val rawDesc = descInput.text?.toString()?.trim() ?: ""
                if (!isActivityProof) {
                    val descValidation = TaufaAiValidator.validateDescription(rawDesc)
                    if (!descValidation.first) {
                        Toast.makeText(this@MainActivity, descValidation.second, Toast.LENGTH_LONG).show()
                        return@setOnClickListener
                    }
                } else if (rawDesc.isBlank() && !isGym && !isBath) {
                    Toast.makeText(this@MainActivity, if (isTravel) "Travel description is required." else if (isActivityProof) "Description is required for ${act.type}." else "Describe what you did during the last hour.", Toast.LENGTH_LONG).show()
                    return@setOnClickListener
                }
                val desc = when {
                    rawDesc.isNotBlank() -> rawDesc
                    isGym -> "Gym workout proof"
                    isBath -> "Bath completed"
                    else -> rawDesc
                }
                if (!isActivityProof && chosenAct.isBlank()) {
                    Toast.makeText(this@MainActivity, "Select an activity category.", Toast.LENGTH_LONG).show()
                    return@setOnClickListener
                }

                val attachmentsToProcess = if (hourlyAttachments.isNotEmpty()) {
                    hourlyAttachments.toList()
                } else if (lastCapturedHourlyPhotoBytes != null && lastCapturedHourlyPhotoBytes!!.isNotEmpty()) {
                    listOf(AttachedProof(lastCapturedHourlyPhotoBytes!!, lastCapturedHourlyPhotoName.ifBlank { "evidence.jpg" }))
                } else {
                    emptyList()
                }
                if (attachmentsToProcess.isEmpty()) {
                    val msg = when {
                        act.type.equals("BATH", ignoreCase = true) -> "A valid photo proof is mandatory for Bath. Text descriptions alone are not accepted."
                        act.type.equals("GYM", ignoreCase = true) -> "A valid photo proof is mandatory for Gym. Text descriptions alone are not accepted."
                        act.type.equals("TRAVEL", ignoreCase = true) -> "A valid photo proof is mandatory for Travel. Text descriptions alone are not accepted."
                        else -> "Attach at least one image or supported evidence file."
                    }
                    Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show()
                    return@setOnClickListener
                }
                if (attachmentsToProcess.size > 10) {
                    Toast.makeText(this@MainActivity, "Cannot attach more than 10 photos per submission.", Toast.LENGTH_LONG).show()
                    return@setOnClickListener
                }
                val maxBaths = db.getMaxBathOccurrences(date)
                if (act.type.equals("BATH", ignoreCase = true) && db.getBathSubmissionCount(date) >= maxBaths) {
                    Toast.makeText(this@MainActivity, "Daily bath limit reached ($maxBaths/$maxBaths completed).", Toast.LENGTH_LONG).show()
                    return@setOnClickListener
                }
                if (attachmentsToProcess.any { it.bytes.size > 25 * 1024 * 1024 }) {
                    Toast.makeText(this@MainActivity, "One or more evidence files exceed the 25 MB limit.", Toast.LENGTH_LONG).show()
                    return@setOnClickListener
                }
                // The server receipt timestamp and scheduled window are authoritative.
                // Device clock drift must not block an upload that the server would accept.
                if (!isActivityProof) {
                    val timing = db.evaluateSubmissionTiming(actId, clickNowMs, recordLocally = false)
                    if (!timing.allowed && hourlyPendingSyncEventId == null) {
                        Toast.makeText(this@MainActivity, timing.message, Toast.LENGTH_LONG).show()
                        return@setOnClickListener
                    }
                }
                hourlySubmissionInProgress = true
                btnSubmit.isEnabled = false
                btnSubmit.text = "⏳ SUBMITTING PROOF..."
                btnSubmit.background = surfaceBg("#1A202C", 10, CLR_AMBER, 1)
                btnSubmit.setTextColor(Color.parseColor(CLR_AMBER))
                Toast.makeText(this@MainActivity, "Submitting proof...", Toast.LENGTH_SHORT).show()

                Thread {
                    try {
                        val receipt = ProofEvaluationManager.submitHourlyProof(
                            context = this@MainActivity,
                            db = db,
                            actId = actId,
                            actType = act.type,
                            category = chosenAct,
                            description = desc,
                            attachments = attachmentsToProcess,
                            date = date,
                            isDevMode = isDevMode,
                            schedVer = schedVer,
                            slot = slot
                        )
                        uiHandler.post {
                            hourlySubmissionInProgress = false
                            if (!receipt.success) {
                                btnSubmit.isEnabled = isOpen && !isAlreadySubmitted
                                btnSubmit.text = if (isOpen) "⚡ SUBMIT PROOF" else "SUBMIT"
                                btnSubmit.background = btnBg
                                btnSubmit.setTextColor(Color.parseColor(btnColor))
                                Toast.makeText(this@MainActivity, receipt.message, Toast.LENGTH_LONG).show()
                                try { refreshUi() } catch (_: Throwable) {}
                                return@post
                            }

                            try { WakeUpAlarmReceiver.cancelHourlyNotifications(this@MainActivity) } catch (_: Exception) {}
                            hourlyPendingSubmissionId = null
                            hourlyPendingSyncEventId = null
                            lastCapturedHourlyPhotoBytes = null
                            lastCapturedHourlyPhotoName = "evidence.jpg"
                            hourlyAttachments.clear()
                            hourlyHasPhoto = false
                            try { updateHourlyEvidenceLabels() } catch (_: Throwable) {}
                            selectedHourlyActivity = ""
                            haptic(1)
                            dispatchStrictBotEvent("PROOF_ACCEPTED", receipt.message)
                            Toast.makeText(this@MainActivity, receipt.message, Toast.LENGTH_LONG).show()
                            refreshAiProgress()
                            btnSubmit.isEnabled = false
                            btnSubmit.text = "⏳ AI REVIEW IN PROGRESS (0 PTS)"
                            btnSubmit.background = surfaceBg("#1A202C", 10, CLR_AMBER, 1)
                            btnSubmit.setTextColor(Color.parseColor(CLR_AMBER))
                            try { updateCountdownViews() } catch (_: Throwable) {}
                            try { refreshUi() } catch (_: Throwable) {}
                        }
                    } catch (t: Throwable) {
                        Log.e("MainActivity", "Hourly proof submission failed", t)
                        uiHandler.post {
                            hourlySubmissionInProgress = false
                            btnSubmit.isEnabled = isOpen && !isAlreadySubmitted
                            btnSubmit.text = if (isOpen) "⚡ SUBMIT PROOF" else "SUBMIT"
                            btnSubmit.background = btnBg
                            btnSubmit.setTextColor(Color.parseColor(btnColor))
                            Toast.makeText(this@MainActivity, "Submission error: ${t.message}", Toast.LENGTH_LONG).show()
                            try { refreshUi() } catch (_: Throwable) {}
                        }
                    }
                }.start()
            }
        }
        actionsRow.addView(btnSubmit)
        submitButtonReady = true
        dialogView.addView(actionsRow)

        val dialogScrollView = ScrollView(this).apply {
            layoutParams = ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            isFillViewport = true
            addView(dialogView)
        }

        val progressListener: (ProofSubmissionRules.EvaluationEvent) -> Unit = { evt ->
            if (evt.activityId == actId) {
                runOnUiThread {
                    refreshAiProgress()
                    val isAppr = evt.status == ProofSubmissionRules.States.APPROVED
                    val isRej = evt.status == ProofSubmissionRules.States.REJECTED
                    val isFail = evt.status == ProofSubmissionRules.States.RETRYABLE_FAILURE
                    if (isAppr) {
                        btnSubmit.isEnabled = false
                        btnSubmit.text = if (evt.pointsAwarded == 8) "✅ PROOF APPROVED (FULL POINTS)" else "✅ PROOF APPROVED (+${evt.pointsAwarded} PTS)"
                        btnSubmit.background = surfaceBg(CLR_GREEN, 10)
                        btnSubmit.setTextColor(Color.parseColor("#070A0C"))
                    } else if (isRej) {
                        btnSubmit.isEnabled = false
                        btnSubmit.text = "❌ PROOF REJECTED (0 PTS)"
                        btnSubmit.background = surfaceBg("#2A1215", 10, CLR_RED, 1)
                        btnSubmit.setTextColor(Color.parseColor(CLR_RED))
                    } else if (isFail) {
                        btnSubmit.isEnabled = true
                        btnSubmit.text = "🔄 RETRY AI REVIEW"
                        btnSubmit.background = surfaceBg(CLR_CYAN, 10)
                        btnSubmit.setTextColor(Color.parseColor("#070A0C"))
                    }
                }
            }
        }
        val preflightListener: (ProofWindowPreflightManager.PreflightRecord) -> Unit = { prec ->
            if (prec.activityId == actId) {
                runOnUiThread {
                    if (!isFinishing && !isDestroyed && activeHourlyDialog != null) {
                        try {
                            updateTaufaBadge()
                        } catch (t: Throwable) {
                            Log.w("StrictRecords", "updateTaufaBadge error: ${t.message}")
                        }
                    }
                }
            }
        }
        ProofWindowPreflightManager.addListener(preflightListener)
        ProofEvaluationManager.addListener(progressListener)

        dialogRef = AlertDialog.Builder(this)
            .setView(dialogScrollView)
            .create()
        activeHourlyDialog = dialogRef
        dialogRef?.setOnDismissListener {
            ProofWindowPreflightManager.removeListener(preflightListener)
            ProofEvaluationManager.removeListener(progressListener)
            activeHourlyCountdownRunnable?.let { uiHandler.removeCallbacks(it) }
            activeHourlyCountdownRunnable = null
            hourlyPreviewsContainer = null
            hourlyPreviewsScrollView = null
            if (activeHourlyDialog === dialogRef) {
                activeHourlyDialog = null
            }
        }
        dialogRef?.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
        if (!isFinishing && !isDestroyed && screenResumed) {
            dialogRef?.show()
            uiHandler.post(tickRunnable)
        }
    }

    private fun showTravelProofDialog(selectedActivity: DisciplineScoringRules.ScheduledActivityItem? = null) {
        val date = selectedActivity?.date?.ifBlank { db.nowDate() } ?: db.nowDate()
        if (!db.isTravelPrebooked(date)) {
            Toast.makeText(this, "Travel is only available on pre-booked dates.", Toast.LENGTH_SHORT).show()
            return
        }
        val travelOccurrences = db.getDailyActivities(date).filter { it.type == "TRAVEL" }
        val targetAct = selectedActivity ?: travelOccurrences.firstOrNull()
        val travelDone = (targetAct?.status in listOf("VERIFIED", "COMPLETED", "SUBMITTED", "VALIDATING", "PENDING_SYNC")) ||
            (selectedActivity == null && travelOccurrences.any { it.status in listOf("VERIFIED", "COMPLETED", "SUBMITTED", "VALIDATING", "PENDING_SYNC") })
        if (travelDone) {
            Toast.makeText(this, "Travel proof submitted — AI review processing ✓", Toast.LENGTH_SHORT).show()
            return
        }
        if (targetAct != null) {
            val details = runCatching { JSONObject(targetAct.detailsJson) }.getOrNull()
            val startMs = details?.optLong("proof_window_start_ms", 0L).takeIf { (it ?: 0L) > 0L }
                ?: details?.optLong("travel_end_ms", 0L).takeIf { (it ?: 0L) > 0L }
                ?: db.parseIsoToMs(targetAct.windowStart)
            val endMs = details?.optLong("proof_window_end_ms", 0L).takeIf { (it ?: 0L) > 0L }
                ?: (startMs + 2 * 3600_000L)
            val nowMs = db.authoritativeNowMs()
            if (nowMs < startMs) {
                val mins = ((startMs - nowMs + 59999L) / 60000L).coerceAtLeast(1L)
                val startStr = ScheduleClock.display(startMs, db.scheduleTimezone(), "h:mm a")
                Toast.makeText(this, "Travel proof submission opens in $mins minute(s) at $startStr", Toast.LENGTH_LONG).show()
                return
            }
            if (nowMs >= endMs) {
                val endStr = ScheduleClock.display(endMs, db.scheduleTimezone(), "h:mm a")
                Toast.makeText(this, "Travel proof submission window closed at $endStr. Proof is no longer accepted.", Toast.LENGTH_LONG).show()
                return
            }
        }

        travelProofBytes = null
        travelProofName = "travel_proof.jpg"
        travelSubmissionInProgress = false

        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(22), dp(20), dp(22), dp(18))
            background = surfaceBg(CLR_MODAL, 20, CLR_BORDER, 1)
        }

        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
        }
        val mascotIcon = ImageView(this).apply {
            setImageResource(R.drawable.strictbot_head)
            scaleType = ImageView.ScaleType.FIT_CENTER
            layoutParams = LinearLayout.LayoutParams(dp(28), dp(28)).apply { rightMargin = dp(10) }
        }
        headerRow.addView(mascotIcon)
        headerRow.addView(TextView(this).apply {
            text = "🚗 TRAVEL CHECK-IN"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_PURPLE))
            letterSpacing = 0.06f
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        })
        dialogView.addView(headerRow)

        dialogView.addView(TextView(this).apply {
            text = "Travel Proof Submission"
            textSize = 17f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(4) }
        })

        dialogView.addView(TextView(this).apply {
            text = "Provide a brief description of your travel or commute and attach a photo proof (e.g. vehicle, transit ticket, route, or destination)."
            textSize = 12f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(14) }
        })

        // Description Section
        dialogView.addView(TextView(this).apply {
            text = "Travel Description"
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        })

        val descInput = EditText(this).apply {
            hint = "Brief travel description (e.g. commute route, destination, purpose)..."
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            setTextColor(Color.WHITE)
            textSize = 13f
            minLines = 2
            maxLines = 4
            gravity = Gravity.TOP or Gravity.START
            setPadding(dp(12), dp(10), dp(12), dp(10))
            background = surfaceBg(CLR_SURFACE_LOW, 10, "#334155", 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(14) }
            val prebookedDesc = travelOccurrences.firstOrNull { it.type == "TRAVEL" }?.let {
                val d = runCatching { JSONObject(it.detailsJson) }.getOrNull()
                d?.optString("prebooked_description", d?.optString("description", "") ?: "")
            }.orEmpty()
            if (prebookedDesc.isNotBlank()) {
                setText(prebookedDesc)
            }
        }
        dialogView.addView(descInput)

        // Photo Proof Section
        dialogView.addView(TextView(this).apply {
            text = "Image Proof"
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        })

