            setOnClickListener {
                travelDialogRef?.dismiss()
            }
        }
        actionsRow.addView(btnCancel)

        lateinit var btnSubmit: TextView
        btnSubmit = TextView(this).apply {
            text = "⚡ Submit Travel Proof"
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor("#070A0C"))
            background = surfaceBg(CLR_GREEN, 10)
            setPadding(dp(18), dp(10), dp(18), dp(10))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { leftMargin = dp(8) }
            setOnClickListener {
                val desc = descInput.text.toString().trim()
                if (desc.isBlank()) {
                    Toast.makeText(this@MainActivity, "Please enter a travel description.", Toast.LENGTH_SHORT).show()
                    descInput.requestFocus()
                    return@setOnClickListener
                }
                val photoBytes = travelProofBytes
                if (photoBytes == null || photoBytes.isEmpty()) {
                    Toast.makeText(this@MainActivity, "A valid image proof is mandatory for Travel.", Toast.LENGTH_SHORT).show()
                    return@setOnClickListener
                }
                val actId = targetAct?.activityId ?: db.ensureTravelOccurrence(date)
                if (actId.isBlank()) {
                    Toast.makeText(this@MainActivity, "No valid travel booking found for today. Travel proof requires a pre-booked trip.", Toast.LENGTH_LONG).show()
                    return@setOnClickListener
                }
                val timing = db.evaluateSubmissionTiming(actId, db.authoritativeNowMs(), recordLocally = false)
                if (!timing.allowed) {
                    Toast.makeText(this@MainActivity, timing.message, Toast.LENGTH_LONG).show()
                    return@setOnClickListener
                }
                if (travelSubmissionInProgress) return@setOnClickListener
                travelSubmissionInProgress = true
                btnSubmit.isEnabled = false
                btnSubmit.text = "Submitting..."
                btnCancel.isEnabled = false
                dispatchStrictBotEvent("EVIDENCE_ANALYZING")

                Thread {
                    val subId = "sub_and_${UUID.randomUUID().toString().replace("-", "").take(20)}"
                    val evId = "ev_${subId.takeLast(12)}"

                    val previewBase64 = try {
                        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
                        BitmapFactory.decodeByteArray(photoBytes, 0, photoBytes.size, bounds)
                        var sampleSize = 1
                        val maxOriginalDim = maxOf(bounds.outWidth, bounds.outHeight)
                        while (maxOriginalDim / sampleSize > 1280) { sampleSize *= 2 }
                        val decodeOpts = BitmapFactory.Options().apply { inSampleSize = sampleSize }
                        val bmp = BitmapFactory.decodeByteArray(photoBytes, 0, photoBytes.size, decodeOpts)
                        if (bmp != null) {
                            val outStream = ByteArrayOutputStream()
                            var quality = 80
                            bmp.compress(Bitmap.CompressFormat.JPEG, quality, outStream)
                            while (outStream.size() > 400 * 1024 && quality > 30) {
                                outStream.reset()
                                quality -= 15
                                bmp.compress(Bitmap.CompressFormat.JPEG, quality, outStream)
                            }
                            bmp.recycle()
                            Base64.encodeToString(outStream.toByteArray(), Base64.NO_WRAP)
                        } else {
                            Base64.encodeToString(photoBytes.take(200 * 1024).toByteArray(), Base64.NO_WRAP)
                        }
                    } catch (_: Throwable) { "" }

                    val targetDetails = runCatching { JSONObject(targetAct?.detailsJson ?: "{}") }.getOrDefault(JSONObject())
                    val bookingId = targetDetails.optString("booking_id")
                    val schedVer = if ((targetAct?.scheduleVersion ?: 0) > 0) targetAct!!.scheduleVersion else db.getScheduleIdAndVersionForDate(date).second
                    val depTime = targetDetails.optString("departure_time")
                    val durHours = targetDetails.optInt("duration_hours", 3)
                    val hourSlot = if (depTime.isNotBlank()) "$depTime (${durHours}h)" else "TRAVEL"

                    val payload = JSONObject().apply {
                        put("submission_id", subId)
                        put("evidence_id", evId)
                        put("activity_id", actId)
                        if (bookingId.isNotBlank()) put("booking_id", bookingId)
                        put("task_type", "TRAVEL")
                        put("date", date)
                        put("is_dev_mode", isDevMode)
                        put("schedule_version", schedVer)
                        put("hour_slot", hourSlot)
                        put("category", "TRAVEL")
                        put("primary_activity", "TRAVEL")
                        put("description", desc)
                        put("evidence_filename", travelProofName)
                        put("image_count", 1)
                        put("image_base64", previewBase64)
                    }

                    val syncEventId = db.enqueueSyncEvent("ACTIVITY_PROOF_SUBMITTED", payload, this@MainActivity)
                    try {
                        val nowIsoStr = db.formatMsToIso(db.authoritativeNowMs())
                        db.writableDatabase.execSQL(
                            "UPDATE scheduled_activities SET status='SUBMITTED', submitted_at=? WHERE activity_id=? OR (date=? AND type='TRAVEL')",
                            arrayOf(nowIsoStr, actId, date)
                        )
                        db.reconcileHourlyTravelConflicts(date)
                    } catch (_: Throwable) {}

                    var analysis = JSONObject()
                    try {
                        analysis = db.analyzeAndRecordEvidence(
                            evidenceId = evId,
                            submissionId = subId,
                            activityId = actId,
                            date = date,
                            category = "TRAVEL",
                            description = desc,
                            fileName = travelProofName,
                            mimeType = "image/jpeg",
                            bytes = photoBytes,
                            userDescription = "[TRAVEL] $desc"
                        )
                        db.reconcileHourlyTravelConflicts(date)
                    } catch (_: Throwable) {}
                    try { db.flushSyncEventsQueue(this@MainActivity) } catch (_: Throwable) {}
                    runOnUiThread {
                        if (isFinishing || isDestroyed) return@runOnUiThread
                        travelSubmissionInProgress = false
                        haptic(1)
                        val pts = analysis.optInt("points_awarded", 0)
                        val msg = if (pts > 0) "✓ Travel proof validated! +$pts points added." else "Travel proof submitted for review ✓"
                        Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show()
                        dispatchStrictBotEvent("PROOF_ACCEPTED", if (pts > 0) "Travel proof validated (+$pts pts)." else "Travel proof submitted.")
                        try { travelDialogRef?.dismiss() } catch (_: Throwable) {}
                        travelDialogRef = null
                        try { refreshUi() } catch (_: Throwable) {}
                    }
                }.start()
            }
        }
        actionsRow.addView(btnSubmit)
        dialogView.addView(actionsRow)

        val dialog = AlertDialog.Builder(this)
            .setView(dialogView)
            .create()
        travelDialogRef = dialog
        dialog.setOnDismissListener {
            travelDialogRef = null
            travelPhotoStatusView = null
            travelPhotoPreviewView = null
        }
        dialog.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
        dialog.show()
    }

    private fun showGymProofDialog(selectedActivity: DisciplineScoringRules.ScheduledActivityItem? = null) {
        val targetAct = selectedActivity ?: db.getActiveOrTargetGymActivity()
        val date = targetAct?.date ?: db.nowDate()
        val actId = targetAct?.activityId ?: db.ensureGymOccurrence(date)
        val gymOccurrences = listOfNotNull(targetAct).ifEmpty { db.getDailyActivities(date).filter { it.type == "GYM" } }
        val gymDone = gymOccurrences.any { it.status in listOf("VERIFIED", "COMPLETED", "SUBMITTED", "VALIDATING") }
        if (gymDone) {
            MiFitnessGymWorkoutController.showGymProofDetailsDialog(this, db, targetAct)
            return
