    private fun triggerServerSync() {
        triggerBotMessage("Syncing your records...", "SYNCING")
        Thread {
            val (okFlush, count) = db.flushSyncEventsQueue(this@MainActivity)
            val (okHb, status) = db.sendHeartbeat(this@MainActivity)
            db.syncRoutineScheduleWithServer()
            db.syncRoutineScheduleWithServer(db.nowDate())
            runOnUiThread {
                triggerBotMessage(if (okHb && okFlush) "This phone received a PC heartbeat and submitted $count queued events." else "Sync remains pending. Records are retained locally.", "IDLE")
                Toast.makeText(this@MainActivity, if (okHb) "Records synced with PC ✓ ($count events)" else "PC unreachable ($status). Records safe in local queue.", Toast.LENGTH_SHORT).show()
                refreshUi()
            }
        }.start()
    }

    private fun showNextDayRoutinePlannerDialog(forceUnlock: Boolean = false, initialCollege: String? = null) {
        val nextDate = db.getNextCalendarDate()
        val state = db.getNextDayScheduleState(nextDate)
        val isInitiallyLocked = state.optBoolean("is_locked", false)
        var isLocked = isInitiallyLocked && !forceUnlock

        val existingCollege = db.getCollegeAttendance(nextDate)
        var goingToCollege: Boolean? = initialCollege?.let { it.equals("YES", ignoreCase = true) }
            ?: (if (existingCollege.isNotBlank()) existingCollege == "YES" else null)

        val existingExamPlan = db.getDailyCollegeExamPlan(nextDate)?.let { CollegeExamScheduleRules.CollegeExamPlan.fromJson(it) }
        var collegeStartTime: String = existingExamPlan?.collegeStartHhmm ?: "09:00"
        var collegeEndTime: String = existingExamPlan?.collegeEndHhmm ?: "15:15"
        var hasExamTomorrow: Boolean = existingExamPlan?.hasExam ?: false
        var examStartTime: String = existingExamPlan?.examStartHhmm ?: "09:15"
        var examEndTime: String = existingExamPlan?.examEndHhmm ?: "11:15"

        val existingBathPlan = db.getDailyBathPlan(nextDate)
        val existingBathCount = db.getMaxBathOccurrences(nextDate)
        var bathSessionCount: Int = if (existingBathCount in 1..2) existingBathCount else 1
        var bath1Slot: String = existingBathPlan?.optJSONArray("selected_bath_times")?.optString(0)
            ?: db.getPlannedBathTime(1, false, nextDate).ifBlank { "07:30" }
        var bath2Slot: String = existingBathPlan?.optJSONArray("selected_bath_times")?.optString(1)
            ?: db.getPlannedBathTime(2, false, nextDate).ifBlank { "19:00" }

        var wakeupTarget = state.optString("wakeup_target", state.optString("wake_up_time", "07:00"))
        var gymTarget = state.optString("gym_target", state.optString("gym_time", "18:00"))
        var gymDuration = state.optInt("gym_duration_minutes", 90)
        var gymEnabled = state.optBoolean("gym_enabled", true)

        val wakeupSlots = mutableListOf<String>()
        for (m in (6 * 60)..(10 * 60) step 5) {
            wakeupSlots.add(String.format(Locale.US, "%02d:%02d", m / 60, m % 60))
        }
        val allDaySlots = mutableListOf<String>()
        for (m in 0 until (24 * 60) step 5) {
            allDaySlots.add(String.format(Locale.US, "%02d:%02d", m / 60, m % 60))
        }

        fun calcWindowText(hhmm: String, wakeupDeadline: Boolean = false, isGym: Boolean = false, durationMinutes: Int = 90): String {
            if (isGym) {
                return GymWindowRules.calculateGymWindow(nextDate, hhmm, durationMinutes).windowDisplay
            }
            val parts = hhmm.split(":")
            val mins = (parts.getOrNull(0)?.toIntOrNull() ?: 7) * 60 + (parts.getOrNull(1)?.toIntOrNull() ?: 0)
            val s = (mins - 10 + 1440) % 1440
            val endMins = if (wakeupDeadline) minOf(mins + 10, 10 * 60) else mins + 10
            val e = endMins % 1440
            val sStr = String.format(Locale.US, "%02d:%02d", s / 60, s % 60)
            val eStr = String.format(Locale.US, "%02d:%02d", e / 60, e % 60)
            return "${DisciplineScoringRules.formatTime12h(sStr)}–${DisciplineScoringRules.formatTime12h(eStr)}"
        }

        fun pickTime(initialHhmm: String, title: String, onTimePicked: (String) -> Unit) {
            val parts = initialHhmm.split(":").mapNotNull { it.toIntOrNull() }
            val initH = parts.getOrElse(0) { 9 }
            val initM = parts.getOrElse(1) { 0 }
            TimePickerDialog(this, { _, h, m ->
                val chosen = String.format(Locale.US, "%02d:%02d", h, m)
                onTimePicked(chosen)
            }, initH, initM, false).show()
        }

        val scroll = ScrollView(this)
        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(22), dp(20), dp(22), dp(16))
            background = surfaceBg(CLR_MODAL, 24, CLR_INDIGO, 1)
