                letterSpacing = 0.05f
            })
            dialogView.addView(makeSecondaryButton("REQUEST A CHANGE • SIX-HOUR NOTICE", CLR_CYAN) {
                dialogRef?.dismiss()
                strictBotChat.show("I need to change my schedule. ")
            }.apply {
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(8); bottomMargin = dp(8) }
            })
            dialogView.addView(TextView(this).apply {
