                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(4) }
                })
                val lockedCollege = if (goingToCollege == true) {
                    val pe = if (hasExamTomorrow) CollegeExamScheduleRules.calculatePostExamClassInterval(collegeStartTime, collegeEndTime, examStartTime, examEndTime) else null
                    "College: ${DisciplineScoringRules.formatTime12h(collegeStartTime)}–${DisciplineScoringRules.formatTime12h(collegeEndTime)}" +
                        (if (hasExamTomorrow) "\nExam: ${DisciplineScoringRules.formatTime12h(examStartTime)}–${DisciplineScoringRules.formatTime12h(examEndTime)}" +
                            (if (pe?.hasInterval == true) "\nPost-exam class: ${pe.startHhmm}–${pe.endHhmm} (Bonus: +1 pt)" else "") else "")
                } else "Staying Home (No College)"
                val lockedBath = "$bathSessionCount Bath session(s): ${DisciplineScoringRules.formatTime12h(bath1Slot)}" +
                    (if (bathSessionCount == 2) ", ${DisciplineScoringRules.formatTime12h(bath2Slot)}" else "")
