                lockedCard.addView(TextView(this).apply {
                    text = "• $lockedGym\n• $lockedCollege\n• $lockedBath"
                    textSize = 12f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(10) }
                })

                val unlockBtn = makePrimaryButton("🔓 UNLOCK / EDIT TOMORROW'S PLAN", CLR_CYAN, widthMatchParent = true) {
                    db.unlockNextDaySchedule(nextDate)
