                    haptic(1)
                    renderForm()
                }
                lockedCard.addView(unlockBtn)
                dialogView.addView(lockedCard)

                val closeBtn = makeSecondaryButton("CLOSE", CLR_TEXT_DIM) {
                    dialogRef?.dismiss()
                }
                dialogView.addView(closeBtn)
                return
            }

            // === STEP 1: Are you going to the gym tomorrow? (First Step) ===
