                }
                gymPickerCard.addView(TextView(this).apply {
                    text = "Gym Target Time"
                    textSize = 10.5f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(3) }
                })
                val gymWindowTv = TextView(this).apply {
                    text = "Proof window: ${calcWindowText(gymTarget, isGym = true, durationMinutes = gymDuration)}"
                    textSize = 11f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(4); bottomMargin = dp(2) }
                }
                val gymBtn = makeSecondaryButton("🏋️ Planned Start: ${DisciplineScoringRules.formatTime12h(gymTarget)} ▼", CLR_PINK) {
                    val labels = allDaySlots.map { DisciplineScoringRules.formatTime12h(it) }.toTypedArray()
                    AlertDialog.Builder(this)
                        .setTitle("Select Gym Target")
                        .setItems(labels) { _, which ->
                            gymTarget = allDaySlots[which]
                            gymWindowTv.text = "Proof window: ${calcWindowText(gymTarget, isGym = true, durationMinutes = gymDuration)}"
                        }
                        .show()
                }.apply {
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
                }
                gymPickerCard.addView(gymBtn)

                val durationOptions = listOf(45, 60, 75, 90, 120)
                lateinit var gymDurationBtn: LinearLayout
                gymDurationBtn = makeSecondaryButton("⏱️ Duration: $gymDuration min ▼", CLR_CYAN) {
                    val labels = durationOptions.map { "$it minutes" + if (it == 90) " (Default)" else "" }.toTypedArray()
                    AlertDialog.Builder(this)
                        .setTitle("Select Workout Duration")
                        .setItems(labels) { _, which ->
                            gymDuration = durationOptions[which]
                            (gymDurationBtn.getChildAt(0) as? TextView)?.text = "⏱️ Duration: $gymDuration min ▼"
                            gymWindowTv.text = "Proof window: ${calcWindowText(gymTarget, isGym = true, durationMinutes = gymDuration)}"
