                    letterSpacing = 0.05f
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
                })

                val collegeTimesRow = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
                }

                val colStartCol = LinearLayout(this).apply {
                    orientation = LinearLayout.VERTICAL
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
                }
                colStartCol.addView(TextView(this).apply {
                    text = "College start time"
                    textSize = 10.5f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(3) }
                })
                val colStartBtn = makeSecondaryButton("⏰ ${DisciplineScoringRules.formatTime12h(collegeStartTime)} ▼", CLR_INDIGO) {
                    pickTime(collegeStartTime, "College start time") {
                        collegeStartTime = it
                        renderForm()
                    }
                }
                colStartCol.addView(colStartBtn)
                collegeTimesRow.addView(colStartCol)

                val colEndCol = LinearLayout(this).apply {
                    orientation = LinearLayout.VERTICAL
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
                }
                colEndCol.addView(TextView(this).apply {
                    text = "College end time"
                    textSize = 10.5f
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(3) }
                })
                val colEndBtn = makeSecondaryButton("⏰ ${DisciplineScoringRules.formatTime12h(collegeEndTime)} ▼", CLR_INDIGO) {
                    pickTime(collegeEndTime, "College end time") {
