                        if (!peRes.hasInterval) {
                            peCard.addView(TextView(this).apply {
                                text = "ℹ️ No post-exam class time remains (exam ends at college end time)."
                                textSize = 11f
                               setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                            })
                        } else {
                            peCard.addView(TextView(this).apply {
                                text = "Post-exam class time: ${peRes.startHhmm}–${peRes.endHhmm}"
                                textSize = 12f
                                setTypeface(typeface, Typeface.BOLD)
                                setTextColor(Color.parseColor(CLR_GREEN))
                            })
                            peCard.addView(TextView(this).apply {
                                text = "Hourly submission window: Optional attendance (+1 bonus point)\nBonus point: +1"
                                textSize = 10.5f
                                setTextColor(Color.WHITE)
                                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(3) }
                            })
                        }
                        dialogView.addView(peCard)
