                background = if (isSel) surfaceBg(CLR_GREEN, 10) else surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                setPadding(dp(10), dp(8), dp(10), dp(8))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
                applySpringTouch {
                    bathSessionCount = 1
                    haptic(1)
                    renderForm()
                }
            }
            val btnBath2 = TextView(this).apply {
                text = "2 bath sessions"
                textSize = 11.5f
                setTypeface(typeface, Typeface.BOLD)
                val isSel = bathSessionCount == 2
                setTextColor(Color.parseColor(if (isSel) "#070A0C" else "#FFFFFF"))
                gravity = Gravity.CENTER
                background = if (isSel) surfaceBg(CLR_GREEN, 10) else surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
                setPadding(dp(10), dp(8), dp(10), dp(8))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
                applySpringTouch {
                    bathSessionCount = 2
                    haptic(1)
                    renderForm()
                }
            }
            bathCountRow.addView(btnBath1)
            bathCountRow.addView(btnBath2)
            dialogView.addView(bathCountRow)

            // Slot pickers
            dialogView.addView(TextView(this).apply {
                text = "Bath Session 1"
                textSize = 11f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
            })
            val bath1Btn = makeSecondaryButton("⏰ ${DisciplineScoringRules.formatTime12h(bath1Slot)} ▼", CLR_CYAN) {
                pickTime(bath1Slot, "Bath Session 1") {
                    bath1Slot = it
                    renderForm()
                }
            }.apply {
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(3)
                    bottomMargin = dp(8)
                }
            }
            dialogView.addView(bath1Btn)

            if (bathSessionCount == 2) {
                dialogView.addView(TextView(this).apply {
                    text = "Bath Session 2"
                    textSize = 11f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.WHITE)
                })
                val bath2Btn = makeSecondaryButton("⏰ ${DisciplineScoringRules.formatTime12h(bath2Slot)} ▼", CLR_CYAN) {
                    pickTime(bath2Slot, "Bath Session 2") {
                        bath2Slot = it
                        renderForm()
                    }
                }.apply {
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(3)
                        bottomMargin = dp(8)
                    }
                }
                dialogView.addView(bath2Btn)

                val bVal = CollegeExamScheduleRules.validateIndependentBathSelection(2, listOf(bath1Slot, bath2Slot))
                if (!bVal.isValid) {
                    dialogView.addView(TextView(this).apply {
                        text = "⚠️ ${bVal.errorMessage}"
                        textSize = 10.5f
                        setTextColor(Color.parseColor(CLR_AMBER))
                        layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(10) }
                    })
                }
            }

            // === BOTTOM ACTION BUTTONS ===
            val btnRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.END
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(12) }
            }
            btnRow.addView(makeSecondaryButton("LATER", CLR_TEXT_DIM) {
                db.saveNextDayDraft(wakeupTarget, bath1Slot, gymTarget, gymEnabled, org.json.JSONArray(), dismissed = true, scheduleDate = nextDate, gymDurationMinutes = gymDuration)
                Toast.makeText(this, "Draft saved. Remember to confirm tomorrow's routine!", Toast.LENGTH_SHORT).show()
                dialogRef?.dismiss()
                refreshUi()
            })

            val reviewBtn = makePrimaryButton("REVIEW SCHEDULE", CLR_GREEN) {
                if (goingToCollege == null) {
                    Toast.makeText(this, "Please answer: Are you going to college tomorrow?", Toast.LENGTH_LONG).show()
                    return@makePrimaryButton
                }
                if (goingToCollege == true) {
                    val cVal2 = CollegeExamScheduleRules.validateCollegeTimes(collegeStartTime, collegeEndTime)
                    if (!cVal2.isValid) {
                        Toast.makeText(this, cVal2.errorMessage, Toast.LENGTH_LONG).show()
                        return@makePrimaryButton
                    }
                    if (hasExamTomorrow) {
                        val eVal2 = CollegeExamScheduleRules.validateExamTimes(collegeStartTime, collegeEndTime, examStartTime, examEndTime)
                        if (!eVal2.isValid) {
                            Toast.makeText(this, eVal2.errorMessage, Toast.LENGTH_LONG).show()
                            return@makePrimaryButton
                        }
                    }
                }
                val bathTimes = if (bathSessionCount == 1) listOf(bath1Slot) else listOf(bath1Slot, bath2Slot)
                val bVal2 = CollegeExamScheduleRules.validateIndependentBathSelection(bathSessionCount, bathTimes)
                if (!bVal2.isValid) {
                    Toast.makeText(this, bVal2.errorMessage, Toast.LENGTH_LONG).show()
                    return@makePrimaryButton
                }
                val sb = StringBuilder()
                sb.append("TOMORROW'S ROUTINE ($nextDate)\n\n")
                if (gymEnabled) {
                    sb.append("• Gym: Planned (${DisciplineScoringRules.formatTime12h(gymTarget)}, $gymDuration min) • Proof: ${calcWindowText(gymTarget, isGym = true, durationMinutes = gymDuration)}\n")
                } else {
                    sb.append("• Gym: No session scheduled tomorrow\n")
                }
                if (goingToCollege == true) {
                    sb.append("• College Attendance: YES (${DisciplineScoringRules.formatTime12h(collegeStartTime)}–${DisciplineScoringRules.formatTime12h(collegeEndTime)})\n")
                    if (hasExamTomorrow) {
                        sb.append("• Exam: ${DisciplineScoringRules.formatTime12h(examStartTime)}–${DisciplineScoringRules.formatTime12h(examEndTime)}\n")
                        val pe = CollegeExamScheduleRules.calculatePostExamClassInterval(collegeStartTime, collegeEndTime, examStartTime, examEndTime)
                        if (pe.hasInterval) {
                            sb.append("• Post-exam class time: ${pe.startHhmm}–${pe.endHhmm}\n")
                            sb.append("• Hourly submission window: Optional attendance (+1 bonus point)\n")
                            sb.append("• Bonus point: +1\n")
                        } else {
                            sb.append("• Post-exam class time: None (exam ends at college end)\n")
                        }
                    } else {
                        sb.append("• Exam: No exam scheduled\n")
                    }
                } else {
                    sb.append("• College Attendance: NO (Staying Home)\n")
                }
                sb.append("• Bath Sessions: $bathSessionCount session(s)\n")
                sb.append("  - Bath Session 1: ${DisciplineScoringRules.formatTime12h(bath1Slot)}\n")
                if (bathSessionCount == 2) {
                    sb.append("  - Bath Session 2: ${DisciplineScoringRules.formatTime12h(bath2Slot)}\n")
                }
                sb.append("• Hourly Checkpoints: 10:00 AM–10:00 PM (13 independent slots)")

                AlertDialog.Builder(this)
                    .setTitle("TOMORROW'S ROUTINE")
                    .setMessage(sb.toString())
                    .setNegativeButton("Back to Edit", null)
                    .setPositiveButton("Confirm & Lock") { _, _ ->
                        Thread {
                            val isCollege = goingToCollege == true
                            val collegeDecision = if (isCollege) "YES" else "NO"
                            db.setCollegeAttendance(nextDate, collegeDecision)

                            db.saveDailyCollegeExamPlan(
                                date = nextDate,
                                attendsCollege = collegeDecision,
                                collegeStart = if (isCollege) collegeStartTime else null,
                                collegeEnd = if (isCollege) collegeEndTime else null,
                                hasExam = if (isCollege && hasExamTomorrow) "YES" else "NO",
                                examStart = if (isCollege && hasExamTomorrow) examStartTime else null,
                                examEnd = if (isCollege && hasExamTomorrow) examEndTime else null
                            )

                            val chosenBathTimes = if (bathSessionCount == 1) listOf(bath1Slot) else listOf(bath1Slot, bath2Slot)
                            db.confirmDailyBathPlan(
                                date = nextDate,
                                collegeDecision = collegeDecision,
                                plannedTimes = chosenBathTimes,
                                allowOverwrite = true
                            )

                            val res = db.confirmNextDaySchedule(
                                wakeUpTime = wakeupTarget,
                                bathTime = bath1Slot,
                                gymTime = if (gymEnabled) gymTarget else "",
                                gymEnabled = gymEnabled,
                                scheduleDate = nextDate,
                                gymDurationMinutes = if (gymEnabled) gymDuration else 0,
                                allowOverwrite = true
                            )

                            db.reconcileHourlyPostExamClassSlots(nextDate)
                            db.ensureDailyActivities(nextDate)

                            runOnUiThread {
                                if (res.optBoolean("success", false) || res.optBoolean("ok", false)) {
                                    haptic(1)
                                    triggerBotMessage(res.optString("strictbot_message", "Tomorrow's routine is scheduled."), "SUCCESS")
                                    Thread { db.syncRoutineScheduleWithServer() }.start()
                                    dialogRef?.dismiss()
                                    refreshUi()
                                } else {
                                    Toast.makeText(this@MainActivity, res.optString("error", "Validation error"), Toast.LENGTH_LONG).show()
                                }
                            }
                        }.start()
                    }
                    .show()
            }
            btnRow.addView(reviewBtn)
            dialogView.addView(btnRow)
        }

        renderForm()

        dialogRef = AlertDialog.Builder(this)
            .setView(scroll)
            .setCancelable(true)
            .create()
        dialogRef.show()
    }

    private fun loadSchedulePendingDraftIfNeeded() {
        if (schedulePendingDraftInitialized) return
        val today = db.nowDate()
        val draft = db.getScheduleDraftForDate(today)
        if (draft != null) {
            val cDec = draft.optString("college_decision")
            schedulePendingCollegeChoice = if (cDec.isNotBlank()) cDec else null
            schedulePendingCollegeStart = draft.optString("college_start").ifBlank { "09:00" }
            schedulePendingCollegeEnd = draft.optString("college_end").ifBlank { "15:15" }
            schedulePendingHasExam = draft.optBoolean("has_exam", false)
            schedulePendingExamStart = draft.optString("exam_start").ifBlank { "09:15" }
            schedulePendingExamEnd = draft.optString("exam_end").ifBlank { "11:15" }
            val bc = draft.optInt("bath_session_count", 1)
            schedulePendingBathCount = if (bc in 1..2) bc else 1
            val bTimes = draft.optJSONArray("bath_times")
            if (bTimes != null && bTimes.length() > 0) {
                schedulePendingBath1 = bTimes.optString(0, "07:30")
                if (bTimes.length() > 1) schedulePendingBath2 = bTimes.optString(1, "19:00")
            } else {
                schedulePendingBath1 = draft.optString("bath_time").ifBlank { "07:30" }
            }
            schedulePendingWakeup = draft.optString("wake_up_time").ifBlank { "07:00" }
            schedulePendingGymTime = draft.optString("gym_time").ifBlank { "18:00" }
            val gd = draft.optInt("gym_duration_minutes", 90)
            schedulePendingGymDuration = if (gd > 0) gd else 90
            schedulePendingGymEnabled = draft.optBoolean("gym_enabled", true)
            if (draft.has("gym_enabled")) {
                schedulePendingGymChoice = if (schedulePendingGymEnabled) "YES" else "NO"
            }
        } else {
            val existingCollege = db.getCollegeAttendance(today)
            if (existingCollege.isNotBlank()) schedulePendingCollegeChoice = existingCollege
            val existingExamPlan = db.getDailyCollegeExamPlan(today)?.let { CollegeExamScheduleRules.CollegeExamPlan.fromJson(it) }
            if (existingExamPlan != null) {
                schedulePendingCollegeStart = existingExamPlan.collegeStartHhmm ?: "09:00"
                schedulePendingCollegeEnd = existingExamPlan.collegeEndHhmm ?: "15:15"
                schedulePendingHasExam = existingExamPlan.hasExam
                schedulePendingExamStart = existingExamPlan.examStartHhmm ?: "09:15"
                schedulePendingExamEnd = existingExamPlan.examEndHhmm ?: "11:15"
            }
            val existingBathPlan = db.getDailyBathPlan(today)
            if (existingBathPlan != null) {
                val bTimes = existingBathPlan.optJSONArray("selected_bath_times")
                if (bTimes != null && bTimes.length() > 0) {
                    schedulePendingBath1 = bTimes.optString(0, "07:30")
                    if (bTimes.length() > 1) {
                        schedulePendingBath2 = bTimes.optString(1, "19:00")
                        schedulePendingBathCount = 2
                    }
                }
            }
        }
        val dailyGym = db.getDailyGymSetup(today)
        if (dailyGym != null && dailyGym.choice != DailyGymScheduleRules.DailyGymChoice.UNSET) {
            schedulePendingGymChoice = if (dailyGym.isGymPlanned) "YES" else "NO"
            schedulePendingGymEnabled = dailyGym.isGymPlanned
            dailyGym.plannedStartTime?.takeIf { it.isNotBlank() }?.let { schedulePendingGymTime = it }
            if (dailyGym.plannedDurationMinutes > 0) schedulePendingGymDuration = dailyGym.plannedDurationMinutes
        }
        schedulePendingDraftInitialized = true
    }

    private fun saveCurrentSchedulePendingDraft() {
        val today = db.nowDate()
        val bathList = if (schedulePendingBathCount == 1) listOf(schedulePendingBath1) else listOf(schedulePendingBath1, schedulePendingBath2)
        val isGymYes = (schedulePendingGymChoice == "YES")
        db.saveScheduleDraftForDate(
            date = today,
            wakeUpTime = schedulePendingWakeup,
            bathTime = schedulePendingBath1,
            gymTime = if (isGymYes) schedulePendingGymTime else "",
            gymEnabled = isGymYes,
            collegeDecision = schedulePendingCollegeChoice,
            collegeStart = schedulePendingCollegeStart,
            collegeEnd = schedulePendingCollegeEnd,
            hasExam = schedulePendingHasExam,
            examStart = schedulePendingExamStart,
            examEnd = schedulePendingExamEnd,
            bathSessionCount = schedulePendingBathCount,
            bathTimes = bathList,
            gymDurationMinutes = if (isGymYes) schedulePendingGymDuration else 0
        )
    }

