        fun pickTimeForPending(initialHhmm: String, title: String, onTimePicked: (String) -> Unit) {
            val parts = initialHhmm.split(":").mapNotNull { it.toIntOrNull() }
            val initH = parts.getOrElse(0) { 9 }
            val initM = parts.getOrElse(1) { 0 }
            TimePickerDialog(this, { _, h, m ->
                val chosen = String.format(Locale.US, "%02d:%02d", h, m)
                onTimePicked(chosen)
                saveCurrentSchedulePendingDraft()
                refreshUi()
            }, initH, initM, false).show()
        }

