            setTextColor(if (isYes) Color.BLACK else Color.WHITE)
            gravity = Gravity.CENTER
            background = if (isYes) surfaceBg(CLR_GREEN, 10) else surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
            setPadding(dp(10), dp(10), dp(10), dp(10))
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
            applySpringTouch {
                schedulePendingCollegeChoice = "YES"
                schedulePendingErrorMessage = null
                saveCurrentSchedulePendingDraft()
                haptic(1)
                refreshUi()
            }
        }
        val btnNo = TextView(this).apply {
            text = "NO (Staying Home)"
            textSize = 11.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(if (isNo) Color.BLACK else Color.WHITE)
            gravity = Gravity.CENTER
            background = if (isNo) surfaceBg(CLR_AMBER, 10) else surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
            setPadding(dp(10), dp(10), dp(10), dp(10))
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
            applySpringTouch {
                schedulePendingCollegeChoice = "NO"
                schedulePendingErrorMessage = null
                saveCurrentSchedulePendingDraft()
                haptic(1)
                refreshUi()
            }
        }
        collegeRow.addView(btnYes)
        collegeRow.addView(btnNo)
        mainLayout.addView(collegeRow)

        if (isYes) {
            val collegeHoursCard = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                background = surfaceBg(CLR_SURFACE, 12, CLR_BORDER, 1)
                setPadding(dp(12), dp(10), dp(12), dp(10))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(10)
                }
            }
            val timesRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            val startBtn = makeSecondaryButton("Start: ${DisciplineScoringRules.formatTime12h(schedulePendingCollegeStart)} ▼", CLR_CYAN) {
                pickTimeForPending(schedulePendingCollegeStart, "College Start Time") {
                    schedulePendingCollegeStart = it
                }
            }.apply {
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
            }
            val endBtn = makeSecondaryButton("End: ${DisciplineScoringRules.formatTime12h(schedulePendingCollegeEnd)} ▼", CLR_CYAN) {
                pickTimeForPending(schedulePendingCollegeEnd, "College End Time") {
                    schedulePendingCollegeEnd = it
                }
            }.apply {
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
            }
            timesRow.addView(startBtn)
            timesRow.addView(endBtn)
            collegeHoursCard.addView(timesRow)

            val examHeader = TextView(this).apply {
                text = "Exam Today?"
                textSize = 11f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(8)
                    bottomMargin = dp(4)
                }
            }
            collegeHoursCard.addView(examHeader)

            val examToggleRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            val btnExamNo = TextView(this).apply {
                text = "No Exam"
                textSize = 10.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(if (!schedulePendingHasExam) Color.BLACK else Color.WHITE)
                gravity = Gravity.CENTER
                background = if (!schedulePendingHasExam) surfaceBg(CLR_CYAN, 8) else surfaceBg(CLR_SURFACE_LOW, 8, CLR_BORDER, 1)
                setPadding(dp(8), dp(6), dp(8), dp(6))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
                applySpringTouch {
                    schedulePendingHasExam = false
                    saveCurrentSchedulePendingDraft()
                    refreshUi()
                }
            }
            val btnExamYes = TextView(this).apply {
                text = "Has Exam"
                textSize = 10.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(if (schedulePendingHasExam) Color.BLACK else Color.WHITE)
                gravity = Gravity.CENTER
                background = if (schedulePendingHasExam) surfaceBg(CLR_CYAN, 8) else surfaceBg(CLR_SURFACE_LOW, 8, CLR_BORDER, 1)
                setPadding(dp(8), dp(6), dp(8), dp(6))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
                applySpringTouch {
                    schedulePendingHasExam = true
                    saveCurrentSchedulePendingDraft()
                    refreshUi()
                }
            }
            examToggleRow.addView(btnExamNo)
            examToggleRow.addView(btnExamYes)
            collegeHoursCard.addView(examToggleRow)

            if (schedulePendingHasExam) {
                val examTimesRow = LinearLayout(this).apply {
                    orientation = LinearLayout.HORIZONTAL
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(6)
                    }
                }
                val exStartBtn = makeSecondaryButton("Exam Start: ${DisciplineScoringRules.formatTime12h(schedulePendingExamStart)} ▼", CLR_PINK) {
                    pickTimeForPending(schedulePendingExamStart, "Exam Start Time") {
                        schedulePendingExamStart = it
                    }
                }.apply {
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
                }
                val exEndBtn = makeSecondaryButton("Exam End: ${DisciplineScoringRules.formatTime12h(schedulePendingExamEnd)} ▼", CLR_PINK) {
                    pickTimeForPending(schedulePendingExamEnd, "Exam End Time") {
                        schedulePendingExamEnd = it
                    }
                }.apply {
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
                }
                examTimesRow.addView(exStartBtn)
                examTimesRow.addView(exEndBtn)
                collegeHoursCard.addView(examTimesRow)
            }
            mainLayout.addView(collegeHoursCard)
        }

        // SECTION 3: Bath Sessions
        addSectionHeader("3. Bath Sessions")
        val bathCountRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }
        val isBath1 = schedulePendingBathCount == 1
        val isBath2 = schedulePendingBathCount == 2

        val btnBath1 = TextView(this).apply {
            text = "1 Session"
            textSize = 11.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(if (isBath1) Color.BLACK else Color.WHITE)
            gravity = Gravity.CENTER
            background = if (isBath1) surfaceBg(CLR_GREEN, 10) else surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
            setPadding(dp(10), dp(8), dp(10), dp(8))
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(4) }
            applySpringTouch {
                schedulePendingBathCount = 1
                saveCurrentSchedulePendingDraft()
                haptic(1)
                refreshUi()
            }
        }
        val btnBath2 = TextView(this).apply {
            text = "2 Sessions"
            textSize = 11.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(if (isBath2) Color.BLACK else Color.WHITE)
            gravity = Gravity.CENTER
            background = if (isBath2) surfaceBg(CLR_GREEN, 10) else surfaceBg(CLR_SURFACE_LOW, 10, CLR_BORDER, 1)
            setPadding(dp(10), dp(8), dp(10), dp(8))
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(4) }
            applySpringTouch {
                schedulePendingBathCount = 2
                saveCurrentSchedulePendingDraft()
                haptic(1)
                refreshUi()
            }
        }
        bathCountRow.addView(btnBath1)
        bathCountRow.addView(btnBath2)
        mainLayout.addView(bathCountRow)

        val bathPickersCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            background = surfaceBg(CLR_SURFACE, 12, CLR_BORDER, 1)
            setPadding(dp(12), dp(10), dp(12), dp(10))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(14)
            }
        }
        val bath1Btn = makeSecondaryButton("⏰ Bath Session 1: ${DisciplineScoringRules.formatTime12h(schedulePendingBath1)} ▼", CLR_CYAN) {
            pickTimeForPending(schedulePendingBath1, "Bath Session 1") {
                schedulePendingBath1 = it
            }
        }.apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = if (schedulePendingBathCount == 2) dp(6) else 0
            }
        }
        bathPickersCard.addView(bath1Btn)

        if (schedulePendingBathCount == 2) {
            val bath2Btn = makeSecondaryButton("⏰ Bath Session 2: ${DisciplineScoringRules.formatTime12h(schedulePendingBath2)} ▼", CLR_CYAN) {
                pickTimeForPending(schedulePendingBath2, "Bath Session 2") {
                    schedulePendingBath2 = it
                }
            }.apply {
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            bathPickersCard.addView(bath2Btn)
        }
        mainLayout.addView(bathPickersCard)

        // SECTION 5: CONFIRM SCHEDULE BUTTON / LOADING
        if (scheduleConfirmationState.isProgress || isSubmittingScheduleCompletion) {
            val loadingLayout = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER
                background = surfaceBg(CLR_SURFACE_LOW, 14, CLR_GREEN, 1)
                setPadding(dp(16), dp(14), dp(16), dp(14))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(8)
                }
            }
            loadingLayout.addView(ProgressBar(this).apply {
                isIndeterminate = true
                layoutParams = LinearLayout.LayoutParams(dp(22), dp(22)).apply { rightMargin = dp(10) }
            })
            loadingLayout.addView(TextView(this).apply {
                text = scheduleConfirmationState.displayStatus()
                textSize = 12f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_GREEN))
            })
            mainLayout.addView(loadingLayout)
        } else {
            val btnLabel = when (scheduleConfirmationState) {
                ScheduleDeadlineRules.ScheduleConfirmationState.RETRY_REQUIRED,
                ScheduleDeadlineRules.ScheduleConfirmationState.FAILED -> "RETRY CONFIRMATION"
                else -> "CONFIRM SCHEDULE"
            }
            val confirmBtn = makePrimaryButton(btnLabel, CLR_GREEN, widthMatchParent = true) {
                if (scheduleConfirmationState.isProgress || isSubmittingScheduleCompletion) return@makePrimaryButton

                if (schedulePendingGymChoice == null) {
                    schedulePendingErrorMessage = "Please answer: Are you going to the gym today? Select YES or NO."
                    haptic(3)
                    refreshUi()
                    return@makePrimaryButton
                }

                val isGymChoiceYes = schedulePendingGymChoice == "YES"
                val bathTimes = if (schedulePendingBathCount == 1) listOf(schedulePendingBath1) else listOf(schedulePendingBath1, schedulePendingBath2)
                val cleanPendingWake = DisciplineScoringRules.validateWakeUpTime(schedulePendingWakeup).let {
                    if (it.first) it.second else "07:00"
                }
                val submissionData = ScheduleDeadlineRules.ScheduleSubmissionData(
                    date = today,
                    collegeAttendance = schedulePendingCollegeChoice,
                    collegeStartHhmm = if (schedulePendingCollegeChoice == "YES") schedulePendingCollegeStart else null,
                    collegeEndHhmm = if (schedulePendingCollegeChoice == "YES") schedulePendingCollegeEnd else null,
                    hasExam = schedulePendingCollegeChoice == "YES" && schedulePendingHasExam,
                    examStartHhmm = if (schedulePendingCollegeChoice == "YES" && schedulePendingHasExam) schedulePendingExamStart else null,
                    examEndHhmm = if (schedulePendingCollegeChoice == "YES" && schedulePendingHasExam) schedulePendingExamEnd else null,
                    bathSessionCount = schedulePendingBathCount,
                    bathTimes = bathTimes,
                    wakeUpTargetHhmm = cleanPendingWake,
                    gymTargetHhmm = if (isGymChoiceYes) schedulePendingGymTime else "",
                    gymDurationMinutes = if (isGymChoiceYes) schedulePendingGymDuration else 0,
                    gymEnabled = isGymChoiceYes,
                    gymRequiredByAdmin = db.getConfigValue("gym_required_by_admin", "0") == "1"
                )

                scheduleConfirmationState = ScheduleDeadlineRules.ScheduleConfirmationState.VALIDATING
                refreshUi()

                val valResult = ScheduleDeadlineRules.validateScheduleSubmission(submissionData)
                if (!valResult.isValid) {
                    scheduleConfirmationState = ScheduleDeadlineRules.ScheduleConfirmationState.DRAFT
                    schedulePendingErrorMessage = valResult.errorMessage ?: "Please complete all required schedule fields."
                    haptic(3)
                    refreshUi()
                    AlertDialog.Builder(this@MainActivity)
                        .setTitle("Schedule Configuration")
                        .setMessage(schedulePendingErrorMessage)
                        .setPositiveButton("OK", null)
                        .show()
                    return@makePrimaryButton
                }

                scheduleConfirmationState = ScheduleDeadlineRules.ScheduleConfirmationState.SAVING_LOCALLY
                isSubmittingScheduleCompletion = true
                currentScheduleDeadlineState = ScheduleDeadlineRules.ScheduleDeadlineState.SUBMISSION_IN_PROGRESS
                refreshUi()

                // 15-second bounded timeout watchdog
                val timeoutRunnable = Runnable {
                    val alreadyConfirmed = try { db.isScheduleConfirmedForDate(today) } catch (_: Throwable) { false }
                    if (alreadyConfirmed) {
                        scheduleConfirmationState = ScheduleDeadlineRules.ScheduleConfirmationState.CONFIRMED
                        isSubmittingScheduleCompletion = false
                        isSchedulePendingRestricted = false
                        currentScheduleDeadlineState = ScheduleDeadlineRules.ScheduleDeadlineState.CONFIRMED_AND_RELEASED
                        try { ScheduleDeadlineManager.cancelDeadlineNotification(this@MainActivity) } catch (_: Throwable) {}
                        try { WakeUpAlarmReceiver.scheduleHourlyWindows(this@MainActivity, forceRebuild = true) } catch (_: Throwable) {}
                        Toast.makeText(this@MainActivity, "Today's schedule confirmed! Normal app access restored.", Toast.LENGTH_LONG).show()
                        refreshUi()
                    } else if (scheduleConfirmationState.isProgress) {
                        scheduleConfirmationState = ScheduleDeadlineRules.ScheduleConfirmationState.RETRY_REQUIRED
                        isSubmittingScheduleCompletion = false
                        currentScheduleDeadlineState = ScheduleDeadlineRules.ScheduleDeadlineState.SAVE_FAILED
                        schedulePendingErrorMessage = "Confirmation timed out after 15 seconds. Your inputs are preserved. Please tap RETRY."
                        Toast.makeText(this@MainActivity, schedulePendingErrorMessage, Toast.LENGTH_LONG).show()
                        refreshUi()
                    }
                }
                scheduleConfirmationTimeoutRunnable = timeoutRunnable
                uiHandler.postDelayed(timeoutRunnable, 15000L)

                Thread {
                    try {
                        db.saveDailyGymSetup(
                            date = today,
                            choice = if (isGymChoiceYes) "YES" else "NO_GYM",
                            startTime = if (isGymChoiceYes) schedulePendingGymTime else null,
                            durationMinutes = if (isGymChoiceYes) schedulePendingGymDuration else 0,
                            isConfirmed = true
                        )
                        val result = db.confirmScheduleForDate(
                            date = today,
                            collegeDecision = schedulePendingCollegeChoice ?: "NO",
                            collegeStart = if (schedulePendingCollegeChoice == "YES") schedulePendingCollegeStart else null,
                            collegeEnd = if (schedulePendingCollegeChoice == "YES") schedulePendingCollegeEnd else null,
                            hasExam = schedulePendingCollegeChoice == "YES" && schedulePendingHasExam,
                            examStart = if (schedulePendingCollegeChoice == "YES" && schedulePendingHasExam) schedulePendingExamStart else null,
                            examEnd = if (schedulePendingCollegeChoice == "YES" && schedulePendingHasExam) schedulePendingExamEnd else null,
                            bathSessionCount = schedulePendingBathCount,
                            bathTimes = bathTimes,
                            wakeUpTime = cleanPendingWake,
                            gymTime = if (isGymChoiceYes) schedulePendingGymTime else "",
                            gymDurationMinutes = if (isGymChoiceYes) schedulePendingGymDuration else 0,
                            gymEnabled = isGymChoiceYes
                        )

                        val success = result.optBoolean("success", false)
                        val isConfirmed = db.isScheduleConfirmedForDate(today)

                        val nowMs = db.authoritativeNowMs()
                        val isLate = result.optBoolean("is_submitted_late", false) ||
                                     ScheduleDeadlineRules.isPastDeadline(nowMs, today, db.scheduleTimezone())

                        uiHandler.post {
                            try {
                                scheduleConfirmationTimeoutRunnable?.let { uiHandler.removeCallbacks(it) }
                                scheduleConfirmationTimeoutRunnable = null
                                isSubmittingScheduleCompletion = false

                                if (success && isConfirmed) {
                                    // Asynchronously sync with backend in background without blocking UI un-restriction
                                    Thread {
                                        try {
                                            val syncRes = db.syncRoutineScheduleWithServer(today)
                                            Log.i("MainActivity", "Schedule sync response: $syncRes")
                                        } catch (e: Throwable) {
                                            Log.w("MainActivity", "Non-blocking sync attempt error: ${e.message}")
                                        }
                                    }.start()
                                    scheduleConfirmationState = if (isLate) {
                                        ScheduleDeadlineRules.ScheduleConfirmationState.SUBMITTED_LATE
                                    } else {
                                        ScheduleDeadlineRules.ScheduleConfirmationState.CONFIRMED
                                    }
                                    isSchedulePendingRestricted = false
                                    currentScheduleDeadlineState = ScheduleDeadlineRules.ScheduleDeadlineState.CONFIRMED_AND_RELEASED
                                    schedulePendingErrorMessage = null
                                    try {
                                        ScheduleDeadlineManager.cancelDeadlineNotification(this@MainActivity)
                                    } catch (e: Throwable) {
                                        Log.w("MainActivity", "Could not cancel deadline notification: ${e.message}")
                                    }
                                    try {
                                        WakeUpAlarmReceiver.scheduleHourlyWindows(this@MainActivity, forceRebuild = true)
                                    } catch (e: Throwable) {
                                        Log.w("MainActivity", "Could not schedule hourly windows: ${e.message}")
                                    }
                                    try {
                                        MorningWakeUpManager.cancelMorningNotification(this@MainActivity)
                                    } catch (e: Throwable) {
                                        Log.w("MainActivity", "Could not cancel morning notification: ${e.message}")
                                    }
                                    val toastMsg = if (isLate) {
                                        "Today's schedule confirmed (Submitted Late after 10:00 AM) ✓. App access restored."
                                    } else {
                                        "Today's schedule confirmed! Normal app access restored."
                                    }
                                    Toast.makeText(this@MainActivity, toastMsg, Toast.LENGTH_LONG).show()
                                    try {
                                        refreshUi()
                                    } catch (e: Throwable) {
                                        Log.e("MainActivity", "refreshUi error after schedule confirm", e)
                                    }
                                } else {
                                    scheduleConfirmationState = ScheduleDeadlineRules.ScheduleConfirmationState.FAILED
                                    currentScheduleDeadlineState = ScheduleDeadlineRules.ScheduleDeadlineState.SAVE_FAILED
                                    schedulePendingErrorMessage = result.optString("error", "Failed to persist schedule. Your draft is preserved; please tap RETRY.")
                                    Toast.makeText(this@MainActivity, schedulePendingErrorMessage, Toast.LENGTH_LONG).show()
                                    AlertDialog.Builder(this@MainActivity)
                                        .setTitle("Schedule Confirmation Error")
                                        .setMessage("Could not confirm today's schedule:\n\n$schedulePendingErrorMessage\n\nYour inputs are preserved. Please review and tap RETRY.")
                                        .setPositiveButton("OK", null)
                                        .show()
                                    try {
                                        refreshUi()
                                    } catch (e: Throwable) {
                                        Log.e("MainActivity", "refreshUi error on failure", e)
                                    }
                                }
                            } catch (t: Throwable) {
                                Log.e("MainActivity", "Fatal error in schedule confirm uiHandler", t)
                                isSubmittingScheduleCompletion = false
                                isSchedulePendingRestricted = false
                                try { refreshUi() } catch (_: Throwable) {}
                            }
                        }
                    } catch (e: Throwable) {
                        Log.e("MainActivity", "Exception in confirmScheduleForDate thread", e)
                        uiHandler.post {
                            scheduleConfirmationTimeoutRunnable?.let { uiHandler.removeCallbacks(it) }
                            scheduleConfirmationTimeoutRunnable = null
                            isSubmittingScheduleCompletion = false
                            scheduleConfirmationState = ScheduleDeadlineRules.ScheduleConfirmationState.FAILED
                            currentScheduleDeadlineState = ScheduleDeadlineRules.ScheduleDeadlineState.SAVE_FAILED
                            val errStr = e.localizedMessage ?: e.javaClass.simpleName
                            schedulePendingErrorMessage = "Save failed: $errStr. Draft preserved; please tap RETRY."
                            Toast.makeText(this@MainActivity, schedulePendingErrorMessage, Toast.LENGTH_LONG).show()
                            AlertDialog.Builder(this@MainActivity)
                                .setTitle("Schedule Confirmation Error")
                                .setMessage("An unexpected error occurred while saving schedule:\n\n$errStr\n\nYour draft is preserved. Please tap RETRY.")
                                .setPositiveButton("OK", null)
                                .show()
                            refreshUi()
                        }
                    }
                }.start()
            }.apply {
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(8)
                }
            }
            mainLayout.addView(confirmBtn)
        }

        contentContainer.addView(mainLayout)
    }

    private fun showDeviceCenterDialog() {
        val isReg = db.isDeviceRegistered()
        val reg = db.getDeviceRegistration()

        val padH = dp(if (isWideLayout()) 22 else 16)
        val padV = dp(if (isWideLayout()) 18 else 14)
        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(padH, padV, padH, padV)
            background = surfaceBg(CLR_MODAL, 20, CLR_INDIGO, 1)
        }

        val scrollWrap = ScrollView(this).apply {
            isVerticalScrollBarEnabled = false
            overScrollMode = View.OVER_SCROLL_IF_CONTENT_SCROLLS
            addView(dialogView)
        }

        var dialogRef: AlertDialog? = null

        if (!isReg) {
            dialogView.addView(TextView(this).apply {
                text = "📱 CONNECT TO STRICTROUTINES PC"
                textSize = 15f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                letterSpacing = 0.05f
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
            })
            dialogView.addView(TextView(this).apply {
                text = "Pair this Android device permanently with your Windows StrictRoutines account. Wi-Fi and USB sync are automatic."
                textSize = 11.5f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(18) }
            })

            val scanBtn = makePrimaryButton("📷 SCAN QR CODE", CLR_BLUE, widthMatchParent = true) { _ ->
                dialogRef?.dismiss()
                launchBuiltInQrScanner()
            }
            scanBtn.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(14) }
            dialogView.addView(scanBtn)

            dialogView.addView(TextView(this).apply {
                text = "── OR ENTER 6-DIGIT PIN / SESSION KEY ──"
                textSize = 10f
                gravity = Gravity.CENTER
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
                letterSpacing = 0.1f
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(14) }
            })

            val keyInput = EditText(this).apply {
                hint = "Pairing code"
                textSize = 18f
                setTypeface(Typeface.MONOSPACE, Typeface.BOLD)
                tag = "telemetry_type"
                gravity = Gravity.CENTER
                setTextColor(Color.WHITE)
                setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
                inputType = android.text.InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS
                background = surfaceBg(CLR_SURFACE_LOW, 14, CLR_INDIGO, 1)
                setPadding(dp(16), dp(12), dp(16), dp(12))
                filters = arrayOf(android.text.InputFilter.AllCaps(), android.text.InputFilter.LengthFilter(16))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(12) }
            }
            dialogView.addView(keyInput)

            val endpointInput = EditText(this).apply {
                hint = "PC IP/Host (e.g. 192.168.1.5:8765, optional)"
                textSize = 12f
                typeface = Typeface.MONOSPACE
                gravity = Gravity.CENTER
                setTextColor(Color.WHITE)
                setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
                background = surfaceBg(CLR_SURFACE_LOW, 12, CLR_INDIGO, 1)
                setPadding(dp(14), dp(10), dp(14), dp(10))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(12) }
            }
            dialogView.addView(endpointInput)

            val statusFeedback = TextView(this).apply {
                text = ""
                textSize = 11f
                gravity = Gravity.CENTER
                setTextColor(Color.parseColor(CLR_AMBER))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(12) }
            }
            dialogView.addView(statusFeedback)

            val btnRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.END
            }
            btnRow.addView(makeSecondaryButton("CANCEL", CLR_TEXT_DIM) {
                dialogRef?.dismiss()
            })

            val connectBtn = makePrimaryButton("CONNECT", CLR_GREEN) {
                val key = keyInput.text.toString().trim()
                val pcEndpoint = endpointInput.text.toString().trim()
                if (key.length < 6) {
                    statusFeedback.text = "Please enter valid Session Key (e.g. SR-XXXX-XXXX) or 6-digit PIN"
                    haptic(2)
                    return@makePrimaryButton
                }
                statusFeedback.setTextColor(Color.parseColor(CLR_BLUE))
                statusFeedback.text = "Locating PC and establishing secure connection..."
                Thread {
                    val (ok, msg) = db.performPairingHandshake(pcEndpoint, key, this@MainActivity)
                    runOnUiThread {
                        if (ok) {
                            haptic(1)
                            triggerBotMessage("Device successfully paired with PC!", "SUCCESS")
                            Toast.makeText(this@MainActivity, "✓ Device Connected!\n$msg", Toast.LENGTH_LONG).show()
                            dialogRef?.dismiss()
                            refreshUi()
                            showDeviceCenterDialog()
                        } else {
                            haptic(3)
                            statusFeedback.setTextColor(Color.parseColor(CLR_RED))
                            statusFeedback.text = "Handshake failed: $msg"
                            Toast.makeText(this@MainActivity, "Pairing error: $msg", Toast.LENGTH_SHORT).show()
                        }
                    }
                }.start()
            }
            btnRow.addView(connectBtn)
            dialogView.addView(btnRow)

        } else {
            dialogView.addView(TextView(this).apply {
                text = "📱 DEVICE CENTER"
                textSize = 15f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                letterSpacing = 0.05f
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(4) }
            })
            val pcName = reg?.optString("paired_pc_name", "Windows PC") ?: "Windows PC"
            val endpoint = reg?.optString("server_endpoint", "http://127.0.0.1:8765") ?: "http://127.0.0.1:8765"
            val accountId = reg?.optString("account_id", "user_lok") ?: "user_lok"
            val lastSync = db.getConfigValue("last_sync_time", "Just now")

            val pcOnline = db.getConfigValue("pairing_status", "OFFLINE") == "ONLINE"
            val pcStatusBadge = if (pcOnline) "● ONLINE" else "○ OFFLINE"
            val pcStatusColor = if (pcOnline) CLR_GREEN else CLR_TEXT_DIM
            val lastSeenRelative = db.getConfigValue("last_sync_time", "Unknown")

            val statusBox = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(14), dp(12), dp(14), dp(12))
                background = surfaceBg(CLR_SURFACE_LOW, 14, if (pcOnline) CLR_GREEN else CLR_INDIGO, 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(14) }
            }
            statusBox.addView(TextView(this).apply {
                text = "✓ PERMANENTLY REGISTERED"
                textSize = 12f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_GREEN))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
            })
            statusBox.addView(TextView(this).apply {
                text = "📱 This Device: ● ONLINE (Active)\n💻 Paired PC ($pcName): $pcStatusBadge\nEndpoint: $endpoint\nAccount: $accountId\nLast Synced: $lastSync"
                textSize = 11.5f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                setLineSpacing(0f, 1.25f)
            })

            val devId = reg?.optString("device_id", "") ?: ""
            val devIdTrunc = if (devId.length > 16) devId.substring(0, 16) + "..." else devId
            val diagBox = TextView(this).apply {
                text = "DIAGNOSTICS:\nDevice ID: $devIdTrunc\nRegistration: REGISTERED\nSync Status: ${if (pcOnline) "ONLINE" else "OFFLINE"}\nTransport: Wi-Fi Authenticated"
                textSize = 10f
                setTypeface(Typeface.MONOSPACE)
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
                setPadding(dp(8), dp(6), dp(8), dp(6))
                background = surfaceBg(CLR_MODAL, 8)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(8) }
            }
            statusBox.addView(diagBox)
            dialogView.addView(statusBox)

            dialogView.addView(TextView(this).apply {
                text = "Registration persists through temporary network interruptions. Score and tasks synchronize seamlessly over authenticated Wi-Fi."
                textSize = 11f
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(16) }
            })

            val actionRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
            }

            val syncBtn = makePrimaryButton("🔄 SYNC NOW", CLR_BLUE) {
                triggerBotMessage("Syncing records with PC...", "SYNCING")
                Thread {
                    val (okFlush, count) = db.flushSyncEventsQueue(this@MainActivity)
                    val (okHb, status) = db.sendHeartbeat(this@MainActivity)
                    runOnUiThread {
                        if (okHb) {
                            haptic(1)
                            triggerBotMessage("Records fully synced ($count events).", "SUCCESS")
                            Toast.makeText(this@MainActivity, "Synced with PC! Status: $status", Toast.LENGTH_SHORT).show()
                        } else {
                            triggerBotMessage("Offline mode. Records safely queued locally.", "IDLE")
                            Toast.makeText(this@MainActivity, "PC unreachable ($status). Records queued.", Toast.LENGTH_SHORT).show()
                        }
                        refreshUi()
                        dialogRef?.dismiss()
                    }
                }.start()
            }
            syncBtn.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(6) }
            actionRow.addView(syncBtn)

            val editEpBtn = makeSecondaryButton("⚙️ EDIT IP", CLR_CYAN) {
                val input = EditText(this@MainActivity).apply {
                    setText(endpoint)
                    setPadding(dp(16), dp(12), dp(16), dp(12))
                }
                AlertDialog.Builder(this@MainActivity)
                    .setTitle("Update PC Server Address")
                    .setMessage("Enter the IP address and port shown on Windows PC (e.g. http://192.168.1.5:8765):")
                    .setView(input)
                    .setPositiveButton("UPDATE & TEST") { _, _ ->
                        val newEp = input.text.toString().trim()
                        if (db.updateServerEndpoint(newEp)) {
                            Thread {
                                val (ok, st) = db.sendHeartbeat(this@MainActivity)
                                runOnUiThread {
                                    Toast.makeText(this@MainActivity, if (ok) "Connected to PC ($st)!" else "Saved, but PC unreachable ($st)", Toast.LENGTH_SHORT).show()
                                    dialogRef?.dismiss()
                                    refreshUi()
                                    showDeviceCenterDialog()
                                }
                            }.start()
                        } else {
                            Toast.makeText(this@MainActivity, "Invalid address format", Toast.LENGTH_SHORT).show()
                        }
                    }
                    .setNegativeButton("Cancel", null)
                    .show()
            }
            editEpBtn.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                leftMargin = dp(2); rightMargin = dp(2)
            }
            actionRow.addView(editEpBtn)

            val revokeBtn = makeSecondaryButton("⚠️ REVOKE", CLR_RED) {
                AlertDialog.Builder(this)
                    .setTitle("Revoke Device Registration?")
                    .setMessage("This will permanently unpair this Android device from $pcName. You will need to pair again to sync records.")
                    .setPositiveButton("REVOKE") { _, _ ->
                        db.revokeDeviceRegistration(this@MainActivity, notifyServer = true)
                        haptic(3)
                        Toast.makeText(this@MainActivity, "Device Registration Revoked", Toast.LENGTH_SHORT).show()
                        dialogRef?.dismiss()
                        refreshUi()
                    }
                    .setNegativeButton("Cancel", null)
                    .show()
            }
            revokeBtn.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(6) }
            actionRow.addView(revokeBtn)
            dialogView.addView(actionRow)

            val closeBtn = makeSecondaryButton("CLOSE", CLR_TEXT_DIM) {
                dialogRef?.dismiss()
            }
            closeBtn.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            dialogView.addView(closeBtn)
        }

        dialogRef = AlertDialog.Builder(this)
            .setView(scrollWrap)
            .setCancelable(true)
            .create()
        dialogRef.show()
    }

    // ════════════════════════════════════════════════════════
    // REPORT BUG / ISSUE DIALOG
    // ════════════════════════════════════════════════════════

    private fun showReportBugDialog() {
        val padH = dp(if (isWideLayout()) 22 else 16)
        val padV = dp(if (isWideLayout()) 18 else 14)
        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(padH, padV, padH, padV)
            background = surfaceBg(CLR_MODAL, 20, CLR_INDIGO, 1)
        }

        val scrollWrap = ScrollView(this).apply {
            isVerticalScrollBarEnabled = false
            overScrollMode = View.OVER_SCROLL_IF_CONTENT_SCROLLS
            addView(dialogView)
        }

        var dialogRef: AlertDialog? = null

        // Header Title
        val headerRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        }
        headerRow.addView(TextView(this).apply {
            text = "🐞 REPORT A BUG / ISSUE"
            textSize = 15f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            letterSpacing = 0.05f
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        })
        dialogView.addView(headerRow)

        dialogView.addView(TextView(this).apply {
            text = "Encountered an issue or unexpected behavior? Describe what happened below. System diagnostics will be attached automatically."
            textSize = 11.5f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(14) }
        })

        // Category Chips
        dialogView.addView(TextView(this).apply {
            text = "CATEGORY"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_DIM))
            letterSpacing = 0.08f
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        })

        var selectedCategory = "Points & Sync"
        val categories = listOf("Points & Sync", "Alarms & Windows", "Camera / Proof", "App Locks", "UI / Display", "Other")
        val chipContainer = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(14) }
        }

        val chipViews = mutableListOf<TextView>()
        val row1 = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) } }
        val row2 = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT) }

        fun updateChips() {
            chipViews.forEach { tv ->
                val cat = tv.tag as? String ?: ""
                val isSel = cat == selectedCategory
                tv.background = surfaceBg(if (isSel) "#132D38" else CLR_SURFACE, 8, if (isSel) CLR_CYAN else CLR_BORDER, 1)
                tv.setTextColor(Color.parseColor(if (isSel) CLR_CYAN else CLR_TEXT_SECONDARY))
            }
        }

        categories.forEachIndexed { idx, cat ->
            val chip = TextView(this).apply {
                tag = cat
                text = cat
                textSize = 11f
                setTypeface(typeface, Typeface.BOLD)
                gravity = Gravity.CENTER
                setPadding(dp(8), dp(6), dp(8), dp(6))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                    if (idx % 3 != 2) rightMargin = dp(6)
                }
                applySpringTouch {
                    selectedCategory = cat
                    updateChips()
                }
            }
            chipViews.add(chip)
            if (idx < 3) row1.addView(chip) else row2.addView(chip)
        }
        updateChips()
        chipContainer.addView(row1)
        chipContainer.addView(row2)
        dialogView.addView(chipContainer)

        // Description Input
        dialogView.addView(TextView(this).apply {
            text = "DESCRIPTION"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_DIM))
            letterSpacing = 0.08f
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        })

        val descInput = EditText(this).apply {
            hint = "What happened? (e.g., points sync delayed, error popup, screen flicker...)"
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            setTextColor(Color.WHITE)
            textSize = 13f
            minLines = 3
            maxLines = 6
            gravity = Gravity.TOP or Gravity.START
            setPadding(dp(12), dp(10), dp(12), dp(10))
            background = surfaceBg(CLR_SURFACE, 12, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(14) }
        }
        dialogView.addView(descInput)

        // Telemetry Preview Box
        val pkgInfo = try { packageManager.getPackageInfo(packageName, 0) } catch (_: Exception) { null }
        val verName = pkgInfo?.versionName ?: "1.15.36"
        val devModel = "${Build.MANUFACTURER} ${Build.MODEL}"
        val androidVer = "Android ${Build.VERSION.RELEASE} (API ${Build.VERSION.SDK_INT})"
        val pairingStatus = if (db.isDeviceRegistered()) "REGISTERED / ONLINE" else "UNPAIRED"
        val todayStr = db.nowDate()
        val scoreNow = db.getScore(todayStr, isDevMode)

        val telemetryBox = TextView(this).apply {
            text = "TELEMETRY SNAPSHOT:\n• App: StrictRoutines v$verName\n• Device: $devModel • $androidVer\n• Pairing: $pairingStatus\n• Today Score: $scoreNow pts ($todayStr)"
            textSize = 10f
            setTypeface(Typeface.MONOSPACE)
            tag = "telemetry_type"
            setTextColor(Color.parseColor(CLR_TEXT_DIM))
            setPadding(dp(10), dp(8), dp(10), dp(8))
            background = surfaceBg(CLR_SURFACE_LOW, 8, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(16) }
        }
        dialogView.addView(telemetryBox)

        // Action Buttons
        val actionRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(8) }
        }

        val submitBtn = makePrimaryButton("SUBMIT REPORT", CLR_GREEN) {
            val userText = descInput.text?.toString()?.trim().orEmpty()
            if (userText.isEmpty()) {
                descInput.error = "Please enter a brief description"
                haptic(2)
                return@makePrimaryButton
            }

            val reportId = "bug_" + UUID.randomUUID().toString().take(8)
            val tsIso = db.nowIso()
            val reportObj = JSONObject().apply {
                put("report_id", reportId)
                put("timestamp", tsIso)
                put("category", selectedCategory)
                put("description", userText)
                put("app_version", verName)
                put("device_model", devModel)
                put("android_version", androidVer)
                put("score", scoreNow)
                put("pairing_status", pairingStatus)
                put("is_dev_mode", isDevMode)
            }

            // Persist locally
            try {
                val reportsFile = File(filesDir, "bug_reports.json")
                val existingArr = if (reportsFile.exists()) {
                    try { JSONArray(reportsFile.readText()) } catch (_: Exception) { JSONArray() }
                } else {
                    JSONArray()
                }
                existingArr.put(reportObj)
                reportsFile.writeText(existingArr.toString(2))
            } catch (e: Exception) {
                Log.e("BugReport", "Failed writing bug report file: ${e.message}")
            }

            // Enqueue sync event and audit log
            try {
                db.enqueueSyncEvent("BUG_REPORT", reportObj, this@MainActivity)
                db.logStructured(todayStr, isDevMode, "BUG_REPORT", "[$selectedCategory] $userText")
            } catch (e: Exception) {
                Log.e("BugReport", "Failed enqueuing sync event: ${e.message}")
            }

            haptic(1)
            Toast.makeText(this@MainActivity, "✓ Bug report saved! Diagnostics recorded.", Toast.LENGTH_LONG).show()
            triggerBotMessage("Bug report recorded: [$selectedCategory] $userText", "INFO")
            dialogRef?.dismiss()
        }
        submitBtn.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1.2f).apply { rightMargin = dp(6) }
        actionRow.addView(submitBtn)

        val shareBtn = makeSecondaryButton("SHARE / EXPORT", CLR_CYAN) {
            val userText = descInput.text?.toString()?.trim().orEmpty()
            val body = """
                StrictRoutines Bug Report
                -------------------------
                Category: $selectedCategory
                Description: ${if (userText.isNotEmpty()) userText else "(No description entered)"}

                Telemetry:
                App Version: $verName
                Device: $devModel
                OS: $androidVer
                Pairing: $pairingStatus
                Date / Score: $todayStr / $scoreNow pts
                Timestamp: ${db.nowIso()}
            """.trimIndent()

            val shareIntent = Intent(Intent.ACTION_SEND).apply {
                type = "text/plain"
                putExtra(Intent.EXTRA_SUBJECT, "StrictRoutines Bug Report - $selectedCategory")
                putExtra(Intent.EXTRA_TEXT, body)
            }
            try {
                startActivity(Intent.createChooser(shareIntent, "Share Bug Report"))
            } catch (e: Exception) {
                Toast.makeText(this@MainActivity, "Could not open share sheet: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
        shareBtn.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        actionRow.addView(shareBtn)
        dialogView.addView(actionRow)

        val cancelBtn = makeSecondaryButton("CANCEL", CLR_TEXT_DIM) {
            dialogRef?.dismiss()
        }
        cancelBtn.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        dialogView.addView(cancelBtn)

        dialogRef = AlertDialog.Builder(this)
            .setView(scrollWrap)
            .setCancelable(true)
            .create()
        dialogRef.show()
    }

    // ════════════════════════════════════════════════════════
    // ANDROID ADMIN MODE CONSOLE
    // ════════════════════════════════════════════════════════

    private fun promptAdminPinDialog() {
        val padH = dp(if (isWideLayout()) 22 else 16)
        val padV = dp(if (isWideLayout()) 18 else 14)
        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(padH, padV, padH, padV)
            background = surfaceBg(CLR_MODAL, 20, CLR_INDIGO, 1)
        }

        dialogView.addView(TextView(this).apply {
            text = "🛡 ADMINISTRATOR AUTHENTICATION"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            letterSpacing = 0.05f
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(6) }
        })

        val isDefault = db.isDefaultAdminPin()
        dialogView.addView(TextView(this).apply {
            text = if (isDefault) {
                "Enter Administrator PIN: 1234\n\nYou can change this temporary PIN later in Settings → Change Admin Access Key."
            } else {
                "Enter 4-digit Administrator Key to access protected controls."
            }
            textSize = 11f
            setTextColor(Color.parseColor(if (isDefault) CLR_AMBER else CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        })

        val pinInput = EditText(this).apply {
            hint = "••••"
            textSize = 24f
            setTypeface(typeface, Typeface.BOLD)
            gravity = Gravity.CENTER
            setTextColor(Color.WHITE)
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            inputType = android.text.InputType.TYPE_CLASS_NUMBER or android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD
            background = surfaceBg(CLR_SURFACE_LOW, 14, CLR_INDIGO, 1)
            setPadding(dp(16), dp(12), dp(16), dp(12))
            filters = arrayOf(android.text.InputFilter.LengthFilter(6))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(20) }
        }
        dialogView.addView(pinInput)

        val scrollWrap = ScrollView(this).apply {
            isVerticalScrollBarEnabled = false
            overScrollMode = View.OVER_SCROLL_IF_CONTENT_SCROLLS
            addView(dialogView)
        }

        val alert = AlertDialog.Builder(this)
            .setView(scrollWrap)
            .setCancelable(true)
            .create()

        val btnRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.END
        }

        val cancelBtn = makeSecondaryButton("CANCEL", CLR_TEXT_DIM) {
            alert.dismiss()
        }
        btnRow.addView(cancelBtn)

        val submitBtn = makePrimaryButton("AUTHENTICATE", CLR_INDIGO) {
            val pin = pinInput.text.toString().trim()
            val lockoutLeft = db.getPinLockoutRemainingSeconds()
            if (lockoutLeft > 0) {
                haptic(3)
                Toast.makeText(this, "Rate limited. Locked out for ${lockoutLeft}s", Toast.LENGTH_LONG).show()
                return@makePrimaryButton
            }
            if (db.verifyAdminPin(pin)) {
                if (!AdminSecurityRules.canOpenProtectedConsole(db.isDefaultAdminPin(), db.isTemporaryAdminPinAuthorized())) {
                    alert.dismiss()
                    Toast.makeText(
                        this,
                        "Change the initial administrator key before opening protected controls.",
                        Toast.LENGTH_LONG
                    ).show()
                    promptChangeAdminPinDialog()
                    return@makePrimaryButton
                }
                isAdminMode = true
                activeTab = "ADMIN"
                adminSubTab = "PERMISSIONS"
                haptic(1)
                triggerBotMessage("Administrator Mode active.", "SUCCESS")
                Toast.makeText(this, "Admin mode authenticated ✓", Toast.LENGTH_SHORT).show()
                alert.dismiss()
                refreshUi()
            } else {
                haptic(3)
                pinInput.setText("")
                val nowLockout = db.getPinLockoutRemainingSeconds()
                if (nowLockout > 0) {
                    Toast.makeText(this, "5 failed attempts. Locked out for ${nowLockout}s", Toast.LENGTH_LONG).show()
                } else {
                    Toast.makeText(this, "Invalid PIN. Access denied ❌", Toast.LENGTH_SHORT).show()
                }
            }
        }
        btnRow.addView(submitBtn)
        spaceDialogButtons(btnRow, cancelBtn, submitBtn)
        dialogView.addView(btnRow)

        alert.show()
        pinInput.requestFocus()
    }

    private fun promptChangeAdminPinDialog() {
        val padH = dp(if (isWideLayout()) 22 else 16)
        val padV = dp(if (isWideLayout()) 18 else 14)
        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(padH, padV, padH, padV)
            background = surfaceBg(CLR_MODAL, 20, CLR_INDIGO, 1)
        }

        dialogView.addView(TextView(this).apply {
            text = "🔑 CHANGE ADMINISTRATOR KEY"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            letterSpacing = 0.05f
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(6) }
        })

        dialogView.addView(TextView(this).apply {
            text = "Replace the initial personal setup key (1234) with your private 4-digit PIN."
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        })

        fun createPinField(hintText: String): EditText {
            return EditText(this).apply {
                hint = hintText
                textSize = 14f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
                inputType = android.text.InputType.TYPE_CLASS_NUMBER or android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD
                background = surfaceBg(CLR_SURFACE_LOW, 12, CLR_TEXT_DIM, 1)
                setPadding(dp(14), dp(10), dp(14), dp(10))
                filters = arrayOf(android.text.InputFilter.LengthFilter(6))
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(10) }
            }
        }

        val currPinInput = createPinField("Current PIN (e.g. 1234)")
        val newPinInput = createPinField("New 4-digit PIN")
        val confirmPinInput = createPinField("Confirm New 4-digit PIN")

        dialogView.addView(currPinInput)
        dialogView.addView(newPinInput)
        dialogView.addView(confirmPinInput)

        val changeScrollWrap = ScrollView(this).apply {
            isVerticalScrollBarEnabled = false
            overScrollMode = View.OVER_SCROLL_IF_CONTENT_SCROLLS
            addView(dialogView)
        }

        val alert = AlertDialog.Builder(this)
            .setView(changeScrollWrap)
            .setCancelable(true)
            .create()

        val btnRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.END
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { topMargin = dp(8) }
        }

        val cancelBtn = makeSecondaryButton("CANCEL", CLR_TEXT_DIM) {
            alert.dismiss()
        }
        btnRow.addView(cancelBtn)

        val saveBtn = makePrimaryButton("UPDATE KEY", CLR_INDIGO) {
            val curr = currPinInput.text.toString().trim()
            val newP = newPinInput.text.toString().trim()
            val conf = confirmPinInput.text.toString().trim()

            if (newP.length < 4) {
                haptic(3)
                Toast.makeText(this, "New PIN must be at least 4 digits!", Toast.LENGTH_SHORT).show()
                return@makePrimaryButton
            }

            if (newP != conf) {
                haptic(3)
                Toast.makeText(this, "New PIN and confirmation do not match!", Toast.LENGTH_LONG).show()
                return@makePrimaryButton
            }

            if (db.changeAdminPin(curr, newP)) {
                haptic(1)
                Toast.makeText(this, "Admin key updated successfully ✓", Toast.LENGTH_LONG).show()
                triggerBotMessage("Administrator access key updated successfully.", "SUCCESS")
                alert.dismiss()
                refreshUi()
            } else {
                haptic(3)
                Toast.makeText(this, "Current PIN is incorrect or update rejected.", Toast.LENGTH_LONG).show()
            }
        }
        btnRow.addView(saveBtn)
        spaceDialogButtons(btnRow, cancelBtn, saveBtn)
        dialogView.addView(btnRow)

        alert.show()
        currPinInput.requestFocus()
    }

    private fun renderAdminTab(st: org.json.JSONObject, score: Int) {
        val date = db.nowDate()
        val metrics = db.getAdminMetrics(date, isDevMode)
        val pendingProofs = db.getPendingProofs()

        // 1. Admin Hero Header
        val headerCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(20), dp(20), dp(20))
            background = gradientBg("#1E1B4B", "#0F172A", 24, strokeHex = CLR_INDIGO)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        }

        val topRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(8) }
        }

        val titleCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        titleCol.addView(TextView(this).apply {
            text = "STRICTROUTINES ADMIN"
            textSize = 18f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            letterSpacing = 0.05f
        })
        titleCol.addView(TextView(this).apply {
            text = "Today • Real-time Oversight & Control"
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
        })
        topRow.addView(titleCol)

        // Exit button
        topRow.addView(makeSecondaryButton("🚪 EXIT", CLR_RED) {
            isAdminMode = false
            activeTab = "HOME"
            haptic(0)
            Toast.makeText(this, "Exited Admin Mode", Toast.LENGTH_SHORT).show()
            refreshUi()
        })
        headerCard.addView(topRow)
        contentContainer.addView(headerCard)

        // 2. Navigation Tabs
        contentContainer.addView(sectionHeading("ADMIN CONTROLS"))

        val navScroll = HorizontalScrollView(this).apply {
            isHorizontalScrollBarEnabled = false
            overScrollMode = View.OVER_SCROLL_NEVER
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        }
        val navRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
        }

        val tabs = listOf(
            Triple("OVERVIEW", "📊 OVERVIEW", CLR_VIOLET),
            Triple("PERMISSIONS", "🔑 PERMISSIONS", CLR_INDIGO),
            Triple("PROOFS", "📸 PROOFS (${pendingProofs.size})", CLR_AMBER),
            Triple("SCORING", "⚡ SCORING", CLR_BLUE),
            Triple("DEVICES", "💻 DEVICES", CLR_GREEN),
            Triple("AUDIT", "📜 AUDIT LOG", CLR_CYAN)
        )

        tabs.forEach { (subId, label, color) ->
            val isSel = adminSubTab == subId
            val pill = TextView(this).apply {
                text = label
                textSize = 11f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(if (isSel) "#FFFFFF" else CLR_TEXT_SECONDARY))
                setPadding(dp(16), dp(10), dp(16), dp(10))
                background = if (isSel) gradientBg(color, darken(color, 0.6f), 99)
                             else surfaceBg(CLR_SURFACE, 99, CLR_TEXT_DIM, 1)
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { rightMargin = dp(8) }
                applySpringTouch {
                    adminSubTab = subId
                    refreshUi()
                }
            }
            navRow.addView(pill)
        }
        navScroll.addView(navRow)
        contentContainer.addView(navScroll)

        // 3. Subtab Content
        when (adminSubTab) {
            "OVERVIEW" -> renderAdminOverviewTab(date, score, pendingProofs, metrics)
            "PERMISSIONS" -> renderAdminPermissionsTab()
            "PROOFS" -> renderAdminProofsTab(pendingProofs)
            "SCORING" -> renderAdminScoringTab(date, score)
            "DEVICES" -> renderAdminDevicesTab()
            "AUDIT" -> renderAdminAuditTab()
            else -> renderAdminOverviewTab(date, score, pendingProofs, metrics)
        }
    }

    private fun renderAdminOverviewTab(date: String, score: Int, pendingProofs: List<org.json.JSONObject>, metrics: org.json.JSONObject) {
        // Metrics Grid (Dashboard Summary)
        contentContainer.addView(sectionHeading("TODAY'S METRICS"))

        val gridRow1 = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(8) }
        }
        val gridRow2 = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        }

        fun metricCard(title: String, value: String, accentHex: String, weight: Float = 1f): LinearLayout =
            LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                gravity = Gravity.CENTER
                setPadding(dp(12), dp(14), dp(12), dp(14))
                background = surfaceBg(CLR_SURFACE, 18, accentHex, 1)
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, weight).apply {
                    rightMargin = dp(6); leftMargin = dp(6)
                }
                addView(TextView(this@MainActivity).apply {
                    text = value
                    textSize = 20f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(accentHex))
                    gravity = Gravity.CENTER
                })
                addView(TextView(this@MainActivity).apply {
                    text = title
                    textSize = 9.5f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                    gravity = Gravity.CENTER
                    letterSpacing = 0.04f
                })
            }

        gridRow1.addView(metricCard("Pending Proofs", "${pendingProofs.size}", CLR_AMBER))
        gridRow1.addView(metricCard("Pending Reviews", "${metrics.optInt("pending_reviews")}", CLR_CYAN))
        gridRow1.addView(metricCard("Average Score", "$score", CLR_BLUE))

        gridRow2.addView(metricCard("Missed Tasks", "${metrics.optInt("missed_tasks")}", CLR_RED))
        gridRow2.addView(metricCard("Violations", "${metrics.optInt("violations")}", CLR_PINK))
        gridRow2.addView(metricCard("Devices", "2 / 2", CLR_GREEN))
        gridRow2.addView(metricCard("Sync", "Healthy", CLR_GREEN))

        contentContainer.addView(gridRow1)
        contentContainer.addView(gridRow2)

        // Administration Modules Navigation
        contentContainer.addView(sectionHeading("ADMIN MODULES"))
        val quickCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(14), dp(16), dp(14))
            background = surfaceBg(CLR_SURFACE, 18)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        }
        listOf(
            Triple("📸 Review Pending Proofs (${pendingProofs.size})", CLR_AMBER, "PROOFS"),
            Triple("🔑 Manage Permissions", CLR_INDIGO, "PERMISSIONS"),
            Triple("⚡ Adjust Scoring", CLR_BLUE, "SCORING"),
            Triple("💻 Manage Devices", CLR_GREEN, "DEVICES"),
            Triple("📜 View Audit Log", CLR_CYAN, "AUDIT")
        ).forEachIndexed { idx, (label, color, tab) ->
            if (idx > 0) {
                val divider = View(this).apply {
                    background = surfaceBg(CLR_TEXT_DIM, 1)
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(1)).apply {
                        leftMargin = dp(8); rightMargin = dp(8)
                    }
                }
                quickCard.addView(divider)
            }
            val row = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                setPadding(dp(8), dp(10), dp(8), dp(10))
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                )
                applySpringTouch {
                    adminSubTab = tab
                    refreshUi()
                }
            }
            row.addView(TextView(this).apply {
                text = label
                textSize = 13f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(color))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            })
            row.addView(TextView(this).apply {
                text = "→"
                textSize = 16f
                setTextColor(Color.parseColor(color))
            })
            quickCard.addView(row)
        }
        contentContainer.addView(quickCard)
    }

    private fun renderAdminPermissionsTab() {
        // Warning banner if using default key
        if (db.isDefaultAdminPin()) {
            val warnCard = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(16), dp(14), dp(16), dp(14))
                background = surfaceBg("#271B11", 18, CLR_AMBER, 1)
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(16) }
            }
            warnCard.addView(TextView(this).apply {
                text = "⚠️ INITIAL SETUP KEY ACTIVE (1234)"
                textSize = 12f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_AMBER))
                letterSpacing = 0.05f
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(4) }
            })
            warnCard.addView(TextView(this).apply {
                text = "StrictRoutines is currently secured with the default setup key. For security, please change this to a private 4-digit PIN."
                textSize = 11f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(12) }
            })
            warnCard.addView(makePrimaryButton("CHANGE ADMIN KEY", CLR_AMBER, widthMatchParent = true) {
                promptChangeAdminPinDialog()
            })
            contentContainer.addView(warnCard)
        }

        fun addPermCard(title: String, desc: String, statusText: String, statusColor: String, actionText: String? = null, onAction: (() -> Unit)? = null) {
            val card = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(16), dp(14), dp(16), dp(14))
                background = surfaceBg(CLR_SURFACE, 18, CLR_TEXT_DIM, 1)
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(10) }
            }

            val topRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(6) }
            }

            val titleCol = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            }
            titleCol.addView(TextView(this).apply {
                text = title
                textSize = 13f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
            })
            titleCol.addView(TextView(this).apply {
                text = desc
                textSize = 10.5f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            })
            topRow.addView(titleCol)

            val badge = TextView(this).apply {
                text = statusText
                textSize = 10f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(statusColor))
                setPadding(dp(10), dp(4), dp(10), dp(4))
                background = surfaceBg(CLR_SURFACE_LOW, 8, statusColor, 1)
            }
            topRow.addView(badge)
            card.addView(topRow)

            if (actionText != null && onAction != null) {
                val actBtn = makeSecondaryButton(actionText, CLR_INDIGO) {
                    onAction()
                }
                actBtn.layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { topMargin = dp(4) }
                card.addView(actBtn)
            }

            contentContainer.addView(card)
        }

        // Section 1: Android Permission Controls
        contentContainer.addView(sectionHeading("ANDROID PERMISSION CONTROLS"))

        // Camera
        val hasCamera = checkSelfPermission(android.Manifest.permission.CAMERA) == android.content.pm.PackageManager.PERMISSION_GRANTED
        addPermCard(
            "📷 Camera Permission",
            "Proof captures & morning wake-up verification",
            if (hasCamera) "Granted / Enabled" else "Not granted",
            if (hasCamera) CLR_GREEN else CLR_RED,
            if (!hasCamera) "Open Settings" else null
        ) {
            startActivity(Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
                data = android.net.Uri.fromParts("package", packageName, null)
            })
        }

        // Microphone
        val hasMic = checkSelfPermission(android.Manifest.permission.RECORD_AUDIO) == android.content.pm.PackageManager.PERMISSION_GRANTED
        addPermCard(
            "🎙 Microphone Permission",
            "Audio proof recording & ambient audio verification",
            if (hasMic) "Granted / Enabled" else "Not granted",
            if (hasMic) CLR_GREEN else CLR_RED,
            if (!hasMic) "Open Settings" else null
        ) {
            startActivity(Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
                data = android.net.Uri.fromParts("package", packageName, null)
            })
        }

        // Notifications
        val notifMgr = getSystemService(Context.NOTIFICATION_SERVICE) as? android.app.NotificationManager
        val hasNotifs = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.N) {
            notifMgr?.areNotificationsEnabled() == true
        } else true
        addPermCard(
            "🔔 Notification Access",
            "Discipline alerts & hourly checkpoints delivery",
            if (hasNotifs) "Granted / Enabled" else "Not granted",
            if (hasNotifs) CLR_GREEN else CLR_RED,
            if (!hasNotifs) "Open Notification Settings" else null
        ) {
            val intent = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
                Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).apply {
                    putExtra(Settings.EXTRA_APP_PACKAGE, packageName)
                }
            } else {
                Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
                    data = android.net.Uri.fromParts("package", packageName, null)
                }
            }
            startActivity(intent)
        }

        val fullScreenAllowed = android.os.Build.VERSION.SDK_INT < 34 || notifMgr?.canUseFullScreenIntent() == true
        addPermCard(
            "🔔 Lock-screen bot reminders",
            "Scheduled alarm popups can wake the display. Your screen lock stays enabled.",
            if (fullScreenAllowed) "Full-screen alerts available" else "Notification fallback · access required",
            if (fullScreenAllowed) CLR_GREEN else CLR_AMBER,
            if (!fullScreenAllowed) "Allow full-screen alerts" else null
        ) {
            if (android.os.Build.VERSION.SDK_INT >= 34) {
                runCatching { startActivity(Intent(Settings.ACTION_MANAGE_APP_USE_FULL_SCREEN_INTENT).apply {
                    data = android.net.Uri.fromParts("package", packageName, null)
                }) }.onFailure { Toast.makeText(this, "Open Android app settings → Full-screen notifications", Toast.LENGTH_LONG).show() }
            }
        }

        // Bluetooth
        val btAdapter = android.bluetooth.BluetoothAdapter.getDefaultAdapter()
        val hasBt = (btAdapter != null && btAdapter.isEnabled) && (
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S)
                checkSelfPermission(android.Manifest.permission.BLUETOOTH_CONNECT) == android.content.pm.PackageManager.PERMISSION_GRANTED
            else
                checkSelfPermission(android.Manifest.permission.BLUETOOTH) == android.content.pm.PackageManager.PERMISSION_GRANTED
        )
        addPermCard(
            "🎧 Bluetooth / Audio Permissions",
            "Wake-up earbuds verification & peripheral tracking",
            if (hasBt) "Granted / Enabled" else if (btAdapter == null) "Unsupported" else "Permission required",
            if (hasBt) CLR_GREEN else if (btAdapter == null) "#64748B" else CLR_AMBER,
            if (!hasBt && btAdapter != null) "Open Bluetooth Settings" else null
        ) {
            startActivity(Intent(Settings.ACTION_BLUETOOTH_SETTINGS))
        }

        // Optional Usage Access is distinct from explicit target-monitoring consent.
        val hasUsage = TargetAppMonitoringPolicy.canReadUsage(this)
        addPermCard(
            "📊 Selected-App Monitoring",
            "Only installed Instagram, YouTube, Samsung Music or Spotify apps you choose",
            TargetAppMonitoringPolicy.monitoringStatus(this),
            if (hasUsage) CLR_GREEN else CLR_AMBER,
            "Choose apps / manage consent"
        ) {
            DisciplinePermissionManager.showTargetAppMonitoringSettings(this)
        }

        // QR Scanner & Pairing
        val hasNet = HardwareDeviceVerifier.isNetworkOrWifiAvailable(this)
        val qrPairingReady = hasCamera && hasNet
        addPermCard(
            "📱 QR Scanner & Device Pairing",
            "Local Wi-Fi discovery & desktop QR handshake",
            if (qrPairingReady) "Granted / Enabled" else "Permission required",
            if (qrPairingReady) CLR_GREEN else CLR_AMBER,
            "Open Device Center"
        ) {
            showDeviceCenterDialog()
        }

        // Section 2: Windows Host PC Controls
        contentContainer.addView(sectionHeading("WINDOWS HOST CONTROLS"))

        val pairInfo = db.getDevicePairingStatus()
        val isPcPaired = pairInfo.optString("trust_status", "") in setOf("TRUSTED", "PAIRED", "REGISTERED") || db.isDeviceRegistered()
        val pcName = pairInfo.optString("device_name", "Windows Host PC")

        addPermCard(
            "🖥 Startup / Background Operation",
            "$pcName • Registry Run Key autostart configured",
            if (isPcPaired) "Granted / Enabled" else "Permission required",
            if (isPcPaired) CLR_GREEN else CLR_AMBER,
            if (!isPcPaired) "Pair Windows PC" else null
        ) {
            showDeviceCenterDialog()
        }

        addPermCard(
            "🔔 Notification Delivery",
            "$pcName • Windows Action Center toast delivery active",
            if (isPcPaired) "Granted / Enabled" else "Permission required",
            if (isPcPaired) CLR_GREEN else CLR_AMBER
        )

        addPermCard(
            "🌐 Browser Restriction Integration",
            "$pcName • Edge & Chrome focus enforcement policies",
            if (isPcPaired) "Granted / Enabled" else "Permission required",
            if (isPcPaired) CLR_GREEN else CLR_AMBER
        )

        addPermCard(
            "🛡 Application Restriction Capabilities",
            "$pcName • Win32 process termination & job enforcement",
            if (isPcPaired) "Granted / Enabled" else "Permission required",
            if (isPcPaired) CLR_GREEN else CLR_AMBER
        )

        addPermCard(
            "🔄 Device Synchronization",
            "$pcName • HTTP StrictMesh active on port 8765",
            if (isPcPaired) "Granted / Enabled" else "Not granted",
            if (isPcPaired) CLR_GREEN else CLR_RED,
            "Force Sync"
        ) {
            triggerServerSync()
        }

        addPermCard(
            "🔑 Available OS Permissions",
            "$pcName • Windows standard user token verified",
            if (isPcPaired) "Granted / Enabled" else "Not granted",
            if (isPcPaired) CLR_GREEN else CLR_RED
        )
    }

    private fun renderAdminProofsTab(pendingProofs: List<org.json.JSONObject>) {
        if (pendingProofs.isEmpty()) {
            contentContainer.addView(buildEmptyState("✓", "No Pending Proofs", "All submitted verification evidence has been reviewed."))
            return
        }

        pendingProofs.forEach { pr ->
            val eid = pr.optString("evidence_id")
            val taskCode = pr.optString("task_code")
            val taskTitle = pr.optString("task_title")
            val priority = pr.optString("priority", "NORMAL")
            val submittedAt = pr.optString("submitted_at")
            val category = pr.optString("category").ifBlank { "Unavailable" }

            val card = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(16), dp(14), dp(16), dp(14))
                background = surfaceBg(CLR_SURFACE, 20, if (priority == "HIGH") CLR_AMBER else CLR_TEXT_DIM, 1)
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(12) }
            }

            // Top row: Title + Category + Priority
            val r1 = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(6) }
            }
            val titleView = TextView(this).apply {
                text = taskTitle
                textSize = 14f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            }
            val catBadge = TextView(this).apply {
                text = "CATEGORY: $category"
                textSize = 9.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(if (category == "Unavailable") CLR_TEXT_DIM else CLR_CYAN))
                setPadding(dp(8), dp(3), dp(8), dp(3))
                background = surfaceBg(CLR_SURFACE_LOW, 8, if (category == "Unavailable") CLR_BORDER else CLR_CYAN, 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { rightMargin = dp(6) }
            }
            val priBadge = TextView(this).apply {
                text = priority
                textSize = 9f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(if (priority == "HIGH") CLR_AMBER else CLR_BLUE))
                setPadding(dp(8), dp(3), dp(8), dp(3))
                background = surfaceBg(CLR_SURFACE_LOW, 8, if (priority == "HIGH") CLR_AMBER else CLR_BLUE, 1)
            }
            r1.addView(titleView)
            r1.addView(catBadge)
            r1.addView(priBadge)
            card.addView(r1)

            // Info row
            card.addView(TextView(this).apply {
                text = "Category: $category  •  ID: $eid  •  Task: $taskCode  •  Submitted: $submittedAt"
                textSize = 10.5f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(12) }
            })

            var targetPts = pr.optInt("points", 0)
            if (targetPts <= 0) {
                targetPts = when {
                    taskCode.contains("GYM", ignoreCase = true) -> 15
                    taskCode.contains("TRAVEL", ignoreCase = true) -> 10
                    taskCode.contains("BATH", ignoreCase = true) -> 5
                    taskCode.contains("WAKE", ignoreCase = true) -> 15
                    else -> 8
                }
            }

            // Actions row: Approve (+targetPts) vs Reject
            val actRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.END
            }

            val rejectBtn = makeSecondaryButton("❌ REJECT", CLR_RED) {
                showProofRejectionDialog(eid)
            }
            rejectBtn.layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { rightMargin = dp(10) }
            actRow.addView(rejectBtn)

            val approveBtn = makePrimaryButton("✅ APPROVE (+$targetPts)", CLR_GREEN) {
                if (db.approveProof(eid, "admin", targetPts)) {
                    haptic(1)
                    showFloatingPoints(targetPts)
                    triggerBotMessage("Proof approved (+$targetPts points).", "SUCCESS")
                    Toast.makeText(this@MainActivity, "Proof approved (+$targetPts pts) ✓", Toast.LENGTH_SHORT).show()
                    triggerServerSync()
                    refreshUi()
                }
            }
            actRow.addView(approveBtn)

            card.addView(actRow)
            contentContainer.addView(card)
        }
    }

    private fun showProofRejectionDialog(evidenceId: String) {
        val reasons = arrayOf(
            "Unclear or blurry evidence",
            "Incomplete task requirements",
            "Timestamp mismatch / captured late",
            "Fabricated or non-compliant evidence",
            "Other reason"
        )
        var selectedIdx = 0

        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(16), dp(20), dp(12))
            background = surfaceBg(CLR_MODAL, 20, CLR_RED, 1)
        }

        dialogView.addView(TextView(this).apply {
            text = "REJECT EVIDENCE PROOF"
            textSize = 15f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_RED))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(6) }
        })

        dialogView.addView(TextView(this).apply {
            text = "Select a structured rejection category and optional explanation:"
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
        })

        val noteInput = EditText(this).apply {
            hint = "Optional rejection note for user..."
            textSize = 12f
            setTextColor(Color.WHITE)
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            background = surfaceBg(CLR_SURFACE_LOW, 12, CLR_TEXT_DIM, 1)
            setPadding(dp(12), dp(10), dp(12), dp(10))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { topMargin = dp(12); bottomMargin = dp(16) }
        }

        val alert = AlertDialog.Builder(this)
            .setTitle("Reject Proof: $evidenceId")
            .setSingleChoiceItems(reasons, selectedIdx) { _, which ->
                selectedIdx = which
            }
            .setView(noteInput)
            .setNegativeButton("CANCEL", null)
            .setPositiveButton("REJECT") { _, _ ->
                val reasonCat = reasons[selectedIdx]
                val note = noteInput.text.toString().trim()
                if (db.rejectProof(evidenceId, "admin", reasonCat, note)) {
                    haptic(3)
                    triggerBotMessage("Proof rejected.", "WARNING")
                    Toast.makeText(this, "Proof rejected ($reasonCat) ❌", Toast.LENGTH_SHORT).show()
                    triggerServerSync()
                    refreshUi()
                }
            }
            .create()

        alert.show()
    }

    private fun renderAdminScoringTab(date: String, currentScore: Int) {
        // 0. Hero Score Header Card
        val heroCard = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(18), dp(16), dp(18), dp(16))
            background = surfaceBg(CLR_SURFACE, 20, CLR_BLUE, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(14) }
        }
        val heroCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        heroCol.addView(TextView(this).apply {
            text = "AUTHORITATIVE SCORING ENGINE"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            letterSpacing = 0.04f
        })
        heroCol.addView(TextView(this).apply {
            text = "Today • $date  •  ${if (isDevMode) "DEV MODE" else "STRICT PROD"}"
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            setPadding(0, dp(2), 0, 0)
        })
        heroCard.addView(heroCol)

        val scorePill = TextView(this).apply {
            text = "⚡ $currentScore / 100"
            textSize = 15f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(scoreColor(currentScore)))
            background = surfaceBg(CLR_SURFACE_LOW, 12, scoreColor(currentScore), 1)
            setPadding(dp(14), dp(8), dp(14), dp(8))
        }
        heroCard.addView(scorePill)
        contentContainer.addView(heroCard)

        // 1. Controlled Score Adjustment Card
        val adjCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(18), dp(18), dp(18), dp(18))
            background = surfaceBg(CLR_SURFACE, 20, CLR_BLUE, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        }

        adjCard.addView(TextView(this).apply {
            text = "CONTROLLED SCORE ADJUSTMENT"
            textSize = 15f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(4) }
        })

        adjCard.addView(TextView(this).apply {
            text = "Direct score overwrites are forbidden. Adjustments generate an audited ScoreEvent in the immutable ledger."
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        })

        // Quick adjustment chip buttons
        val chipRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
        }

        val deltaInput = EditText(this).apply {
            setText("5")
            inputType = android.text.InputType.TYPE_CLASS_NUMBER or android.text.InputType.TYPE_NUMBER_FLAG_SIGNED
            textSize = 16f
            setTypeface(typeface, Typeface.BOLD)
            gravity = Gravity.CENTER
            setTextColor(Color.WHITE)
            background = surfaceBg(CLR_SURFACE_LOW, 12, CLR_BLUE, 1)
            setPadding(dp(12), dp(10), dp(12), dp(10))
            layoutParams = LinearLayout.LayoutParams(dp(70), ViewGroup.LayoutParams.WRAP_CONTENT)
        }

        listOf(5, 10, -5, -10).forEach { d ->
            val chip = TextView(this).apply {
                text = "${if (d > 0) "+$d" else "$d"} pts"
                textSize = 11f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
                setPadding(dp(12), dp(8), dp(12), dp(8))
                background = surfaceBg(if (d > 0) CLR_GREEN else CLR_RED, 12)
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { rightMargin = dp(8) }
                applySpringTouch {
                    deltaInput.setText(d.toString())
                }
            }
            chipRow.addView(chip)
        }
        chipRow.addView(deltaInput)
        adjCard.addView(chipRow)

        // Mandatory Reason Input
        adjCard.addView(TextView(this).apply {
            text = "MANDATORY REASON / RATIONALE"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_AMBER))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(4) }
        })

        val reasonInput = EditText(this).apply {
            hint = "E.g. Exceptional deep work milestone verified..."
            textSize = 12f
            setTextColor(Color.WHITE)
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            background = surfaceBg(CLR_SURFACE_LOW, 12, CLR_TEXT_DIM, 1)
            setPadding(dp(12), dp(10), dp(12), dp(10))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        }
        adjCard.addView(reasonInput)

        // Submit Button with progress / double-click protection
        var isApplyingAdjustment = false
        var applyBtn: LinearLayout? = null
        applyBtn = makePrimaryButton("APPLY SCORE ADJUSTMENT", CLR_BLUE, widthMatchParent = true) { btn ->
            if (isApplyingAdjustment) return@makePrimaryButton
            if (!isAdminMode) {
                haptic(3)
                Toast.makeText(this, "Administrator session required.", Toast.LENGTH_SHORT).show()
                return@makePrimaryButton
            }
            val deltaStr = deltaInput.text.toString().trim()
            val reason = reasonInput.text.toString().trim()
            val delta = deltaStr.toIntOrNull() ?: 0

            if (delta == 0) {
                haptic(3)
                Toast.makeText(this, "Adjustment delta cannot be 0.", Toast.LENGTH_SHORT).show()
                return@makePrimaryButton
            }
            if (reason.isBlank()) {
                haptic(3)
                Toast.makeText(this, "Reason is mandatory for score adjustment!", Toast.LENGTH_LONG).show()
                return@makePrimaryButton
            }

            isApplyingAdjustment = true
            btn.isEnabled = false
            (btn.getChildAt(0) as? TextView)?.text = "APPLYING ADJUSTMENT..."
            btn.alpha = 0.6f

            liveStateWorker.execute {
                try {
                    val newScore = db.adjustScoreControlled(date, isDevMode, delta, reason, "admin")
                    uiHandler.post {
                        isApplyingAdjustment = false
                        btn.isEnabled = true
                        (btn.getChildAt(0) as? TextView)?.text = "APPLY SCORE ADJUSTMENT"
                        btn.alpha = 1f
                        haptic(1)
                        showFloatingPoints(delta)
                        triggerBotMessage("Score adjusted by $delta points (Current: $newScore).", "SUCCESS")
                        Toast.makeText(this@MainActivity, "Adjustment applied: ${if (delta >= 0) "+$delta" else "$delta"} pts ✓", Toast.LENGTH_SHORT).show()
                        reasonInput.setText("")
                        refreshUi()
                    }
                } catch (e: Exception) {
                    uiHandler.post {
                        isApplyingAdjustment = false
                        btn.isEnabled = true
                        (btn.getChildAt(0) as? TextView)?.text = "APPLY SCORE ADJUSTMENT"
                        btn.alpha = 1f
                        haptic(3)
                        Toast.makeText(this@MainActivity, "Adjustment failed: ${e.message}", Toast.LENGTH_LONG).show()
                    }
                }
            }
        }
        applyBtn.let { adjCard.addView(it) }
        contentContainer.addView(adjCard)

        // 2. Pending Deduction Proposals Card (with async loading & safe item handling)
        val propCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(18), dp(18), dp(18), dp(18))
            background = surfaceBg(CLR_SURFACE, 20, CLR_AMBER, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        }

        propCard.addView(TextView(this).apply {
            text = "PENDING DEDUCTION PROPOSALS"
            textSize = 15f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(4) }
        })

        propCard.addView(TextView(this).apply {
            text = "Secondary clients (Windows EXE) cannot deduct points independently. Suspected violations require explicit human authorization."
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(14) }
        })

        val propItemsContainer = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            )
        }
        val propLoadingView = ProgressBar(this, null, android.R.attr.progressBarStyleSmall).apply {
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { gravity = Gravity.CENTER_HORIZONTAL; topMargin = dp(8); bottomMargin = dp(8) }
        }
        propItemsContainer.addView(propLoadingView)
        propCard.addView(propItemsContainer)
        contentContainer.addView(propCard)

        // 3. Extension Disablement Enforcement Rule Card
        val ruleCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(18), dp(18), dp(18), dp(18))
            background = surfaceBg(CLR_SURFACE, 20, CLR_BORDER, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        }

        val ruleHeaderRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(6)
            }
        }

        ruleHeaderRow.addView(TextView(this).apply {
            text = "EXTENSION ENFORCEMENT RULE"
            textSize = 15f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        })

        var isRuleEnabled = db.getConfigValue("chrome_extension_penalty_enabled", "1") == "1"
        val ruleToggle = androidx.appcompat.widget.SwitchCompat(this).apply {
            isChecked = isRuleEnabled
            setOnCheckedChangeListener { _, isChecked ->
                isRuleEnabled = isChecked
                liveStateWorker.execute {
                    db.setConfigValue("chrome_extension_penalty_enabled", if (isChecked) "1" else "0")
                }
                haptic(1)
                Toast.makeText(this@MainActivity, "Extension rule ${if (isChecked) "ENABLED" else "DISABLED"}", Toast.LENGTH_SHORT).show()
            }
        }
        ruleHeaderRow.addView(ruleToggle)
        ruleCard.addView(ruleHeaderRow)

        ruleCard.addView(TextView(this).apply {
            text = "Desktop Chrome extension interruption monitoring and penalty proposals. Windows detects interruptions; Android confirms all deductions."
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
        })

        // Grace Period Selection Row
        ruleCard.addView(TextView(this).apply {
            text = "CONFIGURED GRACE PERIOD"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_AMBER))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(6) }
        })

        val graceOptions = listOf(5, 7, 10)
        var selectedGrace = db.getConfigValue("chrome_extension_grace_minutes", "5").toIntOrNull() ?: 5
        if (selectedGrace !in graceOptions) selectedGrace = 5

        val graceRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(14)
            }
        }

        val graceChips = mutableListOf<TextView>()
        val updateGraceChips = {
            for ((idx, mins) in graceOptions.withIndex()) {
                val chip = graceChips[idx]
                val isSel = (mins == selectedGrace)
                chip.background = surfaceBg(if (isSel) CLR_BLUE else CLR_SURFACE_LOW, 10, if (isSel) CLR_BLUE else CLR_BORDER, 1)
                chip.setTextColor(if (isSel) Color.WHITE else Color.parseColor(CLR_TEXT_SECONDARY))
            }
        }

        for (mins in graceOptions) {
            val chip = TextView(this).apply {
                text = "$mins min${if (mins == 5) " (Default)" else ""}"
                textSize = 11.5f
                setTypeface(typeface, Typeface.BOLD)
                setPadding(dp(12), dp(8), dp(12), dp(8))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                    rightMargin = if (mins != 10) dp(6) else 0
                }
                gravity = Gravity.CENTER
                setOnClickListener {
                    selectedGrace = mins
                    liveStateWorker.execute {
                        db.setConfigValue("chrome_extension_grace_minutes", mins.toString())
                    }
                    haptic(1)
                    updateGraceChips()
                    Toast.makeText(this@MainActivity, "Grace period set to $mins min", Toast.LENGTH_SHORT).show()
                }
            }
            graceChips.add(chip)
            graceRow.addView(chip)
        }
        updateGraceChips()
        ruleCard.addView(graceRow)

        // Rule Details / Metadata
        val metaContainer = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(12), dp(10), dp(12), dp(10))
            background = surfaceBg(CLR_SURFACE_LOW, 10)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }

        listOf(
            "Rule Version" to "extension-disabled-v1",
            "Penalty Rate" to "-1 point / complete minute after grace",
            "Human Confirmation" to "Always require Android confirmation",
            "Authority" to "Android Authoritative Ledger"
        ).forEach { (label, value) ->
            val row = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(3)
                }
            }
            row.addView(TextView(this).apply {
                text = label
                textSize = 10.5f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            })
            row.addView(TextView(this).apply {
                text = value
                textSize = 10.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.WHITE)
            })
            metaContainer.addView(row)
        }
        ruleCard.addView(metaContainer)
        contentContainer.addView(ruleCard)

        // 4. Today's Scoring Activity / Ledger History Card
        val actCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(18), dp(18), dp(18), dp(18))
            background = surfaceBg(CLR_SURFACE, 20, CLR_TEXT_DIM, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        }
        actCard.addView(TextView(this).apply {
            text = "TODAY'S SCORING HISTORY"
            textSize = 15f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(4) }
        })
        actCard.addView(TextView(this).apply {
            text = "Audited score events committed to the daily authoritative ledger."
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(12) }
        })
        val actItemsContainer = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            )
        }
        val actLoadingView = ProgressBar(this, null, android.R.attr.progressBarStyleSmall).apply {
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { gravity = Gravity.CENTER_HORIZONTAL; topMargin = dp(8); bottomMargin = dp(8) }
        }
        actItemsContainer.addView(actLoadingView)
        actCard.addView(actItemsContainer)
        contentContainer.addView(actCard)

        // 5. Asynchronous Loader for Proposals and Scoring History
        val inFlightProposals = mutableSetOf<String>()
        fun loadScoringDataAsync() {
            propItemsContainer.removeAllViews()
            propItemsContainer.addView(propLoadingView)
            actItemsContainer.removeAllViews()
            actItemsContainer.addView(actLoadingView)

            liveStateWorker.execute {
                val proposals = runCatching { db.getDeductionProposals(status = "AWAITING_CONFIRMATION", limit = 50) }.getOrDefault(JSONArray())
                val events = runCatching { db.getScoreEvents(date, isDevMode) }.getOrDefault(JSONArray())

                uiHandler.post {
                    if (isDestroyed || !screenResumed) return@post
                    propItemsContainer.removeAllViews()
                    actItemsContainer.removeAllViews()

                    // Render Proposals
                    if (proposals.length() == 0) {
                        propItemsContainer.addView(TextView(this@MainActivity).apply {
                            text = "✓ No pending deduction proposals. All secondary clients are clean."
                            textSize = 12f
                            setTextColor(Color.parseColor(CLR_GREEN))
                            setPadding(0, dp(6), 0, dp(6))
                        })
                    } else {
                        for (i in 0 until proposals.length()) {
                            val prop = proposals.optJSONObject(i) ?: continue
                            val pid = prop.optString("proposal_id", "")
                            if (pid.isBlank()) continue
                            val pts = prop.optInt("proposed_points", -10)
                            val reason = prop.optString("reason", "Violation detected")
                            val origin = prop.optString("originating_device", "SECONDARY_CLIENT")
                            val evType = prop.optString("event_type", "VIOLATION")
                            val pTime = prop.optString("timestamp", "")

                            val item = LinearLayout(this@MainActivity).apply {
                                orientation = LinearLayout.VERTICAL
                                setPadding(dp(14), dp(12), dp(14), dp(12))
                                background = surfaceBg(CLR_SURFACE_LOW, 14, CLR_BORDER, 1)
                                layoutParams = LinearLayout.LayoutParams(
                                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                                ).apply { bottomMargin = dp(10) }
                            }

                            val rowHeader = LinearLayout(this@MainActivity).apply {
                                orientation = LinearLayout.HORIZONTAL
                                gravity = Gravity.CENTER_VERTICAL
                                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
                            }

                            val evJson = prop.optString("evidence_json", "")
                            val evidence = prop.optJSONObject("evidence") ?: if (evJson.isNotBlank()) runCatching { JSONObject(evJson) }.getOrNull() else null
                            val isExtEvent = evType == "BROWSER_EXTENSION_DISABLED"
                            val headerTitle = if (isExtEvent) "CHROME EXTENSION DISABLED" else evType
                            val headerColor = if (isExtEvent) CLR_RED else CLR_AMBER

                            rowHeader.addView(TextView(this@MainActivity).apply {
                                text = "$headerTitle  ($pts pts proposed)"
                                textSize = 12.5f
                                setTypeface(typeface, Typeface.BOLD)
                                setTextColor(Color.parseColor(headerColor))
                                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                            })

                            rowHeader.addView(TextView(this@MainActivity).apply {
                                text = "AWAITING CONFIRMATION"
                                textSize = 9.5f
                                setTypeface(typeface, Typeface.BOLD)
                                setTextColor(Color.parseColor(CLR_AMBER))
                                background = surfaceBg(CLR_AMBER, 6)
                                setPadding(dp(6), dp(2), dp(6), dp(2))
                            })

                            item.addView(rowHeader)

                            val extraMeta = if (evidence != null) {
                                val ep = evidence.optString("episode_id", "")
                                val min = evidence.optInt("minute_index", 0)
                                val graceMin = evidence.optInt("grace_policy_minutes", 5)
                                "\nEpisode: $ep • Minute: $min • Grace: ${graceMin}m"
                            } else ""

                            item.addView(TextView(this@MainActivity).apply {
                                text = "$reason$extraMeta\nDevice: $origin • $pTime"
                                textSize = 11f
                                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                                setPadding(0, dp(6), 0, dp(10))
                            })

                            // Action buttons: Approve vs Reject
                            val btnRow = LinearLayout(this@MainActivity).apply {
                                orientation = LinearLayout.HORIZONTAL
                                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
                            }

                            var approveBtn: LinearLayout? = null
                            var rejectBtn: LinearLayout? = null

                            approveBtn = makePrimaryButton("AUTHORIZE DEDUCTION", CLR_RED, widthMatchParent = false) { btn ->
                                if (pid in inFlightProposals) return@makePrimaryButton
                                inFlightProposals.add(pid)
                                btn.isEnabled = false
                                rejectBtn?.isEnabled = false
                                (btn.getChildAt(0) as? TextView)?.text = "AUTHORIZING..."
                                btn.alpha = 0.6f

                                liveStateWorker.execute {
                                    val res = runCatching { db.approveDeductionProposal(pid, approver = "admin", isDevMode = isDevMode) }
                                        .getOrElse { Pair(false, "Error: ${it.message}") }
                                    uiHandler.post {
                                        inFlightProposals.remove(pid)
                                        if (res.first) {
                                            haptic(1)
                                            triggerBotMessage(res.second, "WARNING")
                                            Toast.makeText(this@MainActivity, res.second, Toast.LENGTH_SHORT).show()
                                            loadScoringDataAsync()
                                        } else {
                                            btn.isEnabled = true
                                            rejectBtn?.isEnabled = true
                                            (btn.getChildAt(0) as? TextView)?.text = "AUTHORIZE DEDUCTION"
                                            btn.alpha = 1f
                                            Toast.makeText(this@MainActivity, "Approval failed: ${res.second}", Toast.LENGTH_LONG).show()
                                        }
                                    }
                                }
                            }
                            approveBtn?.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1.2f).apply { rightMargin = dp(8) }
                            approveBtn?.let { btnRow.addView(it) }

                            rejectBtn = makeSecondaryButton("REJECT", CLR_SURFACE) {
                                if (pid in inFlightProposals) return@makeSecondaryButton
                                inFlightProposals.add(pid)
                                approveBtn?.isEnabled = false
                                rejectBtn?.isEnabled = false
                                (rejectBtn?.getChildAt(0) as? TextView)?.text = "REJECTING..."
                                rejectBtn?.alpha = 0.6f

                                liveStateWorker.execute {
                                    val res = runCatching { db.rejectDeductionProposal(pid, approver = "admin", reason = "Rejected by user") }
                                        .getOrElse { Pair(false, "Error: ${it.message}") }
                                    uiHandler.post {
                                        inFlightProposals.remove(pid)
                                        if (res.first) {
                                            haptic(1)
                                            triggerBotMessage(res.second, "SUCCESS")
                                            Toast.makeText(this@MainActivity, res.second, Toast.LENGTH_SHORT).show()
                                            loadScoringDataAsync()
                                        } else {
                                            approveBtn?.isEnabled = true
                                            rejectBtn?.isEnabled = true
                                            (rejectBtn?.getChildAt(0) as? TextView)?.text = "REJECT"
                                            rejectBtn?.alpha = 1f
                                            Toast.makeText(this@MainActivity, "Rejection failed: ${res.second}", Toast.LENGTH_LONG).show()
                                        }
                                    }
                                }
                            }
                            rejectBtn?.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                            rejectBtn?.let { btnRow.addView(it) }

                            item.addView(btnRow)
                            propItemsContainer.addView(item)
                        }
                    }

                    // Render Scoring History Events
                    if (events.length() == 0) {
                        actItemsContainer.addView(TextView(this@MainActivity).apply {
                            text = "No point activity recorded today yet."
                            textSize = 12f
                            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                            setPadding(0, dp(6), 0, dp(6))
                        })
                    } else {
                        val maxEvents = minOf(events.length(), 20)
                        // Show most recent first
                        for (i in (events.length() - 1) downTo (events.length() - maxEvents)) {
                            val ev = events.optJSONObject(i) ?: continue
                            val pts = ev.optInt("points", 0)
                            val evType = ev.optString("event_type", "EVENT")
                            val desc = ev.optString("description", "")
                            val ts = ev.optString("timestamp", "")
                            val isPos = pts >= 0

                            val evRow = LinearLayout(this@MainActivity).apply {
                                orientation = LinearLayout.HORIZONTAL
                                gravity = Gravity.CENTER_VERTICAL
                                setPadding(dp(12), dp(8), dp(12), dp(8))
                                background = surfaceBg(CLR_SURFACE_LOW, 10)
                                layoutParams = LinearLayout.LayoutParams(
                                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                                ).apply { bottomMargin = dp(6) }
                            }

                            val ptsBadge = TextView(this@MainActivity).apply {
                                text = "${if (isPos) "+" else ""}$pts"
                                textSize = 11f
                                setTypeface(typeface, Typeface.BOLD)
                                setTextColor(Color.parseColor(if (isPos) CLR_GREEN else CLR_RED))
                                background = surfaceBg(if (isPos) CLR_GREEN else CLR_RED, 6)
                                setPadding(dp(8), dp(3), dp(8), dp(3))
                                layoutParams = LinearLayout.LayoutParams(dp(54), ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                                    rightMargin = dp(10)
                                }
                                gravity = Gravity.CENTER
                            }
                            evRow.addView(ptsBadge)

                            val evDetailCol = LinearLayout(this@MainActivity).apply {
                                orientation = LinearLayout.VERTICAL
                                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                            }
                            evDetailCol.addView(TextView(this@MainActivity).apply {
                                text = "$evType  •  $ts"
                                textSize = 9.5f
                                setTextColor(Color.parseColor(CLR_TEXT_DIM))
                            })
                            evDetailCol.addView(TextView(this@MainActivity).apply {
                                text = desc
                                textSize = 11f
                                setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
                            })
                            evRow.addView(evDetailCol)
                            actItemsContainer.addView(evRow)
                        }
                    }
                }
            }
        }

        // Trigger initial async load
        loadScoringDataAsync()
    }

    private fun renderAdminDevicesTab() {
        contentContainer.addView(sectionHeading("MANAGED DEVICE PAIRING"))

        val pairInfo = db.getDevicePairingStatus()
        val trustStatus = pairInfo.optString("trust_status", "UNPAIRED")
        val devName = pairInfo.optString("device_name", "")
        if (trustStatus == "UNPAIRED" || devName.isEmpty() || devName == "No PC Paired") {
            contentContainer.addView(buildEmptyState("📱", "No Devices Connected", "Connect and pair an authorized Windows PC to begin syncing."))
            return
        }

        val dCard = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(16), dp(14), dp(16), dp(14))
            background = surfaceBg(CLR_SURFACE, 18, CLR_GREEN, 1)
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(10) }
        }
        val dCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        dCol.addView(TextView(this).apply {
            text = devName
            textSize = 13f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
        })
        dCol.addView(TextView(this).apply {
            text = "${pairInfo.optString("platform", "WINDOWS")} • $trustStatus"
            textSize = 10f
            setTextColor(Color.parseColor(CLR_GREEN))
        })
        dCard.addView(dCol)
        dCard.addView(TextView(this).apply {
            text = "✓ PAIRED"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_GREEN))
            setPadding(dp(8), dp(4), dp(8), dp(4))
            background = surfaceBg(CLR_SURFACE_LOW, 8, CLR_GREEN, 1)
        })
        contentContainer.addView(dCard)
    }

    private fun renderAdminAuditTab() {
        contentContainer.addView(sectionHeading("IMMUTABLE AUDIT TRAIL"))

        val logs = db.getAdminAuditLogs(25)
        if (logs.isEmpty()) {
            contentContainer.addView(buildEmptyState("📜", "No Audit Logs Yet", "Actions performed by administrators will appear here."))
            return
        }

        logs.forEach { log ->
            val row = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                setPadding(dp(14), dp(12), dp(14), dp(12))
                background = surfaceBg(CLR_SURFACE, 16, CLR_TEXT_DIM, 1)
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(8) }
            }

            val top = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
                ).apply { bottomMargin = dp(4) }
            }
            top.addView(TextView(this).apply {
                text = log.optString("action_type")
                textSize = 12f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_CYAN))
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            })
            top.addView(TextView(this).apply {
                text = log.optString("timestamp").takeLast(8)
                textSize = 10f
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
            })
            row.addView(top)

            row.addView(TextView(this).apply {
                text = "By ${log.optString("admin_user")} • ${log.optString("field_changed")}: ${log.optString("old_value")} -> ${log.optString("new_value")}"
                textSize = 10.5f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            })

            contentContainer.addView(row)
        }
    }

    // ════════════════════════════════════════════════════════
    // INCOMING INTENT HANDLER (test commands / notifications)
    // ════════════════════════════════════════════════════════

    private fun handleIncomingIntent(incoming: Intent?) {

        if (incoming?.getStringExtra("OPEN_MODAL") != null || incoming?.getStringExtra("TASK_TYPE") != null) {
            hasAutoPromptedOnLaunch = true
        }
        val openModal = incoming?.getStringExtra("OPEN_MODAL")?.uppercase(Locale.US)
        if (openModal == "SCHEDULE_COMPLETION") {
            isSchedulePendingRestricted = true
            currentScheduleDeadlineState = ScheduleDeadlineRules.ScheduleDeadlineState.COMPLETION_REQUIRED
            refreshUi()
            return
        }
        val taskType = incoming?.getStringExtra("TASK_TYPE")?.uppercase(Locale.US)
        val activityId = incoming?.getStringExtra("ACTIVITY_ID")?.uppercase(Locale.US) ?: ""

        incoming?.removeExtra("OPEN_MODAL")
        incoming?.removeExtra("TASK_TYPE")
        incoming?.removeExtra("ACTIVITY_ID")
        if (incoming?.action == AppUpdateManager.UPDATE_ACTION_VIEW) {
            val autoStart = incoming.getBooleanExtra("auto_start", false)
            window?.decorView?.post {
                showUpdateDialog()
                if (autoStart) {
                    val mgr = AppUpdateManager.getInstance(this)
                    val rel = mgr.latestRelease
                    if (rel != null && mgr.currentState != AppUpdateManager.UpdateState.DOWNLOADING && mgr.currentState != AppUpdateManager.UpdateState.PREPARING) {
                        mgr.startDownloadAndInstall(rel, this)
                    }
                }
            }
            return
        }

        if (openModal in setOf("CAMERA_CHECK", "CAMERA_AND_FACE_CHECK", "WAKEUP_DEMO")) {
            window?.decorView?.post {
                CameraFaceAnalysisEngine.showCameraAndFaceCheckDialog(this)
            }
            return
        }
        if (openModal in setOf("DIAGNOSTICS", "RESTRICTION_TEST")) {
            window?.decorView?.post {
                val score = db.getScore(db.nowDate(), false)
                DisciplinePermissionManager.showDiagnosticsScreen(this, score) { refreshUi() }
            }
            return
        }
        if (openModal in setOf("TEST_RESTRICTION_POPUP", "RESTRICTION_POPUP")) {
            window?.decorView?.post {
                val decision = DisciplineScoringRules.evaluateRestrictionDecision(
                    score = 65,
                    packageNameOrApp = "com.google.android.youtube",
                    appLocks = db.getRemoteAppLocks(),
                    nextTaskTitle = "Complete scheduled Wake-Up verification",
                    nextTaskWindow = "07:00–09:30"
                )
                StrictBotOverlayController.showStrictBotPopup(this, decision)
            }
            return
        }
        if (openModal in setOf("STRICTBOT", "STRICTBOT_CHAT")) {
            window?.decorView?.post {
                strictBotChat.show()
            }
            return
        }
        if (incoming?.getBooleanExtra("OPEN_WAKEUP_DIALOG", false) == true) {
            val isDemo = incoming.getBooleanExtra("IS_DEV_MODE", isDevMode)
            activeTab = "HOME"
            window?.decorView?.post {
                refreshUi()
                WakeUpVerificationController.showWakeUpVerificationDialog(this, db, isDevMode = isDemo) {
                    refreshUi()
                }
            }
            return
        }
        if (openModal == "MORNING_FLOW" || incoming?.getBooleanExtra(MorningWakeUpManager.EXTRA_START_MORNING_FLOW, false) == true) {
            val today = db.nowDate()
            val isWakeUpDone = db.isWakeUpVerificationCompleted(today, isDevMode)
            val isBathConfirmed = db.isBathScheduleConfirmed(today)
            db.markMorningInAppAutoOpened(today)
            activeTab = "HOME"
            window?.decorView?.post {
                if (!screenResumed || isFinishing || isDestroyed) return@post
                refreshUi()
                if (!isWakeUpDone) {
                    if (!isBathConfirmed) isBathPopupQueued = true
                    showWakeUpVerificationDialog()
                } else if (!isBathConfirmed) {
                    showBathScheduleConfirmationDialog(isEditing = false)
                } else {
                    showBathScheduleConfirmationDialog(isEditing = false)
                }
            }
            return
        }
        if (openModal in setOf("WAKEUP_CHALLENGE", "WAKEUP_ALARM", "WAKEUP_PREP") ||
            taskType == "WAKE_UP" ||
            activityId.contains("WAKEUP")
        ) {
            val today = db.nowDate()
            val isWakeUpDone = db.isWakeUpVerificationCompleted(today, isDevMode)
            activeTab = "HOME"
            window?.decorView?.post {
                if (!screenResumed || isFinishing || isDestroyed) return@post
                refreshUi()
                if (!isWakeUpDone) {
                    showWakeUpVerificationDialog()
                } else {
                    Toast.makeText(this, "Wake-Up verification is already completed for today.", Toast.LENGTH_SHORT).show()
                }
            }
            return
        }
        if (openModal == "HOURLY_CLOSED") {
            activeTab = "HOME"
            val attendance = incoming?.getStringExtra("ATTENDANCE_STATUS") ?: "CLOSED"
            val slot = incoming?.getStringExtra("HOUR_SLOT") ?: "Hourly checkpoint"
            window?.decorView?.post {
                if (!screenResumed || isFinishing || isDestroyed) return@post
                Toast.makeText(this, "$slot closed · $attendance. This window will not reopen.", Toast.LENGTH_LONG).show()
                refreshUi()
            }
            return
        }
        if (openModal != null && (openModal.startsWith("HOURLY") || openModal == "HOURLY_CHECK") || taskType == "HOURLY_CHECKIN") {
            activeTab = "HOME"
            window?.decorView?.post {
                if (!screenResumed || isFinishing || isDestroyed) return@post
                refreshUi()
                val targetActId = activityId
                val occurrence = if (targetActId.isNotBlank()) db.getActivityById(targetActId) else db.getActiveOrTargetHourlyActivity(db.nowDate())
                if (targetActId.isNotBlank() && occurrence == null) {
                    Toast.makeText(this, "This checkpoint is no longer available.", Toast.LENGTH_LONG).show()
                } else if (occurrence != null && occurrence.status in listOf("SUBMITTED", "VALIDATING", "VERIFIED", "COMPLETED")) {
                    Toast.makeText(this, "Hourly checkpoint already submitted (${occurrence.status}).", Toast.LENGTH_SHORT).show()
                } else {
                    showHourlySubmissionDialog(occurrence)
                }
            }
            return
        }
        if (openModal in setOf("DAILY_SUMMARY", "TODAYS_SUMMARY")) {
            activeTab = "HOME"
            window?.decorView?.post {
                refreshUi()
                showTodaysSummaryDialog()
            }
            return
        }
        if (openModal == "PC_SHUTDOWN" || taskType == "PC_SHUTDOWN") {
            activeTab = "CHALLENGES"
            window?.decorView?.post {
                refreshUi()
                showPcShutdownDialog()
            }
            return
        }

        // MainActivity is exported for launcher and notification entry points. Never
        // honor caller-supplied test commands here: they previously fabricated proof,
        // approved evidence, and marked tasks complete without user evidence.
        if (incoming?.hasExtra("TEST_CMD") == true) return

        val requestedTab = (incoming?.getStringExtra("OPEN_TAB") ?: incoming?.getStringExtra("TAB"))?.uppercase(Locale.US)
        if (requestedTab != null && requestedTab in setOf("HOME", "CHALLENGES", "TIMELINE", "REWARDS", "DEVICES", "PROFILE")) {
            activeTab = requestedTab
            refreshUi()
        }
    }

    // ── Dedicated Update Modal / Screen (Requirement 6) ─────
    private fun showUpdateDialog() {
        val mgr = AppUpdateManager.getInstance(this)
        val rel = mgr.latestRelease
        if (rel == null) {
            mgr.checkForUpdates(forceUserInitiated = true) { success, r, err ->
                if (success && r != null) {
                    showUpdateDialog()
                } else {
                    Toast.makeText(this, "No updates available at this time.", Toast.LENGTH_SHORT).show()
                }
            }
            return
        }

        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(22), dp(20), dp(22), dp(20))
            background = surfaceBg(CLR_MODAL, 24, CLR_INDIGO, 1)
        }

        // Title row with icon
        val titleRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(14) }
        }
        val iconTv = TextView(this).apply {
            text = "↻"
            textSize = 22f
            setTextColor(Color.parseColor(CLR_INDIGO))
            setTypeface(typeface, Typeface.BOLD)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { rightMargin = dp(10) }
        }
        val titleTv = TextView(this).apply {
            text = "STRICTRECORDS UPDATE"
            textSize = 17f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
        }
        titleRow.addView(iconTv)
        titleRow.addView(titleTv)
        dialogView.addView(titleRow)

        // Version Comparison card
        val installedVer = "${mgr.getInstalledVersionName()} (${mgr.getInstalledVersionCode()})"
        val newVer = "${rel.versionName} (${rel.versionCode})"
        val verCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(14), dp(12), dp(14), dp(12))
            background = surfaceBg(CLR_SURFACE, 14, CLR_TEXT_DIM, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(12) }
        }
        val verRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
        }
        val currentTv = TextView(this).apply {
            text = "Installed: v$installedVer"
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        val arrowTv = TextView(this).apply {
            text = "➔"
            textSize = 12f
            setTextColor(Color.parseColor(CLR_INDIGO))
            setPadding(dp(6), 0, dp(6), 0)
        }
        val newTv = TextView(this).apply {
            text = "Version ${rel.versionName}"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_GREEN))
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            gravity = Gravity.END
        }
        verRow.addView(currentTv)
        verRow.addView(arrowTv)
        verRow.addView(newTv)
        verCard.addView(verRow)

        // Size and Channel row
        val sizeMb = if (rel.fileSizeBytes > 0) String.format(java.util.Locale.US, "%.1f MB", rel.fileSizeBytes / (1024f * 1024f)) else "Direct APK"
        val metaRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { topMargin = dp(6) }
        }
        val sizeTv = TextView(this).apply {
            text = "Download size: $sizeMb • Channel: ${rel.channel}"
            textSize = 10f
            setTextColor(Color.parseColor(CLR_TEXT_DIM))
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        metaRow.addView(sizeTv)
        if (rel.isMandatory) {
            val mandBadge = TextView(this).apply {
                text = "MANDATORY"
                textSize = 9f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_AMBER))
            }
            metaRow.addView(mandBadge)
        }
        verCard.addView(metaRow)
        dialogView.addView(verCard)

        // Release notes heading and content
        dialogView.addView(TextView(this).apply {
            text = "WHAT'S NEW"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_DIM))
            letterSpacing = 0.08f
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        })
        val notesScroller = ScrollView(this).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(90)).apply { bottomMargin = dp(14) }
            background = surfaceBg(CLR_ELEVATED, 10)
            setPadding(dp(12), dp(10), dp(12), dp(10))
        }
        val notesTv = TextView(this).apply {
            text = if (rel.releaseNotes.isNotBlank()) rel.releaseNotes else "• Performance improvements and bug fixes.\n• Enhanced synchronization stability."
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_PRIMARY))
            setLineSpacing(dp(2).toFloat(), 1f)
        }
        notesScroller.addView(notesTv)
        dialogView.addView(notesScroller)

        // Status text and progress bar
        val statusTv = TextView(this).apply {
            text = mgr.getStatusMessage(mgr.currentState)
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { bottomMargin = dp(6) }
        }
        val progressBar = ProgressBar(this, null, android.R.attr.progressBarStyleHorizontal).apply {
            isIndeterminate = false
            max = 100
            progress = mgr.currentProgress
            visibility = if (mgr.currentState == AppUpdateManager.UpdateState.DOWNLOADING) View.VISIBLE else View.GONE
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(8)).apply { bottomMargin = dp(14) }
        }
        dialogView.addView(statusTv)
        dialogView.addView(progressBar)

        // Action Buttons Row
        val btnRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.END
        }

        var cancelBtn: View? = null
        if (!rel.isMandatory) {
            cancelBtn = makeSecondaryButton("LATER", CLR_TEXT_DIM) {
                updateDialogRef?.dismiss()
            }
            (cancelBtn as? TextView)?.apply {
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(8) }
            }
            btnRow.addView(cancelBtn)
        }

        val actionBtn = makePrimaryButton(
            if (mgr.currentState == AppUpdateManager.UpdateState.INSTALLATION_PENDING) "INSTALL NOW" else "UPDATE NOW",
            CLR_INDIGO
        ) {
            if (mgr.currentState == AppUpdateManager.UpdateState.DOWNLOADING) return@makePrimaryButton
            mgr.startDownloadAndInstall(rel, this@MainActivity)
        }

        (actionBtn as? TextView)?.apply {
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, if (rel.isMandatory) 1f else 1.5f)
        }
        btnRow.addView(actionBtn)
        dialogView.addView(btnRow)

        val dialog = AlertDialog.Builder(this)
            .setView(dialogView)
            .setCancelable(!rel.isMandatory)
            .create()
        dialog.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
        updateDialogRef = dialog

        // Attach listener to update dialog elements live
        val listener = object : AppUpdateManager.UpdateListener {
            override fun onUpdateStateChanged(state: AppUpdateManager.UpdateState, release: AppUpdateManager.ReleaseInfo?, progress: Int, errorMessage: String?) {
                runOnUiThread {
                    val actionTv = actionBtn.getChildAt(0) as? TextView
                    when (state) {
                        AppUpdateManager.UpdateState.PREPARING -> {
                            progressBar.visibility = View.VISIBLE
                            progressBar.isIndeterminate = true
                            statusTv.text = "Preparing update..."
                            actionTv?.text = "PREPARING..."
                            actionBtn.isEnabled = false
                        }
                        AppUpdateManager.UpdateState.DOWNLOADING -> {
                            progressBar.visibility = View.VISIBLE
                            progressBar.isIndeterminate = false
                            progressBar.progress = progress
                            statusTv.text = "Downloading: $progress%"
                            actionTv?.text = "DOWNLOADING ($progress%)"
                            actionBtn.isEnabled = false
                        }
                        AppUpdateManager.UpdateState.VERIFYING -> {
                            progressBar.visibility = View.VISIBLE
                            progressBar.isIndeterminate = true
                            statusTv.text = "Verifying package..."
                            actionTv?.text = "VERIFYING..."
                            actionBtn.isEnabled = false
                        }
                        AppUpdateManager.UpdateState.DOWNLOAD_VERIFIED -> {
                            progressBar.visibility = View.GONE
                            statusTv.text = "Verified ✓"
                            actionTv?.text = "VERIFIED ✓"
                            actionBtn.isEnabled = false
                        }
                        AppUpdateManager.UpdateState.INSTALLATION_PENDING -> {
                            progressBar.visibility = View.GONE
                            statusTv.text = "Ready to install"
                            actionTv?.text = "INSTALL NOW"
                            actionBtn.isEnabled = true
                        }
                        AppUpdateManager.UpdateState.FAILED -> {
                            progressBar.visibility = View.GONE
                            statusTv.text = "Update failed: ${errorMessage ?: "Unknown error"}"
                            statusTv.setTextColor(Color.parseColor(CLR_RED))
                            actionTv?.text = "RETRY"
                            actionBtn.isEnabled = true
                        }
                        AppUpdateManager.UpdateState.UP_TO_DATE -> {
                            dialog.dismiss()
                        }
                        else -> {}
                    }
                }
            }
        }
        mgr.addListener(listener)
        dialog.setOnDismissListener {
            mgr.removeListener(listener)
            if (updateDialogRef == dialog) updateDialogRef = null
        }
        dialog.show()
    }

    // ═══════════════════════════════════════════════════════════════════════
    // GPAY-STYLE TRANSACTION HISTORY & POINTS LEDGER SYSTEM
    // ═══════════════════════════════════════════════════════════════════════
    private var txFilterCategory: String = "ALL"
    private var txSearchText: String = ""
    private val CLR_TEXT = CLR_TEXT_PRIMARY
    private val CLR_TEXT_MUTED = CLR_TEXT_DIM

    private fun promptAdminPinDialog(reason: String, onSuccess: () -> Unit) {
        val padH = dp(if (isWideLayout()) 22 else 16)
        val padV = dp(if (isWideLayout()) 18 else 14)
        val dialogView = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(padH, padV, padH, padV)
            background = surfaceBg(CLR_MODAL, 20, CLR_INDIGO, 1)
        }

        dialogView.addView(TextView(this).apply {
            text = "🛡 ADMINISTRATOR AUTHENTICATION"
            textSize = 14f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.WHITE)
            letterSpacing = 0.05f
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(6) }
        })

        dialogView.addView(TextView(this).apply {
            text = reason
            textSize = 11f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(16) }
        })

        val pinInput = EditText(this).apply {
            hint = "••••"
            textSize = 24f
            setTypeface(typeface, Typeface.BOLD)
            gravity = Gravity.CENTER
            setTextColor(Color.WHITE)
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            inputType = android.text.InputType.TYPE_CLASS_NUMBER or android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD
            background = surfaceBg(CLR_SURFACE_LOW, 14, CLR_INDIGO, 1)
            setPadding(dp(16), dp(12), dp(16), dp(12))
            filters = arrayOf(android.text.InputFilter.LengthFilter(6))
            layoutParams = LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT
            ).apply { bottomMargin = dp(20) }
        }
        dialogView.addView(pinInput)

        val scrollWrap = ScrollView(this).apply {
            isVerticalScrollBarEnabled = false
            overScrollMode = View.OVER_SCROLL_IF_CONTENT_SCROLLS
            addView(dialogView)
        }

        val alert = AlertDialog.Builder(this)
            .setView(scrollWrap)
            .setCancelable(true)
            .create()

        val btnRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.END
        }

        val cancelBtn = makeSecondaryButton("CANCEL", CLR_TEXT_DIM) {
            alert.dismiss()
        }
        btnRow.addView(cancelBtn)

        val submitBtn = makePrimaryButton("CONFIRM", CLR_INDIGO) {
            val pin = pinInput.text.toString().trim()
            val lockoutLeft = db.getPinLockoutRemainingSeconds()
            if (lockoutLeft > 0) {
                haptic(3)
                Toast.makeText(this, "Rate limited. Locked out for ${lockoutLeft}s", Toast.LENGTH_LONG).show()
                return@makePrimaryButton
            }
            if (db.verifyAdminPin(pin)) {
                alert.dismiss()
                onSuccess()
            } else {
                haptic(3)
                pinInput.setText("")
                val nowLockout = db.getPinLockoutRemainingSeconds()
                if (nowLockout > 0) {
                    Toast.makeText(this, "5 failed attempts. Locked out for ${nowLockout}s", Toast.LENGTH_LONG).show()
                } else {
                    Toast.makeText(this, "Invalid PIN. Access denied ❌", Toast.LENGTH_SHORT).show()
                }
            }
        }
        btnRow.addView(submitBtn)
        spaceDialogButtons(btnRow, cancelBtn, submitBtn)
        dialogView.addView(btnRow)

        alert.show()
        pinInput.requestFocus()
    }

    private fun renderTransactionsTab(st: JSONObject, score: Int) {
        val date = db.nowDate()
        val isTablet = isWideLayout()

        // 1. Top Navigation Bar / Header
        val headerCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(16), dp(16), dp(16), dp(16))
            background = gradientBg("#0F172A", "#090D16", 20, strokeHex = "#1E293B")
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(14)
            }
        }

        val topRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(8)
            }
        }

        val backBtn = TextView(this).apply {
            text = "← BACK"
            textSize = 12f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            setPadding(dp(10), dp(6), dp(10), dp(6))
            background = surfaceBg(CLR_ELEVATED, 12, CLR_CYAN, 1)
            setOnClickListener {
                activeTab = "HOME"
                refreshUi()
            }
        }
        topRow.addView(backBtn)

        val titleCol = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                leftMargin = dp(12)
            }
        }
        titleCol.addView(TextView(this).apply {
            text = "POINTS HISTORY"
            textSize = if (isTablet) 18f else 16f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT))
            letterSpacing = 0.05f
        })
        titleCol.addView(TextView(this).apply {
            text = "Authoritative GPay-style transaction ledger & score verification"
            textSize = 10f
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
        })
        topRow.addView(titleCol)

        val resetBtn = TextView(this).apply {
            text = "RESET TO 0"
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_AMBER))
            setPadding(dp(8), dp(6), dp(8), dp(6))
            background = surfaceBg(CLR_ELEVATED, 12, CLR_AMBER, 1)
            setOnClickListener {
                promptAdminPinDialog("Enter Administrator PIN to execute idempotent points reset to 0") {
                    val res = db.executeInitialResetIfNeeded(date, isDevMode)
                    val already = res.optBoolean("already_applied", false)
                    val msg = if (!already) "Authoritative points reset to 0 completed ✓" else "Initial reset already applied previously."
                    Toast.makeText(this@MainActivity, msg, Toast.LENGTH_SHORT).show()
                    refreshUi()
                }
            }
        }
        topRow.addView(resetBtn)
        headerCard.addView(topRow)
        contentContainer.addView(headerCard)

        // Fetch data
        val historyData = db.getUnifiedTransactionHistory(
            targetDate = date,
            categoryFilter = if (txFilterCategory == "ALL" || txFilterCategory == "GAINS" || txFilterCategory == "LOSSES" || txFilterCategory == "PROPOSED") null else txFilterCategory,
            searchQuery = txSearchText.ifBlank { null },
            isDevMode = isDevMode
        )

        val confirmedScore = historyData.optInt("current_confirmed_balance", score)
        val allTx = historyData.optJSONArray("transactions") ?: JSONArray()
        var totalGained = 0
        var totalLost = 0
        val filteredTxList = mutableListOf<JSONObject>()

        for (i in 0 until allTx.length()) {
            val tx = allTx.getJSONObject(i)
            val amt = tx.optInt("amount", 0)
            val stStr = tx.optString("status")
            val confirmed = tx.optBoolean("confirmed", false)
            val reset = tx.optString("category") in listOf("Initial Reset", "Daily Reset")
            if (confirmed && !reset) {
                if (amt > 0) totalGained += amt
                else if (amt < 0 && stStr != "Proposed — Not Deducted") totalLost += kotlin.math.abs(amt)
            }

            var include = true
            if (txFilterCategory == "GAINS" && (amt <= 0 || !confirmed || reset)) include = false
            if (txFilterCategory == "LOSSES" && (amt >= 0 || !confirmed || reset)) include = false
            if (txFilterCategory == "PROPOSED" && stStr != "Proposed — Not Deducted") include = false

            if (include) filteredTxList.add(tx)
        }

        // 2. Hero Balance Card (GPay style)
        val heroCard = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(20), dp(20), dp(20), dp(20))
            background = gradientBg("#0F2231", "#08131C", 24, strokeHex = CLR_CYAN)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(14)
            }
        }

        val balHeaderRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        balHeaderRow.addView(TextView(this).apply {
            text = "AUTHORITATIVE CONFIRMED BALANCE"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            letterSpacing = 0.08f
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        })
        balHeaderRow.addView(TextView(this).apply {
            text = "✓ VERIFIED"
            textSize = 9.5f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_GREEN))
            setPadding(dp(8), dp(3), dp(8), dp(3))
            background = surfaceBg("#064E3B", 12, CLR_GREEN, 1)
        })
        heroCard.addView(balHeaderRow)

        val scoreRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.BOTTOM
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                topMargin = dp(6)
                bottomMargin = dp(4)
            }
        }
        scoreRow.addView(TextView(this).apply {
            text = confirmedScore.toString()
            textSize = if (isTablet) 42f else 36f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(scoreColor(confirmedScore)))
        })
        scoreRow.addView(TextView(this).apply {
            text = " POINTS"
            textSize = 13f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                leftMargin = dp(6)
                bottomMargin = dp(6)
            }
        })
        heroCard.addView(scoreRow)

        val unverifiedCount = (0 until allTx.length()).count {
            allTx.getJSONObject(it).optString("status") == "Proposed — Not Deducted"
        }
        heroCard.addView(TextView(this).apply {
            text = "Android ledger confirmed • $unverifiedCount pending deduction${if (unverifiedCount == 1) "" else "s"} • ${historyData.optString("sync_status")}"
            textSize = 10.5f
            setTextColor(Color.parseColor(CLR_TEXT_MUTED))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(14)
            }
        })

        // 3 Metric Summary Boxes
        val metricsRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        fun createMetricBox(label: String, value: String, colorHex: String): LinearLayout {
            return LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                gravity = Gravity.CENTER
                setPadding(dp(8), dp(10), dp(8), dp(10))
                background = surfaceBg(CLR_SURFACE, 14, "#1E293B", 1)
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply {
                    setMargins(dp(3), 0, dp(3), 0)
                }
                addView(TextView(this@MainActivity).apply {
                    text = label
                    textSize = 9f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(CLR_TEXT_MUTED))
                })
                addView(TextView(this@MainActivity).apply {
                    text = value
                    textSize = 13f
                    setTypeface(typeface, Typeface.BOLD)
                    setTextColor(Color.parseColor(colorHex))
                    layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                        topMargin = dp(2)
                    }
                })
            }
        }
        metricsRow.addView(createMetricBox("Gained (+)", "+$totalGained pts", CLR_GREEN))
        metricsRow.addView(createMetricBox("Lost (−)", "-$totalLost pts", CLR_RED))
        metricsRow.addView(createMetricBox("Entries", "${filteredTxList.size}", CLR_CYAN))
        heroCard.addView(metricsRow)
        contentContainer.addView(heroCard)

        // 3. Search Bar
        val searchCard = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(12), dp(6), dp(12), dp(6))
            background = surfaceBg(CLR_SURFACE, 14, "#334155", 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(10)
            }
        }
        searchCard.addView(TextView(this).apply {
            text = "🔍"
            textSize = 14f
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                rightMargin = dp(8)
            }
        })
        val searchEdit = EditText(this).apply {
            hint = "Search reason, task, or ID..."
            setHintTextColor(Color.parseColor(CLR_TEXT_DIM))
            setTextColor(Color.parseColor(CLR_TEXT))
            textSize = 12f
            background = null
            setText(txSearchText)
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            addTextChangedListener(object : TextWatcher {
                override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) {}
                override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) {
                    txSearchText = s?.toString() ?: ""
                }
                override fun afterTextChanged(s: Editable?) {}
            })
            setOnEditorActionListener { _, actionId, _ ->
                if (actionId == EditorInfo.IME_ACTION_SEARCH || actionId == EditorInfo.IME_ACTION_DONE) {
                    refreshUi()
                    true
                } else false
            }
        }
        searchCard.addView(searchEdit)
        val goBtn = TextView(this).apply {
            text = "FILTER"
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            setPadding(dp(8), dp(4), dp(8), dp(4))
            setOnClickListener { refreshUi() }
        }
        searchCard.addView(goBtn)
        contentContainer.addView(searchCard)

        // 4. Horizontal Filter Chips ScrollView
        val chipsScroll = HorizontalScrollView(this).apply {
            isHorizontalScrollBarEnabled = false
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(14)
            }
        }
        val chipsRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
        }
        val chipOptions = listOf("ALL", "GAINS", "LOSSES", "PROPOSED", "Wake-up", "Hourly", "Gym", "Restriction", "Initial Reset")
        for (chip in chipOptions) {
            val isActive = txFilterCategory.equals(chip, ignoreCase = true)
            val chipView = TextView(this).apply {
                text = when (chip) {
                    "ALL" -> "All"
                    "GAINS" -> "Gains (+)"
                    "LOSSES" -> "Losses (−)"
                    "PROPOSED" -> "Proposed"
                    else -> chip
                }
                textSize = 11f
                setTypeface(typeface, if (isActive) Typeface.BOLD else Typeface.NORMAL)
                setTextColor(Color.parseColor(if (isActive) "#090D16" else CLR_TEXT_SECONDARY))
                setPadding(dp(12), dp(6), dp(12), dp(6))
                background = if (isActive) {
                    surfaceBg(CLR_CYAN, 16)
                } else {
                    surfaceBg(CLR_SURFACE, 16, "#334155", 1)
                }
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    rightMargin = dp(6)
                }
                setOnClickListener {
                    txFilterCategory = chip
                    refreshUi()
                }
            }
            chipsRow.addView(chipView)
        }
        chipsScroll.addView(chipsRow)
        contentContainer.addView(chipsScroll)

        // 5. Transactions List
        if (filteredTxList.isEmpty()) {
            contentContainer.addView(buildEmptyState("🧾", "No Transactions Found", "No points events match the selected filters or search query."))
            return
        }

        for (tx in filteredTxList) {
            val title = tx.optString("title", "Points Event")
            val reason = tx.optString("reason", "No reason recorded")
            val amt = tx.optInt("amount", 0)
            val amtStr = tx.optString("amount_formatted", "$amt pts")
            val status = tx.optString("status", "Approved")
            val ts = tx.optString("timestamp_formatted", tx.optString("timestamp", "Recent"))
            val cat = tx.optString("category", "General")
            val origin = tx.optString("origin", "Android APK")

            val txCard = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                setPadding(dp(14), dp(12), dp(14), dp(12))
                background = surfaceBg(CLR_SURFACE, 16, "#1E293B", 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(8)
                }
                applySpringTouch {
                    showTransactionDetailDialog(tx)
                }
            }

            // Category Icon
            val iconTxt = when {
                cat.contains("wake", ignoreCase = true) -> "⏰"
                cat.contains("hourly", ignoreCase = true) -> "⏱️"
                cat.contains("gym", ignoreCase = true) -> "🏋️"
                cat.contains("bath", ignoreCase = true) -> "🚿"
                cat.contains("sleep", ignoreCase = true) -> "🌙"
                cat.contains("restriction", ignoreCase = true) -> "⚠️"
                cat.contains("reset", ignoreCase = true) -> "⚖️"
                cat.contains("reversal", ignoreCase = true) -> "↩️"
                else -> "🪙"
            }
            val iconView = TextView(this).apply {
                text = iconTxt
                textSize = 18f
                gravity = Gravity.CENTER
                setPadding(dp(8), dp(8), dp(8), dp(8))
                background = surfaceBg(CLR_ELEVATED, 14)
                layoutParams = LinearLayout.LayoutParams(dp(40), dp(40)).apply {
                    rightMargin = dp(12)
                }
            }
            txCard.addView(iconView)

            // Middle Info
            val midCol = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
            }
            midCol.addView(TextView(this).apply {
                text = title
                textSize = 12.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT))
            })
            midCol.addView(TextView(this).apply {
                text = cleanUserFacingText(reason)
                textSize = 10.5f
                setTextColor(Color.parseColor(CLR_TEXT_SECONDARY))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(2)
                    bottomMargin = dp(4)
                }
            })
            val metaRow = TextView(this).apply {
                text = "📅 $ts  •  🏷️ $cat  •  📱 $origin"
                textSize = 9f
                setTextColor(Color.parseColor(CLR_TEXT_DIM))
            }
            midCol.addView(metaRow)
            txCard.addView(midCol)

            // Right Amount & Status
            val rightCol = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                gravity = Gravity.END
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    leftMargin = dp(8)
                }
            }
            val amtColor = when {
                status == "Proposed — Not Deducted" -> CLR_AMBER
                amtStr.contains("Balance set") -> CLR_CYAN
                amt > 0 -> CLR_GREEN
                amt < 0 -> CLR_RED
                else -> CLR_TEXT_MUTED
            }
            rightCol.addView(TextView(this).apply {
                text = amtStr
                textSize = 13.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(amtColor))
            })
            val (statusColor, statusBg) = when (status) {
                "Proposed — Not Deducted" -> Pair(CLR_AMBER, "#451A03")
                "Rejected" -> Pair(CLR_TEXT_MUTED, "#1E293B")
                "Reversed" -> Pair("#C084FC", "#3B0764")
                "Completed" -> Pair(CLR_CYAN, "#083344")
                else -> Pair(CLR_GREEN, "#064E3B")
            }
            rightCol.addView(TextView(this).apply {
                text = if (status == "Proposed — Not Deducted") "PENDING" else status.uppercase()
                textSize = 8.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(statusColor))
                setPadding(dp(6), dp(2), dp(6), dp(2))
                background = surfaceBg(statusBg, 8, statusColor, 1)
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(4)
                }
            })
            txCard.addView(rightCol)

            contentContainer.addView(txCard)
        }
    }

    private fun showTransactionDetailDialog(tx: JSONObject) {
        val title = tx.optString("title", "Transaction Details")
        val reason = tx.optString("reason", "Legacy transaction — reason unavailable")
        val amtStr = tx.optString("amount_formatted", "${tx.optInt("amount")} pts")
        val status = tx.optString("status", "Approved")
        val ts = tx.optString("timestamp_formatted", tx.optString("timestamp", "—"))
        val date = tx.optString("date", "—")
        val cat = tx.optString("category", "General")
        val origin = tx.optString("origin", "Android APK")
        val rule = tx.optString("rule_applied", "Scoring Protocol Standard Rule")
        val refId = tx.optString("reference_id", tx.optString("transaction_id", "—"))
        val isProp = status == "Proposed — Not Deducted"

        val panel = FrameLayout(this).apply {
            background = surfaceBg(CLR_MODAL, 28, CLR_BLUE, 1)
            elevation = dp(24).toFloat()
            layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT, Gravity.BOTTOM)
            translationY = dp(700).toFloat()
        }
        val scroll = ScrollView(this).apply {
            isVerticalScrollBarEnabled = false
            overScrollMode = View.OVER_SCROLL_NEVER
        }
        val inner = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(22), dp(24), dp(22), dp(40))
        }

        // Handle pill
        inner.addView(View(this).apply {
            background = surfaceBg(CLR_TEXT_DIM, 4)
            layoutParams = LinearLayout.LayoutParams(dp(40), dp(4)).apply {
                gravity = Gravity.CENTER_HORIZONTAL
                bottomMargin = dp(16)
            }
        })

        // Top category badge & title
        inner.addView(TextView(this).apply {
            text = cat.uppercase()
            textSize = 10f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_CYAN))
            letterSpacing = 0.08f
            setPadding(dp(8), dp(3), dp(8), dp(3))
            background = surfaceBg("#0E2A38", 8, CLR_CYAN, 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(6)
            }
        })
        inner.addView(TextView(this).apply {
            text = title
            textSize = 18f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(12)
            }
        })

        // Amount card
        val amtCard = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(16), dp(12), dp(16), dp(12))
            background = surfaceBg(CLR_SURFACE, 14, "#1E293B", 1)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                bottomMargin = dp(16)
            }
        }
        val amtLeft = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        amtLeft.addView(TextView(this).apply {
            text = "TRANSACTION IMPACT"
            textSize = 9f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(CLR_TEXT_MUTED))
        })
        amtLeft.addView(TextView(this).apply {
            text = amtStr
            textSize = 22f
            setTypeface(typeface, Typeface.BOLD)
            val amtCol = when {
                isProp -> CLR_AMBER
                amtStr.contains("Balance set") -> CLR_CYAN
                tx.optInt("amount") > 0 -> CLR_GREEN
                tx.optInt("amount") < 0 -> CLR_RED
                else -> CLR_TEXT_MUTED
            }
            setTextColor(Color.parseColor(amtCol))
        })
        amtCard.addView(amtLeft)
        amtCard.addView(TextView(this).apply {
            text = status
            textSize = 11f
            setTypeface(typeface, Typeface.BOLD)
            setTextColor(Color.parseColor(if (isProp) CLR_AMBER else CLR_GREEN))
            setPadding(dp(10), dp(4), dp(10), dp(4))
            background = surfaceBg(if (isProp) "#451A03" else "#064E3B", 10, if (isProp) CLR_AMBER else CLR_GREEN, 1)
        })
        inner.addView(amtCard)

        // Metadata grid
        fun addField(label: String, value: String, isMono: Boolean = false) {
            val fieldLayout = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    bottomMargin = dp(12)
                }
            }
            fieldLayout.addView(TextView(this).apply {
                text = label.uppercase()
                textSize = 9.5f
                setTypeface(typeface, Typeface.BOLD)
                setTextColor(Color.parseColor(CLR_TEXT_MUTED))
                letterSpacing = 0.05f
            })
            fieldLayout.addView(TextView(this).apply {
                text = value
                textSize = 12f
                if (isMono) typeface = Typeface.MONOSPACE
                setTextColor(Color.parseColor(CLR_TEXT))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(2)
                }
            })
            inner.addView(fieldLayout)
        }

        addField("Reason / Explanation", reason)
        addField("Established Scoring Rule", rule)
        addField("Event Date & Time", "$date at $ts")
        addField("Origin Device", origin)
        addField("Reference ID", refId, isMono = true)

        val humanConf = tx.optJSONObject("human_confirmation")
        if (humanConf != null) {
            val req = humanConf.optBoolean("required", false)
            val obtained = humanConf.optBoolean("obtained", false)
            val by = humanConf.optString("authorized_by", "")
            val confTxt = if (req) {
                if (obtained) "Confirmed by $by ✓" else "Awaiting Explicit Human Confirmation ⏳"
            } else {
                "Automated Rule Execution (No confirmation required)"
            }
            addField("Human Confirmation Status", confTxt)
        }

        // Proposal action buttons
        if (isProp) {
            val actRow = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
                    topMargin = dp(8)
                    bottomMargin = dp(8)
                }
            }
            val authBtn = makePrimaryButton("AUTHORIZE DEDUCTION", CLR_GREEN) {
                promptAdminPinDialog("Enter Administrator PIN to authorize deduction") {
                    val (ok, resMsg) = db.approveDeductionProposal(refId, approver = "Primary Administrator", isDevMode = isDevMode)
                    if (ok) {
                        Toast.makeText(this@MainActivity, "Deduction proposal authorized ✓", Toast.LENGTH_SHORT).show()
                        panel.animate().translationY(dp(700).toFloat()).setDuration(DUR_MED).withEndAction { rootFrame.removeView(panel) }.start()
                        refreshUi()
                    } else {
                        Toast.makeText(this@MainActivity, "Authorization failed: $resMsg", Toast.LENGTH_SHORT).show()
                    }
                }
            }
            authBtn.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(6) }
            actRow.addView(authBtn)

            val rejBtn = makePrimaryButton("REJECT PROPOSAL", CLR_RED) {
                promptAdminPinDialog("Enter Administrator PIN to reject proposal") {
                    val (ok, resMsg) = db.rejectDeductionProposal(refId, approver = "Primary Administrator", reason = "Rejected by administrator")
                    if (ok) {
                        Toast.makeText(this@MainActivity, "Proposal rejected (0 points deducted) ✓", Toast.LENGTH_SHORT).show()
                        panel.animate().translationY(dp(700).toFloat()).setDuration(DUR_MED).withEndAction { rootFrame.removeView(panel) }.start()
                        refreshUi()
                    } else {
                        Toast.makeText(this@MainActivity, "Rejection failed: $resMsg", Toast.LENGTH_SHORT).show()
                    }
                }
            }
            rejBtn.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(6) }
            actRow.addView(rejBtn)

            inner.addView(actRow)
        }

        // Close button
        val closeBtn = makePrimaryButton("CLOSE", CLR_BLUE, widthMatchParent = true) {
            panel.animate().translationY(dp(700).toFloat()).setDuration(DUR_MED).withEndAction { rootFrame.removeView(panel) }.start()
        }
        closeBtn.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply {
            topMargin = dp(12)
        }
        inner.addView(closeBtn)

        scroll.addView(inner)
        panel.addView(scroll)
        rootFrame.addView(panel)
        panel.animate().translationY(0f).setDuration(DUR_SLOW).setInterpolator(DecelerateInterpolator(1.8f)).start()
        panel.setOnClickListener {
            panel.animate().translationY(dp(700).toFloat()).setDuration(DUR_MED).withEndAction { rootFrame.removeView(panel) }.start()
        }
    }

    // ════════════════════════════════════════════════════════
    // Local records and device pairing do not require a cloud account.
    // ════════════════════════════════════════════════════════





}
